-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[26606]="我是父亲最优秀的儿子！你们的末日来临了！"
D.Strings[26607]="来呀！出招吧！"
D.Strings[26608]="接招吧，让你看看我的厉害！"
D.Strings[26609]="啊啊啊啊啊！见识见识钢与铁的愤怒吧！"
D.Strings[26610]="让我结束你的诅咒吧。"
D.Strings[26611]="血肉……是……脆弱的！"
D.Strings[26612]="怎么可能……？血肉之躯竟强过了……钢铁！"
D.Strings[26613]="就是你们杀死了我那么的多孩子吗？你们……要付出代价！"
D.Strings[26614]="腐化而成的血肉生物……死吧。"
D.Strings[26615]="一切都不会被浪费的。看着吧……"
D.Strings[26616]="我要把你们踩在脚下，彻底碾碎！"
D.Strings[26617]="我的工作……还没结束！"
D.Strings[26618]="钢铁的大军将征服一切！"
D.Strings[26619]="呸！可怜虫！"
D.Strings[26620]="你们的确让我费了不少力气！"
D.Strings[26621]="主人……果然……深谋远虑。"
D.Strings[26622]="你和你的伙伴们都准备好了吗？我会激活水晶，发射能量波，让我的守卫趁机撤退。"
D.Strings[26623]="如果你们都准备好了，那么我就开始组织撤退，让你们接手这里的防务。我会采取激进的防御措施，让守卫们安全离开监狱并关上大门。此后，你们要不惜一切代价守住大门！"
D.Strings[26624]="让他们放心撤离吧，我们会竭尽全力牵制蓝龙军团的入侵。"
D.Strings[26625]="连天灾军团都被我们击败了，你们以为自己能有几分胜算？"
D.Strings[26626]="来应付更“大”的挑战吧！"
D.Strings[26627]="大地要将你们吞噬！"
D.Strings[26628]="看我踩碎你们这些蟑螂！"
D.Strings[26629]="谁能阻止我？就凭你？"
D.Strings[26630]="怎么，这就不行了？"
D.Strings[26631]="神都会死去……何况我们自身……"
D.Strings[26632]="年轻人，别害怕，死亡的阴霾不会降临到这位北伐军勇士的头上。"
D.Strings[26633]="活着的时候，布雷登布莱德拥有显赫的战绩。死后他的灵魂将升入天堂。"
D.Strings[26634]="圣光不会抛弃它的勇士。"
D.Strings[26635]="我为银色北伐军所做的一切只是为了履行义务。当然，也算是报恩吧。大领主让我摆脱了巫妖王的控制并为我们指明了救赎之路。我说过，我们做事的方式是有差异的——你必须明白这一点。我和黑锋骑士团会竭尽全力，帮助银色北伐军在冰冠冰川站稳脚跟。在那之后，我们就会离开。我希望能以这样的方式报答大领主的恩情。$B$B等待我们的，将是截然不同的命运。"
D.Strings[26636]="毫无疑问，和这些北伐军将士相处起来别提有多别扭了。但是不承担痛苦的话，算什么牺牲呢？你曾经与我共同经历了圣光之愿礼拜堂一战，目睹过许多伟大的牺牲。我们是来这里报答大领主的，报答他所做出的牺牲。$B$B一旦银色北伐军在冰冠冰川的高墙内站稳脚跟，我们就会离开。等待我们的，将是截然不同的命运。"
D.Strings[26637]="位于风暴峭壁的80级地下城闪电大厅已开放测试。请在进入地下城之前组满队伍。该地下城的集合石尚未开放。\n\n您只要通过从地下城的常规出口，就能离开闪电大厅，返回这里。如果您的角色死亡并选择了释放，您可从该NPC处传送回去。"
D.Strings[26638]="我已经组好队伍，准备进入闪电大厅了！"
D.Strings[26639]="我要返回闪电大厅！"
D.Strings[26640]="第1篇"
D.Strings[26641]="先做个自我介绍吧。我名叫大法师瓦格斯，是首批进驻德拉诺的肯瑞托远征队的队长。我们和联盟的军队一起跨越了黑暗之门，如今，我们在法兰伦建立起了一座名叫肯瑞瓦村的营地，就在嘲颅兽人氏族的家乡附近。真是个美好的地方！"
D.Strings[26642]="<这本布满灰尘的日记缺了好几篇>"
D.Strings[26643]="尊贵的主人。"
D.Strings[26644]="这……是哪里？我……我要……消灭你们！"
D.Strings[26645]="第42篇"
D.Strings[26646]="能量线的挖掘工作仍在继续，成果喜人。我们惊讶地发现，艾泽拉斯和德拉诺的能量线在结构上存在相似之处，会不会是因为两者有着相似的起源呢？\n我的挚友纳比留斯报告说，嘲颅氏族已经与联盟达成了休战协议。我向来是不信任兽人的，这消息真不知道是喜是忧啊。"
D.Strings[26647]="第205篇"
D.Strings[26648]="联盟的军队大多已经启程前往艾泽拉斯。希望图拉扬将军能将我们仔细撰写的报告安全地送回达拉然。\n耐奥祖不计后果地开启了传送门，强大的能量撕碎了法兰伦。在扭曲虚空的侵蚀下，这片青翠的山岭迅速沦为了废墟。我必须想办法回去！"
D.Strings[26649]="你去死吧！这是主人的命令。"
D.Strings[26650]="真是简单的工作！"
D.Strings[26651]="什么样的狗杂种竟然胆敢入侵这里？快点，弟兄们！谁要是能把他们的头提来，就赏他吃肉！"
D.Strings[26652]="你想要挑战死亡本身吗？来吧，“王”。面对莫格莱尼的怒火！"
D.Strings[26653]="我会在回音谷等你。朋友，坚持住。"
D.Strings[26654]="我命令维库人去杀掉他们，结果却只能依靠这条没用的龙！以伊米隆的名义，干掉他们！"
D.Strings[26655]="要是再让我的飞龙被鱼叉碰到一下，我就亲自跳下来剥了你们的皮！"
D.Strings[26656]="你这只无能的蠢龙！你的尸体干脆给我的新飞龙拿去当点心算了！"
D.Strings[26657]="你现在怎么不那么嚣张了啊？"
D.Strings[26658]="我要让你尝尝我的厉害！"
D.Strings[26659]="啊啊！这也能叫……攻击？我要……让你们……见识见识……啊啊啊……"
D.Strings[26660]="你们不仅侵入我的家园，还有胆来挑战我？我要把你们的徽记拿来作为礼物献祭给伟大的死神！Rualg nja gaborr！"
D.Strings[26661]="黑色风暴之王布约恩！应我的召唤前来协助我！"
D.Strings[26662]="岩石峭壁之王赫尔多！把你的力量借给我！"
D.Strings[26663]="恐怖深渊之王拉努夫！以漆黑的深夜吞噬这群蝼蚁！"
D.Strings[26664]="野蛮杀戮之王托尔，将你的威能赐予我！"
D.Strings[26665]="你的死亡仅仅是个开始！"
D.Strings[26666]="你让你的人民失望了！"
D.Strings[26667]="这就是我能加冕为王的理由！"
D.Strings[26668]="又……又有什么……在等着我呢？"
D.Strings[26669]="监狱守卫们，准备撤退了！这些冒险者将接管这里的防御事务！迅速撤离！"
D.Strings[26670]="我要锁上大门了。祝你们好运，感谢你们的帮助。"
D.Strings[26671]="尤顿海姆传来消息，据说那里的沉睡卫士发现了一位重要人物。"
D.Strings[26672]="教徒激动得语无伦次。"
D.Strings[26673]="模样？他就是个维库人。呃，其实我并没有见过他本人。自从暗影拱顶……"
D.Strings[26674]="名字？对，他的名字！我记得是叫伊斯卡德尔。"
D.Strings[26675]="遵命，主人。"
D.Strings[26676]="汇报情况吧。"
D.Strings[26677]="描述一下这名维库人吧。他长什么模样？"
D.Strings[26678]="我没兴趣听你找借口。他们总该告诉过你他的名字吧。"
D.Strings[26679]="伊斯卡德尔？！蠢货！你没听过他的名头吗？他是有史以来最伟大的维库人战士！"
D.Strings[26680]="立即返回尤顿海姆，告诉他们，在我抵达之前不准让他苏醒过来。我要亲眼看看这个维库人。"
D.Strings[26681]="现身吧，熔尸！"
D.Strings[26682]="这里没我们的事了。我走了。"
D.Strings[26683]="连这样的场面都应付不了，你还真够弱的。好吧……"
D.Strings[26684]="在我离开之前，你还需要什么帮助吗？好吧，我不认为……"
D.Strings[26685]="远古的魔法在眼睛深处旋转，令你感到一阵眩晕，仿佛自己被吸入了虹膜之中并永远地陷落了。"
D.Strings[26686]="紧握巫妖王之眼并集中你的意志，以此获取重要的信息。"
D.Strings[26687]="你观察着貌似平静的冰冠冰川，突然发现了有趣的景象……"
D.Strings[26688]="%s进入了星界位面！"
D.Strings[26689]="开始对创世神殿进行分析。"
D.Strings[26690]="创世神殿完好无损。"
D.Strings[26691]="机械仆人之间似乎发生了内讧。部分机械侏儒随从被随意地堆放在一起。"
D.Strings[26692]="某种未知的力量摧毁了剩余的机械侏儒守卫。"
D.Strings[26693]="未发现守护者米米尔。分析完毕。"
D.Strings[26694]="维库人安详地沉睡着。"
D.Strings[26695]="开始对寒冬神殿进行分析。"
D.Strings[26696]="叫醒休眠的尤尔丁人，确认他是不是远古英雄伊斯卡德尔。"
D.Strings[26697]="寒冬神殿完好无损。"
D.Strings[26698]="神殿守卫者已经死亡。弥漫神殿的硫磺气味表明他是被某种火焰生物杀死的。"
D.Strings[26699]="神殿之前设定的寒冷气候模式已终止。"
D.Strings[26700]="未发现守护者霍迪尔。分析完毕。"
D.Strings[26701]="未发现守护者弗蕾亚。分析完毕。"
D.Strings[26702]="生命神殿遭到破坏，无法修复。"
D.Strings[26703]="种种迹象表明神殿曾发生过激战。估计守护者弗蕾亚的对手在体型和力量上都与她不相上下。"
D.Strings[26704]="未发现神殿守护者。与神殿伴生的植物形态已经死亡。"
D.Strings[26705]="开始对生命神殿进行分析。"
D.Strings[26706]="开始对秩序神殿进行分析。"
D.Strings[26707]="秩序神殿完好无损。"
D.Strings[26708]="未发现战斗迹象。未发现神殿守护者。"
D.Strings[26709]="未发现守护者提尔。分析完毕。"
D.Strings[26710]="<嗝儿>$b$b没有同伴，真是孤单呐。"
D.Strings[26711]="对了！你去给他们点颜色瞧瞧！$b$b<嗝儿>"
D.Strings[26712]="该喝点双份朗姆酒啦！$b$b哎呀，我的酒快喝光了……"
D.Strings[26713]="传送门已经稳定！发动进攻！"
D.Strings[26714]="你为什么要保卫肯瑞托……"
D.Strings[26715]="你休想破坏传送门！"
D.Strings[26716]="你的死亡毫无意义！"
D.Strings[26717]="伊斯卡德尔，你总算露面了。怎么？你已经开始战斗了吗？"
D.Strings[26718]="很好。杀死这些低级生物吧，我们好谈正事。"
D.Strings[26719]="天哪！这怎么可能？"
D.Strings[26720]="我不明白怎么会这样，但是你一定是伊斯卡德尔。等等……怎么回事？"
D.Strings[26721]="怎么回事？你被我控制了！我是来复仇的！"
D.Strings[26722]="滚远点！别碰我！"
D.Strings[26723]="哈哈哈哈！好啦。回到我待的洞穴去吧。我们还有很多要事要商量呢。"
D.Strings[26724]="为织法者而战！"
D.Strings[26725]="你们无法阻止魔枢之战！"
D.Strings[26726]="你们是在白费力气！"
D.Strings[26727]="北伐军的神圣军旗被摧毁了！\n天灾军团获胜！"
D.Strings[26728]="北伐军的神圣军旗已经插好了。\n保护旗帜，击退攻击者！"
D.Strings[26729]="来战，$n！杀死伊斯卡德尔！"
D.Strings[26730]="卡塔莉娜·斯坦弗就在监狱西南方的运河边。"
D.Strings[26731]="耶利尼克的理发店就在贸易区的北部。"
D.Strings[26732]="主人的意志必将实现！！"
D.Strings[26733]="你来了！我刚刚找出开启这扇门的方法。你准备好之后就告诉我，我来打开它！"
D.Strings[26734]="来吧，布莱恩！打开它！"
D.Strings[26735]="艾莉丝·布莱里特就在飞行管理员旁边的大锻炉附近。"
D.Strings[26736]="理发店就在平民区的西部。"
D.Strings[26737]="啧啧。你犯下了如此可怕的错误，是不是感觉很自豪啊？"
D.Strings[26738]="我本来就打算销毁他，看来可以提前完成了。"
D.Strings[26739]="芬迪·达金就在工匠区中央的第二层。"
D.Strings[26740]="哎呀，这些质量上等，可以重复利用的零件都要报废啦……真是可惜……"
D.Strings[26741]="补丁再也不想被随意地切开或是缝合了！"
D.Strings[26742]="嘿！别担心！老布莱恩在后面给你们加油呢！把这些该死的金属疙瘩给我挡住，让我来好好跟这台可爱的大机器谈谈，让它帮帮你们！"
D.Strings[26743]="补丁要向萨布诺克博士复仇！"
D.Strings[26744]="水晶大厅的索斯能教你铭文技能。"
D.Strings[26745]="犹尔曼就在暗巷区二层的某座建筑物内。"
D.Strings[26746]="理发师？她已经把理发店搬出暗影裂口，挪到力量谷上方的悬崖中去了。就是原来开水果店的那个地方。"
D.Strings[26747]="天啊！该死的怪物！看看它们对我们的人民做了些什么！"
D.Strings[26748]="烧死它们。烧毁这一切。"
D.Strings[26749]="来吧。让它们为此付出代价！"
D.Strings[26750]="玛尔迦·帕克雷就在炼金房，她是一位漂亮的女士。"
D.Strings[26751]="理发师纳兹尼克在贸易区的上层，紧邻银行。"
D.Strings[26752]="波什金·哈比德尔在灵魂高地下的预见之池。"
D.Strings[26753]="赞塔希娅在逐日王庭。"
D.Strings[26754]="仆从们，把他们都消灭！"
D.Strings[26755]="毁灭。"
D.Strings[26756]="成功啦！我们从天灾军团手中夺得了北伐军之峰！立刻向古斯塔夫神父汇报这一好消息！我们要立即展开建设工事！快！"
D.Strings[26757]="了解……我的……痛苦。"
D.Strings[26758]="凝视……虚空。"
D.Strings[26759]="更多的……能量。"
D.Strings[26760]="放弃吧。"
D.Strings[26761]="坠入……黑暗。"
D.Strings[26762]="消散。"
D.Strings[26763]="轻盈追迹者遭到攻击，变得虚弱了。"
D.Strings[26764]="面对如此大规模的危机，我要如何应对？"
D.Strings[26765]="所有人都病倒了——这是天灾！"
D.Strings[26766]="药物根本不起作用——整座城市在痛苦中呻吟。"
D.Strings[26767]="关于变质粮食的传闻在士兵之间流传，恐慌正在蔓延。市民们互相指责邻居就是投毒者。城市已经陷入骚乱。"
D.Strings[26768]="越来越多的劳工卧床不起，城市系统正在趋于瘫痪……"
D.Strings[26769]="我完全不知所措。面对这样的灾难，我又能做些什么呢？"
D.Strings[26770]="我发誓，我的不适感源于焦虑……"
D.Strings[26771]="由于唤醒的方式不当，维库人死亡了。"
D.Strings[26772]="由于唤醒仪式受到了干扰，维库人死亡了。"
D.Strings[26773]="由于唤醒魔棒的使用不当，沉睡中的维库人死亡了。"
D.Strings[26774]="沉睡中的维库人摔倒在地。"
D.Strings[26775]="占领北伐军之峰只是第一步，我们的事业漫长而危险。要攻陷冰冠冰川，要做的事情还有很多。$B$B只有在像你这样的勇士的帮助下，我们才有可能取得胜利。"
D.Strings[26776]="欢迎来到达拉然，$c。"
D.Strings[26777]="我准备好飞往索拉查盆地了。"
D.Strings[26778]="他就快到了！"
D.Strings[26779]="我弄丢了博学者的罩衫。"
D.Strings[26780]="你胆敢挑战我？你还不够资格呢！"
D.Strings[26781]="不，大领主巴拉加德。你必须接受挑战！"
D.Strings[26782]="瓦尔德玛达？！巫妖王亲自派你来的？"
D.Strings[26783]="好吧。我会解决掉这些生物。不过是小小的麻烦罢了。准备受死吧！"
D.Strings[26784]="萨菲德拉，让他们感受到来自冰冠冰川的寒意吧！"
D.Strings[26785]="立即返回玛雷卡里斯！"
D.Strings[26786]="我把探索者战袍弄丢了。"
D.Strings[26787]="立即返回布伦希尔达村！"
D.Strings[26788]="立即返回蓝天伐木场！"
D.Strings[26789]="立即返回风险湾！"
D.Strings[26790]="我把蛮力战袍弄丢了。"
D.Strings[26791]="给我的？"
D.Strings[26792]="礼物？"
D.Strings[26793]="干嘛给我炸弹？"
D.Strings[26794]="是要我送到什么地方去吗？"
D.Strings[26795]="恐怕不太安全吧，小恶鬼。"
D.Strings[26796]="这个不应该放在这儿。"
D.Strings[26797]="小恶鬼想要什么啊？"
D.Strings[26798]="那样可不太好！"
D.Strings[26799]="我真受不了这些骷髅。"
D.Strings[26800]="我是个伟大的战士，别来惹我，骷髅。"
D.Strings[26801]="我不是苦力……我的耐心是有限的。"
D.Strings[26802]="我的时间都浪费在对付你们这些肮脏的家伙身上了。"
D.Strings[26803]="看着我，骷髅。我要把你的头从脆弱的骨架上拧下来！"
D.Strings[26804]="给我滚远点，你这没脑子的傀儡。"
D.Strings[26805]="破天号将开往冰冠冰川。世界上找不到比它更好的飞船啦。"
D.Strings[26806]="请送我上船。"
D.Strings[26807]="奥格瑞姆之锤即将开往冰冠冰川。你找不到比它更好的船只啦。"
D.Strings[26808]="住手！快跪下！蠢货，这可是巫妖王！"
D.Strings[26809]="愿荣耀与你同在。"
D.Strings[26810]="瓦尔德玛达。我还以为你失踪了呢。伊斯卡德尔呢？"
D.Strings[26811]="奈丝伍德夫人，我能看穿你的伪装。你以为这点小把戏就能愚弄我吗？！"
D.Strings[26812]="但是……！"
D.Strings[26813]="你可以继续战斗了，领主。"
D.Strings[26814]="陛下，但是……？"
D.Strings[26815]="但是什么！杀了他们！别让我失望，BALARGARDE！"
D.Strings[26816]="<大领主达里安·莫格莱尼点了点头。>"
D.Strings[26817]="我要接受训练，大领主。"
D.Strings[26818]="死亡骑士也来玩了？"
D.Strings[26819]="为什么要伤害帕奇维克？"
D.Strings[26820]="巫妖王说帕奇维克是从纳克萨玛斯“暂借”来的。这让帕奇维克很生气！"
D.Strings[26821]="帕奇维克跟你玩！帕奇维克很孤单！"
D.Strings[26822]="帕奇维克想念纳克萨玛斯。杀死你们，帕奇维克或许就能早点回家啦。"
D.Strings[26823]="你还活着只是因为我比较好奇。"
D.Strings[26824]="必须攻陷达拉然！"
D.Strings[26825]="消灭所有和我们作对的家伙！"
D.Strings[26826]="必须阻止肯瑞托！"
D.Strings[26827]="必须抑制……魔法……"
D.Strings[26828]="达拉然将会陷入火海！"
D.Strings[26829]="我的职责就是保护传送门，哪怕付出生命的代价！"
D.Strings[26830]="你们的防御力量就会被歼灭！"
D.Strings[26831]="你们无法摧毁所有的传送门！"
D.Strings[26832]="就算我死了，这次入侵行动也不会停止！"
D.Strings[26833]="你们的努力是徒劳的！"
D.Strings[26834]="进入达拉然的传送门开启了！"
D.Strings[26835]="达拉然注定要毁灭！"
D.Strings[26836]="你获得了2500点荣誉以及50点竞技场点数。"
D.Strings[26837]="让我们看看入口附近的大门后面藏着什么。我会悄悄地潜过去。去那里和我碰面吧，我会带你们进去吧。"
D.Strings[26838]="血红色的液体在眼睛里漩流，显现出天灾军团大军的影像。它似乎在拉扯着你，企图侵入你的思想。你本能地抗拒着眼睛的影响，觉得心神不宁。"
D.Strings[26839]="凶手！"
D.Strings[26840]="恶心的家伙。"
D.Strings[26841]="这简直是引狼入室的行为。"
D.Strings[26842]="天灾军团杀死了我的家人！怪物！"
D.Strings[26843]="你竟敢踏进我们的城市！"
D.Strings[26844]="%s害怕得发抖。"
D.Strings[26845]="%s向$n扔烂苹果。"
D.Strings[26846]="%s向$n扔烂香蕉。"
D.Strings[26847]="%s对$n吐口水。"
D.Strings[26848]="你有什么需要，尽快开口吧。"
D.Strings[26849]="暴风城的市民！联盟的公民！你们的国王有话要说！"
D.Strings[26850]="今天，是天灾军团首次战败的日子！巫妖王昔日的奴仆——死亡骑士已经摆脱了他的控制，并结成了反抗其暴政的新同盟！"
D.Strings[26851]="死亡骑士曾是联盟的英雄，如今他们再次成为暴风城的盟友！你们应该欢迎他们，并给予他们应有的尊重！"
D.Strings[26852]="部落的同胞，你们的酋长有话要说！"
D.Strings[26853]="死亡骑士曾是部落的英雄，如今他们再次成为奥格瑞玛的盟友！你们应该欢迎他们，并给予他们应有的尊重！"
D.Strings[26854]="天灾军团！！！退后！加摩尔会保护你们的！"
D.Strings[26855]="我们冲破了监狱的大门！进入达拉然的道路被清理干净了！魔枢之战终于可以结束了！"
D.Strings[26856]="你击败了我忠诚的奴仆，但是你付出的努力是徒劳的。"
D.Strings[26857]="你成功啦！你击退了蓝龙军团，并杀死了他们的指挥官。这真是个奇迹！"
D.Strings[26858]="冰冠冰川的霜寒之心在等待……"
D.Strings[26859]="这里就交给我们吧。在那场战斗之后，你已经赢得了大家的尊重。"
D.Strings[26860]="%s笑了笑，重新附到了白骨女巫身上。"
D.Strings[26861]="警告：你已经进入了禁飞区域，骑乘状态即将解除！"
D.Strings[26862]="你！到前面来！"
D.Strings[26863]="尤格-萨隆！赐予我力量吧！"
D.Strings[26864]="主人，这是奉献给您的礼物！"
D.Strings[26865]="荣耀归于尤格-萨隆！"
D.Strings[26866]="你毫无价值。"
D.Strings[26867]="起来！你受的痛苦还远远不够呢。"
D.Strings[26868]="别以为你们亵渎了这里……还能安然无恙。"
D.Strings[26869]="元素之力必将崛起，夺回这个被文明玷污的世界！只有最虔诚的信徒才能幸免于难！"
D.Strings[26870]="只要将全部身心都献给伟大的尤格-萨隆，就连你们也可以获得不朽的生命！"
D.Strings[26871]="在这里，在最靠近他领地的地方，你可以亲身体会到这强大得无以复加的力量！"
D.Strings[26872]="你经历了长途跋涉和艰难险阻来到这里！你应为你的执着而得到奖励。"
D.Strings[26873]="信徒们，你们有理由高兴与欢呼，但我们仍有许多未尽的事业。在整个艾泽拉斯都被他的阴影笼罩之前，我们还要继续努力！"
D.Strings[26874]="一切胆敢践踏这片土地的入侵者都将被达卡莱巨魔消灭！"
D.Strings[26875]="你没气了？很好！"
D.Strings[26876]="害怕了吧？"
D.Strings[26877]="我下一个就要吃你！"
D.Strings[26878]="我明白了……天灾军团……并不是我们最大的敌人……"
D.Strings[26879]="你好。弗拉斯·希亚比现在不在。明天再来光顾希亚比的烟草店吧！哔哔！"
D.Strings[26880]="真是一群英勇的卫兵，但这座城市必须被夷平。我要亲自执行玛里苟斯大人的指令！"
D.Strings[26881]="<利用眼睛控制一只幻象观察者。>"
D.Strings[26882]="希望你不是来这里打架的。街上到处都是愤怒的市民。"
D.Strings[26883]="今天我只出售盾牌，不卖锤子。我不希望看到无辜的市民被我出售的武器所伤。"
D.Strings[26884]="整座城市都陷入了骚乱，我不知道今天还能营业多久。如果你要修理东西的话，我可以尽快帮你处理。"
D.Strings[26885]="让我们来做个了断吧，肯瑞托的勇士们！"
D.Strings[26886]="很抱歉，石鸦旅店今天暂停营业。最近饮食卫生问题闹得很严重，我可不想别人跳出来指责我们的厨师传播疾病。"
D.Strings[26887]="我要终结肯瑞托！"
D.Strings[26888]="达拉然即将沦陷！"
D.Strings[26889]="你对织法者的冒犯到此为止了。"
D.Strings[26890]="或许……我们……低估了……你们。"
D.Strings[26891]="我不喜欢让别人失望呢，但是石鸦旅店已经暂停营业了。孤儿院的孩子们都撤离了，我们为什么还要开门做生意。"
D.Strings[26892]="外面怎么乱哄哄的？"
D.Strings[26893]="出了什么事？我听到愤怒的喊叫声。"
D.Strings[26894]="最近发生的事情都很奇怪……"
D.Strings[26895]="在东瘟疫之地的圣光之愿礼拜堂，银色黎明指挥着对抗天灾军团的战斗。去那里接受命令吧。"
D.Strings[26896]="我要使用符文。"
D.Strings[26897]="你的能力还不足以参加冬拥湖的战斗。等你的经验更丰富一些后，再回来吧。"
D.Strings[26898]="该传送门通往冬拥湖。"
D.Strings[26899]="有谁能在我的力量面前屹立不倒？"
D.Strings[26900]="带我去见冰锤中尉，索雷克！"
D.Strings[26901]="许多人都死在了瓦哈拉斯，他们的尸体见证了比武场的残酷。$B$B$n，你的骸骨是否也会留在荣耀与血腥的战场呢？"
D.Strings[26902]="我很可能会在眨眼之间把你劈成两半，$r！$B$B如果你说完了废话，最好趁早滚开！"
D.Strings[26903]="瓦哈拉斯是你抉择生死之地，$n。在任何情况下，你都不能擅自退出比武场。如果你选择逃跑，就意味着你可耻地输掉了比赛。"
D.Strings[26904]="$n和$g他:她;的战友被选中，将在神圣的瓦哈拉斯进行光荣的战斗。"
D.Strings[26905]="瓦哈拉斯的战斗只有一个结果：必须有一方倒下。$n，如果你想要证明自己的力量，就必须将对手的尸体踩在脚下！"
D.Strings[26906]="挑战者失败了。他们不是维库人，落得败局也是可以预见的。"
D.Strings[26907]="比武场上的败者将带着羞耻离开尘世。"
D.Strings[26908]="还有谁想要在瓦哈拉斯一展实力？"
D.Strings[26909]="瓦哈拉斯不是消遣玩乐的地方。"
D.Strings[26910]="我们会再给战败者一次机会的。你们不是维库人，不能用比武场严格的标准要求你们。"
D.Strings[26911]="瓦哈拉斯的荣耀源于这满地的尸骨。让下一组挑战者进来吧！"
D.Strings[26912]="如果你目前的实力还不足以参加瓦哈拉斯的战斗，那么在尤顿海姆地区还有其他类型的比赛。"
D.Strings[26913]="$n战胜了瓦哈拉斯的英雄之魂。虽然这仅仅是一场热身赛，但是也算是精彩的对决吧。"
D.Strings[26914]="瓦哈拉斯的英雄之魂现身了，准备再次投入战斗！"
D.Strings[26915]="你还没有获得参与瓦哈拉斯比武赛的资格，$n。$B$B等你小有名气之后再到这里来吧。"
D.Strings[26916]="低等生物，竟敢入侵这里！可惜你们过度膨胀的勇气，无法挽救愚蠢所导致的悲惨结局！"
D.Strings[26917]="这里除了蓝龙军团，没有人可以进来。看来是阿莱克丝塔萨在搞鬼？很好，她实际上是派你们来送死的！"
D.Strings[26918]="你们以为自己能做些什么呢？自大地在我的领域横冲直撞，用毁灭性的魔法来对付……我？"
D.Strings[26919]="我在这里不受任何约束。那些你们必须遵循的法则对我无效。在这个领域之中，我就是一切！"
D.Strings[26920]="我给你们一次机会吧。向我宣誓效忠，这是让我原谅你们的傲慢与无礼的唯一机会。"
D.Strings[26921]="我的耐心到此为止了。我要亲自消灭你们！"
D.Strings[26922]="没有人体验过你们将要承受的痛苦！"
D.Strings[26923]="你们的愚蠢必将葬送自己！"
D.Strings[26924]="又有更多的神器可以没收了。"
D.Strings[26925]="太天真了！"
D.Strings[26926]="$n接受了黑暗主宰西塔利克斯的挑战。西塔利克斯绝不会手下留情的，愿诸神保佑$g他:她;吧。"
D.Strings[26927]="做好准备吧。西塔利克斯将从东南方进入瓦哈拉斯。记住，不要离开比武场，否则你就会输掉比赛。"
D.Strings[26928]="我原本只是想尽快结束你们的生命……可你们竟然远比我想象得要坚韧。虽然如此，你们的努力仍将付诸东流。事实上，这场战争本身就是因为你们凡人不计后果的行为而起，我只是在尽自己的责任罢了。如果这责任意味着要灭绝你们……那就这样吧！"
D.Strings[26929]="我要让你们这些无知的孩子重新了解魔法的概念。"
D.Strings[26930]="就这样无助地看着希望破灭吧！"
D.Strings[26931]="我会妥善利用你们留下的魔法能量。"
D.Strings[26932]="我是织法者！我的力量是无穷无尽的！"
D.Strings[26933]="你们的灵魂将永远在这里游荡！"
D.Strings[26934]="够了！既然你们这么想夺回艾泽拉斯的魔法，我就给你们！"
D.Strings[26935]="现在你们幕后的主使终于出现了，但已经太迟了！这里弥漫着的能量已经足以将世界毁灭十次。你们觉得他们会对你们做些什么呢？"
D.Strings[26936]="在我的龙息之下，一切都将荡然无存！"
D.Strings[26937]="在这里涌动的力量早已超越了你们的理解与想象！"
D.Strings[26938]="我无坚不摧！"
D.Strings[26939]="阿莱克丝塔萨，又有一个你的孩子倒下了！"
D.Strings[26940]="就比小虫子强了一点点！"
D.Strings[26941]="红龙军团也将步你们的后尘！"
D.Strings[26942]="竟然还没倒下？不会太久了。"
D.Strings[26943]="你们的妄想破灭了！"
D.Strings[26944]="你们脆弱的精神即将崩溃！"
D.Strings[26945]="不可思议！这群凡人……竟然毁灭了一切！我的妹妹，你都做了些……什么？"
D.Strings[26946]="昨天我就是这个摊位买的食物，现在我的家人都病倒了！"
D.Strings[26947]="呃，听到这样的消息真让我难过呀，但是我出售的食物都是新鲜的！"
D.Strings[26948]="绝不能释放这些囚犯！玛里苟斯的话就是律法！"
D.Strings[26949]="颤抖吧，蠕虫！"
D.Strings[26950]="会飞么？"
D.Strings[26951]="现在逃跑已经太晚了！"
D.Strings[26952]="都给我过来……"
D.Strings[26953]="谁也别想逃跑！"
D.Strings[26954]="我判处你们死刑！"
D.Strings[26955]="多么恰当的惩罚。"
D.Strings[26956]="行刑！"
D.Strings[26957]="又一个战争的牺牲品。"
D.Strings[26958]="战争……还会继续的。"
D.Strings[26959]="看来我的自由必须用鲜血去换取了！"
D.Strings[26960]="采之不尽，用之不竭的资源……我必须要得到它！"
D.Strings[26961]="看来我们有必要重新交涉一次。"
D.Strings[26962]="我们其实没有个人恩怨。"
D.Strings[26963]="纯粹是为利益而已。"
D.Strings[26964]="利益！"
D.Strings[26965]="这真是个……不可挽回的……损失。"
D.Strings[26966]="入侵者，你们一路的胜势到此为止了。我是指挥官瓦尔洛斯。我和飞龙们制御着这里的天空，保护着这里的管线，也将保证魔枢之眼不会落入你们的手中！"
D.Strings[26967]="我是不会心慈手软的！"
D.Strings[26968]="炸死他们！摧毁他们！"
D.Strings[26969]="不留俘虏！进攻！"
D.Strings[26970]="进攻！消灭他们！"
D.Strings[26971]="魔枢是我们的！"
D.Strings[26972]="他们……咳……太强大！我低估了……他们的顽强。"
D.Strings[26973]="$n和$g他:她;的战友击败了黑暗主宰西塔利克斯。下一场挑战马上开始！"
D.Strings[26974]="不要……呱呱……挡我……呱呱……去路！"
D.Strings[26975]="咔咔咔！"
D.Strings[26976]="宝贵的生命……呱呱……浪费了！"
D.Strings[26977]="强大的人……呱呱……才能活下去！"
D.Strings[26978]="没……呱……逃掉……"
D.Strings[26979]="感谢圣光再次赐予我机会。同样谢谢你，$n。"
D.Strings[26980]="要不是你，我早就沦为巫妖王的奴仆，成为天灾军团中的一员了。"
D.Strings[26981]="稍后我会正式地感谢你，但是现在我们还有一场仗要打！"
D.Strings[26982]="稍微见识见识吧……见识一下织法者的真正力量！"
D.Strings[26983]="这么多不稳定的能量……但为了消灭你们，这点风险不算什么！"
D.Strings[26984]="如果你能早点理解就好了！"
D.Strings[26985]="你明白了吗？明白了吗？！"
D.Strings[26986]="真不幸，但这是必要的。"
D.Strings[26987]="我所做的一切……都是为了艾泽拉斯……"
D.Strings[26988]="我就知道你会来的。"
D.Strings[26989]="战斗结束后，我就要把你们的徽记挂在艾卓-尼鲁布的城墙上！"
D.Strings[26990]="你卖的食物有毒！我的妻子和孩子都病倒了！"
D.Strings[26991]="你卖的食物有毒！我的丈夫和孩子都病倒了！"
D.Strings[26992]="肯定不是我卖的食物！"
D.Strings[26993]="别狡辩！你脱不了干系的！"
D.Strings[26994]="根本不关我的事啊！要不……要不我赔偿啊，就诊的钱我来出？你们到底要我怎么样！"
D.Strings[26995]="蠢货！你们根本无法理解这种你们正在对抗着的伟大力量。魔网能量的传输是不会被你们干扰的！而你们，唯一的结局只有失败与死亡！"
D.Strings[26996]="呸……省省吧！不收你的钱，这也救不了我的家人！"
D.Strings[26997]="%s烹制了大型筵席！"
D.Strings[26998]="$n烹制了鱼肉筵席！"
D.Strings[26999]="$n烹制了小型筵席！"
D.Strings[27000]="$n烹制了丰盛筵席！"
D.Strings[27001]="狗联盟，仰天长泣吧。你最好祈祷我的伤口没有那么快就愈合。"
D.Strings[27002]="绿皮怪！闭嘴，不然我就割下你的舌头，去喂你那群猪崽子。"
D.Strings[27003]="你找死啊，杂种！"
D.Strings[27004]="从你谋杀伯瓦尔的那天起，你就该死了！诅咒你！"
D.Strings[27005]="刚才的战斗给我留下了深刻的印象。"
D.Strings[27006]="打得不错……"
D.Strings[27007]="我期待着这场对决。"
D.Strings[27008]="尝到痛苦的滋味了吧。"
D.Strings[27009]="现在，你肯定希望自己是个亡灵吧。"
D.Strings[27010]="欢迎来到亡者的世界。"
D.Strings[27011]="真是可贵的努力。"
D.Strings[27012]="别停手啊，我就快出汗啦。"
D.Strings[27013]="我不怕死。我会回来……找你……"
D.Strings[27014]="你的血真甜。"
D.Strings[27015]="又多了一件战利品。"
D.Strings[27016]="你的鲜血归我啦。"
D.Strings[27017]="脆弱的生物。"
D.Strings[27018]="就凭你们几个？连慷慨陈词都没有？你们的“荣耀”不过如此。"
D.Strings[27019]="真是动听的豪言壮语啊，但是你们必须面对现实。"
D.Strings[27020]="你终将臣服于巫妖王的意志……很快。"
D.Strings[27021]="等我解决了你的朋友，你就会成为天灾军团的新兵了。"
D.Strings[27022]="你在死后也不会得到安息的。"
D.Strings[27023]="永恒的痛苦才刚刚开始。"
D.Strings[27024]="你的灵魂属于我了。"
D.Strings[27025]="你们这些莽撞的入侵者已经无计可施了！我要亲自把你们碾碎！"
D.Strings[27026]="如此肆意妄为，如此骄纵轻狂……必须惩罚你们！"
D.Strings[27027]="自然魔法现在帮不了你们啦！"
D.Strings[27028]="奥术魔法归我们号令！休想用它来对付我们！"
D.Strings[27029]="熄灭你们的小火苗，完全没有难度！"
D.Strings[27030]="这可要很久才能落地的……"
D.Strings[27031]="回到尘土中去！"
D.Strings[27032]="好好享受坠落的快感！"
D.Strings[27033]="好好珍惜这场胜利吧，愚蠢的低等动物。你们和你们的龙类盟友或许赢得了这次战役，但我们……才是整个魔枢战争的胜利者。"
D.Strings[27034]="啊，是你！还记得我吗？我相信你记得！等着吧，我这就下来。"
D.Strings[27035]="我说过，下次见面时，我会做好充分的准备。我取得了海德比武会的胜利，在瓦基里安接受了严酷的训练。今非昔比，尝尝我的厉害吧！"
D.Strings[27036]="深渊的秘密，就永远留在深渊之中吧。"
D.Strings[27037]="卡纳基来啦！记住，在任何情况下，都不能离开比武场，否则就取消你们的参赛资格。"
D.Strings[27038]="幼体可千万不能饿着了……"
D.Strings[27039]="在寒冷的黑暗中长眠吧……"
D.Strings[27040]="或许你很快就要成为我的盟友啦。"
D.Strings[27041]="主人……我的使命……结束了吗？"
D.Strings[27042]="齐格莉德·冰魂已经重返尤顿海姆，她将与$n展开对决。他们上次交手时，$n战胜了她。这场比赛的胜负如何呢？让我们拭目以待吧！"
D.Strings[27043]="我……呱呱……最喜欢的！哇哇哇！呱呱！"
D.Strings[27044]="一只安卡哈守护者孵化了！"
D.Strings[27045]="我要吞噬你们的尸体！"
D.Strings[27046]="你的心跳在我耳中就是最美妙的音乐。"
D.Strings[27047]="我在，我亦不在。我就是那无形无迹的监视者。"
D.Strings[27048]="不错的开胃菜。"
D.Strings[27049]="新鲜的肉，温暖的血……好久没有尝到了。"
D.Strings[27050]="我已经很久没有痛饮过鲜血了。"
D.Strings[27051]="最后的……拥抱。"
D.Strings[27052]="我依然这么饿。我依然……这么……渴。"
D.Strings[27053]="你们烧焦的骨头正好可以用来装饰地板！"
D.Strings[27054]="你们能承受多高的温度呢？"
D.Strings[27055]="一切都将化为灰烬！"
D.Strings[27056]="燃烧吧，你们这些可怜虫！"
D.Strings[27057]="你或许会是孩子们最好的晚餐。"
D.Strings[27058]="你们真是占尽了下风。"
D.Strings[27059]="这就是你们被称为低等生物的原因！"
D.Strings[27060]="你将孤独地走向生命的终点。"
D.Strings[27061]="信任他人是你最大的弱点。"
D.Strings[27062]="希望是无谓的幻象。"
D.Strings[27063]="你所知的一切都将消逝。"
D.Strings[27064]="你们疯了吗？停止这愚蠢的战斗！"
D.Strings[27065]="兄弟姐妹们，我们必须保持团结！如果我们闹起了内部分裂，还怎么战胜巫妖王！"
D.Strings[27066]="难道你们没有发现自己中了巫妖王的圈套？他就是希望你们自相残杀啊！"
D.Strings[27067]="加入银色北伐军吧！只要我们团结起来，就一定能消灭巫妖王！"
D.Strings[27068]="审判之日已经来临，兄弟姐妹们！你们准备好了吗？"
D.Strings[27069]="为了攻击联盟，我们浪费了多少力气？"
D.Strings[27070]="$n再次击败了齐格莉德·冰魂。好吧，虽然$g他:她;是在队友的帮助下获胜的，但是胜利就是胜利！"
D.Strings[27071]="我们必须团结起来，一致对抗真正的威胁：巫妖王！"
D.Strings[27072]="为了攻击部落，我们浪费了多少力气？"
D.Strings[27073]="卡纳基来自曲径幽深的地下大厅。勇敢又愚蠢的$n已经接受了这个挑战。$G他:她;将率领自己的队伍面对这个怪物。"
D.Strings[27074]="可怕的卡纳基已经不复存在啦。$n真的配得上瓦哈拉斯的战斗吗？让我们拭目以待吧。"
D.Strings[27075]="呃……别……别管我。$b$b我……没救了……"
D.Strings[27076]="收集……天灾军团的……情报。$b$b联盟的军队出现了……$b$b我们躲了起来，接着他们开始攻打大门……然后我们从背后发动了袭击。$b$b三方展开了混战……但是天灾军团……数量太多了……$b$b我的$g兄弟:姐妹;……那真是一场……荣耀的战斗。"
D.Strings[27077]="坚持住，朋友。告诉我究竟发生了什么事。"
D.Strings[27078]="够了！你们这些爬虫不配在这片圣地上战斗！你们的战斗毫无荣誉可言！你们别想战胜我！"
D.Strings[27079]="来受死吧，懦夫！"
D.Strings[27080]="我听见齐格莉德·冰魂的声音从西北方传来。我们已经告知她不得在比武场中使用始祖龙。不要离开竞技场！"
D.Strings[27081]="往东南方看，领主很快就会出现在残忍的亚纳尔附近的平台上。等他自己下来。不要离开瓦哈拉斯的竞技场。"
D.Strings[27082]="数个世纪后，巴纳霍格领主首次重返瓦哈拉斯。他要证明，只有维库人才有资格在这片圣地上战斗。$n能证明他错了吗？"
D.Strings[27083]="巴纳霍格领主败在了$n和$g他:她;的战友手下。挑战者即将迎来最后一场对决。他们的对手是谁呢？"
D.Strings[27084]="$n，在我最需要帮助的时候，是圣光的赐福让你找到了我。"
D.Strings[27085]="我受够这个鬼地方了。我们走吧。"
D.Strings[27086]="谢谢你救了我。回去之后，我一定会向大家宣扬你的勇敢。请你竭尽所能，与天灾军团抗衡吧。我们会帮助你的。"
D.Strings[27087]="请转告我的兄弟，我还活着。"
D.Strings[27088]="难以置信啊……$n杀死了萨杜瓦尔王子！"
D.Strings[27089]="挑战者击败了王子，这证明$g他:她;及其战友完全有资格在维库人的圣地上战斗！"
D.Strings[27090]="审判之日即将来临。你深知正义才是唯一正确的道路。"
D.Strings[27091]="向$n，瓦哈拉斯的勇士欢呼吧！"
D.Strings[27092]="现在逃跑已经太迟啦。不要离开比武场。慷慨地赴死吧，$n！"
D.Strings[27093]="接受圣光的审判吧！"
D.Strings[27094]="挑战者的对手来自冰冠堡垒，这位被巫妖王选中的勇士是来终结$n及其战友的生命的。"
D.Strings[27095]="银色北伐军决不投降！"
D.Strings[27096]="原谅我，兄弟们，我让你们失望了……"
D.Strings[27097]="尤顿海姆的战士们，他就是血精灵王子萨杜瓦尔！"
D.Strings[27098]="亲爱的，你的介绍可不怎么得体。那么，这位声名大噪的挑战者是谁呢？"
D.Strings[27099]="我会尽量让你死个痛快的。过来受死吧。你侵犯并玷污了这座神圣的比武场，而我只要求你用性命赎罪罢了。"
D.Strings[27100]="你光荣地完成了任务……我会让整个部落都知道你获胜的消息的。"
D.Strings[27101]="哎呀，黑锋骑士团派人来杀我了。我害怕得发抖啊。"
D.Strings[27102]="我为部落……奉献了一切……"
D.Strings[27103]="哈！你们就这点本事啊？就凭这点实力，你们也敢闯进城堡啊。"
D.Strings[27104]="巫妖王赐予我的力量远远超过了你们的想象。看招！"
D.Strings[27105]="该结束了。"
D.Strings[27106]="你总算来了，达里安！我正在猜想你什么时候会露面呢。"
D.Strings[27107]="泰里恩随口吹嘘了几句，你竟然就被蛊惑了，以为他会赢得最终的胜利。达里安，你终究是个胆小鬼啊。就跟你的父亲一样。"
D.Strings[27108]="%s狡黠地笑了笑。"
D.Strings[27109]="巫妖王会将……你们……统统……干掉。"
D.Strings[27110]="脆弱的家伙。"
D.Strings[27111]="巫妖王又多了一名仆从。"
D.Strings[27112]="这算什么挑战。"
D.Strings[27113]="哎呀……你这就死了啊。"
D.Strings[27114]="藐视巫妖王的权威是要付出代价的！"
D.Strings[27115]="就凭你，也想反抗我的意志，破坏我的计划吗？"
D.Strings[27116]="你将一事无成！"
D.Strings[27117]="奥尔巴兹·血毒，就凭你也敢自称是巫妖王的左膀右臂。"
D.Strings[27118]="停止无力的抵抗吧，这仅仅能延缓你的毁灭罢了。"
D.Strings[27119]="你迫不及待地想要除掉我，然后独揽大权是吗？"
D.Strings[27120]="趁你还活着，只管宣扬这些陈词滥调吧。你终究会落到我的手里，摩比乌斯将宣告你的死讯！"
D.Strings[27121]="为我报仇，$g兄弟:姐妹;……"
D.Strings[27122]="摩比乌斯，让他们知道，敢于违抗国王的旨意是什么下场！"
D.Strings[27123]="等等，$c……$b$b我还有最后……一个请求……"
D.Strings[27124]="奥尔巴兹，你根本就不具备领袖的天赋，你连一队没脑子的骷髅都指挥不了！"
D.Strings[27125]="我们……是无比强大的龙族！怎……怎么会这样……？"
D.Strings[27126]="我无所畏惧！你们根本不值一提！"
D.Strings[27127]="渺小卑微的东西。"
D.Strings[27128]="真是微弱的抵抗……"
D.Strings[27129]="你们太容易对付了！"
D.Strings[27130]="父亲大人教了我很多东西。"
D.Strings[27131]="我真是同情你，萨塔里奥，仅此一次。"
D.Strings[27132]="啊……太晚了，$g兄弟:姐妹;。$b$b我……快死了……"
D.Strings[27133]="你们没资格来这里！你们的归宿……在死者的国度！"
D.Strings[27134]="毫无悬念。"
D.Strings[27135]="轻松。就像我平常的娱乐一样……"
D.Strings[27136]="我要将你们投入黑暗中。"
D.Strings[27137]="一群自大的低等生物。来挑战一下你们永远也无法理解的强大力量吧。"
D.Strings[27138]="我不仅仅是一条龙。你们还可以在我身上发现更多的秘密。"
D.Strings[27139]="欣赏你的挣扎真是令人愉悦。好吧，现在让你见识见识该怎么了结这一切！"
D.Strings[27140]="我不该……犹……犹豫的……"
D.Strings[27141]="你们这些下等生物根本无法对我构成任何威胁！使出全力战斗吧！"
D.Strings[27142]="你唯一可以做到的事情，就是体面地战死！"
D.Strings[27143]="这就是你的全部实力了吗？"
D.Strings[27144]="我要用你们的骨头来剔牙！"
D.Strings[27145]="与你们不同的是，我有无数的绝技！"
D.Strings[27146]="父亲大人对你的评价一点都没错，萨塔里奥。你就是个废物。"
D.Strings[27147]="我还能……继续……战……"
D.Strings[27148]="谢谢你。如果你还有其他需要，可以到银色前线基地来找我。"
D.Strings[27149]="你必须打败萨杜瓦尔王子。这是你活下来的唯一希望，$c。"
D.Strings[27150]="朋友，坚持住。告诉我究竟出了什么事。"
D.Strings[27151]="$n，瓦哈拉斯的勇士，很高兴再次见到你。$B$B你是回来帮助朋友作战的吗？"
D.Strings[27152]="我们在暴风雪的掩护下发动了进攻……$b$b天灾军团被打了个措手不及……眼看就要取得胜利……$b$b突然……我们遭遇了……部落大军的偷袭。$b$b他们毁了……一切……"
D.Strings[27153]="黑锋骑士们，准备战斗！"
D.Strings[27154]="我听够了你的废话！骑士们，前进！"
D.Strings[27155]="等等……$b$b还有一件事……"
D.Strings[27156]="坚强点，朋友。去做你该做的事吧……"
D.Strings[27157]="破败的大厅前，一位幽灵用肢体和口型传达着无声的语言，另一群幽灵则坐在地上，聚精会神地听着。"
D.Strings[27158]="失落的杉达拉之魂默默地跪在紫色的湖泊前，凝视着平静的湖面。"
D.Strings[27159]="嗨，我们又见面了！"
D.Strings[27160]="干得好！阿尔萨斯正在赶往诺森德！"
D.Strings[27161]="阿尔萨斯王子背叛了我们？"
D.Strings[27162]="亡灵冲我们来了！"
D.Strings[27163]="我们要守住这里！"
D.Strings[27164]="传言是真的！王子已经疯了！"
D.Strings[27165]="我的家人都病倒了！"
D.Strings[27166]="整座城市都被疾病传染了！"
D.Strings[27167]="我们是吃了你的粮食才生病的！"
D.Strings[27168]="都是因为你！我敢打赌！"
D.Strings[27169]="这是毒药！是毒药！"
D.Strings[27170]="我们本来身体好好的，就是吃了这些被污染的粮食之后才病倒的！"
D.Strings[27171]="你有什么理由阻止我们烧掉这些谷物！"
D.Strings[27172]="女王陛下，他们知道吗？"
D.Strings[27173]="我只是负责运货而已！"
D.Strings[27174]="不，亲爱的。"
D.Strings[27175]="不能让他们知道年轻的圣骑士的命运。还不到时候。"
D.Strings[27176]="我要输入神秘兑换码，兑换暴雪巨熊。"
D.Strings[27177]="我没动过手脚！我发誓！"
D.Strings[27178]="我只是个送货的！"
D.Strings[27179]="我什么都没干！"
D.Strings[27180]="他们不会知道的。"
D.Strings[27181]="到我这里来，$n。"
D.Strings[27182]="退潮了……"
D.Strings[27183]="我就是自然之力！"
D.Strings[27184]="我要离开这里！"
D.Strings[27185]="你们无法阻止汹涌的海潮！"
D.Strings[27186]="我是不会被困住的！Ngyah！！"
D.Strings[27187]="我要吞噬，要屠戮，要毁灭，要破坏！在澎湃的大海面前屈服吧！"
D.Strings[27188]="流水无形，它可以化为任何形态……跨越任何障碍。"
D.Strings[27189]="别挡道，凡人！"
D.Strings[27190]="巴瑟拉斯在哪儿？！"
D.Strings[27191]="我们要和镇长谈一谈！"
D.Strings[27192]="我们该怎么办？！"
D.Strings[27193]="我们需要有人领导！"
D.Strings[27194]="别再躲了，巴瑟拉斯！"
D.Strings[27195]="让我们进去！"
D.Strings[27196]="是不是非要我们把你拖出来啊！"
D.Strings[27197]="陆战队员，快！"
D.Strings[27198]="保持警惕，陆战队员！"
D.Strings[27199]="放松点，陆战队员！"
D.Strings[27200]="陆战队员，稍息！"
D.Strings[27201]="镇长很忙。"
D.Strings[27202]="请大家回家去吧。"
D.Strings[27203]="各位，请保持冷静……"
D.Strings[27204]="巴瑟拉斯镇长现在没空……"
D.Strings[27205]="护盾法师，撑起护盾！"
D.Strings[27206]="请不要再聚集在这里！"
D.Strings[27207]="请大家不要打扰镇长！"
D.Strings[27208]="法师们，启动防御措施！撑起护盾！"
D.Strings[27209]="回去吧，我们不会让你们进来的！"
D.Strings[27210]="西部下水道的入口在通往紫罗兰城堡的阶梯下面。"
D.Strings[27211]="东部下水道的入口在克拉苏斯平台的入口外面。"
D.Strings[27212]="掠天者，准备战斗！"
D.Strings[27213]="准备战斗，掠天者！"
D.Strings[27214]="掠天者，撤退！"
D.Strings[27215]="撤退，掠天者！"
D.Strings[27216]="暗影卫士，展现实力的时候到了！"
D.Strings[27217]="达拉然墓地位于城市西部，紫罗兰城堡的北面。"
D.Strings[27218]="暗影卫士，保护我们的飞船！"
D.Strings[27219]="日暮广场位于达拉然南部。广场上的魔法喷泉是很受欢迎的钓鱼场所。"
D.Strings[27220]="鲁因广场是一座位于达拉然中心的公园。"
D.Strings[27221]="安东尼达斯的纪念碑位于达拉然北部。"
D.Strings[27222]="在达拉然城北有一口井，某些……富有冒险精神的游客能通过那口井进入下水道。"
D.Strings[27223]="动作快点，蠢货！巫妖王可没有耐心来容忍你们这些懒骨头！"
D.Strings[27224]="瓦格里工头，给我盯紧点。我们必须提高产量！"
D.Strings[27225]="难道一定要我亲自监督吗，啊？！"
D.Strings[27226]="紫罗兰监狱位于达拉然东南部，用于关押肯瑞托法师议会的敌人。"
D.Strings[27227]="啊，新的奴隶来啦。瓦格里工头们，给他们分配工作，让他们马上开工！"
D.Strings[27228]="看见达拉然东部的巨塔了吗？那就是宏伟的紫罗兰城堡。"
D.Strings[27229]="部落旅客主要集中在达拉然东北部的夺日者圣殿。$B$B那里设有旅店，还有通往各大战场和奥格瑞玛的传送门。"
D.Strings[27230]="联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。"
D.Strings[27231]="达拉然至少有三条地下通道：东部和西部各有一个下水道入口，北部还有一口井。"
D.Strings[27232]="东部下水道入口"
D.Strings[27233]="西部下水道入口"
D.Strings[27234]="水井入口"
D.Strings[27235]="达拉然有许多有趣的地方。你想去哪里？"
D.Strings[27236]="联盟区"
D.Strings[27237]="部落区"
D.Strings[27238]="紫罗兰城堡"
D.Strings[27239]="紫罗兰监狱"
D.Strings[27240]="下水道"
D.Strings[27241]="安东尼达斯纪念碑"
D.Strings[27242]="鲁因广场"
D.Strings[27243]="日暮广场"
D.Strings[27244]="墓地"
D.Strings[27245]="达拉然的竞技场和管理员都在这座城市的下水道里。$B$B至少有三条地下通道可以抵达那里：东部和西部下水道的入口，还有北部的水井。"
D.Strings[27246]="在达拉然的联盟区银色领地和部落区夺日者圣殿都设有通往暴风城、奥格瑞玛和各大战场的传送门。"
D.Strings[27247]="快点干活，别找麻烦！"
D.Strings[27248]="遵……遵命……一定遵照您的吩咐。"
D.Strings[27249]="缝合场再也不能为巫妖王制造血肉大军了。"
D.Strings[27250]="让我们杀了这个……东西……了结这里的麻烦。"
D.Strings[27251]="在肯瑞托议会中，我的职责是保障法师议会的战略利益。$B$B本周要做的事情还有很多，$n。你愿意帮忙吗？"
D.Strings[27252]="魔法商业区位于达拉然西北部，那里汇集了大部分专业技能训练师。"
D.Strings[27253]="贸易区"
D.Strings[27254]="魔法商业区的避邪纺织店汇集了全城最好的裁缝。魔法商业区就在达拉然的西北部。"
D.Strings[27255]="魔法商业区的传说皮甲汇集了各种剥皮和制皮训练师。魔法商业区就在达拉然的西北部。"
D.Strings[27256]="魔法商业区的亮晶晶矿业公司汇集了全城的采矿训练师和供应商。魔法商业区就在达拉然的西北部。"
D.Strings[27257]="你要找的卡蒂亚珠宝店就在达拉然西北部的魔法商业区。"
D.Strings[27258]="你要找的铭文师的殿堂就在达拉然西北部的魔法商业区。"
D.Strings[27259]="在达拉然西北部的魔法商业区，农艺炼金房的旁边坐落着一间温室。你可以在那里找到全城最好的草药师。"
D.Strings[27260]="在达拉然南部的日暮广场内有一座魔法喷泉，你可以在那附近找到钓鱼训练师。"
D.Strings[27261]="在达拉然西北部的魔法商业区设有全城最高级的急救中心——急你所急。"
D.Strings[27262]="工程师可以前往达拉然西北部的魔法商业区，在精密仪器接受训练。"
D.Strings[27263]="你可以去简单附魔瞧一瞧，就在达拉然西北部的魔法商业区外面。"
D.Strings[27264]="你可以在联盟区和部落区旅店的厨房里找到烹饪训练师。"
D.Strings[27265]="联盟旅店"
D.Strings[27266]="部落旅店"
D.Strings[27267]="英雄之家位于达拉然西南部的银色领地旁边。$B$B那里不仅设有露天啤酒店，还汇集了全城最好的烹饪训练师。"
D.Strings[27268]="你可以前往达拉然东北部的部落区，去夺日者圣殿的“肮脏的野兽”瞧一瞧。$B$B听说那里非常脏乱，但是有一位很棒的烹饪训练师。"
D.Strings[27269]="达拉然西北部的魔法商业区内设有大型的锻造台和熔炉。$B$B你只要找到巨大的魔法铁砧和描绘着战斧及护盾图案的彩色玻璃窗就对了。"
D.Strings[27270]="农艺炼金房位于达拉然西北部的魔法商业区，房间的门呈药水瓶状。你是不可能找错地方的！"
D.Strings[27271]="你要找哪一种专业训练师？"
D.Strings[27272]="奥格瑞玛正处于封锁状态。所有商店全部关闭。如果你要寻找商人、拍卖师或训练师，请前往雷霆崖或是银月城。$B$B幽暗城还是算了吧！"
D.Strings[27273]="高等精灵希拉·雪晨能教你学会寒冷天气飞行。$B$B她骑着龙鹰，就在达拉然东部的克拉苏斯平台上。"
D.Strings[27274]="达拉然的法师训练师和传送门训练师聚集在东部的一幢大型建筑物内，就在城市中心的鲁因广场和克拉苏斯平台之间。"
D.Strings[27275]="你要找哪一种训练师？"
D.Strings[27276]="法师训练师"
D.Strings[27277]="你可以在达拉然东北部的魔法动物店找到兽栏管理员。"
D.Strings[27278]="魔术旅馆是达拉然最受欢迎的旅店，就在市中心以北。$B$B联盟区和部落区均设有旅店。听说达拉然下水道里也有一家旅店。"
D.Strings[27279]="达拉然著名的理发店就坐落在城市北部。"
D.Strings[27280]="你可以在达拉然东部的克拉苏斯平台找到飞行管理员。"
D.Strings[27281]="达拉然银行位于城市北部。"
D.Strings[27282]="达拉然商业银行位于城市南部，毗邻日暮广场。"
D.Strings[27283]="糟糕！车间要爆炸啦！快离开这里，快！"
D.Strings[27284]="达拉然内设有三座银行：北部的达拉然银行，南部的达拉然商业银行以及位于下水道的银行。"
D.Strings[27285]="北部银行"
D.Strings[27286]="南部银行"
D.Strings[27287]="达拉然设有许多信箱：你可以在各个街道转角，旅店和银行外以及克拉苏斯平台找到它们。"
D.Strings[27288]="克拉苏斯平台"
D.Strings[27289]="克拉苏斯平台位于达拉然的最东端。$B$B本城的飞行管理员和寒冷天气飞行训练师都在那里。"
D.Strings[27290]="达拉然没有拍卖行。你必须通过传送门返回各大主城才能使用拍卖行。$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。"
D.Strings[27291]="你想销毁我们的原料是吧？呃，主人已经想到了一项特殊的计划……"
D.Strings[27292]="你需要什么服务？"
D.Strings[27293]="瞧！冰霜巨龙！它冲我们来了！"
D.Strings[27294]="服务"
D.Strings[27295]="主城传送门"
D.Strings[27296]="竞技场"
D.Strings[27297]="联盟旅客主要集中在达拉然西南部的银色领地。$B$B那里设有旅店，还有通往各大联盟主城和战场的传送门。"
D.Strings[27298]="欢迎来到达拉然，旅行者。$B$B我能帮你什么忙吗？"
D.Strings[27299]="陌生人，在达拉然逗留期间，请您遵守此地的法律。$B$B您迷路吗？我能帮上什么忙吗？"
D.Strings[27300]="副本即将重置。你即将被移出副本。"
D.Strings[27301]="达拉然的公会注册员就在市中心以南的旅客中心。"
D.Strings[27302]="副本已重置。"
D.Strings[27303]="副本将在10分钟后重置。"
D.Strings[27304]="副本将在5分钟后重置。"
D.Strings[27305]="副本将在3分钟后重置。"
D.Strings[27306]="副本将在2分钟后重置。"
D.Strings[27307]="副本将在1分钟后重置。"
D.Strings[27308]="欧尔拉金，你给我滚回来！这里还有很多工作要做呢！"
D.Strings[27309]="副本将在30秒后重置。"
D.Strings[27310]="你会为自己的行径付出代价的！为银色北伐军而战！"
D.Strings[27311]="骷髅废物。我的耐心已经到头了！"
D.Strings[27312]="$n，根据我的预见，你将同大法师兰达洛克谈话。"
D.Strings[27313]="达拉然只有法师训练师。如果你要找其他职业的训练师，就必须通过传送门返回各大主城。$B$B$B$B传送门位于达拉然的联盟和部落区：银色领地和夺日者圣殿。"
D.Strings[27314]="下水道的东北部有一个黑市。"
D.Strings[27315]="西部下水道设有通往城市底层的隧道，就在咒语和乌鸦旅店以北。$B$B有些喜欢冒险的旅客会从隧道进出达拉然。"
D.Strings[27316]="你要找的是咒语和乌鸦旅店吧，就在西部下水道。"
D.Strings[27317]="西部下水道有一座地精开设的银行，就在咒语和乌鸦旅店以北。"
D.Strings[27318]="热砂港在达拉然的中心下水道里举办竞技场循环赛。$B$B你还可以参与意志竞技场的比赛。"
D.Strings[27319]="东部下水道有一条直通克拉苏斯平台的斜道。"
D.Strings[27320]="西部下水道有一条通往紫罗兰城堡附近的斜道。"
D.Strings[27321]="达拉然下水道共有三条出路：通往东城和西城的斜道，以及通往达拉然底层的隧道。$B$B当然，你可以乘坐飞行坐骑穿越那条隧道。"
D.Strings[27322]="下水管道"
D.Strings[27323]="欢迎来到达拉然下水道。我能帮你什么忙吗？"
D.Strings[27324]="必须不惜一切代价阻止天灾军团。绝不能让他们在这里组建的大军进入战场。"
D.Strings[27325]="%s跑向他的铁砧！"
D.Strings[27326]="下水道出口"
D.Strings[27327]="不准朝我扔石头！"
D.Strings[27328]="如果惹我发火，你就要倒霉了……"
D.Strings[27329]="哈！总算有理由干掉你了！"
D.Strings[27330]="去死吧，骷髅！"
D.Strings[27331]="忍无可忍了……"
D.Strings[27332]="我一直在找机会，好拆了你的骨头！"
D.Strings[27333]="这是你最后一次犯错误了，骷髅。"
D.Strings[27334]="帮帮我们！求求你！"
D.Strings[27335]="幽暗城被攻陷了。如今城里只剩下恶魔和普特雷斯的药剂师了。"
D.Strings[27336]="你一定要帮帮我们！我们已经无家可归了！"
D.Strings[27337]="你能给我一枚金币吗？"
D.Strings[27338]="他们杀了好几百人！我们好不容易才捡回性命！帮帮我们！"
D.Strings[27339]="黑暗女王竭尽全力迎战，但最终……希望她能活下来。请你帮帮我们！"
D.Strings[27340]="被遗忘者完蛋了！发发善心吧！"
D.Strings[27341]="出了什么事？"
D.Strings[27342]="被遗忘者在这里干什么？"
D.Strings[27343]="城市怎么被封锁了？"
D.Strings[27344]="回答我们！"
D.Strings[27345]="酋长呢？"
D.Strings[27346]="商店什么时候才能重新开业啊？我一直在亏损！"
D.Strings[27347]="萨尔怎么能听任我们的城市发生这种事？"
D.Strings[27348]="我们正处在与联盟爆发全面战争的边缘！"
D.Strings[27349]="诺森德发生了许多悲剧事件。酋长正在尽力保障我们的安全。"
D.Strings[27350]="在没有进一步的通告前，所有的服务设施和商店都不得开业！就是这样！"
D.Strings[27351]="%s百无聊赖地在克拉苏斯平台上转悠。"
D.Strings[27352]="%s抬起手掌，轻轻地打了个哈欠。"
D.Strings[27353]="我被地雷炸到了！"
D.Strings[27354]="来吧，云翼。我们来飞一圈。"
D.Strings[27355]="我被部落击中了！"
D.Strings[27356]="%s轻轻地叹了口气，耸了耸肩。"
D.Strings[27357]="我被联盟击中了！"
D.Strings[27358]="好无聊啊，云翼。走吧！"
D.Strings[27359]="你也像我一样安静不下来吧，云翼？那我们去飞一会儿吧！"
D.Strings[27360]="我们的道路是神圣的。我们宁愿死去，也不会背弃托里姆，与巫妖王同流合污。"
D.Strings[27361]="我不能再纵容我的兄弟了。是时候纠正他犯下的过错了。我们要消灭他和他的追随者。"
D.Strings[27362]="重大发现！ $n发现了一种新的铭文！"
D.Strings[27363]="求求你，$r。$b$b让我解脱吧……"
D.Strings[27364]="别犹豫，$c。$b$b动……动手吧……"
D.Strings[27365]="请转告我的家人……$b$b我临死前还记挂着他们……"
D.Strings[27366]="送我上路吧……求求你……"
D.Strings[27367]="动手吧，$c……然后……为我复仇！"
D.Strings[27368]="求求你，$r……$b$b我不想被天灾军团复活！"
D.Strings[27369]="一路走好，联盟的英雄！"
D.Strings[27370]="握紧你们的武器，兽人！"
D.Strings[27371]="准备战斗，炼金区的叛徒们似乎把城门当作了目标地点！"
D.Strings[27372]="朝着荣耀之路前进吧，兽人！"
D.Strings[27373]="普特雷斯那个恶棍是不会得逞的！"
D.Strings[27374]="我们竟然没有料到这样的后果，竟然相信了恐惧魔王！"
D.Strings[27375]="真不敢相信，诅咒教派竟然如此粗心，把这些东西都落下了。"
D.Strings[27376]="我准备好发起进攻了，克里托斯。给我一匹骷髅狮鹫吧？"
D.Strings[27377]="<通过眼睛控制一只轻盈追迹者。>"
D.Strings[27378]="这个王国已经属于天灾军团了。只有亡者才能通行！"
D.Strings[27379]="你们的到来体现了自身的愚蠢。"
D.Strings[27380]="遵照阿努巴拉克的命令！"
D.Strings[27381]="我们被攻击了！立刻出击，把敌人的尸体给我带回来！"
D.Strings[27382]="我们必须守住大门。进攻！将他们撕成碎片！"
D.Strings[27383]="不惜一切代价保卫城门！把他们全都撕碎！"
D.Strings[27384]="小心守着隧道。我们不能让任何人通过！"
D.Strings[27385]="我听到了脚步声。提高警惕。"
D.Strings[27386]="活人的气息。准备战斗。"
D.Strings[27387]="它们很饿了……"
D.Strings[27388]="宠物们，该吃晚饭了！"
D.Strings[27389]="我本该感谢你们的……但我已经没有那个资格了……"
D.Strings[27390]="返回哭泣采掘场！"
D.Strings[27391]="阿尔萨斯的弱点就是骄傲。随着他的力量日益强大，这个弱点也越来越明显。我相信，黑锋骑士团一定能找到机会击败这位前王子。"
D.Strings[27392]="库卡隆，退下！"
D.Strings[27393]="吉安娜……"
D.Strings[27394]="萨尔，出了什么事？国王正在备战……"
D.Strings[27395]="吉安娜，天谴之门的事，是因为我们中间出了叛徒……"
D.Strings[27396]="普罗德摩尔女士，酋长说的是实话。这是瓦里玛萨斯和大药剂师普特雷斯安排的诡计，并非部落的本意。"
D.Strings[27397]="自从联盟和部落进军天谴之门以来，幽暗城就发生了暴乱。瓦里玛萨斯和他的恶魔同党叛变了，残忍地杀害了数百名无辜的平民。我是好不容易才逃出来的。"
D.Strings[27398]="部落已经失去了幽暗城。"
D.Strings[27399]="我们正准备围攻那座城市，将这群不可饶恕的罪魁祸首绳之以法。"
D.Strings[27400]="如果闹起内讧，巫妖王就会摧毁我们在诺森德的驻军。"
D.Strings[27401]="我们会妥善处理的，吉安娜。请你把这里的情况转告国王吧。"
D.Strings[27402]="我会转告国王的，萨尔，但是……"
D.Strings[27403]="伯瓦尔与他情同手足。国王离开期间，是他维系着联盟的团结。在最艰难的日子里，他是人民的支柱。他监护着安度因，将其视如己出。"
D.Strings[27404]="我担心国王克制不了心中的怒火，萨尔。希望我能说服他吧，但是我们必须做好最坏的打算……比如战争。"
D.Strings[27405]="再见，酋长。希望下次见面时，我们能够成为盟友。"
D.Strings[27406]="库卡隆，准备传送到幽暗城。"
D.Strings[27407]="字填在此"
D.Strings[27408]="请翻到第二页。"
D.Strings[27409]="%s吐丝结茧！"
D.Strings[27410]="%s朝四周喷射蛛丝！"
D.Strings[27411]="蛛网上爬出了小蜘蛛！"
D.Strings[27412]="%s加入了战斗！"
D.Strings[27413]="中央大门打开了！"
D.Strings[27414]="无尽的痛苦在等待着你！"
D.Strings[27415]="你将要经历我曾经历过的一切！"
D.Strings[27416]="你已经做出了选择。"
D.Strings[27417]="很快，你就将听到主人的召唤。"
D.Strings[27418]="来呀，我的子民！吞噬他们的血肉吧！"
D.Strings[27419]="在我的虫群面前，你的盔甲毫无用处！"
D.Strings[27420]="感受这可怕的热疫吧！"
D.Strings[27421]="啊……啊啊啊！从没有想到……我还能摆脱……他的魔掌……"
D.Strings[27422]="%s开始喷射软泥怪！"
D.Strings[27423]="%s对你施放了变异注射！"
D.Strings[27424]="%s对附近的所有血肉之躯发动了残杀！"
D.Strings[27425]="早上好！"
D.Strings[27426]="极性转换！"
D.Strings[27427]="我能为你做什么吗？"
D.Strings[27428]="为萨鲁法尔而战！"
D.Strings[27429]="在地狱之火中煎熬吧！"
D.Strings[27430]="我们要夺回这里！"
D.Strings[27431]="我们要把这里彻底烧毁！"
D.Strings[27432]="%s传送到了上层平台！"
D.Strings[27433]="%s施放传送后开始引导法术！"
D.Strings[27434]="%s再次发动进攻！"
D.Strings[27435]="死灵能量形成的光环屏蔽了一切治疗法术！"
D.Strings[27436]="光环散去了，又可以治疗了！"
D.Strings[27437]="你好啊！"
D.Strings[27438]="我要重新学习布匹清洁。"
D.Strings[27439]="你不该那么做的！他不喜欢那样。"
D.Strings[27440]="部落的英雄，酋长在召唤你们！"
D.Strings[27441]="鲜血与雷鸣，部落的勇士们！今天，我们要为死去的兄弟姐妹而战！不要悲伤，因为他们都是心怀荣耀的勇者！"
D.Strings[27442]="虽然我们面临着巨大的分歧，但只要我们齐心协力，就一定能消灭敌人！所有对部落的不公正都将被势不可挡的力量碾碎！"
D.Strings[27443]="四方之灵，将你们的祝福赐予部落吧！今天，我们的事业是正义而高尚的！"
D.Strings[27444]="战争的阴云已经迫近，$n。我们和部落都派了轰炸机进入轰炸船和失落希望之谷。你愿意参加这次行动吗？"
D.Strings[27445]="给我一架轰炸机！"
D.Strings[27446]="空气中的魔法能量正在消散……"
D.Strings[27447]="入侵者！是谁闯入了古代王国？"
D.Strings[27448]="小伙子们，咱们动手吧！"
D.Strings[27449]="干得好！我们只能休息一会儿。"
D.Strings[27450]="谢谢你掩护我们回来！我们会一边等待援军，一边守住大门。"
D.Strings[27451]="$n超乎寻常的作战技巧令龙骑士手忙脚乱起来。"
D.Strings[27452]="你战斗起来就像只野兽！"
D.Strings[27453]="这一招你是从哪儿学来的？"
D.Strings[27454]="你准备好参与夺回幽暗城一战了吗，$n？"
D.Strings[27455]="我准备好了，酋长。"
D.Strings[27456]="元素之灵与我们同在，$n。在它们的帮助下，我们可以竭尽全力阻止瓦里玛萨斯和普特雷斯的阴谋得逞！LOK'TAR OGAR！"
D.Strings[27457]="随我到幽暗城门口集合！我们要夺回这座沦陷的城市——为了部落！"
D.Strings[27458]="风之灵，将这曲战歌送到小萨鲁法尔耳畔吧！为所有阵亡的同胞们报仇雪恨！"
D.Strings[27459]="幽暗城的战斗即将打响！吹响战争的号角！部落的勇士们，接受酋长赋予你们的力量吧！"
D.Strings[27460]="哎呀！小声点，$n！怎么？你想把我们害死吗？！$B$B我当然知道你是谁！你的大名早就在联盟中传遍了！$B$B你觉得我的跳跃机器人怎么样啊？她是根据机械侏儒的原理设计的，运行起来非常流畅，是以空气为动力的！"
D.Strings[27461]="哇，哇，哇！小声点，$n。小声点！$B$B<布拉斯朝四周看了看。>$B$B你也不想我们被那些冰棍儿维库人发现吧？$B$B你觉得我的跳跃机器人怎么样啊？这是根据机械侏儒的原理设计的哦。很棒吧，对吗？"
D.Strings[27462]="风之灵，扫清前进的道路！"
D.Strings[27463]="尝尝元素之灵的厉害，恶魔！"
D.Strings[27464]="水之灵，冲走这一切堕落吧！"
D.Strings[27465]="返回伊米海姆，不然跳跃机器人就会散架！"
D.Strings[27466]="我准备好了，布莱恩。我们把钥石拼起来吧。"
D.Strings[27467]="教徒们，回去工作！"
D.Strings[27468]="报告长官！装配完毕，随时可以出发！"
D.Strings[27469]="我的士兵已经准备好了——请下命令吧！"
D.Strings[27470]="欢迎来到我的黑暗王国！"
D.Strings[27471]="你喜欢我的那些恐怖的造物吗？很厉害，不是吗？"
D.Strings[27472]="我们准备好了，长官。"
D.Strings[27473]="指挥官，我们随时可以发动攻击，只等你下达命令！"
D.Strings[27474]="武装完毕，随时待命。"
D.Strings[27475]="我们准备好发动进攻了，长官。"
D.Strings[27476]="请下令吧，长官。"
D.Strings[27477]="真是天真！你们想夺回这座城市？那就来吧，英雄们！你们的灵魂会让我更强大！而你们只能夺回一片废墟！"
D.Strings[27478]="形势严峻，没有捷径可走。如果你的战斗力够强，请掩护我的小队，直到他们做好爬上伊米海姆的准备。他们需要一切可利用的帮助。"
D.Strings[27479]="嗯。我们试试能不能拼好钥石。"
D.Strings[27480]="你好，布莱恩·铜须。我是这座神殿的最后一名守卫者。"
D.Strings[27481]="你当之无愧是一名优秀的探险家，你的心中充满了对知识的渴求。"
D.Strings[27482]="土灵已经将你视为忠实的盟友。"
D.Strings[27483]="在战斗以及寻找钥石的过程中，你和你的同伴都证明了自己。"
D.Strings[27484]="你们的动机是纯洁的。钥石的碎片将得以重新拼合。前往奥杜尔寻找你想要的答案吧，布莱恩·铜须。"
D.Strings[27485]="钥石拼好了！我们成功啦，$n！"
D.Strings[27486]="自信号上虫灾泛滥，我们没法开往诺森德了。"
D.Strings[27487]="谁也不知道存放在奥杜尔的档案中隐藏了什么秘密。我要去那里揭开真相。再次感谢你的帮助，$n。没有你的帮助，我现在还在找那把钥匙呢。"
D.Strings[27488]="我们已经做好了扬帆诺森德的准备，突然发现船上出现了大批害虫。"
D.Strings[27489]="在开往诺森德之前，我们必须解决自信号上的虫害问题。"
D.Strings[27490]="进攻！！！！"
D.Strings[27491]="站起来，小伙子们！"
D.Strings[27492]="有埋伏！"
D.Strings[27493]="维库人进攻了！"
D.Strings[27494]="站起来，小伙子们！前进！前进！"
D.Strings[27495]="哎呀，你长得真难看！不过这并不表示你不会战斗。$B$B我麾下的一支小队很快就要出发啦——加入他们的行列，一起爬上伊米海姆吧！"
D.Strings[27496]="我们已经整装待发，长官。"
D.Strings[27497]="继续前进！"
D.Strings[27498]="快，在我们冲到大门之前，摒住呼吸迅速前进！"
D.Strings[27499]="你很有斗志！愿鲜血与荣耀与你同在，朋友！"
D.Strings[27500]="维库人！"
D.Strings[27501]="拔出武器！"
D.Strings[27502]="浴血奋战的时刻到了！"
D.Strings[27503]="指挥官，士兵们渴望杀戮的快感。"
D.Strings[27504]="我们准备好为荣誉而战了，长官。"
D.Strings[27505]="我们做好了战斗的准备。"
D.Strings[27506]="我们已经整装待发，准备浴血沙场了。长官，请下达命令吧。"
D.Strings[27507]="我们随时准备牺牲。请下令吧！"
D.Strings[27508]="我们准备好与维库人展开激战了。请下令吧，长官。"
D.Strings[27509]="请下令，指挥官。"
D.Strings[27510]="%s唱起歌来。"
D.Strings[27511]="要我为你指引道路吗，年轻人？"
D.Strings[27512]="请带我去冬拥堡垒墓地。"
D.Strings[27513]="请带我去沉降之环墓地。"
D.Strings[27514]="请带我去破碎神殿墓地。"
D.Strings[27515]="请带我去东部火花车间墓地。"
D.Strings[27516]="请带我去西部火花车间墓地。"
D.Strings[27517]="请指引我返回联盟营地。"
D.Strings[27518]="请指引我返回部落营地。"
D.Strings[27519]="呀啊啊啊啊！！！！！"
D.Strings[27520]="我们在这里的行动关系到许多人的性命。你想说什么就快说吧，$c。"
D.Strings[27521]="你带来了最新的战况情报吗，$r？"
D.Strings[27522]="最好的战术是速战速决。谈话也是一样。你想说什么，$r？"
D.Strings[27523]="该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B如果你要去那里的话，我可以将你传送过去。"
D.Strings[27524]="该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B但是你的力量还不够强大，我建议你不要去那里。"
D.Strings[27525]="我能闻到炸弹和火箭里的火药味儿！你也要出去找些乐子吗？"
D.Strings[27526]="有很多声音在对我讲话。"
D.Strings[27527]="我必须服从。"
D.Strings[27528]="你最好赶紧离开，不然你也会被它影响！"
D.Strings[27529]="跟我说说精魂披风图样的事儿吧。"
D.Strings[27530]="我们就快准备好啦。再给我们一点时间，很快就能出发了。"
D.Strings[27531]="准备工作尚未完成。我们暂时还不会离开。"
D.Strings[27532]="它就在我们身边。就在我的脑海里！"
D.Strings[27533]="士兵们都准备好了。我们要让那些维库人流血！"
D.Strings[27534]="萨隆邪铁……里面藏有什么东西！"
D.Strings[27535]="邪铁里藏有东西！就在岩石和泥土里！"
D.Strings[27536]="我在旅途中学会了精魂披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得耐力、法术强度、智力以及法力回复速度的加成。我一直在寻找有资格学习这张图样的人。$B$B打通诺森德所有的普通难度地下城，并获得“诺森德地下城大师”成就的人才有资格学习精魂披风的图纸。"
D.Strings[27537]="我准备好学习精魂披风了。"
D.Strings[27538]="我要离开这里！你能放我出去吗？"
D.Strings[27539]="你听见了吗？它正在你的脑海中低语。"
D.Strings[27540]="走吧，你自由了。快离开这儿！"
D.Strings[27541]="我准备好加入前往伊米海姆的队列了。我们出发吧。"
D.Strings[27542]="我们已经攻占了庭院！朝内部圣殿前进！"
D.Strings[27543]="停下，他们摧毁了升降梯！"
D.Strings[27544]="升降梯有问题，酋长。摔下去的人都难逃一死。"
D.Strings[27545]="我曾去过许多黑暗的地方，学会了死寒披风的图样。$B$B图样可交易，是史诗级的施法者披风，装备后可获得法术强度、急速以及爆击的加成。我一直在寻找有资格学习这张图样的人。$B$B完成诺森德的大部分任务，并获得“诺森德的博学者”成就的人才有资格学习死寒披风的图纸。"
D.Strings[27546]="跟我说说死寒披风图样的事儿吧。"
D.Strings[27547]="重大发现！$n发现了一种新的配方！"
D.Strings[27548]="我来了，主人！"
D.Strings[27549]="我的生命属于你！"
D.Strings[27550]="我准备好学习死寒披风了。"
D.Strings[27551]="我是不会离开的！"
D.Strings[27552]="不！你错了！我脑海中的声音非常美妙！"
D.Strings[27553]="我不想走！我要留在这里！"
D.Strings[27554]="我不要回去。我要去地底找寻我存在的意义！"
D.Strings[27555]="啊哈哈哈哈……你很快就会加入我们的！"
D.Strings[27556]="我要到地底深处去，到主人身边去。我一定要跳下去！"
D.Strings[27557]="你是一位颇为出色的裁缝，因此我可以教你一些特别的图样，比如精魂披风和死寒披风。"
D.Strings[27558]="瓦里玛萨斯召唤出了凋零畸体！"
D.Strings[27559]="天灾之锅剧烈地沸腾起来！"
D.Strings[27560]="有什么东西从锅里冒了出来！"
D.Strings[27561]="三只强大的精英！！"
D.Strings[27562]="一群非精英！"
D.Strings[27563]="天灾之锅还在沸腾……"
D.Strings[27564]="中和剂失效了！$b赶紧倒入液体！"
D.Strings[27565]="中和剂失效了！$b立即倒入液体！！"
D.Strings[27566]="中和剂失效了！"
D.Strings[27567]="天灾之锅中的东西被中和了！"
D.Strings[27568]="他们对我美丽的城市都做了些什么？"
D.Strings[27569]="伟大的空气之灵，请再次倾听我的呼唤！"
D.Strings[27570]="空气之灵已经听到了我的呼唤。飓风会送我们返回地面。现在，跳吧！"
D.Strings[27571]="激活防御设施"
D.Strings[27572]="你！快过来！尽情吃喝一顿吧，为下一次的战斗做好准备。$B$B不许在这里打架！不然我就送你去喂狼。"
D.Strings[27573]="我们攻占了内部圣殿，勇士们！继续前进！"
D.Strings[27574]="参与暴乱的叛徒们唯一的救赎就是痛苦的死去。我的复仇将迅速而决不留情。"
D.Strings[27575]="带路吧，黑暗女王。我们会跟着你的。"
D.Strings[27576]="很好，酋长。皇家区在这边。保持警惕，谁也不知道瓦里玛萨斯和普特雷斯会有什么圈套。"
D.Strings[27577]="背叛的下场就是死亡！"
D.Strings[27578]="你竟敢玷污我的圣殿！用鲜血偿还吧！"
D.Strings[27579]="部落必将赢得胜利！"
D.Strings[27580]="你很快就会和你的主子碰面了——在死了以后。"
D.Strings[27581]="女妖之王对你早有安排！"
D.Strings[27582]="为你可悲的性命乞求吧！"
D.Strings[27583]="求求你，住手。"
D.Strings[27584]="再打我一下试试，你会后悔的！"
D.Strings[27585]="对不起。我会努力干活的。"
D.Strings[27586]="主人很快就会召我回去的！"
D.Strings[27587]="我要把你的肉一片片地割下来！"
D.Strings[27588]="我受够你们的胡言乱语了。快干活！"
D.Strings[27589]="根本没有什么低语声。都是你自己想象出来的。回去干活！"
D.Strings[27590]="巫妖王需要更多的萨隆邪铁。快点干活，蠢货。不然就送你们去喂怪物！"
D.Strings[27591]="把你们的口粮减半或许能刺激你们挖得快点儿？"
D.Strings[27592]="瓦格里工头，如果再有奴隶偷懒，就送他去喂怪物！"
D.Strings[27593]="矿井里出现了入侵者！解决他们！"
D.Strings[27594]="我看见你了，小家伙。到这儿来，我要和你谈谈。"
D.Strings[27595]="别相信这怪物的谎言。快回去干活！"
D.Strings[27596]="停！我感觉到了黑暗的魔法。是恶魔的法术……准备战斗！"
D.Strings[27597]="你真聪明……"
D.Strings[27598]="我在这里下吧！"
D.Strings[27599]="欢迎来到肯瑞托议会的故乡。"
D.Strings[27600]="我的兄弟们都饿了。你们的灵魂一定很合他们的胃口。"
D.Strings[27601]="我把《奥术魔法的学派 - 精通》弄丢了。你能再给我一本吗？"
D.Strings[27602]="我下去啦。祝你们好运！"
D.Strings[27603]="谢谢你掩护我们！"
D.Strings[27604]="顺利抵达目的地——这里就是本次侦察任务的目标地点。"
D.Strings[27605]="渗透行动开始。"
D.Strings[27606]="我跳啦！"
D.Strings[27607]="我们战场上见吧。"
D.Strings[27608]="我会为你杀死一名敌人的。"
D.Strings[27609]="%s发出奇怪的声音，你觉得那是笑声。"
D.Strings[27610]="我要把你碎尸万断！"
D.Strings[27611]="这之后，一切都将灭亡！"
D.Strings[27612]="你们想见识真正的力量？那我就让你们如愿以偿！"
D.Strings[27613]="剁碎他们！刺穿他们！"
D.Strings[27614]="来跟我的大朋友问声好吧！"
D.Strings[27615]="真快呀！"
D.Strings[27616]="谁需要神？我们自己就是神！"
D.Strings[27617]="我提醒过你了！"
D.Strings[27618]="再强大的力量……也有衰落的一天。"
D.Strings[27619]="当阻挡者卡诺克出现时，你周围的空气发出了爆裂声！"
D.Strings[27620]="你没有获胜的希望！"
D.Strings[27621]="你以为自己能从我手里夺得这座壁垒的控制权吗？"
D.Strings[27622]="我觉得你做不到。傲慢的家伙，你战败之后，我会将你的尸体用尖刺钉起来，为其他“英雄”做个示范！"
D.Strings[27623]="请送我去冬拥湖。"
D.Strings[27624]="仅此而已？恶魔，你没有别的东西可扔了吗？"
D.Strings[27625]="你只能在冰冠冰川、索拉查盆地和风暴峭壁的上空飞行。"
D.Strings[27626]="冒险者们，牢门的力量开始减弱了！"
D.Strings[27627]="牢门的封印力量只剩一半了！你们必须坚持住！"
D.Strings[27628]="牢门的封印即将崩溃！如果蓝龙军团攻破大门，一切都完了！"
D.Strings[27629]="够了，麦克尔。城里的气氛越来越恐慌，我们的生意已经够惨淡的了。就算是一个铜板的小买卖也不应该错过。"
D.Strings[27630]="你好，朋友。我能为你做什么吗？"
D.Strings[27631]="嘿，等一等。你没有属于自己的飞行坐骑诶。$B$B如果出行不便的话，恐怕你没有办法帮助其他的地精了。他们付钱给我，让我将旧坐骑借给你这样的人使用——免费使用哦。$B$B怎么样？"
D.Strings[27632]="我们来了！做好准备吧！"
D.Strings[27633]="懦夫！你以为投掷小石块就能阻止部落的酋长吗？我会让你见识到元素的真正力量！"
D.Strings[27634]="好吧。"
D.Strings[27635]="前面不远就是皇家区了，酋长。"
D.Strings[27636]="摧毁大厅！快！"
D.Strings[27637]="%s不情愿地点了点头。"
D.Strings[27638]="好吧，你说得对。"
D.Strings[27639]="士兵的工作非常重要。人民的安全更加重要，马尔，如果你还想让顾客们多活一天的话。"
D.Strings[27640]="别太担心。直到我下班的时候，这里还没有发现一颗被污染的谷物。"
D.Strings[27641]="感谢圣光。"
D.Strings[27642]="伟大的大地之灵，请在紧急关头帮助我们吧！"
D.Strings[27643]="你需要什么帮助？"
D.Strings[27644]="我已经找到了诺甘农钥石的线索，有了它就能进入奥杜尔的档案室；但是泰坦将钥石分成了两块并分别藏了起来。$B$B钥石的外壳藏在北部海滩的创世者图书馆里，就在奥杜尔以南。首先，你要从图书馆守护者那里获得访问磁盘的碎片。"
D.Strings[27645]="时间到了。愿圣光赐予我们力量吧。"
D.Strings[27646]="我乞求您的宽恕，主人！我一定会亲手解决入侵者的！"
D.Strings[27647]="接受你的未来吧——命运什么都没给你留下……"
D.Strings[27648]="说到财宝，永远不要轻视翻捡别人的垃圾的行为。偷来的财宝更加珍贵，是吗？但是免费的东西就是好的，无论你采用什么方式！"
D.Strings[27649]="不速之客！你们以为自己能偷偷地溜进我的王国吗？"
D.Strings[27650]="走吧！快！"
D.Strings[27651]="我必须承认……我早已预知你们的到来。希望你们能找到安息地……适合你们的安息地。"
D.Strings[27652]="人们经常置疑我身为三指大盗的本事。其实我靠的是手腕的灵活性……一旦失手，你应该立即制服他们，这同样要依赖手腕的力量。$B$B灵巧的双手比稳定的收入更加宝贵，你明白吗？"
D.Strings[27653]="我一点都不担心巫妖王。我见过无数的大人物沉沉浮浮，他们喜欢把事情搞得一团糟。但是每当人民站起来反抗时，他们很快就会偃旗息鼓，沦为历史课本上的教程。巫妖王也不会例外。"
D.Strings[27654]="我们上次交手时，你占尽了圣地的优势。但如今，你会发现我们的境遇已经发生了……逆转。"
D.Strings[27655]="或许吧。就算我的双脚没有踏在圣地上，也能用灰烬使者摧毁你的徽记。"
D.Strings[27656]="徽记……那是你残存的最后一丝人性。我要在你彻底丧失人性之前亲自摧毁它。我相信……"
D.Strings[27657]="你似乎过于自信了。你不如想想上次我们交手的结果。"
D.Strings[27658]="别虚张声势了，你毕竟是一名圣骑士。你对于救赎的痴迷已经到了不可救药的地步。"
D.Strings[27659]="你想要“挽救”我这个任性的孩子，不愿意放弃人道救赎的唯一机会，因此你只会死得更快！"
D.Strings[27660]="你心中只剩下往昔的阴影，无可救赎了！"
D.Strings[27661]="饥饿驱使着那些以失落灵魂为食的阴影。"
D.Strings[27662]="凝视虚空吧。它们就居住在其中。"
D.Strings[27663]="它们是寒风中的低语。"
D.Strings[27664]="它们的阴影将永远地笼罩着大地。"
D.Strings[27665]="它们畅饮着你们的恐惧：这是生命的鲜血。"
D.Strings[27666]="每倒下一个，会有更多的阴影接替它的位置。"
D.Strings[27667]="它们无所谓死，亦无所谓生。它们游离于生命的循环之外。"
D.Strings[27668]="长久以来……我们不知疲倦地谋划……不应该落得这样的结局……"
D.Strings[27669]="再给我一点时间……主人就在附近……"
D.Strings[27670]="强大的力量！凡人们，你们感受不到吗？别愚蠢啦，加入我们吧！"
D.Strings[27671]="我不会失败！再也不会！"
D.Strings[27672]="我快要……坚持不住了……"
D.Strings[27673]="大人，虽然我们在与无面者战斗的过程中损失了不少人手，但是我们成功地从纳扎纳克夺回了徽记。"
D.Strings[27674]="保持冷静，听我的指挥。"
D.Strings[27675]="心血……付诸一旦……"
D.Strings[27676]="你真让我失望，瓦里玛萨斯！"
D.Strings[27677]="它来了。做好准备。"
D.Strings[27678]="不对劲……我感觉到黑暗的气息。"
D.Strings[27679]="巫妖王就在这里。愿圣光指引我们的剑刃吧。"
D.Strings[27680]="囚犯们绝望地啜泣着，等待末日的来临。"
D.Strings[27681]="那些嘲笑我的战袍的人都是蠢货。$B$B这件衣服所用的旧钢都来自一个远古的学习之地！"
D.Strings[27682]="这次我不会死那么快了！"
D.Strings[27683]="勇士们！我将派出得到我祝福的孩子，帮助你们进行战斗！"
D.Strings[27684]="我只是尽了我应尽的义务，兄长。你让我别无选择。"
D.Strings[27685]="魔枢战争就此结束了。"
D.Strings[27686]="这个决定令我的心灵深处痛楚不已，但这生灵涂炭与天地崩裂的局面也终于得到了休止。无论玛里苟斯犯过什么大错，我都会为他的死默哀。他曾是一位高贵的守护者。今天，世界上最强大的守护者之一，就这样逝去了。"
D.Strings[27687]="红龙军团将会担负起修复世界创伤的责任与义务。回去吧，和你的同伴们一起回去，好好休息。明天，你们还要应对新的挑战，你们必须时刻为此做好准备。生命……仍要继续。"
D.Strings[27688]="等等，我没有激活宝珠啊……？"
D.Strings[27689]="我突然觉得很好笑。呃？！"
D.Strings[27690]="好吧，谁朝我扔了宝珠？"
D.Strings[27691]="我不是哨兵！"
D.Strings[27692]="你搞错了。我是黑暗压制者！"
D.Strings[27693]="是误会啊。我是被陷害的。别把我扔下去！"
D.Strings[27694]="随意抛出了|Hitem:44430|h|cff0070dd[达拉然泰坦神铁徽记]|r|h。"
D.Strings[27695]="你竟敢干预我们的事！"
D.Strings[27696]="没用的东西。"
D.Strings[27697]="你的时间流被彻底摧毁了！"
D.Strings[27698]="我的生命……结束了……"
D.Strings[27699]="部落夺回了幽暗城！LOK'TAR！"
D.Strings[27700]="你救了我的性命，请接收我的谢意。我必须立即向长官汇报这里发生的事件。"
D.Strings[27701]="黑暗女王，来吧！你曾为登上王座倾尽心力、浴血奋战。现在，皇家区属于你了！"
D.Strings[27702]="酋长，这就是与部落为敌的下场。现在，该去对付普特雷斯那个恶棍了。"
D.Strings[27703]="我们会的，希尔瓦娜斯……"
D.Strings[27704]="联盟的号角声？保持警惕！"
D.Strings[27705]="达拉然北部的再来一杯应该能满足你的需求。"
D.Strings[27706]="达拉然南部的好战的秘法师应该能满足你的需求。"
D.Strings[27707]="达拉然东部的猎人用品店出售枪支、弓弩、弹药等商品。"
D.Strings[27708]="达拉然东南部的神兵利器出售各类近战武器。"
D.Strings[27709]="如果能挣脱这些锁链，总有一天我会回来亲手杀了你。"
D.Strings[27710]="击败你是我莫大的享受。"
D.Strings[27711]="达拉然西部的耶比托·乔巴斯的奇妙玩具店会出售这类物品。"
D.Strings[27712]="我宁愿为黑暗领主亚历山大效劳，也不要待在你身边做只可怜的宠物。"
D.Strings[27713]="我听说，如果将你这样的家伙扔进火里，你就会发出地狱犬一般的尖叫声。"
D.Strings[27714]="你过于沉迷我们的魔法。我要亲手夺走你的灵魂！"
D.Strings[27715]="所有的录音带，我都倒着放。除了“箭头小子”乐队的。"
D.Strings[27716]="就算你逃到扭曲虚空最寒冷的边缘，也躲不过我复仇的怒火。"
D.Strings[27717]="我只为萨格拉斯效劳！总有一天你也会臣服在他的权威之下，凡人……"
D.Strings[27718]="硬币正面朝上！"
D.Strings[27719]="硬币反面朝上！"
D.Strings[27720]="达拉然东南部的荣耀杂货店中，“红发”杰克·芬德出售各种杂货。$B$B如果你想购买特殊物品，就去魔法商业区吧。那里的店铺都设有供给商贩。"
D.Strings[27721]="任务完成！我在这里的工作结束了。"
D.Strings[27722]="艾美的货车通常停在达拉然北部，就在达拉然银行附近。"
D.Strings[27723]="魔法动物店位于达拉然东北部。那里出售宠物用品和珍稀坐骑，并提供兽栏服务。"
D.Strings[27724]="达拉然西部的巫术姐妹出售各种魔法材料。$B$B不过你要小心莫尔海德的那只黑猫……"
D.Strings[27725]="噢，不！冒险者们，刚刚发生了一件可怕的事！永恒之龙抓走了我的一位同伴，他们正在对他做一些可怕的事！$B$B保护阿尔萨斯还是你们的首要任务。但是如果你们行动够快的话，或许还有机会挽救一位时光守护者！"
D.Strings[27726]="达拉然南部的荣耀杂货店出售各种杂货。"
D.Strings[27727]="苹果树的水果货车通常停在达拉然的西南部，就在银色领地附近。"
D.Strings[27728]="你可以在达拉然东南部找到爱丽丝·普里洛斯小姐的花摊。"
D.Strings[27729]="冒险者可以在银色领地或者夺日者圣殿为自己立下的功绩领取公正的奖励。"
D.Strings[27730]="达拉然北部的坦克用品店是城里最受欢迎的板甲和盾牌商店。"
D.Strings[27731]="达拉然南部的摩尔珍品店有好几位商贩，他们出售各类饰品、圣物、家传宝物和副手武器。"
D.Strings[27732]="达拉然南部的兰格鲁的皮加锁应该能满足你的需求。"
D.Strings[27733]="冒险者，快！时间的守护者坚持不了多久的！"
D.Strings[27734]="我几乎感受不到时间的守护者的讯息！他的时间流正在急速消逝！"
D.Strings[27735]="达拉然西部的命运丝线是城里最受欢迎的裁缝物品和布甲商店。"
D.Strings[27736]="你需要什么类型的武器？"
D.Strings[27737]="近战武器"
D.Strings[27738]="远程和投掷武器"
D.Strings[27739]="法杖和魔杖"
D.Strings[27740]="你需要什么类型的护甲？"
D.Strings[27741]="布甲"
D.Strings[27742]="提里奥倒下了！用你们的生命保护他！"
D.Strings[27743]="皮甲"
D.Strings[27744]="锁甲"
D.Strings[27745]="板甲"
D.Strings[27746]="我离开得太久了。好几位伟大的英雄为此付出了生命的代价。而你这种人渣，还有这个邪恶的巫女却还在世上，为所欲为。"
D.Strings[27747]="盾牌"
D.Strings[27748]="匡扶正义的时刻到了。我要摧毁这个满是凶手和窃贼的王国！普特雷斯只是个开始。好戏刚刚开始！"
D.Strings[27749]="啊啊啊！！！"
D.Strings[27750]="你是来帮忙的吗？"
D.Strings[27751]="这一刻我等了很久，萨尔。每当我被扔进你那该死的兽人竞技场……每当我杀死一只和你一样可憎的绿皮怪物……我都只有一个念头。"
D.Strings[27752]="你……会为此付出代价！杀光他们！"
D.Strings[27753]="如果没有你和你那扭曲的部落，世界将多么美好……酋长，你们要完蛋了。"
D.Strings[27754]="进攻！为了暴风城！为了伯瓦尔！为了联盟！"
D.Strings[27755]="你要找哪种商贩？"
D.Strings[27756]="护甲"
D.Strings[27757]="裁缝供应"
D.Strings[27758]="正义军需官"
D.Strings[27759]="鲜花"
D.Strings[27760]="水果"
D.Strings[27761]="快穿过传送门！他坚持不了多久的。"
D.Strings[27762]="振作起来，北伐军战士。你们并非孤军奋战！"
D.Strings[27763]="不，瓦里安！住手！"
D.Strings[27764]="我们打扰了你们的聚会，请不要介意。我还带来了一些老朋友！"
D.Strings[27765]="事情不该变成这样的……"
D.Strings[27766]="珠宝"
D.Strings[27767]="宠物和特殊坐骑"
D.Strings[27768]="馅饼和蛋糕"
D.Strings[27769]="施法和魔法材料"
D.Strings[27770]="玩具"
D.Strings[27771]="商业材料"
D.Strings[27772]="武器"
D.Strings[27773]="看来提里奥的确对巫妖王造成了一定伤害。可惜我们没能杀死他……"
D.Strings[27774]="美酒和奶酪"
D.Strings[27775]="巫妖王受了重伤。我们应该留下来杀死他。"
D.Strings[27776]="耐心点……我们会有机会干掉巫妖王的。这次，提里奥欠我们一份情。对此我已经很满足了。"
D.Strings[27777]="地精工程学的奥秘是，教你学会如何让爆炸物在指定的地点按时引爆，而不是确保产品不会爆炸。"
D.Strings[27778]="结局仿佛只是开始……"
D.Strings[27779]="我们追寻的梦想破灭了。我的双亲……还有奥格瑞姆……他们的期望和梦想……破灭了……"
D.Strings[27780]="老朋友，如果你在这里就好了。你该知道要怎么做。"
D.Strings[27781]="我知道他会干什么。"
D.Strings[27782]="他会对你说：萨尔，领导你的人民。"
D.Strings[27783]="让我们回家吧，老朋友。"
D.Strings[27784]="老朋友，见到你真高兴。对小萨鲁法尔的遭遇，我很抱歉。"
D.Strings[27785]="%s过来抓起一些东西送进嘴里。"
D.Strings[27786]="我是见证者夏拉托尔。"
D.Strings[27787]="你愿意听我讲个故事吗？"
D.Strings[27788]="故事？"
D.Strings[27789]="嗯，我读到过你的故事，$n。"
D.Strings[27790]="做个自我介绍吧，夏拉托尔。你为什么被称为见证者？"
D.Strings[27791]="我是最早一批，也是最后一代接受过塞纳留斯教诲的牛头人德鲁伊之一。那时候世界还很年轻，没有燃烧军团，大灾变也还没有发生。一切都是那么宁静。$B$B当我的同胞学习猎杀巨兽时，我却在搜寻历史故事。对知识的渴求令我沉湎于德鲁伊的魔法。有段时间，我满足于与树木、岩石和野兽交谈，倾听它们的故事。$B$B后来，塞纳留斯不再露面，我的同胞渐渐遗忘了他的教诲，但是我忘不了，我还想了解更多关于这个世界的知识。$B$B于是我告别族人，离开家乡去远方流浪。"
D.Strings[27792]="我穷尽一生寻找知识，目睹了许多奇迹，遇见了各种各样神秘的种族，这些经历远远超越了所有的先辈。我的足迹遍布远古的卡利姆多大陆，直到再也找不到新鲜的事物，直到地平线看不见新的陆地。$B$B但是……就在这次旅途即将划上句号时，我觉得自己还是对很多东西缺乏了解。我深知这将成为永远的遗憾，禁不住放声痛哭。$B$B自然生命总有消亡的一天，我跌到在地。这时，他们找到了我。"
D.Strings[27793]="他们？"
D.Strings[27794]="青铜龙族。他们将我从死亡的边缘拯救回来，并带我去见时光之王诺兹多姆。诺兹多姆说，他们一直在关注我的动向，并希望我能够继续追寻知识。他赐我永生并任命我为观察者，担当起艾泽拉斯历史见证者的角色。$B$B我是见证者夏拉托尔，我的任务是维系艾泽拉斯的真实历史，避免它被遗忘。"
D.Strings[27795]="这里是唐卡洛营地，我的兄弟掌管着这个村落，但是……我不记得你。"
D.Strings[27796]="你的存在差点就被抹杀了。$n勇敢地与北风作战，保护了关于你的历史。"
D.Strings[27797]="北风？它还在祸害我的族人？"
D.Strings[27798]="雷蹄，你与北风的战斗已经过去了数百年。你重创了它，这些年来它一直都很沉寂。"
D.Strings[27799]="但是北风不甘心就此落败。相反，它一直在积聚力量，等待时机，意图摧毁你的历史和这座村庄。"
D.Strings[27800]="北风让它的爪牙扭曲了这个地区的历史，意图改变牦牛人口口相传的故事并消灭先祖的亡魂。"
D.Strings[27801]="黑暗主宰西塔利克斯从东南方冲进了瓦哈拉斯！"
D.Strings[27802]="要不是$n和我循着北风扭曲历史的线索，找到了破坏的源头：你与北风的那场远古之战，它们的阴谋已经得逞了。"
D.Strings[27803]="在我的帮助下，$n及时返回了那场战斗的时间流，维护了历史的真相。北风的命运已经被封印起来，你的故事也得以恢复正常。"
D.Strings[27804]="我代表村民谢谢你们，虽然你们的事迹不会为大多数人所知。"
D.Strings[27805]="齐格莉德·冰魂在瓦哈拉斯上空盘旋，她是来复仇的！"
D.Strings[27806]="南方飘来的气味预示了卡纳基的到来！"
D.Strings[27807]="我不能待在这里。我必须返回自己的陵墓。当我与长者的灵魂重聚时，会向大家讲诉你的故事。"
D.Strings[27808]="巴纳霍格领主出现在东南方的高台上！"
D.Strings[27809]="萨杜瓦尔王子在毫无征兆的情况下，如幻影般出现在瓦哈拉斯！"
D.Strings[27810]="安息吧，勇士。"
D.Strings[27811]="%s扬起利爪，朝你挥来！"
D.Strings[27812]="哇！你是来自未来的我！嘿嘿，装备强力了不少嘛。真是酷毙了！"
D.Strings[27813]="只有时间能证明一切……"
D.Strings[27814]="这里发生了什么事，阿莱克丝塔萨？"
D.Strings[27815]="欢迎来到奇妙玩具店！$B$B请随意看看。我们出售许多奇妙的玩具，老少咸宜！"
D.Strings[27816]="我弄丢了达拉然泰坦神铁徽记。能再给我一枚吗？"
D.Strings[27817]="永恒之龙来了！我必须确保沙漏的安全。你能帮帮我吗？"
D.Strings[27818]="这件装备看上去不错啊，但是你就不能穿得更好一点吗？难道你都不去团队副本的么？"
D.Strings[27819]="嗯，冰冠冰川的局势怎么样啦？"
D.Strings[27820]="克罗米说如果我不能完成任务，我就会从历史上消失。如果我消失了，那么你也就不存在了！"
D.Strings[27821]="我似乎不够强力啊。"
D.Strings[27822]="这事儿完了之后我很可能会借酒消愁。"
D.Strings[27823]="你最好告诉我，我们总共需要面对多少个敌人。你还记得吧？"
D.Strings[27824]="我想说的是，如果我们能活下来，我一定能比你做得更好。我说这话可没有冒犯的意思。"
D.Strings[27825]="等等！既然你来到这里，那就是说将来我也会扮演你现在的角色，再回来这里来帮助我自己？天哪，这分明是一个死循环啊？！"
D.Strings[27826]="见鬼！诺兹多姆就在那里！"
D.Strings[27827]="我感觉自己正在脱离时间流。谢谢你……"
D.Strings[27828]="对不起，我坚持不住了。希望你不会就此消失……"
D.Strings[27829]="你快抓不住了！"
D.Strings[27830]="复苏的时刻还没有到来，谁敢提前惊醒我？！"
D.Strings[27831]="你们无法与我匹敌！"
D.Strings[27832]="你们不应该插手的……"
D.Strings[27833]="我注定要为巫妖王效劳！"
D.Strings[27834]="谁也别想阻止我！"
D.Strings[27835]="蠢货，放下武器……已经太迟了！"
D.Strings[27836]="来吧，成为我的仆从吧。向我效忠，如同我对巫妖王效忠一样！"
D.Strings[27837]="很快……很快……"
D.Strings[27838]="蠢货！别再打搅我休息！"
D.Strings[27839]="躲开了利爪攻击！"
D.Strings[27840]="致命打击未能命中！继续侦查！"
D.Strings[27841]="地穴卫士的尸体上爬出了死尸甲虫！"
D.Strings[27842]="不论付出怎样的代价，我们都会避免再次与部落开战！"
D.Strings[27843]="普罗德摩尔女士，我准备好前往奥格瑞玛了。请开启传送门。"
D.Strings[27844]="千万不要激怒部落，$n。酋长已经同意与我们坦城相见。"
D.Strings[27845]="萨菲隆缓缓升空！"
D.Strings[27846]="萨菲隆再次发动了攻击！"
D.Strings[27847]="克尔苏加德发动了攻击！"
D.Strings[27848]="寒冰皇冠卫士加入了战斗！"
D.Strings[27849]="光环的力量开始减弱了！"
D.Strings[27850]="这辆载具似乎也曾风光过。"
D.Strings[27851]="欢迎！"
D.Strings[27852]="欢迎！请随便看看。"
D.Strings[27853]="你需要什么，可以直接告诉我，$c。"
D.Strings[27854]="你好。我能帮上什么忙吗？"
D.Strings[27855]="有什么要修理的吗，$r？"
D.Strings[27856]="%s发出尖叫声，身体痛苦地扭曲着。他张开大嘴，一口咬住了你！"
D.Strings[27857]="冬拥湖争夺战将在1小时后开始！"
D.Strings[27858]="为了伯瓦尔！为了联盟！"
D.Strings[27859]="冬拥湖争夺战将在15分钟后开始！"
D.Strings[27860]="冬拥湖争夺战将在5分钟后开始！赶快做好战斗的准备吧！"
D.Strings[27861]="我们已经损失了好几名优秀的同胞。我开始怀疑，这里是否值得我们如此关注。"
D.Strings[27862]="你好，我的$r朋友。你的光临令我不胜荣幸。$B$B我能帮你什么忙吗？"
D.Strings[27863]="很累……但是很有趣。"
D.Strings[27864]="立即返回第一军团前线营地。"
D.Strings[27865]="您是来给士兵们训话的吗，长官？"
D.Strings[27866]="很高兴再次见到你，$n。"
D.Strings[27867]="欢迎$n，龙族的朋友。"
D.Strings[27868]="你能与我们同在，是我们的荣幸，$n。"
D.Strings[27869]="请随意在龙眠神殿中休息，$n。"
D.Strings[27870]="库尔迪拉……这听上去有些诡异，但是我最近经常看见一个孩子的魂魄。米斯希尔萨·阿奈尔……你听过这个名字吗？"
D.Strings[27871]="做好战斗的准备，$n。等部队全部就位之后，我们就要开始进攻了！"
D.Strings[27872]="看来这场高强度的战斗终于让你体力不支了，$n。放心吧，我不会泄漏你的小秘密的——省得别人认为你疯了。$B$B休息一下吧。这对你有好处。"
D.Strings[27873]="伟大的红龙女王，我弄丢了聚焦之虹的钥匙。能帮我找回来吗？"
D.Strings[27874]="冬拥湖争夺战将在5分钟后开始！"
D.Strings[27875]="报告，陛下！可以开始进攻了！"
D.Strings[27876]="伟大的红龙女王，我弄丢了英雄聚焦之虹的钥匙。能帮我找回来吗？"
D.Strings[27877]="最后的决战即将开始，$n。保持警惕！"
D.Strings[27878]="冬拥湖战场需要援军！我已经在银色领地开启了一道通往冬拥湖的传送门。"
D.Strings[27879]="当然可以，不过以后请小心一些。"
D.Strings[27880]="冬拥湖战场需要援军！我已经在夺日者圣殿开启了一道通往冬拥湖的传送门。"
D.Strings[27881]="我们取得了冬拥湖战场的胜利！要塞归我们了！"
D.Strings[27882]="联盟的英雄们，国王在召唤！随我攻入下水道的入口吧！"
D.Strings[27883]="很快我们就会进入这个被诅咒的地方，清除一切邪恶！"
D.Strings[27884]="聚焦之虹发出低沉的嗡嗡声，积蓄着不可思议的强大力量！"
D.Strings[27885]="用钥匙打开聚焦之虹。"
D.Strings[27886]="救赎的时刻即将来临！做好准备！"
D.Strings[27887]="凡人，好好保护自己；我们不想失去你这样宝贵的盟友。"
D.Strings[27888]="前进！攻打幽暗城！英雄们，接受国王的祝福吧！跟着我！为联盟的荣耀而战！"
D.Strings[27889]="保护好自己，$n。"
D.Strings[27890]="我们会继续守护这片土地，$n，希望你能平安归来。"
D.Strings[27891]="好好保护自己，$n。如果让我看见你曝尸荒野，我大概会停留片刻向你致哀的。"
D.Strings[27892]="好好活着，$n。"
D.Strings[27893]="$n，你拥有振奋人心的力量。"
D.Strings[27894]="保重自己，$n。你值得拥有更美好的结局。"
D.Strings[27895]="前进，兄弟姐妹们！命运在等待！"
D.Strings[27896]="很高兴看到你还活着，$n。"
D.Strings[27897]="我们即将进入这邪恶的深渊！保持警惕！吉安娜，赐予我们力量！"
D.Strings[27898]="怎么回事？！稳住阵脚！别让敌人得逞！"
D.Strings[27899]="$n！是你！"
D.Strings[27900]="你没事我们就放心啦，$n。"
D.Strings[27901]="你是北伐军的骄傲，$n！"
D.Strings[27902]="$n！你依然是称霸沙场的勇者吗？"
D.Strings[27903]="我们在这里的军事行动少不了你的帮助，$n。"
D.Strings[27904]="遵命，陛下！"
D.Strings[27905]="能认识你这样杰出的$c，真是我的荣幸。"
D.Strings[27906]="$n，你的精神鼓舞着我们。"
D.Strings[27907]="$n是一个好榜样。"
D.Strings[27908]="我敢说，再也找不到比$n更出色的人了。"
D.Strings[27909]="$n，见到你真是太好啦。真的。"
D.Strings[27910]="$n！啊，见到你真是太好啦。你还是很忙吗？"
D.Strings[27911]="欢迎你，龙族的朋友和盟友。请在大厅好好休息吧。"
D.Strings[27912]="啊，是你，$n！欢迎来到我们的圣殿。在这里好好休息一下，这是你应得的权利。"
D.Strings[27913]="复活吧，辛达苟萨！带领霜巢巨龙投入战斗！"
D.Strings[27914]="下水道巨鳄垂涎欲滴地盯着你。"
D.Strings[27915]="你瞧瞧我们俩，瞧瞧。失业，穷困潦倒，整天躲在下水道这家以食腐鸟命名的破旅店借酒浇愁！"
D.Strings[27916]="是啊，我也很厌倦目前的生活。"
D.Strings[27917]="更要命的是，我居然还和你搅和在一起！就是你害我丢了沙塔斯城的工作！"
D.Strings[27918]="你这该死的酒鬼！分明是你的错，别怪到我头上。我只所以会失业，还不是因为你把事情搞砸了！我真是倒霉！"
D.Strings[27919]="是我把事情搞砸的？！是我吗？！是因为你无能！我们之所以这么落魄，都是拜你所赐！"
D.Strings[27920]="你给我闭嘴，亚达尔。你已经抱怨了好几个月，烦不烦啊。不管怎么样，我们现在自由啦！你想想，我们再也不用当差，不用面对政治纷争，乐得消遥自在！"
D.Strings[27921]="是啊，我们背井离乡，身无分文，孤零零地呆在这片亡灵肆虐的极北荒地。"
D.Strings[27922]="或许吧，但是我们很有机会出名啊！你想想，我们在沙塔斯城的时候是多么受欢迎啊，我们是艾泽拉斯的救星，是天灾军团的克星！"
D.Strings[27923]="呃……你说的也有一定道理。再来一杯吧。"
D.Strings[27924]="艾斯瑞克，我又想起了为什么我至今还能容忍你的原因。"
D.Strings[27925]="%s冷笑了一声。"
D.Strings[27926]="我和你打了几十年的交道，听够了你天花乱坠的大话。而在这片萧条的冰原上，我是你唯一认识的人。"
D.Strings[27927]="我准备好进入风暴峭壁了。"
D.Strings[27928]="我真应该让你烂死在这个下水道里。"
D.Strings[27929]="嗯，我知道你会这么想。"
D.Strings[27930]="容许你的存在简直侮辱了我的信仰。"
D.Strings[27931]="嗯，是啊。"
D.Strings[27932]="你比我差劲多了。"
D.Strings[27933]="是啊，我是一只低级的爬虫。"
D.Strings[27934]="你是一条蛇。"
D.Strings[27935]="好吧，如果你更喜欢蛇的话，那我就是一条蛇。"
D.Strings[27936]="别再附和我说的话！"
D.Strings[27937]="嗯嗯，你说得对。这是一种可怕的行为。"
D.Strings[27938]="獐头鼠目。"
D.Strings[27939]="目中无人。"
D.Strings[27940]="人穷志短。"
D.Strings[27941]="你才人穷志短呢？！玩文字接龙的时候干嘛提这个……啊。"
D.Strings[27942]="%s竖起一根手指。"
D.Strings[27943]="呃……到哪个字了？“短”？"
D.Strings[27944]="短……短吃少穿。"
D.Strings[27945]="$n，等女王的事情完结之后，你必须和我谈一谈。"
D.Strings[27946]="好啦。现在，你可以打开聚焦之虹了。"
D.Strings[27947]="我·是·机器人。"
D.Strings[27948]="操作错误。密码错误：.- .- .-"
D.Strings[27949]="<女王的伴侣对你点了点头。>"
D.Strings[27950]="你的请求已被驳回，请等候下次通知。关掉引擎，下次行动最好当心点！"
D.Strings[27951]="你执行过很多次轰炸任务了，但是表现得非常一般啊。你最好当心点，不然我就吊销你的飞行执照……"
D.Strings[27952]="阿尔萨斯，残存在你心中的人性令你止步不前。"
D.Strings[27953]="$n，繁忙的航程是吧？在返回战场之前，你最好先喘口气。"
D.Strings[27954]="摒弃你的人性吧，这样你就再也不会流血了！"
D.Strings[27955]="阿尔萨斯，别担心。很快你就不再需要那颗心了。"
D.Strings[27956]="我刚得到命令，决定撤消你的飞行资格，$n。稍后再来找我吧，我们会让你重返轰炸机的。"
D.Strings[27957]="你的体内流淌着人类的鲜血，这只会令你受伤。摈弃所有凡人的情感吧！"
D.Strings[27958]="折磨你的痛苦很快就会消失了……你再也不会因此困扰了！"
D.Strings[27959]="你轰炸起敌人来还真厉害，但是你自己也被炸得够呛啊。这听上去很好笑，不过你最好当心点，不然我就不给你轰炸机了……"
D.Strings[27960]="老实说，看你轰炸真是有趣！你肯定开过不少轰炸机吧！"
D.Strings[27961]="我终于追上你了，阿尔萨斯。"
D.Strings[27962]="大药剂师普特雷斯释放了充血的凋零虫！"
D.Strings[27963]="我要参加对抗巨龙的战斗。能给我一只雄鹰吗，弗亚林？"
D.Strings[27964]="当心，$n。你的教徒长袍呢？"
D.Strings[27965]="给。准备好了吗？一旦我们开始行动，就不能回头了。"
D.Strings[27966]="我准备好了，大领主。"
D.Strings[27967]="欢迎。"
D.Strings[27968]="这些畸形的野兽挡不住联盟！普特雷斯，等着瞧吧！"
D.Strings[27969]="士兵们，集合！保卫大厅！"
D.Strings[27970]="究竟发生了什么事？到处都是尸体……恶臭熏天……"
D.Strings[27971]="是部落。看这种情形，他们的军队应该，就在附近。"
D.Strings[27972]="保持警惕。我们不知道前面会有怎样的恐怖。"
D.Strings[27973]="奴仆们，阻止他们！"
D.Strings[27974]="杀死他们！不能让他们干扰我的行动！"
D.Strings[27975]="主厅在这个方向！我们走！"
D.Strings[27976]="你无处可逃了，怪物！"
D.Strings[27977]="我不会束手就擒！我做了这么多的努力！这些年来……我……我需要更多的能量！"
D.Strings[27978]="凝视深渊吧，它将吞噬你们的灵魂！"
D.Strings[27979]="力量在我体内流淌！我能看见……一切！"
D.Strings[27980]="品尝更多的痛苦吧！"
D.Strings[27981]="你们嬴不了我的造物！"
D.Strings[27982]="欢迎来到魔术旅馆，$c。祝你愉快。"
D.Strings[27983]="欢迎来到咒语和乌鸦旅店，$r。$B$B你最好当心点。纳莉萨不喜欢擦拭地板上的血迹。"
D.Strings[27984]="重获自由的始祖龙振翅飞走了！"
D.Strings[27985]="附近的裂隙中冒出了一团能量火花！"
D.Strings[27986]="一只沙德隆的信徒出现了！"
D.Strings[27987]="塔尼布隆开始孵蛋！"
D.Strings[27988]="一只维斯匹隆的信徒出现了！"
D.Strings[27989]="正义得以伸张！"
D.Strings[27990]="没话可说了吧，普特雷斯？"
D.Strings[27991]="看看周围，兄弟姐妹们，睁开眼睛！看看王国被践踏成了什么样子！"
D.Strings[27992]="你们还要对这种野蛮的践踏容忍多久？"
D.Strings[27993]="我对部落了如指掌。无论是他们的城市，还是他们的思维……"
D.Strings[27994]="我深知，兽人的内心是多么邪恶。"
D.Strings[27995]="萨尔！他来了？"
D.Strings[27996]="前进！结束这一切吧！"
D.Strings[27997]="众所周知，兽人有一句口号：LOK'TAR OGAR！意思是“非胜即死”。真合适……"
D.Strings[27998]="向王座前进！"
D.Strings[27999]="瓦里安，停下！我不会帮你这么做的！"
D.Strings[28000]="如果轰炸机被击落，而你被敌人俘虏的话，一定不要讲出自己的真名。要用代号噢。"
D.Strings[28001]="%s召唤出骷髅战士！"
D.Strings[28002]="%s再次投入了战斗！"
D.Strings[28003]="%s召唤出更多的骷髅！"
D.Strings[28004]="%s施放了瞬移！"
D.Strings[28005]="那个在天谴之门屠杀我们同胞的凶手，就龟缩在这座肮脏的城市里！他必须受到正义的裁决！"
D.Strings[28006]="霜爪熊怪去死吧！"
D.Strings[28007]="霜爪熊怪的敌人就是我们的盟友！"
D.Strings[28008]="灰喉堡属于红牙熊怪！"
D.Strings[28009]="杀光红牙熊怪！"
D.Strings[28010]="胜利属于霜爪熊怪！"
D.Strings[28011]="红牙熊怪的敌人，就是我们的朋友！"
D.Strings[28012]="大多数巨龙都不敢来到此地，$r。$b$b你这样的凡人为何要以身犯险？"
D.Strings[28013]="你敢于进入玛里苟斯的王国，面对他手下的精英侍卫吗，$r？"
D.Strings[28014]="我……我想是的……"
D.Strings[28015]="幼龙一直在盼望你回来呢，$c。$b$b你准备好起飞了吗？"
D.Strings[28016]="我准备好了，科拉丝塔萨。"
D.Strings[28017]="好累！这些恶魔还真是顽固。"
D.Strings[28018]="*呼*我要喘口气……"
D.Strings[28019]="浴血奋战的感觉真好，你觉得呢？"
D.Strings[28020]="一队精英蓝龙冲出了传送门！"
D.Strings[28021]="传送门守卫者保护着新的传送门！"
D.Strings[28022]="一名传送门看护者冲出了传送门！"
D.Strings[28023]="对不起，朋友。只有联盟的军官才有权购买载具。"
D.Strings[28024]="魔法力量宝典"
D.Strings[28025]="你可以在铭文训练师附近找到这种古老的书册。"
D.Strings[28026]="载具起火了！"
D.Strings[28027]="成功啦！你听到了吗？真是难以置信！"
D.Strings[28028]="以后有的是时间啊，布莱恩。我们必须立即转移！"
D.Strings[28029]="好吧，以后再来这里。我觉得我们应该瞧瞧入口附近的门后面到底隐藏着什么秘密。我会悄悄地潜行过去。到门口找我吧，我能带你们进去。"
D.Strings[28030]="放置欧米伽符文。成功激活。"
D.Strings[28031]="这里的风景是不是很漂亮啊？你能看到潜在的利益吗？"
D.Strings[28032]="今天是个好日子，不是吗？希望今天结束的时候我们能欣赏到焰火表演。"
D.Strings[28033]="你好，小$r。"
D.Strings[28034]="即使东西没有损坏，也不代表你不能鼓捣它。你想要什么，亲爱的？"
D.Strings[28035]="在如此寒冷的气候下，你要如何飞行呢？"
D.Strings[28036]="听说你出售摩托车零件。"
D.Strings[28037]="立即返回魔枢！"
D.Strings[28038]="D16限时炸弹分配器发出轰鸣声。"
D.Strings[28039]="<从分配器中取出一枚炸弹。>"
D.Strings[28040]="谢谢你！谢谢你一点忙都不帮！"
D.Strings[28041]="你为什么要这样对待哈克穆德？"
D.Strings[28042]="你让哈克穆德现在怎么办好呢？"
D.Strings[28043]="哈克穆德没法在这种环境下工作！再见！"
D.Strings[28044]="我以为我们是朋友！你要丢下哈克穆德吗？"
D.Strings[28045]="没人喜欢尼莫……"
D.Strings[28046]="再见！你曾经是尼莫最好的朋友！"
D.Strings[28047]="尼莫走了。"
D.Strings[28048]="这上面的景色可真不错！"
D.Strings[28049]="噢，我明白了……你也想那样对待我，是吗？"
D.Strings[28050]="嗯……我总是被人抛弃。"
D.Strings[28051]="我们的友谊完蛋了！"
D.Strings[28052]="你想把我丢在这儿？那我怎么回去？"
D.Strings[28053]="你是认真的吗？你想丢下莫吉蒂？"
D.Strings[28054]="你很坏！别说莫吉蒂没警告过你！"
D.Strings[28055]="那就这样吧！"
D.Strings[28056]="糟糕，我把轻羽毛放家里了……缓落术在这里应该很有用的！"
D.Strings[28057]="嗯……真有趣。"
D.Strings[28058]="瞧瞧这些书籍，我只恨时间不够用。"
D.Strings[28059]="这么多神奇的书籍……"
D.Strings[28060]="回家的感觉真好。"
D.Strings[28061]="$n打伤了%s。"
D.Strings[28062]="欢迎造访，$c。达拉然让我感觉身心舒畅，我喜欢待在家里。但是有时候，也会有孤单……冷清的感觉。"
D.Strings[28063]="我有一本书，你或许会感兴趣的。想看看吗？"
D.Strings[28064]="这真是太奇妙了！书里记载的很多内容都是我闻所未闻的。你肯定费了一番功夫才找到的吧？如果你再发现这样的书，一定要立即通知我。\n\n我将肯瑞托魔仆交给你，这样你可以随时向我汇报最新的进展。"
D.Strings[28065]="阅读指令"
D.Strings[28066]="带上麦酒，踏上寻宝之旅——还有什么比这更美好的事情呢。"
D.Strings[28067]="谢谢你！如果有所发现，我一定会及时通知你的。"
D.Strings[28068]="翡翠梦境已然危机四伏。许多勇士放弃了艾泽拉斯的生活，试图拯救翡翠梦境。我越来越担心他们的安危了。"
D.Strings[28069]="请送我去翡翠梦境寻找橡果。我知道这很危险，但是我不怕。"
D.Strings[28070]="好吧，我们换个法子……"
D.Strings[28071]="你的申请已被批准，$n。请等待飞行机会……"
D.Strings[28072]="$n，轰炸机准备好了。祝你好运！"
D.Strings[28073]="等等，$n……"
D.Strings[28074]="土灵愿意握紧铁锤，成为布德克拉格坚强的后盾。我们要和洛肯的爪牙斗争到底。"
D.Strings[28075]="我们击败了瓦杜兰！还将推倒他的塑像。"
D.Strings[28076]="干得好！今天我们取得了胜利，但是战争还在继续！"
D.Strings[28077]="快点，$c。"
D.Strings[28078]="%s将你的灵魂转移到了食尸鬼体内。"
D.Strings[28079]="再来一瓶？为什么不呢！"
D.Strings[28080]="<引擎发出巨大的轰鸣声。>"
D.Strings[28081]="<坐上轰炸机，返回无赖港。>"
D.Strings[28082]="沉降之环攻城车间遭到了联盟的袭击！"
D.Strings[28083]="沉降之环攻城车间遭到了部落的袭击！"
D.Strings[28084]="破碎神殿攻城车间遭到了联盟的袭击！"
D.Strings[28085]="破碎神殿攻城车间遭到了部落的袭击！"
D.Strings[28086]="我们会想你的，安东尼达斯。"
D.Strings[28087]="谢谢你为我们所做的一切。愿你安息。"
D.Strings[28088]="将亚维鲁的宝珠放到祭坛上。"
D.Strings[28089]="狂风环绕着祭坛。你发现祭坛的凹槽处刚好可以放进一颗宝珠。"
D.Strings[28090]="偶尔离开圣殿，呼吸一下新鲜空气也是很不错的。"
D.Strings[28091]="好在巫妖王的魔爪还没有伸到达拉然来。"
D.Strings[28092]="她约我在这里碰面的……难道我找错地方了？"
D.Strings[28093]="终于！$b$b预言中提到的$r$c终于出现了！"
D.Strings[28094]="我准备好返回生者的世界了。"
D.Strings[28095]="宝库遭到了攻击！"
D.Strings[28096]="宝库被攻破了！泰坦圣物失去了保护！"
D.Strings[28097]="我能帮你什么忙吗，战士？"
D.Strings[28098]="有事吗，小家伙？"
D.Strings[28099]="%s召唤出一名碧蓝魔环上尉！"
D.Strings[28100]="炼金房的铭文训练师身旁有一本巨大的，闪闪发光的魔法书，能够帮助你制作强化法术和技能的铭文。"
D.Strings[28101]="快一点，$r。我很疲倦，没功夫开玩笑……"
D.Strings[28102]="保持警惕，$r。$b$b这里不是弱者的游乐场。"
D.Strings[28103]="%s向$n冲来！"
D.Strings[28104]="%s准备猛击他面前的地面！"
D.Strings[28105]="%s对所有人施放了不灭痛楚！"
D.Strings[28106]="%s对所有人施放了谴责！"
D.Strings[28107]="请你再展示一次，米斯希尔萨。"
D.Strings[28108]="返回弗约恩之砧！"
D.Strings[28109]="也许我应该解释一下……"
D.Strings[28110]="我为萨尔酋长和乌瑞恩国王安排了一次秘密峰会，举办地点就在塞拉摩。"
D.Strings[28111]="国王本来要秘密乘船来到这里，但是那艘船从未来过，国王也从此杳无音讯。"
D.Strings[28112]="在你的帮助下，我们找出了迪菲亚盗贼的幕后主使者——奥妮克希亚。她伪装成一名皇家议会的成员，潜藏在暴风城。"
D.Strings[28113]="与此同时，国王设法逃了出来，并返回暴风城去挑战奥妮克希亚。"
D.Strings[28114]="我会告诉乌瑞恩国王，是你找到了迪菲亚盗贼的幕后主使。之前我曾经以为在艾德温·范克里夫死后，迪菲亚盗贼已经土崩瓦解，看来我大错特错了。乌瑞恩国王正好借此机会向其他蠢蠢欲动的家伙发出警告。"
D.Strings[28115]="Lok'tar！你是来协助部落作战的吗？"
D.Strings[28116]="谢谢你，$n。士兵们的健康就全靠你了。"
D.Strings[28117]="当心，$n。记住，部落也在搜集龙骨。杀死他们或许比杀死幽灵容易一些。"
D.Strings[28118]="别对那些禽兽心软，$n！"
D.Strings[28119]="你要阻止部落收集灰烬，$n。我们不能让他们在以后的战斗中占据优势！"
D.Strings[28120]="毁掉那些邪恶的战争机器，$n！"
D.Strings[28121]="冰川瀑布非常危险，$n。为了施放邪恶的巫毒魔法，部落会毫不犹豫地杀死你，夺走你的护甲。"
D.Strings[28122]="帮助我们取得胜利吧，$n。你会得到应得的荣耀！为联盟而战！"
D.Strings[28123]="森林就在冬拥湖的西部边缘。你只要找那些吸食灵魂的幽灵就行了，它们肯定会很高兴有人来做伴的……"
D.Strings[28124]="无耻的联盟也跑来这里抢夺资源，他们糟蹋了这片土地！你要毫不犹豫地杀死他们，从他们的尸体上拿走草药！"
D.Strings[28125]="杀光他们，$n！"
D.Strings[28126]="元素灰烬在燃烧时释放出的热量，比杜隆塔尔在火焰节期间燃起的烈焰还要强烈。绝对不能让联盟得到它们！"
D.Strings[28127]="毁掉那些攻城器械，$n！莫普会知道的。"
D.Strings[28128]="非胜即死，$n！"
D.Strings[28129]="保护我们的战争机器，$n！为联盟的荣誉而战！"
D.Strings[28130]="保护我们的攻城器械，$n！摧毁他们的城墙！"
D.Strings[28131]="死亡……是无法阻止我的……"
D.Strings[28132]="我把峭壁号角弄丢了。"
D.Strings[28133]="啊，复活节。看到人们放下尊严，四处搜寻彩蛋，真是有趣啊。显然，这些彩蛋拥有某种特殊的魔力……"
D.Strings[28134]="复活节又到啦！在这个节日里，我们要感谢圣光让世界重生。"
D.Strings[28135]="糖果！这正是我想要的；希望我不用为了找糖果而东奔西跑！"
D.Strings[28136]="为什么要庆祝世界的自然演变，真是可笑。无论我们庆祝与否，它都会发生呀！不过，这是一个吃糖果的好借口！"
D.Strings[28137]="嘿，如果人们乐意四处奔走，在土堆里寻找彩蛋，我有什么好说的呀？反正我能从绘制彩蛋上赚到一笔，而且今年我还投资了养鸡场。"
D.Strings[28138]="复活节来啦！我找到了好多好多彩蛋。今天真是个找彩蛋的好日子呢，不是吗？"
D.Strings[28139]="复活节是艾泽拉斯的德鲁伊们庆祝生命复苏的日子。彩蛋是繁衍的象征，同时能很好地引导大家理解灵魂的奥秘，你说是吗？"
D.Strings[28140]="我们会在复活节期间庆祝春天的到来。赞美生命和一切美好的事物。"
D.Strings[28141]="此刻，我们赞美生命的诞生，而彩蛋代表着春天和复苏。愿你度过一个美好的春天。"
D.Strings[28142]="嘿，朋友，眼下正是为生命和春天欢呼的日子。你已经收集到了不少彩蛋吧？"
D.Strings[28143]="这个节日根本毫无意义。彩蛋和所谓“生命的礼赞”，我呸。"
D.Strings[28144]="%s预感到自己大祸临头了！"
D.Strings[28145]="抓起码头上的炸药，摧毁大门！"
D.Strings[28146]="嗨，朋友！你是来协助我们作战的吗？"
D.Strings[28147]="你好，朋友。希望你在复活节期间玩得开心！为什么不一起狂欢呢？"
D.Strings[28148]="你好，$c。$B$B一旦联盟取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧！"
D.Strings[28149]="你好，$c。$B$B一旦部落取得冬拥堡垒的控制权，我就将为想要前往那里的旅行者开启一道传送门。$B$B战斗正在进行中，赶快前往冬拥湖，支援我们的部队吧。"
D.Strings[28150]="在我们的新盟友牦牛人的帮助下，部落一定会取得诺森德的统治权。"
D.Strings[28151]="我要返回大德鲁伊莉琳德拉身边。你能送我过去吗？"
D.Strings[28152]="你好啊，$c！欢迎乘坐吻云号。诺森德的环境非常恶劣，希望你已经做好了准备。"
D.Strings[28153]="哦，那么你应该去找本尼克·螺剪。他就在矮人区中心的铁匠铺。"
D.Strings[28154]="沃特尔·索雷夫。盗贼区。他做钥匙。"
D.Strings[28155]="如果你要找锁匠的话，不如去下水道看看？你可以在那里找到许多……名声不太好的家伙。"
D.Strings[28156]="入侵者！你们这些凡人竟敢坏了我的兴致，看我怎么……等等，你们……"
D.Strings[28157]="<奥琳迪雅的身躯在海浪中微微晃动着。看样子，她死去已经有一段时间了。>"
D.Strings[28158]="<你靠近塞瑞利恩，听到他喘息的声音。看样子，如果救治及时，他应该还有机会。>"
D.Strings[28159]="狂妄的小崽子们，竟敢在我的地盘上挑战我？我要亲自碾碎你们！"
D.Strings[28160]="<沃尔科的身躯纹丝不动。当你抬脚要走开的时候，一只手抓住了你的脚踝。他还活着！>"
D.Strings[28161]="<你靠近莎尔蒂，听到她的喉咙中传出一阵微弱的声音。>\n\n请……救救我。"
D.Strings[28162]="<戈沙拉翻滚过来，看着你。你在他的脸上发现了一抹充满希望的微笑。>"
D.Strings[28163]="<当你将巴瑞萨斯瘫软的身体在水中翻转过来的时候，他头顶上一个可怕的伤口赫然出现在你眼前。你立刻明白了他没能撑下去的原因。>"
D.Strings[28164]="<达蒙德的身体埋在浅滩中，神色很安详。>"
D.Strings[28165]="<格隆达尔无力地向你伸出手。随着他的生命迅速流逝，他的手臂瘫软了下去。>"
D.Strings[28166]="<特伦希斯的眼睛凝望着远方，眨也不眨，其中流露出哀伤的神情。>"
D.Strings[28167]="<瓦尔达隆身上全都是可怕的伤口。你不需要检查他的脉搏就知道，他已经过世了。>"
D.Strings[28168]="<当你靠近这名暗夜精灵的时候，她转向你，并朝你伸出手。>\n\n我已经救不活了。我们因为自身的骄傲而得到这样的命运。走吧……也许还有其他人值得你去救。尽量救助他们。\n\n<随着生命的流逝，她的手又垂了下去。>"
D.Strings[28169]="这就是……临死的感觉？\n\n<随着玛芙琳呼吸的终止，这个问题自然也有了答案。>"
D.Strings[28170]="火鸡猎人！"
D.Strings[28171]="火鸡主宰！"
D.Strings[28172]="火鸡大绝杀！"
D.Strings[28173]="维斯派塔斯的角鹰兽可以将你快速送往目的地。"
D.Strings[28174]="火鸡制霸！"
D.Strings[28175]="去找维斯派塔斯吧。他负责管理在泰达希尔底部起落的角鹰兽。"
D.Strings[28176]="嘿！这边！"
D.Strings[28177]="让我离开这里，行吗？"
D.Strings[28178]="那个家伙有钥匙。"
D.Strings[28179]="骡子充满期待地看着你。"
D.Strings[28180]="这不是你的骡子。"
D.Strings[28181]="我们的家园在大灾变中被摧毁了！$B$B许多幸存者向北流亡，逐步建立起新奥伯丁。而我们留在这里也是有原因的。等到我们治愈了伤口，就要从那些暮光之锤的恶棍手中夺回旧奥伯丁。$B$B希望你能在那时帮助我们消灭那些敌人。"
D.Strings[28182]="在我从达纳苏斯向南方飞行，寻找玛法里奥·怒风的途中，我遇到了这些受伤的旧奥伯丁难民。$B$B我开始帮忙照料这些伤员，但他们的数量太多了，让他们完全恢复需要很长的时间。$B$B相信你也会愿意帮助他们。"
D.Strings[28183]="警告：魔像只能在丹厄古尔使用！"
D.Strings[28184]="多年以前，我本想帮助解决本地的鱼人问题，不料却因此而悲惨地丢了性命。但值得欣慰的是我并未如其他灵魂一般前往女神身边，而是得以留在这里继续看着我的家人和朋友。$B$B现在，他们都已经离开，甚至去世了。我留在这里的理由就只剩下了一个。$B$B复仇。"
D.Strings[28185]="需要擦鞋吗，$c？"
D.Strings[28186]="好好保养鞋子啊，$c。"
D.Strings[28187]="来擦擦鞋吧！"
D.Strings[28188]="让我来帮您擦擦鞋吧，$c。"
D.Strings[28189]="又一个体面而又快乐的人，一路顺风，$c！"
D.Strings[28190]="感谢你救了我，陌生人。"
D.Strings[28191]="桑迪斯·织风的尸体倒伏在这里。这显然是暮光之锤的诡计造成的。"
D.Strings[28192]="说服桑迪斯·织风的灵魂。"
D.Strings[28193]="桑迪斯·织风的灵魂被召唤出来。"
D.Strings[28194]="阿图里斯升起了护罩。你必须迅速打断他的法术。"
D.Strings[28195]="冰霜豹已经被麻醉了，静静地躺在地上。"
D.Strings[28196]="拎起冰霜豹的尾巴，检查一下它是雄性还是雌性。"
D.Strings[28197]="这是一头愤怒的雄性野兽！"
D.Strings[28198]="这是一头雌性野兽。"
D.Strings[28199]="冰爪熊已经被麻醉了，静静地躺在地上。"
D.Strings[28200]="拎起冰爪熊的尾巴，检查一下它是雄性还是雌性。"
D.Strings[28201]="渴了？不如来一壶又暖又甜的蜜酒？快来尝尝吧！"
D.Strings[28202]="我在哪儿？嗝！"
D.Strings[28203]="我的酒瓶子呢？你看到它了吗？"
D.Strings[28204]="我的法术强度曾经高达1850，现在这是怎么回事？"
D.Strings[28205]="没有什么能比一杯茴香烈酒更暖胃啦。来这里购买吧！"
D.Strings[28206]="甘醇的雪梅白兰地！一杯入口，回味无穷！"
D.Strings[28207]="美酒应有尽有！从雪梅白兰地到西部荒野威士忌，快来买啊！"
D.Strings[28208]="你到外面来干什么？你应该在里面跟蓝龙军团作战！"
D.Strings[28209]="我没有在打架，所以赶紧给我找个人来打！"
D.Strings[28210]="我知道，我知道……“在下水道里钓鱼？”但是如果你知道在这里能钓到什么，一定会大吃一惊的。我还听说有人钓到过鲨鱼，你信不信？"
D.Strings[28211]="这名哨兵的尸体倒在地上，他显然是死在元素攻破这座城镇的战斗中。"
D.Strings[28212]="说服那个灵魂，让它离开哨兵艾莉萨·星风的尸体。"
D.Strings[28213]="这里是塔尔丹送上最后一杯饮料的地方。"
D.Strings[28214]="说服塔尔丹的尸体，让他放弃自己的灵魂。"
D.Strings[28215]="元素没有如此巨大的力量。凯莱斯和她的角鹰兽一定是被另外某个东西打下来的。"
D.Strings[28216]="说服那个灵魂，让它离开凯莱斯·月羽的尸体。"
D.Strings[28217]="下一个牺牲品就是新奥伯丁，傻瓜。阿瑟里恩几乎已经完全进入这个世界了，一切都只是时间问题！"
D.Strings[28218]="这个地方只是一个开端。我们会粉碎你们的难民营地，然后率领我们的元素向北，直捣新奥伯丁。阿瑟里恩将是我们的先锋！"
D.Strings[28219]="新奥伯丁竟然派你这样的人来,他们一定是绝望了。我们很快就会和他们开战了!"
D.Strings[28220]="我们的主人将打碎这个世界。你所熟知的一切都将终结。现在只是一个小小的开端！"
D.Strings[28221]="你无法阻止我们将阿瑟里恩带到这个世界的最终仪式。可惜的是，你将无法活着看到这一幕！"
D.Strings[28222]="如果你明白我所侍奉的是怎样的力量，你必将毫不犹豫地跪倒在我面前，加入我们的行列。可惜的是，你的傲慢只能给你带来毁灭！"
D.Strings[28223]="你在干什么？难道你不知道世界末日就要到来了吗？来，让我展示给你看！"
D.Strings[28224]="你要找祖祖的麻烦？没关系……阿瑟里恩在这里，伙计。我们要冲进你们的难民营里去，再去打破你们的新奥伯丁。但首先要死的是你！"
D.Strings[28225]="没时间和你耗了。阿瑟里恩就快要开始肆虐了！"
D.Strings[28226]="我就要进入这个世界了。暮光之锤，认真进行召唤仪式，否则我也把你们一并摧毁！"
D.Strings[28227]="我看到你了，爬虫。趁着还能逃跑就拼命逃跑吧。跑去告诉你们那个可怜的洛达内尔，我就要去摧毁它了！"
D.Strings[28228]="玛法里奥，能听到我说话吗？等到我毁灭了艾露恩的孩子们，我就会来把你了结掉！"
D.Strings[28229]="凡人们，我的主人来了！我只是主人大军的传令官。你们的世界将经历巨大的转变，你们全都难逃一死！"
D.Strings[28230]="耐心一些！让我进入这个世界的仪式非常复杂，绝不能有任何贸然行动！"
D.Strings[28231]="现在，加入暮光之锤吧。当我完全进入这个世界的时候，那些不肯屈服的人只能迎来死亡！"
D.Strings[28232]="最终的结局只有一个。大灾变只是一个开始。你所熟悉的这个世界终将灭亡！"
D.Strings[28233]="你们这些由元素构成的凡人，怎么能妄想反抗真正强大的存在？准备回归到你们真实、根本的状态吧！"
D.Strings[28234]="你怎敢如此？！今天，洛达内尔、玛法里奥和你都将彻底毁灭！"
D.Strings[28235]="我不会根据他们的外表去做出判断，而是根据他们的勇气和忠诚。"
D.Strings[28236]="不，阿瑟里恩，我们不会允许这样的事情发生！"
D.Strings[28237]="这是什么？雅尔达？哈哈哈哈哈哈，你和其他这些灵魂不可能阻止我！"
D.Strings[28238]="走着瞧。让我们合力削弱他，朋友们！"
D.Strings[28239]="我们真是焦头烂额了。先是没能及时赶到冰冠冰川与我们的部队会合，现在又处在被天灾军团和达卡莱巨魔两面夹击的险境。$B$B我早就跟大领主说过了，来这里根本就是个错误。$B$B看看你能帮帮我们什么忙吧。"
D.Strings[28240]="你听到了吗，$c？元素们哭喊着说，这片土地已经濒临死亡了。达卡莱巨魔正在窃取自己神灵的力量，用以抵御天灾军团。$B$B他们的鼠目寸光终将导致他们自身的毁灭。"
D.Strings[28241]="在目睹了瘟疫之地的凄惨和圣光之愿礼拜堂的血战之后，我以为再也看不到比那些更加恐怖的东西了。$B$B但是我错了。"
D.Strings[28242]="虽然被削弱了，我还是能摧毁你们！！！"
D.Strings[28243]="你深深吸了一口气，可以开始了！"
D.Strings[28244]="你的拳头捏得劈啪作响，可以开始了！"
D.Strings[28245]="你的肌肉已经充分伸展，可以开始了！"
D.Strings[28246]="%s开始召唤坍缩之星！"
D.Strings[28247]="群星将为我而战！"
D.Strings[28248]="女神祝福了你。"
D.Strings[28249]="接受艾露恩的礼物吧。"
D.Strings[28250]="塞瑞利恩！你还活着！"
D.Strings[28251]="我会带他回到洛达内尔。感谢你的帮助，陌生人。"
D.Strings[28252]="艾露恩与你同在。"
D.Strings[28253]="感谢你，女祭司。"
D.Strings[28254]="赞美艾露恩！"
D.Strings[28255]="我感觉好多了，谢谢你。"
D.Strings[28256]="我们一定要夺回奥伯丁！"
D.Strings[28257]="暮光之锤将为他们所做的一切付出代价。"
D.Strings[28258]="赞美艾露恩。"
D.Strings[28259]="女神护佑着你。"
D.Strings[28260]="戈沙拉……德塔莉亚看到你还活着，一定会非常高兴的。"
D.Strings[28261]="我会把他带回到女祭司那里。衷心感谢你。"
D.Strings[28262]="我会将莎尔蒂安全地带回去。感谢你，英雄。"
D.Strings[28263]="莎尔蒂！"
D.Strings[28264]="沃科尔……很高兴看到你还活着。但锐爪在哪里？"
D.Strings[28265]="我们以后再担心他吧。现在我先要保障你的安全。"
D.Strings[28266]="朋友，感谢你的帮助。这里就交给我吧。"
D.Strings[28267]="铁枝长老施放了钢铁根须！"
D.Strings[28268]="石树长老开始施放|cFFFF0000大地震颤！|r"
D.Strings[28269]="一道劈啪作响的符文屏障包围了%s！"
D.Strings[28270]="石树长老开始施放岩石之拳！"
D.Strings[28271]="见证宇宙的怒火吧！"
D.Strings[28272]="我记得你们……在群山中……但是你们……这是怎么回事？我这是在——"
D.Strings[28273]="外域的传送门"
D.Strings[28274]="燃烧军团"
D.Strings[28275]="%s选择了一个新目标。"
D.Strings[28276]="没用的废物！"
D.Strings[28277]="用力煽火！$B$B\n|TInterface\\Icons\\INV_Misc_EngGizmos_04.blp:64|t"
D.Strings[28278]="烈焰巨兽开始超载！"
D.Strings[28279]="调节传动装置！ $B$B\n|TInterface\\Icons\\INV_Misc_EngGizmos_13.blp:64|t"
D.Strings[28280]="引擎过热了！$B压力消失。"
D.Strings[28281]="火花塞熄火了！$B压力消失。"
D.Strings[28282]="齿轮磨损了！$B压力消失。"
D.Strings[28283]="引擎过冷了！$B压力消失。"
D.Strings[28284]="火花塞堵住了！$B压力消失。"
D.Strings[28285]="传动装置松动了！$B压力消失。"
D.Strings[28286]="火焰温度升高了！$B干得好！"
D.Strings[28287]="火花塞干净了！$B干得好！"
D.Strings[28288]="引擎正常运转了！$B干得好！"
D.Strings[28289]="欢迎进入攻城车技师控制台v0.1内部测试版界面。"
D.Strings[28290]="本系统允许你手动控制$B攻城器械的动力和速度。"
D.Strings[28291]="一旦启动系统，你就必须手动$B处理引擎发生的各种紧急故障。"
D.Strings[28292]="正确处理以下情况可以为$B攻城车5000型的溢流罐充能。$B\n|TInterface\\Icons\\INV_Misc_EngGizmos_04.blp:32|t |TInterface\\Icons\\INV_Misc_EngGizmos_12.blp:32|t |TInterface\\Icons\\INV_Misc_EngGizmos_13.blp:32|t"
D.Strings[28293]="压力可以提升攻城车的$B速度、伤害和防御能力。$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t"
D.Strings[28294]="操作员还可以将自己装填到装载臂中，$B让攻城车的驾驶员将其发射到远处。$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t"
D.Strings[28295]="GG工程公司对使用攻城车时$B可能造成的生命、肢体或毛发损失$B|cFFFF2222概不负责|r。"
D.Strings[28296]="联盟的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！"
D.Strings[28297]="Lok'tar！第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！"
D.Strings[28298]="联盟的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！"
D.Strings[28299]="部落的第一座塔楼已经被摧毁了！只要我们扫平全部三座塔楼，敌人就不得不撤退了！"
D.Strings[28300]="第二座塔楼已经被摧毁了！只要我们解决最后一座塔楼，敌人就不得不撤退了！"
D.Strings[28301]="部落的塔楼全部被摧毁了！他们已经落败。解决残余的敌人！"
D.Strings[28302]="输入兑换码，领取冰龙宝宝。"
D.Strings[28303]="必须保卫温室！"
D.Strings[28304]="%s的回路过载了。"
D.Strings[28305]="%s已经恢复如常。正在重新启动作战功能。"
D.Strings[28306]="欢迎进入攻城车机师控制台v0.1内部测试版界面。"
D.Strings[28307]="本系统允许你手动调节$B攻城器械的弹药和速度。"
D.Strings[28308]="一旦启动系统，你就必须手动$B维持攻城车的运作。"
D.Strings[28309]="给齿轮上油可以提高$B攻城车的移动速度。$B\n|TInterface\\Icons\\INV_Misc_Gem_Pearl_01.blp:32|t"
D.Strings[28310]="主炮必须定时装填弹药。$B|TInterface\\Icons\\INV_Misc_Ammo_Bullet_02.blp:32|t"
D.Strings[28311]="弗蕾亚开始施放|cFFFF0000大地震颤！|r"
D.Strings[28312]="%s获得了冰冻重击的效果！"
D.Strings[28313]="%s开始施放快速冻结！"
D.Strings[28314]="回去工作，你这个懒家伙！"
D.Strings[28315]="俗话说狗改不了吃屎。这话说的就是你！"
D.Strings[28316]="这是懦夫的行为！我们应该去把联盟碾碎，就现在！"
D.Strings[28317]="一瓶能够溶解精灵的药剂？也许你会需要这种玩意儿，被遗忘者。而我，会用我的锤子好好的给他们上一课！"
D.Strings[28318]="我需要更多的血啤酒来减缓我的干渴！"
D.Strings[28319]="全力赶工，为了部落的荣耀！"
D.Strings[28320]="被遗忘者，如果你赶不上进度，地狱咆哮酋长一定会要了你的脑袋！"
D.Strings[28321]="多么特别啊……你真是很擅长采花。你要送我一支花束吗？哈哈哈哈！"
D.Strings[28322]="%s击碎了珍贵的霍迪尔宝箱！"
D.Strings[28323]="托里姆，我的陛下！这些入侵者闯入您的圣殿，除了来杀您，还会有别的意图吗？您必须阻止他们！"
D.Strings[28324]="月夜猛虎突然醒过来，发出一阵低沉的咆哮。"
D.Strings[28325]="向暗夜致敬！"
D.Strings[28326]="你无法阻止我们，肮脏的$r！"
D.Strings[28327]="小可爱，想尝点儿腐化污染吗？"
D.Strings[28328]="你在这里干什么？！"
D.Strings[28329]="救命！有人吗？！"
D.Strings[28330]="我会碾碎你，小$r！"
D.Strings[28331]="很好，联盟来了！"
D.Strings[28332]="终于有仗可打了！"
D.Strings[28333]="为了灰谷！"
D.Strings[28334]="为了艾露恩！"
D.Strings[28335]="哞，我现在彻底是一头牡鹿了。你喜欢我的角吗？我刚刚把它们抛光了。"
D.Strings[28336]="喵。我是一只猫了。不要抱我，否则我就抓你。有猫薄荷吗？"
D.Strings[28337]="你是哑巴吗？我可是一头反复无常的熊。后退，废物。"
D.Strings[28338]="给我个任务。"
D.Strings[28339]="$c，这片森林里到处都是部落。一定要时刻警惕周围的动静！"
D.Strings[28340]="我到这里来是为了不惜一切代价完成主人的命令。还有什么比一个命悬一线的小女孩的生命更加重要？"
D.Strings[28341]="掘地鼠炖肉美味极了。"
D.Strings[28342]="回到海洋中去……回到潮汐中去。"
D.Strings[28343]="潮汐也服从艾露恩的命令。"
D.Strings[28344]="感谢你，凡人。海洋的意志是自由的。"
D.Strings[28345]="欢迎你，$g先生:女士;。这片营地比我待过的上一个营地要好多了。$B$B很荣幸，我能够和一群出色的战友共事，他们教会了我不少战斗技巧。现在我已经能独立与部落作战了。"
D.Strings[28346]="你好，$c。我们在这里的位置已经暴露了，部落的军队正在南方集结。$B$B我们将非常感激你为我们提供的一切帮助。"
D.Strings[28347]="欢迎，勇士们。我们多次尝试击落她，但是都失败了。你们能不能来帮帮忙，用这些鱼叉炮把她打下来？"
D.Strings[28348]="我们这就来帮忙！"
D.Strings[28349]="做好准备。我们将在涨潮时发动攻击！"
D.Strings[28350]="召集军队。我们将从灰谷清除掉一切联盟和部落的痕迹！"
D.Strings[28351]="我们的女王鼓舞我们奋勇前进。让我们将敌人打个落花流水！"
D.Strings[28352]="佐拉姆的力量必将崛起！让我们的敌人在我们的触须中被碾碎！冲锋，让他们知道怒尾的强大！"
D.Strings[28353]="摧毁佐拉姆加前哨站！摧毁黑渊营地！我们要向梅伊瑟娜岗哨进军。到日落时分，阿斯特兰纳就会成为一片废墟！"
D.Strings[28354]="大灾变只是开始。让那些两条腿的家伙们死无葬身之地！"
D.Strings[28355]="拿起武器！入侵者就在眼前！把他们彻底消灭，一个也不要留下！"
D.Strings[28356]="你好，陆行者。过来……我们聊聊。"
D.Strings[28357]="我还以为我永远都没有办法摆脱那个可怕的诅咒了。陌生人，谢谢你。"
D.Strings[28358]="乐意为你效劳，女士。听说你曾是一把传说之剑的守护者。你能告诉我该去哪儿寻找这把剑吗？"
D.Strings[28359]="收下它吧。再次感谢你，$c。"
D.Strings[28360]="我的耐心已经到头了！"
D.Strings[28361]="这是真的吗？经历了多年的磨难，我竟然还能重获自由？"
D.Strings[28362]="现在，我必须返回湖泊了。"
D.Strings[28363]="这些可悲的凡人毫无威胁，根本不值得我动手。干掉他们！"
D.Strings[28364]="这不可能！托里姆陛下，我要让您的敌人在严寒中死去！"
D.Strings[28365]="|cFF00FFFF生命缚誓者的礼物|r开始生长！"
D.Strings[28366]="嗨！有人吗？"
D.Strings[28367]="有人能帮忙吗？有少女陷入了困境！<哼哼>"
D.Strings[28368]="到旅店顶上来！他们把我锁起来了！"
D.Strings[28369]="有人能救我吗？请救我出去，不要让他们把我当成祭品！"
D.Strings[28370]="到旅店二楼！快！"
D.Strings[28371]="有人吗？救命！请把我救出去！"
D.Strings[28372]="天哪！真没想到我还能看到别人！$B$B请一定救我出去！"
D.Strings[28373]="太棒了！让我们离开这里。我没有武器。所以，如果你能……你明白的，如果你能保护我，我一定会非常感激！"
D.Strings[28374]="这里是难民营地！"
D.Strings[28375]="我要和你赛跑，看谁先到！"
D.Strings[28376]="霍里！"
D.Strings[28377]="艾丽萨！哦，能从那里逃出来可真好！现在奥伯丁已经彻底被邪教徒和元素占领了！"
D.Strings[28378]="啊，女孩，你现在安全地和朋友们在一起了。我还以为你已经死了！"
D.Strings[28379]="请问，你能给我的这位朋友一些酬金吗？我现在没有钱。但等我回到铁炉堡，就能给你报偿。"
D.Strings[28380]="不要这样说。我不想听你说什么给我报偿之类的话！"
D.Strings[28381]="哦，谢谢，艾丽萨！谢谢你！"
D.Strings[28382]="随时为你效劳。"
D.Strings[28383]="这真是只能喘口气的时间。"
D.Strings[28384]="我们必须离开这里。"
D.Strings[28385]="他们有多少元素？！"
D.Strings[28386]="必须说……暮光之锤真该死！"
D.Strings[28387]="这是最后一个了？"
D.Strings[28388]="为什么我们会听雷塔维的话，来到黑海岸？"
D.Strings[28389]="如果不是你，我就死定了。"
D.Strings[28390]="铁炉堡绝不会发生这种事！"
D.Strings[28391]="你们这些邪教徒一定要付出代价！一定会有人救我出去的！"
D.Strings[28392]="我是探险者协会的一名考古学家！我向你保证，麦格尼国王一定会知道这一侮辱！"
D.Strings[28393]="$G先生:女士;，我能为您做什么？"
D.Strings[28394]="暴风城冠军的旗帜"
D.Strings[28395]="塔尔丹！"
D.Strings[28396]="这没有发生。哦，不……朋友们！"
D.Strings[28397]="快点！我们必须赶紧看看其他人！"
D.Strings[28398]="它已经被毁坏了，但看样子，这里并没有尸体。"
D.Strings[28399]="抱歉，但我必须进行检查。好了，让我们离开这里吧。"
D.Strings[28400]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将冰霜之韧赐予你和你的朋友们，以此提高你们造成的伤害并减少敌人对你们的伤害。如果你们当中有谁命悬一线，我可以将他冻结成冰，在短时间内使他免受任何伤害。这一技能需要消耗大量的精力，因此施放后我必须休息一段时间。"
D.Strings[28401]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将自然之韧赐予你和你的朋友们，以此提高你们造成的伤害并提高法术和效果的治疗量。此外，我还可以召唤理智之井，帮助那些意志动摇的队友恢复理智。"
D.Strings[28402]="我已经为我的侦察任务做好准备了。"
D.Strings[28403]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将发明之速赐予你和你的朋友们，以此提高你们造成的伤害以及移动速度。此外，我还可以扰动那些用萨隆邪铁铸造的生命体的矩阵，降低它们的攻击和施法速度。"
D.Strings[28404]="凡人们，感谢你们让我摆脱了弥漫在这片土地上的堕落力量。尽管我尚未完全恢复，但我能帮助你们与尤格-萨隆作战。\n\n我将风暴之怒赐予你和你的朋友们，以此提高你们造成的伤害以及生命值上限。当你们面对难以摧毁的邪恶时，我会将自己全部的力量汇聚成一道泰坦风暴。即便是神，也会在它的威力下挫骨扬灰。"
D.Strings[28405]="帮助我们作战吧，守护者。只要我们齐心协力，就一定可以击败尤格-萨隆。"
D.Strings[28406]="鲜血与雷鸣，$r！"
D.Strings[28407]="非常感谢，$c！"
D.Strings[28408]="这些是冬水仙？给我的？"
D.Strings[28409]="已经很久没有手捧鲜花的旅行者到这里来了。"
D.Strings[28410]="这些年来，寂寞萦绕着这面湖泊。旅行者再也不愿涉足此地，而邪恶的力量侵蚀了这片水域。"
D.Strings[28411]="你的礼物传达出珍贵的温情，旅行者。为表谢意，请你收下这把剑。很久以前，另一位旅行者将它赠给了我，不过我几乎用不上。"
D.Strings[28412]="自然的盟友出现了！"
D.Strings[28413]="你准备好骑乘作战了吗？"
D.Strings[28414]="我再也不喜欢你了！"
D.Strings[28415]="%s不理睬$n。"
D.Strings[28416]="到这里来，$c。我没有太多的时间……"
D.Strings[28417]="这个受了重伤的兽人已经不省人事了。"
D.Strings[28418]="<这具没有了生命的兽人躯体已经不再有任何动作了……>"
D.Strings[28419]="凡人，感谢你让我摆脱了这个诅咒的束缚。请你收下这把剑。"
D.Strings[28420]="它带给我的只有痛苦与灾难。或许你可以找到那个能操控它的力量的人。"
D.Strings[28421]="我把夏日天空战袍弄丢了。"
D.Strings[28422]="我把夏日烈焰战袍弄丢了。"
D.Strings[28423]="感谢你，朋友。知道我的任务还没有完成，我真是寝食难安。"
D.Strings[28424]="……我那些牺牲的部下还没有得到应有的复仇。"
D.Strings[28425]="我们必须加快速度。我感觉到我的时间已经不多了。"
D.Strings[28426]="跟紧我，准备战斗！"
D.Strings[28427]="胆小的艾伦迪拉德船长就藏在前方的那座岛上，向他的部下发出各种命令。"
D.Strings[28428]="必须打倒他！"
D.Strings[28429]="真累呀。我要休息一会儿！"
D.Strings[28430]="%s的徽记暴露出来，正在泄漏能量。"
D.Strings[28431]="我们来玩吧！"
D.Strings[28432]="现身吧，懦弱的精灵！光荣地迎接你的死亡吧！"
D.Strings[28433]="很高兴见到你，$c。$B$B抱歉……我不能和你长谈。我们这里还有一点战斗。"
D.Strings[28434]="如果你准备好带队出动，就告诉我。$B$B我这里还有一些预备队，所以，如果你还需要更多的人，就回来找我。"
D.Strings[28435]="战况太激烈了。我需要补充一些新兵，哨兵奥奈雅。"
D.Strings[28436]="不！不！不！不！不要这样！"
D.Strings[28437]="%s令地面震颤起来。"
D.Strings[28438]="我必须杀掉你多少次，兽人？！"
D.Strings[28439]="感谢你的救援。让我们离开这里吧！"
D.Strings[28440]="终于逃出来了。到了这里，我就应该能游回去了。但在我离开之前，还有件事要对你说……"
D.Strings[28441]="首先，战歌氏族驱赶这些巨魔离开山地来攻击我们。这对莫拉来说一定是一个重要的情报。我怀疑他们也打算进攻灰谷。"
D.Strings[28442]="我曾经有机会突袭他们的首领。但那个首领被某种魔法保护着。所以在发动攻击之前，一定要让莫拉知道这件事。"
D.Strings[28443]="再见，新朋友。愿艾露恩的祝福与你同在。"
D.Strings[28444]="你根本不知道自己在干什么！"
D.Strings[28445]="你这该死的$r虫子！这片森林是属于卡多雷的……"
D.Strings[28446]="%s凋零入土，开始新生。"
D.Strings[28447]="在盟友的帮助下，%s重获新生。"
D.Strings[28448]="%s开始施放烈焰喷射！"
D.Strings[28449]="史诗级紫色衬衫"
D.Strings[28450]="摇摇虎"
D.Strings[28451]="泡沫塑料剑架"
D.Strings[28452]="角斗士之血"
D.Strings[28453]="任务完成。谢谢你，朋友。"
D.Strings[28454]="维扎克斯将军咆哮着，黑暗的力量在他体内奔涌！"
D.Strings[28455]="我要让你不得好死，蛆虫！"
D.Strings[28456]="$r？你这该死的！"
D.Strings[28457]="你就是那个所谓的联盟勇士。只要你一死，这里就会被轻松地攻陷。"
D.Strings[28458]="可怜的弱者。你的死期不远了！"
D.Strings[28459]="我在看着你，虫子。你还在瞎哼哼什么？赶快去干掉他们！"
D.Strings[28460]="注意那边。好好瞄准他们。不要放过他们！"
D.Strings[28461]="投降吧，梅伊瑟娜，我会让你死个痛快！"
D.Strings[28462]="砸扁他们！打碎他们！为了部落的荣耀！"
D.Strings[28463]="你们的时代过去了，暗夜精灵。灰谷是我们的了！"
D.Strings[28464]="我想要那家伙的命！那里的那个家伙看起来有些与众不同！"
D.Strings[28465]="你们已经没有希望了。你们的黑海岸变成了一片废墟。阿斯特兰纳和这个地方很快都将陷落。趁现在逃到达纳苏斯去吧。"
D.Strings[28466]="弱小的暗夜精灵，轻易就能战胜！"
D.Strings[28467]="我……我终于从他的魔掌中……解脱了。"
D.Strings[28468]="不！加尔鲁什，我辜负了你……"
D.Strings[28469]="记住，那座塔顶的术士能够看穿你的隐形！"
