D.Strings[28491]="新玩具？给我的吗？我保证这次不会把它们弄坏了！"
D.Strings[28492]="我……我好像把它弄坏了。"
D.Strings[28493]="好像不能这么用力折它。"
D.Strings[28494]="你们是坏玩具……很……坏。"
D.Strings[28495]="我不喜欢这些玩具了！我不想玩了！"
D.Strings[28496]="图伦需要战歌营地的木材。我需要蛮角拖动那些木材。"
D.Strings[28497]="很好，$c。但一定要小心，蛮角可是相当……不好对付。"
D.Strings[28498]="撤销"
D.Strings[28499]="艾欧娜尔，您的仆人需要帮助！"
D.Strings[28500]="元素之潮会击垮你们！"
D.Strings[28501]="孩子们，帮帮我！"
D.Strings[28502]="长老们，将你们的力量赐予我！"
D.Strings[28503]="杀死科多兽，捉住骑手！"
D.Strings[28504]="不要让它过去！"
D.Strings[28505]="%s利用符文的力量强化了周围的盟友。"
D.Strings[28506]="他对我的控制已经不复存在了。我又一次恢复了理智。谢谢你们，英雄们。"
D.Strings[28507]="来吧，暗夜精灵的杂碎们！"
D.Strings[28508]="小心引线！"
D.Strings[28509]="射程设定。"
D.Strings[28510]="一！二！五！……三！"
D.Strings[28511]="我走了。多加小心——我会尽快回来的。"
D.Strings[28512]="我们需要你的炸药。为此，我很愿意要你的命。"
D.Strings[28513]="老朋友们，你们站错了队。现在你们的运输队是我的了。"
D.Strings[28514]="蛮角怒吼着冲入伏兵之中！"
D.Strings[28515]="已启动自动修复程序。"
D.Strings[28516]="已解除武器系统。"
D.Strings[28517]="现在，我要将圣光之力注入这块水晶，让它揭穿一切谎言与欺瞒的伪装。"
D.Strings[28518]="赐予我们洞悉真相的能力吧。如果凶手就在我们之中，请指引我们寻求正义的裁决。"
D.Strings[28519]="除非精灵滚蛋，否则我就不会工作！"
D.Strings[28520]="精灵在森林里杀了太多的人。我们要留在这个安全的地方。"
D.Strings[28521]="我可不会为一点木头丧命！"
D.Strings[28522]="来吧，朋友。让我来保护你免受精灵的偷袭，好吗？"
D.Strings[28523]="干得好！那些叛徒终于得到了惩罚。这是一件大快人心的事情。沿着米兰走过的路向东方前进，让勘察员基恩萨·铁环知道我们的胜利。我相信，他也会有一些任务给你。"
D.Strings[28524]="很感谢你对我们的帮助。我们从不会认为赛恩是个有同情心的人——我们只是还没有为此做好准备。"
D.Strings[28525]="嗯，你看上去不是很强壮……不过应该还成。"
D.Strings[28526]="别离开我，$r。别让精灵靠近我！"
D.Strings[28527]="你不会让我死吧？好吧，那么……"
D.Strings[28528]="哨兵，我想骑着你的一头夜刃豹去阿斯特兰纳。"
D.Strings[28529]="一定要小心，$r！这里到处都是精灵！"
D.Strings[28530]="去死吧。"
D.Strings[28531]="死亡只是你的生命的必然结果。"
D.Strings[28532]="我们遍布在你下方。"
D.Strings[28533]="这是新的开始。为你们的末日而欣喜吧。"
D.Strings[28534]="拥抱从深渊崛起的未来吧。"
D.Strings[28535]="丛林守护者哈特维斯，停止你的反抗。"
D.Strings[28536]="凡间的生物，你们是必须被清除的害虫。"
D.Strings[28537]="来和我聊聊吧。让我们以文明的方式讨论一些事情。"
D.Strings[28538]="回到你原来的地方去吧，污秽的生物！"
D.Strings[28539]="给我回去！"
D.Strings[28540]="艾露恩之光将击败你！"
D.Strings[28541]="我不知道你是什么玩意儿，但我知道，你必死无疑！"
D.Strings[28542]="在艾露恩的神恩中枯萎吧！"
D.Strings[28543]="我会将你从这个世界清除掉！"
D.Strings[28544]="这是非自然的！"
D.Strings[28545]="我只能靠你了……不要让我死！"
D.Strings[28546]="就这样了，$r。"
D.Strings[28547]="我走了！注意警惕……"
D.Strings[28548]="我对此有一种不祥的预感……"
D.Strings[28549]="掩护我，$r！"
D.Strings[28550]="我们不会在容忍你了，兽人！"
D.Strings[28551]="灰谷属于卡多雷！"
D.Strings[28552]="我们这里不欢迎部落，兽人！现在，去死吧！"
D.Strings[28553]="为我报仇，$n。"
D.Strings[28554]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智偏低！|r"
D.Strings[28555]="你残破的身躯将成为新的力量崛起的养料！"
D.Strings[28556]="这个躯壳毫无意义。我们永无终结。"
D.Strings[28557]="%s变成了一尊石像，等待下一场战斗分出胜负。"
D.Strings[28558]="%s察觉到一场战斗即将爆发，准备变回一尊石像。"
D.Strings[28559]="一团萨隆邪铁蒸汽在附近聚集起来！"
D.Strings[28560]="露亚娜，我要骑着你的一头夜刃豹去梅伊瑟娜岗哨。"
D.Strings[28561]="终于找到我了？没关系，你不可能有机会再把这件事告诉别人了！"
D.Strings[28562]="快一点，$c！没时间磨蹭了！$b$b碎木岗哨绝不能失守。"
