D.Strings[28575]="蠕虫"
D.Strings[28576]="你们漂泊得太远了，浪费了太多的时间……"
D.Strings[28577]="快一点！她马上就要挣脱了！"
D.Strings[28578]="保持警惕！钻探机即将冒出地表，讨厌的铁矮人就要来了！"
D.Strings[28579]="你的执着真是令人钦佩。"
