D.Strings[28583]="看来你还没有做好骑乘作战的准备。"
D.Strings[28584]="我可没时间整天跟你打斗。等你的技能提升之后再来挑战我吧。"
D.Strings[28585]="坚持住，$n！这可不是容易的事情！"
D.Strings[28586]="被无情地杀戮……"
D.Strings[28587]="或者杀戮别人。"
D.Strings[28588]="我希望那些精灵和他们的德莱尼朋友现在就完蛋！"
D.Strings[28589]="去莫尔杉！"
D.Strings[28590]="召集战友！向林歌神殿进发！"
D.Strings[28591]="砍倒那片森林！把精灵赶出来！"
D.Strings[28592]="不留俘虏！"
D.Strings[28593]="如果产量不能加倍，酋长一定会把我们全都剥皮的！"
D.Strings[28594]="嗨，你完成今天的木材和精灵徽记定额了吗？"
D.Strings[28595]="我们是灰谷防御力量的中坚。我们绝不能失败！"
D.Strings[28596]="出来消灭那些联盟！"
D.Strings[28597]="你们微不足道的抵抗只能让我变得更加强大……向死亡之神屈膝投降吧！"
D.Strings[28598]="他会明白……没有谁可以永远坐在王位上，只有死亡才是永恒的！"
D.Strings[28599]="这远远不够，兽人！下马投降，否则就是死路一条！"
D.Strings[28600]="别挡道，蠢货！"
D.Strings[28601]="天哪，我从来没有想过能亲眼目睹泰坦之城奥杜尔。当布莱恩恳求我资助这支探险队时，我怎么能忍心拒绝呢？！"
D.Strings[28602]="我还以为我们没法逃出那片雾蒙蒙的丛林呢！现在，我是这支探险队的首席工程师啦。"
D.Strings[28603]="这些攻城器械有什么用处？"
D.Strings[28604]="这些宝贝儿看上去跟废铁似的，但是它们可以高速前进，猛烈地撞击敌人。器械前端的撞锤加载了可以施放电能震击的高压电容器。$B$B就连炮塔也升级成了防空火箭，使它比那些破烂攻城车更具优势。"
D.Strings[28605]="我们时间不多了，朋友们！来帮忙测试一下我所发明的最新型、最强大的机体吧。在你们改变主意之前，请允许我提醒一下，你们把XT-002搞得一团糟，应该算是欠我个人情吧。"
D.Strings[28606]="这里汇集了外域最丰富的藏书。即便是银月城的大图书馆也要相形见绌了。$B$B请……尽情享受阅读的乐趣吧。所有的书籍都已分门别类，整理得井井有条。"
D.Strings[28607]="太棒了！测试结果非常好！外壳完整率百分之九十八点九！几乎没有划伤！继续。"
D.Strings[28608]="看呀，VX-001反步兵突击炮，你们也许应该找掩护。"
D.Strings[28609]="杀死她！"
D.Strings[28610]="射击！"
D.Strings[28611]="唔！"
D.Strings[28612]="快点，蛮角，我受伤了！"
D.Strings[28613]="一道萨隆邪铁屏障环绕着维扎克斯将军！"
D.Strings[28614]="维扎克斯将军的萨隆邪铁屏障闪着微光，逐渐消失了！"
D.Strings[28615]="能找到足够的零件让这些宝贝儿重新运转起来，还真是幸运！$B我能帮你什么忙吗？"
D.Strings[28616]="跟我讲讲攻城车的作用吧。"
D.Strings[28617]="这些宝贝儿能以与众不同的方式投掷弹药。除了副炮和抓升钩，它们还配备了手动燃油喷射系统。如果你从机械侏儒身上找到了液态燃铁，就可以用它发射高密度炸药，或者启动涡轮加速器来提高行进速度。\n\n让我们瞧瞧探险者协会的傻蛋们能不能造出更高档的器械来。"
D.Strings[28618]="你们总算来啦！铁矮人迫使我们撤退到了这里，形势愈发严峻，我们就快撑不住了。\n\n更糟糕的是，他们正在强化魔法防御力量。如果再不主动出击，铁矮人就会在转眼之间将我们杀得片甲不留！\n\n我们设法修复了联盟和部落的远征军留下的部分攻城载具。但是，所有的驾驶员在上一轮攻击中都牺牲了。\n\n你必须驾驶这些器械，攻破奥杜尔的大门！\n\n$n！你是我们最后的希望！"
D.Strings[28619]="我们准备好了。发动攻击吧！"
D.Strings[28620]="我……完蛋了……"
D.Strings[28621]="$n……你为部落做了很大贡献。$b$b快一点……和卡德拉克谈谈……$b$b拯救碎木岗哨！"
D.Strings[28622]="我不会失败的，戈尔卡！"
D.Strings[28623]="完成了。大家都付出了自己该付出的。现在，我将永远封印巨龙之魂。"
D.Strings[28624]="这可怕的光芒……难道是……？"
D.Strings[28625]="是的。必须这样。"
D.Strings[28626]="这是一件与众不同的武器。一件绝无仅有的武器。"
D.Strings[28627]="是谁竟敢召唤强大的乓乓？"
D.Strings[28628]="他的族群没用多久就得到了教训。你们也快了！"
D.Strings[28629]="坏消息，陛下。"
D.Strings[28630]="兽人氏族在黑手的统一指挥下发起了攻击。他们会一致作战，直到暴风城沦陷。"
D.Strings[28631]="古尔丹和他的术士们将在晚上抵达。在那之前，黑石氏族会集中火力攻打东面的城墙。"
D.Strings[28632]="部落的领袖同意你的看法。"
D.Strings[28633]="非常感谢，朋友们！你们的帮助使我获得了一些极其珍贵的数据！下面，我要让你们——咦，我把它放哪去了？哦！这里。"
D.Strings[28634]="是不是很漂亮？我把它称为华丽的空中指挥单位！"
D.Strings[28635]="我们要坚守阵地，等待援军到达。只要勇敢的将士仍在保卫城墙和王庭，暴风城就不会沦陷。"
D.Strings[28636]="伯塔鲁斯，听见了吗？快让法师们解除护盾，勇士们要踏上征战之路啦！"
D.Strings[28637]="布莱恩，我们愿与你共同进退，请信任你的土灵兄弟们。"
D.Strings[28638]="好的，布莱恩。我们这就解除护盾。"
D.Strings[28639]="兄弟们，准备出击！尽量占领坡道上的防御点，开辟出一条安全的道路让攻城车辆通过。我们生于大地，终将回归大地。让创造者的力量在你们体内燃烧吧！"
D.Strings[28640]="达纳苏斯冠军的旗帜"
D.Strings[28641]="埃索达冠军的旗帜"
D.Strings[28642]="肯瑞托的法师们，布莱恩命令你们解除护盾！用你们的生命保卫这座平台和我们的盟友！为了达拉然！"
D.Strings[28643]="诺莫瑞根冠军的旗帜"
D.Strings[28644]="铁炉堡冠军的旗帜"
D.Strings[28645]="老大，我能为你做什么吗？"
D.Strings[28646]="暗矛冠军的旗帜"
D.Strings[28647]="被遗忘者冠军的旗帜"
D.Strings[28648]="奥格瑞玛冠军的旗帜"
D.Strings[28649]="好了！我们出发吧。钻进你的战车里，我会通过无线电跟你保持联络！"
D.Strings[28650]="银月城冠军的旗帜"
D.Strings[28651]="雷霆崖冠军的旗帜"
D.Strings[28652]="我们的盟友已经准备好了。解除护盾，前进！"
D.Strings[28653]="你用的时间实在是太久了。你还没有做好成为勇士的准备。"
D.Strings[28654]="你在对战中的反应太慢了。需要继续磨练自己的技巧。"
D.Strings[28655]="干得好！看来你完全有资格成为一名勇士！"
D.Strings[28656]="你的战斗技巧令人印象深刻。我相信以你的潜力，远不止成为一名勇士那么简单。"
D.Strings[28657]="我知道军队需要食物，但是这也太荒唐了。"
D.Strings[28658]="我还是想不通，为什么不直接召唤餐桌呢。"
D.Strings[28659]="我拥有无与伦比的奥术力量，却待在这里不停地召唤食物和水。"
D.Strings[28660]="我变成餐厅的女招待了。"
D.Strings[28661]="你确信自己已经做好成为勇士的准备了吗？我们会拭目以待的。"
D.Strings[28662]="别以为你轻而易举就能取得勇士的头衔。做好准备吧！"
D.Strings[28663]="你暂时还不能取得勇士的头衔。你可能需要更多的训练。"
D.Strings[28664]="恐怕你暂时还不能取得勇士的头衔。但是我相信你很快就会做好充分准备的。"
D.Strings[28665]="我听说过一两个关于奥达曼看门人的故事，和你的描述很像。你是否也有类似的用途呢？"
D.Strings[28666]="我的用途就是存储这座泰坦之城的重要信息。我的主要功能包括传达前沿防御系统的状况以及评估关押在这座庞大建筑物中的实体的状态。"
D.Strings[28667]="前沿防御系统？在布莱恩派人进入这座城市之前，我需要提醒他什么吗？"
D.Strings[28668]="目前，一切企图进入泰坦之城的行动都将遭到制约。主防御系统处于激活状态。次防御系统处于未激活状态。"
D.Strings[28669]="你能详细描述一下防御系统的性能吗？"
D.Strings[28670]="检测到威胁，已启动安全控制 － 允许查询。"
D.Strings[28671]="明白了。至少我们不用考虑那些轨道炮台。"
D.Strings[28672]="琳蒂安，请立即转告布莱恩和大法师伯塔鲁斯关于防御系统的事儿。"
D.Strings[28673]="被囚禁的实体？是什么实体？目前它处于什么样的状态？"
D.Strings[28674]="个体标识：尤格-萨隆。安全受到威胁。囚犯的行动状态未知。无法联络或通知到守护者。"
D.Strings[28675]="主防御系统包括铁铸像和风暴信标，后者将不断地催生更多的构造体。辅助防御系统包括轨道防御炮台。"
D.Strings[28676]="尤格-萨隆被关押在这里？看来我们有得忙了。"
D.Strings[28677]="战斗即将开始，我该离开了。另找时间继续我们的谈话吧。"
D.Strings[28678]="%s低声对布莱恩说着什么。"
D.Strings[28679]="银色盟约欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。"
D.Strings[28680]="这次不能再出错了！我可不希望这些攻城器械在战场上抛锚。"
D.Strings[28681]="但愿这是最后一辆毁在我们手里的器械。他们可是为这些东西花了大价钱的。"
D.Strings[28682]="看来你在操纵器械方面很有天分。给他们点颜色瞧瞧！"
D.Strings[28683]="如果你的朋友们能击落它，别忘记多弄点燃铁。"
D.Strings[28684]="我真想跟你一起去呢。炸翻天！"
D.Strings[28685]="希望你喜欢炸药。这可是我的专长。"
D.Strings[28686]="你会好好照顾我的宝贝儿的，对吧？战斗结束后，我可不希望在她身上看到哪怕是一块凹痕。"
D.Strings[28687]="试试新增的乘客抛掷功能吧！你们一定会喜欢的！"
D.Strings[28688]="燃铁的储备有限，省着点用。"
D.Strings[28689]="交给你啦。好好利用它吧！"
D.Strings[28690]="这些家伙可以在一瞬间就把塔楼给砸平了！"
D.Strings[28691]="我们给它们换上了更先进的装甲钢板——现在它们的抗打击能力已经很强了！"
D.Strings[28692]="炸翻他们！"
D.Strings[28693]="防空火箭可以击落那些空中运输器，这样我们就能获得更多燃铁了。"
D.Strings[28694]="我管她叫贝蒂。她很漂亮吧？"
D.Strings[28695]="相信我，它会让那些地精嫉妒死的。这简直是一件艺术品啊。"
D.Strings[28696]="它的质量远远超过了布莱恩的要求，肯定不会让你失望的。"
D.Strings[28697]="这家伙能摧毁整支钢铁部队。而且它还不会突然爆炸……比我以前见过的某些机器上等多了。具体是什么机器，我就不提了。"
D.Strings[28698]="你也来赶时髦吗？我欣赏你的品位。"
D.Strings[28699]="只要骑上这辆宝贝，谁也别想抓住你了！"
D.Strings[28700]="它已经翻修一新，随时可以出发啦。要好好待它哟！"
D.Strings[28701]="我们给这些家伙装上了可爱的小喇叭。希望你会喜欢！"
D.Strings[28702]="好好利用那些焦油。如果你的朋友够聪明的话，就应该知道怎么点燃它们。"
D.Strings[28703]="天生狂野！"
D.Strings[28704]="风掠过头发的感觉真是酷毙了！不过你最好戴上护目镜。我敢打赌，那些铁矮人一定会被你吓得乱作一团。"
D.Strings[28705]="围着他们转圈！"
D.Strings[28706]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失2%%|r"
D.Strings[28707]="控制台显得非常陈旧，却没有一丝破损或是荒废的迹象。上面刻有一道插槽，似乎可以放入大型的圆盘。"
D.Strings[28708]="|cFFCCCCCC%s将自己装填进了攻城车的发射臂。$B武器系统处于离线状态，直至发射成功。|r"
D.Strings[28709]="你做好和勇士战斗的准备了吗？"
D.Strings[28710]="别以为你可以轻而易举地战胜一位勇士。你确定自己已经准备好了吗？"
D.Strings[28711]="你做好与我交战的准备了吗？"
D.Strings[28712]="预备！"
D.Strings[28713]="开始！"
D.Strings[28714]="我该如何学习双天赋专精？"
D.Strings[28715]="看来你还需要多加练习。我们还是下次再打吧。"
D.Strings[28716]="我希望学习双天赋专精。"
D.Strings[28717]="你确定要购买双天赋专精吗？"
D.Strings[28718]="我认输。"
D.Strings[28719]="看来我低估了你的本事。干得不错。"
D.Strings[28720]="刚才的战斗很精彩。我认输。"
D.Strings[28721]="%s因同伴的死而震怒！"
D.Strings[28722]="要想打败我，你恐怕还得多加练习。"
D.Strings[28723]="我赢了。祝你下次好运，朋友。"
D.Strings[28724]="等我们以银月城的名义赢下这场锦标赛时，荣耀将属于我们。"
D.Strings[28725]="你现在已经学会了双天赋专精。"
D.Strings[28726]="看来你已经做好晋级为冠军的准备了。"
D.Strings[28727]="令人印象深刻啊。你完全有资格成为冠军。"
D.Strings[28728]="我们来到这里，为荣耀而战，为名誉而战，为获得与银色北伐军的兄弟们并肩作战的资格而战。"
D.Strings[28729]="麦格尼国王希望我们赢得锦标赛的胜利。我们绝不能失败。"
D.Strings[28730]="诺莫瑞根的精英来参加锦标赛啦。祝我们好运！"
D.Strings[28731]="你觉得自己已经做好了晋级冠军的准备？让我们拭目以待吧。"
D.Strings[28732]="你觉得自己已经做好了晋级冠军的准备？小心了！"
D.Strings[28733]="达纳苏斯的精灵们希望在锦标赛中一展身手。"
D.Strings[28734]="看来你还没有做好晋级为冠军的准备。最好多加练习。"
D.Strings[28735]="你输了。不要放弃。我有预感，总有一天你会加入我们的行列，成为一名冠军。"
D.Strings[28736]="这次测试用了太久的时间。你还不足以成为一名冠军。"
D.Strings[28737]="你的表现应该更好才对。这场战斗简直是在浪费我的时间。你还不足以成为一名冠军。"
D.Strings[28738]="锦标赛开始后，所有人都将见证被遗忘者的胜利。"
D.Strings[28739]="竞争会非常激烈，但是奥格瑞玛的勇士是所向披靡的。"
D.Strings[28740]="我们不仅为荣耀而战，还要为我们的先祖和人民赢得光荣。"
D.Strings[28741]="暗矛氏族已经做好了竞争的准备。"
D.Strings[28742]="我代表夺日者欢迎你参加锦标赛。银色北伐军委托我们登记并训练那些对比赛感兴趣的选手。"
D.Strings[28743]="你做好和银色北伐军勇士作战的准备了吗？"
D.Strings[28744]="当你准备好参加勇士的晋级测试后，我会召来一位银色北伐军的成员。"
D.Strings[28745]="这座竞技场专供冠军们互相切磋之用。我负责召唤骑兵来参加战斗练习。"
D.Strings[28746]="让加文召唤黑骑士。"
D.Strings[28747]="$n向黑骑士发起挑战！"
D.Strings[28748]="有人正在进行挑战。战斗结束后才能使用竞技场。"
D.Strings[28749]="黑骑士被击败了！"
D.Strings[28750]="我受够了你的傲慢！去死吧！"
D.Strings[28751]="正在关闭。"
D.Strings[28752]="你可真好，美人！愿意和我们永远留在一起！"
D.Strings[28753]="欢迎，朋友，欢迎！这里永远都会为新朋友留下位置！"
D.Strings[28754]="嗨！我叫尤希尔。等你死了，我们一定能成为好朋友的！"
D.Strings[28755]="生长吧，小家伙。"
D.Strings[28756]="帮我们抵御这刺骨的寒风吧，小树苗。"
D.Strings[28757]="祝你好运。等广场清理干净后，我就到里面去跟你会合。"
D.Strings[28758]="开始行动，别让那些矮人妨碍我们！"
D.Strings[28759]="后退，$n。我必须净化森林之心。"
D.Strings[28760]="我们的工程师挂掉了，事情好像要糟糕！"
D.Strings[28761]="森林之心已经被净化了。它的力量将再一次充盈灰谷。年轻人，我们将永远感激你的英勇行为。"
D.Strings[28762]="给我们一点时间，做好建筑炮台的准备。"
D.Strings[28763]="火灭了！准备重建炮台！"
D.Strings[28764]="俺可不喜欢地面乱晃……"
D.Strings[28765]="出……出了什么事！？！"
D.Strings[28766]="碎木岗哨遭到了攻击！！"
D.Strings[28767]="碎木岗哨被包围了！"
D.Strings[28768]="%s对自己施放了虚空屏障，阴影在它的周围汇聚了起来！"
D.Strings[28769]="我们到底是怎样到这里的？"
D.Strings[28770]="看看地面在哪里！让我来驾驶。"
D.Strings[28771]="赶快去工作！我们的进度已经落后了！"
D.Strings[28772]="挖！挖！挖！"
D.Strings[28773]="快点挖！矿石不会自己蹦出来！"
D.Strings[28774]="没时间休息了，快回去工作！"
D.Strings[28775]="你们击败了钢铁议会，打开了档案馆！干得好，伙计们！"
D.Strings[28776]="支持你最喜欢的冠军吧！下一回合时，穿上和他们的代表色一致的衣服，让大家都看看你喜欢谁！"
D.Strings[28777]="你是否已经厌倦了与野兽扭打，想要换个方式来展示自己的本事？无论你来自哪座城市，我都可以满足你的愿望！"
D.Strings[28778]="嘿！瞧瞧这些紧身衣！穿上它，既有了城市的代表色，又省去了宽松的战袍带来的麻烦事儿！"
D.Strings[28779]="本次锦标赛是数个世纪以来最盛大的赛事！买点纪念品回家送给家人和孩子吧！"
D.Strings[28780]="$n在喘着粗气！"
D.Strings[28781]="小心啊，$n！"
D.Strings[28782]="$n，坚强点！"
D.Strings[28783]="用力揍他们，$n！"
D.Strings[28784]="真不敢相信，$n居然还能站在场地上！"
D.Strings[28785]="别放松警惕，$n！"
D.Strings[28786]="别放弃，$n！"
D.Strings[28787]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失4%%|r"
D.Strings[28788]="你不能离开银色锦标赛的赛场。"
D.Strings[28789]="%s吞噬了一个废料机器人以进行自我修复！"
D.Strings[28790]="可以使用鱼叉炮台了！"
D.Strings[28791]="就是你！我们急需有能力的人。许多人的生命都在等待你去拯救！"
D.Strings[28792]="高墙内的秘密远远超越了我们的想象。"
D.Strings[28793]="女祭司，我带来了消息，现在有更多的幸存者来到这里。他们正在竭尽全力寻找还活着的人。请尽量派遣人手来帮助我们！"
D.Strings[28794]="明白了，哨兵，回到海滩上，帮助他们将还活着的人救回来。"
D.Strings[28795]="当伤员到达时，我们要将他们安置在旅店里，照料他们。你回来的时候，就请去那里找我们吧。"
D.Strings[28796]="当然，女祭司。"
D.Strings[28797]="科隆加恩施放了岩石之握！"
D.Strings[28798]="你做好与冠军作战的准备了吗？"
D.Strings[28799]="别以为你可以轻而易举地战胜一位冠军。你确定自己已经准备好了吗？"
D.Strings[28800]="%s旋转着，发出可怕的“嘟嘟”声……"
D.Strings[28801]="结束这一切吧！"
D.Strings[28802]="开始分析守护者弗蕾亚的状态。"
D.Strings[28803]="古树仆从的存在增强了守护者的力量。"
D.Strings[28804]="正在分析明叶长老的强化效果……太阳能增效提供了永久的区域性防护力增强。"
D.Strings[28805]="石树长老的分析结果表明，他的声波防御能力足以干扰魔法的使用。"
D.Strings[28806]="铁枝长老的扫描结果显示，存在基于植物功能的移动阻碍机制。"
D.Strings[28807]="另外，我的分析表明，每位古树长老的存在都令弗蕾亚的魔法能力、物理攻击或召唤能力得到增强。"
D.Strings[28808]="摧毁古树仆从可以导致守护者弗蕾亚失去这些增强效果。但是也极可能对弗蕾亚自身及其携带的物品，包括她的守护者徽记，造成永久性的伤害。"
D.Strings[28809]="开始分析守护者托里姆的状态。"
D.Strings[28810]="检测到外部影响。其存在方式是伪装成托里姆已故的配偶西芙。"
D.Strings[28811]="这一外部影响所导致的心智干扰极可能触发局部的记忆损伤。"
D.Strings[28812]="开始分析守护者霍迪尔的状态。"
D.Strings[28813]="霍迪尔的徽记被放在一只用来保存神器的宝箱中。"
D.Strings[28814]="守护者霍迪尔的情绪和行为极度不稳定。如果战斗时间过长，极可能导致宝箱损毁。"
D.Strings[28815]="与盟军协同作战可以提高战斗力，使战斗时长降到最短。"
D.Strings[28816]="开始分析守护者米米尔隆的状态。"
D.Strings[28817]="守护者米米尔隆的徽记与一套自毁系统相关联，该系统又与发明回廊的完整性相关联。"
D.Strings[28818]="这套自毁系统的触发装置被称为“红色大按钮”，由米米尔隆自行制造。"
D.Strings[28819]="要获取米米尔隆的徽记，必须初始化自毁程序，并在流程执行完毕之前击败它。"
D.Strings[28820]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失12%%|r"
D.Strings[28821]="嗯，$c，这很……巧妙。"
D.Strings[28822]="我必须继续履行我的职责，$c。"
D.Strings[28823]="拒绝登录。权限级别不足。"
D.Strings[28824]="已获得档案馆访问权限。入侵保护机制暂停。"
D.Strings[28825]="正在初始化问询。奥尔加隆保险系统是一套在首席管理官死亡时触发的自动化紧急信号系统。"
D.Strings[28826]="正确。首席管理官洛肯被毁灭与信号被激活的时间戳相符。"
D.Strings[28827]="正在搜索……首席管理官的毁灭被判定为系统级行星故障的第一道报警信息。观察者奥尔加隆抵达之后所展开的行星分析，可能产生两种回复代码中的一种。回复代码阿尔法代表“一切正常”；回复代码欧米迦代表“行星结构重组”。"
D.Strings[28828]="行星自身与其所承载的生命体将解离为基础元素：金属、岩石和气体。随后，这些元素将按照最初的行星蓝图完成重组。"
D.Strings[28829]="请求被拒绝。回复代码内建于奥尔加隆的躯体中。他既是信使，也是信号本身。"
D.Strings[28830]="奥尔加隆检测到了侵入关键行星功能的系统级上古之神污染。正在计算产生欧米迦回复代码的几率……"
D.Strings[28831]="百分之九十九点九九。"
D.Strings[28832]="小数点后无限循环。"
D.Strings[28833]="看哪，这就是我们所说的重大发现！"
D.Strings[28834]="我叫你看看我的权限，你这烂机器。瞧好了：诺甘农的钥匙！"
D.Strings[28835]="看起来跟我们找到的其它泰坦档案库也没什么不同嘛，只不过旧了点……大了点。"
D.Strings[28836]="且慢。不对啊！这个一闪一闪的信号灯……奥尔加隆是啥玩意？"
D.Strings[28837]="首席管理官？我在哪里听过这名字来着？对了！洛肯就是艾泽拉斯的首席管理官啊。洛肯的死亡触发了这东西？"
D.Strings[28838]="然后呢？谁在监听这个信号？会发生什么事情吗？"
D.Strings[28839]="行星结构重组？把话说明白点，你这破烂！"
D.Strings[28840]="听到了吗，伙计们？我们的世界要完蛋了！你还等什么啊，破烂机器？快发送回复代码阿尔法。一切正常！尽在掌握中！"
D.Strings[28841]="啊，这个奥尔加隆分析出了什么结果来？我们有多大的几率不被毁灭？"
D.Strings[28842]="真要命啊，伙计们。看来我们有一场硬仗要打了。"
D.Strings[28843]="战争之血"
D.Strings[28844]="位移石板被激活并稳定下来了。"
D.Strings[28845]="传送到远征军营地。"
D.Strings[28846]="传送到练兵场。"
D.Strings[28847]="传送到巨人熔炉。"
D.Strings[28848]="传送到废料场。"
D.Strings[28849]="传送到奥杜尔的前厅。"
D.Strings[28850]="传送到破碎步道。"
D.Strings[28851]="传送到生命温室。"
D.Strings[28852]="传送到思想火花。"
D.Strings[28853]="传送到疯狂阶梯。"
D.Strings[28854]="我谨代表银色北伐军，欢迎你参加银色锦标赛。"
D.Strings[28855]="布拉斯波兄弟的建筑工程是速度最快，造价最低、质量最上乘的！"
D.Strings[28856]="%s被永久地禁锢在地面上！"
D.Strings[28857]="新的指令！打开天文馆的大门。"
D.Strings[28858]="四位守护者？徽记？你这废铜烂铁，说话能不能别这么拐弯抹角啊？"
D.Strings[28859]="那我们怎样才能搞到他们的徽记啊？走过去跟他们好声好气地借吗？"
D.Strings[28860]="那你倒是告诉我们怎样才能解除这种威胁啊？"
D.Strings[28861]="多少年来，我做梦都想在泰坦之城游览。没想到今天居然要跟他们创造的东西作战。"
D.Strings[28862]="请求被拒绝。需要四位守护者的徽记进行权限确认。"
D.Strings[28863]="奥杜尔的四位守护者是：弗蕾亚、托里姆、霍迪尔和米米尔隆。他们的徽记与其本体及心智的完整性密切相关。要进入天文台，就必须拥有全部四枚徽记。"
D.Strings[28864]="正在分析守护者的状态。请稍候。"
D.Strings[28865]="检测到腐蚀。外部影响已经控制了守护者。徽记受到威胁。"
D.Strings[28866]="足够的冲击力可以使守护者重启动，消除外部影响。"
D.Strings[28867]="为了在这一过程中不对徽记造成损伤，我可以分析每位守护者的状态，并根据计算结果给出具体建议。"
D.Strings[28868]="一个%s开始攻击伐树者。"
D.Strings[28869]="一个灵魂现身了，它要为晶歌森林橡树复仇！"
D.Strings[28870]="一个%s从濒死的晶歌森林橡树中现身了！"
D.Strings[28871]="能协助布莱恩探索泰坦古城奥杜尔的秘密真是莫大的荣幸。"
D.Strings[28872]="我所知道的关于探险的知识，都是布莱恩教给我的。"
D.Strings[28873]="住手！我认输了！"
D.Strings[28874]="我觉得自己像是从一场噩梦中惊醒过来，但是这里的阴影仍然挥之不去。"
D.Strings[28875]="西芙……西芙在这里吗？不可能——她被我的兄弟杀死了。一场黑暗的噩梦……"
D.Strings[28876]="我需要一些时间仔细思考……如果你们需要我的帮助，请尽管开口。这是我欠你们的人情。保重。"
D.Strings[28877]="你！你这个恶魔，你不是我的爱人！滚开！"
D.Strings[28878]="看吧，这隐藏在一切罪恶幕后的黑手，它覆灭了奥杜尔，将我的王国夷为废墟，腐蚀了我的兄弟，杀害了我的妻子。"
D.Strings[28879]="现在，为我们复仇的重任落到了你们的肩膀上，勇士们。前方的路途依然无比艰险，但我会鼎力相助。你们必须取得胜利。"
D.Strings[28880]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失100%%|r"
D.Strings[28881]="死吧，精灵！！"
D.Strings[28882]="力量与荣耀！！"
D.Strings[28883]="鲜血与雷鸣！！"
D.Strings[28884]="|TInterface\\Icons\\Spell_Arcane_MindMastery.blp:24|t|cFFFF8900 理智损失9%%|r"
D.Strings[28885]="站好了，凝视这耀眼的光芒吧！"
D.Strings[28886]="$c，很高兴见到你。$B$B我负责向候选者传授骑乘近身战的诀窍。"
D.Strings[28887]="教我如何与近战目标作战吧。"
D.Strings[28888]="这是什么，小凡人……$b$b嗯……是$r？我能为你做些什么？"
D.Strings[28889]="初步测试阶段完成。真正的测试开始啦！"
D.Strings[28890]="$c？这是什么？"
D.Strings[28891]="近战目标可以帮助候选者训练骑乘攻击与防御的技巧。$B$B你需要靠近并刺击近战目标。刺击的力量通常会令目标旋转起来，对你或你的坐骑造成伤害。因此，你需要巧妙地利用防御技能。$B$B在攻击目标之前，最好确保自己至少有一层防御效果。在接下来的战斗中，你还需要尽可能地堆叠并刷新防御效果。否则，你很快就会被打下坐骑。$B$B在骑乘实战中遵循着同样的原则：在攻击与防御之间寻求平衡，一有机会就发动刺击，并尽可能保持多层防御效果。"
D.Strings[28892]="很高兴见到你，$n。$b$b一切都在按照计划进行吧？"
D.Strings[28893]="杜莱克，我失去了伪装！"
D.Strings[28894]="回去工作，废物！我们的进度已经落后了！"
D.Strings[28895]="不要让小小的精灵进攻干扰你的工作！"
D.Strings[28896]="继续挖！矿石可不会自己蹦出来！"
D.Strings[28897]="嗨，你好！$B$B你是来学习冲锋技巧的吗，$c？"
D.Strings[28898]="教我如何与冲锋目标作战吧。"
D.Strings[28899]="好吧！骑乘冲锋可不仅仅是让你的坐骑高速冲刺，体验那种心飙到嗓子眼的快感……当然这的确是最有趣的部分，嘿嘿！但是冲锋目标可以帮助你掌握更多诀窍。$B$B冲锋的关键在于距离与时机。不能靠得太近，否则无法全力提速。也不能离得太远，否则坐骑就会进入疲惫状态！至于冲锋的时机……$B$B在冲锋之前，你最好确认一下冲锋目标身上是否有防御效果。如果有，你应该先使用碎盾然后再冲锋！$B$B实战中遵循着同样的原则：在冲锋前要尽可能地削弱对手的防御效果！"
D.Strings[28900]="%s捉住了一条鱼！"
D.Strings[28901]="哎呀。又一位$c，你是来学习碎盾的技巧的吗……？"
D.Strings[28902]="教我如何与远程目标作战吧。"
D.Strings[28903]="远程碎盾攻击上手容易精通难。碎盾攻击所能造成的伤害不高，但是配合刺击和冲锋使用就能发挥出完美的效果，令你在骑乘作战中所向披靡。$B$B选定一个远程目标，估算一下碎盾攻击的射程……你需要多远的距离以及你能将长枪掷多远。$B$B接下来，就开始投掷长枪吧，直到你破坏目标身上的所有防御效果。$B$B骑乘实战中遵循着同样的原则：彻底粉碎对手的防御……然后狠狠地揍他们！"
D.Strings[28904]="我们收到了布莱恩的消息，已经开始着手做准备了。"
D.Strings[28905]="达拉然的公民们！抬起你们的头，仰望天空吧！"
D.Strings[28906]="今天，我们所生活的这个世界，险些被它的缔造者毁灭！"
D.Strings[28907]="我们勇敢的伙伴们深入泰坦之城奥杜尔，击败了观察者奥尔加隆，泰坦派来的使者！"
D.Strings[28908]="奥尔加隆前来决定我们这个世界的命运。"
D.Strings[28909]="他发现，在这个世界中，人们并不接受泰坦设计的蓝图。在这个世界中，并非一切都按照计划完美运行。"
D.Strings[28910]="冷酷的逻辑推论出：我们的世界不值得拯救。但是，它并没有考虑到自由意志的力量。我们每一个人都有责任证明，这是一个值得拯救的世界。"
D.Strings[28911]="因为我们的生命……是值得延续的生命。"
D.Strings[28912]="%s用被遗忘者语言自言自语着。"
D.Strings[28913]="弗蕾亚施放了|cFF00FF00强化钢铁根须！|r"
D.Strings[28914]="%s狂暴了，摧毁了所有生命体！"
D.Strings[28915]="看吧，这创世的神器！"
D.Strings[28916]="你们的行动不合逻辑。这场战斗所有可能产生的结果都已被计算在内。无论结果如何，万神殿都会收到观察者发出的信息。"
D.Strings[28917]="生命的凋零，不可避免。"
D.Strings[28918]="我必须这么做。"
D.Strings[28919]="通过我的双眼来观察你们的世界吧：一个广袤无垠的宇宙，即使是你们当中最睿智的人，也无法理解这一切。"
D.Strings[28920]="当心……"
D.Strings[28921]="我曾见证过无数个世界被造物者的烈焰吞噬，那些世界中的人们甚至来不及发出一声悲鸣就永远消逝了。整个星球从诞生到毁灭，不过是弹指一挥间。但是从始至终，我都没有为之动容……我，毫无，感觉。千亿的生命被毁灭。他们是否都像你们一样坚强？他们是否都像你们一样热爱生命？"
D.Strings[28922]="高尔巴格带我游览了达卡莱帝国。我很乐意帮助你征服它！"
D.Strings[28923]="朋友，你来得正是时候。很快我就会给你安排更多的任务了……"
D.Strings[28924]="%s过载了！"
D.Strings[28925]="我狠狠地教训了那些荒芜恶鬼！"
D.Strings[28926]="分析完成。这个星球的生命支持系统受到了部分腐蚀，而防御机制则完全被腐蚀了。"
D.Strings[28927]="我看出来了。荒芜水晶的储量大增，很快就能满足需求了。"
D.Strings[28928]="我已经击败了达穆克！你还需要我做什么吗？"
D.Strings[28929]="达穆克这个饭桶再也不能惹麻烦了！耐心点，朋友。很快就会有更多的工作交给你做了……"
D.Strings[28930]="我已经俘获了达卡莱酋长！你还需要我做什么吗？"
D.Strings[28931]="也许正是这种不完美，才使你们获得了自由的意志，并因此有能力改变那些看起来不可避免的必然命运。泰坦所创造的许多完美生命体都遭遇了失败，而你们仍能继续前行。"
D.Strings[28932]="我已经修改了回复代码，你们的行星得救了。我不能再对自己的计算结果深信不疑了。"
D.Strings[28933]="启动上行通讯：回复代码“欧米迦”。请求启动行星组织重构。"
D.Strings[28934]="再会了，凡人们。你们是不完美的生命体，但你们的勇气值得钦佩。"
D.Strings[28935]="我没有足够的力气去发射信号。你们必须……尽快……找到一处发射场……要靠近天空。"
D.Strings[28936]="我知道该去哪里。你没事吧？"
D.Strings[28937]="不用担心我的命运，布隆赞。如果信号没有及时发射出去，行星结构重组仍然会自行启动。拯救……你们的世界……"
D.Strings[28938]="除掉那些酋长之后，我们就准备发动攻击了！用不了多久的，$n……"
D.Strings[28939]="达库鲁，我亲眼目睹了你精妙的部署。什么时候执行攻占达卡莱帝国的计划呢？"
D.Strings[28940]="朋友，眼下的形势你已经了如指掌了！做好准备吧……我们很快就要发动攻击了！"
D.Strings[28941]="%s张开了大嘴！"
D.Strings[28942]="%s分崩离析了。"
D.Strings[28943]="洛丹伦沦陷时，我正在这里拜访亲戚……唉。我大概再也不能回到西部荒野了。$B$B有时我会思念家人，也不知他们是否依然健在。但是更多的时候，我的内心平静地如同一滩死水，好像没有什么能让我牵挂的了。"
D.Strings[28944]="我们成功了，伙计们！终于抢在奥尔加隆前面来到了这儿……也许我们可以对系统做点手脚，改变他的分析结果……"
D.Strings[28945]="迁移完成。开始对艾泽拉斯展开行星分析。"
D.Strings[28946]="退后，凡人们。我不是来这里跟你们打架的。"
D.Strings[28947]="如果我的分析结果表明确实存在系统级的污染，对这颗行星进行结构重组无疑是最妥当的方案。不要插手。"
D.Strings[28948]="我这就回档案馆，看看能不能堵塞他的信号。在你们对付他的同时，我努力多争取一点时间。"
D.Strings[28949]="去熟悉一下技能吧。"
D.Strings[28950]="给自己加上防御。$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B然后对近战目标使用刺击。$B|TInterface\\Icons\\INV_Sword_65.blp:32|t"
D.Strings[28951]="庄严地注目它吧！沐浴在它的荣耀中吧！将要出场的是……V-07-TR-0N！"
D.Strings[28952]="对冲锋目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标处于脆弱状态时立即冲锋。$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t"
D.Strings[28953]="对远程目标使用碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B趁目标毫无防御力时再次碎盾。$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t"
D.Strings[28954]="这只碗里散发出强烈的气味，闻起来好象是各种草药和燃烧的毛发混合在一起。"
D.Strings[28955]="通往%s思维的传送门打开了！"
D.Strings[28956]="守护者分析：弗蕾亚"
D.Strings[28957]="守护者分析：霍迪尔"
D.Strings[28958]="我已经准备好和你一起去碎木岗哨了，卡德拉克！"
D.Strings[28959]="守护者分析：托里姆"
D.Strings[28960]="守护者分析：米米尔隆"
D.Strings[28961]="一只风暴爪牙冒出来帮助埃玛尔隆作战！"
D.Strings[28962]="吸入这股烟雾，吸引动物巨灵的注意。"
D.Strings[28963]="我很快就会回来找你的，卡德拉克！"
D.Strings[28964]="蛮角正在外面给那些矮树丛浇水。$b$b不过不要走太远，$n。他应该很快就会为我们前往碎木岗哨的旅程做好准备。"
D.Strings[28965]="现在……见证战斗科多兽在一位大师手中所能发挥出的力量吧！"
D.Strings[28966]="%s高声喊道：“我会报仇的！”"
D.Strings[28967]="前往碎木！"
D.Strings[28968]="你以为自己能跟不生不死的军团抗衡？"
D.Strings[28969]="反抗……凡人性的瑕疵。"
D.Strings[28970]="你们的失败是命中注定的。"
D.Strings[28971]="你们的毁灭预示着痛苦的新时代即将降临！"
D.Strings[28972]="哦，真正的恐惧还在前方……"
D.Strings[28973]="尤格-萨隆的黑血在我的体内奔涌！我，无坚不摧！"
D.Strings[28974]="看吧，绝对的恐怖！"
D.Strings[28975]="战术分析结果显示，最佳方案为从前方进入竞技场，同时派遣另一支分队通过位于底层的小路。要在外部影响完全控制托里姆的心智之前抵达他所在的高台，这是成功率最高的方案。"
D.Strings[28976]="请坚持一段时间不要动。"
D.Strings[28977]="正在进行碎片分析。"
D.Strings[28978]="目标确认：瓦兰奈尔，远古王者之锤。"
D.Strings[28979]="泰坦亲自铸造了瓦兰奈尔，并将其交给了第一位土灵之王，尤雷尔·石心。通过这柄圣锤，他可以制造新的土灵，并赐予他们生命。"
D.Strings[28980]="在土灵和铁矮人之间爆发的第一次战争中，瓦兰奈尔碎裂了。据信它的残片已在战争中遗失。"
D.Strings[28981]="通过这个世界上实际存在的常规手段修复瓦兰奈尔的可能性趋近于零。正在分析理论上可能存在的修复方式，请稍候。"
D.Strings[28982]="在名为尤格-萨隆的生物体内，理论上存在一种酸性极强的物质，可以将萨隆邪铁液化。泰坦铸成的合金可能通过浸没在此物质中重新熔合。"
D.Strings[28983]="孢子蝠"
D.Strings[28984]="狡诈宠物"
D.Strings[28985]="狂野宠物"
D.Strings[28986]="坚韧宠物"
D.Strings[28987]="小家伙，帮助你的同伴吧。这场战斗需要你们齐心协力！"
D.Strings[28988]="向你致敬，勇士。奥杜尔的大厅中回荡着尤格-萨隆挫败的惨叫声。"
D.Strings[28989]="土狼"
D.Strings[28990]="巨蛾"
D.Strings[28991]="陆行鸟"
D.Strings[28992]="巨蜂"
D.Strings[28993]="熊"
D.Strings[28994]="螃蟹"
D.Strings[28995]="鳄鱼"
D.Strings[28996]="猩猩"
D.Strings[28997]="海龟"
D.Strings[28998]="来得正是时候。我们赶紧搞定这件事吧。"
D.Strings[28999]="%s发出劈啪声，浑身涌动着原始的力量！"
D.Strings[29000]="看起来我的计算有一点小小的偏差。监狱中的恶魔侵蚀了我的思维，篡改了我的主要指令。所有系统都已恢复正常。完毕。"
D.Strings[29001]="让他们明白鲜血与雷鸣的意义！"
D.Strings[29002]="结束了。我们还需要再等待一段时间，这个祝福才能生根发芽。但只要你在黑海岸，随时都能接受这一祝福。愿你继续为自然贡献力量。"
D.Strings[29003]="你必须骑上锦标赛坐骑，我才能教你如何骑乘作战。$B$B拿上一支长枪，然后从你所在阵营的兽栏中挑选一匹坐骑吧。"
D.Strings[29004]="我想知道更多关于防御和刺击的技巧。"
D.Strings[29005]="我想知道更多关于碎盾的技巧。"
D.Strings[29006]="我想知道更多关于冲锋的技巧。"
D.Strings[29007]="现在，终于有真正的鲜血与雷鸣了！"
D.Strings[29008]="想要坐骑吗？"
D.Strings[29009]="我能帮你做些什么？"
D.Strings[29010]="很高兴见到你。"
D.Strings[29011]="在找坐骑吗？"
D.Strings[29012]="你好，$c。"
D.Strings[29013]="有一点冷，你觉得呢？"
D.Strings[29014]="很高兴看到你平安无事。"
D.Strings[29015]="只有暴风城的勇士才有资格从我这里购买物品。"
D.Strings[29016]="我要去玛塞斯特拉废墟。"
D.Strings[29017]="你的死亡将是一个新生命的开端！"
D.Strings[29018]="我要去碎矛谷。"
D.Strings[29019]="我要去巴莎兰。"
D.Strings[29020]="我要去洛达内尔。"
D.Strings[29021]="现在不远了……"
D.Strings[29022]="碎木岗哨……"
D.Strings[29023]="我们必须打破敌人的围攻！"
D.Strings[29024]="主人，温室已经被攻破了！"
D.Strings[29025]="急什么呢，$r！$B$B只有铁炉堡的勇士才有资格从我这里购买物品。"
D.Strings[29026]="兄弟们，打开大门！让我们以真正的部落风格欢迎我们的来访者！"
D.Strings[29027]="肥料。"
D.Strings[29028]="你的尸体将滋养这片土地。"
D.Strings[29029]="很抱歉，$r。只有雷霆崖的勇士才有资格从我这里购买物品。"
D.Strings[29030]="主人，我不行了！"
D.Strings[29031]="走吧，$r！$B$B只有幽暗城的勇士才有资格从我这里购买物品。"
D.Strings[29032]="凡人不许进入这里！"
D.Strings[29033]="从哪里来，就回哪里去！"
D.Strings[29034]="弗蕾亚！他们冲你来了。"
D.Strings[29035]="只有奥格瑞玛的勇士才有资格从我这里购买物品。"
D.Strings[29036]="只有埃索达的勇士才有资格从我这里购买物品。"
D.Strings[29037]="这里将成为你们的墓地。"
D.Strings[29038]="真是浪费……"
D.Strings[29039]="嗨，朋友！$B$B很抱歉，只有诺莫瑞根的勇士才有资格从我这里购买物品。"
D.Strings[29040]="主人，快逃！他们非常残忍！"
D.Strings[29041]="哎呀，只有达纳苏斯的勇士才有资格从我这里购买物品。"
D.Strings[29042]="萨玛巴认为你找错了军需官！$B$B只有森金村的勇士才有资格从她这里购买物品。"
D.Strings[29043]="我要把你彻底捏碎！"
D.Strings[29044]="哎呀，只有银月城的勇士才有资格从我这里购买物品。"
D.Strings[29045]="主人，他们来了……"
D.Strings[29046]="不疼不痒！"
D.Strings[29047]="只是轻伤而已！"
D.Strings[29048]="快看你正前方那些柱子底部的掩体，铁矮人正源源不断地从里面冒出来！摧毁那些掩体，他们就不得不撤退了！"
D.Strings[29049]="小心！我们的空中侦察人员报告说，导弹发射井的能源塔已经开始启动了！"
D.Strings[29050]="总共有四座能源塔为这些防御设施提供能量。如果你们能炸掉那些塔，导弹攻击就会立即停止！"
D.Strings[29051]="这座塔为霍迪尔之锤提供能量。据说它可以把整支军队冻成冰块！"
D.Strings[29052]="这就是弗蕾亚之塔。它所拥有的力量可以在一夜之间将贫瘠的荒漠变成生机盎然的丛林。"
D.Strings[29053]="这座塔为米米尔隆之眼提供能量。只要一瞬间的工夫，它就可以把大地烧成灰烬，石块熔为岩浆——绝不能让它达到最大功率！"
D.Strings[29054]="啊，科洛米尔之塔。据说托里姆的威力只展现过一次……结果就是整整一块陆地变成了灰尘。"
D.Strings[29055]="导弹能量塔的控制器就在塔顶。如果你能想办法上去，就可以自己动手关掉它。"
D.Strings[29056]="你附近似乎有一座维修站！把你的座驾开到平台上去，接受自动修理。"
D.Strings[29057]="成功了！你瓦解了奥杜尔的防御设施。用不了多久，我们就可以进入……"
D.Strings[29058]="那是什么？当心！有什么东西朝你去了！"
D.Strings[29059]="小心！规避动作！规避——"
D.Strings[29060]="一定要到城东南的桥那里去看看。你应该能在那里得到一头夜刃豹，载你到废墟那里去。"
D.Strings[29061]="不要忘记在城东南的桥附近看看，你能在那里找到坐骑，前往我们的前哨站。"
D.Strings[29062]="蛮角，让他们付出代价！"
D.Strings[29063]="我们成功了，伙计们！终于抢在奥尔加隆前面来到了这里。也许我们可以对系统做点手脚，改变他的分析结果——"
D.Strings[29064]="%s激活了野性防御者！"
D.Strings[29065]="你的血肉将不再属于你！"
D.Strings[29066]="鲜血与雷鸣！"
D.Strings[29067]="把他们赶回去！赶回到达纳苏斯！"
D.Strings[29068]="把你们的脏爪子翻到的任何纸片儿都送来给我过目。"
D.Strings[29069]="我说过了，在你吃尸体前都先给我好好搜查一下！"
D.Strings[29070]="要把每块石头都翻一遍。执行我的命令，不许有半点折扣，烂家伙！如果有必要，就把这个地方翻个底朝天。"
D.Strings[29071]="下马来，敢不敢和我单挑！"
D.Strings[29072]="%s准备施放暗影强化！"
D.Strings[29073]="蛮角……不！！！"
D.Strings[29074]="所有人……立刻返回碎木岗哨！"
D.Strings[29075]="搞到这些替换器械可不容易。别让我们白费力气，好吗？"
D.Strings[29076]="这次你一定能击溃他们。不要手软！"
D.Strings[29077]="备用攻城器械立即送货上门。还有比这更好的服务吗？"
D.Strings[29078]="上一轮不过是热身而已！这次你一定要成功！"
D.Strings[29079]="别担心，我们已经备好了替换器械。你也知道，这种任务很难一次成功的嘛。"
D.Strings[29080]="嗨，瞧这辆大型攻城坦克！你可比我厉害多了。祝你好运！"
D.Strings[29081]="我们永远支持你……唔，我们这就开始修理这成堆的攻城器械。"
D.Strings[29082]="啊，我说过让你好好照顾她的。你知道我在她身上倾注了多少心血吗？这次你可得小心点。"
D.Strings[29083]="%s悄无声息地滑入了草丛中。"
D.Strings[29084]="围攻被击退了……至少暂时是如此。跟随我去碎木岗哨吧。"
D.Strings[29085]="不行。我完全搞不明白这玩意儿是如何运作的。"
D.Strings[29086]="我不会让你失望的，主人！"
D.Strings[29087]="别灰心。如果这确实是传送器的话，那它对我们的进攻行动会很有帮助的。"
D.Strings[29088]="嗯，我知道……我会继续尝试的。不过你也别抱太大的希望，这种科技完全超越了我能理解的范围。"
D.Strings[29089]="你们微不足道的抵抗只能让我变得更加强大。"
D.Strings[29090]="这该死的玩意儿总算运行起来了！它可以将你传送到广场尽头，就是之前你们与烈焰巨兽战斗的地方。"
D.Strings[29091]="我们把备用的攻城器械都抬上来啦，这次你一定能把那家伙打倒。祝你好运！"
D.Strings[29092]="把它撕成碎片吧！"
D.Strings[29093]="感谢大家参加此次布道会。看到这么多熟悉的面孔真是令人欣慰！"
D.Strings[29094]="今天，我要谈谈圣光的三大美德。"
D.Strings[29095]="对我们来说，这是一个黑暗而艰苦的时代。天灾军团盘踞在南方。那些在战场上牺牲的勇士们，转瞬间就沦为了敌人的爪牙。"
D.Strings[29096]="柯尼拉，你能告诉我些什么？"
D.Strings[29097]="你们中的大多数都体会过被背叛的苦楚。"
D.Strings[29098]="但是你们坚持了下来，我们也必须这样做。在这个时代，人们不应该对坚韧这一美德感到陌生。面对绝望与仇恨，我们仍然要坚守自己的信仰并继续战斗。"
D.Strings[29099]="暂时这样就可以了。那座塔呢？奥萨拉克斯怎么样了？"
D.Strings[29100]="毫无疑问，你们拥有坚韧的意志……但是我们也不能忽略其它的美德。"
D.Strings[29101]="尊重，是所有踏上圣光之路的人们应该首先学习的美德。"
D.Strings[29102]="走廊对面，就是那些被你们视为敌人的家伙。尽管仇恨让彼此疏远，但是他们依然拥有值得你们尊重的品德。他们的勇气就值得钦佩。"
D.Strings[29103]="在场诸位都懂得荣誉之战的概念吧。对战时光明磊落是谓尊重，公平地对待敌人是谓尊重。"
D.Strings[29104]="在战场上，无论你的对手是兄弟还是宿敌，都要予以同样的尊重。即便你们的信仰不同，这种尊重依然能在你们之间建立某种联系……"
D.Strings[29105]="这就是你为我找到的？我要的是数量、地点还有目的——我们现在简直是两眼一抹黑。赶快去完成任务！"
D.Strings[29106]="……而认可这种联系，你们就会更接近圣光。"
D.Strings[29107]="要在圣光之路上更进一步，我们还必须学会同情。"
D.Strings[29108]="我们置身于竞争与对抗的年代。无论你们走到哪里，都能看见分歧与争执。"
D.Strings[29109]="如何看透本质并寻求共同点，是我们面临的挑战。唯有理解，才能让你们对他人所遭受的痛楚产生同情……"
D.Strings[29110]="……即使是对那些身处不同阵营的牺牲者。"
D.Strings[29111]="一旦感受并理解这种对敌对友一视同仁的同情，你们就重申了自己与世界的联系。"
D.Strings[29112]="只要我们奉行这些原则与美德，这个世界就会变成彼此向往的美好世界。荣耀而正义的世界。"
D.Strings[29113]="好好想想我的话吧，朋友们。黑暗笼罩着我们，人们更加需要圣光的指引。"
D.Strings[29114]="那些投石车仍然无法使用。我已经烧毁了几辆投石车，并破坏了其余的。"
D.Strings[29115]="我……我不知道。在那片废墟里有不寻常的动静。"
D.Strings[29116]="嘘……我在战场上的时候请不要暴露我的位置。马萨斯需要知道这里发生了什么。"
D.Strings[29117]="如果有谁想找我谈谈，我就在忏悔室的屏风后面等着你们。我很乐意为大家排解疑问、忧虑和彷徨。"
D.Strings[29118]="%s开始施放等离子冲击！"
D.Strings[29119]="让我们结束碎矛的威胁吧。哨兵，发动攻击！"
D.Strings[29120]="我已经粉碎了保护他们首领的护盾。赶快消灭他！"
D.Strings[29121]="我们并非孤军作战。无论今天我们有怎样的下场，暗夜精灵仍然难逃灭亡！"
D.Strings[29122]="他们这群蠢货，竟然以为我们是软弱可欺的。这些巨魔已经没有希望了——今天将在我们手中结束。"
D.Strings[29123]="我准备好了，开始进攻。"
D.Strings[29124]="准备好发动攻击之后就告诉我。"
D.Strings[29125]="碎矛的首领随时都有可能在这里出现。如果你想参与这次进攻，就耐心一些。"
D.Strings[29126]="多么激烈的战斗啊！你瞧见了吗，琳蒂安？！"
D.Strings[29127]="或许吧，但是我们攻入奥杜尔是迟早的事。找到传送进去的办法了吗？"
D.Strings[29128]="布莱恩，看来我们的朋友干得不错，但是事情还没有解决呢。"
D.Strings[29129]="毫无头绪。侦察兵在奥杜尔的前厅发现了一个巨型机械构造体，我怀疑是这玩意儿在捣鬼。"
D.Strings[29130]="噢。这么说，我们不得不跟那个大家伙打一架了？"
D.Strings[29131]="肯瑞托不可能在这种大块头上浪费资源。或许我们也没有必要跟它正面冲突。"
D.Strings[29132]="那附近的装甲始祖龙和火焰巨人怎么办？肯瑞托的法师们能对付得了吗？"
D.Strings[29133]="我们可以偷偷地溜过去吧。只要打倒前厅的机械构造体，就能进入奥杜尔了。"
D.Strings[29134]="溜过去？！你以为我们是什么，土拨鼠吗？"
D.Strings[29135]="我们要对付的真正敌人是上古之神啊，布莱恩。"
D.Strings[29136]="好吧。如果我们的盟友不嫌麻烦的话，就让他们来决定如何前进吧。"
D.Strings[29137]="你成功地击败了那只金属怪物。看来面前的障碍已经不多啦。$B$B一旦除掉前厅尽头的机器人，我们就能进入奥杜尔了。$B$B我们还发现了一头巨型喷火始祖龙和一个熔化的巨人。不过他们并没有挡住我们的去路，如果你想避开它们也没有问题。"
D.Strings[29138]="你必须待在赛场里。"
D.Strings[29139]="我正在执行卡德拉克的任务。我必须立刻前往佐拉姆加！"
D.Strings[29140]="你能不能使出点真本事来？"
D.Strings[29141]="不要退缩！干掉他们！"
D.Strings[29142]="欢迎你参加锦标赛，$n。"
D.Strings[29143]="很高兴能在这里见到你，$n。"
D.Strings[29144]="嘿，你们为什么要这么做啊？没看到上面写着“不要按这个按钮”吗？你们激活了自毁系统，还怎么完成测试呀？"
D.Strings[29145]="我想接受钓鱼训练。"
D.Strings[29146]="我估算了一下胜出的概率，发现这种可能性低得要命！"
D.Strings[29147]="在让长枪保持最精确的角度并让盾牌处于任何时候都能提供最佳保护的位置的同时我还怎么算得清该为机械陆行鸟加载多大的电荷！"
D.Strings[29148]="……而且有些坐骑可以把我踩扁！"
D.Strings[29149]="振作点。体型不是问题，关键在于你的作战技巧。"
D.Strings[29150]="体型上的劣势可以用信心和专注来弥补，小家伙。圣光与你同在。"
D.Strings[29151]="我在来这里的路上殴打了一只企鹅。"
D.Strings[29152]="哈哈，骗你的。我只是想看看你脸上的表情。"
D.Strings[29153]="天哪。你连一点怜悯之心都没有吗？"
D.Strings[29154]="姑娘，我要向你坦白一件事。"
D.Strings[29155]="我有一种……冲动。"
D.Strings[29156]="我在听你布道时，心中涌起了一股强烈的情感，我快疯掉了！"
D.Strings[29157]="……我想喝一杯！"
D.Strings[29158]="那就喝上几杯吧，我的矮人朋友。不过你最好先上缴你的长枪和缰绳。圣光与你同在。"
D.Strings[29159]="我的心情一天比一天沉重，神官。"
D.Strings[29160]="我被派来这里，以暴风城的名义作战。但是我所做的一切都毫无意义。"
D.Strings[29161]="在赛场之外，天灾军团仍在肆意破坏着我们的家园。那里才是真正的战场。而我，应该前往真正的战场。"
D.Strings[29162]="我怎么能留在这里，让那些需要我来保护的人们惨死呢？"
D.Strings[29163]="你有一副好心肠，我知道你想要侍奉圣光。但是战场上的厮杀难以撼动天灾军团的首脑。"
D.Strings[29164]="锦标赛的目的就是要建立一支强大而团结的军队，虽然这个目标看上去并不十分明确。待到一切准备就绪，北伐军以及麾下所有勇士的目光就会转向冰冠冰川了。"
D.Strings[29165]="我们将集结所有的力量向巫妖王发动攻击，而他，注定会失败。"
D.Strings[29166]="我知道你对此尚有疑惑，但是这会让你更加接近圣光。战斗吧，我的兄弟。"
D.Strings[29167]="这根本不是荣耀之战。我渴望挥舞战斧，浴血沙场！"
D.Strings[29168]="他们都是我的敌人。在战场上，你也会是我的敌人！你们的国王已经向我族宣战了！"
D.Strings[29169]="我却不能像同胞们一样浴血奋战。我能做的，只是端着一根笨重的长枪，哄着座狼朝对手发起冲锋，根本就不是真正的攻击。"
D.Strings[29170]="这就不是兽人的作战方式！酋长的命令与个人的荣耀令我左右为难。我不信仰圣光，但是你看起来像是个不错的顾问，我想听听你的建议。"
D.Strings[29171]="本区域将在六分钟后自毁。"
D.Strings[29172]="本区域将在五分钟后自毁。"
D.Strings[29173]="本区域将在四分钟后自毁。"
D.Strings[29174]="本区域将在三分钟后自毁。"
D.Strings[29175]="本区域将在二分钟后自毁。"
D.Strings[29176]="本区域将在一分钟后自毁。"
D.Strings[29177]="自毁程序确认启动。祝你愉快！"
D.Strings[29178]="本区域将在七分钟后自毁。"
D.Strings[29179]="本区域将在八分钟后自毁。"
D.Strings[29180]="本区域将在九分钟后自毁。"
D.Strings[29181]="本区域将在十分钟后自毁。"
D.Strings[29182]="自毁程序已中断。过载代码A-9-0-5。"
D.Strings[29183]="我理解你沮丧的心情。兽人作战时都非常勇猛，你一定不习惯锦标赛的方式。"
D.Strings[29184]="但是这依然是另一种形式的荣耀之战。你或许并不认可，但是我相信大家都目睹了你所表现出来的强大力量。"
D.Strings[29185]="而且……战斧的确很有杀伤力，但是长枪也不赖啊。"
D.Strings[29186]="圣光与你同在，兽人。"
D.Strings[29187]="没完没了的战斗。我不知道自己还能坚持多久。"
D.Strings[29188]="赛场上这种装腔作势的打斗……根本毫无意义。有什么用呢？"
D.Strings[29189]="而且我的发型都被头盔压扁了。真是太滑稽了！"
D.Strings[29190]="这看起来可能毫无意义，但是你可以试着在战斗中找到尊严。你迟早会发现这些练习的价值的。"
D.Strings[29191]="而且你的发型看起来很棒。"
D.Strings[29192]="幻象消散，通往中央房间的道路开启了！"
D.Strings[29193]="左臂再生了！"
D.Strings[29194]="右臂再生了！"
D.Strings[29195]="训练并骑乘毒皮暴掠龙需要耗费大量精力。"
D.Strings[29196]="哦，天哪！我没想到有人要来！工作间里真是一片狼藉。真丢人啊。"
D.Strings[29197]="医生！"
D.Strings[29198]="我可以修好它……也许不行！呀，真是一团糟……"
D.Strings[29199]="真棒。我想他们应该是把这个叫做“完美击杀”。"
D.Strings[29200]="我得记下来：火炮对血肉之躯非常有效。"
D.Strings[29201]="你败了！"
D.Strings[29202]="哦，天哪！我们好像已经超时了，朋友们。"
D.Strings[29203]="大胆！今天就要以尔等的鲜血，为曾用来改造这个世界的武器淬火！"
D.Strings[29204]="觉醒吧，钢铁熔炉中的兵士！执行造物者的意志！"
D.Strings[29205]="我要烧尽尔等的杂质！"
D.Strings[29206]="让烈焰吞噬尔等的身躯！"
D.Strings[29207]="燃烧吧！在造物者的烈火中燃烧吧！"
D.Strings[29208]="废料堆上又多了些渣滓。"
D.Strings[29209]="尔等的骨骸可做燃料。"
D.Strings[29210]="我……失败了。"
D.Strings[29211]="任你是天下最厉害的恶棍，还是最强大的英雄，都只不过是凡人之躯。"
D.Strings[29212]="可怜的家伙！"
D.Strings[29213]="雷暴之云在空中聚结，降下死亡之雨吧！"
D.Strings[29214]="风暴的力量仍将长存。"
D.Strings[29215]="你们盲目地冲进了疯狂之喉！"
D.Strings[29216]="钢铁议会的正事都被你们耽搁了！"
D.Strings[29217]="你们这些入侵者，休想轻易击败钢铁议会！"
D.Strings[29218]="真是不堪一击！"
D.Strings[29219]="血肉……碍事的东西。"
D.Strings[29220]="你们想要探寻奥杜尔的秘密？那就拿去吧！"
D.Strings[29221]="我的死只会加速你们的灭亡。"
D.Strings[29222]="只有把你们全部消灭才能解恨。"
D.Strings[29223]="又一个无关紧要的损失。"
D.Strings[29224]="傲慢的代价就是死亡。"
D.Strings[29225]="破译这个看看！"
D.Strings[29226]="面对猛烈的闪电吧！"
D.Strings[29227]="风暴的传统不容破坏。"
D.Strings[29228]="你们击败了我，又能得到什么呢？厄运依然会降临到你们这些凡人头上。"
D.Strings[29229]="你要为你的罪行受到惩罚！"
D.Strings[29230]="悲剧。千辛万苦，功亏一篑。"
D.Strings[29231]="欢迎进入无尽的寒冬。"
D.Strings[29232]="北地的寒风会将你吞噬！"
D.Strings[29233]="够了！了结这一切吧！"
D.Strings[29234]="有些东西，最好永远都不去碰！"
D.Strings[29235]="救命啊！别让它们靠近我！"
D.Strings[29236]="你们想把我怎么样？别过来！"
D.Strings[29237]="对！没错！不要手下留情！不要停止攻击！"
D.Strings[29238]="让仇恨和愤怒指引你们战斗吧！"
D.Strings[29239]="攻击这头野兽要害的时刻即将来临！将你们的愤怒和仇恨倾泻到它的爪牙身上！"
D.Strings[29240]="被你们自己的仇恨吞噬吧！"
D.Strings[29241]="战栗吧，凡人们，末日就要来临了！"
D.Strings[29242]="毫无力量……"
D.Strings[29243]="他们没救了吗？"
D.Strings[29244]="我是清醒的梦境。"
D.Strings[29245]="你们噩梦中的怪物。"
D.Strings[29246]="千面的恶魔。"
D.Strings[29247]="死人是不会泄密的。"
D.Strings[29248]="在我的真正形态面前颤抖吧。"
D.Strings[29249]="在死亡之神的面前屈服吧！"
D.Strings[29250]="你们在浪费我的时间！"
D.Strings[29251]="意志薄弱的蠢货！"
D.Strings[29252]="凝视死亡的真正面孔吧，你们的末日就要来了！"
D.Strings[29253]="疯狂将把你彻底吞噬！"
D.Strings[29254]="永恒的痛苦在等待着你！"
D.Strings[29255]="我的奴仆，快去毁灭他们！这是主人的命令！"
D.Strings[29256]="你们的命运早已注定。末日即将降临于这个可笑而渺小的世界，你们所有人都要灭亡。Uulwi ifis halahs gag erh'ongg w'ssh."
D.Strings[29257]="寒冬将会庇护你们，勇士们！"
D.Strings[29258]="艾欧娜尔，请祝福您的仆人！"
D.Strings[29259]="战斗矩阵已强化。全速突击！"
D.Strings[29260]="高戈奈斯，将您的威能赐予我！让我的战友们获得雷霆的力量！"
D.Strings[29261]="熔火巨人的力量逐渐被削弱，一声低沉的怒吼如闷雷般在空气中轰隆作响：“燃烧吧”。"
D.Strings[29262]="返回阿斯特兰纳！"
D.Strings[29263]="$c，走在这片树林里的时候一定要放轻脚步。这些树仿佛有眼睛，而且还会和我们的敌人说话。"
D.Strings[29264]="库格，送我去莫尔杉营地。"
D.Strings[29265]="目标躲过了你的冲锋。"
D.Strings[29266]="目标被打得失去了平衡。"
D.Strings[29267]="目标端起长枪，等待你发起冲锋。"
D.Strings[29268]="银色北伐军的骑兵是如何作战的？"
D.Strings[29269]="银色北伐军的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。"
D.Strings[29270]="暴风城的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是暴风城骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。"
D.Strings[29271]="诺莫瑞根的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。"
D.Strings[29272]="达纳苏斯的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。"
D.Strings[29273]="铁炉堡的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。"
D.Strings[29274]="埃索达的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。"
D.Strings[29275]="森金的骑兵以灵巧与远程攻击著称。$B$B他们敏捷的身手足以避开你的冲锋，因此你必须灵活运用近距离刺击和碎盾攻击，才有可能击败他们。"
D.Strings[29276]="雷霆崖的骑兵是魁梧而强壮的战士，近身战时能爆发出可怕的威力。$B$B他们的刺击势如破竹，你要尽量拉远彼此的距离，并在发起冲锋前使用碎盾打破他们的防御。"
D.Strings[29277]="银月城的骑兵将攻击和防御巧妙地结合起来，在作战中实现平衡与精准。$B$B但是，由于他们需要时刻与你保持距离，因此你可以伺机冲锋。$B$B你必须抢在他们之前发起冲锋，拉近彼此的距离，接下来在围绕他们跑动的过程中使用碎盾并看准机会使用刺击。"
D.Strings[29278]="幽暗城的骑兵是一群坚韧的勇士，他们擅长防御与持久作战。$B$B你应该在维持自身防御的前提下使用冲锋把他们累得趴下……只要你能保持防御优势，他们就会在对战中承受较大的伤害。"
D.Strings[29279]="奥格瑞玛的骑兵以其无畏而极具破坏性的冲锋为傲。即便是被对方冲锋，他们也能立即以牙还牙，这就是奥格瑞玛骑兵的可怕之处了。$B$B你要尽可能地打近身战并使用刺击，当他们试图拉开距离时，先利用碎盾令他们失去平衡，然后使用冲锋。否则，他们会不断地向你发动正面攻击。"
D.Strings[29280]="鱼人害虫，我要偷走你们的宝物！来阻止我吧！快一点！"
D.Strings[29281]="即将爆炸。"
D.Strings[29282]="欢迎来到这座圣光礼拜堂。请坐。愿你暂时远离痛苦的尘世，享受片刻的宁静。"
D.Strings[29283]="让我们开始吧，$r。$b$b我们的时间不多了，但还有很多事要做。"
D.Strings[29284]="今天你已经战胜了一位骑兵，我不能再接受你的挑战了。"
D.Strings[29285]="下一次，你也许要在火盆里放上更多的信号火药。我不知道他们从奥格瑞玛能不能看见这里的信号……"
D.Strings[29286]="你不需要一次用光一口袋吧，是不是？"
D.Strings[29287]="当这里的事情结束时，你也许要磨砺一下你的秘密技巧……"
D.Strings[29288]="%s准备高声咆哮！"
D.Strings[29289]="你是来听神官布道的吗？但愿你还能找到座位……"
D.Strings[29290]="守护者的远古之门开启了！"
D.Strings[29291]="一名卡多雷刺客躲避开$n的目光，潜入到阴影里。"
D.Strings[29292]="返回碎矛谷。"
D.Strings[29293]="联盟占领了东部火花车间！"
D.Strings[29294]="联盟占领了西部火花车间！"
D.Strings[29295]="部落占领了东部火花车间！"
D.Strings[29296]="部落占领了西部火花车间！"
D.Strings[29297]="联盟正在进攻东部火花车间！"
D.Strings[29298]="部落正在进攻东部火花车间！"
D.Strings[29299]="联盟正在进攻西部火花车间！"
D.Strings[29300]="部落正在进攻西部火花车间！"
D.Strings[29301]="你有一种感觉，有人正在盯着你……"
D.Strings[29302]="你听到身边传来一阵细碎的声音，却什么都没有看见。"
D.Strings[29303]="你从眼角瞥到一个影子。"
D.Strings[29304]="一名卡多雷刺客从阴影中跳出来，向$n发动了攻击！"
D.Strings[29305]="我的女士。$b$b我没有能保护她。我又怎么能回到银月城……"
D.Strings[29306]="如你所愿，$n。"
D.Strings[29307]="激活辅助防御系统后，轨道炮台将消灭所有未经认证的生命体。$B$B你属于未经认证的生命体。请确认。"
D.Strings[29308]="激活辅助防御系统。"
D.Strings[29309]="已确认。"
D.Strings[29310]="允许安全控制。辅助防御系统已激活。$B$B可以通过广场上的独立能源塔关闭这些辅助系统。"
D.Strings[29311]="能在锦标赛中代表银色北伐军出场真是无上的荣耀。"
D.Strings[29312]="禁止进入泰坦之城。主要防御系统与辅助防御系统均已激活。"
D.Strings[29313]="奇怪，我记得上次根本没提到什么轨道炮台啊。是哪个蠢货把它们给激活的？"
D.Strings[29314]="银色锦标赛在冰冠冰川的北部边界拉开了帷幕，$c。如果你不知道怎么去哪儿，我可以免费送你一程。$B$B我们积累的作战经验越多，在面对巫妖王时胜算也就更大。"
D.Strings[29315]="我要飞过去。"
D.Strings[29316]="耶！来吧！"
D.Strings[29317]="把我抛上去！"
D.Strings[29318]="让这个小废物看看，什么是真正的勇气。"
D.Strings[29319]="我准备好了，发射吧！"
D.Strings[29320]="这会很疼吧？"
D.Strings[29321]="希望不会弄坏我的指甲……"
D.Strings[29322]="把我抛出去！"
D.Strings[29323]="别浪费时间了！发射吧！"
D.Strings[29324]="那个超大号的玩具根本不是我的对手！"
D.Strings[29325]="月夜猛虎从沉睡中醒来，发出一阵深沉的吼叫。"
D.Strings[29326]="月夜猛虎跳起来，露出了獠牙。"
D.Strings[29327]="月夜猛虎站起来，因为受到打扰而愤怒不已。"
D.Strings[29328]="我要看到些汗水。如果我还看不到汗水，我保证，我一定能看到鲜血。"
D.Strings[29329]="加快脚步，苦力！……不要让我抽打你们。"
D.Strings[29330]="赶快把货物装好！十字路口需要这些物资。"
D.Strings[29331]="你……你刚做了什么，$n？！布莱恩！布——莱——恩——！"
D.Strings[29332]="布莱恩！$n激活了轨道防御系统！我们必须立即离开这里，不然会被烤熟的！"
D.Strings[29333]="手下留情？不行！"
D.Strings[29334]="这一下你就别想再站起来啦，朋友。"
D.Strings[29335]="%s开始施放恐吓尖啸。"
D.Strings[29336]="传送到奥杜尔地铁。"
D.Strings[29337]="你怎么敢扰乱我们与这个世界最后的联系！"
D.Strings[29338]="寒冷到来了……"
D.Strings[29339]="加入我们……直到永远。"
D.Strings[29340]="凡人，和我们在一起……永生不死。"
D.Strings[29341]="死亡欢迎你。"
D.Strings[29342]="让孤独指引你……服从吧。"
D.Strings[29343]="生命的重负……就此放松吧……"
D.Strings[29344]="你的寻求毫无意义。"
D.Strings[29345]="你的生命没有目标。"
D.Strings[29346]="{骷髅} 我死了！{骷髅}"
D.Strings[29347]="欢迎，孩子。"
D.Strings[29348]="我不应该期待这些肮脏的巨魔永远地安于和平。同情部落者绝不能信任。"
D.Strings[29349]="%s开始施放大爆炸！"
D.Strings[29350]="鲜血与雷鸣,$n!"
D.Strings[29351]="%s开始自毁！"
D.Strings[29352]="我们要面对许多危险，但我们不能因此而忽视自然。这样的话，自然将会在我们有所需要时舍我们而去。我们曾经有过这样的教训。"
D.Strings[29353]="阻挡自然者即是异端，即便在自然发挥它破坏之力时亦然如此。$B$B但如今要摧毁黑海岸的并非自然的力量。我不会让这片土地分崩离析。"
D.Strings[29354]="灼烧被水熄灭了！"
D.Strings[29355]="你好啊，我是盖瑞。相信一定是高尔博德派你来的。\n\n如果你要来帮忙，那么你要做的事情相当简单。我装配了一些诱饵机器人。我们可以把它们放在鱼人附近，然后开启它们的倒数计时系统。它们会闪动光芒，发出声音，引诱那些鱼人过来。几秒钟之后，它们就会爆炸，把那些鱼人一并炸飞。\n\n如果我们在那里放置足够多的诱饵机器人，我们就应该能再次进入船舱。希望这次我们的人员伤亡会少一些。当然，进入船舱的任务和你没有关系。先去炸飞那些小鱼人吧！"
D.Strings[29356]="当那些元素拼命要扯碎黑海岸的时候，我竭尽全力想要保护住剩下的自然生命。$B$B$c，我能得到你的帮助吗？"
D.Strings[29357]="挑战？！站直了，看我把你轰成渣。"
D.Strings[29358]="你以为你能打败洛伦瑟·唤雷吗？站稳了，蠢货，看我把你拍死。"
D.Strings[29359]="不要乱动，小冒险者。我这里有你正在寻找的死亡。"
D.Strings[29360]="哈！在我施放这个法术的时候站在这里！不会很痛的。"
D.Strings[29361]="嗨！别躲起来，可爱的家伙，让我好好地欢迎你。"
D.Strings[29362]="软蛋！离开那些柱子，我要让你知道，你所犯下的错误是多么严重。"
D.Strings[29363]="欢迎！不要害羞……从那些柱子中走出来吧，这样我就能清楚地看到你了。"
D.Strings[29364]="你好！不要不敢走出那些柱子。让我好好地欢迎你。"
D.Strings[29365]="不要担心脚下的那些巨魔。他们将被古树深深地踩进泥土之中。"
D.Strings[29366]="不要这样傻站着，$r……$b$b还有很多工作要做呢！"
D.Strings[29367]="一只怪物被半埋在这堆淤泥里，它由一堆恐怖的肢体、触须和无法辨识的面孔组成。你完全不想碰触这团半透明的怪诞血肉。$B$B虽然这只怪物已经死了。但奇怪的是，这具尸体周围的水面却丝毫没有受到污染的痕迹，尸体本身也没有任何腐烂的迹象。"
D.Strings[29368]="安静，小东西，这样你就能听到这片古老的土地在说话。它正在痛苦地呼号。"
D.Strings[29369]="古老的安努，我能在哪里找到一颗大地之种？"
D.Strings[29370]="嗯，这么年轻就拥有了如此强大的力量，这可真是惊人。你一定能以联盟的名义杀死无数敌人。但必须记住，在伟大的循环之中，生具有和死一样强大的力量。$B$B<安努缓缓地伸手到自己的头顶，摘下一颗不显眼的橡实，然后以从容不迫的姿态将手放在你面前>$B$B它有着特别的力量。$B$B……很抱歉，希望你不会认为我这是在自吹自擂。"
D.Strings[29371]="绝不容忍外人的打扰！"
D.Strings[29372]="艾萨拉女王将会归来，你们将会失去一切土地。"
D.Strings[29373]="你们的末日到了。海洋将会吞噬你们。"
D.Strings[29374]="暗夜精灵的时代即将终结。"
D.Strings[29375]="小$r，来看看我们是不是能把敌人冻住。"
D.Strings[29376]="阿克塔努斯，我已经准备好率领你的严寒狂潮进入战场。"
D.Strings[29377]="我们的兄弟迷失了。他烧焦了大地，蒸发了水体，吞噬了太多空气。$B$B帮助我们让他回复平衡与和谐吧。"
D.Strings[29378]="我已经准备好与这盘旋的涡流融为一体，击败玛格玛萨勋爵。"
D.Strings[29379]="%s已经被毁灭，无法拯救了！"
D.Strings[29380]="%s受到了保护，不会被吞噬。"
D.Strings[29381]="%s抓住肉块，然后狼吞虎咽起来。"
D.Strings[29382]="%s心满意足地呜呜叫着。"
D.Strings[29383]="%s开始施放宇宙重击！"
D.Strings[29384]="枯萎的树人将水吸入体内，恢复成原先的大小。"
D.Strings[29385]="这里无路可逃！只有我的岩浆的热烈拥抱！"
D.Strings[29386]="死亡从下方升起，从上面爆发！无人可以逃脱！"
D.Strings[29387]="烧焦大地，蒸干流水，点燃天空！"
D.Strings[29388]="大地之环无法抵挡我的愤怒！"
D.Strings[29389]="我的奴仆们，毁灭他们！"
D.Strings[29390]="我已经挣脱了大地的束缚，我绝不会再回去！"
D.Strings[29391]="灰谷将陷入火海！"
D.Strings[29392]="就像飞蛾投火！"
D.Strings[29393]="<*轰隆*轰隆*轰隆*>"
D.Strings[29394]="%s使一个风暴爪牙超载了！"
D.Strings[29395]="感谢你帮助我们保护这里的自然生命。希望一切都还不至于太晚。"
D.Strings[29396]="感谢你的帮助，$n！这片森林中潜藏的邪恶从没有彻底消失过，但知道有你这样的英雄帮助我守护这里，我的感觉就好多了。"
D.Strings[29397]="谁是上古之神？"
D.Strings[29398]="希望能多告诉你一些这方面的事情。现在已经几乎没有人相信还有这种生物存在了。古久以前，泰坦将艾泽拉斯塑造成我们今天所看到的这个世界，生与死的循环于焉建立。但在此之前，统治这里的是上古之神和服从于他们的元素。为了实现邪恶的目的，他们腐蚀这里的一切造物。$B$B安努告诉我，上古之神最终被泰坦击败，被囚禁在大地之下。这样的怪物真的有可能死亡吗？我希望自己能知道得更多一些，尽管这些都已经是超越了历史的故事。为此，我做了相当长时间的研究。$B$B我知道现在存在着对上古之神的崇拜，无论这是多么难以相信的事情。那些崇拜者似乎正在祈求这个世界的毁灭。上古之神的确是能够让人们发狂！"
D.Strings[29399]="%s饥饿地吃着蛋。"
D.Strings[29400]="<这只幼崽死盯着你，仿佛想分辨出你是不是它的妈妈。>"
D.Strings[29401]="我的毒皮暴掠幼龙走丢了。你看到它了吗？"
D.Strings[29402]="%s大口吞咽着食物。"
D.Strings[29403]="%s抓起食物，一口吞了下去。"
D.Strings[29404]="%s用它强壮的颚撕咬着食物。"
D.Strings[29405]="%s很快就把食物吃了个干净，它焦急地四处看着，好像还没吃饱。"
D.Strings[29406]="放弃挖掘？这太荒谬了！在我漫长而勤勉的一生中，我还从没有放弃过一个发掘点。也许我有勘探错误的时候，但从不曾有意放弃过任何值得挖掘的地方。你又是谁？我们在这里做什么？"
D.Strings[29407]="好极了！振作起来，我们还有很长的路要走。"
D.Strings[29408]="准备好了？我们出发！"
D.Strings[29409]="你在这里看见的废墟就是我在几个月以前挖掘的废墟，但它被淹没了！真是奇怪，不是么？"
D.Strings[29410]="啊，清醒一点，我们就要完成了！我放置记录的那座帐篷就在附近！"
D.Strings[29411]="以三锤部族之名，你好好看看！这里只有废墟！"
D.Strings[29412]="我找到的这座废墟就是我刚刚离开的那座废墟！看来我真的是要找一辈子了！"
D.Strings[29413]="你这个大笨蛋，这还是那座废墟。你只是在绕圈子。"
D.Strings[29414]="胡说。看见了吗？这就是我的日志，就在这里。"
D.Strings[29415]="你是怎么做到的，费德？"
D.Strings[29416]="说实话，这个$n是从哪里来的？"
D.Strings[29417]="是谁把这个$n挖出来的？"
D.Strings[29418]="让我们看看这件宝物会告诉我们什么……"
D.Strings[29419]="我认识它！它正在发出一条信息！"
D.Strings[29420]="妈妈？"
D.Strings[29421]="……诊断……诊断……失败。"
D.Strings[29422]="遗迹被破坏了，必须马上警告守护巨龙们。"
D.Strings[29423]="真是令人震惊。勘察员雷塔维又成功了！我们要看看，这对铁炉堡将有什么意义。"
D.Strings[29424]="阿夫鲁斯用他剃刀一样锋利的爪子伸进胸口，掏出自己的内核，将它和那些落下的月亮石放在一起。"
D.Strings[29425]="不可思议的是，这只萨特并没有死，而是沐浴在一片温暖的光亮之中。"
D.Strings[29426]="我们的挖掘计划已经不可能完成了——探险者协会要我们尽量收集一切有价值的物品，然后离开。说的容易，做起来可不容易。"
D.Strings[29427]="%s变形了！"
D.Strings[29428]="鱼人，呸！"
D.Strings[29429]="恐牙命令我前往地狱咆哮岗哨。"
D.Strings[29430]="这个树妖已经死亡了，显然是部落夺走了她的生命。"
D.Strings[29431]="安抚仪式已经开始。要不惜一切代价守卫住图腾！"
D.Strings[29432]="一个%s从壳中钻了出来！"
D.Strings[29433]="安抚仪式完成了。"
D.Strings[29434]="巫妖王的残酷统治让所有诺森德的居民们都饱受痛苦，尤其是那些孩子。如果你是索拉查盆地的狂心氏族或是神谕者的朋友，也许你会考虑抚养他们的一位孤儿，陪那个小家伙一周。"
D.Strings[29435]="能给我们点陈年蛋黄吃吗？"
D.Strings[29436]="难道连造物主的包包也满了吗？"
D.Strings[29437]="你觉得小狗狗人为什么总追问我们是否同情拉弗乌呢？拉弗乌的确很多话，但他是我们的好朋友。"
D.Strings[29438]="那么$n，你能给我们个哨子吗？这样我们想你的时候吹吹哨子就能见到你了，好吗？"
D.Strings[29439]="也许我们长大了会成为$r呢。是不是呀？"
D.Strings[29440]="你也是因为狗狗人才变成孤儿了吗？"
D.Strings[29441]="你得离海象人远点。他们会弄痛你。"
D.Strings[29442]="科科要带你去打猎。你是个不错的诱饵。"
D.Strings[29443]="兽人们总是嘲笑科科，科科迟早会让他们好看。"
D.Strings[29444]="你知道吗？要是科科闭上眼，你就看不到他了。"
D.Strings[29445]="抓三只小鸡来当午饭。不过我赌你连毛都碰不到。"
D.Strings[29446]="科科带来了大舌头怪幼崽最喜欢的玩具。也许它能让你晚上睡个好觉。"
D.Strings[29447]="询问那些孤儿的事情。"
D.Strings[29448]="我们接收的这些孤儿都来自于被战火焚毁的索拉查盆地。你可以选择照料一个神谕者或者是一个狂心氏族的孤儿。不管怎样，他们都会为了能结识一个新朋友而高兴。但你只能照顾他们之中的一个人。"
D.Strings[29449]="你可以选择照料一个神谕者孤儿或者一个狼獾人孤儿，但你不能二者兼顾。"
D.Strings[29450]="$r，我们的任务绝不止于守卫这棵树。部落不会善罢甘休。$B$B我们必须消灭他们！"
D.Strings[29451]="要带回欢笑的姐妹的尸体。"
D.Strings[29452]="我们到了！如果这是世界之树，那他们把整个世界放进这里的时候，它不会被撑破吗？"
D.Strings[29453]="紧紧抓住！我来负责飞行控制，你要集中精力注意下面的野生动物。"
D.Strings[29454]="在空中，你可以向下方成群的动物施放保护结界。"
D.Strings[29455]="感谢你，阿隆姆。我们也要感谢$n。终于……我们找到了艾露恩。"
D.Strings[29456]="$n，这里有部落！快一点，我们必须使用猎影之影！"
D.Strings[29457]="当大地被撕裂之后，我一直在帮助飞行管理员寻找逃散的角鹰兽。直到现在，我们的鸟还是无法真正安定下来。"
D.Strings[29458]="奥修斯，卡瑟娜派我来向你借一头角鹰兽。"
D.Strings[29459]="我已经准备好使用猎影之影了。"
D.Strings[29460]="去摧毁部落！"
D.Strings[29461]="返回林中树居！"
D.Strings[29462]="白尾鹿又开始在这个地区繁衍了。"
D.Strings[29463]="稳住，火焰产生的上升气流非常猛烈。"
D.Strings[29464]="被烈火赶出家园的月夜猛虎正在这片海滩上游荡，我们需要保护它们！"
D.Strings[29465]="看下面——还有一些蓟熊活着，我们来得还不算太晚。"
D.Strings[29466]="为什么会有人想要挖掘这么恐怖的东西？我相信就是这些东西导致了这里的动物们所遭遇的灾难。"
D.Strings[29467]="干得好！如果我们还需要再来一次，就去告诉奥修斯。如果不需要了，我会在那片树林中等你！"
D.Strings[29468]="利用这棵树下的月亮井在离开战斗的情况下迅速恢复生命值。"
D.Strings[29469]="谁敢反对艾萨拉女王？你们很快就会求生不得，求死不能了！"
D.Strings[29470]="随着吞噬者尤萨尔呼出最后一口气，这件宝物碎裂了。"
D.Strings[29471]="都结束了，艾萨拉！带着你的纳迦回到属于你们自己的海底去。"
D.Strings[29472]="发掘伟大的索苟斯的工作就要由我的人完成了。仪式已经准备好了吗？"
D.Strings[29473]="还没有，我们还需要大量的祭品才能让上古之神的使者重新降临这片大地。"
D.Strings[29474]="别担心，就像我说的那样，我的部下即将完成伟大的深渊滑行者的挖掘工作。他们甚至可以成为最虔诚最完美的祭品。索苟斯必将崛起！"
D.Strings[29475]="接受风之拥抱的祝福吧。愿你从奥达希尔开始的旅程因这祝福而更加顺利。"
D.Strings[29476]="你相信总有一天，科科会带领狂心氏族回家，就像熊人赢得最终的胜利夺回树城那样。科科想要自己的家，而不是遍布紫人的城市，更不是大舌头怪出没的丛林。"
D.Strings[29477]="我要轰炸阿斯特兰纳！这是高戈斯上尉的命令。"
D.Strings[29478]="头儿？为什么我们挖这种东西？"
D.Strings[29479]="看啊！那是我们吗？我们觉得那是我们。只是好像有一点老？"
D.Strings[29480]="我们也许真的得到了造物主的祝福！也许有一天，圣坛的魔法会把我们变成大神谕者？"
D.Strings[29481]="小心你的舌头，虫子。不要把伟大的索苟斯说成“东西”，否则你可要不得好死。"
D.Strings[29482]="赶快回去工作！大人们正在上面看着你，他们可不会对偷懒的人心慈手软！"
D.Strings[29483]="看啊！那一定是强大的战士科科！看到了吧？科科说什么来着。"
D.Strings[29484]="这是一个暂时目标。任务将自动加载。"
D.Strings[29485]="你能感觉到吗？$B$B灵魂世界在悼念日中距离我们更近了。所以我们要用鲜花和蜡烛装饰逝去亲友的坟墓，并告诉他们：欢迎回来，虽然只有片刻。$B$B所以，来吧！和我一起跳舞！让我们纪念那些已经和我们天人永隔的亲人。让逝者同我们一起享用美食，一起微笑。让他们知道，关爱永不逝去。"
D.Strings[29486]="在悼念日，人们会聚集在墓地，追忆、告慰那些逝者的亡魂。$B$B届时任何主城的墓地都会举行这个仪式，在那里有悼念日食品、舞蹈、化装聚会和其他活动。"
D.Strings[29487]="在你进入地狱石之前，一定要同这棵树顶上的塔隆凯·捷根谈一谈。他也有一个任务要交给你。"
D.Strings[29488]="我们有了一个新朋友！"
D.Strings[29489]="想看看我能做些什么吗？"
D.Strings[29490]="我们也能跳舞！"
D.Strings[29491]="一起来跳舞吧！"
D.Strings[29492]="你的样子还不错！"
D.Strings[29493]="你回来啦！"
D.Strings[29494]="这场雪仗打得真精彩！"
D.Strings[29495]="最好小心一些！"
D.Strings[29496]="守卫科多兽商队！"
D.Strings[29497]="领着他们！带他们出来！"
D.Strings[29498]="我要将这些物资运到十字路口，这事关我的荣誉。如果你不想帮忙，就站开一些。"
D.Strings[29499]="好吧，$n，准备好了吗？这可不容易啊！"
D.Strings[29500]="是的，我准备好了。让我们开始吧！"
D.Strings[29501]="$n，上马！不要让我失望。"
D.Strings[29502]="她就是红龙女王？嗯……我们一直以为她应该更大一些。"
D.Strings[29503]="她怎么和其他的龙一点也不像？她真的可以变成一头巨大的龙吗？"
D.Strings[29504]="嗯……尊贵的殿下，你愿意为我们变成一条龙吗？"
D.Strings[29505]="好啊……就现在吧？"
D.Strings[29506]="如果我变回红龙形态。这里就装不下其他人了，小家伙。"
D.Strings[29507]="嗯……那个科科已经非常老了。而狂心氏族的首领一定要更老一些。这很不错。作为战士和首领，科科有着美好的未来。科科很高兴你能带他参观这里。孤儿院的阿姨从不带科科来。"
D.Strings[29508]="艾露恩指引我们，$c。"
D.Strings[29509]="我们绝不能向敌人让出一寸土地。如果他们进攻黑海岸，我们就把他们打回去。我们要像保卫达纳苏斯一样保卫这里。"
D.Strings[29510]="你太迟了……当我们说话的时候，那件圣物已经被献给了艾萨拉！"
D.Strings[29511]="需要有人帮你找到路吗？我对这个地方可以说是了如指掌。"
D.Strings[29512]="筑巢符文在哪里？"
D.Strings[29513]="天蓝之石在哪里？"
D.Strings[29514]="黑色羽毛在哪里？"
D.Strings[29515]="鸦爪神符在哪里？"
D.Strings[29516]="奥本·怒爪在哪里？"
D.Strings[29517]="战斗将在60秒后开始。"
D.Strings[29518]="战斗将在15秒后开始。"
D.Strings[29519]="筑巢符文就在这座桥另一端，南边房间里的上层部分。"
D.Strings[29520]="天蓝之石就在北边房间里下层部分的小房间中。"
D.Strings[29521]="黑色羽毛就在南边房间里下层部分的坡道尽头。"
D.Strings[29522]="鸦爪神符就在北边房间里上层部分的露台上。"
D.Strings[29523]="奥本·怒爪就在双桥之一所通向的西边房间里，靠近离开兽穴的走廊。"
D.Strings[29524]="科科还以为我们会看到红龙女王。但那只是个长着可爱犄角的女精灵。"
D.Strings[29525]="为了地狱咆哮酋长！"
D.Strings[29526]="毁灭精灵！"
D.Strings[29527]="灰谷是我们的！"
D.Strings[29528]="卡利姆多属于部落！"
D.Strings[29529]="把他们全干掉，烧掉他们的塔楼！"
D.Strings[29530]="但这到底该怎样解释？龙巨大而强猛。精灵女士却弱不禁风。科科想要看到红龙女王真正的样貌。"
D.Strings[29531]="放心吧，科科，她就是红龙女王。我们在和他们一同工作的时候，经常会变成更小的躯体。"
D.Strings[29532]="哦！现在科科明白了。科科不想被强大的女王捏扁。也许等这里不太挤的时候，科科还会回来。不管怎样，很高兴见到你，女王。"
D.Strings[29533]="干得好！我会负责卸货。你应该去找一趟卡纳尔·菲斯。"
D.Strings[29534]="薄雾会引领道路。"
D.Strings[29535]="出口在西北方……薄雾会引领道路。"
D.Strings[29536]="你能带我去出口吗？"
D.Strings[29537]="我坚持不住了……我需要撤退，进行恢复。"
D.Strings[29538]="喔！真正的造物主？我们完全没有想到索乌塞遇到过一个真正的造物主！"
D.Strings[29539]="呃，你好，造物主。见到你是我们的荣幸。"
D.Strings[29540]="你睡着了吗，造物主？我们知道，为了收集我们留给你的所有好东西，一定费了很大力气。"
D.Strings[29541]="我们为你带来了一件礼物，造物主。也许你在醒来的时候会看到它。也许你会记得我们来看过你，是吗？"
D.Strings[29542]="扁鼻子的垃圾！离开我的地盘！"
D.Strings[29543]="该死的猪！你们的胖脑袋里只有一团肥肉！"
D.Strings[29544]="我会扯掉你们的獠牙，听到了吗？"
D.Strings[29545]="没错！死吧，害虫！部落将彻底消灭你们。"
D.Strings[29546]="你们在我的手里根本不堪一击！"
D.Strings[29547]="没错，你们这帮只知道尖叫的害虫。我现在倒是很想吃烤猪肉！"
D.Strings[29548]="没有人能偷走我的牲畜！"
D.Strings[29549]="你们这些猪排原料，吃我的斧头吧！"
D.Strings[29550]="能够再度和亲友一起欢庆，彼此分享旧日的故事，这种感觉实在太好了。"
D.Strings[29551]="喔！科科终于找到赫米特·奈辛瓦里了！"
D.Strings[29552]="在你来到索拉查以后，就连狂心氏族也知道了你的事情。也许你能教科科两招？"
D.Strings[29553]="好啊，小伙子，你可以从阅读《荆棘谷的青山》开始。然后，也许你能和我一同参加行动，你觉得如何？"
D.Strings[29554]="科科不知道阅读有什么用。科科不会阅读，但如果赫米特·奈辛瓦里要科科这样做，科科就会努力去做。"
D.Strings[29555]="也许你最终会彻底放弃，但现在，你还需要坚持。"
D.Strings[29556]="%s挣破了网子。"
D.Strings[29557]="%s被捉住了！"
D.Strings[29558]="<喷鼻息>懦夫就是这么战斗的吗，$r！"
D.Strings[29559]="<胖揍这个蠢货。>"
D.Strings[29560]="我们的一些女猎人已经去过班尼希尔兽穴。当你在那里的时候，她们会找到你。去和辛塔瑞谈谈，从她那里取得坐骑吧。"
D.Strings[29561]="双中！"
D.Strings[29562]="多中！"
D.Strings[29563]="超多中！"
D.Strings[29564]="疯狂投掷！"
D.Strings[29565]="超级投掷！"
D.Strings[29566]="怪力投掷！"
D.Strings[29567]="史诗投掷！"
D.Strings[29568]="传说投掷！"
D.Strings[29569]="以圣光的名义！"
D.Strings[29570]="如果你想的话，那就去吧，大舌头怪的崽子！"
D.Strings[29571]="把玩具还回来！"
D.Strings[29572]="%s倒在地上，昏迷不醒。"
D.Strings[29573]="那些野猪人总是在我们的营地边缘劫掠食物和供给物资。难道他们现在竟然直接对我们的农场和家园发动攻击了？他们这种疯狂的行为一定是有原因的。"
D.Strings[29574]="托格莉，你能再把这名囚犯弄醒吗？"
D.Strings[29575]="<这头野猪人用他黑珠子一样的眼睛紧盯着你。>"
D.Strings[29576]="<这头野猪人抽着鼻子，一边哼哼，一边嗅着你。>"
D.Strings[29577]="怎么样，$r？想干什么就干吧。"
D.Strings[29578]="我们是骄傲的战士，$n。<哼哼>数量还很多。"
D.Strings[29579]="我们要向孤儿院长告状！"
D.Strings[29580]="孩子们，请注意你们的行为！如果再这样胡闹，永远也不会有人收养你们的！"
D.Strings[29581]="是谁派你来的？！"
D.Strings[29582]="<抽他一记大耳刮子。>"
D.Strings[29583]="<一脚踢在他的肥屁股上。>"
D.Strings[29584]="<施舍食物。>"
D.Strings[29585]="<挠痒痒时间！>"
D.Strings[29586]="嗨，你好！"
D.Strings[29587]="莎尔蒂恩，我需要达图尔的魔棒。"
D.Strings[29588]="莱恩，我需要达图尔的魔棒。"
D.Strings[29589]="<熊怪闻闻你，哼了两声。>"
D.Strings[29590]="克罗尔格，我需要达图尔的魔棒。"
D.Strings[29591]="%s谨慎地接下递过来的食物。"
D.Strings[29592]="嗯，<哼哼>为什么你要把这个肉煮熟？突牙告诉我们，生肉才最好吃。"
D.Strings[29593]="哦，我已经说得太多了！"
D.Strings[29594]="哦！<哼哼>"
D.Strings[29595]="呼呼，你从我这里什么也得不到！"
D.Strings[29596]="呼呼，不要打脸！"
D.Strings[29597]="嗷！我不会说的！"
D.Strings[29598]="<喷鼻息！>你就这点能耐？"
D.Strings[29599]="嗷喔！我什么都不说！"
D.Strings[29600]="你在浪费你的力气！突牙训练过我们该如何咬紧牙关。"
D.Strings[29601]="<喷鼻息！>"
D.Strings[29602]="我不会说的！"
D.Strings[29603]="我才不怕你！"
D.Strings[29604]="我不会说的！<哼哼>"
D.Strings[29605]="哈哈，<哼哼>哈——喝！<哼哼>哈哈哈哈哈<哼哼><费力地喘息>嗬嗬！突牙长官从没有教过我们该如何应付这个！"
D.Strings[29606]="这片土地将是我们的！"
D.Strings[29607]="突牙吼叫着，喘着粗气，哼哼着，气恼地向他的部下发号施令。"
D.Strings[29608]="我们钢鬃……必须……繁衍下去……"
D.Strings[29609]="%s微微一笑。"
D.Strings[29610]="好的，奥伯妮。我有很多事情要说。你有没有和月光林地的精灵们交谈过？"
D.Strings[29611]="精灵们都在谈论一位月亮女神，你知道她吗？他们非常重视月亮发出的光芒。"
D.Strings[29612]="就像她一样，我听到的非常有趣。众所周知的是，所有德鲁伊，无论是舒哈鲁还是精灵，都能召唤穆莎的月光。"
D.Strings[29613]="我有些奇怪。伊哈缪尔一直在以他的睿智指引着我们。我从他那里学到了许多东西。而传说告诉我，起初，我们的人民全都是德鲁伊……"
D.Strings[29614]="……但伊哈缪尔所教导的正是精灵们熟知的东西。暗夜精灵都是夜的生物，月亮女神是他们忠贞的信仰。"
D.Strings[29615]="不！不，不会那样的。他是一位好长者。穆莎是大地之母的一只眼睛。她看护着我们。这不是什么坏事。"
D.Strings[29616]="弗蕾亚从艾欧娜尔的礼物中汲取精华，开始治疗周围的盟友！"
D.Strings[29617]="但如果不全力维持世界的平衡，我们就没有任何存在的意义。我们的战士只有在需要的时候才会奔赴战场。我们的猎人只猎取族人生存所必需的野兽。而且每一头猎物身上的一切都会被我们妥善利用。我们的萨满则担负着引导与调和元素之力的重任。"
D.Strings[29618]="当我们这些德鲁伊全力守护自然的时候，我怀疑我们是否忽略了一把维持世界万物平衡的钥匙。"
D.Strings[29619]="不，不。不要在他招待朋友的时候用无聊的哲学问题去打扰他。"
D.Strings[29620]="嗯，这并不算是一个新主意，姐妹。"
D.Strings[29621]="$c，在你的一生中，你肯定有过一段做学生的时光。从导师那里学习知识，并想要为导师争光，对不对？我不是指具体的某个人，但导师肯定是比你知道更多，而且愿意教导你的人。不过，要不是这样呢？想象一下……$b$b如果你发现，你的导师所知道的也许并不如你想象的那样多，你也许能找到更好的办法提升自己，你又会怎样做？"
D.Strings[29622]="这可真糟糕！我不应该无所事事地坐在这里。需要我去做的事情实在太多了！要不是我的胳膊在诺森德受了伤……但现在抱怨这种事是没用的！塔胡会帮我包扎好，并治好我。虽然有伤，但是我们还能帮上点忙。\n\n虽然不在前线，但这并不意味着我们就要混吃等死。"
D.Strings[29623]="不，不，不，不，不……"
D.Strings[29624]="恢复活力的科多兽站起来，摇晃掉身上的泥土。"
D.Strings[29625]="又是一张新面孔？很高兴见到你，我是德林拉尔。"
D.Strings[29626]="和我聊聊，塔胡。随便和我说些什么。什么事都行！我要闷得发疯了。"
D.Strings[29627]="不是很多。"
D.Strings[29628]="就像穆莎一样。"
D.Strings[29629]="你带着这个要去哪里？"
D.Strings[29630]="我听出了你要说“但是”……"
D.Strings[29631]="你觉得他的教导错了吗？"
D.Strings[29632]="那么，你打算把这个交给那位长者？"
D.Strings[29633]="我是这样想的。不管你怎么说，这并不傻。"
D.Strings[29634]="我看见你在沉思中紧皱双眉，塔胡。"
D.Strings[29635]="你心里有事情，对不对？"
D.Strings[29636]="是什么？"
D.Strings[29637]="有一句话说……“黎明前永远都是最黑暗的时刻。”但黎明就要到了，塔胡。太阳终将升起。一切都将回复平衡。"
D.Strings[29638]="%s微笑着，指了指北方。"
D.Strings[29639]="即使在荒凉的冰原上，阳光还是能透过昏黑的云幕。我的希望没有泯灭，塔胡。我想，我们能够取得最终的胜利，无论挡在我们面前的敌人是多么可怕。"
D.Strings[29640]="与其在空洞的信仰中寻求自我安慰，我宁可冲上前线。我们不能只是坐等希望变成现实。"
D.Strings[29641]="借助这个希望来加强我们的力量？"
D.Strings[29642]="抱歉，姐妹。这不值得担心。"
D.Strings[29643]="我正在考虑关于北方前线的问题。看样子，你正急不可待地要回到那里去。"
D.Strings[29644]="奥伯妮，我一直在劝你要保持耐心，但现在我和你一样讨厌呆在这里。这里的时光乏味无趣。这种无所事事的状态最终也许会逼迫我彻底改变这里的一切。"
D.Strings[29645]="万物皆有平衡，死亡亦然。我痛恨那种认为破坏和黑暗也是一种合理存在的想法。"
D.Strings[29646]="嗯……还是人类烹调的食物好吃。"
D.Strings[29647]="我知道，姐妹，我知道。总有一天，我们会重返战场。但现在，我们最应该做的也许是将这个消息传递给其他人……让他们拥有和你一样的希望。"
D.Strings[29648]="就是这样。"
D.Strings[29649]="我骗了你。你这烂食物正在散发着臭气。但这城市更加臭不可闻！"
D.Strings[29650]="嘿！你以为你在干什么？"
D.Strings[29651]="我知道，幽影谷的状况并不好。但回到这片森林总是让我有一种回家的感觉。$B$B这里永远都是安宁而纯净的。"
D.Strings[29652]="清空旗帜"
D.Strings[29653]="哦，$n！我的兄弟巴尔格告诉我，你在科多兽背上的表现可谓是百发百中。这支运输队能从前沿哨所安全地来到这里，你可是立了一大功。$B$B听着，我知道你在格罗多姆还有很多工作要做……不过我更希望你能够继续护送运输队前往十字路口。$B$B做好准备以后再来找我吧！"
D.Strings[29654]="我曾经不断地将各种辎重和食物从奥格瑞玛拖送到十字路口，那可是件繁重的工作。现在我的脖子总会因为那时的劳累而隐隐作痛。"
D.Strings[29655]="自从海加尔山之战以来，我们的族人已经改变了许多。"
D.Strings[29656]="诺达希尔的力量曾经败过阿克蒙德，击退了燃烧军团的入侵，但它只剩下了一个苍白的影子。"
D.Strings[29657]="我们的不朽力量，我们的生命的精华——已经丢失了。"
D.Strings[29658]="那名叛徒已经离开了他的牢狱，大导师怒风则消失在翡翠梦境里。"
D.Strings[29659]="这是一个黑暗的时代。"
D.Strings[29660]="随着玛法里奥·怒风的离开，德鲁伊陷入混乱，迫切需要一名新的领导者。"
D.Strings[29661]="大德鲁伊范达尔·鹿盔唤醒了德鲁伊，并说服黑海岸的古树议会，让他们相信现在正是吾族重建之时。"
D.Strings[29662]="为了让我族重新获得不朽，在得到议会的同意之后，鹿盔率领最强大的德鲁伊们培育出泰达希尔。你正站在它的枝干上。"
D.Strings[29663]="虽然我们已经有了新的家园，我们不朽的生命却依然没有得到恢复。"
D.Strings[29664]="大德鲁伊造访了巨龙，祈望他们祝福新生的生命之树，就如同他们在上古时代祝福诺达希尔那样。"
D.Strings[29665]="时光之王诺兹多姆拒绝给予他的祝福，并谴责了德鲁伊的傲慢。"
D.Strings[29666]="但为了遵守上古的契约，阿莱克丝塔萨也拒绝了鹿盔。没有她的祝福，泰达希尔的成长出现了无可预期的瑕疵。"
D.Strings[29667]="鹿盔回到了他在达纳苏斯的领地里，开始寻找能够祝福泰达希尔，让我族恢复不朽的新方法。"
D.Strings[29668]="随着时光的推移，鹿盔只是同我们的族人变得越来越疏离。"
D.Strings[29669]="有些人认为他在责怪我们，责怪他的族人。因为他在很久以前的流沙之战中失去了儿子。"
D.Strings[29670]="还有谣言说，他和我族的光芒，达纳苏斯的领袖泰兰德·语风之间出现了越来越多的矛盾。"
D.Strings[29671]="但许多塞纳里奥议会的德鲁伊仍然坚信，范达尔在全心全意为卡多雷的福祉而努力。他们全都会不惜一切代价地效忠于他。"
D.Strings[29672]="范达尔·鹿盔独力担负了我们的原罪和愚行，因此，他应该得到我们全体暗夜精灵的尊敬。"
D.Strings[29673]="几周前，泰达希尔上的所有生灵都发现的自己记忆开始变得模糊，仿佛时间偷走了他们的一部分生命。"
D.Strings[29674]="迷雾终于散去之后，我们却发现范达尔·鹿盔和他的许多最亲近的追随者都在悄然间消失了。"
D.Strings[29675]="而大德鲁伊怒风已经从梦境中醒来，回到了他所钟爱的泰兰德·语风身边。"
D.Strings[29676]="当他回归时，阿莱克丝塔萨和伊瑟拉也一同到来，并最终将他们的祝福赐予泰达希尔。"
D.Strings[29677]="虽然还残留有少量急需清除的腐化物，但泰达希尔似乎已经开始萌生新枝了。新生已然开始。"
D.Strings[29678]="没有人知道以后会发生什么，但随着玛法里奥和泰兰德的重新结合，卡多雷又有了新的希望。"
D.Strings[29679]="你准备好了吗，$n？"
D.Strings[29680]="开始吧，罗克。"
D.Strings[29681]="她来了，上坐骑！"
D.Strings[29682]="%s凝望着月亮井，似乎是迷失在遥远的记忆中。"
D.Strings[29683]="卡多雷的幻影闭上眼睛，渐渐消失了。"
D.Strings[29684]="真是令人难以置信的射击！我会尽量让这些科多兽平静下来。去向索克报告吧，他一定很想了解关于这次袭击的情况。"
D.Strings[29685]="搞定！"
D.Strings[29686]="成功！"
D.Strings[29687]="做到了！"
D.Strings[29688]="更坚韧，更优秀，更快，更强大！"
D.Strings[29689]="这个炸弹能终结一切炸弹！"
D.Strings[29690]="有谁来为我们安放好这颗炸弹！"
D.Strings[29691]="我需要找个够蠢的家伙把这东西带进石爪去！"
D.Strings[29692]="我已经等不及了。我要把它引爆！哇哈哈哈哈哈哈哈！"
D.Strings[29693]="让我们对它进行测试。"
D.Strings[29694]="只要一点……"
D.Strings[29695]="随着你一步步靠近，%s变成一个具体的形态，并点头向你致意。"
D.Strings[29696]="%s在月亮井旁边，陷入了沉思。"
D.Strings[29697]="%s缓步靠近月亮井，一种熟悉的，若有所思的神情出现在它的脸上。"
D.Strings[29698]="随着它逐渐靠近，%s向你露出了胸有成竹的微笑。"
D.Strings[29699]="呜哈！"
D.Strings[29700]="啊哈哈哈哈，你落进了我的陷阱，$n！"
D.Strings[29701]="$n，小心！"
D.Strings[29702]="波尔温，卡丽瓦还在附近吗？"
D.Strings[29703]="是的，小心背后，$n！"
D.Strings[29704]="$r，这是什么？时间就是金钱！"
D.Strings[29705]="你好啊，$r。"
D.Strings[29706]="森林的拯救者！如果不是你的英勇行为，阿斯特兰纳和灰谷一定会落进燃烧军团的手中。$B$B希望你诸事顺利，$n！"
D.Strings[29707]="不要屈服于这个诅咒！你们曾是吉尔尼斯人……你们能够再次成为吉尔尼斯人！"
D.Strings[29708]="吉尔尼斯需要你们！你们不能像野兽一样逃进森林中！勇敢地面对敌人，无论生死，都要作一个吉尔尼斯人，而不是野兽！"
D.Strings[29709]="你们也许沾染了野性，但吉尔尼斯的血仍然流动在你们的体内。对抗部落，保卫我们的家园！"
D.Strings[29710]="荣耀之地"
D.Strings[29711]="塞纳留斯之路"
D.Strings[29712]="食人魔皮纳塔"
D.Strings[29713]="魔法公鸡坐骑"
D.Strings[29714]="科隆加恩在注视着你！"
D.Strings[29715]="嘿，你是怎么找到我的？看来我要找一个更好的藏身地了。"
D.Strings[29716]="你的名字叫做$n？这对于熊怪来说可真是个奇怪的名字。$B$B看来你不是从灰谷来的。"
D.Strings[29717]="现在这并不重要。奥塔·旺，听我说。你必须起来反抗那些兽人！"
D.Strings[29718]="<奥塔·旺的眼睛本已经因为饱受奴役而变得灰暗。听到你的方案，它们重新闪烁出光芒。你感觉到达图尔魔棒的力量通过你传到了这只熊怪的身上。>$B$B你要反抗吗？"
D.Strings[29719]="是的，奋起反抗吧！带领你的熊怪打破牢笼，消灭部落。是那根魔杖的力量在压迫你们！"
D.Strings[29720]="<一道奇怪的光芒在奥塔·旺的眼中闪过。他挺起身子，向天空发出咆哮。>$B$B我们会奋起抗争！摧毁我们的枷锁！"
D.Strings[29721]="我已经准备好了奔向石爪！"
D.Strings[29722]="不必再等多久了，你这个叫$n的家伙，我们很快就会消灭那些抓捕我们的混蛋！"
D.Strings[29723]="装死是一件超级容易的事，$n。你来看……"
D.Strings[29724]="%s开始装死。"
D.Strings[29725]="看到了吗？！这不难吧？现在你可以轻松地戏弄那个恶心的老奥索·棘痕和他的卫士了。"
D.Strings[29726]="图加的鹰鸣叫着，向山峰盘旋而去。"
D.Strings[29727]="干得好，朋友！现在我们就可以勘察这片区域了。"
D.Strings[29728]="仁慈的大地母亲啊，看看这场浩劫带来的满目疮痍吧！或许我们还应该感到庆幸的是，贫瘠之地没有整个沉入海底。"
D.Strings[29729]="这是什么？看来这道裂缝南边发生了另一些事情。"
D.Strings[29730]="实际上，这种植物不受任何限制地生长，吞噬了整片陆地。和我们在绿洲发现的非常相似。"
D.Strings[29731]="我们必须竭尽全力阻止这种事情在这里发生。所以我们对绿洲的调查要进一步升级，从源头阻止这一现象。我们会在十字路口再谈谈！"
D.Strings[29732]="$c，深吸一口气。雷鸣峰顶的空气非常稀薄，不过这里毕竟没有下面那种呛鼻子的尘土。"
D.Strings[29733]="计算路径……"
D.Strings[29734]="警报……有危险！"
D.Strings[29735]="检测到系统故障……重新计算路线……"
D.Strings[29736]="重新计算中……"
D.Strings[29737]="重新计算完毕。恢复传输。"
D.Strings[29738]="开始传送，目的地，狂风峭壁。"
D.Strings[29739]="小朋友，能帮个忙吗？"
D.Strings[29740]="哈，是啊，$n！这正是我想听到的。让我们弄些响动出来吧！"
D.Strings[29741]="来吧，你们这些长着马脸的怪物们！"
D.Strings[29742]="再来些……多来些！"
D.Strings[29743]="啊哈，这就是我们的目标了，我在这里就能闻到他的气味了。"
D.Strings[29744]="真是令人吃惊！$B$B你读的这个东西意思就是“DAN纯爷们！”"
D.Strings[29745]="摧毁炸弹！"
D.Strings[29746]="不要让它到达石爪山！"
D.Strings[29747]="射击它！摧毁它！"
D.Strings[29748]="阻止那个炸弹！"
D.Strings[29749]="脚步放轻！你会被发现的。"
D.Strings[29750]="呸！我想要被看见？我只是努力想要藏起来。"
D.Strings[29751]="$c，请不要刺激格高。我们应该做的是观察和报告情况，而不是引起一场骚乱。"
D.Strings[29752]="看呼乌听到了这个消息还怎么说！"
D.Strings[29753]="当库拉克倒下时，%s惶恐地逃跑了。"
D.Strings[29754]="偷偷摸摸，鬼鬼祟祟。让我告诉你关于格高的事：格高从来不会躲躲藏藏。"
D.Strings[29755]="哈哈！这太精彩了！我随时都会和你并肩战斗，$n。"
D.Strings[29756]="炸弹状况：百分之80！"
D.Strings[29757]="炸弹状况：百分之60！"
D.Strings[29758]="炸弹状况：百分之40！"
D.Strings[29759]="炸弹状况：危急！"
D.Strings[29760]="为吉尔尼斯哭泣吧！"
D.Strings[29761]="你们的国度已经毁灭了！"
D.Strings[29762]="我们的狼群会把你吃光！"
D.Strings[29763]="你的日子已经屈指可数了，变形者！"
D.Strings[29764]="炸弹状况：完全修复！"
D.Strings[29765]="我们还没有失去希望……"
D.Strings[29766]="你绝对到不了石爪山！"
D.Strings[29767]="蠢货！你要为在灰谷的所作所为而遭到惩罚！"
D.Strings[29768]="向石爪山脉进攻。做好准备，敌人可能会发动猛烈的抵抗！"
D.Strings[29769]="我要把这些送到雷霆崖，以确认我的发现。也许我很快就将再次需要你的帮助了，朋友。"
D.Strings[29770]="系统当机……"
D.Strings[29771]="看看你的周围，部落的仆人……"
D.Strings[29772]="你很快就会与这些先你而来的家伙们汇合了。"
D.Strings[29773]="瞄准，姐妹们……"
D.Strings[29774]="射击！！！"
D.Strings[29775]="这道传送门通向地狱火半岛的命运阶梯……绝对没错，就是外域。$B$B你准备好了吗……？"
D.Strings[29776]="握紧它！"
D.Strings[29777]="你们两个在干什么？把那个包交给我。"
D.Strings[29778]="$C，你应该知道，酋长不信任亡灵。你有没有听说过天谴之门发生的事情？"
D.Strings[29779]="你应该好好考虑一下该效忠谁，$r。"
D.Strings[29780]="我们已经见到了你的“调查”结果。我会将这个包裹送到奥格瑞玛去进行研究。"
D.Strings[29781]="什么，这个？不是什么重要的东西，只是某种……野生物种研究。"
D.Strings[29782]="胡说！你反应过度了。难道你就打算这样一直盯着我吗？"
D.Strings[29783]="%s恼怒地自言自语着。"
D.Strings[29784]="你们听说过那位女士，孩子们……给他们些烈火尝尝！"
D.Strings[29785]="血犬嗅到了气味，跟着它！"
D.Strings[29786]="血犬在这条小路尽头找到了一页文件。"
D.Strings[29787]="走开，蠢货！你根本无法和我匹敌！"
D.Strings[29788]="嘿，头儿，我相信这次晋升一定让你很高兴吧？$B$B我们全都认为只有你能代替那个恶心的老加里维克斯，得到贸易$g大王:女王;的头衔。虽然你从没有听我这样说过！$B$B我们还有许多事要做，但时间却很少。希望你已经做好了准备。"
D.Strings[29789]="我们只需要把离心球敲回去就行了，简单！"
D.Strings[29790]="翻滚的白烟……这是预先计划的吗？"
D.Strings[29791]="嗨，$r。最近有什么赚钱的买卖吗？"
D.Strings[29792]="好吧，我的单人传送器已经做好测试准备了！我是说，已经可以使用了。我不会把没经过测试的设备给你用的，对不对？"
D.Strings[29793]="我想，我已经做好传送准备了。"
D.Strings[29794]="欢迎来到石爪山脉，朋友！索博兹正在等你。"
D.Strings[29795]="站直了，$n！屏住呼吸，"
D.Strings[29796]="嗯，$G他:她;要完蛋了。"
D.Strings[29797]="哇！！下雨了！"
D.Strings[29798]="移动系统可运转。恢复传输。"
D.Strings[29799]="我需要另一个加兹瑞迪安探测器。"
D.Strings[29800]="这些猴子真让人头痛！"
D.Strings[29801]="嘿，$n，很高兴见到你。这些猴子已经快把我逼疯了！$B$B你需要些什么？"
D.Strings[29802]="我们要让这个主动式负载平衡器重新转起来！"
D.Strings[29803]="我要做的就是重新设定震荡冷却阀门……"
D.Strings[29804]="什么？$n，你不是个术士。$B$B我不可能教导你这样的$c，$g先生:女士;。"
D.Strings[29805]="$n，很高兴你在这里。或许我能教你一两招。$B$B你觉得怎么样，$g先生:小姐;？"
D.Strings[29806]="不管怎样，我怀疑你不会想接受我的训练，$n。我不确定你的手指能不能控制好火焰箭。"
D.Strings[29807]="我不了解你，$n，但我可不打算被永远困在这座岛上！$B$B如果我那时留在学院里，学会该如何使用传送魔法……"
D.Strings[29808]="你能相信这些猴子吗，$n？"
D.Strings[29809]="哦，你来得正好……未来的元素大师！今天你想接受怎样的训练？"
D.Strings[29810]="即使不是牧师也可以缴纳什一税，你的金币一样受欢迎，$g先生:女士;。"
D.Strings[29811]="圣光在上，记住，$n，如果你要成为一名牧师，你就需要许多金币来应付一切事务。$B$B所以千万不要羞于向凡人要求捐献。"
D.Strings[29812]="我很惊讶，$n，像你这样的$c竟然能看到我。我正在专心潜行呢！"
D.Strings[29813]="当然，$n，我会训练你。但你一定要小心那些猴子！"
D.Strings[29814]="全能战士NX-01型当前处于离线状态。"
D.Strings[29815]="全自动战士训练机NX-01型联线运行中。$B$B如要接受训练，请塞入硬币。"
D.Strings[29816]="这可真漂亮！……我们有没有搞清楚它是做什么的？"
D.Strings[29817]="不知道。但它现在做得实在是完美！"
D.Strings[29818]="马上，诺兹。"
D.Strings[29819]="这个主动式负载平衡器能工作吗？让它运转起来！最大能量！"
D.Strings[29820]="斯布特瓦夫，你是个天才！我要30。"
D.Strings[29821]="有时候，如果我们距离太远，雾气就会让我们无法找到路径。让我们更深入一些，重试一次。"
D.Strings[29822]="%s开始施放|cFFFFFFFF光明漩涡！|r切换到|cFFFFFFFF光明|r 精粹！"
D.Strings[29823]="%s开始施放|cFF9932CD黑暗漩涡！|r切换到|cFF9932CD黑暗|r 精粹！"
D.Strings[29824]="死吧，废物！"
D.Strings[29825]="$R，我要你的脑袋。"
D.Strings[29826]="为了北卫军！"
D.Strings[29827]="海军少将会知道这件事的。"
D.Strings[29828]="竞技场战斗将在四十五秒后开始！"
D.Strings[29829]="孩子！到这里来！"
D.Strings[29830]="……小狗，我们给你找了一个好骨头。"
D.Strings[29831]="把钥匙给我，你这个蠢货！"
D.Strings[29832]="%s向那条叫查莉的狗吹了声口哨。"
D.Strings[29833]="平局！"
D.Strings[29834]="联盟夺取了最后一面旗帜！"
D.Strings[29835]="这是给我准备的绞架……"
D.Strings[29836]="你终于来了。喜欢这里的风景吗？"
D.Strings[29837]="很高兴看到你。我们现在可以开始了吗？"
D.Strings[29838]="凯拉说你也许需要帮助。"
D.Strings[29839]="你在这里！我还以为你被那些熊怪抓住了。"
D.Strings[29840]="很高兴见到你。他们散布在这些隧道的每一个角落里。我们必须时刻保持警惕。"
D.Strings[29841]="我受伤了！不要管我，继续前进。"
D.Strings[29842]="我需要找个地方休息一下。继续吧……不要把那些圣物丢下。"
D.Strings[29843]="我受伤了！我需要休息一下。"
D.Strings[29844]="看到那些熊怪的堕落，我感到非常伤心。他们曾经是我们的朋友。"
D.Strings[29845]="这个地方已经遭到了污染……我们需要带着那些圣物尽快离开这里。"
D.Strings[29846]="我还没有看到那些沉眠的德鲁伊。他们一定是已经被带走了。"
D.Strings[29847]="我应该预见到今天的景象。这种污染已经扩散了相当长的一段时间。"
D.Strings[29848]="如果熊怪会变成今天这种样子，那么泰达希尔其余的地方又会是怎样？"
D.Strings[29849]="一定有办法阻止这种污染将我们全部吞噬。"
D.Strings[29850]="诅咒你，范达尔！你怎么会培育出这种受诅咒的“世界之树”？"
D.Strings[29851]="呀！！"
D.Strings[29852]="部落夺取了最后一面旗帜！"
D.Strings[29853]="什么？你疯了吗？！你要把我也炸成碎片吗！"
D.Strings[29854]="$n，是你！谢谢你，$g兄弟:甜心;！"
D.Strings[29855]="炸开我的逃生舱。我喜欢你的风格，$n！"
D.Strings[29856]="$n？我听说你已经死了。"
D.Strings[29857]="你就不能用一下撬棍么？"
D.Strings[29858]="$n！请告诉我那个混蛋贸易大王已经挂了……"
D.Strings[29859]="谢谢你，$n。但你欠我的钱还是得还，$g先生:女士;！"
D.Strings[29860]="这些联盟船干嘛要向我们开火？！我好像又看见了一艘部落船？"
D.Strings[29861]="时间到！"
D.Strings[29862]="<那个喝醉的工程师对你眨着惺忪的醉眼。>"
D.Strings[29863]="<把他敲昏。>"
D.Strings[29864]="哈哈哈，很好，$n！"
D.Strings[29865]="如果这只绿色的大怪物在五秒钟之内不安静下来，我就要聋掉了。我知道该如何操纵这家伙。我可不是白痴！"
D.Strings[29866]="呆子，如果不是我在这里，泽匹克会让我们直接撞上悬崖。"
D.Strings[29867]="如果你不介意这些沙尘，那这就是一次很不错的旅行。"
D.Strings[29868]="离这道悬崖远一点，我可不想看到你摔下去。"
D.Strings[29869]="我干活呢。"
D.Strings[29870]="<工程师一头栽倒在地。>"
D.Strings[29871]="<搜一搜他的口袋。>"
D.Strings[29872]="嘿，我正在休息。"
D.Strings[29873]="欢迎登上西风号飞艇。搭乘它，你能以最快的速度穿越贫瘠之地。请坐下来，尽情享受飞行的乐趣吧。没有什么能比干燥的空气混合上汽油味更好闻的了。"
D.Strings[29874]="嘘！有人在这里。"
D.Strings[29875]="不要误会我的意思……我很高兴玛法里奥能回来，但这实在太令人怀疑了。范达尔出了什么事？"
D.Strings[29876]="我是图维。我的工作就是维护这里的和平，警惕敌人的入侵。所以我一直保持着最高度的警觉。"
D.Strings[29877]="那里有一只鸟！"
D.Strings[29878]="那团云看上去就像是个大酋长。"
D.Strings[29879]="小心那艘船！一个鹰身人！……等等，那只不过是一只鸟。"
D.Strings[29880]="那里有一只虫子。"
D.Strings[29881]="奥格瑞玛还是那么的巍峨和险峻。赶快休息一下吧，孩子，一会就要返回雷霆崖了！"
D.Strings[29882]="下一站，雷霆崖！"
D.Strings[29883]="小心！你应该不会想摔成一团肉酱吧。欢迎来到雷霆崖！"
D.Strings[29884]="好吧，孩子们，让我们飞越奥格瑞玛！"
D.Strings[29885]="小心。小心！我已经感到颤动了！你差一点就要把那座塔撞塌了，呆子！"
D.Strings[29886]="我们的进度已经落后了！转向东方！东方！"
D.Strings[29887]="我已经准备好前往班尼希尔兽穴了。"
D.Strings[29888]="别傻站着，泽匹克！我们可不能把一整天的时间都花在它上面！"
D.Strings[29889]="嗨，甜心。停泊在这里的飞艇会把你一直送到雷霆崖，而且是免费的。有我们地精在，又会有谁想去骑双足飞龙？"
D.Strings[29890]="前往雷霆崖的飞艇到达了！全体登船，我们要迅速飞越贫瘠之地！"
D.Strings[29891]="你相信吗？他们终于解除了这个地方的禁制，让我们的飞艇能够穿越这里的天空了！这里不再是飞行禁区了。毕竟，我们在测试飞行中只不过让一艘飞艇撞上了崖壁。我完全不明白他们到底在担心什么。"
D.Strings[29892]="做好准备！前往奥格瑞玛的飞艇已经到达！全体登船，目标杜隆塔尔！"
D.Strings[29893]="刺贝水雷已放置就位！起爆时间："
D.Strings[29894]="你在看什么，$r？想要折磨囚犯吗？"
D.Strings[29895]="<巴隆举起他的镣铐。>$B$B好吧，$c。你信任我吗？"
D.Strings[29896]="绝不屈服，你这条恶狗！"
D.Strings[29897]="<打断朗绍尔的镣铐，解救他。>"
D.Strings[29898]="哈！$n，很高兴和你做生意。"
D.Strings[29899]="怎么样？你没有脑袋可以踢，没有宝藏可以挖吗？"
D.Strings[29900]="敬请随意，朋友。我和财宝都可以被埋起来。"
D.Strings[29901]="你好，$n。如果你想要接受烹饪训练，那你就找对地方了。当感恩节进行的时候，我经常会有很多新学生。"
D.Strings[29902]="加格斯普吉特！给我把这个削平——快点！"
D.Strings[29903]="没问题，头儿。"
D.Strings[29904]="挖掘"
D.Strings[29905]="拿着它，$r！我承诺过会告诉你宝藏在哪里，但从没有承诺过会让你拥有它！"
D.Strings[29906]="如果你想对感恩节的节日传统有更多了解，就和那些女侍应们聊聊天吧。"
D.Strings[29907]="哈哈！戈莫克把你打扁啦！"
D.Strings[29908]="我们已经打赢了你！"
D.Strings[29909]="看到了吗？戈莫克把笼子打破了！"
D.Strings[29910]="这种臭气哄哄的肥东西却能提供食物！"
D.Strings[29911]="你来到这里是为了和我们一起庆祝感恩节吗？"
D.Strings[29912]="%s释放了一股吸血虫群来治疗自己！"
D.Strings[29913]="%s钻入了地下！"
D.Strings[29914]="来吧，伙计！攻占那艘船，绝不留情！"
D.Strings[29915]="好了，卡斯伯特应该在下面的甲板上，跟我来吧！"
D.Strings[29916]="造反啦！"
D.Strings[29917]="戈莫克还有更多的仆从。吃个饱吧。"
D.Strings[29918]="她在那里！让我们了结这件事吧。"
D.Strings[29919]="别和我开玩笑，$r。"
D.Strings[29920]="我应该知道这一切都是你在搞鬼，双齿。接受惩罚吧，叛徒！"
D.Strings[29921]="又镇压了一场哗变。现在，把这些血污从我的甲板上洗干净！"
D.Strings[29922]="嘉维伊船长会知道的！"
D.Strings[29923]="你的伐木机就要完成了，真的！$b$b随时都有可能……请再联系我！"
D.Strings[29924]="帮我离开这里！"
D.Strings[29925]="我就指望这个了！"
D.Strings[29926]="我们成功了！女武士之匕号是我的了，完全是我的了！"
D.Strings[29927]="你告诉迪兹维格，我愿意开启谈判……"
D.Strings[29928]="伐木机……已经完成了！驾驶员又去哪儿了……"
D.Strings[29929]="欢迎，你是来和我们一起享受感恩节的吗？请坐到盛宴餐桌旁来。$B$B试试这里的每一样食品吧！我相信，这里一定会有你喜欢的东西。"
D.Strings[29930]="就像你说的那样，它们是永远也不会止歇的怪物。"
D.Strings[29931]="他们不会放弃战斗的机会。"
D.Strings[29932]="感恩节。嗯，我明白这些牛头人都渴望着向部落酋长表达他们的感激和情谊。但亡灵呢？$B$B我还以为他们早就丢弃了这种多愁善感的传统。"
D.Strings[29933]="有人告诉我，在感恩节之中，我们要做的就是纵情狂欢，并和周围的人们分享我们的快乐。$B$B我们幸运地找到了这个世界和这里勇敢的居民。我们应该全无保留地将我们的知识和力量与我们新的盟友分享。"
D.Strings[29934]="人类总是把身子裹在那种破烂的亚麻口袋里。不过他们的确知道该如何烹调美食。感恩节？那可是我的最爱！"
D.Strings[29935]="为了庆祝感恩节而进行的大规模后勤工作实在是令人吃惊……无数物资与人力都被投入其中。成千上万箱各种物料成品被运送到世界各地，摆放在数不清的盛宴餐桌上。$B$B说实话，这次的后勤活动给我留下了很深的印象。而且现在我已经饿坏了……我能闻到南瓜馅饼的香味。你能闻到吗？"
D.Strings[29936]="感恩节？倒不如说是“蠢猪节！”$B$B成千上百箱食物就这样被白白送出去了……居然一个子儿也不收！肯定是脑子进水了！$B$B不过呢，我想我应该将我的一部分家禽投资转移到火鸡上去……我无法相信那笔鸡肉投资竟然有这么大规模。那么多复活节蛋到底是从哪里来的？！"
D.Strings[29937]="感恩节是人们纵情狂欢，并与你周围的朋友分享快乐的节日。$B$B我们希望，在这个节日里，我们所有高贵的朋友们都能加入到庆祝的行列中来。"
D.Strings[29938]="这样的节日和人类的风格实在是有着巨大的反差。有谁会想到，贪婪无情的人类竟然会举办一个表达赠与和分享的节日？$B$B我很高兴看到这样欢乐的景象。达纳苏斯会不遗余力地支持这一活动。"
D.Strings[29939]="兽人和牛头人能够在这个世界上彼此找到，成为伙伴，这对他们来说实在是一件幸运的事。这两个种族有着不相上下的强猛力量。我们很高兴能和他们一起庆祝这个节日。$B$B就连被遗忘者一族也参加了这次节日庆典。虽然我并不确定他们要怎样庆祝这个节日……"
D.Strings[29940]="感恩节是人们纵情狂欢，并与你周围的朋友分享快乐的节日。$B$B在莫高雷和部落中间，我们都找到了家的感觉和亲密的朋友，来共同享用各种美好的果实。$B$B我们希望，在这个节日里，我们所有的朋友都能加入到庆祝的行列中来。"
D.Strings[29941]="那些牛头人真的很懂得什么叫美食！你有没有看见过他们做的那些菜？$B$B我要一直吃到把自己撑死……然后再从坟墓里爬出来，重新开始吃！"
D.Strings[29942]="我们为什么要庆祝……？我也不太清楚。也许是习惯吧。我又尝不出什么味道。$B$B南瓜馅饼，强效药剂……我们烹制的到底是什么真的很重要吗？"
D.Strings[29943]="棘齿城保安只是个笑话。它会向出价最高者开放。我们的保险箱可以把那些卫兵全买过来。"
D.Strings[29944]="南海珍珠号和征服号将在本周内加入我们，帮助我们进行这次入侵。"
D.Strings[29945]="征服号将首先进入棘齿城港口。它将指向喧哗声发生的地方：枪支两次齐射，制造大规模混乱。"
D.Strings[29946]="我会为女武士之匕号掌舵，并亲自率领登岸部队。"
D.Strings[29947]="等到棘齿城成为我们的新基地，奥格瑞玛的港口就会成为任我们摘取的甜美果实！"
D.Strings[29948]="别碰朗姆酒！"
D.Strings[29949]="盛宴餐桌是什么？能吃吗？"
D.Strings[29950]="一张盛宴餐桌上放着五种感恩节美食。每一份都放在一把座椅前面。$B$B坐进这些椅子里，你就能随心所欲地大吃面前的美食，并将这些美食传递给其它椅子中的朋友。能够和朋友共享的快乐才是真正的快乐！$B$B如果你吃足任何一种食物，你就能从这种食物中获得独特的好处。$B$B另外，如果你将每种食物都吃得足够多，你就能得到分享之魂！"
D.Strings[29951]="<你面前的这个巨魔从头到脚都是伤疤。一道新伤口横亘在他的脸上，豁开了他的嘴唇。>$B$B你好！$B$B巨魔把恐龙当坐骑。但与野生恐龙进行交流，并进一步训练它们是个难题！所以我会到这里来。我是一名恐龙训练师。"
D.Strings[29952]="抱歉。这件事不会再发生了。"
D.Strings[29953]="我这就去干活儿。我这就去！"
D.Strings[29954]="哦，休息结束了。"
D.Strings[29955]="我这就去干活儿，老大！"
D.Strings[29956]="这个陷阱发出一阵猛禽尖啸般的声音！"
D.Strings[29957]="为了MOTHER RUSSIA！"
D.Strings[29958]="哦，我忘记了用魔法拴住他们。"
D.Strings[29959]="……我们需要一些更小的巨魔！"
D.Strings[29960]="小心那些恐龙，它们可能非常非常聪明。$B$B上个星期，两头恐龙吸引了我的注意力，而第三头恐龙却用一根棒子偷袭我。"
D.Strings[29961]="梅格斯，我把那些钥匙错放在那艘船上了。你找到它们了吗？"
D.Strings[29962]="%s在召唤她的伙伴！"
D.Strings[29963]="狂热的维罗戈愤怒地吼叫着！"
D.Strings[29964]="该死，被你逮到了！"
D.Strings[29965]="布隆诺，你要付出代价！"
D.Strings[29966]="什么？好啊，好啊……我会把欠你的钱还给你，混蛋！"
D.Strings[29967]="把它交出来，弗兰基！"
D.Strings[29968]="什么？好啊，好啊……我明白了，我明白了！"
D.Strings[29969]="%s哼哼着放弃了挣扎，显然是认输了。"
D.Strings[29970]="<哼哼>"
D.Strings[29971]="不要愚弄我，杰克。我知道你有钱！"
D.Strings[29972]="不要打脸，不要打脸！"
D.Strings[29973]="最近生意不好做吧，萨德希？"
D.Strings[29974]="全力驰骋，绝不留情！"
D.Strings[29975]="火刃？他们在这里干什么？全力开火！"
D.Strings[29976]="$n$G先生:女士;，很高兴看到你。$B$B希望你能喜欢卡亚可乐的营销战役。我们正在计划进行一系列大规模的爆破行动，为战役的下一个阶段铺平道路。这一招对我们的目标客户群总是很有效。"
D.Strings[29977]="你会在灵魂高地的西部边缘，飞艇停泊处附近找到克伦德尔。我可不喜欢看到那种地精机器从这里飞过去……但它的确能把你送到奥格瑞玛去，只要你在那上面没吐到晕过去。在奥格瑞玛，你可以搭乘一艘飞艇前往东部王国的幽暗城或者银月城，或者另一艘前往诺森德的战歌要塞。"
D.Strings[29978]="真正的十字军绝不仅仅是在战场上对抗邪恶……十字军是一个榜样，一面正义的旗帜，是大众心中一名坚不可摧的守护者。$B$B作为高阶十字军，我的责任就是向这样的战士们分派各种值得他们去完成的任务。"
D.Strings[29979]="银月城的血精灵为$n而欢呼。"
D.Strings[29980]="埃索达的德莱尼人为$n而欢呼。"
D.Strings[29981]="铁炉堡的矮人为$n而欢呼。"
D.Strings[29982]="诺莫瑞根的侏儒为$n而欢呼。"
D.Strings[29983]="暴风城的人类为$n而欢呼。"
D.Strings[29984]="达纳苏斯的暗夜精灵为$n而欢呼。"
D.Strings[29985]="奥格瑞玛的兽人为$n而欢呼。"
D.Strings[29986]="雷霆崖的牛头人为$n而欢呼。"
D.Strings[29987]="森金村的巨魔开始颂唱歌曲，为$n而庆祝。"
D.Strings[29988]="幽暗城的被遗忘者为$n而欢呼。"
D.Strings[29989]="$n准备好了一份盛宴大餐！"
D.Strings[29990]="别想……抓住我！"
D.Strings[29991]="别杀我！"
D.Strings[29992]="丝网拦不住我！不……网把我拦住了。"
D.Strings[29993]="我们不害怕！"
D.Strings[29994]="有些奖励只会赠予那些赢得了银色北伐军及其盟友的崇拜，获得了十字军头衔的战士。$B$B提里奥亲自授命令我寻找这样的英雄，并赐予他们应得的奖章。"
D.Strings[29995]="联盟的成员们为$n而欢呼。"
D.Strings[29996]="部落的成员们为$n而欢呼。"
D.Strings[29997]="%s碰到$n后开始沸腾！"
D.Strings[29998]="大门被打破了！保卫要塞！"
D.Strings[29999]="击败这些邪恶的野兽！"
D.Strings[30000]="保护平民！"
D.Strings[30001]="打起精神来，战士们！我们必须保护我们的城市！"
D.Strings[30002]="欢迎，勇士！你是否已经做好准备，打算迎接十字军的试炼的挑战了？"
D.Strings[30003]="是的，我们已经准备好了迎接即将到来的挑战。"
D.Strings[30004]="那么，你是否准备好了接受第一个挑战？"
D.Strings[30005]="开始第一场挑战吧！"
D.Strings[30006]="我听说萨维斯领主今天去他在灰谷的高塔了。"
D.Strings[30007]="哦？你认为他真的能兑现诺言，给我们一个更强大的能量之源吗？"
D.Strings[30008]="作为上层精灵中最强大的一员，他绝不会像别人那样惨遭失败。"
D.Strings[30009]="我仍然在为可能的风险感到担心。虽然我同意，玛法里奥和他那些喜爱泥土的兄弟们都是疯子，但这个萨格拉斯就是另一回事了……"
D.Strings[30010]="嘘！安静……不要让别人听到你。"
D.Strings[30011]="他们正在屠杀囚犯！赶快行动，去援救其他人。"
D.Strings[30012]="我还以为自己再也无法活着离开这里了！"
D.Strings[30013]="我还以为我要死在那里了！"
D.Strings[30014]="我早就知道，我不应该到这场锦标赛来！"
D.Strings[30015]="我的朋友们，我的同伴们，请尽管放心。"
D.Strings[30016]="最近，我们的魔法能量正在逐渐减弱。这会儿，我们已经在调查这一现象了。不过萨维斯大人已经说过，这种魔法能量的波动起伏是正常的。"
D.Strings[30017]="不管怎样，我们来自扭曲虚空的新盟友将为我们带来新的能量源泉和无可言喻的魔法技艺。相信艾萨拉女士吧，就如同她相信你一样。"
D.Strings[30018]="%s热切地点着头。"
D.Strings[30019]="请先让我看看你的公文。"
D.Strings[30020]="%s创造出了一个虚空传送门！"
D.Strings[30021]="%s创造出了一个|cFF00FF00地狱火山！|r"
D.Strings[30022]="根据女王的命令，一切物品都要经过检查才能进城。"
D.Strings[30023]="耐心，耐心。我们很快就会加入你了。"
D.Strings[30024]="$n中了|cFFFF0000军团烈焰！|r"
D.Strings[30025]="$n受到了|cFF00FFFF血肉成灰|r效果的影响！"
D.Strings[30026]="放置"
D.Strings[30027]="哦，伊琳娜，你的眼睛，它们是那样美丽。"
D.Strings[30028]="是的，如果没有你的影子落在它们上面，它们会更加美丽的。"
D.Strings[30029]="伊琳娜，为什么你要拒绝我？只要你说一句话，我甚至能织出一张网，为你捉住太阳。"
D.Strings[30030]="那么你不赶快去做这件事？我的朋友们和我还有更重要的事要去做呢！"
D.Strings[30031]="如果能将你揽在臂弯里，那就是我梦想成真的时刻。从那里下来吧，让我们去旅行，远远地离开这里！"
D.Strings[30032]="你先去旅行吧，我做好头发之后就去追你。"
D.Strings[30033]="哦，伊琳娜，我爱你！"
D.Strings[30034]="%s打了个哆嗦。"
D.Strings[30035]="这是我生命中最伟大的时刻……"
D.Strings[30036]="离我远点，下贱的渣滓！否则小心我的靴子踹到你的脸上！"
D.Strings[30037]="瓦格里双子开始狂暴了！"
D.Strings[30038]="进来，进来！一次一个。"
D.Strings[30039]="尽情观赏我的各种器具吧！从最精巧的魔法器皿，到最时髦的先锋派风格，你在这里全都能看到。"
D.Strings[30040]="我建议你要以倾家荡产的豪情进行购买。谁能知道你在什么时候还有机会买到这么好的东西呢？"
D.Strings[30041]="千万不要再执迷于那些过时的风格了！"
D.Strings[30042]="那些猛兽实在是令人惊愕。被他们打败绝不是什么羞耻的事情。"
D.Strings[30043]="你干得真漂亮！等你再次准备好以后，就立刻通知我。"
D.Strings[30044]="我们要向这些野兽再发出狠狠的一击！"
D.Strings[30045]="我们已经准备好了。这一次情况就不一样了。"
D.Strings[30046]="你还不具备足够的力量来参与征服之岛的战斗。等你获得更多经验以后再回来吧。"
D.Strings[30047]="征服之岛上有许多非常重要的物资，我们绝不能让它落入部落的手中。你愿意加入我们的战斗吗？"
D.Strings[30048]="征服之岛上有许多非常重要的物资，我们绝不能让它落入联盟的手中。你愿意加入我们的战斗吗？"
D.Strings[30049]="我想要一副合成酿酒护目镜。"
D.Strings[30050]="我们希望所有人都会在美酒节中得到乐趣。如果能让人记住它就更好了。$b$b这副眼镜能够让每一个人都体验到喝醉时的感觉，却不必喝下许多烈酒。带上这副眼镜吧，这样你就喝醉了！只要摘下它，你就能立刻恢复清醒！$b$b你对这副眼镜有兴趣吗？"
D.Strings[30051]="什么是合成酿酒护目镜？"
D.Strings[30052]="想要踏入战场，你还没有足够的阅历。$c。等你获得更多经验以后再回来吧。"
D.Strings[30053]="你是否已经准备好了为部落而战，$c？"
D.Strings[30054]="你是否已经准备好了为联盟而战，$c？"
D.Strings[30055]="你竟敢挑战德罗丁·洛斯加尔，诸海之王？"
D.Strings[30056]="全体登上飞行战舰！做好开火准备！"
D.Strings[30057]="好，那么，让我们开始吧。"
D.Strings[30058]="只要敢于面对，即使是最黑暗的回忆也将不再可怕！"
D.Strings[30059]="%s从背上抓下来一个狗头人仆从，并准备把它扔进战场！"
D.Strings[30060]="请保护我！"
D.Strings[30061]="到底出了什么事？我们赶快离开这里！"
D.Strings[30062]="没有时间可以浪费了！"
D.Strings[30063]="狼人！到处都是狼人！"
D.Strings[30064]="这个地方不安全。赶快离开这里！"
D.Strings[30065]="赶快逃吧！他们到处都是！"
D.Strings[30066]="你都出售些什么样的配方？"
D.Strings[30067]="在线更新再次生效了！"
D.Strings[30068]="请向骄傲而强壮的暴风城总冠军，雅克布·奥勒留斯元帅欢呼吧！"
D.Strings[30069]="今天，矮人的力量将在铁炉堡的总冠军，拉娜·硬锤的身上得以展现！"
D.Strings[30070]="从大门中走出来的是克罗索斯，埃索达强大的总冠军！"
D.Strings[30071]="现在出场的是矮小却极度致命的安布罗斯·雷钉，诺莫瑞根的总冠军！"
D.Strings[30072]="进入竞技场的是达纳苏斯的总冠军，战技非凡的娅琳·永歌！"
D.Strings[30073]="干得好！你竟然打败了所有这些猛兽，这简直太神奇了！不过，我听说下一个挑战将更加艰难！"
D.Strings[30074]="有什么新的挑战正等待着我们？"
D.Strings[30075]="现在我们暂时压制住了加拉克苏斯大王，但我们不可能压制住他太长时间。"
D.Strings[30076]="敌人将有多么强大，你很快就会知道了。现在，你是否已经准备好了迎接下一场挑战？"
D.Strings[30077]="我们已经准备好了再次同那名法师作战。"
D.Strings[30078]="嗨！我看起来如何？"
D.Strings[30079]="这太好了，一定及时给我信号，让我知道该在什么时候放下那些法术。"
D.Strings[30080]="我们已经准备好了迎接下一个挑战。"
D.Strings[30081]="开始。"
D.Strings[30082]="银色盟约们很高兴地在此介绍他们的斗士，大领主。"
D.Strings[30083]="夺日者们自豪地介绍他们在这场竞赛中的代表。"
D.Strings[30084]="我可真喜欢你！你相信我？是吗？"
D.Strings[30085]="我真想念你！你到哪里去了？$B$B你真的不愿意理我吗？"
D.Strings[30086]="你喜欢我的这身打扮吗？这可是为聚会准备的。我用你的帐户买的。"
D.Strings[30087]="又有个家伙打了我。哦，这可真让人气恼！$B$B你愿意帮我打他一顿吗，甜心？谢谢，我真爱你！"
D.Strings[30088]="我全心全意地期待着你晋升到顶点的那一天。想一想，那时我就是贸易大王的太太。$B$B我还能去买下我一直想买的所有东西！！！"
D.Strings[30089]="小心。我听说这片海湾里有南海海盗。$B$B嗯，也许我应该亲自去查看一下……"
D.Strings[30090]="我们能在卡亚罗山的顶端渡过一个美好、浪漫的野餐日吗？$B$B一定要带我喜欢的香槟来！"
D.Strings[30091]="你的眼睛里有一种恶作剧的意味。你想要干什么？$B$B嗯？"
D.Strings[30092]="甜心，你去哪里了？你是否知道，当我无法联系到你的时候，是多么担心吗！"
D.Strings[30093]="你觉得我的腹肌如何，亲爱的？我刚刚从健身馆回来。$B$B现在我够健美了吧！"
D.Strings[30094]="其他那些女人只是普通朋友，亲爱的。"
D.Strings[30095]="我喜欢你的衣服！"
D.Strings[30096]="我知道，昨晚和前天晚上我都答应过你。等到明天晚上，我一定会带你去个好地方！"
D.Strings[30097]="听说早些时候南海海盗进入了港口。如果你要进城的话，一定要小心！$B$B那些海盗之中甚至还有女人！嗯，也许我应该亲自去查看一下？这只是为了保护你的安全，亲爱的。"
D.Strings[30098]="我热辣的公司总监女朋友今天过得如何？既然你已经在管理这么多事情。我想，我们随时都有可能会改称你为贸易女王$n了！我真期待那一天的到来！那样我就能随心所欲地在健身馆健身，在池塘边把皮肤晒成健美的褐色了。"
D.Strings[30099]="一个聪明的$c，一个骄傲的$r。我们非常高兴地把$n介绍给你们。"
D.Strings[30100]="$n突袭了车间！"
D.Strings[30101]="联盟夺取了车间！"
D.Strings[30102]="部落占领了车间！"
D.Strings[30103]="任何语言都无法形容这位$c在战场上的种种功业。我们骄傲地向大家介绍$n。"
D.Strings[30104]="如果你还不知道这个人的名字，那么你就应该好好看看他的战斗。我们在此向大家介绍$n。"
D.Strings[30105]="莎希，给我另一匹坐骑，让我驰向卡亚矿吧。"
D.Strings[30106]="$n守住了车间！"
D.Strings[30107]="嗨，头儿。这批巨魔奴隶可是我见过的最糟糕的一批！$B$B幸运的是，卡亚矿石似乎并没有让他们的豆腐渣脑子变得更聪明一些，对不对？"
D.Strings[30108]="戴姆维克，我立马赶回总部，马上！"
D.Strings[30109]="终于……现在我能够休息了。"
D.Strings[30110]="我的噩梦终于结束了？"
D.Strings[30111]="这真可怕……我梦见我正在和自己的朋友作战。"
D.Strings[30112]="我听不到那些尖叫声了。一切都结束了吗？"
D.Strings[30113]="我累坏了，让我先休息一下。"
D.Strings[30114]="能够为你驾驶，这是我的荣幸，我可以这样说吗？"
D.Strings[30115]="在你的英明领导下，这里的采矿工作效率达到了前所未有的高峰！那些坑道虫和懒惰的巨魔也终于安分了。"
D.Strings[30116]="现在我已经送了一个月的信。现在有什么主管的位置空缺吗？我已经把简历准备好了。"
D.Strings[30117]="好天气啊，不是吗？"
D.Strings[30118]="这些地震简直是疯了！"
D.Strings[30119]="$n在我们的锦标赛中晋升到了勇士等级。今天，我们骄傲地将$g他:她;介绍给大家。"
D.Strings[30120]="这场锦标赛中的勇士们对于这名$c有着很高评价。今天，我们就向大家介绍$n。"
D.Strings[30121]="想要找到比这位$c更强悍的勇士绝对是不容易的。今天，让我们来介绍$n。"
D.Strings[30122]="我们将向大家介绍一位强大的勇士，一位技艺高超的$c，一位光荣的$r，那就是$n。"
D.Strings[30123]="许多勇士都败在了$n的手中。现在，我们将骄傲地介绍这位可怕的$c。"
D.Strings[30124]="等着收我的律师函吧！"
D.Strings[30125]="看你往哪儿开的？"
D.Strings[30126]="你疯了吗！"
D.Strings[30127]="我的脖子！我要提出控告！"
D.Strings[30128]="我会找你的，$n！"
D.Strings[30129]="你真是个令人讨厌的家伙，$n！"
D.Strings[30130]="贸易大王会知道的，$n！"
D.Strings[30131]="%s一下撞到演武场的墙壁，晕了过去！"
D.Strings[30132]="%s爆发出狂烈的怒气，他面前的战士转眼间就被他踩在脚下！"
D.Strings[30133]="$c，是否已经准备好了迎接第一个挑战？"
D.Strings[30134]="欢迎，勇士们。今天，在你们的领袖与族人面前，你们将证明自己强大的实力。"
D.Strings[30135]="我对这些游戏可没什么兴趣，提里奥。不过……我相信它们一定很精彩。"
D.Strings[30136]="他们当然会的。"
D.Strings[30137]="感觉如何？哈！我很喜欢看着你们这些弱小的勇士是怎样失败的，人类。"
D.Strings[30138]="加尔鲁什，够了。"
D.Strings[30139]="打得好，部落！Lok'tar Ogar！"
D.Strings[30140]="终于出现了一场值得一看的战斗。"
D.Strings[30141]="我到这里来不是为了看野兽们无意义地彼此撕扯，提里奥。"
D.Strings[30142]="你将会知道，他们都是强大的战士。"
D.Strings[30143]="你首先会与这场锦标赛的三名总冠军作战。这些强大的战士已经把他们的对手都一一击败了。"
D.Strings[30144]="你要学习如何驾驭坐骑？"
D.Strings[30145]="多年以来，我一直在这个被世界遗忘的角落里工作着，查看这里的地形，在无聊中打发时间。但我的时代终会到来的。奥格瑞玛正将全部力量转向艾萨拉，我们打开了通往灰谷的通道，并终将统治这片大陆。欢迎来到前线，$c。"
D.Strings[30146]="现在请注意，强大的奥格瑞姆总冠军，碎颅者莫克拉出场！"
D.Strings[30147]="进入竞技场的是削瘦却极度危险的祖尔托，森金村的总冠军！"
D.Strings[30148]="高高地骑坐在科多兽上的是雷霆崖的总冠军，令人敬畏的鲁诺克·蛮鬃！"
D.Strings[30149]="我们现在要介绍的是幽暗城的总冠军，强韧的亡灵，死亡猎手维赛里！"
D.Strings[30150]="从大门中走出来的是埃蕾希·晨歌，强大的法师！银月城总冠军！"
D.Strings[30151]="语法错误行14，序列：逃命。进入被动模式。*点击！*"
D.Strings[30152]="不管怎样，我觉得更糟糕了。"
D.Strings[30153]="我早就知道，我应该买地震保险！"
D.Strings[30154]="跨上角鹰兽，准备作战！"
D.Strings[30155]="<这头角鹰兽看上去已经急切地准备要走了！>"
D.Strings[30156]="你们准备好了吗？我会全力以赴。"
D.Strings[30157]="什么？你想要什么？"
D.Strings[30158]="快滚开，否则奇普·英代尔的老拳可就要砸在你脸上了！"
D.Strings[30159]="你好，$n$g先生:女士;。欢迎来到南海第一科赞贸易与商业银行。$B$B我能为你做些什么？"
D.Strings[30160]="我要提款。来十捆杏仁币！"
D.Strings[30161]="这么多？好吧，感谢你的光顾，$n$g先生:女士;。$B$B祝你好运。"
D.Strings[30162]="呦！你看上去像是个有些品味的$g男人:女人; 。$B$B我能为你做些什么？"
D.Strings[30163]="把你最华丽，最耀眼的首饰都给我拿来！"
D.Strings[30164]="这件首饰就像你的妈妈一样好！"
D.Strings[30165]="怎么了？看样子你还没有足够的杏仁币来购买我这里的首饰。$B$B你也许应该先去一趟银行？"
D.Strings[30166]="你已经来不及阻止我的计划了。"
D.Strings[30167]="注意不要让我被跟踪。"
D.Strings[30168]="看看和我共事的都是什么人。苏扎博能弄出奇迹来吗？$B$B<苏扎博叹了口气>$B$B是的，是的，苏扎博认为他能为你做些事。"
D.Strings[30169]="苏扎博的服务不是你能负担得起的。我们可不提供免费服务，小家伙。$B$B还是先去银行吧。把你的杏仁币全都给苏扎博拿来。"
D.Strings[30170]="苏扎博，我需要一身闪亮的新装扮，为了我即将参加的聚会！"
D.Strings[30171]="哦，看看苏扎博做了什么。真是杰作啊！$B$B说实话，你配不上这身行头，但苏扎博需要钱。<叹气>"
D.Strings[30172]="$n突袭了码头！"
D.Strings[30173]="$n守住了码头！"
D.Strings[30174]="联盟夺取了码头！"
D.Strings[30175]="部落占领了码头！"
D.Strings[30176]="$n突袭了飞艇基地！"
D.Strings[30177]="$n守住了飞艇基地！"
D.Strings[30178]="联盟夺取了飞艇基地！"
D.Strings[30179]="部落占领了飞艇基地！"
D.Strings[30180]="$n突袭了采石场！"
D.Strings[30181]="$n守住了采石场！"
D.Strings[30182]="联盟夺取了采石场！"
D.Strings[30183]="部落占领了采石场！"
D.Strings[30184]="$n突袭了油料精炼厂！"
D.Strings[30185]="$n守住了油料精炼厂！"
D.Strings[30186]="联盟夺取了油料精炼厂！"
D.Strings[30187]="部落占领了油料精炼厂！"
D.Strings[30188]="我这里有各种各样新款墨镜。你能叫出名字的，我都有的卖！"
D.Strings[30189]="什么？你看上去没有足够的钱能买我的东西。$B$B<米萨用嘴里的泡泡糖吹了个泡泡。>$B$B也许你忘记去银行了？"
D.Strings[30190]="我需要一些超酷的墨镜。两捆杏仁币能为我换来什么样的货色？"
D.Strings[30191]="好吧，我以优惠的价格把我最好的一副遮阳镜卖给你！$B$B它一定会让你爱不释手的！"
D.Strings[30192]="狠狠打脸！狠狠打脸！"
D.Strings[30193]="这就是致命一击吗？"
D.Strings[30194]="我永远也不会喜欢你！"
D.Strings[30195]="还债的时候到了！"
D.Strings[30196]="别来惹我！"
D.Strings[30197]="你在看我吗？"
D.Strings[30198]="为这个，我已经等了一整天！"
D.Strings[30199]="愚蠢的$c，你无法阻止克瓦迪尔！"
D.Strings[30200]="你好，你是否想加入银色竞技场团队，进行与诺森德猛兽的战斗？\n\n你将以现在你所选择的难度进入这一遭遇战。这一战斗序列还在制作中。所以，请在Blizzard论坛上报告您遇到的所有bug。\n\n准备好开始这场战斗了吗？"
D.Strings[30201]="你好，你是否想加入银色竞技场团队，进行与加拉克苏斯大王的战斗？\n\n你将以现在你所选择的难度进入这一遭遇战。这一战斗序列还在制作中。所以，请在Blizzard论坛上报告您遇到的所有bug。\n\n准备好开始这场战斗了吗？"
D.Strings[30202]="$g兄弟:姐妹;你已经得到了这座岛上最好的首饰！"
D.Strings[30203]="伐木机锯刃被激活了。"
D.Strings[30204]="你买的这副墨镜是没有质保的！"
D.Strings[30205]="苏扎博已经为你制作了一套配得上贸易大王的装扮。现在离开吧，你已经把苏扎博的客人都吓跑了。"
D.Strings[30206]="欢迎来到我的店铺。我们这里有你所需要的一切……如果你所需要的是炼金术材料……"
D.Strings[30207]="你真的有卖东西吗？"
D.Strings[30208]="不，我的脑子很不错，最好不要小看我。我能够用洗碗水和蒲公英配制出治疗药剂。不过这不是我要给你的东西！$b$b不管怎样，如果你想要买东西，就请和Patricia谈谈吧。"
D.Strings[30209]="X-51虚空火箭特别加强版坐骑"
D.Strings[30210]="要不要接受训练？"
D.Strings[30211]="%s用正义之锤对准了$n！"
D.Strings[30212]="部落要塞的前门被摧毁了！"
D.Strings[30213]="联盟要塞的前门被摧毁了！"
D.Strings[30214]="部落要塞的西门被摧毁了！"
D.Strings[30215]="联盟要塞的西门被摧毁了！"
D.Strings[30216]="部落要塞的东门被摧毁了！"
D.Strings[30217]="联盟要塞的东门被摧毁了！"
D.Strings[30218]="%s开始向四周放射光芒！赶快遮住你的眼睛！"
D.Strings[30219]="榴弹发射器已装弹。"
D.Strings[30220]="一杯清新的香槟酒。这正是医生所叮嘱的，$n。"
D.Strings[30221]="感谢你给我斟酒，$g先生:女士;！"
D.Strings[30222]="这种发泡白酒真是美味！你是从哪里得到它的？"
D.Strings[30223]="我只能再喝这一杯了。聚会之后我还要开车回家。"
D.Strings[30224]="感谢！"
D.Strings[30225]="现在我觉得好多了……嗝！"
D.Strings[30226]="哦，我头痛得厉害。"
D.Strings[30227]="抱歉弄脏了你的鞋子。"
D.Strings[30228]="一场迪斯科舞会？！真棒！"
D.Strings[30229]="喜欢我的舞步吗，$n？"
D.Strings[30230]="我们应该痛快地跳一支舞！"
D.Strings[30231]="像地精巨星那样摇滚！"
D.Strings[30232]="喔！毫无疑问比我手上的小烟花精彩多了！"
D.Strings[30233]="你可真是大手笔$n！真令人惊叹！"
D.Strings[30234]="这是……最好的……聚会！"
D.Strings[30235]="喔，喔，焰火！再放一次，再放一次！"
D.Strings[30236]="谢谢，我几乎不行了。实在太饿了！"
D.Strings[30237]="这是我尝过的最好吃的开胃菜。$n，一定要告诉我你的厨艺秘方！"
D.Strings[30238]="啊，真是吮指回味！"
D.Strings[30239]="味道还不错！"
D.Strings[30240]="守卫大门！"
D.Strings[30241]="把这个混蛋赶回到森林里去！"
D.Strings[30242]="我的墨镜丢了！"
D.Strings[30243]="我需要一套新装扮！"
D.Strings[30244]="我的漂亮首饰丢了！"
D.Strings[30245]="正义之锤！"
D.Strings[30246]="应急能量联线。"
D.Strings[30247]="你的聚会客人一定会对你的穿着赞叹不已！使用下面的新能力来让你的聚会客人高兴吧！"
D.Strings[30248]="我还需要一个神谕者孤儿哨。"
D.Strings[30249]="战利品在哪里？"
D.Strings[30250]="让我们跳支舞吧！"
D.Strings[30251]="我们要向贸易大王表示礼貌。"
D.Strings[30252]="有朗姆酒吗？"
D.Strings[30253]="好了，小子们。搅个天翻地覆吧！"
D.Strings[30254]="我们要的是黄金！"
D.Strings[30255]="谁在这里管事？"
D.Strings[30256]="我把我的图腾丢掉了，你能帮助我吗？"
D.Strings[30257]="请一定更加小心，$n。这件宝物是由大地之环所创造的。它是我们赠予你的礼物。"
D.Strings[30258]="元素之灵是睿智的。在我们出现之前，他们早已经存在于此，在我们尽数消失之后，他们仍然会在这里长存不息。当他们对我们说话的时候，我们必须仔细倾听。"
D.Strings[30259]="元素之灵就在我们身边。我们必须时刻注意倾听他们的声音。我亲眼见到过当我们忽视他们的警告时，发生了怎样的灾难……"
D.Strings[30260]="$n守住了联盟要塞"
D.Strings[30261]="$n守住了部落要塞！"
D.Strings[30262]="$n突袭了联盟要塞！"
D.Strings[30263]="$n突袭了部落要塞！"
D.Strings[30264]="联盟夺取了联盟要塞！"
D.Strings[30265]="联盟夺取了部落要塞！"
D.Strings[30266]="部落占领了部落要塞！"
D.Strings[30267]="真是一场精彩的聚会，$n。迪斯科舞会更是令人兴奋！"
D.Strings[30268]="<因为大胖嘴里塞满了食物，你听不清他到底在说些什么。不过你可以确信，他一定是在感谢你。>"
D.Strings[30269]="这是我最好的朋友！来吧，$n，和我们一起跳舞吧！"
D.Strings[30270]="塔伦迪斯古树痛苦地吼叫着！"
D.Strings[30271]="海盗？海盗！"
D.Strings[30272]="但我已经付过保护费了！"
D.Strings[30273]="是谁雇佣了这些海盗？这太棒了！真是精彩的聚会！哦，这很痛！他们的武器是真的！！！"
D.Strings[30274]="你的报酬是多少？我付双倍……三倍？！哦，不！"
D.Strings[30275]="南海海盗？这个地方真的要完蛋了。"
D.Strings[30276]="来吧！只要齐心协力，我们就能打败他们！啊！"
D.Strings[30277]="滚开，虫子。你不属于这个地方。不要激怒我。"
D.Strings[30278]="你怎么会来到这里，年轻的$r？请小心，我们的敌人正在从东边山脉中的一个窟窿里源源不断地涌出来。他们对这片土地造成了严重的伤害。"
D.Strings[30279]="别让你的机器碰到我，$r！你会像那些杂草一样从这片土地上被清除掉！"
D.Strings[30280]="再次感谢你能“帮助”那些懒家伙，老板。$B$B要我说，我们既然已经不再是那些巨魔的奴隶，就不应该对那些巨魔太仁慈。"
D.Strings[30281]="谢谢你救了我， $n$g先生:女士;。"
D.Strings[30282]="为什么贸易大王会这样做？"
D.Strings[30283]="那么，下一次聚会在什么时候开始？"
D.Strings[30284]="你看到我的女朋友了吗？"
D.Strings[30285]="聚会结束了吗？"
D.Strings[30286]="请把我从你的客人名单里划去。"
D.Strings[30287]="我可不知道这场聚会里还有海盗表演。我真应该把眼罩带来！"
D.Strings[30288]="%s开始施放梦魇乍醒！"
D.Strings[30289]="我们会永远记住这次拜访。绝不要忘记你从新朋友那里学到了什么，小鲁鲁。远大的未来正在前方等着你。"
D.Strings[30290]="别担心，科科。你要长大，成为一名强壮的狂心者。你要率领族人返回旧日的家园。那里不会再有大舌头怪。"
D.Strings[30291]="那箱炸药着火了！"
D.Strings[30292]="来追我们，你们这些可恶的野兽！"
D.Strings[30293]="在这儿，你这跳蚤！"
D.Strings[30294]="你永远抓不到我们，该死的杂种！"
D.Strings[30295]="让我们尽可能地把他们引过来。多一只狼人追我们就少一只狼人追杀幸存者！"
D.Strings[30296]="警告！警告！发现有敌人潜入！"
D.Strings[30297]="我丢掉了紫罗兰要塞的钥匙。"
D.Strings[30298]="苏伦命令我来这里，向你借弗瑞恩的龙鹰使用。"
D.Strings[30299]="$n是我的目标！"
D.Strings[30300]="地精百宝腰带的电池耗光了。"
D.Strings[30301]="看到那些爆盐炸弹了吗？在我修理这部攻城器械的时候，你要对大门使用它们！"
D.Strings[30302]="一路平安，$c。"
D.Strings[30303]="我就要完成了！挡住那帮部落的家伙。他们可不是在工程学校进行战斗教学！"
D.Strings[30304]="这是我最成功的作品！这部攻城器械已经准备好，随时可以使用了！"
D.Strings[30305]="它已经坏了？！别担心，没有我修不好的。"
D.Strings[30306]="去为聚会准备服装吧。"
D.Strings[30307]="大胖哼哼着道了别。"
D.Strings[30308]="聚会上见，宝贝儿！"
D.Strings[30309]="前往一家银行。"
D.Strings[30310]="%s向那一排卫士点点头，招手示意吉安娜随他来。"
D.Strings[30311]="拜访一名商人。"
D.Strings[30312]="造访马厩。"
D.Strings[30313]="我要处理这部攻城器械，掩护我。如果有需要，就对大门使用那些爆盐炸弹！"
D.Strings[30314]="我就要完成了！挡住那帮联盟的家伙，合同上没说我还得打仗！"
D.Strings[30315]="攻城坦克已经准备好了！"
D.Strings[30316]="它又坏了？！我会把它修好……但我可不保证它一定能好用。"
D.Strings[30317]="提里奥。"
D.Strings[30318]="瓦里安国王，吉安娜女士，欢迎你们的到来。我们恭候多时了。"
D.Strings[30319]="谢谢，这是我唯一能做的。我们需要同心协力。"
D.Strings[30320]="你说个不停，提里奥。要平心静气，要相信那些野人会管住自己。"
D.Strings[30321]="我的人在这里是为了确保比赛的井然有序。最好让你的部下知道你在看着他们。"
D.Strings[30322]="%s点点头，招手示意他的客人跟上。"
D.Strings[30323]="也许吧。我觉得这比赛没什么意义。我们现在就应该集结大军发动总攻。"
D.Strings[30324]="但如果我出席这些比赛能换来你在战争中的协助。那我暂时，会留下来。"
D.Strings[30325]="我相信萨尔会管住他的部下……"
D.Strings[30326]="的确会有人不再想获得经验。他们想永远停留在现有的水平，不再变得更强。$B$B我可以实现这一点……当然，我需要收取一些费用。$B$B但你要明白：一旦你把酬金支付给我，你就无法再获得经验了。是一直，而不是一段时间。$B$B如果你以后又改变主意，想要重新开始获取经验，也可以向我支付同样多的酬金，让我解除这一禁制。"
D.Strings[30327]="我已经不再想获得经验了。"
D.Strings[30328]="我希望能再次开始获取经验。"
D.Strings[30329]="你确定想要再一次开始取得经验？"
D.Strings[30330]="访问邮箱。"
D.Strings[30331]="你确定想要停止获取经验？"
D.Strings[30332]="这可真是令人惊叹。那么，你准备好迎接下一个挑战了么？"
D.Strings[30333]="今天，你在竞技场上的表现给所有人都留下了深刻的印象。现在，你将在万众瞩目下成为这次比武的冠军。"
D.Strings[30334]="我已经为下一个挑战做好了准备。"
D.Strings[30335]="那些狗继续去闻味了？"
D.Strings[30336]="干得漂亮！你的下一个挑战将来自于十字军的骑士们。他们将以强大的实力对你进行测试。"
D.Strings[30337]="正在走进竞技场的是一位对于战场和比武场都绝不陌生的圣骑士——银色十字军的总冠军，纯洁者耶德瑞克！"
D.Strings[30338]="接下来出场的是圣光最忠实的追随者！银色神官帕尔崔丝！"
D.Strings[30339]="干得好，今天，你证明了自己的实力。"
D.Strings[30340]="那些椽子旁边是什么？"
D.Strings[30341]="你搞砸了我的盛大登场，鼠辈。"
D.Strings[30342]="你们真以为，巫妖王的战士会败在你们那可怜的比武场上？"
D.Strings[30343]="我是来做个了断的。"
D.Strings[30344]="不要只是傻站在那里，干掉他！"
D.Strings[30345]="把他撕碎！"
D.Strings[30346]="加尔鲁什，我希望你能控制自己。我不想紫罗兰城堡的一幕再发生。"
D.Strings[30347]="哼！那只是领袖在展示他的力量。我真后悔没在那个法师插手前干掉那个人类。"
D.Strings[30348]="挥舞粗头棒子有什么荣誉可言？这是在浪费时间。"
D.Strings[30349]="别算上我，萨尔。"
D.Strings[30350]="一派胡言。部落杀死那只亡灵易如反掌，不需要你，更别说那个傲慢的国王。"
D.Strings[30351]="我们是客人，加尔鲁什，你要注意你的言行。"
D.Strings[30352]="感谢您的邀请，弗丁大人。我们期待着精彩的比赛。"
D.Strings[30353]="说的好。"
D.Strings[30354]="加尔鲁什，够了！"
D.Strings[30355]="当然，提里奥，我为他的莽撞向你致歉，我保证下不为例。"
D.Strings[30356]="这座纪念碑以永不消失的古老能量发出各种嗡嗡和噼啪的声音。"
D.Strings[30357]="你发现身上没有漩涡宝石，便将手伸到符文石中，又拿了一枚。"
D.Strings[30358]="在你眼前的是这个世界上最具艺术品位的采矿系统。只有土包子才会在山下挖隧道以获得矿石。我们则会将整座山移开！现在，我们就可以直接从地面上挖掘珍贵的金属了。"
D.Strings[30359]="为了夺回你的私人财产，你要砸开保险库！"
D.Strings[30360]="使用你的地精百宝腰带上必要的功能，打开这座保险库！功能具体如下：$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |TInterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |TInterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |TInterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t"
D.Strings[30361]="一旦|cFFFF2222保险库破坏进度条到达百分之百，保险库就会被打破！|r$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t$B在错误的时间采取错误的行动会让进度条后退。"
D.Strings[30362]="我自由了！"
D.Strings[30363]="我出来了……"
D.Strings[30364]="噩梦结束了！"
D.Strings[30365]="我被石化的时间仍然可以算在工作时间里，对吧？"
D.Strings[30366]="要给那个$g男人:女人;加薪！"
D.Strings[30367]="没有任何工作值得这样做！"
D.Strings[30368]="使用你的|cFFFF2222卡亚矿钻！|r$B|TInterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t"
D.Strings[30369]="使用你的|cFFFF2222爆裂弹!|r$B|TInterface\\Icons\\INV_Misc_Bomb_07.blp:64|t"
D.Strings[30370]="使用你的|cFFFF2222顺风耳！|r$B|TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t"
D.Strings[30371]="使用你的|cFFFF2222无限复杂开锁器！|r$B|TInterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t"
D.Strings[30372]="我退出，我退出！"
D.Strings[30373]="这里真是安静得令人惊讶。"
D.Strings[30374]="%s发狂了！"
D.Strings[30375]="%s等着$n，发出一阵震耳欲聋的怒吼！"
D.Strings[30376]="%s的尖刺正在追击$n！"
D.Strings[30377]="可以开始了！"
D.Strings[30378]="这么长时间里，我们终于有机会研究散布在这里的废墟了……希望这些财迷不会先把这个地方毁掉"
D.Strings[30379]="和我说说附近的那些废墟。"
D.Strings[30380]="你不属于这里，$r！"
D.Strings[30381]="你的脚踏在神圣的土地上，$c……"
D.Strings[30382]="$r，这里不欢迎你们！"
D.Strings[30383]="易如反掌。"
D.Strings[30384]="这就是部落最强的战士？"
D.Strings[30385]="联盟对付这些部落垃圾不需要恶魔领主的帮助！来吧，蠢货！"
D.Strings[30386]="为荣耀而战！英雄们，为国王和人民而战！"
D.Strings[30387]="我们的荣耀被玷污了！他们对我们进行肆意的污蔑与诽谤。我要讨回公道！请允许我的勇士代替你的人出场，提里奥。我们要挑战部落！"
D.Strings[30388]="即使是巫妖王最强大的爪牙也无法与联盟抗衡。为胜利欢呼吧！"
D.Strings[30389]="你的猛兽阻挡不了我的勇士！提里奥。"
D.Strings[30390]="发现自己并没有盛怒漩涡宝石，你便伸手到符文石中，又取了一枚。"
D.Strings[30391]="败了……"
D.Strings[30392]="狡诈的联盟狗！召唤恶魔领主来对抗部落的战士？你们离死不远了。"
D.Strings[30393]="使用你的|cFFFF2222神奇地精射线！|r$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t"
D.Strings[30394]="不要手下留情，部落勇士们！LOK'TAR OGAR!"
D.Strings[30395]="正确！"
D.Strings[30396]="部落需要公正！我们向联盟挑战！请允许我们代你出战，圣骑士。我们要让那些狗知道侮辱部落的下场。"
D.Strings[30397]="这只是一个小小的开始。为了部落！"
D.Strings[30398]="圣骑士，你还在怀疑部落的力量吗？我们战无不胜！"
D.Strings[30399]="我在鲜血之环经历过更强大的挑战。这是浪费时间，圣骑士。"
D.Strings[30400]="欢迎，勇士们！你们听到了银色北伐军的号召，并勇敢地作出了响应！此时此地，就在十字军演武场，你们将面对最强大的挑战。能在这次选拔中活下来的人都将加入北伐的行列，共同进军冰冠堡垒！"
D.Strings[30401]="他来自风暴峭壁最幽深，最黑暗的洞穴，穿刺者戈莫克！准备战斗，英雄们！"
D.Strings[30402]="做好准备，英雄们，两头猛兽已经进入了竞技场！它们是酸喉和恐鳞！"
D.Strings[30403]="当下一名斗士出场时，空气都会为之冻结！它是冰吼，胜或是死，勇士们！"
D.Strings[30404]="这些恐怖的野兽终于被消灭了！"
D.Strings[30405]="悲剧……他们英勇奋战，但还是没有制服诺森德的猛兽。让我们为这些死去的英雄默哀。"
D.Strings[30406]="高阶术士威尔弗雷德·菲兹班将是你们的下一个对手。等待他的上场吧。"
D.Strings[30407]="快，英雄们，消灭那只恶魔，不要让他打开通向恶魔空间的传送门！"
D.Strings[30408]="很遗憾，我们失去了威尔弗雷德·菲兹班，但这也给那些胆敢研习黑暗魔法的人们敲响了警钟。唉，你胜利了。准备面对下一个挑战吧。"
D.Strings[30409]="大家冷静！不要慌乱！这并不是什么阴谋！这名术士只是在按照自己的意愿行事，并不是联盟的授意。比赛必须继续！"
D.Strings[30410]="接下来你们将面对银色北伐军最强的骑士！只有打败他们，才能证明你的价值……"
D.Strings[30411]="好吧，我同意了。为荣誉而战吧！"
D.Strings[30412]="肤浅且可悲的胜利。今天的内耗让我们又一次被削弱了。这种愚蠢的行为只能让巫妖王受益！伟大的战士们就这样白白牺牲，而真正的威胁却步步逼近。巫妖王正计算着我们的死期。"
D.Strings[30413]="你们只有团结才能战胜最终的挑战。来自于冰冠冰川的深处，天灾军团最强的战将：巫妖王的双翼使者，恐怖的瓦格里！"
D.Strings[30414]="这是对巫妖王的一次重创！你的实力绝不亚于银色北伐军的勇士。很快，我们将携手攻入冰冠堡垒，消灭天灾军团的残余！只要心齐，我们必将胜利！"
D.Strings[30415]="阿尔萨斯！你已经孤立无援了！放下霜之哀伤，我会让你死个痛快。"
D.Strings[30416]="欢迎参加十字军的试炼！只有全艾泽拉斯最强大的斗士才能参加这次选拔。而你正是其中之一。"
D.Strings[30417]="感谢你，大领主。挑战者们，我将开始召唤仪式。当仪式完成时，一个恐怖的末日守卫就会出现！"
D.Strings[30418]="准备迎接末日吧！"
D.Strings[30419]="啊哈！我做到了！看看召唤大师威尔弗雷德·菲兹班强大的力量吧！为我效命吧，恶魔！"
D.Strings[30420]="我才是主人……呦，哦……哦……"
D.Strings[30421]="渺小的侏儒！你们的傲慢将会招致灭亡！"
D.Strings[30422]="面对加拉克苏斯吧，燃烧军团的艾瑞达之王！"
D.Strings[30423]="卑微的虫子！"
D.Strings[30424]="被逐入虚空吧！"
D.Strings[30425]="会有人来代替我。而你们注定要被毁灭……"
D.Strings[30426]="血肉成灰！"
D.Strings[30427]="前进！这是主人的命令！"
D.Strings[30428]="地狱——之火！"
D.Strings[30429]="以黑暗之主的名义。为了巫妖王。你必死无疑。"
D.Strings[30430]="我们确认了你的力量，知道你正是我们需要的人。"
D.Strings[30431]="无能！"
D.Strings[30432]="天灾军团无人可挡……"
D.Strings[30433]="让黑暗吞噬你！"
D.Strings[30434]="让光明焚毁你！"
D.Strings[30435]="会有人战败你的，弗丁。"
D.Strings[30436]="蛛魔在诺森德的冻土荒原地下建立了一个帝国。只有最愚蠢的人才会在这个帝国上方建起房屋。那是我的帝国！"
D.Strings[30437]="你们死去勇士的灵魂都将属于我，弗丁。"
D.Strings[30438]="啊，我们的客人到了，主人说的果然没错。"
D.Strings[30439]="这里将是你的葬身之地！"
D.Strings[30440]="又是一个献给主人的灵魂。"
D.Strings[30441]="我让您失望了，主人……"
D.Strings[30442]="Auum na-l ak-k-k-k, isshhh。起来，奴仆们，吃吧……"
D.Strings[30443]="虫群会吞噬你！"
D.Strings[30444]="呃！你！回去再练练吧。"
D.Strings[30445]="不！不！我再说一遍，不！还不够好。"
D.Strings[30446]="我认输！我投降。你做的很好。我可以走了吧？"
D.Strings[30447]="感谢你，传讯者，你的话真令我高兴。"
D.Strings[30448]="愿圣光赐我力量，让我不负众望。"
D.Strings[30449]="现在，让时光在你脑中倒流。"
D.Strings[30450]="下去休息吧。"
D.Strings[30451]="安心的去吧。"
D.Strings[30452]="这场闹剧该结束了！"
D.Strings[30453]="真是对生命的浪费。"
D.Strings[30454]="不！我绝不能再……失败了……"
D.Strings[30455]="我的烂肉还真碍事！"
D.Strings[30456]="我可不需要用骨头来打败你！"
D.Strings[30457]="时间结束！"
D.Strings[30458]="你了解上古战争吗，$n？那是在万年以前发生的事情。那时，燃烧军团的恶魔第一次到达艾泽拉斯。他们打算将这个世界彻底吞噬，就如同他们吞噬无数个其它世界一样。在这次入侵中，这片土地曾经的心脏——艾萨拉的古老首都被夷为平地。你会在这一地区的各个角落找到古老的废墟遗迹，它们就是祖先曾经自负的证据。"
D.Strings[30459]="我现在很关心东边门纳尔湖周围的废墟。千万年以前，门纳尔学院第一个开始研究奥术的技艺，那是一座美丽的多层建筑，环绕一座平静的湖泊，非常有利于贤者们沉思和冥想。正是在那里，我的祖先首先发现魔法能量从永恒之井中溢出。$B$B很抱歉，我的介绍是不是太过冗长了？至今为止，我沉浸在这段神秘的历史中已经有数十年之久。我忘记了，其他人并不一定有和我一样的兴趣。"
D.Strings[30460]="不，请继续。"
D.Strings[30461]="总的来说，学院对于这种新发现的力量抱着相当谨慎的态度。从那个时代留存下来所剩无几的史籍资料来看，当时的贤者法师们非常担心我们会沉迷在这种奥术能量中而无法自拔,而这正是时至今日仍困扰我族的麻烦根源。$B$B因此，门纳尔贤者们最终与艾萨拉女王和她的上层精灵仆从决裂。而艾萨拉女王和她的奴仆很快便肆无忌惮地汲取并滥用这股力量，丝毫不在意这其中蕴含的巨大危险。"
D.Strings[30462]="当燃烧军团发动攻击时，门纳尔学院的贤者法师们已经远离了艾萨拉女王。他们本应该在那场战争中发挥巨大的力量，但当精灵的都市毁灭时，他们拒绝撤退。$B$B他们没有在城外重新集结，加入到反击燃烧军团的队伍中，而是留了下来，竖起魔法屏障，将他们曾经静瑟安详的家园变成一座堡垒。在恶魔入侵刚刚开始的那段恐慌日子里，难民不断涌入门纳尔学院，幸存者们开始在那里建立防御。"
D.Strings[30463]="他们挡住恶魔的进攻了吗？"
D.Strings[30464]="挡住？面对燃烧军团先锋的全力进攻？这根本不可能！$B$B不，历史没有记录后来发生了什么……那里已经不再有幸存者了。狂暴的恶魔只留下了你今天所看到的这些废墟。学院的秘密就深埋在这片艾萨拉的泥土中。"
D.Strings[30465]="我们要把他们挖出来。"
D.Strings[30466]="我喜欢你的想法，$r！$B$B就在不久以前，埋藏在这片废墟中的魔法能量还一直吸引着蓝龙军团的注意。所以我无法对这里进行研究。而现在，那些巨龙的注意力已经转移到别的地方去了，但一个更加可怕的威胁正在形成——那些绿色的小畜生想要把这片废墟推平，为一座燃料补给站开辟道路！用不了多久，埋藏上万年的神秘知识就将永远遗失了。我们必须尽快采取行动。"
D.Strings[30467]="欢迎你们，萨尔酋长，地狱咆哮统帅。"
D.Strings[30468]="我希望你能明白现在的状况，加尔鲁什。如果再这样互相争斗，就休想战胜天灾军团。"
D.Strings[30469]="在我这里，各位，我相信你们不会乱来。"
D.Strings[30470]="那就请跟我来。"
D.Strings[30471]="感谢圣光！我绝不会再干这种蠢事了！"
D.Strings[30472]="他们马上就要把我绑在祭坛上，吸取我的灵魂里。让我们赶快离开这里！"
D.Strings[30473]="让我们狠狠地教训那些邪教疯子！我要把他们全都砍成两段！"
D.Strings[30474]="让我们救出剩下的候选者，杀回营地去。然后我要喝下满满一桶啤酒！"
D.Strings[30475]="给那些邪教徒们一个教训。$n。没有人能在惹恼了北伐军战士库尔之后全身而退！"
D.Strings[30476]="干得好，胜利属于部落！"
D.Strings[30477]="你打得非常英勇。"
D.Strings[30478]="勇士们，祝贺你们！经历过一系列计划之中和意料之外的试炼，你们终于取得了胜利。"
D.Strings[30479]="现在去休息一下吧，辛苦了。"
D.Strings[30480]="你获得了|cFFFFFFFF光明之触。|r转换为|cFFFFFFFF光明精粹|r！"
D.Strings[30481]="参加联盟和部落之间的战斗吧！欢迎你加入到银色十字军的麾下。"
D.Strings[30482]="我们的目标就在南方。我们将向那座要塞进军，直捣天灾军团的心脏。"
D.Strings[30483]="这可不是一个轻松的任务。"
D.Strings[30484]="一场动员所有人参加的大规模攻击只会导致本可以避免的惨重伤亡。而每一名倒下的士兵都会变成敌人再爬起来。到那时候，艾泽拉斯将再没有力量对抗亡灵怪物的威胁。"
D.Strings[30485]="实际上，我们需要组建一支小规模的精英力量，对敌人造成致命打击。这才是我们的取胜之道。所以我们举办了银色锦标赛。"
D.Strings[30486]="你获得了|cFF9932CD黑暗之触。|r转换为|cFF9932CD黑暗精粹|r！"
D.Strings[30487]="你将在这里接受测试。你必须以自身的战斗实力来对抗诺森德最凶暴危险的力量。而你的领袖们将亲眼见证你的战斗。"
D.Strings[30488]="你们的勇敢、力量和机智都将受到万众瞩目。这些竞赛将决定谁才是艾泽拉斯最强的战士。"
D.Strings[30489]="胜利者将成为进攻冰冠堡垒大军的先锋。我们将并肩对抗邪恶。阿尔萨斯必将灭亡！"
D.Strings[30490]="%s仔细察看着这些被找到的财宝，直到有什么东西吸引了她的目光。"
D.Strings[30491]="啊！这枚戒指就很不错……"
D.Strings[30492]="瓦里安·乌瑞恩国王殿下和吉安娜·普罗德摩尔女士已经茹临比武场！让路！"
D.Strings[30493]="部落的酋长萨尔和督军加尔鲁什·地狱咆哮已经来到比武场！让路！"
D.Strings[30494]="大领主提里奥·弗丁已经来到台上，要向聚集在比武场上的人们讲话！来听他的演讲吧！"
D.Strings[30495]="让他睡吧。在那个时刻到来之前，我们不需要唤醒他。"
D.Strings[30496]="寒风猛烈地吹过这里的峭壁，在冰冠冰川的这个角落，绝大多数生命都不会做片刻停留。不过，只需要一点耐心，生命又都会回来。所以我现在走在这片大地上。总有一天，这些树木会高过我们所有人。"
D.Strings[30497]="我，威尔弗雷德·菲兹班，被邀请到这座怪异的竞技场来，在这里施展我无穷的智慧和伟大的召唤技艺。当然，在这方面，这个世界上不会有比我更好的人选了。"
D.Strings[30498]="很快，全世界都将知道威尔弗雷德的名字！"
D.Strings[30499]="用不了多久，菲兹班就会成为一个家喻户晓的名字。母亲会用它来吓唬不乖乖睡觉的孩子。“小心了，菲兹班会召唤一头强大的恶魔来吃掉你！”"
D.Strings[30500]="为这些竞技选手们召唤恶魔敌人的工作当然应该由我来完成。我是威尔弗雷德·菲兹班，召唤大师！在我钢铁般意志的控制下，即使是恶魔也会瑟瑟发抖！"
D.Strings[30501]="蠢货！你以为我们的主人瞎了吗？你以为我们不知道你的闯入吗？我们的长姊们就要来了，你绝对无法逃脱她们的怒火！"
D.Strings[30502]="我们的姐妹被敌人捉住了！后撤！"
D.Strings[30503]="东南方那个东西是什么？"
D.Strings[30504]="是瓦格里！注意掩蔽！"
D.Strings[30505]="小心！冰霜巨龙从南边过来了！"
D.Strings[30506]="瓦格里来进攻了！注意掩蔽！"
D.Strings[30507]="不要在地面滞留！冰霜巨龙发动攻击了！"
D.Strings[30508]="你们这些小个子给我听着，戈莫克一定能获得自由！"
D.Strings[30509]="不！我的仆从！"
D.Strings[30510]="那群傻瓜竟然让我帮他们管理他们的商店！而我只喜欢花。$B$B<小艾德琳突然斜眼盯着你，表情显得异常严肃>$B$B你喜欢花吗？"
D.Strings[30511]="是的，没错！"
D.Strings[30512]="我可不怕什么鬼魂！"
D.Strings[30513]="勘测员！我可不认识她！哈哈！"
D.Strings[30514]="不用在乎这个了——等到今年底，我就会成为高级勘测员了。"
D.Strings[30515]="让我们动手吧。"
D.Strings[30516]="猛犸人并不像看上去那样愚蠢。看管戈莫克就是一个非常困难的任务。但现在他已经被紧紧地捆住，应该不会有任何危险了。"
D.Strings[30517]="我帮助戈莫克照顾这些怪物。我并不完全赞同这种屠杀。但至少，他有机会进行战斗了。"
D.Strings[30518]="雪人是一种凶猛而狡诈的怪物，而这头雪人又是雪人之中最强壮的一头。我们在他的食物里掺了药，让他睡着了。$b$b但你可千万别以为他在斗兽场里还会这样昏昏沉沉地酣睡。"
D.Strings[30519]="我们照顾这些虫子已经有一段时间了。我希望它们能在斗兽活动中充分发挥作用。要知道，你要打败的不是一条冰虫，而是两条。"
D.Strings[30520]="我们也许只能在上流社会的阴影中做着默默无闻的事情。只有离开这里，在战争的最前线，我们的力量才能得到应有的尊重。"
D.Strings[30521]="你！好啊，就是你！$b$b好好看着我。对你来说，遇到我是你不可多得的幸运。过不了多久，全世界的人都会知道并畏惧威尔弗雷德·菲兹班的名字和我威严的面容！一旦我宏大的召唤最终完成，将没有任何人敢怀疑我的能力！"
D.Strings[30522]="掩护我，我需要把精神集中在这上面……"
D.Strings[30523]="这里有勘测仪！"
D.Strings[30524]="开始吧——在我工作的时候，别让那些东西碰我！"
D.Strings[30525]="成功了！"
D.Strings[30526]="|TInterface\\Icons\\Spell_Shadow_Darkritual.blp:36|t你获得了黑暗增效！"
D.Strings[30527]="|TInterface\\Icons\\Spell_Holy_Searinglightpriest.blp:36|t你获得了光明增效！"
D.Strings[30528]="成功了！你得到了你的私人财产！$B$B|TInterface\\Icons\\INV_Misc_coin_02.blp:64|t"
D.Strings[30529]="那……那是什么东西！！"
D.Strings[30530]="我……我想，那东西里面应该是有人！"
D.Strings[30531]="躲开！那东西会烧死你！"
D.Strings[30532]="誓死守住尼耶尔前哨站！"
D.Strings[30533]="离开……这个……地方……"
D.Strings[30534]="这里……不是……你们的……"
D.Strings[30535]="回……去……"
D.Strings[30536]="第一场挑战需要你骑上一匹银色战马。"
D.Strings[30537]="以这样可怜的效率……我永远也没办法成为高级勘测员……"
D.Strings[30538]="我要申请危险补助。"
D.Strings[30539]="……还是别活过来！"
D.Strings[30540]="我……我失去了对这些矿藏的控制！$B$B求求你，$g先生:女士;，不要解雇我！"
D.Strings[30541]="$n打开引擎盖，摆弄着里面的机械部件……"
D.Strings[30542]="%s不停地颤抖，一团绿色的软泥从排气管里涌了出来！"
D.Strings[30543]="排队等待冬拥湖战场。"
D.Strings[30544]="你通过卡莱莎的眼睛看到这个世界……"
D.Strings[30545]="世界上最强大国家的勇士们都聚集在冰冠冰川东北部的银色比武场，准备在这里迎接各种艰难而致命的挑战。"
D.Strings[30546]="你好，因为命运的多变无常，我们获得了克尔苏加德的遗物——恐怖的憎恶，帕奇维克的碎片。我们的研究人员能够用不同的方式将这些碎片重新拼合起来。如果你愿意，你们这些想要成为英雄的人可以用它来测试自己到底有多少勇气。\n\n我们能制造一个牢固的帕奇维克测试你们造成伤害的力量；或者是制造一个凶猛的帕奇维克，看看谁能在他的强力攻击前屹立不倒。\n\n那么，你想要什么样的战斗？"
D.Strings[30547]="我想测试我们的伤害输出。"
D.Strings[30548]="我想测试我们的坦克。"
D.Strings[30549]="别玩了。"
D.Strings[30550]="你好，如果你需要我的拍卖服务，那么我只能遗憾地告诉你：不行。只有宗师级工程师才有足够的能力操纵我的超级功能。$b$b更重要的是，为什么你还在和我说话？"
D.Strings[30551]="今天拍卖行有什么东西？"
D.Strings[30552]="我们绝不能让他们过去！"
D.Strings[30553]="还有？他们都是从哪里来的！？"
D.Strings[30554]="他们在冲击城墙！"
D.Strings[30555]="他们的数量远远超过了我们！"
D.Strings[30556]="挡住他们，一定要挡住他们。大法师已经有了计划。"
D.Strings[30557]="卡莱莎，你还活着！赶快找掩蔽所，这些怪物简直……无穷无尽！"
D.Strings[30558]="我还在流血？我不能……不能坚持下去了。你有没有见到任何一位大法师？"
D.Strings[30559]="嗯，我想这是魔法作用的结果。你收获了你所见到的一切……愿艾露恩保佑我们。"
D.Strings[30560]="卡莱莎，大法师瑟维恩正在找你。她应该就在附近……"
D.Strings[30561]="这些怪物……它们实在太多了。这么多人都死了！艾萨拉陷入了火海。那些上层精灵到底做了些什么？"
D.Strings[30562]="为什么我没有和其他人一起逃走？他们已经将学院包围了。我们被困在了这里。"
D.Strings[30563]="我维持着那些奥术结界的能量。"
D.Strings[30564]="我的力量……正在……减弱。卡莱莎，请告诉我，大法师们还有备用计划……"
D.Strings[30565]="我没办法将这面护盾维持太久了。卡莱莎，我们之中能有人活过这场劫难吗？"
D.Strings[30566]="还有更多怪物！它们都是从哪里来的？首都现在怎么样了？"
D.Strings[30567]="卡莱莎！赶快，大法师瑟维恩正急着想要见你。也许我们还能渡过这个难关？"
D.Strings[30568]="我只能维持住这些结界。卡莱莎！赶快去找到一位大法师。我觉得我就要崩溃了……"
D.Strings[30569]="银色十字军邀请你参加银色锦标赛，在光荣的战斗中与艾泽拉斯各地的英雄们比试，并以此测试你的战斗技艺。"
D.Strings[30570]="卡莱莎……完成了。这块岩石已经被充满能量，并开始从传送门转移能量。你的水性还和多年前一样令人惊叹吗？绝不能让恶魔或者我们“敬爱”的女王找到这块石头。$B$B游到湖底去，卡莱莎，将这块石头深埋在湖心。希望那些恶魔入侵者在摧毁湖周围的圣殿时不会发现它。去吧！"
D.Strings[30571]="是的，大法师。我会藏好这块石头。"
D.Strings[30572]="<这个闪烁微光的身影并不知道你的出现。她迷失在自己的世界中，依旧只是关注着千万年以前发生的事情。>"
D.Strings[30573]="<与这个灵魂融合。>"
D.Strings[30574]="当进攻冰冠堡垒的战斗开始时，我一定会加入。"
D.Strings[30575]="准备武器！他们来了！他们来了！！"
D.Strings[30576]="你们这些奴隶最好再卖力一些！"
D.Strings[30577]="你！是的，就是你！回去工作！"
D.Strings[30578]="我可不想和这些蛮子混在一起！"
D.Strings[30579]="我发誓，你们这些巨魔是我见过的最糟糕的工人！"
D.Strings[30580]="难道我必须亲自告诉你该怎么做吗？！"
D.Strings[30581]="没用的家伙！你们都是没用的家伙！我应该把你们都扔到大漩涡里去！"
D.Strings[30582]="时间就是金钱，巨魔！"
D.Strings[30583]="我要把你们都派回到安德麦去！"
D.Strings[30584]="你们这些笨蛋要注意外面的强盗，对付他们的时候绝对不要手软！"
D.Strings[30585]="我在远方看到了巨大的商机。整个锈水码头的资产都将流入我的腰包。"
D.Strings[30586]="卡亚罗山有没有爆炸并不重要。重要的是我要继续坐在头把交椅上！"
D.Strings[30587]="你们这些混蛋，给我听好了，绝不能让我的头号主管靠近这栋别墅。"
D.Strings[30588]="准备好我的游艇！我们将乘浪而行，而且我只欢迎最富有，最合适的人与我们同行！"
D.Strings[30589]="我们将乘船前往遥远的艾萨拉。在那里，我会构建一个新的贸易帝国。热砂集团将被我们碾成齑粉！而且，我还会在远方土地的高山上雕刻我的巨像。到那时候，所有国家都要向我进贡！"
D.Strings[30590]="下一个请！"
D.Strings[30591]="你好，你想要在银色演武场副本中同阵营冠军作战吗？\n\n当你进入这一遭遇战副本时，副本的难度相当于当前你所选择的副本难度。这一遭遇战还在制作过程中，所以请在暴雪论坛上报告你所遇到的一切bug。\n\n你是否准备好了进入这一遭遇战？"
D.Strings[30592]="你好，$c。$B$B现在部落控制着冬拥堡垒。当争夺冬拥堡垒的战斗开始的时候，你和我交谈，就能加入这场战斗。$B$B"
D.Strings[30593]="听我说，凄凉之地的入侵者们！你们全都会成为火刃的祭品！"
D.Strings[30594]="你好，$c。$B$B现在部落控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！"
D.Strings[30595]="时间就要到了！我们要横扫这片土地，让所有敢于挑战我们的生灵都成为祭品！"
D.Strings[30596]="有了火刃的帮助，恶魔将统治整个艾泽拉斯！"
D.Strings[30597]="要战斗就过来吧！火刃氏族将饱餐你的灵魂！"
D.Strings[30598]="全体艾泽拉斯的生灵们，做好准备吧！火刃氏族的时代即将到来！"
D.Strings[30599]="凄凉之地的入侵者们，加入火刃，或者准备好承受与火刃对抗的后果吧！"
D.Strings[30600]="你好，你想要在银色竞技场副本中同瓦格里作战吗？\n\n当你进入这一遭遇战副本时，副本的难度相当于当前你所选择的副本难度。这一遭遇战还在制作过程中，所以请在暴雪论坛上报告你所遇到的一切bug。\n\n你是否准备好了进入这一遭遇战？"
D.Strings[30601]="哇哈哈哈！你们太迟了。毁灭你们的力量已经受到召唤，即将降临！"
D.Strings[30602]="你好，$c。$B$B现在联盟控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！"
D.Strings[30603]="你好，$c。$B$B现在联盟控制着冬拥堡垒。当战斗就要开始的时候，你和我交谈，就能加入这场战斗。$B$B"
D.Strings[30604]="你好，$g先生:女士;！我能为你做些什么？"
D.Strings[30605]="在时间和空间构造上出现的这道裂痕看起来非常凶险。许多截然不同的景象从这道裂痕中以可怕的速度闪过。此时此刻，大概只有极为勇敢的人才会跳入其中……"
D.Strings[30606]="北风苔原"
D.Strings[30607]="索拉查盆地"
D.Strings[30608]="冰冠冰川"
D.Strings[30609]="风暴峭壁"
D.Strings[30610]="嚎风峡湾"
D.Strings[30611]="蠢货！你们要为此而付出沉重的代价！"
D.Strings[30612]="这里并不安全，$n。赶快去找避难所。"
D.Strings[30613]="嗨，$n，真高兴是你救了我。你没生我的气吧？"
D.Strings[30614]="%s说：小心！他要爆炸了！"
D.Strings[30615]="谁能挡住这个食尸鬼！"
D.Strings[30616]="这一定很痛！脑子！"
D.Strings[30617]="我们孤立无援！联盟击溃了我们，让我们流落到天知道是在哪里的孤岛上！$B$B但生意还得进行，不是吗，$n？"
D.Strings[30618]="漂亮的爆头射击！"
D.Strings[30619]="$n被踏倒了！"
D.Strings[30620]="你好，$c。$b$b看看你的周围。你有没有认真考虑过所有这些东西的意义？"
D.Strings[30621]="裁决者玛蕾尔·图哈特请求我们负责锦标赛所需的各项工作。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。"
D.Strings[30622]="裁决者玛蕾尔·图哈特委托我们负责锦标赛所需的各项工作。不幸的是，她把同样的工作也委托给了夺日者。那些蠢货只会给我们制造麻烦。现在我们的工作量要成倍地增加了！"
D.Strings[30623]="这是破坏行为！我已经被毁了……$b$b这一切的幕后操纵者一定要付出代价！我说话算话……"
D.Strings[30624]="$n? $G先生:女士;，你不是猎人，你是$c。"
D.Strings[30625]="哦，我们将一起渡过一段重要的时光。关于猎人之路，我有很多东西要教你。"
D.Strings[30626]="我们需要你，$n！这里到处都是狼人！"
D.Strings[30627]="这太恐怖了。我怀疑他们全都死了。$B$B现在我该怎样把卡亚矿石从这里运出去？"
D.Strings[30628]="啊！不要再搞了！"
D.Strings[30629]="%s从地面上升起来了！"
D.Strings[30630]="不要招惹巴伯亚，你这个发光的小虫子！"
D.Strings[30631]="这是谁干的？！停止！"
D.Strings[30632]="不要再这样了！我不喜欢这样！"
D.Strings[30633]="风已经悄声告诉我，一名$r$c即将到来。$g他:她;会帮助我取得成功，而不是像其他人那样只能让我尝到失败的苦果。$b$b你会是那个人吗？"
D.Strings[30634]="我已经准备好了解你所说的那个威胁了，库拉。"
D.Strings[30635]="我无法对你进行任何训练，$n。但我需要你帮我对付这些该死的猴子！"
D.Strings[30636]="我喜欢术士！今天我能在你的耳边说一些怎样的黑暗秘密？"
D.Strings[30637]="嗨，$n$g先生:女士; ，我无法传授你魔法技艺，只能教你如何用手指按摩僵硬的脖子。"
D.Strings[30638]="请原谅，恐怕现在我还有别的事情必须去做。请以后再来找我。"
D.Strings[30639]="这正是个传授神秘技艺的好日子。你是不是也这样想，$n$g先生:女士;？"
D.Strings[30640]="我可以给你一点时间，让你为这场战斗做好准备。"
D.Strings[30641]="干得漂亮，$n$g先生:女士;。保持这种高水平的发挥吧。"
D.Strings[30642]="我预见到了你光辉的未来，我的孩子！今天我要教你些什么？"
D.Strings[30643]="一座岛屿旁的失事船只上挤满了扔炸弹的猴子？那这以后又会有什么……一座即将爆炸的火山？"
D.Strings[30644]="我们需要……呃，我是说，圣光需要许多金钱，而且现在比以往更加需要。$B$B我们说到哪里了？你需要训练吗？"
D.Strings[30645]="你能看见我？你怎么可能看见我，老板？$B$B我正在努力提高自己的潜行技巧呢。"
D.Strings[30646]="不管是训练还是按摩，我能满足你的一切需要，老板。只是当你成为新的贸易大王时不要忘记我！"
D.Strings[30647]="那名术士肯定没有召唤末日守卫。你在下一场挑战中将和银色十字军作战。做好接受挑战的准备了吗？"
D.Strings[30648]="好吧，你做好准备之后，我就会向提里奥发出信号。"
D.Strings[30649]="发信号吧！我们已经准备好了！"
D.Strings[30650]="这场战斗真是野蛮残忍至极。我已经有许多年没见到过如此大规模的战斗了！实在是令人震惊！"
D.Strings[30651]="等到我们将他们彻底消灭的时候，你会更吃惊的！"
D.Strings[30652]="我已经等不及要看到下一场战斗了！他们似乎已经做好了准备。所以，你们也赶快进行准备吧！"
D.Strings[30653]="我们已经做好了一切准备！"
D.Strings[30654]="猛鹫的蛋被毁了……"
D.Strings[30655]="好吧，我们出发。你会掩护我的，对吗？"
D.Strings[30656]="这里的纳迦数量正在稳定地持续增长……"
D.Strings[30657]="大灾变撕裂了这里的陆地，让纳迦能够进入内陆……"
D.Strings[30658]="一名艾萨拉的女祭司！难道是她在统率他们吗？"
D.Strings[30659]="他们正在这一地区横行肆虐。我们必须查清楚，他们在这里寻找什么！"
D.Strings[30660]="这里的水体本身也在对抗他们。这是为什么？我们有很多问题，却只有很少的答案……"
D.Strings[30661]="马上来找我，$c。我们还有很多事情要做。"
D.Strings[30662]="我想你是来帮我挡住那些东西的吧？"
D.Strings[30663]="如果我遭到攻击，就没办法采矿了。"
D.Strings[30664]="我们会像其他人一样死在这里，对不对？"
D.Strings[30665]="我想回家了。"
D.Strings[30666]="要让我做这种事，他们付的酬劳还不够。等等！他们根本就没有给过我一点酬劳！"
D.Strings[30667]="我到这里来是为了挖矿，你到这里来是为了战斗。明白了吗！"
D.Strings[30668]="这些洞里的壁画已经快把我吓跑了。更不要说那些想要杀我的猴子了！！"
D.Strings[30669]="我确信卡亚矿强化了那些猴子的智力，就如同它们曾经提升我们远古祖先的智力一样。"
D.Strings[30670]="这块矿已经被采掘干净了。"
D.Strings[30671]="我从这里面已经挖不出任何东西了。"
D.Strings[30672]="看来我们找到这地方的头等奖了！"
D.Strings[30673]="我有没有告诉过你，我在科赞的公司里曾经是一名中级会计？我为你工作了好几年。你知道我的名字吗？"
D.Strings[30674]="那些猴子已经将这里的大部分卡亚矿都挖走了。"
D.Strings[30675]="现在我还不打算进行爆破。"
D.Strings[30676]="嗨，为什么我们要在这里做这种工作？"
D.Strings[30677]="危险已经过去了。我可以自己继续前进。感谢你的护送，$n。"
D.Strings[30678]="为了抓住你就要见到的这个挑战者，我们可是蒙受了很大的伤亡！"
D.Strings[30679]="呃，戴姆维克，我还需要一个矿工……"
D.Strings[30680]="%s看到那些存活下来的猛兽，立刻发出一声震耳欲聋的吼叫，再次发动了凶猛的攻击！"
D.Strings[30681]="地下……"
D.Strings[30682]="瓦格里的团队协作能力真是令人震惊。现在我终于明白，为什么只是抓住两只瓦格里就会如此困难。"
D.Strings[30683]="很困难吗？"
D.Strings[30684]="我们必须提高我们的团队协作能力，才能战胜那两个家伙。"
D.Strings[30685]="你最好记住！你要面对的是阿尔萨斯最强大的两个瓦格里侍从！"
D.Strings[30686]="瓦格里？我们已经准备好和他们作战了。"
D.Strings[30687]="我希望你能够迅速提高！"
D.Strings[30688]="尽管把她们带出来，然后好好看着吧。"
D.Strings[30689]="臼炮射击准备。让他们尝尝苦头，海克尔！"
D.Strings[30690]="%s发现他需要一些尖牙护腿。"
D.Strings[30691]="%s正梦想着获得一顶幸运钓鱼帽。"
D.Strings[30692]="现在，竞技场终于落成了。而锦标赛的管理者也请求我们负责管理在那里面举行的竞技活动。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。"
D.Strings[30693]="%s因为丢失了他的虚空裂蹄护甲片而非常烦恼。"
D.Strings[30694]="现在，竞技场已经竣工。裁决者玛蕾尔·图哈特请求我们帮助管理锦标赛和保护赛事安全。她想让我们和那些无能的银色盟约混蛋们一同工作。但他们只会碍事。"
D.Strings[30695]="%s正在计划一次荆棘谷垂钓。"
D.Strings[30696]="救命，救救我！"
D.Strings[30697]="有狼人追我！"
D.Strings[30698]="当我作为一名奥格瑞玛卫兵接受训练的时候，萨尔叮嘱我们在对敌作战的时候需要保持耐心和谨慎。$B$B但纳迦时刻都有可能完全占领这座半岛。萨尔也不再是我的酋长了。现在应该是对敌人予以痛击的时候了，$c。"
D.Strings[30699]="为什么你要干扰我在这里的工作？给我解释清楚！"
D.Strings[30700]="你最好想出一个接近我的好理由，小鱼！"
D.Strings[30701]="这是什么？你想要对我做什么，小鱼？"
D.Strings[30702]="太好了，今天你们证明了自己是强大的勇士。只要你们和银色十字军并肩作战，我们必将战胜天灾军团！"
D.Strings[30703]="感谢你的赞扬，演武场统领。"
D.Strings[30704]="无论给予你怎样的赞扬都不会过份。提里奥肯定想亲自表彰你的功绩。嗨，你有没有突然觉得有些冷？"
D.Strings[30705]="这真奇怪……"
D.Strings[30706]="你竟敢打扰我们，准备好付出代价吧！"
D.Strings[30707]="我要让那可恨的鼓声彻底消失！"
D.Strings[30708]="你以为你在干什么，傻瓜？"
D.Strings[30709]="没有人能在惹恼了洛肯的仆人之后还能全身而退的！"
D.Strings[30710]="持剑的手臂要挺直，$n。"
D.Strings[30711]="你不是战士！你最好回到安全的地方去……当然，我这样说不是要冒犯你。"
D.Strings[30712]="向你致以我最谦恭的道歉，勇士，但你现在已经没有机会完成这次大十字军的试炼了。不过请记住，你和你的同伴每一周都有一次机会再次开始大十字军的试炼。希望你们在这周得到的教训能够让你们向这里的最终的胜利更迈进一步，并帮助你们彻底战胜天灾军团！"
D.Strings[30713]="你在这里建立的功业不会被遗忘，$n！我将确保这一点。"
D.Strings[30714]="你所走的并非旧时的道路。我没有什么可以教你的，孩子。"
D.Strings[30715]="狼人会消失。我们也会消失。$B$B只有大地和她的秘密会留存下来。你愿意学习吗，$n？"
D.Strings[30716]="我想接受更多关于古老的德鲁伊之道的训练。"
D.Strings[30717]="最后的一批兽人很快就要灭亡了！"
D.Strings[30718]="死吧，兽人渣滓！"
D.Strings[30719]="来到这片海岸的先是那些兽人，然后是这些可怜的地精。"
D.Strings[30720]="我们会消灭他们的，$n。那些怪兽敌不过我们。"
D.Strings[30721]="一定要非常、非常安静。这里到处都是狼人。"
D.Strings[30722]="我在寻求进一步的训练。"
D.Strings[30723]="当然，我会和你分享我的智慧。你可以借助这些智慧帮助我们击败狼人。"
D.Strings[30724]="教导你耗费了我很大力气。而为了让自己的心智适应奥术力量，你还需要经历许多个岁月的磨砺。"
D.Strings[30725]="你可以向我寻求帮助和建议……只是别向我要钱，好吗？"
D.Strings[30726]="我发誓，这不是我的错。为什么你要这样看着我？"
D.Strings[30727]="即使是现在这个最黑暗的时代，圣光的教诲依旧能指引你安然无恙地穿行在这个危险的世界上。"
D.Strings[30728]="圣光与你同在，$c。今天你必将不会受到伤害。"
D.Strings[30729]="我想，我们也许已经激怒他们了。"
D.Strings[30730]="很高兴在这个极其危险的时代与你分享我的禁忌知识。黑暗会保护我们，$g兄弟:姐妹;。"
D.Strings[30731]="对于我所保藏的秘密，即使是最肤浅的一瞥，也能够让你发疯，$c。"
D.Strings[30732]="什么事，凡人？"
D.Strings[30733]="用你载具的能力援救克雷南·阿朗纳斯。$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t"
D.Strings[30734]="我已经准备好与你并肩作战了，海卓尼斯！"
D.Strings[30735]="欢迎，勇士！你是否已经聚集起力量，做好准备，打算迎接大十字军的试炼的挑战了？只有最强大，最聪明的冒险者才能进行这样的试炼。为了参与这次试炼，你们必须首先完成普通的十字军的试炼。"
D.Strings[30736]="我完成了十字军的试炼。"
D.Strings[30737]="我还没有完成十字军的试炼。"
D.Strings[30738]="当你在十字军的试炼中赢得胜利的时候再回来。"
D.Strings[30739]="大十字军的试炼比十字军的试炼更加困难。这里的每一个敌人都会变得更强大。而且你无法为自己挑选敌人，除非你们曾经战胜过他们。如果在这周之内，你们进行了50次不成功的尝试，就只能等到下周再继续大十字军的试炼了。在成功地完成大十字军的试炼之后，你们将获得另一个宝物匣。现在，是否已经为这一试炼做好了准备？"
D.Strings[30740]="我道歉，冒险者。大术士威尔弗雷德·菲兹班还没有到达比武场。所以，这一试炼的下一场挑战还无法开始。我们相信他会在下个星期赶到。"
D.Strings[30741]="延迟，延迟，还是延迟。十字军的试炼已经陷入了停顿。只有对威尔弗雷德·菲兹班行为的研究得出结果之后，试炼才能继续进行。下一周，试炼应该能够继续，准备好在那时与银色十字军最优秀的骑士作战吧！"
D.Strings[30742]="我们派出一队骑士，去俘虏两名阿尔萨斯的天灾军团战将，以作为下一场试炼挑战的敌人。但骑士们并没有带着俘虏回来。所以试炼的下一个阶段也只能暂停了。下周再来看看吧。"
D.Strings[30743]="实在是太厉害了！真令人难以置信！干得漂亮！我们已经制定好了为你庆祝胜利的计划。等到下个星期，我们就会做好准备。那时候再见！"
D.Strings[30744]="守住工事！绝不让他们前进一寸！"
D.Strings[30745]="把他们打退！"
D.Strings[30746]="计划是继续向南移动。我们不能回到商人区去了。那里不安全。"
D.Strings[30747]="我们必须团结一致才能生存下去。我们要结队行动。"
D.Strings[30748]="国王的人会保护我们。再坚持一会儿。"
D.Strings[30749]="你对我的小鱼都做了些什么？！你要付出代价，傻瓜！"
D.Strings[30750]="<基拉格示意你压低声音。>"
D.Strings[30751]="%s在惊骇和愤怒中发出“嘶嘶” 的吼声！"
D.Strings[30752]="我们救出阿朗纳斯了！任意开火！"
D.Strings[30753]="你救不了……耐普图隆！"
D.Strings[30754]="当%s的力量消散时，她发出一阵能刺穿耳膜的尖叫声！"
D.Strings[30755]="喔！那座洞里都画了些什么？嗯，我听到的是猴子叫声吗？！"
D.Strings[30756]="我们必须在城里吸引狼人的注意。这是让幸存者逃往暮湾镇的唯一机会。"
D.Strings[30757]="不行，孩子。吉尔尼斯的国王必须心无旁骛。不能让你的父亲分心担忧你的安危。"
D.Strings[30758]="我们会在圣光黎明大教堂里死守。我已下令，并布置了火炮。吉恩，好好领导人民。"
D.Strings[30759]="我要和皇家卫士一起留下来，父亲。这是我的责任。"
D.Strings[30760]="要是我们能通过暮湾镇的大门，我们就安全了。东边的山脉几乎是无法通行的。"
D.Strings[30761]="我们不应该愚蠢地相互残杀，达利乌斯。这些狼人原本毫无机会的。"
D.Strings[30762]="我们要前进，基拉格。"
D.Strings[30763]="$n已经清理出一条道路。我们将继续前进。"
D.Strings[30764]="不要耽误时间，基拉格。我们将向前搜索。"
D.Strings[30765]="地精技术真是奇异而又可怕。我赞同！"
D.Strings[30766]="我们将要向前搜索，直到荒野瞭望台。在那里见，基拉格。"
D.Strings[30767]="小心。这片丛林中能要你性命的东西比这些树还多！"
D.Strings[30768]="该是出发的时间了。希望我们能够再见，$n。"
D.Strings[30769]="我们现在应该出发了。在荒野瞭望台见。"
D.Strings[30770]="那副护目镜！根本就不管用！"
D.Strings[30771]="火……火！"
D.Strings[30772]="再次伴随着火焰和痛苦。"
D.Strings[30773]="我们又制造了一场高投入低产出的大型灾难。"
D.Strings[30774]="我着火了。赶快记录在日志里！"
D.Strings[30775]="我的身体！"
D.Strings[30776]="准备作战，卫兵们！我们不知道入侵者的数量。但海角已经沦陷，港口城镇的联系被切断了。做好孤军奋战的准备。"
D.Strings[30777]="给我守住外围。大门始终要有两名卫兵把守。不允许任何人进出城市。"
D.Strings[30778]="天灾入侵时我们守住了吉尔尼斯。北门叛乱时我们也守住了她。无论面对任何新威胁，吉尔尼斯绝不会失守。"
D.Strings[30779]="我立马就会出发去下一个集结点。"
D.Strings[30780]="谢谢你，谢谢你！"
D.Strings[30781]="勇士们，你们还活着！你们不仅克服了十字军试炼的每一场挑战，还直接阻挠了阿尔萨斯的计划！你们的技巧和机智在对抗天灾军团的战斗中一定能发挥极为强大的作用。干得好！请让我的一名法师将你们传送回地面吧！"
D.Strings[30782]="喔，谢谢！我要好好检查一下这些结果是不是可以重复的。"
D.Strings[30783]="我实在是不应该那么频繁地喷出火团来。"
D.Strings[30784]="记录：火是不好的。"
D.Strings[30785]="快，救助其他人！"
D.Strings[30786]="勇士们，你们已经完成了大十字军的试炼！只有真正身经百战的冒险者才有可能完成这个试炼。我将这个嘉奖箱交给你们。这是你们应得的奖励！愿箱中的宝物在未来的战斗中能够协助你们直捣冰冠堡垒的核心，战胜阿尔萨斯！"
D.Strings[30787]="现在，你已经完成了十字军的试炼，你应该考虑去参加大十字军的试炼了。只有最强大的冒险者才有希望完成这一试炼。但你的努力一定能换回丰厚的报偿。"
D.Strings[30788]="我要去找些药膏来。"
D.Strings[30789]="它不像是看上去那么糟糕。"
D.Strings[30790]="你来到了这里，就是犯了一个大错。这些比武场是光明的堡垒，你的力量完全无法与之相比。"
D.Strings[30791]="很抱歉，但你并不属于这里，你不能伤害这里的无辜者。"
D.Strings[30792]="祝贺，请在准备好之后进入这个通向达拉然的传送门！"
D.Strings[30793]="这只嘉奖箱中的奖励品数量和质量取决于你在大十字军的试炼中进行过多少次不成功的尝试。不成功的尝试越少，得到的奖励就越丰厚。"
D.Strings[30794]="我想要忘掉侏儒工程学分支的知识！"
D.Strings[30795]="你真的想要忘掉侏儒工程学分支的知识，并失去所有与之相关的配方吗？"
D.Strings[30796]="你真的想要忘掉地精工程学分支的知识，并失去所有与之相关的配方吗？"
D.Strings[30797]="我想要忘掉地精工程学分支的知识！"
D.Strings[30798]="看到同伴的死亡，%s被激怒了！"
D.Strings[30799]="基拉格，我……唔……嗯，我的斥候失踪了。"
D.Strings[30800]="你们两个要更加小心！我们的人只有这么点了！"
D.Strings[30801]="什么？！你认为我是矿工出身？$B$B你还能有更糟糕的想法吗？"
D.Strings[30802]="我再一次道歉，但这是你选择的命运。"
D.Strings[30803]="看到海滩那边的旋翼机了吗，$n？！"
D.Strings[30804]="拿上钥匙，然后到旋翼机那里去！"
D.Strings[30805]="我们一定会复仇的！"
D.Strings[30806]="警告：反应堆核心泄露！"
D.Strings[30807]="嗨！离我的飞行器远点！"
D.Strings[30808]="不要忘记带上你的护目镜，$n。只有这样，我们才能在他们扑到我们身上之前发现他们。"
D.Strings[30809]="我们必须推动小车！"
D.Strings[30810]="到旋翼机那里去！马上！"
D.Strings[30811]="啊，你做到了！实在是漂亮。"
D.Strings[30812]="喔——这就是精炼后的艾萨莱特水晶？"
D.Strings[30813]="我从没有想过还能看到如此纯粹的样品。"
D.Strings[30814]="我已经见到了未来，$r。$b$b如果我们不能迅速采取行动，半人马的土地将永远地堕落。"
D.Strings[30815]="我已经准备好和熔岩部落作战了！"
D.Strings[30816]="$r！长矛就位！"
D.Strings[30817]="艾萨莱特水晶核心立刻冷却了。"
D.Strings[30818]="啧！这肯定是侏儒建造的。"
D.Strings[30819]="上来，要起飞了！"
D.Strings[30820]="艾萨莱特水晶核心过热——使用灭火器进行冷却！"
D.Strings[30821]="艾萨莱特水晶核心强度为60%%。"
D.Strings[30822]="危险，艾萨莱特水晶核心接近过热。"
D.Strings[30823]="艾萨莱特水晶核心即将到达临界点！"
D.Strings[30824]="加快速度！不要等到我们被发现！"
D.Strings[30825]="你没有能将长矛竖好！我们必须再试一次……赶快！"
D.Strings[30826]="%s情况紧急！"
D.Strings[30827]="找到珍贵的货物！"
D.Strings[30828]="科卡尔部族！进攻！！"
D.Strings[30829]="一位地精？我肯定是眼花了。感谢你，并很高兴见到你，小家伙！"
D.Strings[30830]="给兽人酋长一些嗅盐，让他从麻药的昏迷作用中清醒过来。"
D.Strings[30831]="看起来，这很有效。"
D.Strings[30832]="科卡尔可汗之矛折断了……"
D.Strings[30833]="撤退！！"
D.Strings[30834]="长矛折断了！撤退！"
D.Strings[30835]="够了！这是干什么的？！"
D.Strings[30836]="$n，坐下。火已经热了。这可不是给猴子准备的。"
D.Strings[30837]="谁能想到，在我们渡过那么多难关之后，却会在这里结束？"
D.Strings[30838]="嗨，看啊，是$n！"
D.Strings[30839]="看样子我们被困在这儿了。你能让我们从这里出去吗？"
D.Strings[30840]="哦，$n，我们被困住了！"
D.Strings[30841]="我想念科赞。我们还能再看到锈水码头吗，$n？"
D.Strings[30842]="和我一起坐一会儿。我们可以唱唱歌，在火上烤烤螃蟹。"
D.Strings[30843]="我全都指望你了，但你怎样做才能让我们离开这座岛？"
D.Strings[30844]="<大胖哼哼着。>$B$B俺现在是银行家了！"
D.Strings[30845]="$n，很高兴再见到你。"
D.Strings[30846]="海之英灵，让敌人葬身于你的怒涛之下！"
D.Strings[30847]="海洋之力，响应我的召唤！"
D.Strings[30848]="流水深渊之子，清除玷污了你们家园的恶人吧！"
D.Strings[30849]="疾速的风暴，响应我的召唤！"
D.Strings[30850]="风之狂怒，向联盟倾泻你的雷暴吧！"
D.Strings[30851]="风墙之子，降临凡间，摧毁那些阻止我保护这个世界的敌人吧。"
D.Strings[30852]="我已经觉得好多了。"
D.Strings[30853]="为了部落的荣耀，$n！"
D.Strings[30854]="酋长，我需要另一场飓风。"
D.Strings[30855]="进入神庙中心，使用元素愤怒号角！"
D.Strings[30856]="这里到处都是狼人……那本应该是我……"
D.Strings[30857]="吉尔尼斯很快就将落入被遗忘者手中！"
D.Strings[30858]="你可以在炼金区找到他们。你可以叫他们赫伯特·哈尔希医生和马尔什医生。要小心。"
D.Strings[30859]="赫伯特·哈尔希医生就是你要找的人。别干傻事。再搞那种无聊的瘟疫，你的脑袋就得搬家。"
D.Strings[30860]="皇家区的兽人格里兹尔就是你要找的人。"
D.Strings[30861]="格里兹尔是幽暗城的战场军官，他是那个年代最勇猛的战士。你可以在皇家区找到他。"
D.Strings[30862]="你可以去找玛洛维尔爵士。他和其他战场军官一样，都呆在皇家区。"
D.Strings[30863]="你想帮助污染者吗？同皇家区的玛洛维尔爵士谈一谈。他是你要找的人。"
D.Strings[30864]="所有的拍卖师都在中央区域。"
D.Strings[30865]="如果你想看看这里的市场，那么就到中央区域去吧。"
D.Strings[30866]="卡啡？记忆药水？哈！这可不是记忆药水。"
D.Strings[30867]="银行？就在贸易区中间的塔里。"
D.Strings[30868]="那么，厄格尔罗，这些就是你的记忆药水所需要的全部东西么？"
D.Strings[30869]="早晨，我让自己醒来时。太阳总是让我觉得很累，难以思考。"
D.Strings[30870]="所有这些只是为了叫醒你？我相信我有好几种武器都能做到这一点。"
D.Strings[30871]="我相信这个方式会更可靠。"
D.Strings[30872]="那么……厄格尔罗，我能在哪里找到艾索雷苟斯？"
D.Strings[30873]="艾索雷苟斯！我记得他。又高又蓝，大牙齿。真是个好家伙，虽然有点怪癖。有几个星期没见他了。"
D.Strings[30874]="就在城的正中央。中心区的小房间。"
D.Strings[30875]="纳兹尼克是这里的理发师。他的理发店就开在贸易区的上层区域。"
D.Strings[30876]="迈克尔·加勒特是幽暗城的蝙蝠管理员。他就在贸易区的上层区域。"
D.Strings[30877]="蝙蝠管理员的架子就搭在贸易区的上层区域。远远的就会闻到那股味儿的。"
D.Strings[30878]="战场军官都在皇家区内；你可以在王座厅四周找到他们。"
D.Strings[30879]="你要前往哪个战场？"
D.Strings[30880]="詹姆斯·范·布朗特的锻造生意一直不错，就在军事区的内环区域。"
D.Strings[30881]="铁匠在军事区干活，买了他们武器的人马上就可以在旁边试上一试。铁匠就在那里的内环区域。"
D.Strings[30882]="贸易区的尤奈斯·伯奇是这里的厨师。是你的肚子在叫，不是我的。"
D.Strings[30883]="这里的厨师是尤奈斯·伯奇，你可以在贸易区找到她。"
D.Strings[30884]="拉文尼亚·克洛文是这里的附魔师。他的店就开在炼金区的内环区域。"
D.Strings[30885]="炼金区内环区域的拉文尼亚·克洛文可以教你有关附魔的知识。"
D.Strings[30886]="弗兰克林·洛伊德是这里的工程师。他平时都在盗贼区外环区域修修补补。"
D.Strings[30887]="听着，如果你要去见盗贼区外环区域的那些工程师，那就看好标记。"
D.Strings[30888]="你可以找玛丽·艾塔斯谈一谈。她就呆在盗贼区的内环区域。"
D.Strings[30889]="真的？几个星期？你就不能告诉我一些好事么？"
D.Strings[30890]="他总是嘟囔着要去找到这个或者那个魔法宝物。他说艾萨拉到处都有这种宝物。要我说，他大概是有些强迫症的迹象。$B$B最近我听说他正在和那个叫克希雷姆的大法师交朋友。他说克希雷姆已经找到了一些很强大的魔法物品。"
D.Strings[30891]="大法师克希雷姆？厄格尔罗，我在哪里能找到这位大法师？"
D.Strings[30892]="克希雷姆似乎有一点社交恐惧症。大多数时间里，他只是自言自语，偶尔才会和他的学徒说上几句话。对于其他人，他总是视而不见。$B$B他说太笨拙，不能作他的学徒。他还说我的脑子根本学不了魔法，只能被魔法弄得乱七八糟。"
D.Strings[30893]="有什么办法能让他回答我的问题？"
D.Strings[30894]="成为大法师的学徒，我猜，大概是件很费周折的事。$B$B光是上个月，我就遇上了十多个被淘汰的学徒。尽管那些气馁的学徒满身伤痕，但却总是会不停地回来继续尝试。我猜，成为大法师的机会并没那么多。$B$B今天我刚刚又遇到一名学徒，他去往了西边，到那座正在建造的巨大石柱那儿去了。"
D.Strings[30895]="这是个好的开始。谢谢，厄格尔罗。"
D.Strings[30896]="是啊，是啊！如果你找到他，代我向他问好。"
D.Strings[30897]="你好！终于见到一个身上没有臭鱼味的人了。我喜欢。"
D.Strings[30898]="即使是行尸走肉也需要维护自己的身体。玛丽·艾塔斯精通此道。她就在盗贼区的内环区域。"
D.Strings[30899]="疯狂的渔夫就在魔法区的港口那。"
D.Strings[30900]="你好，朋友。$b$b相信你很喜欢这个地方吧？"
D.Strings[30901]="我不知道阿曼德·克伦威尔在试图追赶什么，不过他已经到了魔法区的码头。"
D.Strings[30902]="克里斯托弗·德库尔是这里的公会注册员。他的办公区设在贸易区东侧平台。"
D.Strings[30903]="公会注册员在贸易区办公。你可以在东侧平台找到他。"
D.Strings[30904]="马尔萨·奥列斯塔是这里的草药学家。你可以在炼金区的内环区域找到她。"
D.Strings[30905]="去炼金区的内环区域，那里的马尔萨·奥列斯塔可以教你有关草药学的知识。"
D.Strings[30906]="旅馆——如果算得上的话——在贸易区的上层区域。那里连床铺都没有。"
D.Strings[30907]="贸易区上层区域的诺曼是这里的旅店老板，他的店只不过是几面满是灰尘和裂缝的墙壁。"
D.Strings[30908]="这里的抄写员在炼金区，她的名字叫玛尔迦·帕克雷。"
D.Strings[30909]="城里的皮匠在盗贼区的内环区域。"
D.Strings[30910]="亚瑟·摩尔是这里的皮匠。他在盗贼区的内环区域传授制皮技能。"
D.Strings[30911]="如果要钥匙，你可以找盗贼区的沃特尔·索雷夫谈一谈，不过要小心。"
D.Strings[30912]="法师？他们都在魔法区的中央建筑中。你得机灵点儿才能找得到。"
D.Strings[30913]="在魔法区的外环区域你能找到一座大型、阶梯式的建筑。法师们都在那里。"
D.Strings[30914]="邮箱在贸易区的棺材铺前面，也有人管那里叫旅馆。"
D.Strings[30915]="邮箱吗？你可以到城中央上层区域的旅店看看，那里有邮箱。"
D.Strings[30916]="和军事区内环区域的布罗姆·基里安谈一谈，他可以教你如何采矿。"
D.Strings[30917]="这里的采矿训练师在军事区的内环区域工作。他的名字叫布罗姆·基里安。"
D.Strings[30918]="找圣骑士你得去皇家区。那些有几个精灵可以教你。"
D.Strings[30919]="牧师们都在军事区的外环区域。"
D.Strings[30920]="去军事区外环区域看看吧。那里的牧师努力确保没有哪个断掉的肋骨长时间得不到修复。"
D.Strings[30921]="盗贼们都呆在盗贼区。就这么简单。你可以在外环区域找到他们。"
D.Strings[30922]="你可以在盗贼区外环区域找到那些潜行者。"
D.Strings[30923]="基里安·哈根是这里的剥皮训练师。他就在盗贼区的内环区域。"
D.Strings[30924]="如果你想学习剥皮，就要前往盗贼区。剥皮训练师的铺位就在内环区域。"
D.Strings[30925]="如果你真的想把宠物委托给某个亡灵，那你可以和安雅·玛尔雷谈谈，他就呆在贸易区上层的旅馆里。"
D.Strings[30926]="你可以同安雅·玛尔雷谈一谈，他就在贸易区上层的旅店旁边。我并不建议你这样做，不过它们毕竟是你的宠物。"
D.Strings[30927]="这里的裁缝叫乔瑟夫·格里高利。他就在魔法区的内环区域。"
D.Strings[30928]="先到魔法区，然后朝内环区域走，裁缝店就在那里。"
D.Strings[30929]="你竟然有胆量问我有关术士的事。到魔法区的外环区域看看吧，现在给我消失。"
D.Strings[30930]="你可以在魔法区的主建筑区域找到那些术士，我希望告诉你这些不会引起什么麻烦。"
D.Strings[30931]="战士都在军事区外环区域进行操练。"
D.Strings[30932]="你可以在军事区的外环区域找到那些战士。"
D.Strings[30933]="到军事区内环区域找到阿基巴德，他可以教你如何某些使用武器。"
D.Strings[30934]="很高兴有人愿意学点儿真正有用的东西。到军事区的内环区域去找阿基巴德吧。"
D.Strings[30935]="你想离开这，这我不怪你。先到最顶层，然后朝废墟的北面走。坐上两座塔那的地精飞艇就可以离开了。"
D.Strings[30936]="飞艇塔就在幽暗城的北面。"
D.Strings[30937]="在这看到兽人感到意外吧？用不着这样。$b$b需要有人看着那些被遗忘者。如果从一开始我们就好好盯着，或许天谴之门的事根本就不会发生。"
D.Strings[30938]="希望你要找的不是那些憎恶。炼金师没有一个靠得住，他们造出来的那些在大厅里巡逻的东西也一样。真正保卫这里安全的是我们。"
D.Strings[30939]="Lok'tar。不要在这里做出任何可疑的行为。如果那些亡灵打算加入部落，他们就得接受我们的监视。"
D.Strings[30940]="怎么了？骨头堆。在找人吗？这里只有我，要买东西就快点儿。"
D.Strings[30941]="我会盯着你的，法拉尼尔。"
D.Strings[30942]="没有憎恶保护你。没有秘密。没有私下密谋。"
D.Strings[30943]="这里完全不欢迎随地吐痰的人。"
D.Strings[30944]="我向您保证，监工，皇家药剂师协会愿意为这场导致了大量死亡的悲剧事故做出补偿。"
D.Strings[30945]="我们不会给你惹麻烦的。我们只想安安静静地继续我们的研究。"
D.Strings[30946]="让那个死脑筋把嘴闭上！"
D.Strings[30947]="闭嘴，叽里呱啦的蠢货！"
D.Strings[30948]="我敢说你们这些无赖一定觉得自己在天谴之门干得很漂亮，对吧？游戏结束了。我们来就是要阻止你们的一切行为。"
D.Strings[30949]="我会告诉你都该知道些什么，但这并不表示我有多么愿意。我们一直在监视着你和你的同类。"
D.Strings[30950]="坑里臭气熏天，还有一群蛇围着我。不过我来这是有事要做的。$b$b自从普特雷斯在天谴之门上演了一出好戏，酋长便不再信任那些人，而是离他们远远的。这就是为什么我们会在这里。那些药剂师离了我什么都做不了。"
D.Strings[30951]="啊！！！！我在这儿看不到！！！！"
D.Strings[30952]="桶子闻起来像火药……"
D.Strings[30953]="这不太好…"
D.Strings[30954]="阿噢……这会伤到我……"
D.Strings[30955]="我感觉不好…"
D.Strings[30956]="滚回去！我打烂你！"
D.Strings[30957]="[DND] 要使用我的服务，你必须先取得对应的许可。"
D.Strings[30958]="[DND] 我已经取得了银行的使用许可。"
D.Strings[30959]="[DND] 使用银行所需的许可和费用你都办好了吗？"
D.Strings[30960]="我没有能在吉尔尼斯城保护我的人民。但命运似乎是要给我第二次机会，$n。我不会再失败了！"
D.Strings[30961]="[DND] 使用拍卖行所需的许可和费用你都办好了吗？"
D.Strings[30962]="很高兴看到憎恶们祥和的喘气声和气体爆破声又回到了幽暗城。兽人的体味可难闻多了。"
D.Strings[30963]="你已经被麻痹毒素感染了！"
D.Strings[30964]="不要伤害我！我只是在寻找我的姐妹！我想阿什莉就在这幢房子里！"
D.Strings[30965]="你真可怕！我只想要妈妈！"
D.Strings[30966]="你是那种好狼人吗，$g先生:女士;？你有没有见到藏在外面棚屋里的辛西娅？"
D.Strings[30967]="我能看看你的古代宝石配方么？"
D.Strings[30968]="你的妈妈就在旁边那道门后的地下室里。现在就去找她吧！"
D.Strings[30969]="这里不安全，到艾伦家的地下室去。"
D.Strings[30970]="这是什么，$c？恶魔不在了，这里有很多东西我要看。总得有人来整理这些文书，确保普特雷斯的事不再发生。$b$b我真是走运。"
D.Strings[30971]="去旁边那道门后的地下室里去找其他人，和他们待在一起。快！"
D.Strings[30972]="看看你周围，$c！$b$b这里难道不是非常美丽吗？"
D.Strings[30973]="真的是你？我还记得这双眼睛。"
D.Strings[30974]="你还好吗，$g小伙子:姑娘;？"
D.Strings[30975]="你不会是认真的吧！难道你忘记了$n为我们做的一切？$g他:她;留下来……都是为了我们！"
D.Strings[30976]="放弃吧，克雷南。该处决它了。这是“既定程序”。"
D.Strings[30977]="告诉我，高弗雷。那些留在吉尔尼斯城中，让我们能够活下来的人。他们的死也是“既定程序”？"
D.Strings[30978]="我可不这样想。把那个药剂给我，克雷南……我要双倍剂量。"
D.Strings[30979]="你不会是认真的吧！难道你忘记了$n为我们做的一切？"
D.Strings[30980]="我不会放弃你。虽然我还不能治愈诅咒，但……我有方法能够让你重获理智。"
D.Strings[30981]="<格蒙刚的声音发出隆隆的回音，让你感到耳鼓震痛，脚下的地面也在一阵阵颤抖。>$B$B你好，小软人。$B$B你们总是喜欢四处乱窜。来，和我休息一会儿吧。"
D.Strings[30982]="我给你带来些吃的。"
D.Strings[30983]="哈——啊哈！食物？我们可不吃这种有汁水的东西，朋友，除非他们来伤害我们。我们吃的是岩石、石块和沙砾。不过有时候我也觉得嚼嚼小骨头是一种不错的调剂。$B$B<格蒙刚用一只巨大的手举起一块巨石。将你带来的尸体摁在上面，就好象在蛋糕上放一块水果。然后在一阵宏亮的“嘎吱”声中，他把那块石头嚼碎，咽下了肚。>"
D.Strings[30984]="你知道艾萨莱特水晶的情况吗？"
D.Strings[30985]="艾萨莱特水晶？你们这些软弱的家伙倒是喜欢乱起新名字。这个“艾萨莱特水晶”又是什么？"
D.Strings[30986]="就是我们在这里找到的这堆蓝水晶。"
D.Strings[30987]="<格蒙刚的笑声浑厚而悠长。大地也随着他的声音在颤抖，远处细碎的砾石在不住地滑动。>$B$B哦……哈！哈！哈！小朋友，我很抱歉。我想，我们一族的行为方式和你总会有些区别。"
D.Strings[30988]="巨人的身上一直在掉下艾萨莱特水晶？但它到底是从巨人身上的什么地方出来的呢？"
D.Strings[30989]="它来自——嗯——你们的语言是怎样说的？嗯。我要说，我们一族可是没有厕所的。你明白吗？"
D.Strings[30990]="这是……你拉出来的？！而地精们一直在忙着收集这些东西？"
D.Strings[30991]="看起来是这样。你和你的朋友们可以随意收集这些东西。我想，它可能是有些用处。我们可不是经常会有这些东西的。"
D.Strings[30992]="那你，呃，多长时间会“有”一些这种东西呢？"
D.Strings[30993]="我们的生命进程不像你们那样快，我柔软的朋友！一个健康的巨人每十年会吃三顿饭。不过我每两年会吃一次小点心。我们每15到25年会上一次厕所……拉肚子除外。"
D.Strings[30994]="15到25年？助手格瑞里可不会喜欢听到这种消息！"
D.Strings[30995]="<格蒙刚和善地喷了一下鼻息。>$B$B 哈！我还没有这样细致地考虑过自己的个人习惯呢。你们总是让我感到吃惊。再见，朋友，祝你好运……无论你要找的是什么。"
D.Strings[30996]="能再告诉我一下关于艾萨莱特水晶的事情么？"
D.Strings[30997]="抓住一个！"
D.Strings[30998]="打败他们！"
D.Strings[30999]="无意冒犯，宝贝儿，但我的男朋友是奇普，而且现在我要听贸易大王的。$B$B赶快走吧，你挡住我的视线了。"
D.Strings[31000]="听着，$n，我不能让别人看见我在和你说话。你不再是贸易大王眼中的红人了，而我则需要为我的未来考虑。$B$B你明白我的意思，对吧，宝贝儿？另外，我现在和小甜甜在一起了。"
D.Strings[31001]="走开，小子。"
D.Strings[31002]="我的房子！"
D.Strings[31003]="<贸易大王用低微的耳语说道。>$B$B不管你是否能逃掉，绝不要以为我会忘记你这个卑微的家伙，$n。$B$B不必再为你那颗$g简单:漂亮;的脑袋而担心了。记住，我很快就会进行复仇！$B$B到时候，你将羡慕那些能成为我的奴隶的人。你逃不出我的手心。"
D.Strings[31004]="你身上连个刮痕都没有！干得好！"
D.Strings[31005]="真是不可思议！你向前蹦的速度简直比被火烧了尾巴的小猫更快。实在是太合适了！"
D.Strings[31006]="哦，我想我们全都知道，到底是谁该为现在这种一团糟的局面负责！不必担心，我保证$n会得到应有的教训！"
D.Strings[31007]="不要惊慌！我会让所有人都离开这座糟糕的岛屿。看着吧……我早已经计划好了！"
D.Strings[31008]="不要害怕，贸易大王加里维克斯就在这里。我们立马就要出发前往我们在艾萨拉的新家了！就算是某个人继续在那儿捣乱也没用。"
D.Strings[31009]="我禁不住会想，如果不是$n在科赞捣乱，我们现在早已安全到达艾萨拉，过上好日子了。"
D.Strings[31010]="我一直都在注意你，$n。如果我们之中只有一个能够离开这座岛，那么这个地精的名字就是贸易大王！"
D.Strings[31011]="你想要取代我在科赞的位置，$n？痴心妄想！别忘了，是我给了你今天的地位。现在你什么都不是了！不是了！！"
D.Strings[31012]="我要你们都好好听着……任何不跟从我的人现在就可以去找一个新的工作！"
D.Strings[31013]="大家不必担心，这只是前往我们新家园途中的一次短暂的休整。"
D.Strings[31014]="我们欠你的永远都还不清，$n。"
D.Strings[31015]="$n，谢谢你救了萨尔。我们一直都找不到他。$B$B<阿格娜关切的看着酋长。>"
D.Strings[31016]="返回夏克索卡的战场，否则半人马就会抛弃你！"
D.Strings[31017]="我发誓这排的队压根儿就没动过！"
D.Strings[31018]="另外那座岛上是有一座火山吗？"
D.Strings[31019]="即使以我们的标准来看，那个火箭也不安全！"
D.Strings[31020]="为什么我们要向一座有火山的岛发射火箭？我们不是刚刚在科赞的行动中幸存下来吗？"
D.Strings[31021]="看这东西的样子，我宁可试着和鲨鱼一起游泳！"
D.Strings[31022]="我就知道，应该把我的折叠椅带来。"
D.Strings[31023]="又见到你了，柔软的小朋友。这次你要做什么？"
D.Strings[31024]="嗨，$g兄弟:小姐;。乘坐火箭吧！耶！"
D.Strings[31025]="给，把这个吃了！这是一种特殊的巧克力石头。"
D.Strings[31026]="哦，$n，你又救了我们！感谢你为我们消灭了那些恶棍！"
D.Strings[31027]="<格蒙刚带着怀疑的神情看着这团软软的东西，然后又嗅了嗅它，便气恼地将它捏塑成一只地精的样子。>$B$B我怀疑你那些小绿人朋友没想让你做好事儿。去告诉他们，我们巨人可不是任人玩弄的。$B$B<为了表达他的意思，格蒙刚在把他刚做成的地精雕像交给你的时候，又用力拧断了它的脑袋。>"
D.Strings[31028]="本迪加斯！让这个新$r先了解一下情况，好吗？"
D.Strings[31029]="很高兴见到你，朋友！"
D.Strings[31030]="钩锤相信我能把事情做好。不能让这些琐碎的事情干扰他。"
D.Strings[31031]="你准备好被缩小了吗？这也许有一点痛，还有一点烧灼感。不过疼痛和抽搐很快就会过去的。"
D.Strings[31032]="我准备好了，缩小我吧！"
D.Strings[31033]="动作快一点， $n！几分钟之内，你就会回复到正常大小了。"
D.Strings[31034]="我必须瞄准被遗忘者的船。"
D.Strings[31035]="嗯，什么？"
D.Strings[31036]="吱吱！！"
D.Strings[31037]="<高大的巨人俯视着渺小的你。>$B$B$n，你换发型了？"
D.Strings[31038]="%s开始施放流星拳！"
D.Strings[31039]="镇定，朋友……$b$b随后的几个小时将决定我们部族的命运。"
D.Strings[31040]="我准备好了！我要参战！"
D.Strings[31041]="塞纳里奥之子，团结起来！"
D.Strings[31042]="$n，胜利是我们的！"
D.Strings[31043]="谢谢你……*喘息声*是你救了我一命。"
D.Strings[31044]="我……我还以为自己死定了。谢谢。"
D.Strings[31045]="我们脚下的地面在坍塌……我还以为我已经死了。我欠你一份情。"
D.Strings[31046]="我会接管这只猫。它看上去能够成为完美的诱饵。准备好去死吧，傻瓜！"
D.Strings[31047]="别弄脏我的猫，你这个混蛋！"
D.Strings[31048]="这套衣服真漂亮。专程为了聚会穿的吧！"
D.Strings[31049]="我已经准备好接受审判了。"
D.Strings[31050]="咿——嘎——！"
D.Strings[31051]="哦，$n，是你啊。请不要这样吓唬我。"
D.Strings[31052]="<这是一段手写的文字：>$B$B          秘密实验室档案馆$B     X.尼泽柏克，实验室主管$B$B$B请按蜂鸣器呼叫服务。"
D.Strings[31053]="<按响蜂鸣器>"
D.Strings[31054]="卫兵，我想和你们的高阶祭司谈谈。"
D.Strings[31055]="有这个必要吗？我想泰兰德女士还有更重要的事。"
D.Strings[31056]="能量的诱惑很难抗拒。错误已然铸成。"
D.Strings[31057]="不召见我我是不会走的。形势已经非常危险了。"
D.Strings[31058]="我从风中感到了变化，我们不能不闻不问。我带着诚意走过尘灰漫天、满目疮痍的过去，为得就是能让我们尽弃前嫌。"
D.Strings[31059]="卡多雷族人恐怕很快就会需要我们的知识与技艺。"
D.Strings[31060]="我可以等，卫兵……但请一定要召见我。"
D.Strings[31061]="冷静，卫兵。我不是要试图使用它。我只是……在记忆。"
D.Strings[31062]="够了。几百年来我一直与它相隔天涯。这座神庙中的月亮井也许是永恒之井枯竭的影照，但它仍然是那么……美丽。纯净。"
D.Strings[31063]="我已经忘记了。"
D.Strings[31064]="我不相信赞美与怀旧的思想会与这个社会相抵触。"
D.Strings[31065]="你就是那个不明就里的家伙。我坚持要等泰兰德召见我。"
D.Strings[31066]="%s注视着月亮之井，轻轻的叹了口气。"
D.Strings[31067]="作为塞纳里奥之子，我们团结在一起。感谢你。$b$b只要我们部族还存在，你在这里的事迹就不会被遗忘，$n！"
D.Strings[31068]="我们绝不会再让我们之间的差异分裂我们。$b$b塞纳里奥之子万岁！"
D.Strings[31069]="愿塞纳里奥的祝福倾洒在你的身上，就如同他曾经对这片土地的赐福，$r。"
D.Strings[31070]="加弗斯特厌倦了这些凡人。刺骨的寒风刮起来！"
D.Strings[31071]="斧子太弱了。看我弄好他，然后……然后砸扁你。"
D.Strings[31072]="你必须要等候召见。"
D.Strings[31073]="敢来泰达希尔证明你还有些许勇气，上层精灵。但这里不欢迎你。上古之战的伤痛和那些战争背后的企图让我们铭心刻骨。"
D.Strings[31074]="我们不应该再次犯错。回到你的流亡族人中去吧。"
D.Strings[31075]="不要死盯着这月亮井，流亡者。井水中的能量不属于你们。"
D.Strings[31076]="在回想你们的背叛吗？"
D.Strings[31077]="小心点，上层精灵。"
D.Strings[31078]="等时机成熟吧。"
D.Strings[31079]="嗨，$n。我知道这挺糟的，但贸易大王的船骸暂时就是我们的家了。"
D.Strings[31080]="你好，$r。请不要太惊讶。我确实是在用你的语言与你交谈。$B$B虽然身为迅猛龙，但我的智力已经通过一系列试验得到了大幅增强。你可以称我为“九号实验品”，这是我的创造者们不久以前给我取的名字。不过现在他们要么消失要么挂掉了。也许你能帮我个忙？"
D.Strings[31081]="随着我认知能力的增强，我开始审视我们这个种族。我们的大部分精力都被用于捕捉猎物。我在想，为什么我们不能用这些时间驯服并圈养这些猎物，让它们成为我们稳定的食物供给？$B$B我认为人类是很好的食物来源——很快就能被养肥，而且味道鲜美，还能够进行训练，代替我们完成畜牧工作。嗯……"
D.Strings[31082]="我早知道我会受到这种冷遇。长久以来我们一直在隐居，因为我们必须要与族人分离。$b$b那段时间已经过去。不管这颗幼树之荫下的居民是否会接受我们，上层精灵们都要摒弃过去的身份，从黑暗中返回光明。"
D.Strings[31083]="这真的是个好主意吗？"
D.Strings[31084]="爬升，爬升，火箭分离！"
D.Strings[31085]="我的兄弟和我乘船几天时间就能到达北吉尔尼斯。当然，我们得先完成修理工作。"
D.Strings[31086]="你以为你是个超级英雄，能拯救所有人，还能和那些野蛮的兽人交朋友？"
D.Strings[31087]="我要毁掉你！我是贸易大王！我有个计划能让我离开这个岛，并成为艾萨拉之王！"
D.Strings[31088]="记住我的话！我要干掉你，$n！我要把你们全都干掉！别挡我的道！"
D.Strings[31089]="海象人风筝"
D.Strings[31090]="迷你坐骑"
D.Strings[31091]="幽灵虎幼崽"
D.Strings[31092]="天灾战争"
D.Strings[31093]="哦，别盯着我不放。我只是个传话儿的。死亡猎手的领袖当然不会蠢到亲自到这来送死。历史不会重演的。"
D.Strings[31094]="刚出油锅，又入烈火，是吗，$n？"
D.Strings[31095]="刚出油锅又入烈火，是吗，$n？需要训练吗？"
D.Strings[31096]="我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！"
D.Strings[31097]="我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！$B$B需要训练吗，$n？"
D.Strings[31098]="我看见戴姆维克骑过这东西。所以我宁可使用缓落术。不过我还不知道这法术该怎么用。"
D.Strings[31099]="我看见戴姆维克骑过这东西。所以我宁可使用缓落术。不过我还不知道这法术该怎么用。$B$B想要训练吗，$n？"
D.Strings[31100]="干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？"
D.Strings[31101]="干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？$B$B我能教你些新东西吗？"
D.Strings[31102]="看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。"
D.Strings[31103]="看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。$B$B想要进行训练吗？"
D.Strings[31104]="嗨，$n。我很高兴能远离那些该死的猴子！"
D.Strings[31105]="嗨，$n。我很高兴能远离那些该死的猴子！$B$B那么，想要对你的技艺进行一些磨砺么？"
D.Strings[31106]="全能战士NX-01型在线。$B$B请塞入硬币，接受训练。"
D.Strings[31107]="我被一个$r给召唤出来了？真是难以置信。无论是出于绝望还是愚蠢，这都将是你最后的错误。"
D.Strings[31108]="%s喝了一口他酿的酒，禁不住打了几个哆嗦。"
D.Strings[31109]="我要的就是这个！现在我完全清醒了！太美味了！"
D.Strings[31110]="我要再重申一次，$n，我们之间工作关系的发展实在是令我感到高兴。在我的心智得到大幅度提升之后的几个星期里，我的地精恩人们开始了解到我的智力已经超越了他们。虽然他们仍然对此深表怀疑。$B$B很遗憾，正是由于我的祖先没能阻止最近这一系列的工业化“事件”，现在的我才能变得如此无所不能……"
D.Strings[31111]="我的心肝宝贝！"
D.Strings[31112]="%s的伤口开始愈合了。"
D.Strings[31113]="永别了，艾泽拉斯。我离开了一个在大灾变中被污损毁坏的世界。"
D.Strings[31114]="让我们点亮这根蜡烛！"
D.Strings[31115]="你渺小的智力根本无法和我超强的爪子相比！"
D.Strings[31116]="啊，新鲜的食物！"
D.Strings[31117]="首先是你，$r。明天就是整个世界！"
D.Strings[31118]="克拉伯尼克，你听到了吗？那些在门纳尔湖保卫战中牺牲的战士都是英雄。他们的无私也许拯救了全世界！我们应当郑重地纪念他们。"
D.Strings[31119]="克拉伯尼克？我希望你死了。被烈火烧成灰烬。"
D.Strings[31120]="我听到你说话了。"
D.Strings[31121]="用一座燃料仓库……纪念他们……如何？"
D.Strings[31122]="那一定非常不错！"
D.Strings[31123]="沉默吧，蠢货！"
D.Strings[31124]="我同情愚者！"
D.Strings[31125]="不要激怒我！"
D.Strings[31126]="%s嗅着索拉塔的衣服，发出沉重的鼻息声。"
D.Strings[31127]="赞美圣光，$n$g兄弟:姐妹;！让我们好好看看……"
D.Strings[31128]="嗯，找到问题了！这部机器里有个被我们称为鬼魂的家伙需要你对付。"
D.Strings[31129]="这需要一场老式的推土机驱魔仪式！如果她不服从管束，就请帮我一下，可以吗？"
D.Strings[31130]="喔！我们搞到了一个活的！"
D.Strings[31131]="我将驱逐你！不洁的灵魂……离开这里！"
D.Strings[31132]="强大的工具压迫你！强大的工具压迫你！"
D.Strings[31133]="神圣之火将净化你！"
D.Strings[31134]="死吧，地精！"
D.Strings[31135]="干得好！一切顺利。"
D.Strings[31136]="让克拉伯尼克知道，牧师教会的账单随后就到。为了圣光！"
D.Strings[31137]="嗯，我又一次忘记了自己是谁，正在这里做什么。如果出了什么事，就来叫我吧。"
D.Strings[31138]="唔……有人能帮帮我吗？"
D.Strings[31139]="啊，这是个测试。"
D.Strings[31140]="你会想看看幽暗城的模样。它就坐落在南边的旧洛丹伦废墟，你会找到一个下行的升降梯。等你到了，幽暗城的卫兵会给你更详细的指引。"
D.Strings[31141]="使用你的红外感温眼镜！"
D.Strings[31142]="你需要到那片悬崖去，找到斥候布拉克斯，$n。"
D.Strings[31143]="我需要借你驯服的丛林豹去悬崖，基拉格。"
D.Strings[31144]="帮我回忆一下有关卡亚矿的知识。"
D.Strings[31145]="卡亚矿……你是否知道，就是这种传说中的玩意儿，帮助地精全族成为了炼金术和工程学的究极大师？！$B$B正是这种材料帮助我们推翻了压迫我们的丛林巨魔，控制了科赞——愿她得到安息——它是最珍贵的矿石！$B$B嗨，你不会是认为卡亚矿石对那些猴子也起了作用吧？"
D.Strings[31146]="散布在这一地区的废墟是暗夜精灵文明发展到顶峰时期留下的遗迹。对于研究奥术的人来说，它们是蕴含着无数珍贵信息的宝藏。$B$B看样子，一队最不同寻常的暗夜精灵法师已经注意到了它们。是的，听我说，$r——暗夜精灵要取回他们的魔法遗产！如果他们在这里发现了有价值的东西，很可能会导致可怕的后果。除此之外，我倒是觉得他们的举动很有些意思。"
D.Strings[31147]="暗夜精灵法师，呸！"
D.Strings[31148]="需要更多的灵魂为引擎提供能量！"
D.Strings[31149]="我的灵魂属于您，主人。"
D.Strings[31150]="死亡的漩涡在召唤你！"
D.Strings[31151]="<奥术构造体的“声音”似乎在你周围四面八方同时响起，撕扯你的耳膜，让你寒毛倒竖。这个构造体在用一种你听不懂的语言和你说话。就好象有多个话音叠加在一起，同时传入你的耳朵。>"
D.Strings[31152]="Um... Al'teth ... la c'tolgar？还是其它什么。"
D.Strings[31153]="%s正在追赶你。快跑！"
D.Strings[31154]="%s正在追赶$n。"
D.Strings[31155]="%s开始释放一块毒云！"
D.Strings[31156]="哎呀！"
D.Strings[31157]="我的眼睛……噢！"
D.Strings[31158]="%s体内充满了无法控制的魔法能量。"
D.Strings[31159]="不，是那个！那个！就是他！"
D.Strings[31160]="快点，趁他们在一起的时候上毒！"
D.Strings[31161]="不要乱动！站稳了，等我把他们都炸飞！"
D.Strings[31162]="看——它松开了……"
D.Strings[31163]="那个$r在这里干什么？"
D.Strings[31164]="我们该怎样阻止它？"
D.Strings[31165]="发明家，你干嘛楞在那儿？难道你不知道身边的是谁吗？"
D.Strings[31166]="那是$n！正是因为$G他:她;，我们才能继续在这里呼吸，而不是在科赞变成碎片。"
D.Strings[31167]="后退，我要让$g他:她;活过来！希望浸水的起搏器不会把我们都杀死！"
D.Strings[31168]="我能做的都做了。现在就要看$g他:她;自己了。听到我的话了吗，$n？来吧，振作起来！现在还不是去见圣光的时候！"
D.Strings[31169]="你做出了正确的选择。我们全都深深地感谢你，$n。但不要让自己的生命遭受危险。"
D.Strings[31170]="还有许多幸存者需要救治。我们海滩上再见吧。"
D.Strings[31171]="%s开始不断召唤出炸雷！"
D.Strings[31172]="$n，我的孩子！$B$B你想要学习我的手掌热疗技术吗？$B$B不？绷带技术？你想要学习绷带技术？"
D.Strings[31173]="哈！$n，你看上去比以往更丑了！"
D.Strings[31174]="%s发动了一场白骨风暴！"
D.Strings[31175]="白骨风暴！"
D.Strings[31176]="这是个原始的伪装法术，$r，但它应该有用。"
D.Strings[31177]="请不要见怪，$n。也许你的确是一台狂野的杀戮机器，不过你现在至少还是我们这一边的。"
D.Strings[31178]="我们在甲板上见，$n。再次感谢你解救了我。"
D.Strings[31179]="滚远点！黑喉部族不想和你打交道，$r。"
D.Strings[31180]="欢迎你，朋友。我们有许多事要谈。$B$B被你称作“部落”的那些野兽正在这片森林中横行作恶。他们可怕的岩石条带切开了我们的土地，吓跑了我们捕猎的动物，让空气中充满了噪音和灰尘。$B$B告诉我，朋友。我们黑喉部族该怎样加入你们的“联盟”？"
D.Strings[31181]="别着急，熊脸丑八怪。首先，我需要来次足浴。"
D.Strings[31182]="你闯进我的家园，向我的人民这样颐指气使，你到底想干什么？"
D.Strings[31183]="这是什么臭味？是你身上的？我可没开玩笑。"
D.Strings[31184]="什么？我们带着良好的愿望来参加谈判，而你却只是来侮辱我们？"
D.Strings[31185]="联盟要求你们在每个新月时把新生儿送进我们的童工劳动营。"
D.Strings[31186]="哈格鲁姆渗透进黑喉要塞的计划实在是极具野心。对于一个兽人来说，这已经可以说是诡诈透顶了。在我把你传送过去之前先把这身魔法伪装服穿好。"
D.Strings[31187]="这身魔法伪装只能持续几分钟。我将把你直接传送到黑喉要塞的核心位置。然后你要立刻和他们酋长谈判……并准备好一路冲杀出来。"
D.Strings[31188]="我准备好了，把我传送到黑喉要塞去吧。"
D.Strings[31189]="可怜的$n。你这是送$g他:她;去完成一个自杀任务，哈格鲁姆。"
D.Strings[31190]="你们最好赶紧习惯这种待遇，硬肉干。联盟只不过把你们当作宠物。你们明白吗？"
D.Strings[31191]="闭嘴，长毛的呕吐物！很快你们就要学会向你们的侏儒统治者屈服了！！"
D.Strings[31192]="你的话激怒了我，外来者。如果这就是你们所谓的“联盟”能给我们的，我们绝对不会加入！"
D.Strings[31193]="当你的族人成为联盟铁腕下的奴隶时，你们将别无选择！"
D.Strings[31194]="你说了这么多，我听到的却只是“呱啦呱啦，我们熊怪用自己的粪便洗澡。”"
D.Strings[31195]="<扯掉他的脐环。>"
D.Strings[31196]="战士们——联盟渣滓背叛了我们！消灭他们！"
D.Strings[31197]="是$n？！抱歉，医生，我还以为$g他:她;死了！"
D.Strings[31198]="我还记得和我的兄弟一起在艾萨拉荒野上露营的时候。看看它现在的样子。"
D.Strings[31199]="那个叫克希雷姆的家伙真是个古怪的人。"
D.Strings[31200]="为什么我要签这个字？"
D.Strings[31201]="你一定是在和我开玩笑……"
D.Strings[31202]="圣光在上！这一定是世界的尽头！"
D.Strings[31203]="这里的地震永远都停不下来吗？"
D.Strings[31204]="我们做了什么，才会受到这样的报应？"
D.Strings[31205]="哦，不。不要再来了！"
D.Strings[31206]="我们的末日到了！"
D.Strings[31207]="我们不应该任由那些背负着诅咒的人再出现在我们中间。这样不对。"
D.Strings[31208]="小心，$n。如果你不是克雷南的宠物，那你早就应该死了。"
D.Strings[31209]="狼人杀了我的双亲，$n。你一定要小心。"
D.Strings[31210]="真高兴能再看到你，$n。而且一根毛都不缺。"
D.Strings[31211]="谢谢，$r。你的坚持和为了保卫你们一族所做的贡献激励了你的人民和朋友。请让我用这份礼物表达我的谢意。伸出你的手，接受你的奖励吧，$n！"
D.Strings[31212]="你刚刚赢得了一块显示卡！！"
D.Strings[31213]="喘气啊，该死的！"
D.Strings[31214]="引爆中"
D.Strings[31215]="我的肋骨断了。"
D.Strings[31216]="感谢你，地精！"
D.Strings[31217]="你好，地精！"
D.Strings[31218]="感谢你救了我的命。"
D.Strings[31219]="准备接受命令，基拉格！"
D.Strings[31220]="时刻保持警惕，$n。"
D.Strings[31221]="你……你看到了吗？"
D.Strings[31222]="那……那件事发生了？"
D.Strings[31223]="不……这不可能。"
D.Strings[31224]="诅咒这片土地，我们不能留在这里。"
D.Strings[31225]="这是部落的胜利！"
D.Strings[31226]="我们要让$g他:她;过去吗？"
D.Strings[31227]="$g他:她;已经是克雷南的人了。这是国王的命令。而且，看样子我们还有更大的问题要处理。"
D.Strings[31228]="即使这瓶药能起作用……我们也不能让狼人在我们的城里乱跑，克雷南。"
D.Strings[31229]="一定要万分小心。没人会邀请你去他们家里。但至少他们也不会公开向你射击。"
D.Strings[31230]="欢迎回来，$n。你很幸运。对于像你这样受到诅咒的人，克雷南的治疗方法并不总是有效的。"
D.Strings[31231]="对于地精来说，还不算糟。"
D.Strings[31232]="在战斗中，那个$c是怎么骗的你？"
D.Strings[31233]="人类都是懦夫。听到我的话了吗，人类？出来，带着荣誉大战一场！"
D.Strings[31234]="我还以为地精只会卖卖东西，吹吹牛呢。"
D.Strings[31235]="你听到了什么吗？注意周围的动静，$n，小心有人偷袭我们。"
D.Strings[31236]="告诉我，地精，为什么你们的奴隶船会开进我们的战场？"
D.Strings[31237]="你想过要杀我，小人类？这个小地精比起可怜的你们更有勇气！"
D.Strings[31238]="你那条腰带里还有什么？"
D.Strings[31239]="啊哈哈！你会喜欢上这个的！"
D.Strings[31240]="%s发出怒吼，在黑暗力量的作用下开始膨胀！"
D.Strings[31241]="这里发生了许多变化，年轻人。不管看到什么奇怪的东西都不要惊慌……比如我。哞。"
D.Strings[31242]="保护船长！"
D.Strings[31243]="伙计们，守住阵地。"
D.Strings[31244]="坚守战线，弟兄们！"
D.Strings[31245]="出了什么事？！"
D.Strings[31246]="加快速度！我们不能让那条龙跑了！"
D.Strings[31247]="我能为你提供些什么，$n？"
D.Strings[31248]="对新武器有兴趣吗，$c？"
D.Strings[31249]="你知道些什么有关古剑的事？"
D.Strings[31250]="当我在失落群岛上束手无策的时候，我见识了我们新地精盟友的能力。但现在，我们要测试他们的才华了：我们要在敌人的要塞中与他们作战。"
D.Strings[31251]="有人不相信传说中的暗夜精灵莫霍克。$B$B真为他们悲哀。"
D.Strings[31252]="我相信你。"
D.Strings[31253]="跟着我，$n！"
D.Strings[31254]="幸会，莫霍克的好$G兄弟:姐妹;。"
D.Strings[31255]="不要暴露了我们的位置，$n！那座塔里塞满了保镖。"
D.Strings[31256]="我准备好了，史莉琪。我们行动吧。"
D.Strings[31257]="去取下那个队长的首级吧——我正在安装炸药。"
D.Strings[31258]="好了，这个地方就要爆炸了。我们赶快离开这里！"
D.Strings[31259]="霜牙，干掉那个蠢货！"
D.Strings[31260]="冰霜巨龙霜牙凝视着$n，准备发动一次冰霜袭击！"
D.Strings[31261]="你只能在克罗雷马厩场和克罗雷果园中骑乘高山马。"
D.Strings[31262]="因为在龙骨荒野发生的那场，啊，“误会”，我们不得不将全部设备都迁移到这座破旧肮脏的城堡里。$B$B不过我们现在有了足够的时间和场地来制作各种新鲜可爱的……产品……"
D.Strings[31263]="开始战斗"
D.Strings[31264]="准备武器"
D.Strings[31265]="听我说，$c！"
D.Strings[31266]="卫兵！他们在塔底搞鬼，快阻止他们！"
D.Strings[31267]="我准备好了。但是，我倒是愿意不参加这庆典。"
D.Strings[31268]="%s开始施放哀嚎之魂！"
D.Strings[31269]="%s开始|cFFFF0000释放灵魂！|r"
D.Strings[31270]="艾泽拉斯遭到了进攻，而入侵者来自于现实位面以外的空间……"
D.Strings[31271]="她拼命呼喊着，寻求帮助，但几乎没人能听到她的哀求。"
D.Strings[31272]="我能听懂他们说话， $r。请让我翻译……"
D.Strings[31273]="拿起剑，击败我们世界的敌人。"
D.Strings[31274]="[ph] 愚蠢的生物们，你们那点牢骚面对巫妖王的意愿根本不值一提。你们会变成他的奴仆，生生世世！"
D.Strings[31275]="[ph] 收起你们那些可悲的牢骚吧。你们会继续下去的。这些像狗一样可怜的家伙全都要侍奉巫妖王，生生世世！"
D.Strings[31276]="[ph] 从现在开始，你的每一根骨头都要承担永远的劳作…等等…入侵者？在这里？！马上解决掉他们！"
D.Strings[31277]="[ph] 求你了，我没法再干更多的活儿了！请让我们稍微休息一会儿吧！"
D.Strings[31278]="如果失败，世界就会毁灭，我们也将一同灭亡！"
D.Strings[31279]="你将得到强大的祝福，好$r。"
D.Strings[31280]="第一场挑战要求你骑上一头银色战狼。你会在演武场的墙边找到这些坐骑，骑着它们来找我，然后我们继续。"
D.Strings[31281]="各就各位。"
D.Strings[31282]="全队前进。"
D.Strings[31283]="离开开阔地。"
D.Strings[31284]="小队，你们知道该做什么。"
D.Strings[31285]="找到侧袭位置。"
D.Strings[31286]="行动。"
D.Strings[31287]="我们搞到个活的。"
D.Strings[31288]="发现目标。"
D.Strings[31289]="12点"
D.Strings[31290]="已定位。"
D.Strings[31291]="前方有敌人。"
D.Strings[31292]="有敌人。"
D.Strings[31293]="一团糟。"
D.Strings[31294]="有人想去野营烧烤吗？"
D.Strings[31295]="热力还要更强！"
D.Strings[31296]="地精小队报告。"
D.Strings[31297]="等待你的命令。"
D.Strings[31298]="有敌情。"
D.Strings[31299]="看着我有趣吧。"
D.Strings[31300]="变烤肉吧。"
D.Strings[31301]="我在融化……融化！"
D.Strings[31302]="击中目标。"
D.Strings[31303]="是个女孩，唉呦。"
D.Strings[31304]="发现目标生物。"
D.Strings[31305]="爆头！"
D.Strings[31306]="我对魔法器物有一点粗浅的认识，蓝龙自己的麻烦已经够多的了。$B$B图书馆里曾有一本书介绍了我们为凡人盟友打造的那些剑，不过恐怕我已经把这本书借给了夺日者的使者。$n，你并不是第一个来这打探那些古剑消息的人。"
D.Strings[31307]="我对魔法器物有一点粗浅的认识，蓝龙自己的麻烦已经够多的了。$B$B图书馆里曾有一本书介绍了我们为凡人盟友打造的那些剑，不过恐怕我已经把这本书借给了银色盟约的使者。$n，你并不是第一个来这打探那些古剑消息的人。"
D.Strings[31308]="%s释放毒气孢子！"
D.Strings[31309]="%s开始施放|cFFFF7F00刺鼻毒气！|r"
D.Strings[31310]="你们的努力是徒劳的，入侵者。巫妖王让我统率的可是一支亡灵大军！小心了！"
D.Strings[31311]="固执的家伙！你们根本到不了主人的密室！士兵们，消灭他们！"
D.Strings[31312]="就要完成了。"
D.Strings[31313]="安装完毕，撤离！"
D.Strings[31314]="钟摆，炸飞这玩意儿。"
D.Strings[31315]="霜牙，把他们困在隧道里！统统给我埋了！"
D.Strings[31316]="那些灵魂发怒了，展开了攻击！"
D.Strings[31317]="他们派你来干掉我？你就是部落里最强的战士？"
D.Strings[31318]="这一切……还远没有结束……$r。"
D.Strings[31319]="走这边！我们就要对天灾领主的领地发动袭击了！"
D.Strings[31320]="|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 过热  |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t"
D.Strings[31321]="我真应该向你收费。"
D.Strings[31322]="圣光与你同在……只需要掏一两个银币！"
D.Strings[31323]="随手丢个韧可是好习惯！"
D.Strings[31324]="你不会介意再来个韧吧，老板。"
D.Strings[31325]="这次是免费的，$g先生:女士;。"
D.Strings[31326]="很想知道我们什么时候能够再见，$n。"
D.Strings[31327]="这不算很厉害，但它也许刚好能保护到你的绿皮肤。"
D.Strings[31328]="只想让你知道，我们全都在指望你呢！"
D.Strings[31329]="<你面前的兽人看上去比以往更绿了。>$B$B$C，那些地精已经把“所有人都能吃的海产”带了过来。但这些东西……*呃*，也在我的胃里引起了一场大灾变。"
D.Strings[31330]="*啊！*"
D.Strings[31331]="不应该要……蛤蚌……"
D.Strings[31332]="就是……这种杂烩。"
D.Strings[31333]="“这些都是能吃的，”他说。*打嗝*"
D.Strings[31334]="这个……蚌肉……"
D.Strings[31335]="这个“浓汤”里都有些什么？"
D.Strings[31336]="求你了！我真的……我真的受不了了！"
D.Strings[31337]="要让我说的话，暗夜精灵在一万年以前就已经丢掉了这个地方。今天他们被我们驱逐只不过是一个形式上的事情。"
D.Strings[31338]="这块巨大的石头闪烁着聚焦的奥术能量。"
D.Strings[31339]="<使用这块石头传送回瓦罗莫克。>"
D.Strings[31340]="这块巨大的石头闪烁着集中起来的奥术能量。$B$B如果安多瑞尔的指示是可信的，它就应该能轻易地重新集中这块石头的能量。"
D.Strings[31341]="干得好，$n！那么，让我集结队伍……"
D.Strings[31342]="很好。无论你们想干什么……都努力去做。"
D.Strings[31343]="$n，不要忘记，现在你就能使用召唤石将自己传送回我在瓦罗莫克的所在地了。"
D.Strings[31344]="咸鱼翻身的时刻到了，亚达尔。这场比赛会让我们从此扬名立万！"
D.Strings[31345]="我不知道。我不确定这坐骑能带我们走向辉煌。"
D.Strings[31346]="你为什么退缩了？你这么矍铄、健壮……当然，你少了一只眼睛，但这绝不能让你临阵退缩！"
D.Strings[31347]="我讨厌雷象，非常讨厌。"
D.Strings[31348]="呃，这倒是个问题。"
D.Strings[31349]="你为什么不去比赛？"
D.Strings[31350]="我……曾和一个人有点不愉快，那家伙现在是夺日者的头目了。其实就吵了一架，换你你也会的。"
D.Strings[31351]="不用说了，那天我走进大帐，里面在吵架。"
D.Strings[31352]="他们拒绝训练你？"
D.Strings[31353]="他建议我拿着长矛去做点别的事。他说那里不是我进行粗野行为的地方。"
D.Strings[31354]="没错，这就对了，如果我们都参加这场锦标赛，那么最终的结果很可能是我们在沙场上一决胜负。"
D.Strings[31355]="在我看来你输定了。蛮力和武勇永远赢不了速度和智慧。"
D.Strings[31356]="听好了，列队！看到会跑的东西就开枪。如果对面也开枪……就快跑吧！"
D.Strings[31357]="好了，该行动了。"
D.Strings[31358]="在这见到我吃惊吗？每个人都需要干净衣服，除了找你的水元素帮忙，还有更好的办法吗？$B$B只需把你的衣服拿来，象征性的付点钱，不知不觉中你的衣服又变得清爽、干净！"
D.Strings[31359]="奥术师泰拜林说你会借我一件战袍。"
D.Strings[31360]="你很走运。我刚装了些你需要的，正准备拿去洗。"
D.Strings[31361]="看到大堆的衣服和那桶水了吧？我会大声喊需要什么，你就把需要的扔进盆里。准备好了吗？"
D.Strings[31362]="哦，不！不应该这样的。现在我们不得不再弄些清洁剂重新开始了！"
D.Strings[31363]="别人会取代他。你是在浪费时间。"
D.Strings[31364]="[ph] 真是个倒霉的侏儒。要不是有他在，那只怪兽肯定打得更好。"
D.Strings[31365]="警告：伐木机设计程式仅能在艾萨拉使用。"
D.Strings[31366]="啊呀。"
D.Strings[31367]="武勇？没有我的坚持不懈，咱们能有今天吗，你这种绣花枕头上去5秒就得趴下。"
D.Strings[31368]="你就胡诌吧。不管怎样，到马厩还有一段路，咱们带的酒还够。"
D.Strings[31369]="我听说那些长矛都是粗制的，我可不想扎的满手都是刺儿。"
D.Strings[31370]="谁不是呢？"
D.Strings[31371]="嘿，要是我们成功了，你猜接下来会怎么样。"
D.Strings[31372]="你说那冻冰的堡垒？当然是面对巫妖王最强大的爪牙。"
D.Strings[31373]="我们两个对阵茫茫的亡灵大军。"
D.Strings[31374]="……也许我们应该去找个不那么危险的地方混口饭吃。"
D.Strings[31375]="毕竟，慎重比勇气更重要。"
D.Strings[31376]="你们之中的某一个能不能快点把对方干掉？我们可是急着要拿钱呐！"
D.Strings[31377]="有人要赌赌这两个白痴谁会打赢么？"
D.Strings[31378]="你们两个白痴能消停下么，老板来了！"
D.Strings[31379]="暗影对火焰，你们可真复古。吃一记闪电！"
D.Strings[31380]="下一次我可不会打偏了！"
D.Strings[31381]="我正急着要学习妖术呐。你们俩可怜的后半生就只能以青蛙的模样度过了。"
D.Strings[31382]="你们俩是怎么混到主管级的？"
D.Strings[31383]="要让我做这种无利可图的事，他们付的酬劳显然不够！"
D.Strings[31384]="朝桶里扔几条裤子！"
D.Strings[31385]="快点儿，扔几件衬衫到洗衣桶里！"
D.Strings[31386]="加几件儿恶心的…呃，我是说，“棘手的”！"
D.Strings[31387]="桶里需要加水！"
D.Strings[31388]="看到人多好办事了吧？尽管从干净的里面挑你需要的吧，不过别忘了穿完了再送回来。"
D.Strings[31389]="一会儿我还有点别的事要你做。"
D.Strings[31390]="你的拯救已经来了……而且它的价格很合理！"
D.Strings[31391]="我要从你的薪水中收取劳务费。"
D.Strings[31392]="让我给你治疗一下！"
D.Strings[31393]="我有最好的治疗手段，独此一家，别无分号！"
D.Strings[31394]="奶从天降！"
D.Strings[31395]="我喜欢早晨进行拯救行动。"
D.Strings[31396]="我有你需要的！"
D.Strings[31397]="圣光就是金钱，朋友。"
D.Strings[31398]="救援来了！"
D.Strings[31399]="不要再傻躺着了。"
D.Strings[31400]="别想轻易逃过债务。"
D.Strings[31401]="回去工作！"
D.Strings[31402]="赶快走吧。"
D.Strings[31403]="事不过三，朋友。再多的话，我的费用就要增长了。"
D.Strings[31404]="为了这个，你可是要付给我风险酬金的，朋友。"
D.Strings[31405]="这次你甚至没有跑出去20尺。"
D.Strings[31406]="<这是一段手写的文字：>$B$B          秘密实验室档案馆$B     X.尼泽柏克，实验室主管$B$B$B<看样子，现在没有人在家。也许你应该稍后再来？>"
D.Strings[31407]="海盗？不许提起海盗！！！$B$B别让他们抓住我，老板。我还年轻，还不想死！！！"
D.Strings[31408]="哇噢，你可装了不少。"
D.Strings[31409]="冰凉乐趣！"
D.Strings[31410]="你看起来可真酷。"
D.Strings[31411]="我的嘴巴湿透了！"
D.Strings[31412]="……是喝酒时间么？"
D.Strings[31413]="阿夸诺斯，别把衣服扔那么高了！我知道你不用看艾萨斯·夺日者在喷泉找到自己裤子时的脸色！"
D.Strings[31414]="干杯吧，话痨。"
D.Strings[31415]="干，小鬼。"
D.Strings[31416]="海盗不在我的合同之内！"
D.Strings[31417]="太强大了。我们必须马上离开！我的魔法只能暂时拖住他。快来，英雄们！"
D.Strings[31418]="你来这要干什么，$c？"
D.Strings[31419]="你终于来了。我们必须尽快把这本宝典带到冰冠冰川。"
D.Strings[31420]="魔导师哈瑟尔，我已经做好递送宝典的准备了。"
D.Strings[31421]="永远不要相信那些夺日者。他们不遗余力的破坏我们和银色北伐军盟友的关系。"
D.Strings[31422]="请停下来吧！我只是需要休息一会儿！"
D.Strings[31423]="我会…回…去…工作…的…我…保证。"
D.Strings[31424]="找到你了！我几乎以为你已经被逐日者劫走了。你准备好把宝典递送给冰冠冰川的使者了吗？"
D.Strings[31425]="你能为我准备一套新的夺日者伪装吗？"
D.Strings[31426]="魔导师哈瑟尔，你能为我准备一套新的银色盟约伪装吗？"
D.Strings[31427]="<这头恐龙紧盯着你，大声咆哮着，嘴里不停地流出口水。>$B$B<看样子，九号实验品留下了一个她的克隆品，只是这个克隆品的智力没有像她一样得到强化。她这样做大概是为了隐藏自己的行迹。聪明的女孩！你在考虑你给这个宇宙带来了什么……>"
D.Strings[31428]="我曾经遵从阿尔萨斯，这真让人难以置信。"
D.Strings[31429]="我们都是王子的奴隶，我们的境遇生不如死。"
D.Strings[31430]="我真感到吃惊，他们没把我们的穿戴和武器一块儿拿走…"
D.Strings[31431]="巫妖王为什么需要活着的仆人？他为什么不干脆把我们都杀了？"
D.Strings[31432]="我们是来这进行调查的时候被捕的，当时的样子就像个侏儒把手搭在梅卡托克国王的王座上。"
D.Strings[31433]="那头座狼是工头。他早晚会注意到即将发生的事。"
D.Strings[31434]="呃…这么久…我的肋骨…撑不住了…"
D.Strings[31435]="等等！停！别杀我！我把一切都告诉你！"
D.Strings[31436]="你要找的就在主人的巢穴里，但要先干掉泰兰努斯才能进去。霜之哀伤就在映像大厅里……你们……你们能在它那里找到真相。"
D.Strings[31437]="我发誓我没说谎！求你了！别杀我！"
D.Strings[31438]="啊…不！！"
D.Strings[31439]="为什么女妖之王要饶恕你的小命？"
D.Strings[31440]="霜之哀伤？巫妖王从不离开他的佩剑。如果你撒谎……"
D.Strings[31441]="叛徒就是这种下场。来吧，我们必须解救那些奴隶，再看看巫妖王的密室中都有什么。"
D.Strings[31442]="%s逃跑了！"
D.Strings[31443]="一定要注意一下哥布兰的征兵布告。一旦我们的行动顺利展开，很希望你能再次加入我们。"
D.Strings[31444]="很高兴又见到你了，$n。"
D.Strings[31445]="$n!到这里来。我有一个“特别项目”，需要你来帮个忙。"
D.Strings[31446]="没用的虫子！死亡正等待着你！"
D.Strings[31447]="不要以为我会那么容易让你进入主人的密室。有本事放马过来吧。"
D.Strings[31448]="我不会因为你的可怜而手下留情，有话快说吧。"
D.Strings[31449]="恶有恶报。来吧，英雄们。去看看那个侏儒说的是真是假。如果阿尔萨斯没了霜之哀伤，我们也许有机会阻止他。"
D.Strings[31450]="霜之哀伤无人守卫？不可能！"
D.Strings[31451]="卡雷派我来的……"
D.Strings[31452]="卡雷苟斯？！这就是你来找我的好理由？$B$B那就祝你好运吧，伙计。"
D.Strings[31453]="不，不，不，你不明白。我是来帮忙的。"
D.Strings[31454]="哈，你当然是来帮忙的，来拯救这个蓝色的大家伙，现在他已经彻底沉陷在灵魂世界里，完全被魔法物品迷住了。但卡雷苟斯并不明白，我已经翻开了新的一页。$B$B我与“某人”相遇了。"
D.Strings[31455]="一头龙？哈！别说胡话了。$B$B你真是个无礼的$r，她就在这里！"
D.Strings[31456]="……那位灵魂医者？"
D.Strings[31457]="她有名字。她的名字是安娜拉。你应该对她保持应有的尊敬。$B$B她和她的姐妹们有多少次将你从死亡的利爪中拯救出来？你这种人真是从来不懂得尊重他人，不是吗？"
D.Strings[31458]="很抱歉，我并不是要这样无礼，我只是……"
D.Strings[31459]="我知道。我知道。我们永远也不可能，对吗？龙和灵魂医者……两个完全不同的世界！更别提生理方面的问题了。$B$B但你错了。我们有着一种更深刻的联系。安娜拉和我，我们相爱了。$B$B而且我很喜欢这里。这里没有那些惹人讨厌，让我发怒的冒险者。"
D.Strings[31460]="这根本就不是我想说的。"
D.Strings[31461]="好吧，让我们回到正题。要知道，这些无谓的话题都是你搞出来的。"
D.Strings[31462]="我是……得了吧。我到这里来是为了警告你，黑龙正在这里捕杀你。"
D.Strings[31463]="哦，是吗？你以为我没有注意到被烧焦的土地和那些无意义的杀戮吗？无论他们到哪里，都会留下这些痕迹。我还没有老糊涂呢。"
D.Strings[31464]="你已经知道了？那为什么你不阻止他们？"
D.Strings[31465]="干嘛要自找烦恼？他们绝不可能知道我在哪里。他们也不会损害这里已经被发现的古物。$B$B而且呢，邪恶和毁灭有一个有趣的共同点，那就是它们最终会把自己摧毁。"
D.Strings[31466]="但卡雷苟斯正竭尽全力要阻止他们。他需要你的帮助。"
D.Strings[31467]="他正在对付黑龙？而且派你来向我寻求帮助？他有没有跪求？有没有泪流满面？$B$B<艾索雷苟斯向远处望去，一脸露齿的坏笑。>$B$B你知道，要是我去替他解了围，他可就欠了我一辈子的人情。也许他得帮我也做一个太阳井妹子什么的来还这人情。$B$B没冒犯的意思，安娜拉。"
D.Strings[31468]="你会来吗？"
D.Strings[31469]="是的，是的，我会去救他。$B$B不过你可别被他的救世英雄的小故事迷惑了！他只是想引起别人的注意。我发誓，他一定想成为下一个守护巨龙。这真可笑。"
D.Strings[31470]="我这就去让他知道。我们在漆黑山脊见面吧。"
D.Strings[31471]="好了，好了，别催我。"
D.Strings[31472]="你管这个叫触发装置？这可不是玩具！"
D.Strings[31473]="再用心一些，霍维奇。你也是，格伦尼克斯！钩锤只需要绝对的完美。"
D.Strings[31474]="这是什么？我告诉过你，我要把螺纹压在阻断螺栓上！我们现在只能重新制作整个装载系统了！"
D.Strings[31475]="布拉科维兹，你最好给这些反冲设备涂好油，否则我就把油涂到你的脸上。"
D.Strings[31476]="弗林克，你还没有为液压反弹起重器编译好压缩数据？赶快，赶快！"
D.Strings[31477]="这就是复位减震桶吗？在我看来就是垃圾。重新制造！"
D.Strings[31478]="我们准备好了！出发！"
D.Strings[31479]="我没办法阻挡他太久，我们必须马上离开！"
D.Strings[31480]="这里到底发生了什么事？！？！"
D.Strings[31481]="只有几次漂亮的坠毁才能真正“磨砺”一台飞行器。$B$B任何头脑正常的地精都不会只安心于安全的飞行。"
D.Strings[31482]="钩锤想要我做什么？他终于完成了他的炸弹，然后他想让我把它投到海湾的那头去？不行！$B$B听着，我会帮你把我的一架直升机设定为自动驾驶状态。然后我还会祝你好运！$B$B接着我就要到掩体里去了。"
D.Strings[31483]="费利兹，把直升机给我。"
D.Strings[31484]="这全都是你的错，斯登！"
D.Strings[31485]="你在找艾索雷苟斯？痛苦海岸灾星？风暴海湾之祸？艾萨拉的魔法之主？$B$B好吧，你找到他了。$B$B<艾索雷苟斯似乎是在微笑。>"
D.Strings[31486]="我受够了！"
D.Strings[31487]="我也一样，恐怖图腾。"
D.Strings[31488]="不必担心，年轻人。我知道我们的安排只是……暂时性的。我会没事的。$B$B但是你，你不属于这里。现在你的时候还没有到。我会帮助你返回生命世界。$B$B这是我的责任。"
D.Strings[31489]="贝恩！你暴露了！去干掉他！"
D.Strings[31490]="你也许拯救了艾索雷苟斯，$r，但你的生命也将在这里结束。"
D.Strings[31491]="我不这样想，小蜥蜴。"
D.Strings[31492]="你会带着羞耻死去，就像你可怜的父亲一样。"
D.Strings[31493]="杀死我父亲的不仅仅是地狱咆哮的狂怒，还有懦夫的毒药。"
D.Strings[31494]="你们有机会吗？！"
D.Strings[31495]="[PH] 不要企图违抗主人的意愿！"
D.Strings[31496]="为什么你要破坏我们的家园？！"
D.Strings[31497]="你打破我们的洞穴，我要打破你的脑袋！"
D.Strings[31498]="穴居人洞穴全完了！你要为此付出代价！！"
D.Strings[31499]="这样就可以了。"
D.Strings[31500]="你来自寻死路吗？很高兴能帮到你。"
D.Strings[31501]="你来得非常及时，谢谢！"
D.Strings[31502]="我可不想死在沼泽地里。再次谢谢！"
D.Strings[31503]="是时候逃跑了！"
D.Strings[31504]="让我们离开这片沼泽！"
D.Strings[31505]="你这个小贼！克洛斯发现你了！克洛斯要把你的脸打扁！"
D.Strings[31506]="谁敢碰克洛斯的旗帜？！"
D.Strings[31507]="%s爆成一团神秘的孢子云。"
D.Strings[31508]="这一击是给你的。"
D.Strings[31509]="还没有完，贝恩……"
D.Strings[31510]="%s回归大地了！"
D.Strings[31511]="旧伤尚未复原，$g小伙子:姑娘;。我尚能深深地感觉到。没错，我还有仇要向阿尔萨斯报，当他还未成气候时我就应该好好教训他，我会给他补上这个的。总是感觉他有些不对劲。$B$B你的船员准备好以后告诉我一声，我们准备起飞直达堡垒的顶部。$B$B阿尔萨斯决不会料到这一招！"
D.Strings[31512]="我的战友全都加入，穆拉丁。出发吧！"
D.Strings[31513]="找到了！"
D.Strings[31514]="这是我们最后的阵地。今天的一切都将千古流传。无论是生是死，我们都是为了荣誉而战。我们都是为了自由和人民而战！记住，英雄们，在这邪恶之地，恐惧是你们最大的敌人。勇气将让你们的灵魂比千颗太阳还要明亮。敌人会在你们面前溃不成军。正义的光芒将彻底摧毁他们！"
D.Strings[31515]="$G先生:女士;"
D.Strings[31516]="解散！"
D.Strings[31517]="<做出一系列复杂的手势。>"
D.Strings[31518]="那到底是什么？"
D.Strings[31519]="那是……瑜伽？"
D.Strings[31520]="你想要我去偷第三个？"
D.Strings[31521]="%s看起来很困惑。"
D.Strings[31522]="你为什么要喊我妈妈？"
D.Strings[31523]="这太粗鲁了……"
D.Strings[31524]="领袖也要承受压力……"
D.Strings[31525]="从实际操作方面讲，我不认为这是可能的，长官。"
D.Strings[31526]="长官，爆炸和枪炮的声音应该已经让我们暴露了。你不必再打手语了。"
D.Strings[31527]="干脆地说，你能指导我吗？"
D.Strings[31528]="测试，1…2…3！"
D.Strings[31529]="元素在眷顾你。你要向它们要求什么？"
D.Strings[31530]="元素变幻莫测，没有受过训练的双手很难控制它们。很抱歉，我并不需要你。"
D.Strings[31531]="哦……看上去很性感！"
D.Strings[31532]="能拥有如此众多忠诚而具有献身精神的学徒，这是我的幸运。如果没有这些测试样品，我的工作也不可能进行。"
D.Strings[31533]="大法师克希雷姆，你能为我打开一个前往你的高塔的传送门吗？"
D.Strings[31534]="我已经打开了通向我的休养之地的传送门。去休息一下吧。当我们的研究在早晨重新开始的时候，我需要你保持充沛的活力，机敏的小东西。"
D.Strings[31535]="他们已经接受了这次行动的酬金价格。我希望能够在这次行动中得到一笔丰厚的利润。他们最好不要再骗我们了。"
D.Strings[31536]="准备战斗，北伐军的弟兄们。维库人会用他们的生命保护冰霜女王。"
D.Strings[31537]="都给我严肃点！我们的勇士已经到了，我们要奋勇战斗，支援他们！"
D.Strings[31538]="卫兵！把这个$r用链子锁住！"
D.Strings[31539]="我宁愿死在这里，也不要为那个疯子芬克斯坦收集材料。"
D.Strings[31540]="%s变得更加不稳定了！"
D.Strings[31541]="不要打我！告诉匹克，我变好了。"
D.Strings[31542]="先是大火，现在又是$r！你死定了！"
D.Strings[31543]="朋友，你先去打他。我还没打他呢。"
D.Strings[31544]="我不想死在火里，朋友。"
D.Strings[31545]="%s几乎无法维持当前的形态！"
D.Strings[31546]="你问我们要干什么？我们在等待。"
D.Strings[31547]="真不知道那些灵魂为什么要如此排斥我们。"
D.Strings[31548]="孩子，别担心。格瑞克尼尔会帮助我们。"
D.Strings[31549]="格瑞克尼尔说他会和这个元素谈谈，让它帮助我们作战。"
D.Strings[31550]="我们很快就会占领这座山谷。"
D.Strings[31551]="那些灵魂痛恨我们。"
D.Strings[31552]="我们的世界是一片冰雪之地。"
D.Strings[31553]="但孩子，在那片大地之下，燃烧着永恒的烈火。"
D.Strings[31554]="来自于深渊彼方的灵魂正在同格瑞克尼尔交谈。"
D.Strings[31555]="我们得到命令，要再次进行冲锋。而迎击我们的是一片长矛组成的壁垒。我做不到，$c。我的武器滑出了双手，两条腿也无法动弹。$B$B我玷污了自己的荣誉。"
D.Strings[31556]="我的指挥官就在我的眼前被杀害了，兄弟们不断地在我身边倒下。我无法继续战斗下去。我没有能为他们报仇，$c，我让他们蒙受了羞耻。"
D.Strings[31557]="不要看我，$r，我让部落蒙羞，我彻底完蛋了。"
D.Strings[31558]="任何兽人都不应该像我一样逃离战场。别理我，让我单独咀嚼自己的耻辱吧。我不害怕死在这座塔里，却害怕知道我的祖先会如何看待我的懦弱。"
D.Strings[31559]="去工作，孩子们！"
D.Strings[31560]="不要着急，我们很快就能出去。"
D.Strings[31561]="我们要保持这股火继续燃烧，矮人们！"
D.Strings[31562]="乔恩在那里干什么？"
D.Strings[31563]="只有当你潜入雪层时，你的冰虫才能够移动，但潜入后你的冰虫无法攻击。浮出雪层的冰虫可以使用它强大的酸性攻击穿透钢铁巨像的护甲。要做好随时下潜的准备以躲避钢铁巨像最具毁灭性的攻击。"
D.Strings[31564]="我拿回了你的盔甲和武器。我们不胜即死！"
D.Strings[31565]="谢天谢地，你们终于来了，英雄们。奥格瑞姆之锤号已经离开了。赶快到破天号去！也许你们还能乘上那艘船。"
D.Strings[31566]="复仇……"
D.Strings[31567]="还没有哪支队伍能够把这么不利的局势扳回来！"
D.Strings[31568]="教练，让我重新开始比赛吧！"
D.Strings[31569]="这应该能管用！"
D.Strings[31570]="谢谢！从这里开始，我自己就能搞定了。"
D.Strings[31571]="你是大救星！为了铁炉堡！"
D.Strings[31572]="啊，这下好多了。我欠你一个人情。"
D.Strings[31573]="朝着热沙港大鲨鱼队的队员掷出你的足球炸弹！"
D.Strings[31574]="火箭背包不见了？看看在不在背包里。"
D.Strings[31575]="诅咒这个肮脏的笼子……"
D.Strings[31576]="啊，终于摆脱了牢笼……"
D.Strings[31577]="原谅我，英雄们。我应该听乌瑟尔的。我……我只是希望能够，能够看他最后一眼。对不起。"
D.Strings[31578]="我们知道该怎么做了。我会把这个消息带给瓦里安国王和弗丁大人。"
D.Strings[31579]="这……这是死路！我们别无选择，只能战斗。准备迎战，英雄们，这是我们最后的阵地。"
D.Strings[31580]="穷途末路……变成我的奴仆吧！"
D.Strings[31581]="真是非常感谢。你的到来帮了我们大忙。"
D.Strings[31582]="穆拉丁大人正在破天号上等着呢。我们会守住这里，等你起飞。"
D.Strings[31583]="前面有个出口，赶快！"
D.Strings[31584]="那些山丘和隐秘的小路就是我的家。许多年以来，我一直利用它们进行狩猎。$B$B但我从没有想过会利用它们进行一场战争。"
D.Strings[31585]="破天号的兄弟们，给我顶住！"
D.Strings[31586]="几年以前，恐怖图腾袭击了我的村庄。直至今日，痛苦、愤怒和失落仍然沉重地压在我的心上。$B$B现在，我自己却在安慰和帮助其他失去了自己村庄的人。"
D.Strings[31587]="那么，你打算钻进这条隧道……？"
D.Strings[31588]="我建议你去找安威玛尔，$n……而且要尽快去！我会向诺莫瑞根空军发出信号。"
D.Strings[31589]="借助这些隐秘的路径，我们能够对下面的敌人发动猛烈的进攻。$B$B游击战算不上是荣誉的行动，但一名优秀的战士明白该如何让他的敌人措手不及。"
D.Strings[31590]="寻找一个名叫米罗·齿针的家伙。看来我能在这件事上帮些忙。"
D.Strings[31591]="滚回去，你这个肮脏的怪物！"
D.Strings[31592]="来尝尝矮人的枪子儿吧！"
D.Strings[31593]="为了铁炉堡！"
D.Strings[31594]="你这个躲在洞里的怪物，吃我一记！$b$b啊……我能帮你做些什么，$n？"
D.Strings[31595]="$c，你想要什么？"
D.Strings[31596]="$n，那些巨魔可真奇怪。我不喜欢这样，一点也不喜欢。"
D.Strings[31597]="把他们引到这里来。我们会支援你。"
D.Strings[31598]="快！推进！"
D.Strings[31599]="她的援兵就要到了！我们必须迅速消灭她！"
D.Strings[31600]="我来挡住她。让我的兄弟回到坟墓中去，然后帮我消灭她！"
D.Strings[31601]="我会留下来，告诉提里奥我们的进展。你们必须继续前进，击败辛达苟萨。勇士们，Lok’tar！"
D.Strings[31602]="愚蠢的科罗克。你带来了我的援军。银色勇士们，用你们的死来效忠巫妖王吧！"
D.Strings[31603]="快，在那个瓦格里干掉我们之前！"
D.Strings[31604]="你也许曾和我并肩作战，科罗克，但现在你只不过是一个叛徒。接受你的第二次死亡吧！"
D.Strings[31605]="你就是我要找的$c！我正在测试一种新的火箭助推飞行器，我需要你的帮助！\n\n拿上一个控制器放到你的护甲里。按下侧面的按钮，砰，你就飞起来了。\n\n不过你别想把它私吞了。每个飞行器都装有推进器8000，并且和我手里这个相连接。如果你飞得太远，推进器就会关闭主引擎，你便无法起飞，除非回到我这里。\n\n我把那些责任书放哪了？"
D.Strings[31606]="没错，你最看重的是安全。给我个火箭背包。"
D.Strings[31607]="这是我们最后的阵地。今天的一切都将千古流传。无论是生是死，我们都是为了荣誉而战。我们都是为了自由和人民而战！"
D.Strings[31608]="记住，英雄们，在这邪恶之地，恐惧是你们最大的敌人。勇气将让你们的灵魂比千颗太阳还要明亮。敌人会在你们面前溃不成军。正义的光芒将彻底摧毁他们！"
D.Strings[31609]="现在，我们向冰冠堡垒进军！"
D.Strings[31610]="阿尔萨斯！我发誓会彻底消灭你和天灾军团！昔日的恩怨会在今天做个了断！"
D.Strings[31611]="弗丁，你本应是我最强大的战士，你的黑暗力量将清洗这个世界，开启一个新的世代。"
D.Strings[31612]="我为这个灵魂耗费了巨大的力量，让他承受了无数痛苦……他抵抗了那么长时间，但用不了多久就会屈服了。"
D.Strings[31613]="绝不！我……绝不……服从你。"
D.Strings[31614]="你们最终都要臣服于我。"
D.Strings[31615]="弗丁领主，这是真的？如果伯瓦尔还活着，也许联盟和部落之间还有和平的希望。我们必须冲到堡垒顶层，救出圣骑士！"
D.Strings[31616]="圣光在上，胜利属于我们！"
D.Strings[31617]="入侵者进入了主人的领地。拉响警报！"
D.Strings[31618]="嗯，低劣，就连在矿坑里作苦力都不配。享受最后的时刻吧。很快你们就会变成行尸走肉了。"
D.Strings[31619]="那头龙对卡亚罗山干了什么？！！！"
D.Strings[31620]="你们最后的记忆将填满痛苦。"
D.Strings[31621]="让破天号做好空袭城堡的准备！"
D.Strings[31622]="奴仆们，消灭那些闯入者！"
D.Strings[31623]="敌人的数量远远超过我们，我们与十字路口和杜隆塔尔的联系已经被切断。但一个兽人能打败十个联盟懦夫。$B$B我们要对他们迎头痛击，把他们像赶猪群一样轰走。"
D.Strings[31624]="英雄们，你们必须尽快在冰冠堡垒内部夺取一个立足点。我们在城墙上汇合！"
D.Strings[31625]="基洛克，我们是怎样失去荣耀岗哨的？"
D.Strings[31626]="联盟耍了一个极端狡诈的诡计，$n。联盟的军队从北方城堡出发，沿着黄金之路前进，在日暮时分向十字路口发动了进攻。到了深夜，他们又掉头南进，只留下空无一人的营地和依旧在燃烧的篝火。$B$B当黎明的第一缕曙光出现时，我们在荣耀岗哨的大军突然遭到了联盟的猛烈袭击。大批联盟士兵冲过隘口。我们许多最勇敢的战士都死在了他们的刀锋之下。"
D.Strings[31627]="好消息！各位！我修好了毒性软泥管道！"
D.Strings[31628]="把球踢起来，让它飞进对面的烟囱球门！"
D.Strings[31629]="那名圣骑士还活着？是真的吗，大领主？他居然还活着？"
D.Strings[31630]="这是在大灾变之前的事？"
D.Strings[31631]="那我们必须去救他！如果我们救出了伯瓦尔·弗塔根，就能平息联盟和部落无休止的纷争。"
D.Strings[31632]="任务已经明确：巫妖王将为他的罪行付出代价，我们一定要救出伯瓦尔·弗塔根公爵。"
D.Strings[31633]="库卡隆，为最后的冲锋做好准备！勇士们，炮船将在那座堡垒的顶部着陆。我们在那里汇合！"
D.Strings[31634]="圣光的力量没有止境，萨鲁法尔。他的灵魂饱受压抑，但他现在，还活着。"
D.Strings[31635]="是的，我们在隘口东边重新集结，准备发动反击。但在第二天，天空变成了赤红色，大地分裂成两块，就好象一块被小孩掰开的饼干。在地平线与地平线之间，一切都惨遭凌夷。$B$B刚刚建起防御碉堡的联盟军队也像我们一样惊恐异常，茫然不知所措。这本来是最佳的进攻时机！但督军加杜尔坚持要撤往南方，重组队伍。$B$B<基洛克向地面上啐了一口。>$B$B我们之中有许多人没有跟着他走。在上一场战争中，我曾经和恶魔正面交战，半步未退，$n。现在我也不打算掉头逃跑，让联盟占据我们的土地。"
D.Strings[31636]="你和你的人留下来继续作战。"
D.Strings[31637]="是的，我们继续作战。也许我们难免一死，但我们不会给他们半寸土地，$c。$B$B敌人的数量远远超过我们。我们的盔甲破碎，武器损坏。$B$B但这是我们的土地！我们的牛头人盟友熟悉这片山丘中的每一条小道、裂谷和每一个山口。我们埋伏在高地上，向联盟发动了出其不意的突袭，然后又像影子一样消失。恐惧就是我们的武器，我们要向敌人发动毫无止歇的攻击。"
D.Strings[31638]="哦，天哪。菲利克斯的情况并不乐观。"
D.Strings[31639]="再教教我该怎么踢致胜球，教练！"
D.Strings[31640]="吹个球，吹个“卟卟”会爆的大气球！"
D.Strings[31641]="|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s开始施放|cFFFF0000不稳定的软泥爆炸！|r"
D.Strings[31642]="可怜的生物！死吧！"
D.Strings[31643]="你认为我什么时候能离开？我还要回去工作呢。"
D.Strings[31644]="那些穴居人到底是从哪里来的？他们一直都住在地下吗？"
D.Strings[31645]="你最好能安下心来。在穴居人被消灭干净之前，铁枷不会让任何人出去。"
D.Strings[31646]="外面有什么新闻吗？我听说那些巨魔也在蠢蠢欲动。"
D.Strings[31647]="这里真是拥挤得令人窒闷。我在密闭空间里总是感到不自在。"
D.Strings[31648]="试想一下，在经历了灾变程度的大地震后，你最不想待的地方应该就是屋里了，不是吗？"
D.Strings[31649]="$n! 我听说你是铁枷的新$r奴隶。她要你做些什么？"
D.Strings[31650]="我觉得自己永远都要被关在这里了。已经到美酒节了吗？"
D.Strings[31651]="永远……差那么……一点儿……"
D.Strings[31652]="这是为了让我得到变质的蜘蛛毒液！"
D.Strings[31653]="你们这些傻瓜永远找不到一只像样的蝙蝠翅膀。"
D.Strings[31654]="不要……让芬克斯坦拿我……做药……"
D.Strings[31655]="天哪，这里全都是石头！"
D.Strings[31656]="我几乎放弃了希望。"
D.Strings[31657]="就像你看见的那样，我们清理了这片山岩中的敌人。我们损失了许多兄弟，但现在你能安全地通过这条曾经被穴居人占据的隧道了。$b$b不用谢！"
D.Strings[31658]="你好吗，$c？"
D.Strings[31659]="到黄昏时分，火舌已经照亮了天空。我失去了一切。一切。$B$B为什么他们要烧掉一家旅店？"
D.Strings[31660]="<克尔苏瓦避开你的眼睛。>$B$B我在战斗中逃了出来，但没有能及时放开所有被拴住的牲口。$B$B我没办法聚拢它们，结果它们全都逃进烟雾里去了……"
D.Strings[31661]="敲击"
D.Strings[31662]="联盟的英雄们，进攻！"
D.Strings[31663]="不！你这怪物！"
D.Strings[31664]="我别无选择。请原谅我，高贵的战士们……"
D.Strings[31665]="你只能靠自己冲过这个矿坑了。"
D.Strings[31666]="解救你遇到的所有联盟奴隶.我们需要他们的协助来对抗泰兰努斯。我会集结援军，并在矿坑对面与你汇合。"
D.Strings[31667]="嗯，废物，就连在矿坑里作苦力都不配。享受最后的时刻吧。很快你们就会变成行尸走肉了。"
D.Strings[31668]="火山岩！来看看这里的火山岩吧！"
D.Strings[31669]="出售火山岩！刚离开火山，还热气腾腾哪！你想要的，就在我这里！"
D.Strings[31670]="火山岩，最新低价！你一定会爱上我的岩石。"
D.Strings[31671]="来看看这里的火山岩吧！……对猫正合适！"
D.Strings[31672]="把大灾变的纪念带回家吧！出售火山岩——火热，火热，火热的火山岩！"
D.Strings[31673]="能做镇纸，能挡门，还能砸窗户！来看看，来看看！火山岩。"
D.Strings[31674]="火山岩。用法多多。"
D.Strings[31675]="绝不能让他们靠近冰霜女王。快，阻止他们！"
D.Strings[31676]="火山岩！限时供应！配有品质证书和一切相关手续！"
D.Strings[31677]="薇尼，我刚刚弄到了一个真正的大灾变纪念品！"
D.Strings[31678]="%s 准备释放一波严寒！"
D.Strings[31679]="绝望吧，体会主人那无穷无尽的力量吧！"
D.Strings[31680]="在牛头人语中，“乌纳菲”是避难所的意思。但这个名字已经不再合适了。从我们建起这座营地的时候开始，这片诡异的丛林就要将这座营地吞噬。"
D.Strings[31681]="当我们最强壮的战士进行狩猎的时候，他们对陶拉祖发动了进攻。我们遇到的也许是一个奇迹。在联盟的阵线中出现了一个缺口。所以我和另一些人才能带着这些小东西逃出来……$B$B<塔瓦妮的声音低沉了下去。他正努力不让自己在孩子们的面前哭出来。>"
D.Strings[31682]="放心，放心。没有事的，小家伙。"
D.Strings[31683]="睡吧，小家伙。我们很快就能找到你的爸爸妈妈。"
D.Strings[31684]="嗨，小猎人。我正要找你。"
D.Strings[31685]="<静电噪音>$b这东西连通了吗？喂？"
D.Strings[31686]="在援兵赶到前我会尽量拖延时间，但你必须继续前进。$B$B阿尔萨斯很快会发现我们在这里。"
D.Strings[31687]="啊，你在这里。你好！我想，既然你飞去了卡拉诺斯，我应该告诉你一下寒脊山谷外都发生了什么事。"
D.Strings[31688]="看样子，你们这些寒脊山人根本不知道过去几天发生了什么。"
D.Strings[31689]="如果你们以为寒脊山最大的问题是巨魔，那么就到卡拉诺斯去看看吧！这场大灾变让巨魔全都发了疯。"
D.Strings[31690]="野猪人的话我懂得不多，但我可不喜欢我听到的这些话。"
D.Strings[31691]="难民们是不是还聚集在乌纳菲营地？"
D.Strings[31692]="你是我们的救星！我不知道那些怪物想从我们这里抢走什么……"
D.Strings[31693]="这是什么？ <呼噜呼噜> <哼哼>那个$r来了？来挑战强大的刃鼻？"
D.Strings[31694]="我要给$r树立个榜样 <哼哼>！做好准备吧<呼噜>，软弱的家伙。"
D.Strings[31695]="你，<哼哼>你很强大<呼噜>。但……"
D.Strings[31696]="你能抵挡野猪启示录吗？"
D.Strings[31697]="你……没有被那些野猪干掉？<哼哼>那么多野猪！真让我难过！<呼噜>"
D.Strings[31698]="<喷鼻息>？<咯咯叫>！"
D.Strings[31699]="现在我必须干掉你。"
D.Strings[31700]="软弱的凡人……"
D.Strings[31701]="也许……你是对的，科罗克。"
D.Strings[31702]="你们的入侵结束了！无人可以生还！"
D.Strings[31703]="你能感受到死神之手的那股寒意吗？"
D.Strings[31704]="痛苦吧，凡人，你们可怜的魔法背叛了你们！"
D.Strings[31705]="终于……自由了……"
D.Strings[31706]="够了！我厌倦了这些游戏！"
D.Strings[31707]="哈哈！<哼哼>你要完蛋了！"
D.Strings[31708]="唉呦！我绝不再吃芦笋了。"
D.Strings[31709]="我对这片森林已经受够了！"
D.Strings[31710]="让……我……离开这里！"
D.Strings[31711]="我觉得这片丛林想要吃掉我！"
D.Strings[31712]="谢谢！我在那个家伙的触手里简直就象个破布娃娃。"
D.Strings[31713]="我记得以前的贫瘠之地是真的很……“贫瘠”。我们还是比较喜欢那个时候的贫瘠之地！"
D.Strings[31714]="这看上去像是萨洛瑞安·寻晨者的遗体，奎尔德拉最后的使用者。"
D.Strings[31715]="检查遗骸。"
D.Strings[31716]="救命。救命！"
D.Strings[31717]="喔……我要吐了！"
D.Strings[31718]="无论如何我们都要守住太阳之井。"
D.Strings[31719]="我命令你们撤退回太阳之井，在那里协助布置防线。"
D.Strings[31720]="我会守在这里，尽量为你们争取时间。记住，不要辜负我们的王子。"
D.Strings[31721]="能与你们携手保卫家园和人民，是我的荣幸。"
D.Strings[31722]="你……你，不是我的士兵。你愿意留下来和我共同抗敌吗？"
D.Strings[31723]="天灾的渣滓们，给我听着。只要我活着，你们就休想靠近太阳之井！"
D.Strings[31724]="你会同你的家园和城池一样遭受灭顶之灾。我的主人会在这里大获全胜，你的名字将被人们遗忘。"
D.Strings[31725]="一声尖叫直入云霄！"
D.Strings[31726]="什么？这就死了？这也不错。"
D.Strings[31727]="啊！我必须休息一下了。"
D.Strings[31728]="勇士们！我就要挡不住她了。"
D.Strings[31729]="我要亲手杀了你！"
D.Strings[31730]="他……太强大了。英雄们，快，快过来！我们必须马上离开！你们先走。我会尽全力挡住他。"
D.Strings[31731]="天杀的死路！看来真的无路可走了。准备战斗，英雄们，让我们放手一搏！"
D.Strings[31732]="我们暂时……安全了。他的力量已经十倍于往昔。只有一支大军才能战胜巫妖王。单凭部落的力量毫无胜算。"
D.Strings[31733]="你的盟友到了，吉安娜，你说的没错。全都变成效忠我的天灾战士吧。"
D.Strings[31734]="我不会再犯同样的错误，希尔瓦娜斯。这次你走不了了，你们死后都会成为我的奴仆！"
D.Strings[31735]="阴冷的死亡等待着你。"
D.Strings[31736]="屈服于死亡的严寒吧！"
D.Strings[31737]="死路一条！"
D.Strings[31738]="熔炉之主已经死了！抽刀亮剑，我们要干掉天灾领主。"
D.Strings[31739]="接受现实吧，$c。$b$b巫妖王的统治已经到了尽头。"
D.Strings[31740]="灰烬审判军是怎么一回事？"
D.Strings[31741]="灰烬审判军是由黑锋骑士团和银色北伐军中的精英工匠组成的一支队伍。他们的创造标志了一种团结，各支力量齐心协力同巫妖王及其爪牙展开最终的战斗。  $b$b正是通过灰烬审判军的努力，我们掌握了如何将源生萨隆邪铁为我们所用的方法。"
D.Strings[31742]="如何学习加工源生萨隆邪铁？"
D.Strings[31743]="$c，和炼金师菲肯斯坦谈谈。他会为你指明道路。$b$b表明你的忠诚，你就会知道他们的办法。"
D.Strings[31744]="凭借霜之哀伤，我能否击败巫妖王？"
D.Strings[31745]="蠢货！$c，你对那把诅咒之剑完全不了解？$b$b它会把你彻底吞噬，所剩下的皮囊会为敌人永远效力。$b$b阿尔萨斯的命运就是这样铸成的，艾泽拉斯无数的精英勇士为此而倒下。$b$b不过，可能还有…"
D.Strings[31746]="那么告诉我，大领主莫格莱尼，我们还能做些什么？"
D.Strings[31747]="我一直不断地思考这个问题。$b$b我相信可以造出一件能与霜之哀伤抗衡但却不会奴役其使用者的武器。$b$b算了，$r。即使有这个可能，也没有打造这样一件神器的时间了。$b$b你最好还是把精力专注在我们的这场战斗上吧。"
D.Strings[31748]="只要希望尚存，你就必须允许我试上一试！"
D.Strings[31749]="如果希望尚存，请允许我试上一试！"
D.Strings[31750]="也许，$c…只是也许。$b$b如果你想实现这一杰作，你必须遵循灰烬审判军锻炉之主的方式。$b$b融入他们，证明你的忠诚和奉献的决心。$b$b等你做到以后，我们再来讨论接下去的事。"
D.Strings[31751]="夺取中"
D.Strings[31752]="请告诉我更多有关这件神器的事，大领主莫格莱尼。"
D.Strings[31753]="也许，$c…只是也许。$b$b如果你想实现这一杰作，你必须遵循灰烬审判军熔炉之主的方式。$b$b融入他们，证明你的忠诚和奉献的决心。$b$b等你做到以后，我们再来讨论接下去的事。"
D.Strings[31754]="什么是暗影冰霜？"
D.Strings[31755]="首先，宝剑必须吞噬我们敌人奴仆的灵魂。在吸取它们的力量之前，宝剑还必须倾注暗影冰霜。这将使你不受堕落之音的侵害，否则你会被它吞噬…希望这可以起作用。"
D.Strings[31756]="巫妖王已经离我们很近了，$n。我感觉到了他声音中的嘲弄…$b$b去让他安静下来吧！"
D.Strings[31757]="我……我没有想过能生还。"
D.Strings[31758]="为什么会发生这种事？为什么你会来？"
D.Strings[31759]="这是奎尔德拉！你获得了它！"
D.Strings[31760]="我说不清楚，但这把剑已经认定你是它的新主人。请带上我的祝福，像我一样去血战天灾军团！"
D.Strings[31761]="很早以前，恶魔领主基尔加丹迫使萨满耐奥祖向他屈服，在受尽无尽折磨后，耐奥祖的灵魂被封禁在一块冰封的水晶之中。这是一个在扭曲虚空的深入打造的监牢，我们将它称为冰封王座。$b$b直到后来阿尔萨斯用霜之哀伤击碎了那块水晶，将耐奥祖的灵魂融入自身，便成了巫妖王。王座的碎裂产生了[shadowfrost]冰封碎片，这些碎片现在就散落在冰冠堡垒中。"
D.Strings[31762]="住手！你快把那剑放下！"
D.Strings[31763]="又一起电气煤炉燃床瓦斯意外火灾事故？"
D.Strings[31764]="你用上古之神的血，萨隆邪铁重铸了这把剑。巫妖王的力量会召唤它。"
D.Strings[31765]="只有一个办法能净化它。赶快到太阳之井去，将剑沉入井水之中。"
D.Strings[31766]="我抵抗不住霜之哀伤的召唤…"
D.Strings[31767]="为什么我必须取回圣光的复仇？"
D.Strings[31768]="阿尔萨斯在选择霜之哀伤时丢弃的战锤中蕴藏了极大的潜力。$b$b那股力量曾引发过奠定世界命运的事件。它拥有的强大力量很少有人能够领悟。$b$b给我足够的萨隆邪铁，我能将这把战锤打造成一件可以对抗霜之哀伤的神器。$b$b那时，你便开始了一项最危险的试炼…"
D.Strings[31769]="我十分渴望启动我们的工作，大领主莫格莱尼！"
D.Strings[31770]="收起你的激情吧，$r。$b$b你正在进行一项徒劳的任务，并且这任务很可能会毁了你。那些使我们最高贵的同伴变得堕落的力量会向你无情地袭来。$b$b相信这一切吧；屈服吧，我将不得不把你逐出这个世界。"
D.Strings[31771]="%s准备攻击！"
D.Strings[31772]="立刻上船！快！这面山壁随时都可能塌陷。"
D.Strings[31773]="守住山丘！"
D.Strings[31774]="成功！这座山丘是你的了！"
D.Strings[31775]="失败了！防御部队无法守住那座山丘。"
D.Strings[31776]="恐怖图腾绝不投降！"
D.Strings[31777]="看这些小东西，你给加弗斯特带来了好吃的！"
D.Strings[31778]="可以留下来当个小点心。"
D.Strings[31779]="这个好像不……不太好吃。加弗斯特真笨！真笨！"
D.Strings[31780]="加弗斯特不想弄的太狼狈。不想给头领丢脸。晚了。"
D.Strings[31781]="我们的工作绝不能被干扰！伊克，招呼他们！"
D.Strings[31782]="这些部件也许对我们有用。"
D.Strings[31783]="我们正缺胳膊和腿呢！感谢你们的大力援助！"
D.Strings[31784]="我改主意了，现在我要的是这个！"
D.Strings[31785]="你打这个家伙干什么？真正危险的人在那儿，傻子！"
D.Strings[31786]="嗨！我来自皇冠药剂公司。$B$B你在寻找礼物吗？还是要找份工作？想不想送自己点东西？好吧，你来对地方了，朋友。$B$B如果我没有你想要的东西，那么在我旁边的福星基维或是可爱的商贩一定会有。"
D.Strings[31787]="好的，莎希，我已经准备好出发了。"
D.Strings[31788]="我们要利用那些补给为所有人做好战斗的准备。$B$B继续吧。我们会再见面的。"
D.Strings[31789]="我会集结其它的奴隶，被让他们做好战斗的准备。在你同天灾领主泰兰努斯开始交战前我们会赶上你的。"
D.Strings[31790]="我曾经在陶拉祖营地安全的环境中训练年轻的猎人熟悉荒野之道。$B$B现在我们不能奢望再有那种条件了。敌人已经踏过了我们的门槛，我们的年轻人必须在与敌人的激烈搏杀中学会战斗的技巧。"
D.Strings[31791]="英雄们！我们就算拼了性命，也会挡住那些亡灵。去消灭天灾领主吧！"
D.Strings[31792]="唉，勇敢的冒险者，你们的路已经到头了。难道你们没有听到身后隧道里钢铁撞击的声音吗？那就是末日降临的乐章。"
D.Strings[31793]="哈，一群不自量力的乌合之众。等我杀了你们之后，主人的剑就能尽情享用你们的灵魂了。去死吧。"
D.Strings[31794]="英雄们，我们会追随你们的领导。今夕就是天灾领主的死期。"
D.Strings[31795]="将一把谷粒撒向风中。"
D.Strings[31796]="这是真的？就连那些身陷诅咒的人也在和被遗忘者作战！"
D.Strings[31797]="被遗忘者将要为他们所犯的罪行付出代价！"
D.Strings[31798]="怎么回事儿？听说你要搞个聚会，却没有邀请我！"
D.Strings[31799]="你们这帮懒鬼！赶快回去工作，特别是你，$n！"
D.Strings[31800]="如果鲨鱼队击败了海盗队，所有人都要降职！"
D.Strings[31801]="又是你，$n？你跑到总部外面来干什么？还不赶快回去给我工作！"
D.Strings[31802]="所有人为我——艾泽拉斯最伟大的贸易大王——欢呼！"
D.Strings[31803]="感谢你的努力工作和无私奉献。没有报酬的加班对所有人都应该是最合适的安排！"
D.Strings[31804]="喝点卡亚可乐吧！"
D.Strings[31805]="我开始为提拔你而感到后悔了，$n！"
D.Strings[31806]="终于，开始了……"
D.Strings[31807]="看啊！神圣与堕落的结合，那就是影锋，一把潜能无限的武器。"
D.Strings[31808]="让它服从你，你就能获得无法想象的力量！"
D.Strings[31809]="如果失败，你的灵魂就将永远被奴役。"
D.Strings[31810]="凡人，这是给你们的最后警告；如果你们失败了，我会亲手毁了你们！"
D.Strings[31811]="工作再努力些，你们这帮垃圾！矿石可不会自己蹦出来！"
D.Strings[31812]="你能活着是你的运气，吉尔尼斯败狗！现在去工作吧，不要等我们改变主意！"
D.Strings[31813]="这座矿藏和这里的一切都是希尔瓦娜斯女王的财产，也包括你们这些蛆虫。所以，赶快回去工作！"
D.Strings[31814]="抓紧了！我要把油门踩到底了！"
D.Strings[31815]="我们必须试试看。"
D.Strings[31816]="别挡路！"
D.Strings[31817]="我们来了，一切平安……哦，不！我们被骗了！"
D.Strings[31818]="%s向$n施放|cFF00AACC深度冻结|r。"
D.Strings[31819]="十分感谢，英雄们。我会一直呆在这，将你们施放的奴隶集结起来。如果你们能杀死东北方的熔炉之主，我们便可以把自己武装起来。"
D.Strings[31820]="我以为我会死在这坑里。谢谢你！"
D.Strings[31821]="我欠你一顿好酒，我的朋友。"
D.Strings[31822]="收下我的礼物吧。"
D.Strings[31823]="不要放走任何一个。"
D.Strings[31824]="拜托了，为我们向天灾领主报仇。"
D.Strings[31825]="在你打败矿坑的头目以后，替我向他的尸体吐口水，好吗？"
D.Strings[31826]="我感觉我的手臂已经没了，不过只要我找到些武器，我就会和你并肩作战。"
D.Strings[31827]="在这个被遗忘的区域，我迷失在了时间的长河中。能见到你真不错，我的朋友。"
D.Strings[31828]="你的出现是美妙的一幕…对此你可能还并不能理解。"
D.Strings[31829]="我们在这个大坑里损失太多人了。太多太多了。"
D.Strings[31830]="很高兴你来了。我本来撑不了那么久的。"
D.Strings[31831]="让我先喘口气，一会儿我会赶上你们的，英雄们。谢谢你们。"
D.Strings[31832]="报仇的时刻到了。"
D.Strings[31833]="来个男人强有力的拥抱吧。"
D.Strings[31834]="我真想吻你！"
D.Strings[31835]="总有一天我会想办法报答你的，我的英雄。"
D.Strings[31836]="我简直无法相信自己的眼睛。谢谢你。真的，谢谢你。"
D.Strings[31837]="%s点头表示感谢。"
D.Strings[31838]="%s露出了感激的笑容。"
D.Strings[31839]="%s跌跌撞撞向你走来时几乎要倒下去了。"
D.Strings[31840]="%s对自己的命运发出了短短的一声苦笑。"
D.Strings[31841]="%s举起空着的手向你做了个敬酒的姿势。"
D.Strings[31842]="%s给了你一个飞吻。"
D.Strings[31843]="%s闭上了眼睛，细细品味了一下自由的味道。"
D.Strings[31844]="%s每挥出一锄时都完全任由矿工锄拖在地上，明显体力不支。"
D.Strings[31845]="英雄，我与你同在。"
D.Strings[31846]="为了报答你，我愿付出任何代价。"
D.Strings[31847]="我会同你并肩作战。对他们绝不留情。"
D.Strings[31848]="我要回去帮助解救其它奴隶。再次感谢你，英雄。"
D.Strings[31849]="我要回到采石场前线去。帮我多杀几个。"
D.Strings[31850]="贫瘠之地现在也许是干枯荒凉的，但这片土地曾经生机勃勃。我们在这里漫游、狩猎，过着丰足的生活。$B$B然后，联盟来了……他们烧杀抢掠。被他们蹂躏过的地方，现在被我们称为鲜血旷野，$c。$B$B那里的居民已经全部流亡到其它地方。留下来的只有继续与敌人苦战的士兵。"
D.Strings[31851]="大门的守卫者们已经做好了准备，$n。你呢？"
D.Strings[31852]="谢谢你，$n！只要贝恩和我们的部落盟友同心协力，我们就能将入侵者赶回到他们盘踞的沼泽里面去。"
D.Strings[31853]="占位符！锵锵!"
D.Strings[31854]="我准备好了。派我去大门吧！"
D.Strings[31855]="粘性炸弹"
D.Strings[31856]="食尸鬼们，杀掉这个可怜的高等精灵！"
D.Strings[31857]="你们都会被天灾军团的力量击垮。地穴劫掠者，进攻！"
D.Strings[31858]="这是一道紧急撤离传送门。"
D.Strings[31859]="带我离开这座城市。"
D.Strings[31860]="$n，请过来一下。我需要你的帮助。"
D.Strings[31861]="保持戒备！天气越来越糟，元素生物就快追来了！找掩护！"
D.Strings[31862]="清理街道！天色开始阴沉，元素生物很快就要发动袭击了。保持警惕！"
D.Strings[31863]="疾病已经被治愈，你感到再次恢复正常！"
D.Strings[31864]="快点。士兵们已经出发了。"
D.Strings[31865]="寻找一切可以做掩护的东西。"
D.Strings[31866]="我们还没有将这家旅店里的敌人清除干净？完成这个任务之后就把它一把火烧掉！"
D.Strings[31867]="这帮家伙身上只有些破珠子和硬皮。财宝到底在哪里？"
D.Strings[31868]="我们在浪费时间。这个地方必须在他们发动反攻之前清理干净。"
D.Strings[31869]="嗨，有人搜过信箱了没？"
D.Strings[31870]="还应该有更多的东西。再把他们搜查一遍！"
D.Strings[31871]="打开你们超酷派对套装，穿戴上你们的清爽遮阳镜、潮人装束和亮闪闪的珠宝!"
D.Strings[31872]="有人见到那些被关在笼子里的野猪人吗？"
D.Strings[31873]="去试试吧，老板！"
D.Strings[31874]="当战斗开始时，我跑去叫醒了其他人。他们逃出来了么？我只能用一把剥皮小刀和那些凶恶的士兵对抗……"
D.Strings[31875]="勇士们，你们救了我们，还我们自由……这种大恩大德我们无以为报。但我发誓，从今往后所有人都会知道你们的事迹，知道你们如何在这座黑暗的城堡中劈开一条光明之路。"
D.Strings[31876]="今天我们不仅见证了你们的勇猛，还见证了联盟和部落抛开仇怨，精诚团结的力量。有了这种力量，即使是巫妖王也会败倒在你们脚下。"
D.Strings[31877]="现在，我能感觉到全部生命的拥抱，大地母亲永恒的平静。谢谢你。"
D.Strings[31878]="联盟已经包围了这座营地！他们到这里来干什么？为什么他们要攻击陶拉祖？赶快带孩子们逃走，快！快！"
D.Strings[31879]="不，和其他人待在一起。护送他们向北离开战场。我会和双足飞龙留在这里掩护你们。快走！"
D.Strings[31880]="……等等，结束了？"
D.Strings[31881]="我有个好点子：可挤压的石头！"
D.Strings[31882]="绳索……还有已经套在上面的宠物。"
D.Strings[31883]="有腿洞的衬衫。翻领衬衫短裤！"
D.Strings[31884]="牛头人圣骑士！"
D.Strings[31885]="巧克力香草！"
D.Strings[31886]="自动酱油壶，配有激光除垢器。"
D.Strings[31887]="穿在脑袋上的鞋子！"
D.Strings[31888]="这个怎么样：速食开水！你只需要往里边加……哦。"
D.Strings[31889]="我有了个能拍成电影的创意。三个侏儒找到了一个魔力手镯……"
D.Strings[31890]="就像蹦极跳一样，懂吗？只是没有拴上绳子，明白吗？而且你是从地面开始的。我觉得它更像是普通的跳跃，不过你是被大炮轰上去的。"
D.Strings[31891]="可食用的火箭燃料！"
D.Strings[31892]="便携式汽油泵枪！"
D.Strings[31893]="半人……半鲨鳄！"
D.Strings[31894]="十三面骰子！"
D.Strings[31895]="有鳃的地精！"
D.Strings[31896]="将两辆车组合成一辆更大的车，然后让乘客从一辆车跳到另一辆车上！"
D.Strings[31897]="利用电线把信息传送到远方……不，这个发明不现实。还是造巨型火箭，把说话的人绑在上边……"
D.Strings[31898]="喂猪吃橡胶，直到它们能弹起来。这肯定有应用价值。"
D.Strings[31899]="谋杀许可证!"
D.Strings[31900]="内置拍手器的手套，不需动手就能鼓掌。"
D.Strings[31901]="医疗改革!"
D.Strings[31902]="投石车冰激淋快送。"
D.Strings[31903]="微笑猴子皮夹如何？"
D.Strings[31904]="星·际·矮·人！"
D.Strings[31905]="一只用弹簧带动的活塞，上面绑着刀刃，用来处理食物。或者是一些和你意见不一的人。"
D.Strings[31906]="带有喷水花洒的浴袍。"
D.Strings[31907]="小丑，除了让你发笑之外，你还可以暴打他们。"
D.Strings[31908]="模拟鼻子。用来闻不同房间里的气味。"
D.Strings[31909]="隐形触发器！我们会让它们遍布这里的每一个角落。它们就能控制一切了！"
D.Strings[31910]="组建个犯罪公司如何？"
D.Strings[31911]="我们把整个小镇……放进了一个胶囊里！"
D.Strings[31912]="明白吗？这可是一场盛会。你在这里可以看到我们全部的发明。我们称它为地精嘉年华。而且我们在这场盛会中还会派送特别宠物！只是大多数人可能会把那些宠物在拍卖行里卖掉。"
D.Strings[31913]="这是一个二进制系统。它只使用两个数字。6和11。"
D.Strings[31914]="巨型侏儒。不，等等……是小巨人！"
D.Strings[31915]="隐形调味品。永远不影响你的食物的美妙外观。"
D.Strings[31916]="带轮子的鞋子。还有带轮子的手套——专为你跌倒时设计。"
D.Strings[31917]="绳子上的肥皂！特别限定版的锁链肥皂和钢缆肥皂已经上架！多种附加选择，多种额外功能。"
D.Strings[31918]="可食用的床。这样你就能在床上吃早餐了。床……为早餐而设计！"
D.Strings[31919]="一个球，能够在球面上显示出这颗行星的……内部构造……这样你就知道能在哪里进行挖掘了！"
D.Strings[31920]="专为水平移动设计的……楼梯！"
D.Strings[31921]="嘿，伙计，我不认识你，也不知道你为什么要一直跟着我，但我马上就要上船了，并且我想自己一个人呆着，明白吗？"
D.Strings[31922]="斯内维尔，我这有一只火箭，上面有你的标记。"
D.Strings[31923]="%s施放了|cFFFFFF00灵魂倒映!|r"
D.Strings[31924]="干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务会在目的地等着你。"
D.Strings[31925]="感谢圣光，你安然无恙！为了消灭巫妖王和天灾军团，我们还有很多事要做。"
D.Strings[31926]="银色北伐军和黑锋骑士团的盟军已经打破冰冠堡垒的大门，他们正努力在城堡中建造一个前哨站。"
D.Strings[31927]="我们在这些厅堂中的发现将决定他们的成败。虽然任务危险重重，但我们必须坚持！"
D.Strings[31928]="当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找有用的重要情报，从而一劳永逸地铲除天灾军团。"
D.Strings[31929]="瓦里安国王的军情七处得到情报，巫妖王的私人密室就深藏在一个被称作映像大厅的地方。"
D.Strings[31930]="我们要想办法杀出一条通往映像大厅的血路。我感到那里潜藏着强大的魔法。那将是摧毁天灾军团的关键！"
D.Strings[31931]="你的首个任务是摧毁灵魂引擎中的死亡机器，为我们的士兵杀出一条路来。"
D.Strings[31932]="赶快，勇士们！我会让部队紧跟在你们身后。"
D.Strings[31933]="拾起"
D.Strings[31934]="银色北伐军和黑锋骑士团已经攻入冰冠城堡大门，正准备向天灾军团发动总攻。我们的任务虽小，但同样重要。"
D.Strings[31935]="当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找能帮助我们的重要情报，彻底除掉巫妖王。"
D.Strings[31936]="我们的侦察兵说巫妖王在冰封王座外有个私人密室，深藏在被称作映像大厅的地方。那就是我们的目标，勇士们。"
D.Strings[31937]="我们会一路杀进这个被诅咒的地方，找到进入映像大厅的入口。那里一定隐藏着某些极具价值的情报。"
D.Strings[31938]="黑暗女王正在看着你，加紧行动！"
D.Strings[31939]="干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务在目的地等着你。"
D.Strings[31940]="就这样吧。感谢你，$n，帮助我们将奎尔德拉归还给它真正的拥有者。"
D.Strings[31941]="这场背叛究竟意味着什么？"
D.Strings[31942]="放下武器投降，叛徒。"
D.Strings[31943]="我们的勇士在激活这台天灾传送器的战斗中付出了沉重的代价。我们必须时刻准备着延续他们的光辉。伙伴们，跟我来！"
D.Strings[31944]="部落的战士们，进攻！"
D.Strings[31945]="可怜的家伙。"
D.Strings[31946]="你只能靠自己冲过这个肮脏的地方了。"
D.Strings[31947]="解救你遇到的所有部落奴隶。我们需要他们的协助来对抗泰兰努斯。我会集结援军，并在矿坑对面与你汇合。"
D.Strings[31948]="在援兵赶到前我会尽量拖延时间，但你必须继续前进。阿尔萨斯很快会发现我们在这里。"
D.Strings[31949]="该死的被遗忘者！他们要为他们所做的一切付出代价！"
D.Strings[31950]="这是我们的土地——如果不打败我们，就别想夺走它！"
D.Strings[31951]="我们不会作为奴隶而死……我们是吉尔尼斯人！"
D.Strings[31952]="全新的卡亚可乐！喝下一口，灵感翻倍！"
D.Strings[31953]="卡亚可乐尝味大挑战！"
D.Strings[31954]="卡亚可乐！灵感之源！"
D.Strings[31955]="卡亚可乐！阿尔伯特·牛盾说过，有卡亚，有我在！"
D.Strings[31956]="卡亚可乐——锈水海盗队荣誉赞助品牌！"
D.Strings[31957]="卡亚可乐！喝上一口，你的工艺技巧就无人可比！"
D.Strings[31958]="品尝全新的卡亚可乐，享受全新的智慧生活！"
D.Strings[31959]="丧尸人抢了克洛斯的旗帜！丧尸人要被打成碎片了！！！"
D.Strings[31960]="正是时候，$n。被遗忘者来了。"
D.Strings[31961]="到此为止了，被遗忘者渣滓！以格雷迈恩家族战旗起誓，我要把你们驱逐出这片先祖之地！"
D.Strings[31962]="没用的杂种。拿这块被你们叫做旗子的破布擦地板再合适不过了。"
D.Strings[31963]="仿真食物！把真正的食物碾碎，然后压制成各种食物的形状。还添加了足以以假乱真的香料！"
D.Strings[31964]="老妈探测器。"
D.Strings[31965]="用泥土做的房子！如果你把它们清扫干净……它们就不存在了。"
D.Strings[31966]="循环回收利用！但只回收从未使用用过的全新物品。"
D.Strings[31967]="“吸引力诱发”，我不确定这有什么用，不过我最好先把这个名字注册一个商标。"
D.Strings[31968]="勺子打磨器！"
D.Strings[31969]="只有单面的纸！"
D.Strings[31970]="面包圈！"
D.Strings[31971]="防水肥皂！可供水底使用！"
D.Strings[31972]="手持单向镜子！"
D.Strings[31973]="适合老鼠体形的捕熊器……不……适合熊体形的捕鼠器！！"
D.Strings[31974]="上下双面艇！永不倾覆！"
D.Strings[31975]="爆炸式灭火器！我们用火来灭火！"
D.Strings[31976]="链式足球炸弹！"
D.Strings[31977]="可以用脸滚键盘玩的游戏！"
D.Strings[31978]="没线的风筝！"
D.Strings[31979]="耳垢，这一定会有点什么用处的。"
D.Strings[31980]="这并不是我做的，罗曼斯。我没有背叛任何人。"
D.Strings[31981]="叫你的人停手。洛瑟玛·塞隆受伤只能怪他自己愚蠢。没人能驾驭奎尔德拉；它只听从自己认定的主人。"
D.Strings[31982]="卫兵，回到你们的岗位。"
D.Strings[31983]="看起来队长说的是对的。我们完全无法驾驭奎尔德拉。"
D.Strings[31984]="你会得到你想要的，$n。带着这把剑走吧。至于你，乌瑞克，在圣地要注意你讲话的方式。"
D.Strings[31985]="圣光万岁，传送器工作了！"
D.Strings[31986]="这个寒冷的地方让我的骨髓都凝固了。"
D.Strings[31987]="我几乎能感觉到巫妖王的目光。"
D.Strings[31988]="%s向你用力投出一大块萨隆邪铁巨石！"
D.Strings[31989]="我的摄政王！他们都对你做了些什么？"
D.Strings[31990]="$n，带着剑穿过那道传送门返回达拉然。你完成了众多奎尔多雷人许多年来梦寐以求的伟业。终于夺回了奎尔德拉。"
D.Strings[31991]="那真的会是奎尔德拉吗？"
D.Strings[31992]="有人闯进了主人的房间！"
D.Strings[31993]="洛瑟玛，看那。的确是奎尔德拉。"
D.Strings[31994]="那是一场激烈的战斗，$n！集结部队、重整旗鼓。谁知道在那道门后面等待我们的是什么？$B$B准备好以后告诉我，我们准备向上游攻打敌人的堡垒。"
D.Strings[31995]="我们准备好了，穆拉丁。"
D.Strings[31996]="你能肯定吗，$g 伙计:小姑娘;？再给你一两分钟？"
D.Strings[31997]="确信无疑。出发吧！"
D.Strings[31998]="这的确是奎尔德拉。传说中萨洛瑞安·寻晨者的宝剑又回到我们的手里了，我从没想过我会活着见到这一天。"
D.Strings[31999]="你是辛多雷的英雄，你鼓舞着我们，$n，在面对悲剧和背叛时一种坚韧的象征。"
D.Strings[32000]="摄政者说的对，$n。萨洛瑞安的牺牲无法阻止太阳之井的覆灭。"
D.Strings[32001]="当你找到那把剑时，那把剑已经是残破不堪、无人问津了，更像是被凯尔萨斯出卖了的银月城。"
D.Strings[32002]="让奎尔德拉成为我们永不言弃的标志，面对敌人我们将不再心存恐惧。"
D.Strings[32003]="不仅辛多雷的人十分看重奎尔德拉。它在银月城所有孩子们的心中都占据着一定的位置。"
D.Strings[32004]="出于某种原因，这把剑重新回到了我们手里，我的主人。现在，是紧随奎尔德拉持有者重整旗鼓的时候了，为银月城和太阳之井的毁灭报仇。"
D.Strings[32005]="拿回那把剑，$n，带着他穿过传送门前往达拉然。大法师艾萨斯·夺日者正等待着为你喝彩。"
D.Strings[32006]="那我们要行动了，我们要……"
D.Strings[32007]="你每消灭一名部落士兵，或是杀死一只联盟狗。巫妖王的军力就会增长一分。瓦格里正在把你们的阵亡者变为天灾战士。"
D.Strings[32008]="你们就要大祸临头了。来吧，尝尝巫妖王赐予我的力量吧！"
D.Strings[32009]="区区一个兽人竟然想与联盟对抗？？？"
D.Strings[32010]="冲锋！！！"
D.Strings[32011]="欢迎来到凄凉要塞，$c。我们在此等待时机，向联盟还以颜色。"
D.Strings[32012]="快一点， $c。酋长亲自派我来评估我们在贫瘠之地的工作进展，然而我却在这里看到我们的城镇燃起大火，联盟败狗肆无忌惮地发狂。"
D.Strings[32013]="你很有潜力，$n。要想重获对贫瘠之地的控制权，就绝对少不了像你这样的精兵。"
D.Strings[32014]="我第一眼看到它，就知道这是一把龙铸之刃。"
D.Strings[32015]="怎么可能？难道真的……？"
D.Strings[32016]="$n，你是否准备好了作为我的先锋赶赴凄凉要塞？$B$B加杜尔也许想要从你面前蒙混过去。要让他知道，他的审判已经到了。"
D.Strings[32017]="我准备好了，督军！"
D.Strings[32018]="这把剑的形制和铭文表明它是一把龙铸之刃。终于，答案找到了。"
D.Strings[32019]="过了这么多年，难道它真的……"
D.Strings[32020]="矮人……"
D.Strings[32021]="我代表血柄督军前来通知你，他很快就到。"
D.Strings[32022]="血柄督军？加尔鲁什的狗腿子？$B$B正如你看到的，这儿不需要他——啊，告诉他这里的一切状况都在我的掌握之中。"
D.Strings[32023]="我一定会告诉那些陶拉祖难民的。告诉那些活下来的。"
D.Strings[32024]="但是，啊，目前的供给非常紧张。而且，呃，我这里的人力也很短缺。告诉血柄，啊-"
D.Strings[32025]="你亲口告诉他吧。他就快到了！"
D.Strings[32026]="我……终于……解脱了……"
D.Strings[32027]="冰霜女王飞走了。我们……我们必须继续前进——目标就在眼前。"
D.Strings[32028]="英雄们，到我这来！"
D.Strings[32029]="我……我救不了他们……该死，阿尔萨斯！你这恶魔！"
D.Strings[32030]="不要再耽搁了，他——啊——他就快到了！$B$B到最北边塔的塔顶找我"
D.Strings[32031]="谢谢你，$n。我相信你一定会，啊，维护我的权力。"
D.Strings[32032]="你需要什么，$c？暴风城已经被元素团团包围了！我们已经护送撤离了大部分市民，我们的卫兵正在奋力将元素阻绝在城门之外。$b$b你最好自己找个安全的地方待着。我们没工夫一边守城一边还要替你担心。"
D.Strings[32033]="奎尔德拉。"
D.Strings[32034]="巨龙铸造出奎尔塞拉，送给了卡多雷；而将奎尔德拉，送给了我们。"
D.Strings[32035]="国王将它赠予了我的朋友，萨洛瑞安·寻晨者。"
D.Strings[32036]="但即使是萨洛瑞安的力量和奎尔德拉的魔力也无法从天灾手中拯救银月城。"
D.Strings[32037]="为掩护族人逃生，萨洛瑞安在太阳之井的大门前壮烈牺牲。"
D.Strings[32038]="我曾经发过誓，再没有任何东西能让我重新拿起这把剑了。$B$B我是个傻瓜。"
D.Strings[32039]="战后，我从战场上找回这把剑，为了我的王子，为了替我的族人复仇，我把它带到了诺森德。"
D.Strings[32040]="阿尔萨斯粉碎了我们，将我们最强大的战士变成他的爪牙，萨莱因。"
D.Strings[32041]="对萨洛瑞安的回忆已和他的剑一样冰冷。"
D.Strings[32042]="是我将奎尔德拉带来，交给它的铸造者，只为打碎这把武器，消除它的力量。"
D.Strings[32043]="奎尔德拉只能有一个主人！"
D.Strings[32044]="原来你躲在这儿了，加杜尔。"
D.Strings[32045]="你这个只会躲在墙后的懦夫！要不是有$n在，联盟早就杀进莫高雷了。"
D.Strings[32046]="你的借口令我恶心！你的指挥权被解除了。"
D.Strings[32047]="噢！你还有点儿骨气！"
D.Strings[32048]="躲？听着血柄——我已经，啊，加强了对贫瘠之地的控制。"
D.Strings[32049]="但他们，呃，他们得到了援军！东部王国来的援军。然而我的部队却，呃，被包围了-"
D.Strings[32050]="解除指挥权？除非从我的尸体上碾过去！"
D.Strings[32051]="这就是萨鲁法尔的儿子——部落在天谴之门的指挥官。真是个悲剧……"
D.Strings[32052]="远处那里……那里是什么！"
D.Strings[32053]="士兵们，集合！看样子部落马上又要射击了！"
D.Strings[32054]="不出所料……"
D.Strings[32055]="你真以为能轻易地完成莫格莱尼的任务？"
D.Strings[32056]="你们会和他父亲一样饱受折磨……"
D.Strings[32057]="永不得安息！"
D.Strings[32058]="死吧，蠢货。"
D.Strings[32059]="你们这些蠢货胆敢闯入这里。诺森德的冰风将卷走你们的灵魂！"
D.Strings[32060]="这次我成功了！"
D.Strings[32061]="%s临死前的哀号响彻云霄。"
D.Strings[32062]="见证逐日者夺回奎尔德拉是我们的使命。"
D.Strings[32063]="等等，啊……等等！我认输，我认输！"
D.Strings[32064]="认输？你……认输？"
D.Strings[32065]="非胜即死，你还有什么不明白的？赶紧给我从这里消失吧！"
D.Strings[32066]="我发誓，银色盟约终将迎来奎尔德拉的回归。"
D.Strings[32067]="就是这里。我能感觉到这就是发生那场大悲剧的地方。痛苦的嚎叫仿佛仍然在这里回荡。毫无疑问，这就是那些异界的恐怖曾经肆虐横行的地方。$B$B为了能彻底将那些异界怪物入侵这个世界的道路封死，我必须先将它完全打开。那时，我需要你的力量来挡住可能从其中出来的一切东西。$B$B你准备好了吗？"
D.Strings[32068]="准备好了，纳拉雷克斯。"
D.Strings[32069]="加尔鲁什的部落不会容忍失败。"
D.Strings[32070]="到下面去找我，我们会认真谈一谈即将到来的反击。"
D.Strings[32071]="别逼我，兽人。我不能让你过去。"
D.Strings[32072]="躺在那里的是我唯一的儿子。无论什么也不能把我和他分离。"
D.Strings[32073]="我，我不能这样做。回到船上去，我就饶你一命。"
D.Strings[32074]="退后，穆拉丁，让这位伤心的父亲过去。"
D.Strings[32075]="我不会忘记您的……仁慈。感谢您，殿下。"
D.Strings[32076]="我……那时不在天谴之门。但活下来的士兵告诉了我当时的情况。你的儿子为荣耀而战，他英勇地战死，应该得到英雄般的厚葬。"
D.Strings[32077]="你在与天灾的战争中立下了大功。愿圣光给你恩泽。"
D.Strings[32078]="战斗难免牺牲，而我们的战友无论生死，都会效忠银色北伐军。"
D.Strings[32079]="拯救这个邪恶之地非你莫属，谢谢你。"
D.Strings[32080]="小心前面潜伏的危险……就是死也要留个全尸。"
D.Strings[32081]="火箭背包启动！"
D.Strings[32082]="火箭背包已关闭。移至扎福德·波姆布克斯旁边以重新启动。"
D.Strings[32083]="你在希拉斯的动物园里将成为一件精彩的展品，鲁博斯。"
D.Strings[32084]="躲到我后面来！快！"
D.Strings[32085]="我以为他永远都闭不上嘴。但辛达苟萨让这个呱噪的家伙安静下来了。勇士们，向映像大厅前进！我能感觉到……目标已近。"
D.Strings[32086]="吉安娜，你怎么哭了？"
D.Strings[32087]="%s擦干眼泪，朝着瓦里安·乌瑞恩国王笑了笑。"
D.Strings[32088]="穆拉丁，守住甲板，组织士兵向城堡上层发动进攻。我会带另一支暴风城部队过去。"
D.Strings[32089]="没什么，陛下……我只是，为国王而自豪。"
D.Strings[32090]="这就去，陛下！"
D.Strings[32091]="我们没有时间可以浪费了，$c。为什么你在这停了下来？"
D.Strings[32092]="有什么我能效劳的，女妖之王？"
D.Strings[32093]="我们时间不多了，英雄。你需要些什么？"
D.Strings[32094]="有什么我能效劳的，我的女士？"
D.Strings[32095]="魔导师哈瑟尔说你会借我一件战袍。"
D.Strings[32096]="<他看了看火箭，咧开嘴紧张地笑了笑。>$b$b好吧，我是给别人做了些火箭。那又怎么样？价格不错，我也得到了酬劳。这不是出不出人命的问题。工作就要实事求是。这跟你有关系吗？"
D.Strings[32097]="听着，我不知道，可以吗？我不知道！$b$b我只是拿钱做了一些火箭，用来空运那些化学品，这就是我是任务。我的任务结束了，朋友。火箭都做好了，而且装备完成发射了出去。我拿了钱，正准备去消费消费，你就在这个时候满世界的追我。我这没有那种化学品了，我也不知道那究竟是什么东西。"
D.Strings[32098]="那些化学品是送到哪去的？"
D.Strings[32099]="你要我想起所有那些让我精神失常的事？听着。他们并没有付钱让我跟进这件事，我们之间的协议也不允许我透露这些。我可以把我的账本扔在地上，你自己捡起来然后别来烦我了。$b$b听明白了？"
D.Strings[32100]="你听说过我们的“慈善情人符”计划吗？$B$B官方的加冕活动，像我这样的福星会得到授权，分发可爱的情人符工具箱。$B$B你可以用得来的可爱的情人符为自己的朋友和心爱的人制作可爱的情人符手镯，或是把它们拿到可爱的商贩那里来兑换爱情信物！$B$B这期间的另一个流行做法是将自己制作的手镯送给自己喜爱的领袖，让他们感受到众人对他们的欣赏和爱戴…"
D.Strings[32101]="漂亮！"
D.Strings[32102]="我想要一个可爱的情人符工具箱。"
D.Strings[32103]="我已经把我知道的都告诉你了，现在走吧！"
D.Strings[32104]="无论你要什么，布雷泽·盖茨！明白吗？$B$B而且我指的不光是那些“合法”的东西。我是说——无论——你要什么，朋友！任何东西……"
D.Strings[32105]="我对你喜欢的那些怪东西不感兴趣，布雷泽。只管拿给我“合法”的东西。"
D.Strings[32106]="你能取出那把剑吗？"
D.Strings[32107]="黑暗女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。"
D.Strings[32108]="真是……不敢相信！霜之哀伤居然……无人看管，那个侏儒说的没错。来吧，英雄们！"
D.Strings[32109]="我不敢碰它。后退！后退，我要试着和这把剑交谈！也许我们的救赎就在其中……"
D.Strings[32110]="乌瑟尔……乌瑟尔·光明使者。怎么……"
D.Strings[32111]="巫妖王就在这里？那今天就是我完成使命的日子！"
D.Strings[32112]="一定有办法……"
D.Strings[32113]="谁能扛起这样的重担？"
D.Strings[32114]="冰封王座……"
D.Strings[32115]="你别想轻易逃走，阿尔萨斯！我的仇一定要报！"
D.Strings[32116]="你太迟了，信使。不，我不想听你的借口；这个任务极为重要。"
D.Strings[32117]="这是我们的使者从龙眠神殿带回来的宝典。立刻将它带给麦雷昂·阳炎。"
D.Strings[32118]="信使，你要小心。我无须向你解释这本书的重要性，况且，银色盟约的人会不惜一切代价把它从我们手里夺走。"
D.Strings[32119]="小心，女孩。我听说这把被诅咒的剑救过我们。注意周围，看看霜之哀伤都创造了些什么。"
D.Strings[32120]="你没有时间了。巫妖王能看到剑旁的一切。他就要来了。"
D.Strings[32121]="在这里，你无法击败巫妖王。这种企图是愚蠢的。他会打倒那些跟随你的人，把他们变成强大的天灾战士。只有你除外，希尔瓦娜斯……他对你的“馈赠”要比上次更恐怖。"
D.Strings[32122]="也许吧，但要记住：一定要有一位巫妖王。即使你终结了阿尔萨斯，也要有另一个人来取代他。没有了巫妖王的控制，天灾军团就会像蝗灾一样横扫世界，所到之处，寸草不生。"
D.Strings[32123]="我不知道，女妖之王。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。"
D.Strings[32124]="唉，击败巫妖王的唯一方法就是在他的诞生地摧毁他。"
D.Strings[32125]="啊……他……他来了。你……你必须……"
D.Strings[32126]="乌瑟尔摇了摇头。"
D.Strings[32127]="这种刺骨的寒冷……血液好像都要凝结了。"
D.Strings[32128]="看前面！那是什么！难道是？英雄们，到我身边来！"
D.Strings[32129]="霜之哀伤：正是它摧毁了我们的王国。"
D.Strings[32130]="后退！如果碰到这把剑，你的灵魂就会受到永恒的创伤！我必须试着与封印在霜之哀伤中的灵魂交谈。远离我，请再后退一点。"
D.Strings[32131]="乌瑟尔！亲爱的乌瑟尔！我……很难过。"
D.Strings[32132]="阿尔萨斯在这里？也许我……"
D.Strings[32133]="但是，乌瑟尔，哪怕有一丝见到他的可能，我……我也要去。"
D.Strings[32134]="告诉我，乌瑟尔，我该怎样终结我的王子？我的……"
D.Strings[32135]="你是对的，乌瑟尔。原谅我。我……我不知道自己是怎么了。正在冰冠堡垒与天灾军团作战的国王和骑士们很快就会得到我们的报告。"
D.Strings[32136]="也许还有希望……"
D.Strings[32137]="你不能拒绝我，阿尔萨斯！我必须知道……必须明白……"
D.Strings[32138]="吉安娜！真的是你吗？"
D.Strings[32139]="吉安娜，你没有时间了。巫妖王能看到剑旁的一切。他就要来了。"
D.Strings[32140]="不，孩子。阿尔萨斯不在这里。阿尔萨斯只是巫妖王意识中的一个存在。一个即将泯灭的存在……"
D.Strings[32141]="吉安娜，听我说。你必须终结巫妖王。不要试图说服他。他会把你们全杀掉，变成天灾军团的战士。"
D.Strings[32142]="振作起来，女孩。你必须在巫妖王和耐奥祖融合的地方－－冰封王座，将他终结。这是唯一的办法。"
D.Strings[32143]="还有…还有一些事情你需要知道。天灾军团绝不能失去控制。即使你战胜了这个巫妖王，也要有别人来取代他。没有巫妖王的控制，天灾军团就会横扫整个世界，摧毁一切生灵。"
D.Strings[32144]="要有个崇高的灵魂作出牺牲……"
D.Strings[32145]="我不知道，吉安娜。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。"
D.Strings[32146]="不，吉安娜！啊……他……他来了。你……你必须……"
D.Strings[32147]="闭嘴，圣骑士！"
D.Strings[32148]="你真的想和死人交谈？我会满足你。"
D.Strings[32149]="法瑞克，玛维恩，杀掉他们，送到我的大殿来。"
D.Strings[32150]="你要找那个早就被我干掉的家伙吗？现在他只是一个幽魂，一个我脑中微弱的回音……"
D.Strings[32151]="你为什么要打断我，$c？"
D.Strings[32152]="你是个奇怪的小家伙。"
D.Strings[32153]="总算盼到你来了，信使。克拉苏斯将其余的上古龙铸之刃复制品中的一个交给了我们。"
D.Strings[32154]="给你书。你要确保赶在夺日者发现这一切之前将书送到卡莱迪斯·亮矛那里。"
D.Strings[32155]="快马加鞭！夺日者发现我们有他们要的信息时会抓紧一切时间对付我们。"
D.Strings[32156]="暴风城的市民和客人们。我们的城市正在遭受攻击！拿起武器，保卫我们的首都！如果你不想参加战斗，就用沙包在街道上筑起堤坝，阻挡即将到来的洪水吧！"
D.Strings[32157]="$B$B抓紧时间，使用城中每个角落的寒冰之石打开一道通往元素位面的传送门并召唤那些要为此事负责的家伙。$B$B同时激活所有的寒冰之石以确保胜利的取得。"
D.Strings[32158]="将沙袋堆砌在暴风城周围，挡住洪水！$B$B从散落在城市各个角落的沙袋堆里背起一个沙袋$B$B将它们放在红色箭头标记的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。"
D.Strings[32159]="关闭那些裂隙，使用大地之环防御者提供的图腾，解救被围困的平民！"
D.Strings[32160]="现在部落控制了战斗之痕！"
D.Strings[32161]="现在联盟控制了战斗之痕！"
D.Strings[32162]="部落勇敢的战士，我向你致敬！如果没有你和你盟友的帮助，我们一定会死在联盟炮艇的火力下。$B$B请稍事休息，随后我们会展开针对敌人堡垒上游的袭击。"
D.Strings[32163]="我们准备好了，大王。巫妖王必须死！"
D.Strings[32164]="你能肯定吗，$n？要想战胜天灾军团，我们必须全力以赴。如果你休息得差不多了，我们就开始吧。"
D.Strings[32165]="Lok'tar ogar！我们准备好了！兽人兄弟们，冲啊！"
D.Strings[32166]="库卡隆，行动！勇士们，提高警惕。天灾军团已经……"
D.Strings[32167]="加入我，父亲。让我们一同以天灾之名来粉碎这个渺小的世界——巫妖王万岁！"
D.Strings[32168]="我曾听过我的孩子在那里发生的故事。现在，他已经成了巫妖王手下一名强大的死亡骑士。如果这是真的，我必须大义灭亲。$B$B我现在的责任就是指挥奥格瑞姆之锤号抵达冰冠堡垒之顶，并消灭所有阻拦我们的天灾军团。你和你的盟友准备好以后我们就出发。"
D.Strings[32169]="算上我所有的同伴，萨鲁法尔。出发吧！"
D.Strings[32170]="我的儿子战死在天谴之门。我来只是想带走他的尸体。"
D.Strings[32171]="顽固的老头。你以为你能赢？即使你最强壮的时候，也不如我现在的力量。"
D.Strings[32172]="我给他起名为德拉诺什，意思是“德拉诺之心”。我不会让那些术士带走他。我的孩子会安全地藏在加拉达尔长老那里。"
D.Strings[32173]="我在他的母亲弥留时许下诺言。我会孤身穿过黑暗之门。无论我是生是死，我的儿子都不会有事，都会纯净如初……"
D.Strings[32174]="今天，我兑现了诺言。"
D.Strings[32175]="可怜的老兽人！来吧，英雄们，来尝尝天灾军团的力量吧！"
D.Strings[32176]="面对霜之哀伤，奎尔德拉很快复苏了！"
D.Strings[32177]="%s对着自己儿子的尸体流下了眼泪。"
D.Strings[32178]="你会在纳格兰有一个隆重的葬礼，安睡在你的母亲与祖先身旁。"
D.Strings[32179]="年轻的英雄们……无论战斗多么可怕……也不要忘记荣耀。"
D.Strings[32180]="听从您的吩咐，主人……"
D.Strings[32181]="敌人即将大难临头，主人！"
D.Strings[32182]="来吧，斩亡者。我会让主人知道，我们谁才配得上“勇士”之名！"
D.Strings[32183]="怎么选这种低能的盟友，科罗克！"
D.Strings[32184]="结束了，主人。"
D.Strings[32185]="主人……我……失败了。"
D.Strings[32186]="别害怕，主人。看我怎么将敌人撕个粉碎！"
D.Strings[32187]="一点都不疼了，是不是？"
D.Strings[32188]="很抱歉……"
D.Strings[32189]="能感到那灼热吗？"
D.Strings[32190]="我……做了什么？不！"
D.Strings[32191]="这就是你距离炸弹太近的结果！"
D.Strings[32192]="多么……爆炸性的结局啊！"
D.Strings[32193]="什么？这种力量是……？所有的痛苦都消失了！你……？难道我们都投入了永恒的死亡怀抱？"
D.Strings[32194]="我已经救不活了。兄弟们，继续战斗……"
D.Strings[32195]="请……将我火化。让我在死后得到温暖……"
D.Strings[32196]="不！不！为什么我不能在火中死去？ 都烧成焦炭吧！"
D.Strings[32197]="我死的……很值得。"
D.Strings[32198]="巫妖王的意志不可逃避。准备好迎接一场爆炸吧！"
D.Strings[32199]="传送器闪出水晶般的光芒。"
D.Strings[32200]="传送到圣光之锤。"
D.Strings[32201]="真是轻而易举的捕猎。希尔瓦娜斯一定会非常高兴的！"
D.Strings[32202]="你怎么？！没关系，我不需要用陷阱来击败你。"
D.Strings[32203]="在黑暗斥候击中你之前，使用贝瑞莎的护身符！$B$B|TInterface\\Icons\\inv_jewelry_talisman_10.blp:64|t"
D.Strings[32204]="现在，我们要赢得这场战争！$B$B越过这片满目疮痍的地区向东，联盟希望在他们的海岸要塞之间建立起陆上连接。他们想要在这里，在贫瘠之地的正中心建立一座堡垒。但这是我的贫瘠之地。$B$B我绝不会允许那座堡垒出现。"
D.Strings[32205]="这太可怕了，$c。我被蛮横地赶出奥格瑞玛。当我被拖出奥格瑞玛的大门时，我的实验材料全都被扔在地上，被彻底毁了。$B$B他们对待我就好象对待某种可怕的怪物！$B$B幸运的是，我在这里还能继续我的研究。这里从不会缺乏新鲜的实验材料。"
D.Strings[32206]="启动引擎！小伙子们，向命运之战前进！"
D.Strings[32207]="都给我抓紧了！"
D.Strings[32208]="那到底是什么？来人，给我望远镜！"
D.Strings[32209]="以我的胡子起誓！部落的速度真快啊！"
D.Strings[32210]="规避动作！炮火准备！"
D.Strings[32211]="卑鄙的家伙！竟敢偷袭我们！"
D.Strings[32212]="想挡住我？也不看看自己是谁？我现在就要去和阿尔萨斯算账了，谁也别想拦着我！注意！全火力射击！开火！开火！"
D.Strings[32213]="强大的天灾军团将让死亡和毁灭席卷整个世界！"
D.Strings[32214]="这不是你的战斗，矮人。回去，否则我们就只能摧毁你们。"
D.Strings[32215]="又一份给主人的献礼！"
D.Strings[32216]="到下面去挣扎吧！"
D.Strings[32217]="我的眼前……只有黑暗。"
D.Strings[32218]="来吧！部落忠诚勇敢的儿女们！今天是部落仇敌灭亡的日子！LOK'TAR OGAR！"
D.Strings[32219]="主人的怒火赐予我力量！"
D.Strings[32220]="库卡隆，出发！"
D.Strings[32221]="那是什么？有东西正从远方靠近！"
D.Strings[32222]="死亡是唯一的解脱！"
D.Strings[32223]="联盟的炮船！全体集合！"
D.Strings[32224]="白骨的束缚！"
D.Strings[32225]="定住吧！"
D.Strings[32226]="在你面前的是萨鲁法尔！"
D.Strings[32227]="你很快就会明白了。库卡隆，消灭他们！"
D.Strings[32228]="兽人！挪开你的破飞艇，否则我就把它轰烂！这里没部落什么事！"
D.Strings[32229]="火枪手，加速射击！"
D.Strings[32230]="火炮小队，装弹！"
D.Strings[32231]="将士们，给我进攻！"
D.Strings[32232]="我们的船体受伤了，赶快叫个法师来干掉那些大炮！"
D.Strings[32233]="什么？！别妄想能轻易就夺走我们铁炉堡的船！"
D.Strings[32234]="我早就警告过你，恶棍！兄弟姐妹们，前进！"
D.Strings[32235]="指挥官巴雷特，离开这里！我们受到重创，难以漂浮了！"
D.Strings[32236]="看上去不妙啊，小子们。"
D.Strings[32237]="飞斧手，加速掷斧！"
D.Strings[32238]="火箭手，装弹！"
D.Strings[32239]="我们的船体受损了，赶快叫个战斗法师来轰掉那些大炮！"
D.Strings[32240]="你竟敢上我的船？你活不长了。"
D.Strings[32241]="联盟不行了。向巫妖王进攻！"
D.Strings[32242]="把火扑灭，控制损伤！让你们见识一下部落的坚强！"
D.Strings[32243]="我们失败了。"
D.Strings[32244]="<一只蟑螂从卡尔德的嘴里爬出来，又爬进了他的一只空眼窝。>"
D.Strings[32245]="<一看到你，卡尔德装上他的下巴，准备和你说话。>"
D.Strings[32246]="<你发现卡尔德正用一把匕首无聊地拨弄着他的耳朵。>"
D.Strings[32247]="知道我喜欢什么吗，$n？"
D.Strings[32248]="不，卡尔德。你喜欢什么？"
D.Strings[32249]="杀戮。"
D.Strings[32250]="传送到诅咒祷堂。"
D.Strings[32251]="传送到颅骨之墙。"
D.Strings[32252]="传送到死亡使者的高台。"
D.Strings[32253]="传送到尖塔上层。"
D.Strings[32254]="传送到冰封王座。"
D.Strings[32255]="就像戈德林之魂曾经祝福过我们的德鲁伊那样，请让$n得到祝福，赐予他智慧和狼神的勇猛吧。"
D.Strings[32256]="传送到辛达苟萨的巢穴。"
D.Strings[32257]="让塔多伦去安慰$n吧，就像达拉尼尔安慰那些因为受到诅咒，而放弃了平衡的信仰，变成野兽的德鲁伊一样。"
D.Strings[32258]="让月神镰刀解放不应受束缚的生灵！让灵魂控制这兽性，而不是兽性控制灵魂！"
D.Strings[32259]="嘿！过来，$n。"
D.Strings[32260]="%s在你身后高兴地轻轻摇晃着。"
D.Strings[32261]="感谢你们，我的兄弟姐妹。破天号已经启程了。快到奥格瑞姆之锤去！也许你们还能乘上那艘船。"
D.Strings[32262]="这对你来说应该有帮助！"
D.Strings[32263]="Aka'Magosh，勇士们。联盟在这里驻有重兵。"
D.Strings[32264]="萨鲁法尔大王会在奥格瑞姆之锤号欢迎你们。我们会守住这里，等你们做好起飞准备。"
D.Strings[32265]="奥格瑞姆之锤的兄弟们，坚守岗位！"
D.Strings[32266]="来吧，曼科里克，坐到我旁边来休息一下。"
D.Strings[32267]="看看这片土地，曼科里克。部落和联盟之间争斗不休，也让这片土地满目疮痍。"
D.Strings[32268]="这样的仇恨只会给我们带来毁灭。当你和那些野猪人作战的时候，我也能在你的眼睛里看到那种仇恨……你的愤怒只会让你变得衰弱。"
D.Strings[32269]="你在毁灭你自己，曼科里克。"
D.Strings[32270]="我已经一无所有。现在我想要的只是一位战士光荣的死亡。这有错吗？"
D.Strings[32271]="你在寻找的是逃避，不是光荣。这是自杀。"
D.Strings[32272]="那又怎样，你为什么要关心这种事？"
D.Strings[32273]="因为……"
D.Strings[32274]="无论你是否在意，但这个世界里终究还是有人会因为你的死而伤心。"
D.Strings[32275]="玛卡……"
D.Strings[32276]="求求你，曼科里克。放手吧，放下你的剑。"
D.Strings[32277]="憎恨已经在我的心中燃烧了许多年，玛卡。你不可能凭几句话就把它除去。"
D.Strings[32278]="现在……你不需要独自面对这一切。坐到我身边来，忘记你的困扰吧。哪怕一会儿也好。"
D.Strings[32279]="如果累了，就来我这里。"
D.Strings[32280]="玛卡想要你去看她，曼科里克。"
D.Strings[32281]="玛卡想要见我？……好吧，去告诉她，我这就来。"
D.Strings[32282]="迅爪不会停下来！控制它返回暗矛要塞旁边的迅猛龙围栏。"
D.Strings[32283]="%s将一只杯子扣在凄凉城堡的墙上，仔细地倾听着。"
D.Strings[32284]="%s打了个喷嚏，吹动了他藏身的灌木丛。"
D.Strings[32285]="%s发出期待的叫声。"
D.Strings[32286]="%s跳来跳去。"
D.Strings[32287]="%s发出了一声细小的尖叫。"
D.Strings[32288]="%s向你晃动着它的利角。"
D.Strings[32289]="%s在你身后蹦跳着。"
D.Strings[32290]="%s兴奋得几乎一头栽倒在地。"
D.Strings[32291]="%s向你跑过来，小爪子用力敲打着地面。"
D.Strings[32292]="你们永远别想把我们赶出城去，银色盟约的混蛋！"
D.Strings[32293]="你们这些夺日者下人全都一个样。"
D.Strings[32294]="你来晚了，$n。来自达拉然的另一位访客已经来过这里，同样是为了了解有关远古龙剑的事情。"
D.Strings[32295]="根据你的描述我可以断定，我借给那位访客的书能使你很容易地对这把武器做出鉴定。"
D.Strings[32296]="嘘，$n！到这边来！树旁边。"
D.Strings[32297]="恐怕，你得找——嗯，或许卡雷苟斯会帮忙。"
D.Strings[32298]="$n可能已经发现了古剑的碎片，卡雷苟斯。你会帮助我们的到访者吗？"
D.Strings[32299]="你确定你应该帮助那些凡人取得那把剑吗？"
D.Strings[32300]="这些武器，克拉苏斯…它们制造于很久以前，那时候的一切…都不同。"
D.Strings[32301]="<卡索格将水袋递给你。>$B$B我们曾经称这里为黄金大道，$c。今天，它却被鲜血染红。$B$B那全都是联盟的血。"
D.Strings[32302]="你认为我们的盟友没有能力控制这些剑的力量？"
D.Strings[32303]="慢一些，朋友。你说将军就要来了？$B$B我的墙上又要增添一件战利品了！我会吸引那些近卫的注意，你的任务就是去干掉霍索恩将军。准备好了吗？"
D.Strings[32304]="准备好了，卡索格。为了部落！"
D.Strings[32305]="凡间的勇士长久以来都在使用这些武器对抗着邪恶。我认为没有理由不让他们在这场战斗中使用这些剑。"
D.Strings[32306]="我们的敌人曾利用我们最强大的武器来对抗我们。是什么让你觉得这些古剑会有所不同？"
D.Strings[32307]="遵从您的意愿，我的女王。我不会阻拦他们，但我会对他们紧密监视。"
D.Strings[32308]="大家排成密集队形。这是一场伏击。准备武器！"
D.Strings[32309]="我们都会如此。"
D.Strings[32310]="他们来了！所有人，做好准备……"
D.Strings[32311]="我把我的皇冠香水瓶弄丢了。"
D.Strings[32312]="我把我的皇冠古龙水瓶弄丢了。"
D.Strings[32313]="我把我的皇冠巧克力样本弄丢了。"
D.Strings[32314]="……谢谢，玛卡"
D.Strings[32315]="我们杀死他了！陶拉祖的屠夫死了！"
D.Strings[32316]="我们要让联盟知道他是怎样完蛋的。你先回去，把这个消息告诉血柄督军。"
D.Strings[32317]="兄弟们，吸引她们的注意力！让$n能够取回镰刀！"
D.Strings[32318]="后撤！撤到树林里去！"
D.Strings[32319]="陶拉祖的屠夫将会付出代价。"
D.Strings[32320]="在把他们赶回到大海之前，我不会休息，$n。"
D.Strings[32321]="明白！Grok'thar More'gar。Bok choy，朋友。呃。Zub zub！"
D.Strings[32322]="什么？你是谁？你来自于那个氏族？"
D.Strings[32323]="遵……遵命。呃。准备工作！"
D.Strings[32324]="你不是兽人。你是间谍！联盟的间谍！"
D.Strings[32325]="只有取得游侠将军的许可才能进入太阳井高地。"
D.Strings[32326]="%s在城堡的供给物资中翻找着什么东西。"
D.Strings[32327]="我已经准备好进入太阳之井了。"
D.Strings[32328]="诅咒你的眼睛，$r！"
D.Strings[32329]="兄弟姐妹们，目睹太阳之井再度复苏的感受简直难以言表。"
D.Strings[32330]="达利乌斯！黑暗游侠得到了那把镰刀！他们抢在我们之前得到了它。"
D.Strings[32331]="在那一刻，圣光为我揭示出我所犯下的种种罪过的真相。"
D.Strings[32332]="我们的人民走上了一条黑暗的道路，而我在这条路上走得最远。"
D.Strings[32333]="但圣光使我明白我并没有迷失。它帮助我找到力量，使我在经历许多后仍可幸存，即使我曾犯下如此重罪。"
D.Strings[32334]="那是一种所有辛多雷成员共享的力量。我们需要这种力量来摆脱蹂躏我们人民的魔瘾。"
D.Strings[32335]="这场将是我们遭遇过的最残酷的一场战斗，但我们的决心和太阳之井的力量将始终支撑我们重返巅峰。"
D.Strings[32336]="说得好，我的女王。我们辛多雷会重获自由并再度强大！"
D.Strings[32337]="耶，兄弟。去敲烂几个蒂基面具假人吧！"
D.Strings[32338]="立刻让我们的人就位，托比亚斯。我们不能让镰刀落到被遗忘者的手上！！"
D.Strings[32339]="我的主人和女王，请允许我向您们介绍$n，奎尔德拉的持有者。"
D.Strings[32340]="$n。祖尼。你们可以在东边的训练场找到你的训练师。不要给暗矛部族丢脸。"
D.Strings[32341]="我告诉过加杜尔，不要在异种生物的巢穴上建造城堡。$B$B他会听克劳格的话吗？不！"
D.Strings[32342]="玩吗？玩吗？"
D.Strings[32343]="哈哈，我做到了！"
D.Strings[32344]="死吧，死吧，死！"
D.Strings[32345]="我的妈呀！"
D.Strings[32346]="你……玩完了！"
D.Strings[32347]="我有点不舒服……*呕*"
D.Strings[32348]="不！你杀了大臭！你赔！"
D.Strings[32349]="我把它弄坏了……"
D.Strings[32350]="我会拿你做新玩具！"
D.Strings[32351]="真是糟糕……"
D.Strings[32352]="该睡觉了！"
D.Strings[32353]="黏啊，真黏啊！"
D.Strings[32354]="什么？我的心肝？不！！！"
D.Strings[32355]="喜讯，各位！我想我已经研制出一种能够毁灭艾泽拉斯的药剂了！"
D.Strings[32356]="嗯，有趣……"
D.Strings[32357]="这是个意外！"
D.Strings[32358]="噩耗，各位……我觉得我要失败了……"
D.Strings[32359]="这是普通的毒云，但请千万小心，这毒云其实并不普通！"
D.Strings[32360]="嗯，什么感觉也没有。什么？！这是哪儿来的？"
D.Strings[32361]="味道像……樱桃！哦！见笑了！"
D.Strings[32362]="两泥，一室。会有无限惊喜哦！"
D.Strings[32363]="惊天噩耗，我作的腐面，刚刚死了。但重大喜讯，他留下了，大量软泥！哇，我居然还有这么出众的诗歌才华……雷死了！"
D.Strings[32364]="哦烂肠，你是我的最爱，仅次于腐面。不过你的死给我留下了那么多毒气，我都快被熏死了！"
D.Strings[32365]="%s大声哭嚎起来！"
D.Strings[32366]="高潮到了。准备抵御元素生物的进攻！Lok'tar ogar！"
D.Strings[32367]="兄弟姐妹们，做好准备。元素生物集结在一起攻打我们的城池。准备战斗！"
D.Strings[32368]="我获得了新生！伊瑟拉的恩泽赐予我消灭邪恶的力量！"
D.Strings[32369]="我的天才不可能被束缚在一个胶囊里！$B$B等等，这里不是艾萨拉？！这是什么地方？这是一座休眠火山！$B$B我本来有些想去找贸易大王的！但我也在考虑将肉鸡蛋实现武器化的可能！"
D.Strings[32370]="当我们被像行李一样打包运到胶囊镇里的时候，他们对我们说的是我们将受雇前往艾萨拉的某地工作。这是艾萨拉吗？$B$B我问你：是谁搞出了胶囊镇，却又不在里面准备好足够的食物？！某个肮脏的变鸡器？！$B$B我们都知道机动战鸡的微型化是怎么实现的。"
D.Strings[32371]="大领主莫格莱尼，我必须请你为我重新铸造影锋。"
D.Strings[32372]="喔！瞧这烧的！"
D.Strings[32373]="真烫！"
D.Strings[32374]="燃烧吧！这是我的舞台！"
D.Strings[32375]="我着火啦！"
D.Strings[32376]="真性感啊，就是太痛了！"
D.Strings[32377]="最好的永远是最有效的。"
D.Strings[32378]="烧得真漂亮！"
D.Strings[32379]="是的，女士们，我还是单身。"
D.Strings[32380]="元素生物正在入侵这里地区。准备保卫奥格瑞玛！"
D.Strings[32381]="现在发动进攻的是一波更强大的元素生物，不过那些火元素已经失控！清除那些元素生物，控制住那些火元素。"
D.Strings[32382]="大火要将奥格瑞玛全部吞噬。如果你认为自己强大到足以进去，那么请便。否则，就留在城外，让我们来对付它。"
D.Strings[32383]="靠我近点，朋友。我在上一次袭击中被一颗子弹射中了。$B$B<甘恩努力想挪动一下身体，却只是痛苦地呻吟了一声。他的左手按在一处伤口上。血不断地从他的指缝间涌出。>$B$B当矮人们最初入侵贫瘠之地的时候，我只是满足于骚扰他们的挖掘工，破坏他们的设备。我真应该趁有机会的时候对他们发动致命的打击。"
D.Strings[32384]="维兹尔·滑影，伪装大师！"
D.Strings[32385]="|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你获得了|cFF00FF00畸变感染|r效果！"
D.Strings[32386]="拜托你了，凡人，同达拉然的奥术师泰拜林谈一谈。他可能有办法和夺日者进行交涉，让你看一看那本书。"
D.Strings[32387]="拜托你了，凡人，在达拉然找到魔导师哈瑟尔。他可能有办法和银色盟约进行交涉，让你看一看那本书。"
D.Strings[32388]="英雄们，请快些帮助我，我……我快要抵挡不住他们了。请治疗我的伤口！"
D.Strings[32389]="我打开了进入梦境的传送门。英雄们，救赎就在其中……"
D.Strings[32390]="我坚持不了多久了。"
D.Strings[32391]="我的力量回来了。坚持，英雄们！"
D.Strings[32392]="我们不会让你轻易逃脱的！"
D.Strings[32393]="你认为你能活着逃走吗？"
D.Strings[32394]="%s将目光指向了你！"
D.Strings[32395]="这不算什么大挑战，朋友，但在接纳你之前，我们要确认你有能力对付这个地穴里的东西。"
D.Strings[32396]="我已经准备好面对挑战了。"
D.Strings[32397]="到这个地穴里去，让我们看看你的能耐，$G小伙子:姑娘;。"
D.Strings[32398]="巫妖王的爪牙，这里不欢迎你们！"
D.Strings[32399]="被遗忘者以为我们软弱无能。心灰意冷。他们以为我们会像丧家犬一样投降。"
D.Strings[32400]="他们正在进行挑战，朋友。耐心一些。"
D.Strings[32401]="即使我们被包围，失去武器……身受重伤，孤立无援……我们也会带着轻蔑的神情高昂起头，将唾沫啐在敌人的脸上。"
D.Strings[32402]="我们会在城市中战斗，直到射出最后一颗子弹，然后我们会掘起铺路的石块，砸向他们的脑袋。"
D.Strings[32403]="我们会在巷道里战斗，直到我们用尽最后一丝气力，手中的刀剑崩成碎片。"
D.Strings[32404]="他们大错特错了。我们会在旷野上战斗，直到最后一条战壕崩塌，最后一门大炮哑火。"
D.Strings[32405]="安静点，蠢货。如果我要杀你，你早已经死了。"
D.Strings[32406]="即使被包围，失去武器，身受重伤，毫无希望……我们也会高昂着头，将唾沫啐在敌人的脸上。"
D.Strings[32407]="但是我们……决不投降！！！"
D.Strings[32408]="为吉尔尼斯而战！"
D.Strings[32409]="拿走它们吧，凡人，这些灵魂很快又将是我的。"
D.Strings[32410]="凡人，你很快也会成为剑中的囚徒。"
D.Strings[32411]="记住，英雄：我也曾寻找一件强大的武器……"
D.Strings[32412]="我看到你也在收集着灵魂，就像我一样。我们真的不同吗，勇士？"
D.Strings[32413]="没错！打造你的恐怖武器吧。它将随着你的灵魂一同为我效命。"
D.Strings[32414]="带上你的武器，勇士，它会尝到自己主人灵魂的鲜美！"
D.Strings[32415]="孩子，你想操纵灵魂吗……你还无法理解我所掌握的力量！"
D.Strings[32416]="狂妄之徒！来祭我的剑吧！"
D.Strings[32417]="我的考验让你变得更强，你将更好地效忠我！"
D.Strings[32418]="你要知道，凡人，我并不后悔饶你一命，因为你总会给我带来乐趣。"
D.Strings[32419]="你的大限将至，凡人。你将在新的艾泽拉斯永受折磨！"
D.Strings[32420]="你会发现……对灵魂的渴求……是多么的难以抗拒。"
D.Strings[32421]="你的武器感到了饥饿。这不算什么。想要感受真的饥饿，真的力量吗？继续吧，英雄，我等着你们。"
D.Strings[32422]="你只能在黑暗中踌躇。那里没有光明，也没有怜悯！冰冠堡垒吞噬过比你更加强大的灵魂。"
D.Strings[32423]="你不停跳动的心脏令我厌恶。我会让它停止，就像我一样。"
D.Strings[32424]="圣光会抛弃你，英雄，就像抛弃我那样。"
D.Strings[32425]="A-Me有许多运动速度模式。根据A-Me设计说明U-2502，使用者可以自行设定A-Me的运动模式，让它完全符合自己的需求。$b$b在缓行模式下，A-Me以正常的$r速度移动。$b$b在奔跑模式下，A-Me以普通马匹或座狼的速度移动。$b$b在超速模式下，A-Me以高速战马或迅捷座狼的速度移动。$b$b你想要哪种模式？"
D.Strings[32426]="我认为应该从缓速模式开始，A-Me。"
D.Strings[32427]="让我们试试奔跑模式。"
D.Strings[32428]="超速模式！我们来试试！"
D.Strings[32429]="指令输入已确认。请准备好开始旅程。"
D.Strings[32430]="良好。良好。使用者已准备好。现在，我们出发。"
D.Strings[32431]="等待。A-Me遗忘了某事件。我们应立刻停止，然后返回至逃跑进程。"
D.Strings[32432]="A-Me拍打着胸口，向附近的一只猩猩发出呼吼。"
D.Strings[32433]="乌嘎……你来了。良好。A-Me需要你听一听。"
D.Strings[32434]="这对A-Me来说不容易…… A-Me要回家。 这是A-Me离开的最后时刻。"
D.Strings[32435]="A-Me需要你告诉拉库，A-Me感谢他教导A-Me如何制造闪电；还要告诉米思科，A-Me感谢他教导A-Me如何同恐龙作战。"
D.Strings[32436]="但最重要的是……感谢你，乌嘎，是你教会了A-Me该如何去爱。"
D.Strings[32437]="A-Me 01最后凝望了乌嘎一眼，一滴椰奶从她的眼睛里流出来。"
D.Strings[32438]="不坏，$n。不坏。"
D.Strings[32439]="我一点也不喜欢这个皇冠药剂公司的样子。"
D.Strings[32440]="照顾好你的武器，它们就能照顾好你。"
D.Strings[32441]="男人，女人，还有孩子……没人能逃过主人的怒火。你的死早已注定。"
D.Strings[32442]="元素混乱而且狂野。只有通过学习，我们才能保持和它们的联系并控制它们。"
D.Strings[32443]="我不能帮助你，如果你想接受战士训练，就去和诺泰特谈谈。"
D.Strings[32444]="我不能帮助你，如果你想接受萨满祭司训练，就去和奈卡利谈谈。"
D.Strings[32445]="我不能帮助你，如果你想接受德鲁伊训练，就去和岑塔布拉谈谈。"
D.Strings[32446]="我不能帮助你，如果你想接受潜行者训练，就去和雷加提谈谈。"
D.Strings[32447]="我不能帮助你，如果你想接受牧师训练，就去和图娜尼谈谈。"
D.Strings[32448]="我不能帮助你，如果你想接受法师训练，就去和索拉萨谈谈。"
D.Strings[32449]="我不能帮助你，如果你想接受猎人训练，就去和欧塔扎谈谈。"
D.Strings[32450]="我们不能帮你，朋友。"
D.Strings[32451]="无能的家伙！"
D.Strings[32452]="斯坦索姆的小孩子都要比你们勇猛！"
D.Strings[32453]="玛维恩，干掉他们……"
D.Strings[32454]="洛丹伦的战士们，服从主人的召唤！"
D.Strings[32455]="绝望……如此甘甜……"
D.Strings[32456]="恐惧……如此美好……"
D.Strings[32457]="你们只会寻得死亡！"
D.Strings[32458]="我看到的是同样的眼神。泰瑞纳斯怎么也想不到。"
D.Strings[32459]="痛苦的窒息吧！"
D.Strings[32460]="对，去吧……迎接你的命运吧……痛苦、冰冷的拥抱正等着你。"
D.Strings[32461]="主人审视他的王国，找到了它的……不足。他的决断迅速而无情：生灵俱灭！"
D.Strings[32462]="你的躯壳将在你的眼前朽化！"
D.Strings[32463]="灰飞烟灭吧！"
D.Strings[32464]="暗矛巨魔在很久以前就和自然有着密切的联系，但直到最近，我们才了解到德鲁伊的技艺。 $n，你要尽量保持谦虚的态度。"
D.Strings[32465]="骤隐骤现。当人们看到你所做的一切，却看不到你的时候，你就掌握了你的职业技巧。"
D.Strings[32466]="在混乱的战场上，光与影的平衡将引领我们取得胜利。"
D.Strings[32467]="侍从是骑士的左右手。要知道，手应该特别擅长于搬运东西，所以你的第一个任务就是负责搬运我的杂物、小东西和其它各种随身用具。这样我才能放心地在世界各处维护正义。毕竟搬运杂物可不是骑士应该做的事情。"
D.Strings[32468]="可以理解。"
D.Strings[32469]="很好。第二，你必须知道，对于骑士来说，最重要的莫过于骑士精神。骑士永远要秉承慷慨仁慈的骑士情怀，就如同绝对不能放开手中的长枪。他的勇猛果敢必须比他身上的铠甲更加耀眼夺目。无论他的佩剑多么锋利刚硬，他对待朋友却必须和善谦恭。$b$b现在，告诉我，$n，你会立下誓言，坚守骑士的精神和勇气吗？"
D.Strings[32470]="我在此立誓。"
D.Strings[32471]="哈！我没有说过吗，好$n，骑士精神和勇气是骑士必须坚持的原则？你要做的只是一名侍从。严格的骑士精神对于侍从来说是难以承受的重担。就像我曾经提到过的一样，你要扛起的担子只有我的随身物品。"
D.Strings[32472]="这太荒谬了！我可不会容忍这个！"
D.Strings[32473]="开始吧！骑士精神是骑士之道，我正是一名骑士。你必须明白，我天生就是一名勇者。这是真的，我为多罗莉亚女士而战，要将她的美丽与高贵在全世界传颂。任何对她的美好有所质疑的人都是我最大的敌人，一定会得到我正义的惩罚。$b$b当我说话的时候，我才意识到我的一个失误。我们已经正式开始了接纳侍从的仪式，但我还没有确认你是应该接受我的赞许，还是我的正义怒火。$b$b现在我必须知道，你是否认为多罗莉亚女士是艾泽拉斯无可置疑的最美丽的人？"
D.Strings[32474]="很高兴听到你这样说。祝贺你，$n，你已经完成了训练。现在你可以跟随我一同上战场了。"
D.Strings[32475]="聪明，你会发现，魔法比任何武器都要强大得多。"
D.Strings[32476]="嗯……是的，她当然是，毫无疑问。"
D.Strings[32477]="要信任你的弓。当你需要它的时候，它绝不会辜负你。"
D.Strings[32478]="当一切都已失去，自然仍然会指引你。"
D.Strings[32479]="<麦斯米兰沉浸在祈祷中，忘却了你的存在。>"
D.Strings[32480]="收起你的剑，取下你的头盔。在我们用刀剑作战之前，我有好些话得先灌输到你的耳朵里去。$b$b准备好了吗？"
D.Strings[32481]="好的，我准备好了。"
D.Strings[32482]="这里就要爆炸了，赶快出去！"
D.Strings[32483]="%s刺穿了$n！"
D.Strings[32484]="%s的以太护盾已经被$n击碎。"
D.Strings[32485]="这次冒险的意义已经很明显了。看，当天真的少女在丛林中穿行时，一只凤凰幼鸟却在伺机将她猎杀！"
D.Strings[32486]="看着这只可憎的鸟在被杀死时变成火焰和灰烬吧。"
D.Strings[32487]="为了多罗莉亚！"
D.Strings[32488]="奇怪的是，那只鸟并没有变成火焰和灰烬。一只凤凰在死亡时没有变成火焰和灰烬，这是一个可怕的预兆。"
D.Strings[32489]="女士，如果你真的是如此好奇，那么我可以告诉你，是北郡的麦斯米兰拯救了你。"
D.Strings[32490]="真聒噪……"
D.Strings[32491]="干净整洁！"
D.Strings[32492]="干得好。我不想知道那点污迹究竟是什么。"
D.Strings[32493]="阿夸诺斯要忙不过来了！"
D.Strings[32494]="我应该留住你的。"
D.Strings[32495]="以巫妖王的力量为名！"
D.Strings[32496]="你们将在这里魂飞魄散！"
D.Strings[32497]="我变成了……死神！"
D.Strings[32498]="翻腾的仇恨将吞没你们！"
D.Strings[32499]="吃吧，奴仆们！"
D.Strings[32500]="愚蠢的凡人。你以为能轻易打败我们？萨莱因是巫妖王永生的战士！现在他们将合力撕碎你！"
D.Strings[32501]="晚餐……开席。"
D.Strings[32502]="见识到黑暗堕落者的力量了吧？"
D.Strings[32503]="向萨莱因屈服吧！"
D.Strings[32504]="纳克萨纳尔的失败早已过去！有了这颗宝珠，瓦拉纳就能完成复仇！"
D.Strings[32505]="杯子已经被斟满了。"
D.Strings[32506]="你们也敢来冒犯？"
D.Strings[32507]="死亡才是真谛。"
D.Strings[32508]="我的女王，他们……来了。"
D.Strings[32509]="如此汹涌的力量！黑暗堕落宝珠让我所向无敌！"
D.Strings[32510]="血溅当场吧！"
D.Strings[32511]="蛆虫。"
D.Strings[32512]="乞求宽恕吧！"
D.Strings[32513]="在塔达拉姆面前颤抖吧，因为我拥有黑暗堕落宝珠的力量！"
D.Strings[32514]="享受痛苦吧！"
D.Strings[32515]="你竟敢和灵魂之主对视？我会把你一口吃掉！"
D.Strings[32516]="彻底毁灭吧！"
D.Strings[32517]="灵魂的汹涌不会被削弱！一切都只是徒劳。"
D.Strings[32518]="磨难！痛苦！和混乱！来吧，吃个痛快！"
D.Strings[32519]="看这深渊，那里有你的末日。"
D.Strings[32520]="时间就是金钱，我的朋友。快快快！"
D.Strings[32521]="可爱的商贩正等着呢。快点吧！"
D.Strings[32522]="箱子不会自己长腿走路，朋友。开始干活儿吧！"
D.Strings[32523]="你没什么东西要搬吗？"
D.Strings[32524]="我需要一套新的伪装。"
D.Strings[32525]="如果我们不慢一些，我也许就要昏过去了。"
D.Strings[32526]="嗯……我也许需要点帮助……"
D.Strings[32527]="啊……如果你能轻轻地拍拍我的面颊，也许……"
D.Strings[32528]="嗨！谁来帮帮忙！"
D.Strings[32529]="你不必这么狠地打我！"
D.Strings[32530]="好，好，要来了！"
D.Strings[32531]="谢谢，这正是我需要的。"
D.Strings[32532]="你知道你很强壮吗？"
D.Strings[32533]="对于所有反抗巫妖王的人来说这都是个伟大的日子！以银色盟约的名义，勇敢的$n已经拿起了古剑奎尔德拉。"
D.Strings[32534]="我以夺日者领袖的身份自豪的宣布$n成为奎尔德拉新的持有者！"
D.Strings[32535]="有东西在发出臭味，这次可不是我的袜子。"
D.Strings[32536]="希望破灭……"
D.Strings[32537]="今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！银色盟约的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！"
D.Strings[32538]="迎接你的凄惨结局吧。"
D.Strings[32539]="霜之哀伤饿了……"
D.Strings[32540]="霜之哀伤，服从我！"
D.Strings[32541]="霜之哀伤会饱餐你们盟友的灵魂！"
D.Strings[32542]="我会让你的血脉和躯壳化为寒冰！"
D.Strings[32543]="你周围的世界将在眼前崩塌！"
D.Strings[32544]="你做了一个……愚蠢的……决定。"
D.Strings[32545]="跪拜你的主人和首领吧！"
D.Strings[32546]="瓦格里，主人在召唤你！"
D.Strings[32547]="就咬一小口……"
D.Strings[32548]="我饿了！"
D.Strings[32549]="死亡是逃不掉的！"
D.Strings[32550]="你受得了吗？"
D.Strings[32551]="就要来了……"
D.Strings[32552]="多么的……不幸啊。"
D.Strings[32553]="对！吃吧，宝贝！你是我的了！"
D.Strings[32554]="真的……？你就这点能耐？"
D.Strings[32555]="真是可怜。"
D.Strings[32556]="真是的……我们相处得……那么……好……"
D.Strings[32557]="怎么，自诩正义的圣光终于来了？我是不是该丢下霜之哀伤，恳求您的宽恕呢，弗丁？"
D.Strings[32558]="让我来亲自告诉你。当一切结束，你将跪求我的宽恕－－而我会拒绝你。你痛苦的哀号将是我狂野力量的最好证明……"
D.Strings[32559]="我会让你活着目睹这个末日，弗丁。这悲惨的世界将在我手中重铸，我不想让圣光最强大的勇士错过这一切。"
D.Strings[32560]="来吧，勇士们。释放你们的怒火吧！"
D.Strings[32561]="我不再有问题，也不再有疑问。你是艾泽拉斯最强大的勇士。我的阻挠都被你一一化解。我最悍勇的仆从也都倒在了你的无情怒火和利刃之下……"
D.Strings[32562]="真的是正义在驱使你吗？我很好奇……"
D.Strings[32563]="你把他们训练的很好，弗丁。你把世界上最强大的勇士都送到了我的面前，这正合我意！你们的默默牺牲会得到我的褒奖。"
D.Strings[32564]="亲眼目睹吧，我会把他们从尸骸变为天灾军团的战士。艾泽拉斯会在他们的手中陷入混乱，走向毁灭！而你，将是第一具尸体。"
D.Strings[32565]="我会享受这种讽刺。"
D.Strings[32566]="站起来，兄弟们，消灭这些敌人！"
D.Strings[32567]="哼！这些蛆虫居然让我受伤了！… 也许戏弄该结束了……现在－－感受大墓地的复仇吧！"
D.Strings[32568]="今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！夺日者的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！"
D.Strings[32569]="你不停跳动的心脏令我感到厌恶。我会让它停止，就像我的一样。"
D.Strings[32570]="狠狠地抽林格，别让他昏过去。"
D.Strings[32571]="水……"
D.Strings[32572]="水壶……水壶……"
D.Strings[32573]="要水……时间不多了……"
D.Strings[32574]="太……太渴了……"
D.Strings[32575]="真是一把神奇的剑，你觉得呢？这绝不会是出自矮人之手，不，还要古老的多。$B$B这些夺日者和银色盟约的使者似乎打算对这一秘密一探究竟。我已经开始准备给布莱恩的报告了。"
D.Strings[32576]="好的，把史上最大的蛋装进变鸡器里。麦可鸡块人人有份儿！"
D.Strings[32577]="作为德鲁伊，我们的任务就是维护自然的平衡。但我的努力却与此背道而驰。我的愚蠢造成极为巨大的混乱。必须在这种异常的作物进一步扩散之前将它收割。"
D.Strings[32578]="我会留在这里，照看这片正在痊愈的大地。请一定注意来自于这里的游荡者……"
D.Strings[32579]="我们会让你死个痛快，阿尔萨斯。对于犯下累累罪行的你，这是最大的仁慈了。"
D.Strings[32580]="好吧，勇士们，进攻！"
D.Strings[32581]="无上的圣光啊！请祝福我！赐予我力量……帮助我冲破这些枷锁！"
D.Strings[32582]="结束了，阿尔萨斯！你残害生灵的日子今天结束了！"
D.Strings[32583]="巫妖王必须死！"
D.Strings[32584]="你是来审判阿尔萨斯的吗？想要看到巫妖王的灭亡？"
D.Strings[32585]="首先，你需要摆脱霜之哀伤的控制，否则就会像我一样，永世成为这把邪剑的囚徒。"
D.Strings[32586]="帮我摧毁这些痛苦的灵魂！我们合力就能弱化霜之哀伤的控制，从内部削弱巫妖王！"
D.Strings[32587]="终于自由了！结束了，我的儿子。清算的时候到了。"
D.Strings[32588]="圣光的勇士们！集结起来！"
D.Strings[32589]="长官，这真是天才的主意。你的智慧总是让我感到吃惊！"
D.Strings[32590]="重大喜讯！各位！软泥又开始流动啦！"
D.Strings[32591]="%s的法力壁垒闪着微光并在逐渐消退！"
D.Strings[32592]="是谁在打扰我？你们竟敢擅闯这神圣的地方？这里将会是你们的埋骨之地！"
D.Strings[32593]="你还不明白自己的徒劳吗？"
D.Strings[32594]="拥抱黑暗吧……永恒的黑暗。"
D.Strings[32595]="这全是主人的计划……你的结局是必然的……"
D.Strings[32596]="够了！看来需要我亲自上阵了！"
D.Strings[32597]="软弱的你抵挡不了我强大的意志！"
D.Strings[32598]="陪你们玩的够久了！"
D.Strings[32599]="我等待这一天的到来已经太久了，英雄。你和你的同袍们是否已经准备好对巫妖王进行正义的审判？我们将在你的命令下向敌人发起冲锋！"
D.Strings[32600]="来接受这祝福，让入侵者尝尝主人伟大的力量吧！"
D.Strings[32601]="我们准备好了，大领主。让我们为艾泽拉斯的命运而战！为冲破黑暗的光明而战！"
D.Strings[32602]="忠诚的追随者，从血肉的诅咒中解脱吧！"
D.Strings[32603]="来吧，为纯粹的形态欢喜吧！"
D.Strings[32604]="好好看看你粗陋的手：看看那肌腱、软肉和其中的黑暗之血。"
D.Strings[32605]="多么的软弱和不堪……这真是造物主的玩笑。"
D.Strings[32606]="你只有承认自己必然的失败，才有可能早日获得更强的力量，重获新生。"
D.Strings[32607]="我的主人是无所不能的，他有无比强大的力量，不可抗拒的意志。"
D.Strings[32608]="反抗者必将被毁灭。而那些全身心的，坚定不移的，有虔诚的思想与灵魂的效忠者们，必将得到超乎你们想象范畴的强大的力量。"
D.Strings[32609]="你们之所以在这里，那是因为你们是少数几个拥有特殊能力，能够洞悉这诅咒世界的人。"
D.Strings[32610]="你们能够看穿遮蔽世界的迷雾，掌握真正的力量。"
D.Strings[32611]="这蛋可真大！掉转变鸡器的电极。我们得把它推进传送口里。"
D.Strings[32612]="就这样吧。应该用不了多久……"
D.Strings[32613]="父亲……"
D.Strings[32614]="你赢得了令人胆寒的挑战。"
D.Strings[32615]="你承受住了巫妖王的折磨，现在，影之哀伤是你的了。"
D.Strings[32616]="去吧……"
D.Strings[32617]="挥舞这强大的武器，指挥那些赋予它力量的灵魂。"
D.Strings[32618]="去吧，去战胜黑暗的王子。"
D.Strings[32619]="父亲。你的圣洁……让我，感到战栗。"
D.Strings[32620]="父亲……为了你，我万死不辞。"
D.Strings[32621]="达里安，我的孩子。"
D.Strings[32622]="终于，我能够重新见到你了。"
D.Strings[32623]="巫妖王一直在折磨我，达里安。"
D.Strings[32624]="无休无止，他想要击溃我的意志，让我屈服，成为剑中的冤魂……"
D.Strings[32625]="最后，战争让他无暇分身，他才放弃了我。"
D.Strings[32626]="有个回忆，是我的力量，达里安……是让我不被奴役的力量……"
D.Strings[32627]="那就是你的牺牲，我的儿子，再度拯救我于万劫不复。"
D.Strings[32628]="朋友们，帮帮我。让我们召唤卡尔加的幻像。"
D.Strings[32629]="阿尔萨斯……"
D.Strings[32630]="艾泽拉斯的英雄们，你们对我的恩泽远超想象。"
D.Strings[32631]="长久以来，我苦苦地想要宽恕王子的滔天罪行。"
D.Strings[32632]="焦虑和痛苦撕扯着我的灵魂，邪恶的念头……让我远离圣光。"
D.Strings[32633]="麦斯米兰，我已经准备好进行冒险了。"
D.Strings[32634]="我清晰地记得他眼中的光芒，那光芒带着荣耀，带着击败圣光之敌的热切……"
D.Strings[32635]="带着宁死也要保护人民的决心……"
D.Strings[32636]="这就是阿尔萨斯，我要永记于心的阿尔萨斯。"
D.Strings[32637]="朋友，你们的恩情没齿难忘。"
D.Strings[32638]="关掉它，关掉它！这些蛋有问题！！！"
D.Strings[32639]="哦，伙计……"
D.Strings[32640]="我忘不了在洛丹伦的那些日子……"
D.Strings[32641]="……用这把钝剑训练你的剑术……"
D.Strings[32642]="……让你成才，期待着你去完成伟大的使命。"
D.Strings[32643]="呵呵……那些功夫没有白费，不是吗，伙计？"
D.Strings[32644]="如果那天我能阻止你，也许一切都会不一样。"
D.Strings[32645]="要是我从没发现过那把被诅咒的剑……"
D.Strings[32646]="再见了，阿尔萨斯……好兄弟。"
D.Strings[32647]="一切都结束了。"
D.Strings[32648]="我不敢相信这是真的——因为巫妖王已经愚弄我太多太多次了。"
D.Strings[32649]="他对我们犯下累累罪行，现在他终于付出了代价。"
D.Strings[32650]="来吧，侍从$n，冒险正等待着我们！"
D.Strings[32651]="愿艾泽拉斯不要忘记那曾因软弱和傲慢所付出的沉重代价。"
D.Strings[32652]="但现在呢，英雄？那些摆脱了他的束缚，却无法摆脱凡尘俗世的人呢？"
D.Strings[32653]="我的思绪很乱。"
D.Strings[32654]="我想，我要孤身走一段冒险的征程了。"
D.Strings[32655]="没有了血，阿迦玛甘将无法再次崛起！他的躯体在渴求祭品！"
D.Strings[32656]="走！去夺回我们的土地！当野猪人得到了一切，我们也将得到我们所要的。阿迦玛甘将再次崛起！"
D.Strings[32657]="这就是他对我说的……去战斗！"
D.Strings[32658]="我明白了……她在利用他操纵他们所有人……"
D.Strings[32659]="看啊，侍从，那位少女的荷包掉在了葛拉卡温泉的硫磺水中。"
D.Strings[32660]="姑娘！不要害怕，我只是要让你的嘴唇不再颤抖。那个漂在水上的是不是你的荷包？小心，那温泉是很危险的。"
D.Strings[32661]="什么？是的，这是我的……箱子。还有，我不是……"
D.Strings[32662]="你不什么？不会接受我？不必担心，我的心只属于多罗莉亚女士。但像你这样美丽的女子一定能征服许多男人的心。"
D.Strings[32663]="我的侍从会为你取回荷包。"
D.Strings[32664]="除了感觉受到了严重的冒犯，我真不知道该怎样形容我今天的遭遇。谢谢你把荷包还给我。我是说箱子！"
D.Strings[32665]="来吧，侍从。冒险可不会等人！"
D.Strings[32666]="巴尔莫丹……那些矮人……"
D.Strings[32667]="这道伤痕被封印了！感谢塞纳留斯……"
D.Strings[32668]="这……他还留着？一直以来，他还带着它？"
D.Strings[32669]="我知道！"
D.Strings[32670]="我还能感觉到他！饱受摧残……苦苦挣扎……啊，阿尔萨斯！"
D.Strings[32671]="也许……也许有一天，他会想起真正的自己。"
D.Strings[32672]="圣光啊，愿他摆脱那把魔剑的寒冷束缚，魂归故里。"
D.Strings[32673]="又是你……真希望你不曾如此尽心竭力地想要安抚我的灵魂。我早就明白，没有了她，就不会有和平，再也不会有了。$B$B我要将他们的家全部夷为平地。你准备好消灭这些可憎的杀人犯了么？"
D.Strings[32674]="救救我！我的东西都掉在这个热泉里了。$b$b我的长袍就在那里！"
D.Strings[32675]="幸运在召唤我们！一位少女出现在我们面前，她被困在高耸的悬崖上！让我们去拯救她！"
D.Strings[32676]="姑娘！不要害怕，北郡的麦斯米兰将把你从岩壁牢狱中拯救下来！"
D.Strings[32677]="嚯！"
D.Strings[32678]="不要哭，你不会跌向死亡，而是会跌落在我的侍从的臂弯里！现在，松开手吧！"
D.Strings[32679]="在我离开之前，我要告诉你，你会躺在地上不是我的错，而是我的侍从的错。"
D.Strings[32680]="不管怎样，你现在已经摆脱了高山的魔爪，不会再受伤害了。马绍尔哨站大概就在东边。"
D.Strings[32681]="卡鲁亚克钓鱼大赛将在20分钟后开始！"
D.Strings[32682]="卡鲁亚克钓鱼大赛将在10分钟后开始！"
D.Strings[32683]="卡鲁亚克钓鱼大赛将在5分钟后开始！"
D.Strings[32684]="卡鲁亚克钓鱼大赛已经开始了！第一个到达拉然带给我一只黑鳍鲨的参赛者便是本届比赛的冠军！能够钓到小型亚口鱼的地方能都钓到黑鳍鲨。"
D.Strings[32685]="$n在卡鲁亚克钓鱼大赛中取得了胜利！"
D.Strings[32686]="离卡鲁亚克钓鱼大赛结束仅剩10分钟！"
D.Strings[32687]="卡鲁亚克钓鱼大赛将在5分钟后结束！"
D.Strings[32688]="卡鲁亚克钓鱼大赛已经结束了！如果你捉到了一条黑鳍鲨，请在规定时间内把它送到我这。"
D.Strings[32689]="快走吧！到安全的地方去！"
D.Strings[32690]="我曾经是一名圣骑士，$n。由于我罪孽深重，现在圣光已离我远去。$B$B我会尽我所能帮助我的盟友，我绝不会再触碰黑暗的力量。"
D.Strings[32691]="朋友，这是自己造成的创伤。我实在无法面对这样一个在巫妖王的蹂躏下充满恐慌的世界。$B$B这是我救赎之旅的第一站，如果我的罪孽无法得到原谅，我会设法用我的余生加以偿还。"
D.Strings[32692]="欧姆斯，你的眼睛怎么了？"
D.Strings[32693]="我发现我弄丢了我的戒指。"
D.Strings[32694]="丢了？$B$B我真是失望极了，$n。$B$B那只戒指曾是用我们已逝英雄的护甲碎片，加上净化后的敌人刀刃打造的。$B$B这样的事情不要再次发生。"
D.Strings[32695]="不会的。"
D.Strings[32696]="回头吧，朋友，纳迦正控制着北边的那座岛。那里对你不安全。"
D.Strings[32697]="化石探测器3000显示北边有一块巨大的化石。"
D.Strings[32698]="从这里，你能看到大灾变所造成的全部破坏。看到我们的世界竟然如此脆弱，这真是令人胆寒。"
D.Strings[32699]="化石探测器3000显示西北边有一块巨大的化石。"
D.Strings[32700]="化石探测器3000显示西边有一块巨大的化石。"
D.Strings[32701]="化石探测器3000显示西南边有一块巨大的化石。"
D.Strings[32702]="化石探测器3000显示南边有一块巨大的化石。"
D.Strings[32703]="化石探测器3000显示东南边有一块巨大的化石。"
D.Strings[32704]="化石探测器3000显示东边有一块巨大的化石。"
D.Strings[32705]="化石探测器3000显示东北边有一块巨大的化石。"
D.Strings[32706]="现在它发出了亮光。你已经很靠近了！"
D.Strings[32707]="它发出了响亮的“哔哔”声，你距离目标应该只有几步之遥了。"
D.Strings[32708]="它正在发出规律的“哔哔”声，大约每秒钟一次。"
D.Strings[32709]="它正在发出规律的“哔哔”声，大约每两秒钟一次。"
D.Strings[32710]="它每5秒钟发出一次低微的“哔哔”声。"
D.Strings[32711]="它发出的“哔哔”声很微弱。你距离目标还很远。"
D.Strings[32712]="你只能听到极为微弱的“哔哔”声。化石距离你一定还非常非常远。"
D.Strings[32713]="$c，东方吹来了一阵污秽的风。"
D.Strings[32714]="普崔塞德教授驱散了你身上的变异效果！"
D.Strings[32715]="对于治疗这种蔓生，我有一点主意，$c。$B$B不幸的是，纳拉雷克斯已经完全陷入了混乱，拒绝进行任何尝试。"
D.Strings[32716]="腐血打烂小狼人！"
D.Strings[32717]="这会让你明白别管闲事的道理！"
D.Strings[32718]="麦斯米兰，我已经准备好进行更多的冒险了。"
D.Strings[32719]="你这条死笨鱼。"
D.Strings[32720]="死吧，蛇脑袋鱼。"
D.Strings[32721]="如果我钓到你，也只能扔回水里，真是浪费好鱼饵。"
D.Strings[32722]="去舔你的三头叉吧。"
D.Strings[32723]="你惹了不该惹的巨魔，鱼脑袋。"
D.Strings[32724]="你是暗矛的猎物啦。"
D.Strings[32725]="哇哦，你还真是个丑纳迦。"
D.Strings[32726]="喂，兄弟，这里到处都是烂鱼的臭味儿。"
D.Strings[32727]="圣光啊，请赐予我们力量，帮助我们击败安戈洛的邪恶龙女王。"
D.Strings[32728]="圣光啊，请赐予我们勇气，帮助我们与安戈洛的堕落群龙作战。"
D.Strings[32729]="圣光啊，请赐予我们能力，让我们消灭安戈洛的恶龙。"
D.Strings[32730]="我还请求您，在我美丽的多罗莉亚散步时，让鲜花在她的步履间开放。"
D.Strings[32731]="我还请求您，将您的光辉洒在多罗莉亚女士完美无瑕的脸蛋上。"
D.Strings[32732]="我祈求您，当多罗莉亚入睡时召唤来鸟雀，在她的耳边唱起优美的旋律。"
D.Strings[32733]="最后，衷心地请您原谅我的侍从，不要再对他施以惩罚了。"
D.Strings[32734]="最后，我恳求你不要再捶打踩踏我的侍从。"
D.Strings[32735]="最后，我谦恭地祈求您不要再将恨意发泄在我的好侍从身上了。"
D.Strings[32736]="侍从！请在我祈求圣光之灵的祝福时站在我的身边。"
D.Strings[32737]="我接受您的祝福。"
D.Strings[32738]="它还活着，$n。它还活着！"
D.Strings[32739]="你在盯着看什么？没见过天才吗？"
D.Strings[32740]="侍从！我明白你刚刚接受训练不久，但我难道没有告诉过你，不能杀死圣光之灵吗？"
D.Strings[32741]="感谢大地母亲！"
D.Strings[32742]="我又能动了！"
D.Strings[32743]="我要让野猪人付出代价！"
D.Strings[32744]="返回险峻海峡，否则X型蒸汽机械鲨鱼就会神秘地解体。"
D.Strings[32745]="恐怕我现在必须离开你和你的凤凰了。愿圣光照耀你。"
D.Strings[32746]="没错，我会把那些“烟火”列一张表出来。"
D.Strings[32747]="从南海回来后那些东西就能卖大价钱了。"
D.Strings[32748]="你…别以为我看不到你。离我远点！"
D.Strings[32749]="伙计，感谢你提供这么棒的理发、修面服务。"
D.Strings[32750]="因为我就要离开了，所以准备了这么一点额外的东西。"
D.Strings[32751]="我又想了想，整个袋子都拿走吧。我必须，嗯，走了。"
D.Strings[32752]="你真以为我这么容易就会被你困住？"
D.Strings[32753]="绝不能让悲痛的心情削弱我们的力量。我们将并肩作战，以强大的力量击退入侵者。"
D.Strings[32754]="终于盼到我要的援助了！我准备了滑栓需要的各项文书。现在只剩下找人执行了。"
D.Strings[32755]="你真弱，沃金，跟你的父亲一样弱。今天，我将结束这场久远的战争——暗矛巨魔将被彻底扫除干净！"
D.Strings[32756]="我的女王，感谢您接受我们的援助。我向您保证，我们会尽一切所能提供帮助。"
D.Strings[32757]="你知道的，那个闻起来十分的…嘿！别拿那个喷我！"
D.Strings[32758]="一头龙！"
D.Strings[32759]="龙！"
D.Strings[32760]="龙，我要消灭你！"
D.Strings[32761]="我要试试我们的团队。"
D.Strings[32762]="我的责任是测试我们年轻的学徒对于狩猎技艺的掌握程度。$B$B这就是我今天要做的。而那些野猪人就是我们的猎物。"
D.Strings[32763]="大地母亲，我们之中的一员将投入您的怀抱。她就是乌纳雅·鹰风，我的母亲，也是我们所有人的伟大母亲，我们部族中最具智慧的人。"
D.Strings[32764]="愿她飞翔的灵魂拥有您的迅捷，愿风温柔地吹拂她，青草悄声传诵她的名字。"
D.Strings[32765]="看护她，如同她看护我们。让她怀着喜悦之心，通过永恒的安瑟和穆莎凝视看到我们，直到我们和她在死亡中相会。"
D.Strings[32766]="我们全都来自于您，也全都将回到您身边。"
D.Strings[32767]="很高兴你能和我们在一起，$n。对付纳迦可不是一件容易的事！"
D.Strings[32768]="欢迎来到荣耀岗哨， $c！我们已经将这座山谷从部落手中夺了过来，但如果要保持这个咽喉要道的通畅就是另一回事了。"
D.Strings[32769]="你好，$c！荣耀岗哨就在前面。那是联盟在石爪山脉和海岸之间的唯一通道。$B$B根据我的亲身经验，那也是一条充满危险的道路。"
D.Strings[32770]="我来到这里是为了看看能否和那些纳迦建立贸易往来。但他们的回答并不尽如人意。"
D.Strings[32771]="我骨头疼，膝盖疼，脸也疼。我真不应该离开学校。"
D.Strings[32772]="你好，$c。我们萨满祭司聚集在火石岗哨，照看这片土地，治疗它受到的伤害。"
D.Strings[32773]="来吧，用户。我们准备好了逃亡方案。如果你有坐骑，现在就使用它吧。"
D.Strings[32774]="毒气炸药要爆炸了！快找掩护！"
D.Strings[32775]="巨虫正在地下挖洞！"
D.Strings[32776]="她回来了。暗矛部族的仇恨终于要在今天有个了结。$B$B准备好以后就告诉我们，$n。我们绝不会再让她逃走。"
D.Strings[32777]="我准备好了，沃金。"
D.Strings[32778]="你来到这里是个错误，女海巫。你曾经逃脱过我们的复仇。但暗矛氏族不会容忍你再次践踏我们的家园。"
D.Strings[32779]="瓦里玛萨斯？不，他已经有一阵子没来报到了。他无疑是外出完成他的女王交给他的任务去了。"
D.Strings[32780]="瓦里玛萨斯，嗯…不在的时候，我被派来协助布拉贡大人完成任务。"
D.Strings[32781]="由于幽暗城的大部分兵力都已部署在了诺森德的复仇港，酋长派我们来支援幽暗城的防守。"
D.Strings[32782]="夺回烬石村让村民欢欣鼓舞。他们送了些东西来帮助我们对抗被遗忘者。"
D.Strings[32783]="这片土地属于尖啸！牛头人必将毁灭！"
D.Strings[32784]="对赚钱有兴趣吗？"
D.Strings[32785]="我们来到安戈洛只为了一件事：利润。我的同伴我和一直在寻找生意上的合作对象。你有兴趣吗？"
D.Strings[32786]="你好， $n。很高兴见到你在这里。这里简直是一团乱了。"
D.Strings[32787]="你知道吗？贫瘠之地曾经是一片青葱茂密的森林。几千年以前，那时第一次大崩裂还没有发生。卡多雷照料着这片繁荣富饶之地。但随着大陆分崩离析，这一片被撕裂的陆地成为了现在被我们称为卡利姆多的地方，昔日的绿地成为了一片被阳光炙烤的荒芜平原。$B$B当我第一次听说这场恐怖的悲剧时，我就决定要找到办法，让森林重新生长在这片土地上。"
D.Strings[32788]="在研究这片土地的时候，我发现有一座洞穴一直延伸到地下很深的地方。在这片炎热的荒原下面，地下暗河形成的水网覆盖了很大一片地方。我称这座因暗河冲刷而形成的洞穴为哀嚎洞穴。因为风和水流在这座洞中总是会发出一阵阵凄厉的嚎叫。$B$B我相信，这座洞穴是让大地回复生机的契机。暗河中的水已经在贫瘠之地的一些角落里渗透到地面，形成了一些葱翠茂盛的绿洲……如果这种渗水作用得到加强，那么这片土地就会被绿色所覆盖。"
D.Strings[32789]="我的计划是将这些地下水与翡翠梦境直接连通。我带领我忠实的信徒们，进入到哀嚎洞穴深处，在冥想中进入翡翠梦境。通过我的躯体，这个世界和翡翠梦境连接在一起。$B$B然而就在那时，发生了可怕的灾祸。"
D.Strings[32790]="我在翡翠梦境中遭遇了可怖的腐蚀力量，言语难尽其详。无尽的噩梦抓住了我，折磨我的心智。我无法摆脱它的囚禁。我的信徒们无法唤醒我。$B$B无论这种腐蚀来自于何处，它已经通过我的躯体来到了我们的世界。它的能量藉由我进入哀嚎洞穴。那种恐怖的力量扭曲了这里的野生动物，让它们变成了怪物。就连我的信徒们也受到了影响。他们的意识变得疯狂野蛮。他们的身体变得如同巨大的毒蛇。现在他们称自己为毒牙德鲁伊。"
D.Strings[32791]="你是怎样逃脱的？"
D.Strings[32792]="我被我的最后一名信徒穆约和一队冒险者救了出来。我以为我的计划已经彻底失败了。当大灾变到来时，我才意识到，我的计划可以说是过度地成功了！$B$B当贫瘠之地裂开时，巨大的地下水流涌上地表，其中充满了那股在哀嚎洞穴中肆虐的诡异能量。各种生命随之迅速繁衍壮大，无论植物还是动物……都在不受控制地过度生长。$B$B我以为自己能控制自然本身的形态和变化。而现在，我必须为自己的傲慢做出补救。这种生命的蔓生必须被阻止，否则它就会吞没整个自然生态。"
D.Strings[32793]="少女在哪里？"
D.Strings[32794]="我没有看到任何龙。"
D.Strings[32795]="这是个好问题。$b$b温泉的周围，西边悬崖上的烽火，以及北面通往希利苏斯的小路。$b$b这些都是我要去查看的地方。"
D.Strings[32796]="胡说。难道我雇佣了一个瞎眼的侍从？这里到处都是龙。$b$b我的邻居斯巴克说它们是“恐龙”。但我知道龙是什么样子。所以它们必须被消灭。"
D.Strings[32797]="我要把你变成化石，$r！"
D.Strings[32798]="我真是自掘坟墓……"
D.Strings[32799]="见到你真是太好了，罗娜。我们来操纵这些大炮！其他人，把那些憎恶引到开阔地去！"
D.Strings[32800]="小地精？我还记得你们这一族被创造出来的情景。"
D.Strings[32801]="主人的意志不容侵犯…"
D.Strings[32802]="你无法逃脱主人的怒火……"
D.Strings[32803]="我不害怕你的威胁，也不会在乎这些纳迦。为灭亡做好准备吧。"
D.Strings[32804]="没人能阻挡巫妖王的步伐…"
D.Strings[32805]="屈服吧…投入死亡冰冷的怀抱…"
D.Strings[32806]="让你自己摆脱生命的轮回…"
D.Strings[32807]="死亡将你吞噬…"
D.Strings[32808]="你的每个举动都在他的监视之下…"
D.Strings[32809]="在痛苦中哭泣吧…让你的痛消磨你的力量…"
D.Strings[32810]="我已经紧紧控制住了这些小混蛋，$n。当我们控制他们的时候，纳迦是不会攻击我们的。"
D.Strings[32811]="你准备好让他们的首领投降了，$g小伙子:姑娘;？好吧，我们开始吧。"
D.Strings[32812]="嗯，小子，这看上去不太好。我要离开这里！"
D.Strings[32813]="年轻的$n，你现在要死了！"
D.Strings[32814]="克罗雷的部队就在前面！继续前进！"
D.Strings[32815]="加入你父亲的军队，利亚姆。我们一起对抗希尔瓦娜斯。"
D.Strings[32816]="憎恶封锁了通向军事区的道路！这将会是一场硬仗。"
D.Strings[32817]="%s开始施放软泥喷射！"
D.Strings[32818]="封锁退路！利亚姆，把他们赶到计划中的地点去！"
D.Strings[32819]="希尔瓦娜斯！"
D.Strings[32820]="我绝对不会缺席这场战斗。我们出发！"
D.Strings[32821]="让我们看看，当吉尔尼斯人失去了他们顽固的首领时，他们还会有多勇敢！"
D.Strings[32822]="父亲！！！"
D.Strings[32823]="真是浪费。这样的毒箭可不该浪费在你这种小狗崽的身上。我们会再见的！"
D.Strings[32824]="我们做到了，父亲……"
D.Strings[32825]="我们夺回了城市……夺回了……"
D.Strings[32826]="别挡我们的道，否则就让你们的鱼苗吃点苦头！"
D.Strings[32827]="纳迦最好和我们保持距离。我们可不是在开玩笑！"
D.Strings[32828]="我们已经得到了你们的鱼苗。你们最好放明白一些，不要攻击我们！"
D.Strings[32829]="准备向锈水财阀投降吧！"
D.Strings[32830]="我们知道，你们正准备攻击我们。这一切都是你们造成的。"
D.Strings[32831]="不要有任何出轨的举动！我们在谈妥你们的投降条件之后，就会和平地离开。"
D.Strings[32832]="在投降程序完成之后，我们计划进行一场特别的纳迦感恩促销。我们的货架商品绝大部分都会降价30%。"
D.Strings[32833]="我们不想惹麻烦。只要别挡我们的路，一切都不会有问题。没有人会受到伤害。特别是我！"
D.Strings[32834]="好吧，纳迦头领，从你的藏身之地钻出来，向$n和锈水财阀投降吧！"
D.Strings[32835]="别试探我！你根本不知道那些东西里究竟有什么吧？"
D.Strings[32836]="我的女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。"
D.Strings[32837]="喔，那是什么？"
D.Strings[32838]="我们的密探在搜集可用的天灾军团枯萎样本时经历了很多次失败，现在我亲自到前线来视察工作进度。就像他们说的，如果你希望工作能够干好…"
D.Strings[32839]="看起来你和腐面在一起玩的挺开心，但要取得合适的标本，恐怕我同时需要两样东西才行！"
D.Strings[32840]="看起来你和烂肠在一起玩的挺开心，但要取得合适的标本，恐怕我同时需要两样东西才行！"
D.Strings[32841]="炼金师，我沾到了活的枯萎！"
D.Strings[32842]="简直难以置信！你身上覆盖了奇异的活性剧毒枯萎！拜托，请允许我采集这些纯净的标本。我还会帮你的队友清楚残留的感染，并以医学的名义对你们的勇敢和自我牺牲精神加以回报！准备好了以后请告诉我。"
D.Strings[32843]="好了。采集你的标本吧。"
D.Strings[32844]="你在这里什么都得不到。走吧。"
D.Strings[32845]="行行好，我要回到马绍尔哨站。"
D.Strings[32846]="你现在明白了，$n？"
D.Strings[32847]="我的主人需要你。"
D.Strings[32848]="我准备好前往塑造者之台了。"
D.Strings[32849]="我想要返回塑造者之台。"
D.Strings[32850]="立刻出发。我们一定能打倒希尔瓦娜斯。为了吉尔尼斯！"
D.Strings[32851]="跟踪托比亚斯·密斯特曼托，进入教堂区。"
D.Strings[32852]="让我们尽量别被发现，$n。"
D.Strings[32853]="$n，你听到了吗？希尔瓦娜斯正赶往那座教堂。我们要立刻采取行动！"
D.Strings[32854]="快点！藏进水里！"
D.Strings[32855]="你是谁？你想从我们的部族得到什么？"
D.Strings[32856]="娜博亚，是你吗？"
D.Strings[32857]="外乡人，欢迎来到我们的家园。"
D.Strings[32858]="你是来进行观察的吗？想要一个椰子吗？"
D.Strings[32859]="你能教我些什么，大猩猩？"
D.Strings[32860]="你能教我些什么，巨猩猩？"
D.Strings[32861]="你能教我些什么，猩猩？"
D.Strings[32862]="我们部落中的一些人能够驾驭雷电的力量。我们就是用这种力量来抵抗入侵者，不管是人类、兽人还是恐龙。$b$b要知道，我们的雷电能够震晕任何恐龙。"
D.Strings[32863]="个体的力量很重要，但全族的力量更加重要。只有当我们部族中最弱小的个体也强大起来，我们的部族才会真正变得强大。"
D.Strings[32864]="南边的鳄鱼人喜欢吃小动物，比如青蛙和鹦鹉。我们猩猩则喜欢吃鳄鱼人。恐龙喜欢吃猩猩。所有这些都是严肃的自然规律。$b$b人类和兽人也会猎杀猩猩。但他们只剥去我们的毛皮，我们的尸体则被随意丢弃，任由它们腐烂。所以我们才会攻击人类和兽人。"
D.Strings[32865]="天灾军团！发现目标！"
D.Strings[32866]="我明白了，谢谢你。"
D.Strings[32867]="你要让加尔鲁什知道，这只是一次小小的挫折。我们必将在吉尔尼斯取得胜利。"
D.Strings[32868]="小心说话，将军。你和加尔鲁什都不必担心。我们已经服从他的命令，停止施展危害性魔法。如果没有他的许可，我们绝对不会使用那种魔法。"
D.Strings[32869]="荣誉与你同在，将军。"
D.Strings[32870]="这算什么问题？我们当然要按照计划施展魔法！就让吉尔尼斯人去享受他们渺小的胜利吧。到明天，他们就连骨头也不会剩下。"
D.Strings[32871]="你正在失去对吉尔尼斯的控制，希尔瓦娜斯。加尔鲁什担心他恐怕要亲自来指挥这场战争。"
D.Strings[32872]="听起来你很有信心，女王陛下。希望你没有使用伤害性魔法计划。加尔鲁什已严禁使用它。"
D.Strings[32873]="那么，我会向我们的领袖报告的。请原谅，我的女士。"
D.Strings[32874]="我想让你在马绍尔哨站的敌人身上测试你的撕咬技能。"
D.Strings[32875]="|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t对5个人形目标使用撕咬技能。$B$B|TInterface\\Icons\\inv_misc_bone_02.blp:32|t使用骨刺护甲提高你的护甲值。"
D.Strings[32876]="我希望你和当地的猩猩谈一谈。"
D.Strings[32877]="分别找一只猩猩、大猩猩和巨猩猩谈一谈。$b了解一下他们都会教你一些什么。"
D.Strings[32878]="希望你测试一下你的翅膀的极限。"
D.Strings[32879]="飞越这片丛林的树冠。$b$b使用展翼掠飞暂时提高你的飞行速度。$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t"
D.Strings[32880]="我想让你们在彼此身上测试一下血瓣花。"
D.Strings[32881]="在一对一的战斗中挑战并击败另一个血瓣花。"
D.Strings[32882]="你能重新召唤安戈洛测试者吗？"
D.Strings[32883]="安戈洛环形山中的这种花是非常特别的。你说对不对，$n？"
D.Strings[32884]="你能把我传送到上面的水晶塔那儿去吗？"
D.Strings[32885]="女王陛下，我是否要命令手下停止部署魔法？或者我们还是按原计划进行？"
D.Strings[32886]="只要你留在这里，奎尔德拉就会汲取这里的邪能。"
D.Strings[32887]="就像过去一样，对不对， $n？"
D.Strings[32888]="就像过去一样，对不对，$n？$B$B我不算很忙，可以训练你。这些家伙都还不错。"
D.Strings[32889]="有人愿意帮忙吗？还是你需要更多训练，$n？$B$B不知你是否注意到，我现在很忙。"
D.Strings[32890]="你能帮帮我吗？我的法力是有限的。"
D.Strings[32891]="你能帮帮我吗？我的法力是有限的。$B$B当然，如果你需要一些训练……"
D.Strings[32892]="这个地方看上去很不错。只是需要进行一下清洁。$B$B你在找工作吗，$n？"
D.Strings[32893]="这些如芒在背的小混蛋！"
D.Strings[32894]="这些如芒在背的小混蛋！$B$B你需要训练吗？"
D.Strings[32895]="这些俾格米人减少了我的利润！"
D.Strings[32896]="这些俾格米人减少了我的利润！$B$B在寻求教导吗，$n？"
D.Strings[32897]="你已经掌握了诀窍，$n。尽量使用它们！"
D.Strings[32898]="你已经掌握了诀窍，$n。尽量使用它们！$B$B你还想知道一些新的诀窍吗？"
D.Strings[32899]="全能战士NX-01型毁坏！"
D.Strings[32900]="全能战士NX-01型联线运行中！$B$B塞进钱币，获取更多训练。"
D.Strings[32901]="呃…"
D.Strings[32902]="没用的间谍，如果那个空壳，也就是你所谓的脑袋，真装了那么一点儿情报的话，你早已经招了。我受够这一套了。现在去死吧！"
D.Strings[32903]="嗨，你听过那个关于$r$c的故事么？事情是这样的：$b$b一个$r$c走进一座洞穴，开始和猩猩战斗。那群猩猩的头领说：“嘿，你为什么要这么干？！”那个$r$c就说：“是一个地精让我这么干的。”$b$b猩猩头领说：“地精让你干什么，你就干什么？”$r$c回答：“是的，因为我很笨，浑身臭气，而且还用两条腿走路。”$b$b很有趣，对不对？嗯……也许还需要再做些加工……"
D.Strings[32904]="哦，我已经做了这么多了，现在，我怎么才能拿到那些样本呢…？"
D.Strings[32905]="安戈洛环形山的存在有其特殊的意图，$n。现在该是你知道这个意图的时候了。"
D.Strings[32906]="好吧、好吧，看看我们都发现什么了…？你一定知道不少秘密……"
D.Strings[32907]="测试？什么测试？"
D.Strings[32908]="卡兹格罗斯创造的？你说这座环形山里的全部生物都是卡兹格罗斯创造的？"
D.Strings[32909]="为什么你要告诉我这些？"
D.Strings[32910]="娜博亚，我必须问的是……我和我的种族是卡兹格罗斯创造的吗？"
D.Strings[32911]="谢谢你，娜博亚。"
D.Strings[32912]="我是娜博亚，卡兹格罗斯的弟子，安戈洛环形山的使者。我也被称为观察者。$b$b自从我的导师离开艾泽拉斯之后，我就是他的代表。他就是在这里塑造了许多生物。"
D.Strings[32913]="我在观察。看护安戈洛就是我的职责。这里就是我观察的位置。$b$b我还会进行测试，并记录测试结果。这些测试让我能够观察最令我感兴趣的事物。"
D.Strings[32914]="简单的刺激——响应测试。一般来说，我们不会干扰艾泽拉斯的运转。但在安戈洛，我们可以自由地使用更加直接的手段，因为安戈洛是泰坦的试验场。$b$b比如说，卡兹格罗斯想要知道，当他创造的一种生物被暴露在硫磺热泉中的时候，会有怎样的变化。他可以等待千万年，观察，等待这种生物在偶然间跌落入热泉——或是他亲手将这种生物放进热泉中。$b$b在安戈洛，我们就能这么做。"
D.Strings[32915]="不尽然。事实上，这座环形山中的许多生物在我的导师到来之前就已经存在了……$b$b无论是否由我的导师亲手创造，我都对它们进行绝对客观的观察。"
D.Strings[32916]="当大灾变肆虐艾泽拉斯的时候，也打破了保证这一地区处于隐藏状态的屏蔽系统。如此一来，具有智慧的种族发现我就只是时间问题了。$b$b老实说，我们此前并未预见过这种情况。所以现在，我们需要进行一些新的测试。而你，$n，就是我的测试对象。"
D.Strings[32917]="我没有权限回答这个问题。但我可以向你提供一个建议：$b$b找到布莱恩·铜须。$b$b他已经掌握了许多关于我们的线索。而且现在他即将有一个新的发现。帮助他，他也许就能帮助你找到你所需要的知识。"
D.Strings[32918]="夺回吉尔尼斯城的时刻已经到了。"
D.Strings[32919]="让我们夺回我们的城市！"
D.Strings[32920]="利亚姆！！不！！"
D.Strings[32921]="终于，来了个看客！"
D.Strings[32922]="吞噬者在等待着…"
D.Strings[32923]="我会剥下你低贱的灵魂！"
D.Strings[32924]="去注满引擎吧。"
D.Strings[32925]="又是一个属于我们的灵魂！"
D.Strings[32926]="我会尝试封住这道伤疤，$n。绝不让它另一侧的怪物们再钻过来！"
D.Strings[32927]="吉尔尼斯必将复兴。"
D.Strings[32928]="你们的时代结束了，被遗忘者！"
D.Strings[32929]="凡人们，你们将我从那比死亡更可怕的厄运中拯救了出来。如果继续困在那些设备中，我的意志迟早会被巫妖王的巫师们摧毁，我的身体也将遭受永恒的折磨。在你们面前的便是荣耀一时的辛达苟萨——玛里苟斯的配偶。$B$B奈萨里奥的背叛使她受到了致命的创伤，躺在冰冠冰川的积雪中孤独的等待死亡，现在的她完全被仇恨所充斥。然而，恶意之下仍存留着龙之女王的高尚灵魂。我相信辛达苟萨的灵魂还有机会回归安宁。"
D.Strings[32930]="%s施放了|cFFFF7F00窒息毒气弹！|r"
D.Strings[32931]="|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s施放了|cFF00FF00可延展黏液！|r"
D.Strings[32932]="%s开始施放不稳定的实验！"
D.Strings[32933]="普崔塞德教授施放了|cFF00FF00可延展黏液！|r"
D.Strings[32934]="这就是你们的开始与终结之地，凡人们。休想进入主人的密室！"
D.Strings[32935]="你好，$r。我察觉到你对我出现在这里感到困惑。其他人也心存怀疑，不过鉴于我的同胞给他们带来的遭遇，我并不怪他们。$B$B太阳之井事件后发生了很多事，几乎没有一样是好事。我着手开始收拾残局，希望能挽救我此行带来的影响。要说的很多，要做的更多，不过记住这一点：不是蓝龙军团的每个成员都责怪艾泽拉斯的凡人给这个世界带来的祸患。$B$B我们中的某些成员对此有着更深的理解。"
D.Strings[32936]="他真的离去了，是吗？$b$b我……我能感觉到。"
D.Strings[32937]="真的没有办法拯救他吗？$b$b我恐怕永远也无法对此释怀。"
D.Strings[32938]="我…我在哪…？这真是场可怕的恶梦…不过没时间细想了，还有很多事情在等着我汇报！"
D.Strings[32939]="该是上战场的时候了，$n！有你的帮助，胜利的天平一定会向我们倾斜！"
D.Strings[32940]="做好一切准备。兽人使者就要在这座教堂里与希尔瓦娜斯会面了。"
D.Strings[32941]="你嗜血成性！"
D.Strings[32942]="死吧，入侵者！没人能干预教派的计划！"
D.Strings[32943]="我醒了!"
D.Strings[32944]="那里是谁？"
D.Strings[32945]="我们受主人的指挥。"
D.Strings[32946]="死后我们忠心不改。"
D.Strings[32947]="你好，联盟的成员！$B$B作为加基森的官方代表，我的任务是确保我们离散的可怜侏儒们能够与与热砂港地精在加基森和平相处！为此，我们甚至可以容忍他们新的部落地精朋友。$B$B相信有你的帮助，我们能够达成令人愉快的共识！"
D.Strings[32948]="我们再次为主人而战。"
D.Strings[32949]="你为什么要在这寻死？"
D.Strings[32950]="活人不属于这里。"
D.Strings[32951]="我们永远无法摆脱折磨。"
D.Strings[32952]="最终的胜利还没有到来。"
D.Strings[32953]="死后仍为主人效命。"
D.Strings[32954]="这只不过是暂时的休息…"
D.Strings[32955]="我们的灵魂将永无宁日。"
D.Strings[32956]="你好啊，$c！海军司令奥布里正在楼上等你呢。"
D.Strings[32957]="$n，你一定能拯救我们的族人！"
D.Strings[32958]="不要污染调查现场。"
D.Strings[32959]="不要干扰调查工作。"
D.Strings[32960]="别就这么脏兮兮的进来。赶快把身上的脏肉给我弄干净！"
D.Strings[32961]="我会摧毁这道屏障，但你必须挡住那些亡灵！"
D.Strings[32962]="又是一道冰墙！不要让那些亡灵打断我的法术，这样我才能摧毁冰墙。"
D.Strings[32963]="我们就要到了……不要放弃！"
D.Strings[32964]="你的屏障挡不住我们，怪物！我会将它们全部粉碎！"
D.Strings[32965]="没有墙壁能阻挡女妖之王。挡住那些亡灵，英雄们。我会粉碎这道屏障！"
D.Strings[32966]="又是一道！坚持住，勇士们。我会粉碎这面冰墙。"
D.Strings[32967]="我厌倦了你的把戏，阿尔萨斯！你的冰墙阻挡不了我！"
D.Strings[32968]="你们这些恶魔拦不住我们！挡住那些亡灵，我在努力摧毁冰墙！"
D.Strings[32969]="啊！强烈的灼痛！这是什么魔法？"
D.Strings[32970]="地精！！！"
D.Strings[32971]="干掉地精！轰碎他们！"
D.Strings[32972]="地精去死！"
D.Strings[32973]="去死吧，地精！"
D.Strings[32974]="你们活不了多久了！"
D.Strings[32975]="奥布里将军正在楼上等你，$g先生:女士;。"
D.Strings[32976]="让地精尝尝厉害！"
D.Strings[32977]="抓住地精！"
D.Strings[32978]="你逃不出我们的手心！"
D.Strings[32979]="快点，我们会在背后伏击他们！"
D.Strings[32980]="这里有活人？！"
D.Strings[32981]="我自由了！是你救了我！"
D.Strings[32982]="我还以为自己必死无疑了！"
D.Strings[32983]="我觉得我的生命正在离开我。"
D.Strings[32984]="他们要把我变成僵尸！！！"
D.Strings[32985]="我要在他们再次抓住我之前离开这里！"
D.Strings[32986]="真不知道该怎样感谢你！"
D.Strings[32987]="他们把其他人带进了火山口。有些人变成了僵尸，有些人被献祭给他们的海龟神沃卡洛斯！"
D.Strings[32988]="其他俘虏还在火山口里……他们或者是被献祭了，或者下场更悲惨——变成了僵尸！"
D.Strings[32989]="我们必须坚守阵地。如果北方城堡失守，我们就只能背水一战了！"
D.Strings[32990]="指挥官，我能申请一匹坐骑前往黑弹珠号吗？"
D.Strings[32991]="我到这里来可不是为了渡假，朋友。诺格弗格派我来这里完成一个任务：确认该如何从这些异种怪物身上获取利润。如果不行，就将它们消灭干净。$B$B如果像你这样的$r想要为热砂集团做些事情，那么我倒是可以给你个机会。"
D.Strings[32992]="蜂拥的阴影在$n的四周积聚！"
D.Strings[32993]="我甚至不知道该如何使用这件武器……但我相信，如果我摆出一副凶恶的样子，那些狼人也许就会逃到别的地方去。"
D.Strings[32994]="准备去死吧，地精！！！"
D.Strings[32995]="全体上甲板！把他们赶走！"
D.Strings[32996]="队长，我需要坐骑返回北方城堡。"
D.Strings[32997]="万事平安，$c！"
D.Strings[32998]="布兰恩先生？请为$n准备一只狮鹫。"
D.Strings[32999]="是，长官！马上，长官！"
D.Strings[33000]="即使我们能取得胜利，我也要用一个月的时间才能把甲板上的脏东西清理干净。"
D.Strings[33001]="他们顾得上告诉你我是谁或者我在做些什么吗？"
D.Strings[33002]="凯雷塞斯王子获得了鲜血唤醒的效果！"
D.Strings[33003]="瓦拉纳王子获得了鲜血唤醒的效果！"
D.Strings[33004]="塔达拉姆王子获得了鲜血唤醒的效果！"
D.Strings[33005]="但这有什么关系。到了该结束的时候了。"
D.Strings[33006]="巴柯斯特！到这儿来帮帮我！快来！"
D.Strings[33007]="到时候了，进攻！"
D.Strings[33008]="药剂师们！把你们的生命献给皇冠药剂公司吧！"
D.Strings[33009]="同您共事是我一生最大的荣耀。"
D.Strings[33010]="很好。我们不是没种，而是无能。"
D.Strings[33011]="…请不要轻视我。"
D.Strings[33012]="小静，你不会正好知道英格维的躯体在哪儿，对吧？"
D.Strings[33013]="听着，别管我是怎么找到它的。趁还来得及，快把它扔到那蓝色的大篝火里，毁掉英格维的灵魂！"
D.Strings[33014]="…还是说他们只是像利用别人一样在利用你？"
D.Strings[33015]="我们该把克罗雷留在监狱里喂野兽！"
D.Strings[33016]="够了！我已经做出了决定。我们需要克罗雷。"
D.Strings[33017]="还有其它套牌吗？"
D.Strings[33018]="你的提问相当机敏，年轻的$c。铭文师能够制作蕴藏强大力量的塔罗牌，当然即使是铭文师自己也无法完全驾驭他们所创造出来的东西。决定一切的还是命运。$b$b如果你有办法集齐完整的套牌，请把它带给我，你会得到不错的回报。"
D.Strings[33019]="专注于比赛，$n！"
D.Strings[33020]="大家听好，守住阵线！"
D.Strings[33021]="数三下，闪电傻瓜跳着基洛探戈上场。一……二……三！嗯……人呢？！"
D.Strings[33022]="我们要对付翼手龙，鲨鱼，刺角龙，还有扔炸弹的猴子。我们要是能取得胜利，那简直就是奇迹！"
D.Strings[33023]="这可不是玩足球炸弹，孩子们。这是真正的交易！"
D.Strings[33024]="金筛，你准备好出发了吗？"
D.Strings[33025]="难道我们要让那群猴子为所欲为吗？绝不！"
D.Strings[33026]="我现在最渴望的是立刻得到一台海盗队伐木机。"
D.Strings[33027]="加油！锈水海盗队！"
D.Strings[33028]="你好，小子。你干得很不错！$B$B我会在另一边等你。"
D.Strings[33029]="这些关于食物的话题让我更饿了！"
D.Strings[33030]="它害怕了。"
D.Strings[33031]="你知道这是怎样的游戏，小子。干掉他们！"
D.Strings[33032]="$n！你还好吗？"
D.Strings[33033]="天哪！它起作用了！纳瑞安，快来看！"
D.Strings[33034]="它在想什么？"
D.Strings[33035]="它害怕了！"
D.Strings[33036]="灵魂们出现并围在祭坛四周！"
D.Strings[33037]="强能烈焰飞快地冲向$n！"
D.Strings[33038]="保持平静！我们会照顾好大家。"
D.Strings[33039]="我们已经备好了马车，正在等待格雷迈恩国王的命令。"
D.Strings[33040]="看样子，我要亲自割断你的喉咙了！"
D.Strings[33041]="不要慌，我们一定能渡过难关。"
D.Strings[33042]="我有个惊喜给你们，狗儿！"
D.Strings[33043]="%s的血兽获得了血之气息！"
D.Strings[33044]="结束了，高弗雷。东部的领主中已经没有人会支持你了。"
D.Strings[33045]="不……我宁愿早死也不愿有你这样的国王！"
D.Strings[33046]="现在不是自相残杀的时候，$n。"
D.Strings[33047]="我需要一匹马。"
D.Strings[33048]="不，老朋友。我以平等的身份来找你。"
D.Strings[33049]="那么就这样决定。我们将团结全部吉尔尼斯人，将被遗忘者从我们的国土上赶走。"
D.Strings[33050]="克罗雷！你和你的精灵盟友将与国王的军队并肩战斗。不管你是不是受到了诅咒，你仍然受到吉尔尼斯法律的约束！"
D.Strings[33051]="这只癞蛤蟆是你的代言人吗，吉恩？你是以朋友的身份，还是暴君的身份来的？"
D.Strings[33052]="罗娜！"
D.Strings[33053]="遵命，吉恩。约束我们的不是法律，而是某种更为牢固的东西。我的人将服从你的命令，至死方休。"
D.Strings[33054]="他们把科林伍德沉入了海底，但我们还是把她的舰炮拖到了岸上。$B$B只要我有火药，那些野兽肮脏的绿脚就别想踏上这片海滩！"
D.Strings[33055]="正中靶心！"
D.Strings[33056]="哦，这可真疼！"
D.Strings[33057]="你在想什么？这个星期的任务是消灭僵尸？"
D.Strings[33058]="你听说过艾萨拉吗？那里没有僵尸。"
D.Strings[33059]="别担心。僵尸喜欢有脑子的人，所以你是安全的。"
D.Strings[33060]="烟鬼！"
D.Strings[33061]="说话很容易，但行动才有力量，$n$g先生:女士; 。"
D.Strings[33062]="僵尸来了。"
D.Strings[33063]="好啊，看看这些漂亮的旗子。"
D.Strings[33064]="布兰恩先生，向海岸炮兵阵地发信号，让维桑恩先生知道$n就要到了。好，就是现在。"
D.Strings[33065]="兰德鲁的宠物笼"
D.Strings[33066]="霜翼大厅前的最后一道屏障已经被我们击破了，$g小伙子:姑娘;。只有辛达苟萨还挡在正义之师和巫妖王之间！还等什么？！"
D.Strings[33067]="所有的屏障都被击破了，$n！只有辛达苟萨还挡在我们和巫妖王之间。审判即将开始…"
D.Strings[33068]="他太强了！用投石车打倒他！"
D.Strings[33069]="|TInterface\\Icons\\spell_shadow_unstableaffliction_1.blp:16|t%s施放了|cFFFF0000危险实验！|r"
D.Strings[33070]="你没有资格觐见巫妖王！"
D.Strings[33071]="别拿我的齿轮……别拿我美丽的齿轮！"
D.Strings[33072]="嗨！那可是司令最好的银餐具！"
D.Strings[33073]="末日降临。万劫…不复。"
D.Strings[33074]="你能抵挡多久？"
D.Strings[33075]="苏醒吧，奴仆们。拦住他们。"
D.Strings[33076]="奴仆们，抓住他们！带他们的尸体来见我！"
D.Strings[33077]="%s向$n掷出一颗冰冻宝珠！"
D.Strings[33078]="我们在这里的情况相当糟糕，$n。"
D.Strings[33079]="我确定合同里没提过会遇到这种情况！俾格米人，僵尸……这次霍巴特一定要把我晋升到一个足够高的职位才行！"
D.Strings[33080]="我本来以为情况不可能更糟了……"
D.Strings[33081]="我们待在这里干什么？难道我们不应该想办法离开这座岛吗？！！！"
D.Strings[33082]="胶囊镇实在是工程学上的一项伟大成就！"
D.Strings[33083]="$n感染了死亡疫病！"
D.Strings[33084]="现在不是闲聊的时候，侍从$n。我们正在执行任务。"
D.Strings[33085]="入侵者闯入了内室。加紧毁掉那条绿龙！留下龙筋龙骨用来复生！"
D.Strings[33086]="我们要继续前进，找到邪恶的巨龙女王。跟我来，侍从！"
D.Strings[33087]="你应该使用我的坐骑的蹬踏能力。她强有力的蹄子能够踏碎大地，也能把附近的龙全部震晕。"
D.Strings[33088]="运气真好！多香果的蹄子踢起来一些石头，用来对付那些龙正合适。真是愉快的一天！"
D.Strings[33089]="我看见恶龙就在前面。她比我预料得更大。"
D.Strings[33090]="恶龙！听我说！我是北郡的麦斯米兰。我将对你进行正义的审判。你必死无疑……"
D.Strings[33091]="伟大的乌瑟尔之灵，它在追赶我！侍从，想想办法！向它扔石头！我该怎么办？！"
D.Strings[33092]="等等，我有主意了！给，用我受过圣光祝福的盾牌去砸那个怪兽！"
D.Strings[33093]="那个盾牌扔得真好。快，再把我的神圣肩甲扔过去！"
D.Strings[33094]="我把手套也脱下来了。快用它来砸我们的敌人。"
D.Strings[33095]="我的钢板靴子一定能对敌人造成非常严重的伤害。"
D.Strings[33096]="再吃我一记肩甲，邪恶的蜥蜴！"
D.Strings[33097]="如果你能举起我的胸甲，就把它扔出去！为了多罗莉亚把它扔出去！"
D.Strings[33098]="这副样子可不好看……不过很凉快。希望我的腿甲能对敌人造成致命一击。"
D.Strings[33099]="我们成功了！安戈洛得到了净化。"
D.Strings[33100]="侍从，去我的营地找我，接受我的酬金吧。"
D.Strings[33101]="好啊，$n！这不中看，但是很中用。"
D.Strings[33102]="也许你应该试着将它们抛向附近的恶龙。这样也可以锻炼你的臂力。"
D.Strings[33103]="麦斯米兰把他的盾牌交给你。把它向那头魔暴龙，呃，……那头恶龙扔过去！"
D.Strings[33104]="不住手地扔出麦斯米兰的铠甲！"
D.Strings[33105]="你的生命值太低了。请让我帮助你。"
D.Strings[33106]="为什么这些绷带闻起来有一股汗臭味？"
D.Strings[33107]="谢谢。我们已经损失惨重……"
D.Strings[33108]="这些绷带可真臭！不过我也许不应该抱怨。"
D.Strings[33109]="我应该能自己回到城堡去……"
D.Strings[33110]="不能……放弃……"
D.Strings[33111]="到处都是兽人和巨魔！"
D.Strings[33112]="为佩戴，握持或以其它方式使用锈水财阀求生火箭，你同意接受此最终用户协议的全部条款！"
D.Strings[33113]="每个求生火箭的合同期为两年，一切合同条款最终解释权以及仲裁权属于锈水财阀！"
D.Strings[33114]="锈水财阀感谢您使用本企业产品，并期待您继续购买本企业产品！"
D.Strings[33115]="只要你一落地，我们的锈水财阀代表就会帮助你确定合适的酬金计划！"
D.Strings[33116]="请一定在飞行过程中填写好全部的相关文件！"
D.Strings[33117]="不可能……霜牙……警报……"
D.Strings[33118]="低劣的顽抗，死亡是对你的优待。"
D.Strings[33119]="也许你早应该留在……群山里！"
D.Strings[33120]="我不会让巫妖王失望的。准备受死吧！"
D.Strings[33121]="教练，我能再用一下火箭靴吗？"
D.Strings[33122]="当然，小子！"
D.Strings[33123]="格瑞里，为什么超级助推火箭之靴只对僵尸有用？"
D.Strings[33124]="很高兴你这样问，$n！$B$B还从来没有人来问过这东西是怎么运作的。他们要不来了就说：“把它给我，我要炸东西了。”要不就是：“别拿那些细节的事情来烦我，我只需要瞄准和射击。”还有更糟的：“谁在乎它是怎么运作的，这次爆炸不是比上一次更壮观吗？”$B$B我发誓，有时候我真的很想尖叫。霍巴特总是把他的工作全都扔给我，我辛辛苦苦地做完了，却根本得不到承认！我一定是最不被承认，最过劳，所得报酬最不合理的工匠助手！$B$B等等，你刚才在问什么？"
D.Strings[33125]="麦斯米兰，我已经做好了出发的准备。"
D.Strings[33126]="幸好我很喜欢建造船只，因为那些海盗总喜欢把船炸飞。"
D.Strings[33127]="梅格斯派我来取一艘小艇。"
D.Strings[33128]="%s施放了不稳定的软泥怪黏合剂！"
D.Strings[33129]="%s施放了毒肿！"
D.Strings[33130]="谢谢你，我欠你一条命。"
D.Strings[33131]="是的，是的，这非常有趣。但你要知道，我们正在为生存而战。和藏在那座洞里的东西相比，这些俾格米人根本算不上什么问题！$B$B我那个没用的助手在哪里？我现在可是非常需要她呢！也许她又去偷懒了。我猜她肯定还在抱怨没有人关心她，没有人看重她……"
D.Strings[33132]="不要吵，女士！"
D.Strings[33133]="你的叫嚷已经让大家忍无可忍了。安静一些。"
D.Strings[33134]="女士，你需要把声音降低一些。"
D.Strings[33135]="没有人想要你的面包，女士。我们只想你能安静一些。"
D.Strings[33136]="任何地方，除了这里…"
D.Strings[33137]="我怎么了？？！"
D.Strings[33138]="我的脸！我的脸怎么了！"
D.Strings[33139]="我的手……不要看我的手！！"
D.Strings[33140]="阻止它！"
D.Strings[33141]="我无法对抗它！"
D.Strings[33142]="巴斯东！击退闯入者。"
D.Strings[33143]="我已经准备好引导我们的异种虫了。"
D.Strings[33144]="这只猎犬能帮你找到那些隐藏的狼人。"
D.Strings[33145]="好的，老板。我会完成的。"
D.Strings[33146]="这就是你得到的报应，“妖术大师”？"
D.Strings[33147]="尖叫吧，小猪！"
D.Strings[33148]="呸！你的影子吓唬不了任何人，巴斯东。这家伙是我的了。"
D.Strings[33149]="哈！软蛋！你大概也只有这点能耐。"
D.Strings[33150]="不，不！这片土地……是我们的……"
D.Strings[33151]="不应该让这些食人魔坐在沙子里，浪费生命。他们能够加入部落，为我们工作。$B$B我倒是要看看！如果我们不能利用他们，还有谁能？"
D.Strings[33152]="想要什么？"
D.Strings[33153]="食人魔看起来很有趣。"
D.Strings[33154]="我不喜欢沙子。"
D.Strings[33155]="你签文件！太好了！"
D.Strings[33156]="我们有制服吗？"
D.Strings[33157]="我还是很饿。"
D.Strings[33158]="谢谢，有趣的食人魔！"
D.Strings[33159]="阅读让我头痛。"
D.Strings[33160]="……俺忘了你说过啥。"
D.Strings[33161]="好吧，我签。"
D.Strings[33162]="我的力量衰减了……蠢货！我一定会回来取你性命！"
D.Strings[33163]="请来帮帮忙！"
D.Strings[33164]="救救我，救救我！"
D.Strings[33165]="我在流血！"
D.Strings[33166]="医生！救命！"
D.Strings[33167]="真疼！"
D.Strings[33168]="马上就来！"
D.Strings[33169]="我只有两只手和两只脚！"
D.Strings[33170]="希望我还有点绷带！"
D.Strings[33171]="我需要助手！"
D.Strings[33172]="一定要有人去对付那个洞里的大海龟！"
D.Strings[33173]="真是让人筋疲力竭！"
D.Strings[33174]="20毫升卡亚可乐，注射！不是给病人……是给我！"
D.Strings[33175]="我已经注意到你了，馅饼小贩。"
D.Strings[33176]="我们全都认识你，还有这种香气和玫瑰花瓣。它多漂亮啊！"
D.Strings[33177]="我们在注意你，馅饼小贩。"
D.Strings[33178]="小心，馅饼小贩。不要惹祸上身。"
D.Strings[33179]="我们已经收到了一些关于你的馅饼的投诉。你做事可要小心一些！"
D.Strings[33180]="安静些，水果贩子！"
D.Strings[33181]="很多人都在抱怨你过于吵闹。安静一些！"
D.Strings[33182]="我们已经收到投诉，说你的水果不像你所宣扬的那样新鲜。"
D.Strings[33183]="我们听说，你正在贩卖一些坏掉的苹果。"
D.Strings[33184]="我们正在注意你，肉贩子。"
D.Strings[33185]="在这里做买卖可要小心一点，肉贩子。"
D.Strings[33186]="我们得到报告，有不少人因为吃了腐败的肉食而生病了。我们会盯着你的，肉贩子！"
D.Strings[33187]="要记住你是在什么地方，肉贩子。"
D.Strings[33188]="给我看看天灾领主的护甲，欧姆斯。"
D.Strings[33189]="我想要参加这场战斗。"
D.Strings[33190]="吉尔尼斯城之战正在进行！你可以直接到前线去，或者等待我们的队伍重新集结，展开下一波进攻。"
D.Strings[33191]="我们的战士正在重新集结。再过几分钟，他们就能做好战斗准备。"
D.Strings[33192]="我帮助地精女士和食人魔交朋友。"
D.Strings[33193]="嗨，食人魔。现在你的部族已经签好了文件。但我们该怎样说服他们真正为我们工作？"
D.Strings[33194]="给食人魔喜欢的东西。给食人魔觉得有趣的东西。"
D.Strings[33195]="那些异种虫？那些东西令人讨厌，而且根本不能吃……哦，根本不能吃。"
D.Strings[33196]="你好，英雄。我制造和出售德鲁伊需要的树纹套装。"
D.Strings[33197]="……俺不懂你说的啥。"
D.Strings[33198]="你好，英雄。我制造和出售萨满祭司需要的霜巫套装。"
D.Strings[33199]="你好，英雄。我制造和出售潜行者需要的影刃套装。"
D.Strings[33200]="你好，英雄。我制造和出售猎人需要的安卡哈猎血套装。"
D.Strings[33201]="你好，英雄。我制造和出售战士需要的伊米亚之王套装。"
D.Strings[33202]="你好，英雄。我制造和出售圣骑士需要的光誓套装。"
D.Strings[33203]="你好，英雄。我制造和出售牧师需要的血色侍僧套装。"
D.Strings[33204]="你好，英雄。我制造和出售法师需要的血法套装。"
D.Strings[33205]="你好，英雄。我制造和出售术士需要的黑巫套装。"
D.Strings[33206]="哦，食人魔喜欢吃虫子。去西边弄虫子。"
D.Strings[33207]="灵魂们再次复苏！"
D.Strings[33208]="别碰那火，讨厌的巨魔！放弃反抗，去死吧。"
D.Strings[33209]="不！我会让你死得既漫长又痛苦，小巨魔。"
D.Strings[33210]="你这蠢货竟敢碰我的火焰！等沃金死掉，你就是下一个！"
D.Strings[33211]="这是什么？！放开我！"
D.Strings[33212]="这样不对——不应该，不应该就这样结束的。"
D.Strings[33213]="巨浪将会升起，吞没你的部族，沃金！你们不应该回来的！"
D.Strings[33214]="她正在从火焰中吸取力量！赶快扑灭火盆！"
D.Strings[33215]="解决那些鬼魂！我们来对付扎尔吉拉。"
D.Strings[33216]="<你在路旁发现了这名不幸的士兵，他的身上有许多仿佛是用长匕首划开的伤口。你将他的身体翻转过来，注意到一些齿印。>$B$B<这会是野兽干的吗？>"
D.Strings[33217]="那个女海巫就在这里，我能感觉到她。耐心等待，她很快就会从她的洞里出来了。"
D.Strings[33218]="结束了。我们古老的敌人被击败了。"
D.Strings[33219]="为了清算我父亲的仇恨，我已经等待了很长时间。现在，这副重担终于卸下了。"
D.Strings[33220]="我必须回到暗矛要塞去。当瓦妮拉结束对这个孩子的治疗以后，请到那里去找我。"
D.Strings[33221]="恐怕我救不了我们的兄弟了……女海巫的力量夺走了他的灵魂。"
D.Strings[33222]="我会派人来取回他的尸体，让我们为他举行一个告别仪式……希望还有些什么是我能做的。"
D.Strings[33223]="沃金回去得太急了，不过我会把所有人安全地带回去。准备好了就告诉我一声，兄弟。"
D.Strings[33224]="古老的仇恨在今天得以消弭。"
D.Strings[33225]="喂，$n。让我们来看看这根疯狂的棒子能做些什么……"
D.Strings[33226]="有趣。非常……有趣。"
D.Strings[33227]="太奇怪了。我听说贫瘠之地非常……贫瘠。$B$B而这片森林在昨天晚上才冒出来，现在却已经吞掉了我的营地，还把道路堵住了！"
D.Strings[33228]="你是来参加狩猎的吗，$n？"
D.Strings[33229]="滚吧，$c。我的狩猎不需要你。"
D.Strings[33230]="是龙虾！？"
D.Strings[33231]="抓住它！你在说什么！？"
D.Strings[33232]="快躲开沃卡洛斯的呼吸！"
D.Strings[33233]="停止射击，你这个老白痴！你要打死人了！"
D.Strings[33234]="坚持住，老朋友！"
D.Strings[33235]="%s已经可以捕捉了！"
D.Strings[33236]="如果要使用恐怖图腾拍卖服务功能，你必须首先得到玛加萨·恐怖图腾的许可！"
D.Strings[33237]="$n，救命！这绳子……救命……"
D.Strings[33238]="解开"
D.Strings[33239]="啊，感谢你！应该说……谈判是按照计划进行的。"
D.Strings[33240]="我应该能自己回营地了。"
D.Strings[33241]="你要纸干什么？"
D.Strings[33242]="你想要使用什么？"
D.Strings[33243]="别担心，你的钱在我们这里很安全。"
D.Strings[33244]="我已经填好了进入银行所需的文件。"
D.Strings[33245]="坚持住，$n！我们必须马上离开这里！"
D.Strings[33246]="鲜血……更多的鲜血！"
D.Strings[33247]="女海巫死了，我们夺回了家园，但我们的未来仍然充满未知数。"
D.Strings[33248]="有一个人能为我解惑。如果你愿意，就留下来看看。"
D.Strings[33249]="我并不喜欢加尔鲁什，但离开部落对我来说，是一个非常艰难的决定。"
D.Strings[33250]="确实有人想要杀死我，但这并不是我现在最关注的问题。这个世界正需要我的帮助。"
D.Strings[33251]="萨尔，很高兴你一切平安。我听到了可怕的消息。"
D.Strings[33252]="沃金，我选择加尔鲁什，是因为他有能力率领人民渡过这艰难的时代。"
D.Strings[33253]="我的朋友，我需要你的建议。加尔鲁什使人民自相残杀，我不能支持他这样做。我尊敬你，但我不会因此继续效忠于新的部落……我要带着我的族人离开了。"
D.Strings[33254]="即使我倾尽智慧也曾多次几乎无法维持部落的团结。天谴之门和幽暗城就是最好的证明。"
D.Strings[33255]="部落渴望一个旧时代的英雄，一个血统纯粹，不会向人类低头，不会容忍背叛的兽人。一位能让人民重活荣耀的战士。加尔鲁什就是这样的英雄。"
D.Strings[33256]="我明白，兄弟。我会自己考虑，不再打扰你了。你还要去拯救这个世界。"
D.Strings[33257]="你强壮而又高傲，年轻人。你将为暗矛部族带来巨大的胜利与光荣。"
D.Strings[33258]="Throm'ka，老朋友。"
D.Strings[33259]="这是一个艰难的时代，但是为了所有人的利益，我们会继续帮助部落。"
D.Strings[33260]="萨尔的话是正确的，一如既往。组成部落的并不只是几个顽固的老领袖和从诺森德回来的英雄。人们在呼喊加尔鲁什的名字……至少现在是如此。"
D.Strings[33261]="那么，你想要找到传说中的沙怒之剑？$B$B为了寻求财富与权力，你已经准备好为苏萨斯而杀戮？将热血泼洒在黄沙之上？$B$B既然如此……欢迎来到这片沙漠，朋友。"
D.Strings[33262]="我要让你看样东西。亲眼看到它，你就会明白了。"
D.Strings[33263]="Eekrala gree-kay。以血与荆棘……"
D.Strings[33264]="来自泥土的新生命。死亡之土……得到重生。"
D.Strings[33265]="他们来了……<哼哼>漂亮的$r，是么？真漂亮……"
D.Strings[33266]="就凭你们的人对我们所做的一切，你们也不配继续占据这片土地！离开这里，否则狼人的怒火就要把你们烧毁！"
D.Strings[33267]="别跟我顶嘴，巨魔。你清楚现在掌权的是谁。难道你没有自问过，为什么萨尔选择了我，而不是你？"
D.Strings[33268]="这没什么好想的，加尔鲁什。他之所以给你这个头衔，是因为你是格罗姆的儿子，因为人们想要一位战争的英雄。"
D.Strings[33269]="你不是我的酋长。你并没有赢得我的尊敬，我也不会眼睁睁地看着部落因为你对战争的渴望而毁灭。"
D.Strings[33270]="我知道我将会怎样做，地狱咆哮之子。我会静静等待人们逐渐意识到你没有能力担当这个职位。最终，他们会像我一样离开你。"
D.Strings[33271]="你这是自掘坟墓，巨魔。"
D.Strings[33272]="你很走运，我没打算现在就干掉你。你竟然蠢到以为可以用这种口气和你的酋长说话。"
D.Strings[33273]="你觉得你到底能做什么？你的威胁是空洞的。和你的同类一起滚到贫民窟去吧，我已经无法容忍你这种渣滓继续留在我的王座旁边了。"
D.Strings[33274]="你最终只能得到彻底的失败，你的“力量”将变得毫无意义。到时候，我会无声迅捷地结束你的统治。"
D.Strings[33275]="%s在沃金面前的地上啐了一口。"
D.Strings[33276]="$n，快点！到这里来！！！"
D.Strings[33277]="哎呀呀，它可真扎人啊！$G他:她;骗了我们。杀掉$G他:她;，杀掉！"
D.Strings[33278]="我会确保暗矛巨魔顽强屹立，发挥出它所应有的力量。"
D.Strings[33279]="我在开玩笑，朋友。我很久以前就找到了迦萨斯，从而同时拥有了它的两半……但有个狡诈的家伙趁着黑夜把其中一半偷走了。"
D.Strings[33280]="现在，桑萨斯终于又是我的了。而你只能在这里找到……你新鲜的坟墓。"
D.Strings[33281]="小心！鞭笞者苏萨斯要复活了！"
D.Strings[33282]="够了……如果我死了，沙顶酋长就不可能奖励我了，对不对？再见，朋友……最好永远别见了。"
D.Strings[33283]="你可以信任我们的拍卖师。"
D.Strings[33284]="我已经填写了进入拍卖行所需的全部文件。"
D.Strings[33285]="这已经不是我第一次在古怪危险的丛林中拼尽全力挣扎求生了。我去过这个世界的许多地方，$g孩子:姑娘;，如果我会在这里完蛋，那我也只不过是个没用的家伙。"
D.Strings[33286]="给我讲个故事，老脏鬼佩蒂！"
D.Strings[33287]="在很久以前，我和我的同伴根本没有几个钱喝酒。几番豪饮之后，我们就花光了所有的铜板，搞得连每天的日常酒钱都没了着落。$B$B于是我们决定上老巴克的啤酒馆去，从他堆在酒馆顶楼上那些硕大的啤酒桶里“征收”一桶来。$B$B说干就干，我们用短柄斧砍断了支撑酒桶的架子，好家伙，那满满装着啤酒的酒桶就这么从茅草屋顶上滚了下去，就好象一只从巢里掉出来的鸟崽，呃，应该是只大胖鸟，能轧死人的那种。"
D.Strings[33288]="知道为什么他们管它叫刚强烈酒吗？因为它曾经一直从山上滚下来。那时你可没办法和它商量，和它讲道理。它根本不懂得同情，不知道后悔，也绝不会害怕。$B$B那简直就像是一场啤酒雪崩，要是在那里死掉绝对算得上是轰轰烈烈。$B$B酒桶在撞到山下的孤儿院时炸开了。我立刻大张着嘴扑到了满是酒液的泥地里，然后……我记不清那个故事是怎样结尾的了。想要看看我的刺青吗？$B$B<老脏鬼佩蒂脱下了裤子。>"
D.Strings[33289]="看到这杆枪了吗，$g小子:小妞;？$B$B<老脏鬼佩蒂满不在乎地在你面前挥舞着他的武器。>$B$B这杆枪去过诺森德以外的每一块大陆。我已经数不清它救过我几次命了，大概七次吧。有一次，“大麦克”麦当高——我说的可不是那个小麦当高，而是他的老爹。那家伙想要用他最年轻的女儿和我换这杆枪。$B$B要知道，爱蒂可是个有趣的女孩。她和我的枪有很多相同的地方——嘴很大，还是大龅牙，很容易走火，一走火就能把你烤个半熟。$B$B你有没有听说过那个小爱蒂和查克·白酒须用25枚银币打赌的故事？他们赌的就是爱蒂能一脚踢在查克的脑袋上，让查克疼得大哭鼻子！"
D.Strings[33290]="唔，这消息以惊人的速度传播。没过多久，米奈希尔港的所有人都聚集了起来，有些人开始打赌，水果小贩则干脆就地做起了生意。他们就具体的规则进行了冗长的争论，直到镇长亲自出面他们才达成了共识：擦血不算输。$B$B就这样，查克跪倒下去，她则在一只凳子上挺起身，扬起她的那条大粗腿——我好像扯远了。重点是，我当时真应该接受那提议，因为这把枪现在有点儿不灵光了。"
D.Strings[33291]="他们一直都叫我老脏鬼佩蒂。$B$B不过我也有过又年轻又脏的时候。那时我曾经打算用自己的雕刻工艺吸引一个名叫贝丽的姑娘。她可真是个肉感的甜心。$B$B老贝丽！她就完全是另一回事了。我的那个贝丽可不一样。她的身上除了中间的一段细腰之外，都是那么丰满，真是该多么漂亮就有多么漂亮。$B$B所以我找了一块像她的皮肤一样雪白的石灰石，打算雕出了一件惊世杰作。但我把比例全搞错了。最后，我只弄出一个奇怪的大块头。应该叫它什么呢？枪靶子吧！"
D.Strings[33292]="听我说，$g小子:小妞;，一个枪靶子可不能当作送给女士的礼物。但我还是很喜欢它。所以我把它送给了当地的酒馆做装饰品。$B$B他们管它叫脏鬼佩蒂的屁股。最后就连那家酒馆也被叫成这个名字了。可恨的是，那家酒馆后来被兽人烧成了一块黑炭。现在那里只剩下了我那个变黑的大屁股嵌在一堆残垣断壁上。$B$B<老脏鬼佩蒂的眼眶里落下一滴泪水。>"
D.Strings[33293]="在那场战争中——我说的是很早以前的那场战争。那时兽人好似都还骑着龙打仗？总之，我和威斯利从南海镇出发，前往米奈希尔港。我们只乘着一艘用多节的松木做成的独木舟，肚子里灌满了樱桃酒。$B$B因为周围只有海水，所以我们很难判断走了多远的路。不过，应该是在走完三分之一路程的时候，我感到我的脚被打湿了。"
D.Strings[33294]="现在，$g小子:姑娘;，让我和你说说那根长满瘤子的老松木吧。它的确是有很多瘤子和疖子。$B$B那些节瘤让松木上多了许多窟窿，用这种木材可做不出好的独木舟来。我要给它上面涂一层柏油，威斯利却不同意。所以我们决定用拼酒来达成一致。$B$B酒喝光了以后，我们开始抽出匕首来对打。当然，我们只是要比试一下。$B$B不管怎样，那艘松木船最后也没能到达米奈希尔港。我相信我们之中至少有一个人，或者两个人都溺水了。"
D.Strings[33295]="听起来情况相当严重。"
D.Strings[33296]="再给我讲个故事，老脏鬼佩蒂！"
D.Strings[33297]="哭鼻子！？"
D.Strings[33298]="一只桶？"
D.Strings[33299]="这可不好。"
D.Strings[33300]="这个我听过了。再给我讲一个吧……"
D.Strings[33301]="哦，天哪！你的背后！！！"
D.Strings[33302]="你应该经常注意一下自己的背后和你身边的阴影。只有这样，当你的血慢慢流干的时候，你才会知道究竟是谁射出了那支夺去你生命的利箭。"
D.Strings[33303]="你说你和萨尔说过话？我听错了吗？"
D.Strings[33304]="彼此彼此，“酋长大人”。"
D.Strings[33305]="砍掉这些过度生长的植物！如果这样还没有用，我们就必须烧光它们了。"
D.Strings[33306]="我喜欢你思考的方式，布瑞哲沃特。"
D.Strings[33307]="这就是你的计划，缇甘？点火烧光一切挡路的东西？"
D.Strings[33308]="%s拍中了他脖子上的一只蚊子。"
D.Strings[33309]="可恶！我们只能连砍带烧地向前线指挥站前进了。"
D.Strings[33310]="要我说？不。"
D.Strings[33311]="贫瘠之地仿佛在一夜之间就变得林木茂盛，郁郁葱葱，难道你对此一点也不感到奇怪吗？"
D.Strings[33312]="着火了！！"
D.Strings[33313]="肮脏，可憎，臭气熏天的野兽！"
D.Strings[33314]="我正在谈你和老脏鬼佩蒂。"
D.Strings[33315]="耶哦！！！"
D.Strings[33316]="嘿，那些野猪人真是脏得要命。"
D.Strings[33317]="%s大声地打着嗝。"
D.Strings[33318]="要是你有胃口，贫瘠之地可是个打猎的好地方。"
D.Strings[33319]="我们和前线指挥站还没取得联系。但多亏了你和那些野猪人的“沟通”。只要再做些努力，就能重新打通道路了。"
D.Strings[33320]="下士是个好人，但一执行命令就变得鼠目寸光。$B$B这地方好像有什么不对劲，$n。这片丛林不该出现在这里！"
D.Strings[33321]="人们对迅猛龙的了解只限于野蛮凶残，除此之外知之甚少。实际上，他们的忠诚和机智超乎你的想象。"
D.Strings[33322]="出发了宝贝儿。我来掌舵，你留心周围。"
D.Strings[33323]="好吧，快把救生火箭包扔给下面的幸存者，把炸弹扔给海盗。可别搞混了，知道吗？"
D.Strings[33324]="紧急情况4，取消行动！"
D.Strings[33325]="城里见，宝贝儿！"
D.Strings[33326]="我们即将驶抵胶囊镇……"
D.Strings[33327]="哦不！人都去哪儿了？我把他们放在这儿的！"
D.Strings[33328]="%s开始发动强能震荡涡流！"
D.Strings[33329]="在后座上坐好。我们马上就要离开这里了。我知道我们的兽人老朋友在哪儿！"
D.Strings[33330]="$n，注意背后！小心！"
D.Strings[33331]="来啦！部落来啦——$n，小心身后！"
D.Strings[33332]="|TInterface\\Icons\\ability_creature_cursed_01.blp:12|t %s开始释放|cFFFF7F00邪恶毒气！|r"
D.Strings[33333]="你想要加入对抗纳迦的战斗吗？"
D.Strings[33334]="是的。你有迅猛龙可以带我过去吗？"
D.Strings[33335]="滚开，怪物！别盯着我！我知道我很丑！"
D.Strings[33336]="你不丑，莉莉安……你跟我们一样。来，看看这面镜子，看看你自己的样子。"
D.Strings[33337]="你不明白……我不能变成亡灵！我不能，现在不能……"
D.Strings[33338]="父亲，不！等等……我在哪里？"
D.Strings[33339]="啊！滚开，魔鬼！"
D.Strings[33340]="你在这里干什么？离开这儿！"
D.Strings[33341]="我是来救你的。"
D.Strings[33342]="首先，我不需要被援救。第二，我绝不会让你这样的憎恶来救我！"
D.Strings[33343]="莉莉安，你是被遗忘者，就像我一样。可问题是——为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。"
D.Strings[33344]="为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。"
D.Strings[33345]="我不是亡灵！至少很快就不是了。我父亲会来救我，我知道……"
D.Strings[33346]="你父亲？"
D.Strings[33347]="先是科赞，现在又是这里。如果不马上离开这座岛，我们就要被烤熟了！"
D.Strings[33348]="时间到了，我的小俘虏……你父亲那里传来了消息。"
D.Strings[33349]="盖比勒，你来了！他怎么说？"
D.Strings[33350]="高阶牧师沃斯已经抛弃了你这个女儿。他要求立刻把你处死。"
D.Strings[33351]="什么？不！这不可能！盖比勒，你了解我……我们曾经是朋友！"
D.Strings[33352]="高阶牧师对你失望不已。他曾经以为，你终有一天会成为我们对抗敌人的一件强大武器。"
D.Strings[33353]="不幸的是，你活着的时候就太过危险，成为亡灵后变得更加危险。受死吧，天灾女巫……"
D.Strings[33354]="生者的世界已经抛弃了我，但我并不是该诅咒的天灾亡灵。走吧。"
D.Strings[33355]="是……等等，安静！我听到那名军官正向这里走来。"
D.Strings[33356]="盖比勒，父亲，为什么你们……"
D.Strings[33357]="作为暗矛部族的一员，是我最大的光荣。沃金将领导我们赢取巨大的荣耀。"
D.Strings[33358]="我如同羊群前的雄狮，但它们不畏惧我。"
D.Strings[33359]="也不敢畏惧。"
D.Strings[33360]="这是值得庆祝的一天，也是应该追悼的一天，英雄……"
D.Strings[33361]="英雄，我们还不知道未来的目标在哪里。但我们知道，如果没有你的帮助，我们在这里将一事无成。$B$B黑锋骑士团向你致敬。"
D.Strings[33362]="寒冷和黑暗在向我招手……"
D.Strings[33363]="请从寒冷中拯救我！"
D.Strings[33364]="我回来是为了结束我所开始的一切，暗矛巨魔。这些岛屿将成为你的墓地。"
D.Strings[33365]="立……正！"
D.Strings[33366]="沃金，你的父亲是个无能的家伙。我很愿意从你的身上吸取生命，就像对他一样。"
D.Strings[33367]="啊，又一名暗矛战士被放到了我的祭坛上。一个接一个，你们终将彻底毁灭。"
D.Strings[33368]="这次萨尔不会来拯救你们了，暗矛巨魔。躲到阴影中去吧，我会将你们逐一猎杀。"
D.Strings[33369]="潮水将会冲走整个暗矛部落。"
D.Strings[33370]="软弱的巨魔们，你们已经没有希望了。潮水已预言了你们的灭亡。"
D.Strings[33371]="当我消灭掉你们一族之后，我会去干掉那些该死的兽人。他们曾经在我的怒火中救过你们一次。但这次历史不会重演了。"
D.Strings[33372]="离开你们安全的城市是愚蠢的。当你们回到大海上的时候，你们的灭亡就注定了。"
D.Strings[33373]="武装……准备！"
D.Strings[33374]="枪托上肩！"
D.Strings[33375]="格兹沃德，睁大眼睛。"
D.Strings[33376]="赫姆伯格，你上次清理武器是在什么时候？"
D.Strings[33377]="巴克利，我们闭上眼睛就没法瞄准了！"
D.Strings[33378]="记住，在看清楚他们眼睛的颜色之前绝不能开火。"
D.Strings[33379]="很快。但还不够快。我们再做一遍。"
D.Strings[33380]="杰克逊，你把火药洒得到处都是。<叹气>"
D.Strings[33381]="先生们，我们的工作是杀敌。这是个美妙的工作。"
D.Strings[33382]="放松。"
D.Strings[33383]="我们正在做饭，$n。"
D.Strings[33384]="快来尝尝！"
D.Strings[33385]="长官，这些雷角蜥蜴真是麻烦。"
D.Strings[33386]="要知道，我衷心感谢你的帮助，$c。我们在这里的敌人并不是普通的野兽，而是兼具狡诈与疯狂的怪物。我们必须团结一致，否则就会被它们逐一击破。"
D.Strings[33387]="$c，你叫什么名字？$n？欢迎来到贫瘠之地。你正站在我们在这片大陆上最重要的前锋阵地之一。如果你能帮助我们，我会感到非常荣幸。"
D.Strings[33388]="暗矛部族绝不会再次屈服，女海巫。我们的力量远远超过了你的想象。"
D.Strings[33389]="让我去踩灭那妖火！"
D.Strings[33390]="祖尼！不！不——！"
D.Strings[33391]="没有这么快，小巨魔！"
D.Strings[33392]="出什么事了？"
D.Strings[33393]="怎么了……出了什么事……"
D.Strings[33394]="圣光在上，我又活过来了……"
D.Strings[33395]="我曾经英俊潇洒……"
D.Strings[33396]="我曾经很漂亮……"
D.Strings[33397]="那场瘟疫……结束了？"
D.Strings[33398]="我仿佛已经睡了许多年……"
D.Strings[33399]="啊，我明白了。我猜我应该去工作了。"
D.Strings[33400]="……我想，我明白发生了什么事。至少我还有我的自由意志。"
D.Strings[33401]="啊，我明白了。看样子，现在我已经是部落的一员了。"
D.Strings[33402]="啊，我明白。去工作！"
D.Strings[33403]="亡灵？我要向巫妖王复仇！"
D.Strings[33404]="啊，我现在明白了。感谢你唤醒我。"
D.Strings[33405]="这里可真黑。真不知道我是不是喜欢成为一个亡灵。"
D.Strings[33406]="这场觉睡得真香。等等，我的胳膊肘和膝盖到哪里去了？！"
D.Strings[33407]="天灾军团将把你们全部摧毁！死亡将横扫这片陆地！"
D.Strings[33408]="别那么快！给我留点，兄弟！"
D.Strings[33409]="这太疯狂了！沃金是认真的。他要找到那个女海巫，向她复仇。"
D.Strings[33410]="等等，兄弟！"
D.Strings[33411]="你也完成训练了？真高兴你通过了考验。"
D.Strings[33412]="这是件苦差事，但我不介意。这些小恐龙都是可爱的小恶魔。"
D.Strings[33413]="别让我太难堪，嗯？"
D.Strings[33414]="哈！我追上你了！让咱们并肩作战，行吗？"
D.Strings[33415]="瓦妮拉，请带我回暗矛要塞去。"
D.Strings[33416]="你也想分一份？那你可要努力了，宝贝儿！"
D.Strings[33417]="赶快，$c！能拿的全拿走！"
D.Strings[33418]="所有这些牛头人的身上都只有一些念珠和垃圾。你有没有找到什么有用的东西？"
D.Strings[33419]="嗨，$c！这个地方已经被搜检得差不多了。不过你也许还可以花些时间来搜索一下。"
D.Strings[33420]="喔，你来这里不是要对我们进行突击搜查吧？"
D.Strings[33421]="你被捕了。"
D.Strings[33422]="我可不打算回到牢房去，$g小子:姑娘;！"
D.Strings[33423]="别想活捉我，$c！"
D.Strings[33424]="试试这个！这个不错！"
D.Strings[33425]="你本来不必如此的，$c。"
D.Strings[33426]="我绝对不会让他们把我送回到牢笼里去！"
D.Strings[33427]="我投降，我会悄悄走掉。"
D.Strings[33428]="……完蛋了！"
D.Strings[33429]="好了，好了！我投降！"
D.Strings[33430]="你的训练师应该就在不远的地方。稍后我再来找你，兄弟。"
D.Strings[33431]="我希望这次行动过程中不会出现任何严重事故。"
D.Strings[33432]="我要杀了你，暗矛渣滓！"
D.Strings[33433]="女海巫会把你们全杀掉。"
D.Strings[33434]="他们要置你于死地，年轻人。"
D.Strings[33435]="我要你的小命，陆生种。"
D.Strings[33436]="我们要把那些联盟渣滓赶进海里去！"
D.Strings[33437]="萨尔万岁！"
D.Strings[33438]="让这些懦夫们明白，什么是真正的战争！"
D.Strings[33439]="为了你们的祖先和真正的酋长而战！"
D.Strings[33440]="联盟派侏儒和矮人来对抗我们？他们是在开玩笑吗？！"
D.Strings[33441]="我们的小朋友来了。等到地精拿起他们的除草器，我就要为那些矮人哀悼了！"
D.Strings[33442]="你为什么要玩弄他们？这太残酷了。"
D.Strings[33443]="找死也要这么着急吗？一群蠢货！"
D.Strings[33444]="也许他们应该把侏儒派到这里来？他们不可能更蠢了！"
D.Strings[33445]="现在这片海滩上到处都埋了他们肮脏的地雷。真可恶！"
D.Strings[33446]="没有比把矮人打得落花流水更痛快的事情了！"
D.Strings[33447]="再把它收紧一点。我们可不想让它们溜走，这样会错过许多乐趣。"
D.Strings[33448]="我已经见识过了地精朋友的能耐。那些矮人这次可要大吃一惊了！"
D.Strings[33449]="库卡隆不可能打得更好了！为了部落！"
D.Strings[33450]="火山爆发的时候，你的朋友全都被贸易大王加里维克斯抓住了。$B$B我们必须尽快解决联盟的人，这样才能救出他们，离开这座岛。"
D.Strings[33451]="你好，$n。很高兴再见到你。"
D.Strings[33452]="为杰罗德工作并不是那么糟糕。他也许偶尔会发发脾气，但他付的薪水很高。当我不能按进度完成工作的时候，他甚至还会帮我的忙。"
D.Strings[33453]="我能为你做些什么？"
D.Strings[33454]="<亡灵卫兵希米尔专注地看着你。>"
D.Strings[33455]="很抱歉！我没有恶意！"
D.Strings[33456]="任何野蛮人都可能赢得一场战斗。但真正的英雄所关注的并不是战场上的胜利，而是在最后一支羽箭落下之后去维系长久的和平。"
D.Strings[33457]="到静谧湾岸的天空中去，否则将被弹出机舱！"
D.Strings[33458]="你在贫瘠之地立下了令人难以置信的功绩，$n。$B$B有了像你这样的英雄，我们就能守住卡利姆多确保我们的家园能够实现长久的和平。"
D.Strings[33459]="酋长会帮助我们保卫我们的族人，对付加里维克斯。只要我们帮助他们对付联盟。$B$B听上去，这是一笔公平的交易。我的朋友的敌人就是我的敌人，对不对？"
D.Strings[33460]="把我送到天空中去，莎希！"
D.Strings[33461]="$n!我该怎样帮助你，老朋友？"
D.Strings[33462]="这话可别对别人说。我很担心这里的将军并不想做他该做的事情。$B$B我们要对付的是部落。历史表明，他们从不会给予我们真正的和平。$B$B我们的目标是……把敌人消灭干净。"
D.Strings[33463]="你也许不会相信，像我这样的狼人竟然能做出美味的肉排。$B$B就因为我喜欢吃生肉……我还没有从飞行的疲惫中恢复过来……我脑袋上的血管还在一蹦一蹦的……$B$B我们在说什么？哦，是了！我在吉尔尼斯可是一位著名的美食家。"
D.Strings[33464]="告诉我，陶拉祖发生了什么事。"
D.Strings[33465]="啊，是的，我们要对部落城镇陶拉祖发动进攻。我一直在努力厘清这一决定可能产生的后果。$B$B陶拉祖大概可以被称为一个“软目标”。它实际上只是一处猎人营地。但多年以来，它也一直是部落征募兵员，装备和训练军队的基地。$B$B我们的斥候报告说，陶拉祖最危险的部队都已经外出狩猎了。所以我们必须迅速行动。"
D.Strings[33466]="我们洗劫了那座城市？"
D.Strings[33467]="<霍索恩皱了皱眉。>$B$B我可不喜欢用“洗劫”这个词。但这场攻击实在是完美无缺。我们除掉了陶拉祖，收缴了他们的武器，摧毁了他们的锻造工厂。这次攻击为我们赢得了巨大的喘息空间，并打乱了敌人的阵脚。$B$B不过，在进攻过程中，我特意命令我的部下在阵线中留出一个豁口……"
D.Strings[33468]="为什么你会这样做？"
D.Strings[33469]="陶拉祖有许多平民。我希望能让他们避过战火。他们之中有许多人逃出来了，流亡到了北方。$B$B但即使是在联盟最高指挥部里，也有人在指责我放任敌人逃走，说我应该把他们全部俘获，当作人质。但我完全看不出来这种可怕的战术对我们有什么益处。$B$B听我说，$n：我希望这场战争能够结束。但如果我们屠杀或者囚禁平民，这张战争就永远不会有结束的可能。$B$B希望在我们的敌人之中也会有人能看清这一点。"
D.Strings[33470]="要到哪里去？"
D.Strings[33471]="现在我要飞往布瑞尔。"
D.Strings[33472]="我要租一只蝙蝠。"
D.Strings[33473]="$n!你还活着！你听说了吗？"
D.Strings[33474]="他们杀了他！霍索恩将军在路上遭到了部落刺客的偷袭。"
D.Strings[33475]="我们找到了他的尸体。那些野兽……那些肮脏的怪物！"
D.Strings[33476]="贫瘠之地告诉我们，只有焦土政策才能彻底清除那些部落怪物。对敌人不要有半点同情！"
D.Strings[33477]="如果霍索恩将军还活着，一定会毫不留情地将敌人消灭干净。"
D.Strings[33478]="你是对的，塔斯克。"
D.Strings[33479]="莉莉安……你……真高兴能看到你没事。"
D.Strings[33480]="你将我培育成一个杀手。我做得如何，爸爸？"
D.Strings[33481]="我，啊……"
D.Strings[33482]="但，等一等……我现在记起来了。你教过我只能杀亡灵。那么你想让我杀掉我自己吗，爸爸？"
D.Strings[33483]="莉莉安，我……"
D.Strings[33484]="那么，我为什么要把自己杀死……我可以杀死你！"
D.Strings[33485]="谢谢你为我做的一切……爸爸。"
D.Strings[33486]="交出石板，我会让你死个痛快。"
D.Strings[33487]="很好，矮人。尽管挣扎吧。我先把你干掉，然后再拿走这些石板。"
D.Strings[33488]="我能帮助你吗？"
D.Strings[33489]="是否做好开始的准备了？"
D.Strings[33490]="我们在这里竭尽全力医治残破的大地。就在这种极为艰难的情况下，我们还在夜晚遭到了袭击。"
D.Strings[33491]="很好，跟着我。"
D.Strings[33492]="现在该是开始的时候了。"
D.Strings[33493]="代弗林·阿加曼德！听我说！"
D.Strings[33494]="你在凡间的遗骸已经被收集完整，被放置在这个你渡过童年光阴的地方！"
D.Strings[33495]="代弗林，抵抗巫妖王的意志！到我们这里来吧！"
D.Strings[33496]="我最好回到我的岗位上去。如果有需要，你可以在楼下找到我。"
D.Strings[33497]="$c，现在我有一点忙……等我有空的时候再来找我吧。"
D.Strings[33498]="这里出了什么事？"
D.Strings[33499]="等等，我是……在家里？"
D.Strings[33500]="你们……你们在这里干什么？为什么你们会在我的房子里？"
D.Strings[33501]="妈妈……爸爸……萨尔曼……你们在哪里？来帮帮我！"
D.Strings[33502]="不……我想起来了。我的家人都死了。我也死了。"
D.Strings[33503]="我的灵魂……我的灵魂属于天灾！"
D.Strings[33504]="死吧，倒霉鬼！"
D.Strings[33505]="走进雷霆机场吧，$n！谁都不能退出，直到一方倒下为止。演出开始！"
D.Strings[33506]="谢谢你，$n！现在我可以开始最终的装配了……"
D.Strings[33507]="好了……结构？确认。能量？确认。危险？双重确认。让我们发射我的杰作吧！"
D.Strings[33508]="我们的装备在这里受到了真正的打击！"
D.Strings[33509]="嗯……确实。不过这只是很少一点……唔……非常少，对不对？"
D.Strings[33510]="希米尔说葛尔多有肚子，却没有脑子。这是什么意思？"
D.Strings[33511]="葛尔多喜欢摘花。摘花就像是打仗。"
D.Strings[33512]="这里通风很不错。"
D.Strings[33513]="乔汉说，葛尔多需要个裁缝来修整一下葛尔多的肚子。"
D.Strings[33514]="葛尔多，你能修理我的装备吗？"
D.Strings[33515]="胡说！微型化才是战争的未来。"
D.Strings[33516]="通过嗅觉寻找信息素，这样才能找到进入虫巢的路径！"
D.Strings[33517]="我应该说一下。我翻转了变速箱，以适应变小的整体外形。"
D.Strings[33518]="我代表杰出的，并依旧保持中立的热砂集团向你表示问候，并衷心希望你能在这里渡过一段愉快的时光。$B$B请记住，加基森欢迎所有人！只有海盗除外。"
D.Strings[33519]="欢迎回来，朋友！你帮助我配制出第一副诺格弗格药剂到现在仿佛已经有好几年的时间了。$B$B现在我掌管着整座城市！而且那些药剂依旧大受欢迎。"
D.Strings[33520]="死者的鲜血依旧在呼唤着公正的到来。"
D.Strings[33521]="在场的每一位绅士和小姐现在都可以离开了……因为只有真正的男女勇者才能面对这即将出现在你们眼前的血腥场面！让我们欢迎第一位斗士——废土战士——卡亚可乐教派的伟大象征……巨又霸！"
D.Strings[33522]="别作英雄了。走吧。"
D.Strings[33523]="不……这不可能。我们的前哨站被彻底摧毁了！"
D.Strings[33524]="是否已经太晚了？我感觉到死亡之翼就在附近！"
D.Strings[33525]="绝不能再耽搁了。必须完成凯旋壁垒的建造和布防，否则我们将没有可能在这片大陆上建立永久定居点。"
D.Strings[33526]="当我和我的蛮锤佣兵受雇守卫凯旋壁垒的时候，我以为我们的敌人将是部落。$B$B但现在我们却陷入了无数敌人的围困之中！爆炸的地精，挖洞的虫子，放电的蜥蜴……"
D.Strings[33527]="炎魔之王来了！我们必须赶快把这件事告诉其他人。抓紧时间！"
D.Strings[33528]="战斗之痕是一个危险的地方。当大地把一辆蒸汽坦克吞下去的时候，就算是全世界最好的护甲也保护不了它。"
D.Strings[33529]="我们要创造的是超越这个时代的东西，$n。$B$B看看这些蓝图！这就是世界的未来。"
D.Strings[33530]="当然，这里面还有不少的错误要解决。但微型坦克绝对是工程学上的一大奇迹。$B$B它只需要攻城坦克四分之一的制作材料，而且能够由任何人进行大规模生产！……呃，只要你有一双精巧的小手！"
D.Strings[33531]="记住我的话，锈水财阀终将在这里稳稳地扎下根来。"
D.Strings[33532]="<克拉莉斯看着这具尸体，目光显得苍白而空洞。>$B$B我一得到消息，就从塞拉摩岛马不停蹄地赶到这里。$B$B约翰和我一直在讨论，等战争结束以后就定居下来。$B$B我觉得这场战争永远也不会结束，你觉得呢？"
D.Strings[33533]="我们下一位斗士来自祖尔法拉克最深的墓穴之中！饱食诅咒之血，无数次死而复生，他现在只知道狂怒与暴力！鼓起勇气面对……祖蒙加盲目的怒火吧！"
D.Strings[33534]="巨又霸倒下了！$n看来还能应付更多！"
D.Strings[33535]="祖蒙加……杀……"
D.Strings[33536]="我能呼吸了！"
D.Strings[33537]="嗨！那些虫子把我的表抢走了！"
D.Strings[33538]="非常感谢，朋友！"
D.Strings[33539]="我还活着！"
D.Strings[33540]="萨尔万岁，$n！你是要帮我们消灭那些可恶的矮人和侏儒吗？"
D.Strings[33541]="巴斯蒂亚，我们上吧！"
D.Strings[33542]="也许这是岛上唯一凉快的地方了……虽然它就在火山的旁边！"
D.Strings[33543]="嗨，$n。你要进去吗？"
D.Strings[33544]="$n！能帮帮我摆脱菲兹吗？他又要发脾气了！"
D.Strings[33545]="艾沃·邪指一定要为此付出代价！为了我的利润，$n，请帮帮我！"
D.Strings[33546]="走吧，$c。$B$B在大灾变到来之前，我们发现了一些东西。$B$B我们挖出了一些本应该永远被深埋在地下的东西。$B$B无论你信仰什么神，你最好现在就向他祈祷崩裂的大地能再把它埋住……"
D.Strings[33547]="控制好设备——我们要进行清除了！"
D.Strings[33548]="把身上的东西保管好——每个矮人都应该照顾好自己！"
D.Strings[33549]="不要让他们把宝物偷走！"
D.Strings[33550]="我不敢相信菲兹和艾沃竟然会自相残杀。这一定是因为他们的压力太大了。现在我们更加需要你了，$n。"
D.Strings[33551]="恐慌！"
D.Strings[33552]="你要到那里去？我可不打算回去了！"
D.Strings[33553]="请投入硬币。"
D.Strings[33554]="这是我的工作，$c。将军在巡逻的时候，我扛起他的旗帜，并将旗帜牢牢插在土中。$B$B一位将军怎么可能没有旗帜？他还不如不穿裤子。"
D.Strings[33555]="这次，我们让你进城。"
D.Strings[33556]="嗨！别碰那面旗，$g小子:姑娘;。"
D.Strings[33557]="我已经填好了入城所需的文件。"
D.Strings[33558]="你还要把文件整理好。赶快去做。"
D.Strings[33559]="我以前见过你吗？我们会注意你的。"
D.Strings[33560]="你只能进城一个小时。有什么事就快点干。"
D.Strings[33561]="你已经被许可进城了。"
D.Strings[33562]="这里本来是一个美好而又安全的地方。但前面那片空地上突然就出现了一支侏儒军队。$B$B如果我们让那些卑鄙的小个子在这里打赢我们，加里维克斯一定会要我的脑袋。"
D.Strings[33563]="马尔雷·双辫就在这上边，$g先生:女士;。"
D.Strings[33564]="我的，是我的，我找到它的。我说了，是我的！我的！"
D.Strings[33565]="别闲逛了，我们在这里还有工作。"
D.Strings[33566]="他就在这里。别放过他！"
D.Strings[33567]="什么……我出了什么事？"
D.Strings[33568]="$n再次取得了成功！祖蒙加再一次死掉了！"
D.Strings[33569]="胆小的人简直恨不得遮住自己的眼睛！现在登场的是——来自森提帕虫巢黑暗隧道深处的恐怖斗士！跟我一起向着死亡奔跑吧——有请萨里尼克斯！"
D.Strings[33570]="这就是真相！战斗导致杀戮，杀戮导致战争。而这几乎就是我们全部客户的结局！$B$B现在，当人们要进行战斗的时候，它就发生在这里，也在这里结束！并发挥出最大的观赏潜力！"
D.Strings[33571]="谁也无法阻挡$n！萨里尼克斯被杀死了！"
D.Strings[33572]="我们为搏您一笑不惜血本，朋友们！我们要不惜一切代价干掉$n，只为让您看得过瘾，亲爱的观众！接下来是我们不远万里从安戈洛环形山的隐秘丛林中请出来的重量级人物——在他的力量面前畏缩吧……有请大金钢！"
D.Strings[33573]="难以置信！$n获胜了！大金钢从这个世界上消失了！"
D.Strings[33574]="我听说过这个叫奈辛瓦里的家伙。他来自于荆棘谷，以猎捕各种野兽为乐。$B$B他认为这是一种运动。真是个彻头彻尾的白痴，对不对？真不知道他到底把多少值钱的东西扔在田野里，任由它们烂掉！"
D.Strings[33575]="好了，我们现在要离开这座正在爆炸的火山，尝试和兽人们取得联系，对那个贸易大王发动最后的攻击。希望到时候能再见到你。"
D.Strings[33576]="返回回音群岛。"
D.Strings[33577]="我以前经常会频繁地陷入令人疲惫的愤怒之中。但自从我遇到德利兹之后，我的生活变得更加快乐而且积极。$B$B现在我已经学会了用两只空手把东西撕碎。"
D.Strings[33578]="准备好了就告诉我，朋友。"
D.Strings[33579]="我们来自诺森德的船遭到了暮光之锤的袭击！我不知道他们是怎样攻入那艘船的。那艘船的船员都牺牲了。"
D.Strings[33580]="利用了布莱恩连同石板一起送来的那块水晶，我保护了自己，并设法逃脱了。但一名袭击者一直对我紧追不舍！"
D.Strings[33581]="我会利用这块水晶来保护石板，看看它是否能为你提供力量来守卫我。如果暮光之锤的爪牙们打破了我的护盾，他们一定会杀死我，夺走石板！"
D.Strings[33582]="稳住身体，不要惊慌！安全带是给傻瓜用的。"
D.Strings[33583]="我们为巴尔莫丹感到骄傲。它是矮人在卡利姆多的第一个定居点。"
D.Strings[33584]="前方就是巴尔丹城堡了。是不是很漂亮？她绝对是坚不可摧的！"
D.Strings[33585]="……什么？城堡遭到了攻击！"
D.Strings[33586]="我……我控制不住了！求援！求援！"
D.Strings[33587]="呸！吵闹的牛头人吓不住我。"
D.Strings[33588]="这是一架单座飞机。但你可以骑在机身上。这非常安全。$B$B准备好了吗？"
D.Strings[33589]="准备好了，马尔雷。我们起飞吧！"
D.Strings[33590]="凯尔希派我来要一艘船。"
D.Strings[33591]="那个小家伙是谁？"
D.Strings[33592]="他是我的助手。$B$B虽然他也受到了瘟疫的感染，但显然感染的方式和我们有些区别。就像你和我一样，他也臣服于希尔瓦娜斯。$b$b这话不要告诉别人……说实话，我相信当他进入黑暗女王的房间时，黑暗女王并没有怀疑他的忠诚。"
D.Strings[33593]="我们必须在火山真正爆发之前救出所有人，并离开这里！"
D.Strings[33594]="我有主意了！"
D.Strings[33595]="该死的水晶！我们不会这样轻易就放弃。我们一定会把这块石板献给我们的先祖。也许不是今天，但这一天很快就要来了！"
D.Strings[33596]="你必须帮助我保卫地之石板。暮光之锤如果得不到这些石板，绝不会善罢甘休。"
D.Strings[33597]="我会帮助你保卫这些石板。"
D.Strings[33598]="嗯……非常精彩。好了，你通过了我的测试。"
D.Strings[33599]="真是精彩！你学得很快，我的学生。"
D.Strings[33600]="你成功了！你拯救了这些石板。赶快把它们送到铁炉堡。我恢复一下就会赶回去。"
D.Strings[33601]="多克纳……这太难堪了。"
D.Strings[33602]="多克纳，你在干什么？"
D.Strings[33603]="立刻给我下来！"
D.Strings[33604]="你不怕两只脚被烧掉吗？"
D.Strings[33605]="石板终于是我们的了！"
D.Strings[33606]="坚持住，$r。$b$b纳迦随时有可能再次发动攻击。"
D.Strings[33607]="这里正是这场可能毁灭世界的大灾变爆发的核心区域之一。$b$b如果我们要生存下去，就必须发掘出它的原因。"
D.Strings[33608]="对于这些船只的攻击显然不是偶然的。$b$b我们必须查清楚那些纳迦的动机。"
D.Strings[33609]="这座城堡就要塌了！"
D.Strings[33610]="这怎么可能发生？"
D.Strings[33611]="还有其他人——搜索整座营地！"
D.Strings[33612]="他们怎么能这样做！"
D.Strings[33613]="大厅的屋顶坍塌了。许多人都死了！"
D.Strings[33614]="要是有把铲子，我就能把自己从这堆废墟下面挖出来。"
D.Strings[33615]="我还以为自己会像一只火鸡一样被烤熟！"
D.Strings[33616]="我还以为自己完蛋了！谢谢你！"
D.Strings[33617]="元素，听我的命令，消灭这个暮光之锤的敌人！"
D.Strings[33618]="唉呦！我已经受不了了！"
D.Strings[33619]="圣光在上，真疼啊！"
D.Strings[33620]="它打得可真狠啊！"
D.Strings[33621]="灌下去"
D.Strings[33622]="自从黑暗之门打开以前，我就已经在这座谷里了，$g小子:姑娘;。我可不打算让几个血精灵来肆意劫掠这些遗迹！"
D.Strings[33623]="能载我前往剃刀岭吗？"
D.Strings[33624]="来自诺森德的飞艇遭到了暮光之锤的攻击！我不知道他们是怎样找到我们的，但我们的船员都遇害了。"
D.Strings[33625]="我们在一座泰坦宝库中发现了这块水晶和一些石板。我用这块水晶争取了一些时间，但他们还在追杀我！"
D.Strings[33626]="利用水晶的力量保卫我和石板。如果暮光之锤的爪牙们打破了我的护盾，他们一定会杀死我，夺走石板！"
D.Strings[33627]="你终于将他们赶走了。马上带着这些石板到力量谷去找大地治愈者诺莎拉。告诉她，等我恢复过来就会回去。"
D.Strings[33628]="快，我需要帮助！"
D.Strings[33629]="不要让他们冲破防线！"
D.Strings[33630]="为了得到这些石板，暮光之锤的傻瓜们会把大地撕裂。"
D.Strings[33631]="%s施放了毒伤！现在马上放好图腾！"
D.Strings[33632]="谢谢你，$r……我差一点就死了。我能在你身边待一会儿吗？"
D.Strings[33633]="我应该死在战场上……嗯，总有一天。现在我会跟随你，直到我恢复过来。"
D.Strings[33634]="你救了我， $c。在我体力恢复之前，请再保护我一段时间。"
D.Strings[33635]="为了酋长！我会紧紧地跟随你。"
D.Strings[33636]="我感觉好多了。为了部落！"
D.Strings[33637]="再次感谢你。现在我要返回剃刀岭了。"
D.Strings[33638]="能亲眼见证你的战斗是我的荣幸，$n。"
D.Strings[33639]="你打得很好。现在我要和你说再见了。Lok'tar ogar！"
D.Strings[33640]="你必须帮助我，$c！暮光之锤袭击了我的飞艇，妄图夺走正在被运往奥格瑞玛的石板和水晶。"
D.Strings[33641]="我们可不是你的系统的一部分！"
D.Strings[33642]="屋顶上那些……是什么东西？"
D.Strings[33643]="该死的奴隶！不干活就去死！"
D.Strings[33644]="抓住你能让我拿到很大一笔奖金！"
D.Strings[33645]="侏儒夺回家园的时候终于到了。$B$B诺莫瑞根将再次回到我们的手中！"
D.Strings[33646]="贸易大王说了，要对你厉害点！"
D.Strings[33647]="不挖矿，就挨打！"
D.Strings[33648]="我很喜欢打你！"
D.Strings[33649]="我是工头，你是奴隶！"
D.Strings[33650]="休息时间结束了！"
D.Strings[33651]="有什么计划？"
D.Strings[33652]="我们在矮人王国中得到了庇护。因此，我们对矮人感激不尽。但瑟玛普拉格对诺莫瑞根的统治应该到头了。$B$B我们犯下的大错让诺莫瑞根承受了太长时间的毒害。辐射炸弹曾经让我们彻底失去家园。现在，我们终于掌握了恢复家园的技术！$B$B我们必须夺回诺莫瑞根，让瑟玛普拉格得到正义的审判！"
D.Strings[33653]="诺莫瑞根行动将分成数个步骤完成：$B$B首先，我们必须夺回航空塔。这样我们的飞机才能支援进攻诺莫瑞根主入口的部队。$B$B而且，我们还在诺莫瑞根入口附近的一座建筑中发现了防辐射服。装备上防辐射服的侏儒部队能够直接进入诺莫瑞根。$B$B这样，我们就能在诺莫瑞根的核心对瑟玛普拉格发动直接攻击！"
D.Strings[33654]="有人吗……有人吗……"
D.Strings[33655]="我永远也见不到我的妻子了……"
D.Strings[33656]="我永远也见不到我的丈夫了……"
D.Strings[33657]="救救我！"
D.Strings[33658]="我无法再战斗了……"
D.Strings[33659]="%s看上去很虚弱！"
D.Strings[33660]="什么？你不应该在这里。你死定了！"
D.Strings[33661]="杀掉那个地精，赶快！"
D.Strings[33662]="矿车已经做好了出发的准备。"
D.Strings[33663]="欢迎来到前线，$c！如果只是躲在城堡里面，你将无法对现在的战争态势有真正的感受。这就是我总不愿意离开战场的原因。"
D.Strings[33664]="一定要去那片挖掘场和我的儿子马尔雷谈一谈。他是个好孩子。我必须以全部的精力监视巴尔莫丹。"
D.Strings[33665]="你去过巴尔莫丹吗？那里发生了什么事？"
D.Strings[33666]="他们一定要付出代价，$n。他们全都要付出代价。"
D.Strings[33667]="那些疯狂的牛头人。已经有好几年了，他们总是要炸掉我的飞行器！"
D.Strings[33668]="放松，朋友。你还活着。但其他人就没有你这么幸运了。"
D.Strings[33669]="你冒犯了神圣的领地！"
D.Strings[33670]="%s发出一阵凶猛的吼叫！"
D.Strings[33671]="贫瘠之地……会……吞噬你，$r。"
D.Strings[33672]="所有人都慌了！"
D.Strings[33673]="他们冲过了大门！我要离开这里！"
D.Strings[33674]="我会乘下一艘船回家。"
D.Strings[33675]="逃命吧！自求多福吧！"
D.Strings[33676]="你以为我会走着去塞拉摩？"
D.Strings[33677]="我的电压表到哪里去了？呸，没关系，部落会保管好它的！"
D.Strings[33678]="这么多数据……这么点时间……"
D.Strings[33679]="旋翼机全都起飞了。你准备好进行空中勘察了么？"
D.Strings[33680]="我已经做好了飞行准备。"
D.Strings[33681]="真有趣，即使在距离震中如此遥远的地方，艾泽拉斯的外表还是彻底被撕碎了。"
D.Strings[33682]="这些都是什么？在上周进行勘察的时候，这片丛林还没有出现。贫瘠之地发生了什么？"
D.Strings[33683]="是海水。海洋也被扯开了。你认为这道裂缝还在变宽吗？"
D.Strings[33684]="固守阵地。北方城堡的城墙被打破了！我们遭到了攻击！"
D.Strings[33685]="教练在这里？！他一定有办法的！"
D.Strings[33686]="你是谁？另一个微不足道的学生？"
D.Strings[33687]="你将得到一个痛苦的教训！"
D.Strings[33688]="只有真正的强者才能学到我们的秘密！"
D.Strings[33689]="驾驶矿车。"
D.Strings[33690]="你会希望自己从没有来过这里，蛆虫！"
D.Strings[33691]="你得到的唯一教训就是死亡。"
D.Strings[33692]="你将化为灰烬，凡人！"
D.Strings[33693]="你以为你有能力学习我们的秘密？你将为自己的傲慢付出代价！"
D.Strings[33694]="很好，萨满。我会干掉你，然后带着这些石板去见古加尔。"
D.Strings[33695]="我有一个有趣的计划，孩子！"
D.Strings[33696]="不知道我们能将他们拖延多久，$g小子:姑娘;，希望你知道该怎样做！"
D.Strings[33697]="奥格瑞玛的居民们，听我说。我们已经失明了太长时间！我请求你们，向真实睁开双眼吧！"
D.Strings[33698]="奥格瑞玛的人们，不要绝望！加入我们，来了解这个世界的真相吧。"
D.Strings[33699]="你要学会的第一件事就是遵守纪律。"
D.Strings[33700]="不管怎样，一场战争中最重要的部分是你该如何庆祝来之不易的胜利！"
D.Strings[33701]="当你进入战斗的时候，知道如何用震耳欲聋的战吼威吓敌人是非常重要的！"
D.Strings[33702]="但要记住，赢得战争的关键因素是活跃的增援力量。"
D.Strings[33703]="大家欢呼吧！"
D.Strings[33704]="回收"
D.Strings[33705]="这些伐木机是从哪里来的？"
D.Strings[33706]="真无法相信，你竟然这样对我！"
D.Strings[33707]="好啊，你真有让机器起死回生的能力。让我们开始工作吧！"
D.Strings[33708]="为什么我们要相信你？"
D.Strings[33709]="好了，新兵们，敬礼！"
D.Strings[33710]="让我听听你们的战吼！"
D.Strings[33711]="你告诉我们这个世界就要毁灭了。现在你却又对我们说不必担心。你到底要干什么？"
D.Strings[33712]="这里有太多的暴力，太多的痛苦。但我也会在这里得到光荣。离开我吧。"
D.Strings[33713]="我非常非常失望。你让我不得不再次放开我的战争之犬。"
D.Strings[33714]="真是个可怜的计划。"
D.Strings[33715]="灰烬审判军和像你一样的英雄们以惨重的牺牲为代价，终于接近了最终的胜利。现在，我来到冰冠堡垒，帮助所有对抗天灾军团的勇士们。我们将并肩作战，结束巫妖王的暴行！"
D.Strings[33716]="尊敬的殿下，我们能够完成这个任务。"
D.Strings[33717]="你一个人就行？你是傻了？还是自信过度？\n\n当然，我能在你的眼睛里看到取胜的决心。不过你需要用实力来证明自己。好吧，如果你想要这样，我会从战场上撤退。"
D.Strings[33718]="跳舞吧！"
D.Strings[33719]="我要让你们知道该如何成为一名真正的士兵！"
D.Strings[33720]="我们恳请您解除戒备，陛下。"
D.Strings[33721]="要击败巫妖王，你需要的将不止是勇气。祝你好运。"
D.Strings[33722]="你已经做出了选择。至于是生是死，就只能靠你自己了。"
D.Strings[33723]="希望你会喜欢这种旅行方式，我要出去了！"
D.Strings[33724]="我想要得到重生，告诉我要怎样做吧！"
D.Strings[33725]="是的，告诉我们！"
D.Strings[33726]="我一发出信号，你们就用最大的力气吼叫！"
D.Strings[33727]="听我的命令，敬一个标准的军礼，让我看看你们的纪律！"
D.Strings[33728]="我们言出如山，巫妖王必将败倒在我们脚下！"
D.Strings[33729]="诺森德的战事需要你的关注，地狱咆哮统帅。没有你的力量，我们也将去讨伐巫妖王和他的爪牙。"
D.Strings[33730]="战歌远征军已经到达冰冠堡垒。胜利就在眼前！巫妖王的惨败将成为部落新的荣耀！"
D.Strings[33731]="你拒绝战歌远征军的协助？难道战争让你的脑子烧坏了吗？有我的帮助，胜利的果实就唾手可得！如果没有我，那么你将面临极为困难的战局。"
D.Strings[33732]="荣耀属于部落！"
D.Strings[33733]="我将要召集对我们的使命感兴趣的人。如果你想知道得更多，就和我谈谈吧。奥格瑞玛里对现实保持沉默的人太多了。"
D.Strings[33734]="我会证明我自己的！"
D.Strings[33735]="为了这一刻，我已经接受了许多年的训练！"
D.Strings[33736]="你的选择很勇敢！而你对荣耀和功业的欲望也值得尊敬！光荣地去死吧，$n！"
D.Strings[33737]="我会以他们的名义取得胜利！"
D.Strings[33738]="训练已经够多了！现在是行动的时刻！"
D.Strings[33739]="今天我不会死在这里，怪物！"
D.Strings[33740]="你们还要懂得在战场上用欢呼激励你们的同袍。现在，听我的命令，发出欢呼！"
D.Strings[33741]="我一发出信号，就给我跳出最漂亮的胜利舞蹈！"
D.Strings[33742]="喔，真是惊人啊！"
D.Strings[33743]="漂亮极了！"
D.Strings[33744]="你们是我见过的最优秀的新兵！我们很快就会再次开始演习了。"
D.Strings[33745]="啊啊！！"
D.Strings[33746]="我已经和火焰融为一体！我已经……啊！！！真热啊！！！"
D.Strings[33747]="肉体是软弱的！必须被火焰净化！"
D.Strings[33748]="有一天，孤狼饿坏了。他向东跑去，寻找食物。"
D.Strings[33749]="当较软弱的科多兽死亡的时候，孤狼走上前，要吃掉它。"
D.Strings[33750]="另一头科多兽被孤狼激怒了。$b孤狼还没有来得及尝一口鲜肉，就被它杀掉了。"
D.Strings[33751]="以前的情形要比现在好得多……我们到底出了什么事？"
D.Strings[33752]="希恩，能给我讲讲你的预言吗？"
D.Strings[33753]="孤狼跑啊跑，寻找容易到口的食物。"
D.Strings[33754]="他渴望着科多兽的肉。"
D.Strings[33755]="孤狼很懒，不想为取得食物而努力。"
D.Strings[33756]="他跑得越远，他的肚子就叫得越响。"
D.Strings[33757]="孤狼不喜欢恐龙肉。"
D.Strings[33758]="蝎子肉对他来说太苦了。"
D.Strings[33759]="孤狼也吃腻了野猪肉。"
D.Strings[33760]="他在杜隆塔尔的沙丘上搜寻着猎物。"
D.Strings[33761]="我已经厌倦在水里跋涉了。让我们给自己找点儿便利吧，好吗？流水之灵，快来帮助我们！"
D.Strings[33762]="瞧，这样不就好多了？"
D.Strings[33763]="拉格兰，我安全了。"
D.Strings[33764]="主母……您还活着！"
D.Strings[33765]="那我们出发吧。带我去我的孙子拉格兰那里。"
D.Strings[33766]="不！我——我的脚踝！我不确定自己是否能做到……我们已经走了这么远……"
D.Strings[33767]="空气之灵！快来帮我！"
D.Strings[33768]="我想我们现在可以继续了。继续前进。"
D.Strings[33769]="那么多零零碎碎的东西！"
D.Strings[33770]="按那个红色大按钮！"
D.Strings[33771]="登上这架飞行器吧。"
D.Strings[33772]="看上去，它足以承载一名侏儒，也许还能承载两个。"
D.Strings[33773]="我们其余所有人都在那下面！"
D.Strings[33774]="可是，宝贝儿……？"
D.Strings[33775]="我迷惑了。也许只有大地之母本人才明白这一切的缘由。但我们必须设法阻止它……"
D.Strings[33776]="你的真诚很让人感动，德鲁伊。"
D.Strings[33777]="克努！我们身后！一个暗夜精灵。"
D.Strings[33778]="你不是暗夜精灵……这是绿龙的伪装！以大地之母的名义，我……"
D.Strings[33779]="我不配受到如此尊重或敬仰，德鲁伊。我背叛了自己的土地。这片土地的疾患都是我的错。"
D.Strings[33780]="疾患来自翡翠梦境内部的梦魇，巨龙泰拉尔对其进行了散播。现在的他就是从前自己的癫狂镜像，要亲眼看着这片土地被吞噬殆尽。"
D.Strings[33781]="我不敢亲自去面对他。仅是靠近他，就有让同样的腐化再次将我打倒的危险。"
D.Strings[33782]="我们该怎么做？"
D.Strings[33783]="大地在因痛苦而啜泣。收集它的眼泪，用它们去封闭位于符印巨树的传送门。与梦境的联结必须被割断。"
D.Strings[33784]="一定要勇敢，英雄们。"
D.Strings[33785]="提拉加德现在归北卫军了！"
D.Strings[33786]="$n，你必须干掉那个贸易大王！"
D.Strings[33787]="要是菲兹能稍微机灵点儿，我们绝对不会被捉住！"
D.Strings[33788]="要是艾沃能稍微机灵点儿，我们绝对不会被捉住！"
D.Strings[33789]="暮光之锤是起决定性作用的力量。因为我们，死亡之翼自由了。因为我们，上古之神从大地深处重生。因为我们……海加尔在燃烧。$B$B你觉得你能为我们做什么？"
D.Strings[33790]="我们已经看清了前方的道路。回去吧。"
D.Strings[33791]="全靠你了，$n。你必须击败贸易大王，否则我们将一败涂地。"
D.Strings[33792]="现在的整个局面都非常不利。你必须把贸易大王找回来，$n！"
D.Strings[33793]="别担心我们，$n。你只要过去那边，确保解决掉贸易大王就可以了。"
D.Strings[33794]="请插入硬币，然后继续同贸易大王做交易。"
D.Strings[33795]="运气如何？"
D.Strings[33796]="不管是地震还是洪水，魂灵使出的任何把戏都别想阻止我履行自己的职责。"
D.Strings[33797]="天意如此，$n。你必须获胜，否则我们将落得一败涂地，与这座岛屿一同消亡。"
D.Strings[33798]="老实说，这些家伙怎么老是会被捉住？真是彻彻底底的无能！$B$B这简直让我为地精的身份而感到羞耻。$B$B说到羞耻，我那个好吃懒做的助手跑哪儿去了？不用猜，她肯定正坐在什么地方发呆呢！$B$B喔，这可真叫做能者多劳。我想只能靠我来想办法帮大家脱困了。"
D.Strings[33799]="我们来此表达对伟大森林的敬意，亲眼见证大地之母馈赠的奇迹。"
D.Strings[33800]="你是来帮忙的吗，$c？这个山谷就是个天然的阻塞点。要是我们能扼住这条补给线，就能为我们在世界之树的同伴争取时间来发起反击。"
D.Strings[33801]="我不明白这些补给品是从哪儿来的。暮光之锤不知想出了什么办法，同时对整座圣山发起攻击……"
D.Strings[33802]="让我们爬到那大家伙的顶上去。"
D.Strings[33803]="嗯……你注意到这笼子有底了？"
D.Strings[33804]="请转告我的妻子，我很爱她！"
D.Strings[33805]="快把门打开……喔不！"
D.Strings[33806]="那些火箭是干吗用的？！"
D.Strings[33807]="$n，你和霍巴特要害死我啊！"
D.Strings[33808]="那些海盗有钥匙！"
D.Strings[33809]="霍巴特，我需要更多单级助推火箭！"
D.Strings[33810]="什么？你认为这些是长在树上的？那给我找棵这样的树瞧瞧！$B$B这活儿我没法干！"
D.Strings[33811]="你没能通过测试。再试一次吧。"
D.Strings[33812]="<这只机器人大猩猩似乎已经损坏了。>"
D.Strings[33813]="坠毁报告XX1-017$B$B校验和数错误0081$B$B流体水平过低，危险$b$B任务失败$b$b未曾有机会看到外部世界"
D.Strings[33814]="你想要什么，$r？"
D.Strings[33815]="我来向你发起战斗的挑战。"
D.Strings[33816]="我吓到你了吗，$r？"
D.Strings[33817]="怎么了，老兄……没见过狼人吗？"
D.Strings[33818]="一切为了梅卡托克国王！"
D.Strings[33819]="这样有问题吗？"
D.Strings[33820]="我很愿意帮忙！"
D.Strings[33821]="我能带上我的扳子吗？"
D.Strings[33822]="算我一个！"
D.Strings[33823]="动作快，$n！萨尔需要你的帮助！"
D.Strings[33824]="喔！我们要夺回诺莫瑞根？我要参加！"
D.Strings[33825]="我想要驾驶蜘蛛坦克！"
D.Strings[33826]="那个叛徒来救你了，酋长。这倒方便了。你们要么一起向我下跪，要么就一起去死！"
D.Strings[33827]="炸毁那些杜隆塔尔的岩石大道！我已经确定了几个需要炸毁的地方。但这里并不是其中之一。"
D.Strings[33828]="坡道上面，$n！帮助萨尔击败贸易大王！"
D.Strings[33829]="萨尔正和贸易大王在码头的另一端打得难解难分。快去，$n！"
D.Strings[33830]="$n，帮助我。贸易大王已经强大了许多！$B$B我不知道自己还能坚持多久。"
D.Strings[33831]="我输了。你让我看到了我的错误。从现在起，我承诺对财阀进行彻底的改革。"
D.Strings[33832]="我要挥起复仇的扳钳！"
D.Strings[33833]="你有明确的目标吗？"
D.Strings[33834]="我喜欢清晨油脂的香味！"
D.Strings[33835]="我完成任务以后，你觉得他们还会让我保留我的制服吗？"
D.Strings[33836]="庆功会什么时候开始？我已经准备好跳舞了！"
D.Strings[33837]="老爷！老爷！我让步！你们太厉害了！"
D.Strings[33838]="我是你的地精，萨尔。你要我干嘛？"
D.Strings[33839]="戈杜尼食人魔已经破坏这片土地相当久了。我们来这里，就是要为部落夺回这片土地以及它丰富的资源！"
D.Strings[33840]="这些食人魔是站我们这边儿的？"
D.Strings[33841]="石槌部族效忠于部落！$B$B在奥格瑞玛建立期间，当我们的族人努力将卡利姆多改造成我们的家园时，英雄雷克萨击败了石槌食人魔部族的首领。$B$B从那时起，他们便发誓为部落效忠，我已经将他们召集至此，铲除戈杜尼部族。"
D.Strings[33842]="这取决于你对“是”字的定义……"
D.Strings[33843]="只有怀疑论者才会问出这样的问题！你是怀疑论者吗？"
D.Strings[33844]="嗨，我需要释放一些有毒资产！"
D.Strings[33845]="那么……你觉得答案是什么？"
D.Strings[33846]="既是又不是。我想这真要取决于你怎么看了……这个答案你满意吗？"
D.Strings[33847]="就是文字游戏而已，真的。"
D.Strings[33848]="听从死亡之翼领主的号令！"
D.Strings[33849]="财阀要裁员了，就从你开始！"
D.Strings[33850]="锈水财阀的规模已经太大了。该裁员了！"
D.Strings[33851]="我要开除这个废物。为了精简公司规模！"
D.Strings[33852]="请原谅，我得把这些有毒资产倒给你！"
D.Strings[33853]="我需要把有毒资产推给某个笨蛋……比如你！"
D.Strings[33854]="你被解雇了！"
D.Strings[33855]="一想到要开除你，我就激动不已。"
D.Strings[33856]="你烧了我的总部，现在我要烧死你！"
D.Strings[33857]="狗会叫吗？"
D.Strings[33858]="醋是酸的吗？"
D.Strings[33859]="火是热的吗？"
D.Strings[33860]="海洋是不是充满了水？"
D.Strings[33861]="奴隶怎可能获得自由？"
D.Strings[33862]="沙漠难道能生出绿草吗？"
D.Strings[33863]="骗子会说真话吗？"
D.Strings[33864]="我要用你的钱来砸死你！"
D.Strings[33865]="我喜欢你。给你加薪水！"
D.Strings[33866]="我就是有钱！"
D.Strings[33867]="水会往高处流吗？"
D.Strings[33868]="你是$c吗？"
D.Strings[33869]="古加尔是暮光之锤的领袖吗？"
D.Strings[33870]="我们的教派是效忠于上古之神吗？"
D.Strings[33871]="返回奴隶营或加里维克斯码头，否则你将失去足球炸弹制服！"
D.Strings[33872]="<菲兹尔的躯体晃动着，毫无生命气息，右手却依然紧攥着那颗宝珠。>"
D.Strings[33873]="<尝试移除这颗宝珠。>"
D.Strings[33874]="<你抓住那颗宝珠，但菲兹尔的手将它抓得更紧了。这颗球微微闪烁着光亮。>"
D.Strings[33875]="<尝试移开菲兹尔的手。>"
D.Strings[33876]="<放弃吧。这太吓人了。>"
D.Strings[33877]="萨尔咕哝着思考了一会儿，琢磨该拿贸易大王怎么办。"
D.Strings[33878]="至少现在，你仍然是锈水财阀的贸易大王。"
D.Strings[33879]="我会在你们族内选择一名代表，去见新酋长——奥格瑞玛的加尔鲁什·地狱咆哮。"
D.Strings[33880]="你们将在艾萨拉有一个新家。锈水财阀将成为部落的一分子！"
D.Strings[33881]="就按照你说的去做！锈水财阀万岁！为了部落！"
D.Strings[33882]="别被鹰身人那长满羽毛的翘臀迷惑……她们的杀伤力可是致命的！"
D.Strings[33883]="Lok'tar ogar，士兵。"
D.Strings[33884]="为了部落！"
D.Strings[33885]="我们暂时还无法返回卡利姆多。只有卡乌格会跟你一起回去。另一艘船会把我们剩下这些人带去目的地。$B$B最伟大的冒险还在前方等着你呢，$n。我们的道路还会再次交汇，到那时，世界的命运将掌握在我们手中！"
D.Strings[33886]="看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。$B$B当你准备好动身前往奥格瑞玛时，告诉我一声。"
D.Strings[33887]="莎希，在岛屿彻底覆灭前，我们得尽快赶往奥格瑞玛！"
D.Strings[33888]="证明忠诚！食人魔，消灭害虫！（主人需要鲜血！鲜血和痛苦！）"
D.Strings[33889]="嗯……我还会用到你的战斗座狼的。"
D.Strings[33890]="我们要先去奥格瑞玛，$g 小伙子 : 姑娘;，然后前往我们在艾萨拉的新家。在那儿见吧！"
D.Strings[33891]="这可真是个漫长的旅程啊，宝贝儿。谢谢你！$B$B现在让我们离开这座岛吧。"
D.Strings[33892]="你是位真正的$g大英雄:女英雄;，$n！是锈水财阀的偶像$g帅哥:美女;。$B$B我们的股价将一路飙升，而我也能得到加薪了！"
D.Strings[33893]="锈水财阀的未来看起来可不乐观。一点儿也不。$B$B你必须帮我们及早抽身，$n，否则我们不如直接跳进那边的火山里算了。"
D.Strings[33894]="喔天哪，你做到了，$n，你真的做到了！$B$B现在，根据我的估计，如果我们不在最短最短的时内里起航，那堆巨型火山石从天而降，把快艇击成碎片的可能性会越来越大。$B$B出发吗？"
D.Strings[33895]="锈水财阀的$g 英雄 : 女英雄; 总能在最后一刻赶上清仓销售的好机会，$n。"
D.Strings[33896]="这里就是被你称为很糟糕的地方！"
D.Strings[33897]="真是一团糟！我该怎么旋转这个？$B$B这是真的吗？僵尸地精？！！"
D.Strings[33898]="你成功了，孩子！你带球冲进了得分区，引爆并一举取得了胜利！$B$B现在让我们离开这儿吧。我想新的队伍可以命名为$n爆破队！"
D.Strings[33899]="你做到了，我的$g 小伙子 : 姑娘;，你做到了！$B$B现在让我们前往艾萨拉，是时候开始我的新事业了。这个假期可真漫长，我还有账单要付！"
D.Strings[33900]="我不认为你还能想到什么办法把我们从这里弄出去？有吗？$B$B啊，好吧，希望当岩浆缓缓流进来时，我们不会死得太痛苦。"
D.Strings[33901]="我们都要死在这儿了！！！$B$B我是个奴隶工头……不知道现在投靠贸易大王还来得及吗？"
D.Strings[33902]="我知道你一直都有这潜质，$n。$B$B现在说说——你觉得在艾萨拉会有我的位置吗？那儿有巨魔吗？"
D.Strings[33903]="我只想说声谢谢，$n。$B$B这儿的医生能把你救醒真是太好了，不然我们现在都已经死了，甚至更糟！"
D.Strings[33904]="我才不会为你收拾残局呢，你听好了！$B$B你得去解决贸易大王那只老鼠，我就是这么想的！"
D.Strings[33905]="为$n三呼万岁！$B$B我真恨不得现在就去艾萨拉搭起我的小床，吃顿可口的早餐。你觉得那里会是什么样的？"
D.Strings[33906]="你干得棒极了，$n。你可真是一流！$B$B不过，当然，要是没有我的聪明才智，你也做不到——我相信你肯定会在工作报告中写上这一条的。不管怎样，虽然我那笨手笨脚的助手老是添乱，你还是圆满完成了。"
D.Strings[33907]="我们的目的地是奥格瑞玛和艾萨拉。舰船宝贝儿，起航！"
D.Strings[33908]="请把硬币插入船里，以驶离爆炸的岛屿。"
D.Strings[33909]="让我们起航前先把菲兹扔出去。我抬头，你搬脚！"
D.Strings[33910]="让我们彻底解决那个废物吧，艾沃。艾萨拉没法同时容下我们两个人！"
D.Strings[33911]="我就知道你能做到，$n！你救了我们。$B$B现在趁我还没杀死菲兹和艾沃，让我们赶快离开这儿。"
D.Strings[33912]="你知道你为我们节省了多少宝贵的时间和金钱吗，$n？这原本有可能成为一场彻底的灾难，而你单凭一己之力就拯救了整个财阀。$B$B你和萨尔就这么放过了加里维克斯真是太可惜了。我想你肯定能成为一位杰出的贸易$g大王:女王;！"
D.Strings[33913]="没人能取得你的成就，$n。可我不明白为什么你没把加里维克斯拉下马。你本该接替他的职位。$B$B希望我们能顺利在艾萨拉安下新家。我盼望着能早点儿退休呢。"
D.Strings[33914]="我现在没和你说话。如果我是你，我决不会指望今年的加薪了，$n。"
D.Strings[33915]="你成功了！我们得救了！"
D.Strings[33916]="我们真的要去艾萨拉吗？那里是不是也有一座火山？"
D.Strings[33917]="我该怎么感谢你呢，$n？"
D.Strings[33918]="如果我是你，我就会放亮眼睛、竖起耳朵。有传闻说，卡亚罗和失落群岛的火山喷发都与你有关。$B$B我知道这听起来很疯狂。但人们八卦的素材总是千奇百怪，而且总以毁掉英雄为乐——尤其是在有利润和晋升驱使的情况下。"
D.Strings[33919]="我们得在被火山杀死之前离开码头！"
D.Strings[33920]="等您准备好就能出发了，$g 阁下 : 女士;！"
D.Strings[33921]="我不知道。我想我会想念这里的。我们在这儿共度了不少美好时光。"
D.Strings[33922]="我有个主意……这次我们别在联盟和部落的海战中徘徊了。$B$B我只是说说。"
D.Strings[33923]="愿大地母亲时刻护佑你，$n。谢谢你的帮助。"
D.Strings[33924]="你的生命之歌将永远激昂，$n。下次再见。"
D.Strings[33925]="我在艾萨拉还有其它事情要解决，所以我会和你一起上路，$n。"
D.Strings[33926]="你有一颗巨人的心，$n。我无比荣幸！"
D.Strings[33927]="看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。"
D.Strings[33928]="欢迎你，朋友。我们一起直取格瑞姆巴托，给死亡之翼难忘的重重一击！"
D.Strings[33929]="Log'loth og shandai，凡人。只有死亡才能永恒。你将不复存在。"
D.Strings[33930]="命运凌驾信仰之上，凡人。此时祈祷，毫无意义。"
D.Strings[33931]="你现在只是在浪费我的时间！"
D.Strings[33932]="我在航——行！"
D.Strings[33933]="如果我在每次听到世界末日即将到来的时候攒下一枚银币，那我现在就要比地精贸易巨头更富有了！"
D.Strings[33934]="末日教信徒？兽人已经经历过一次世界末日了，再来一次又能怎样？"
D.Strings[33935]="把这些教徒都扔进一艘飞艇里。再让那艘飞艇飞到暴风城去！奥格瑞玛不需要这种人。"
D.Strings[33936]="有谁会加入这种组织？如果世界真的会完蛋，那这种警告又有什么意义？"
D.Strings[33937]="看样子，现在已经是再次清理暗巷区和暗影裂口的时候了。"
D.Strings[33938]="泛舟乘海……远离湾岸……"
D.Strings[33939]="拥抱海风，天空澄明……"
D.Strings[33940]="哦……闪闪发光！"
D.Strings[33941]="伟大的英灵，我并非为我一个人而祈祷，而是为了暗矛部族……为了我的人民。"
D.Strings[33942]="我的激励仪丢了，能再给我一台么？"
D.Strings[33943]="你想要什么吗？"
D.Strings[33944]="你有什么东西要给我看？"
D.Strings[33945]="好吧。我跟你来。这最好是重要的事。"
D.Strings[33946]="上船来吧，快上来！"
D.Strings[33947]="萨米尔船长将指引这艘船直达大洋彼岸……"
D.Strings[33948]="……我们将前往协助联盟，增援他们对部落的突袭。"
D.Strings[33949]="轻松赚钱！佣金将由所有幸存者平分，人人有份！"
D.Strings[33950]="我已经准备好撤退了。"
D.Strings[33951]="哎呦！这可……这可真疼！"
D.Strings[33952]="把暮光新兵从人群里带离，用硬铁棒将他击晕。"
D.Strings[33953]="测试开始。正在施放触发法术。"
D.Strings[33954]="触发法术已收到。闲置中。"
D.Strings[33955]="克罗米，你和我都知道在这个时间流中会出什么事。我们以前都遇到过这种情形。你能不能略过这些部分，直接进入真正的行动？"
D.Strings[33956]="没错，我曾在这里见过你！我怎么会忘记呢？$B$B如果你愿意的话，我可以立刻把你传送到斯坦索姆去。"
D.Strings[33957]="伟大的暮光之眼，引导你谦卑的奴仆吧！"
D.Strings[33958]="请说吧，暮光之眼。"
D.Strings[33959]="你有何指示，暮光之眼？"
D.Strings[33960]="船长！右舷下方发现船骸，好像还有幸存者！"
D.Strings[33961]="双头在哪儿？暮光之眼正在告诉我们什么？"
D.Strings[33962]="谁最后和眼睛说话的？眼睛高兴吗？快告诉伽格尔！"
D.Strings[33963]="洞里太脏了！把污物放在标有旗子的污物堆上吧。"
D.Strings[33964]="伽格尔的大餐时间！去找厨师。如果大餐没有准备好，就把厨师煮了。"
D.Strings[33965]="眼睛用暗语交谈。我照眼睛说的做！你们照伽格尔说的做！"
D.Strings[33966]="眼睛没有嘴唇，可眼睛偷偷说给伽格尔听。眼睛无所不知！"
D.Strings[33967]="要是你对我们不满意，就去跟眼睛说。可眼睛不会听。它不是耳朵。"
D.Strings[33968]="别去理会巴德……那伙计的脑子里少了几根筋。"
D.Strings[33969]="你成功了，$n！神殿又是我们的了！"
D.Strings[33970]="够了！我要亲自来对付你。（呵哈哈哈哈！杀啊！杀啊！）"
D.Strings[33971]="真可怜！看看我精兵真正的力量吧……"
D.Strings[33972]="伊安·杜兰正在营地里等你。"
D.Strings[33973]="塔科里克·怒哮在上面的营地等你。"
D.Strings[33974]="为你效忠，主人！"
D.Strings[33975]="%s开始施展污染！"
D.Strings[33976]="末日教信徒？在那些迪菲亚暴徒之后，我们又有新的麻烦了。"
D.Strings[33977]="把这些教徒都扔进一艘船里。再让那艘船驶进大漩涡里去！暴风城不需要这种人。"
D.Strings[33978]="如果世界真的要完了，难道这些教徒警告我们还有什么意义吗？"
D.Strings[33979]="看样子，该是让卫兵再次清理旧城区的时候了。"
D.Strings[33980]="|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你受到了|cFFBC05FF死疽|r的伤害! |TInterface\\Icons\\ability_creature_disease_02.blp:16|t"
D.Strings[33981]="彻底击败她们，兄弟姐妹们！"
D.Strings[33982]="自动收集太棒了！呀嘿呀嘿，万岁！"
D.Strings[33983]="收集机器人要有大收获啦，哈哈哈哈。"
D.Strings[33984]="大块的——留给我！"
D.Strings[33985]="什么都不能浪费！吖！"
D.Strings[33986]="收集收集收集！"
D.Strings[33987]="让收集机器人帮你提升潜在利益吧！"
D.Strings[33988]="吖——！"
D.Strings[33989]="加恩的头歪向一侧，呼吸变得越发没有节律。$B$B他没有注意到你的到来。"
D.Strings[33990]="我似乎把远程遥控焰火放错地方了。"
D.Strings[33991]="哦，当然，这儿还有一些特别的。我可是焰火专业户……"
D.Strings[33992]="他们也许会夺走我们的生命，但他们永远也无法夺走……"
D.Strings[33993]="你们要搜遍每个补给站，每个居民点，每一座仓库、农舍、鸡窝、厕所和狗屋。哪怕钻进地心也要把目标找出来！"
D.Strings[33994]="我们不会沉默地堕入黑夜！我们不会不经一战就自行消失！"
D.Strings[33995]="嗯，我猜它可能会有用。但它至少还要再诱人一些！"
D.Strings[33996]="什么？我甚至不知道你在说些什么！这太恐怖了！"
D.Strings[33997]="太可怕了！好吧，也许它只是需要被清理一下？"
D.Strings[33998]="Al'tha， Al'tha bormaz， Ni bormaz ta'thall？它来了，它行走在火焰中，$r！"
D.Strings[33999]="阴影看得见。Bo'al lal arwi C'toth。末日即将来临，掩藏在无声的烈焰之中。"
D.Strings[34000]="Mar'kowa tallol ye'tarin，它知道，它明白。"
D.Strings[34001]="恐惧从永恒之心内蒸腾而出。别逼我看！我所看到的一切已经超出了我的承受极限！"
D.Strings[34002]="我们什么都不是。Tulall par'okoth。Far'al, ka'kar。虚空吞噬一切。"
D.Strings[34003]="<暮光仆从向你“嘎嘎”地叫着，白色的泡沫从嘴角边淌了下来。>"
D.Strings[34004]="H'thon，黑暗的幕帘延伸到视野之外。H'thon marwol qualar：面对黑暗的永恒之握。"
D.Strings[34005]="……我们的发明！"
D.Strings[34006]="那个逃亡者的名字是机械师瑟玛普拉格。"
D.Strings[34007]="去找到他。"
D.Strings[34008]="虽然历经劫难，但我们还是会生存下去！今天，我们要庆祝……"
D.Strings[34009]="……我们终于夺回了主权！"
D.Strings[34010]="$n，你们从狼神小径救出来的那些暮光奴隶进了营地，可他们无法讲明他们的身份，语言也含混不清。$B$B我原本以为暮光之锤是以古老的方式对待奴隶——你知道，就是鞭子和锁链那种——但很显然，他们还加入了洗脑的步骤……"
D.Strings[34011]="你必须留在钢架补给站。"
D.Strings[34012]="<给予药剂。>"
D.Strings[34013]="什——什么？我这是在哪儿？我得从这儿离开！"
D.Strings[34014]="我这是怎么了？我要离开了！"
D.Strings[34015]="……我在说什么？这已经没意义了。我要离开这个地方！"
D.Strings[34016]="我的……头……好疼！"
D.Strings[34017]="哇，你让那些声音消失了。我得走了！"
D.Strings[34018]="他们对我做了什么？我得回营地去……"
D.Strings[34019]="运气怎么样？试着和那些被解救的奴隶交谈真让我头痛不已。$B$B他们口齿不清的发着刺耳的噪音，然而还很押韵。"
D.Strings[34020]="谢谢你的帮助，$n。"
D.Strings[34021]="不知恢复神智是不是件好事。$B$B我所知道的一切……也许即将发生在这世界上的一切……$B$B<他战栗着陷入了沉默。>"
D.Strings[34022]="多谢你救了我们，$c。$B$B我们要护送下一个车队下山，但……我不认为我还会犯同样的错误……"
D.Strings[34023]="放过我们吧，陌生人。我们没有对你做任何事。"
D.Strings[34024]="我们远离这座城市中的生活，在这里等待我们的命运，倾心领受最真实的真相。"
D.Strings[34025]="你想要加入我们？我们在这座城市中的信使将告诉你必须怎样去做，寻觅者。"
D.Strings[34026]="哨兵部队在卡利姆多各地阻挡部落的攻势。当灰谷与石爪山相继被战火席卷之时，这里也需要我们的帮助——我们要保护那些仅存的野生动植物，并阻止我们的敌人攻占更为纵深的据点。"
D.Strings[34027]="你以为你在干什么，$c？离那些工具远点儿！"
D.Strings[34028]="你无法……控制眼睛！古加尔会知道的。你将受到……惩罚。"
D.Strings[34029]="带我去梅卡托克那里！"
D.Strings[34030]="生命之日将永远落下，空无之夜即将降临。(毁灭迫近了!它在呼唤!)"
D.Strings[34031]="暮光之锤是带来伟大毁灭的造物，是让一切化为虚无的荣耀之光！（别再迷茫了！向虚无敞开你的心智吧！）真正的力量就在我们手中！"
D.Strings[34032]="加入我们，（加入我们！）你们将获得超乎想象的力量！（力量！他的力量！强大的力量！）"
D.Strings[34033]="我是暮光之眼……快来认识你们的新主人吧！"
D.Strings[34034]="你在海加尔的工作已经完成——回到你的来时之地吧。"
D.Strings[34035]="消灭任何胆敢有异议的人。听从眼睛的号令！"
D.Strings[34036]="为何来这里打扰我们，陌生人？"
D.Strings[34037]="不要害怕，$c。我们全心接受所有寻觅真相的人。"
D.Strings[34038]="我们只希望能不被打扰。为什么这一点就如此难以被理解？"
D.Strings[34039]="世界末日即将到来，但现在还有时间纠正一切，$c。"
D.Strings[34040]="享受你们空虚的胜利吧，害虫们。（黑暗降临了……）愿它成为你们腐烂世界的安慰。"
D.Strings[34041]="你好啊，$c。我想你一定有很多问题要问。$B$B简单说吧，罗伊斯·暮语把我派到这个食人魔洞穴里干什么与暮光之眼相关的活计，可进展得并不顺利。$B$B要是我能抓住那个皮包骨头、没心没肺、油嘴滑舌的暗夜小精灵……$B$B<倒吊在空中的克里斯托弗无助的扭动着，脸涨得通红。>"
D.Strings[34042]="你应该回奥格瑞玛去。你的家人都很担心。"
D.Strings[34043]="不，我不能回奥格瑞玛。我也在为家人伤心，但他们已经做出了选择，我也做出了我的选择。我的未来在这里，在我的兄弟姐妹中间。"
D.Strings[34044]="你的家人正在找你。他们很担心。"
D.Strings[34045]="我不会离开的。告诉我的家人，我在这里很好，也希望他们过得好。"
D.Strings[34046]="有一天，我也会升华。"
D.Strings[34047]="在这样一座大城市里，注意到元素发出警告的人却屈指可数，这真令我感到惊诧。"
D.Strings[34048]="努力工作吧，$c。我们完成任务的时间已经不多了。预言即将实现。"
D.Strings[34049]="我们的世界很快就要完结。但我们将共同得到升华，得到元素的力量。"
D.Strings[34050]="你的家人希望你能回到奥格瑞玛去。"
D.Strings[34051]="你闻到什么了吗？"
D.Strings[34052]="我很愿意帮你，可我被……链子缠住了。我只能往回晃一点儿。"
D.Strings[34053]="你可真是个与众不同的$c，$n。我不是在说你坏话。我只是说，你还挺有趣儿。"
D.Strings[34054]="我吊在那儿多久了？感觉应该有好多天了。"
D.Strings[34055]="像那样吊在链子上的滋味可不怎么好。不过，老实说，那对我头发有好处。"
D.Strings[34056]="食人魔。$B$B我恨食人魔。"
D.Strings[34057]="当有东西给你杀时，你总是话那么多吗？"
D.Strings[34058]="少说废话，多杀点儿食人魔。好吗？"
D.Strings[34059]="他们本来有机会和我在一起。但他们却只是嘲笑我的信仰。他们对我已经毫无意义了。"
D.Strings[34060]="你的妻子很想你。她想让你回奥格瑞玛去。"
D.Strings[34061]="难道她不明白？我希望她能到我身边来。我很年轻，我还不想死。我们还要共渡许多美好的岁月。而这是唯一能让我们活下去的办法。把这些告诉她，请一定让她明白。"
D.Strings[34062]="好吧，就这么办！你对付食人魔，我……就不对付他们了。我去找出口！"
D.Strings[34063]="又给了我一次效力的机会？我不会再失败了！"
D.Strings[34064]="阿莱克丝塔萨选对了盟友……很可惜，你们都将死在这里！"
D.Strings[34065]="不要心存侥幸！"
D.Strings[34066]="这是最好的结局。"
D.Strings[34067]="海里昂，我……"
D.Strings[34068]="让他们化为灰烬，仆从们！"
D.Strings[34069]="我们成功了！我能自己找到回去的路。帮我个忙，告诉罗伊斯·暮语该把那要命的暮光之眼放到哪儿。"
D.Strings[34070]="兄弟姐妹们，我看到你们的数量正在增长。告诉我，主人的计划实施得如何？"
D.Strings[34071]="看来，一切都按部就班。主人将最重要的任务给了我们，他不会接受失败的。"
D.Strings[34072]="看吧！你面前的世界已经受到了裁决。（火、水、土、风！）元素必将毁灭一切生命！（烧灼、溺死、碾碎、窒息！）"
D.Strings[34073]="加入我们，接受必然的结局吧。（主人的力量在召唤！）你将重生，超越血肉！（超越形体的力量！无穷无尽的能量！）"
D.Strings[34074]="向我宣誓效忠，（主人看要的就要得到，他渴望一切！）——你将被我的精神重新塑造（等等！异端！我们这儿藏着一个异端！）入侵者！你！现身吧……"
D.Strings[34075]="对这些装置的处理正按照你的指示进行。我们很快就能准备好执行你下一阶段的命令了。"
D.Strings[34076]="主人将毁灭这个世界，并按照他的意志重铸全新的世界。而你正是他实现这一目标的工具。"
D.Strings[34077]="当它们完成的时候，你就要把这些装置分散放在奥格瑞玛各处。"
D.Strings[34078]="那家伙可真大。你不该激怒他。"
D.Strings[34079]="等那个时刻一到，它们就会释放出火元素，让这座城市被熊熊烈火吞噬！为我们主人荣耀的恢复而做好准备！"
D.Strings[34080]="食人魔！"
D.Strings[34081]="这个闻起来尤其恶心。"
D.Strings[34082]="干掉它！我会守在这儿。"
D.Strings[34083]="啊，更多的食人魔？"
D.Strings[34084]="别被踩死。"
D.Strings[34085]="他看不见我，对吧？"
D.Strings[34086]="那是暮光伪经？我要被活煮了——它真的存在！"
D.Strings[34087]="嗨。对，我知道。我又被抓住了。$B$B我不想谈这些。$B$B你准备好了吗？"
D.Strings[34088]="嗯？你打算帮我下去吗？"
D.Strings[34089]="好吧，让我们再试一次。"
D.Strings[34090]="嗯，不。你不介意再多吊上一会儿吧？我还得先干点儿别的事。"
D.Strings[34091]="你说……什么？$B$B过来给我再说一遍！$B$B<克里斯托弗因愤怒而乱踢乱抓，面目扭曲的瞪着你。>$B$B快来帮我，不然我就——我就——我就把你打个鼻青脸肿！然后把靴子踩在你肮脏的脸上！你过来！快给我回来！$B$B<克里斯托弗奋力想要掐住你的脖子，抓挠的手指尖几乎就要碰到你的脸。>"
D.Strings[34092]="你对眼睛的研究进展得怎么样了？"
D.Strings[34093]="$n，$n，我能叫你$n吗？$B$B我马上就要被挂到食人魔洞穴里的肉钩子上了。$B$B你觉得我的研究进度如何？你这个中看不中用的笨$c！到这里来！你这个坏家伙！$B$B<克里斯托弗在锁住他的链子上晃来晃去，拼命想要踢到你的脸。>"
D.Strings[34094]="<克里斯托弗哼哼着。>"
D.Strings[34095]="我的兄弟姐妹们，我们应该抛弃这副脆弱的躯壳，升华为不朽之身！"
D.Strings[34096]="在所有远古半神中，戈德林是最杰出的一位。他的狂怒，他的决心……你一定能赶上他。"
D.Strings[34097]="如您所愿，主人。"
D.Strings[34098]="你的位置应该是我的！我要让你瞧瞧！"
D.Strings[34099]="我要杀了你，然后夺回你的位置，渣滓！"
D.Strings[34100]="无论生死，我们都将效忠他们！"
D.Strings[34101]="我才应该是了解上古诸神秘密的那个人！我会让你看看！"
D.Strings[34102]="我是被选中的！我是不可战胜的！"
D.Strings[34103]="暮光领主，请听我说！接受$r这份卑微的贡品吧！"
D.Strings[34104]="泰拉尔主人已经不住在这里了，你这傻瓜。他已赐予我足够的力量来阻止你！"
D.Strings[34105]="我不认识你，你刚到这里吗？"
D.Strings[34106]="这是什么设备，要这么多人共同建造？"
D.Strings[34107]="哦，看来你是个新人。这些装置是我们主人改造世界计划的一部分。它会向整个世界释放出审判的烈火，并让我们得到永恒的生命。这是主人对我们许下的承诺。"
D.Strings[34108]="你不属于这里，陌生人。别惹麻烦，赶快离开吧。"
D.Strings[34109]="不——————！"
D.Strings[34110]="泰拉尔并没有逃离菲拉斯。而是以自己的方式充当着连通恶梦的管道。"
D.Strings[34111]="我不会再逃离。到东边的山峰顶上找我。"
D.Strings[34112]="血卫士，你必须帮我找到他。我完全找不到他！"
D.Strings[34113]="你一定要帮帮我。他去了市场，就再没有回来。"
D.Strings[34114]="你一定能做些什么的，血卫士。"
D.Strings[34115]="他绝对不会单独离开！他到底去哪里了？"
D.Strings[34116]="我的丈夫失踪了。求求你，血卫士，他并不是战士。请一定帮我找到他。"
D.Strings[34117]="你是个通情达理的人，血卫士。如果你的亲人失踪了，你会怎么做？"
D.Strings[34118]="你认为他被绑架了？我还能再见到他么？"
D.Strings[34119]="我并非唯一到这里来报告失踪案件的人。这样的案件已经发生了许多。"
D.Strings[34120]="奥格瑞玛正在发生一些可怕的事情。这里的女人们都在传说有人失踪了。还有人说，世界将要完结。这到底是什么意思？"
D.Strings[34121]="让火焰净化一切！！！！"
D.Strings[34122]="$c，世界末日就要到了。但不需要绝望。听听我所说的，看看我的兄弟所给予你的一切吧。"
D.Strings[34123]="我会听一听你要说些什么。"
D.Strings[34124]="%s匆忙地将一张纸条夹进他的手稿里。"
D.Strings[34125]="%s查看着他的手稿，不住地嘟囔着。"
D.Strings[34126]="%s摆弄着工作台上一些奇形怪状的工具。"
D.Strings[34127]="%s轻声笑着，仔细地把进展情况记录在他的手稿里。"
D.Strings[34128]="你现在妨碍的是你这榆木脑袋根本无法理解的工作！"
D.Strings[34129]="我想加入你们的行动。"
D.Strings[34130]="我还需要一件长袍。"
D.Strings[34131]="兄弟姐妹们，聚集在圣坛周围吧！真相即将被揭示！"
D.Strings[34132]="诺莫瑞根的居民和朋友们！"
D.Strings[34133]="我们曾经是难民，是被放逐之人，是饱受辐射之苦，被拴在战争机器上的奴隶！但是，灾难已经过去！"
D.Strings[34134]="我们将终结瑟玛普拉格的统治！"
D.Strings[34135]="我们的战术，我们的技术，我们的勇气和决心都无可匹敌。"
D.Strings[34136]="诺莫瑞根行动正式开始！"
D.Strings[34137]="目标进入视野！各小队，摧毁全部敌方火箭发射器！"
D.Strings[34138]="干掉了一个。保持攻势！"
D.Strings[34139]="又摧毁了一个。给我继续攻击！"
D.Strings[34140]="干得好。不要松懈！"
D.Strings[34141]="我们占领了机场，也掌握了制空权。"
D.Strings[34142]="今天，我们将消灭叛徒瑟玛普拉格，夺回我们光荣的城市！"
D.Strings[34143]="请加入我们的队伍，光复我们失落已久的家园！"
D.Strings[34144]="在待命区集结！"
D.Strings[34145]="进攻马上就要开始了！"
D.Strings[34146]="第一阶段：我们将夺取敌方机场！"
D.Strings[34147]="摧毁火箭发射器，完全取得制空权！"
D.Strings[34148]="现在多重轰炸机可以摧毁瑟玛普拉格的反坦克大炮护盾了。"
D.Strings[34149]="第二阶段：攻占地面指挥所！"
D.Strings[34150]="多重轰炸机摧毁了反坦克大炮的护盾。端掉那些大炮，攻占地面指挥所！"
D.Strings[34151]="陷阱！一台全线运作的辐射器！"
D.Strings[34152]="我们占领了地面！诺莫瑞根行动完成进度93%%……干得好！"
D.Strings[34153]="我会关闭防御辐射泵。各小队，拿上剩余的机械装备，向主入口全速前进。"
D.Strings[34154]="朋友们，我们已经站到了胜利的边缘。第三阶段：进入隧道！"
D.Strings[34155]="一旦我们攻占了地下铁路和码头，我们就可以对城市中心发动快速突袭。"
D.Strings[34156]="光复诺莫瑞根近在咫尺！"
D.Strings[34157]="绝不！等等……这东西启动了？是这个……按钮？测试……测试。啊！*咳嗽*"
D.Strings[34158]="绝不！诺莫瑞根是我的，梅卡托克。"
D.Strings[34159]="你自以为能闯进我的城市？"
D.Strings[34160]="马上激活一次性原子防御系统：把穴居人都给我派过去！！！"
D.Strings[34161]="我的天啊……这座城里的穴居人一定全都杀出来了！"
D.Strings[34162]="全队注意，准备手榴弹和压制火力……坚守战线！我们绝不会退却！"
D.Strings[34163]="我的娘亲啊！这是我见过的最大的穴居人！继续开火……把它干掉！"
D.Strings[34164]="太安静了。瑟玛普拉格的军队在哪里？"
D.Strings[34165]="这是什么？这就是那颗污染了诺莫瑞根的辐射炸弹……等等！有情况！"
D.Strings[34166]="不！不，不，不！！！我不会让你进入我的王国！我绝不允许！"
D.Strings[34167]="激活终极原子保卫系统。"
D.Strings[34168]="……彻底粉碎他们！"
D.Strings[34169]="这……比第一个强大二十六倍！"
D.Strings[34170]="十分钟！你还没改那东西的设置？快把控制器给我，白痴！"
D.Strings[34171]="你失败了，梅卡托克！别想踏入我宝贵的城市！"
D.Strings[34172]="哦，我想看看那个老家伙的脸。我打赌他……什么？它还开着？快关掉……"
D.Strings[34173]="十分钟？足够拆除这个装置了。"
D.Strings[34174]="辛克尔斯，把高速青铜齿轮和清凉的泉水给我。克斯宾，扔给我肮脏的穴居人布片和一把螺栓……"
D.Strings[34175]="呦喔！雷戈，送我们回去，赶快！"
D.Strings[34176]="见鬼！我们必须撤退。但瑟玛普拉格已经失败了。他清楚这一点……现在他只是在垂死挣扎。"
D.Strings[34177]="我们控制了地面，等到辐射被清除干净，我们就会以更加强大的攻势彻底占领诺莫瑞根。"
D.Strings[34178]="必须有人报告这里的情况！"
D.Strings[34179]="快说，食人魔。这些宝珠是谁给你们的？"
D.Strings[34180]="部落的战士们，我们将赞颂$n的勇气。正是$g他:她;发现了暮光之锤侵害这座城市的阴谋！"
D.Strings[34181]="我们必须揭开这些谣言的真相，阻止暮光之锤在我们之间散播恐惧！"
D.Strings[34182]="不想说。"
D.Strings[34183]="谁给的你能量？"
D.Strings[34184]="古加尔！"
D.Strings[34185]="暮光之锤？！他们在哪儿？"
D.Strings[34186]="很好。现在你可以滚了。"
D.Strings[34187]="厄运之槌！厄运之槌！"
D.Strings[34188]="魂角酋长，我恳求你立刻向西岸峰派出援军，否则一切都将无法挽回。"
D.Strings[34189]="千针石林深埋在数百尺深的水底。你有勇气帮助我们吗？"
D.Strings[34190]="大灾变把东部山脉碾碎。南海的水灌入并吞没了整个千针石林！你能在这紧要关头帮帮我们吗？"
D.Strings[34191]="拜托了。我们正在西岸峰展开救援工作。千针石林已经消亡了！"
D.Strings[34192]="我明白大灾变也同样袭击了菲拉斯，但莫沙彻营地看上去还相对安全。你愿意伸出援手吗？"
D.Strings[34193]="要是你不能派帮手前往西岸峰，也许能让乱风岗的难民到莫沙彻营地的边上待一阵子？"
D.Strings[34194]="我担心要是援军不能尽快赶到千针石林的话，恐怖图腾就会开始行动了。我们无论如何都坚守不了多久。"
D.Strings[34195]="要是千针石林的舒哈鲁被击败，恐怖图腾部族很快就会出现在你家门口。现在是时候行动了，魂角酋长！"
D.Strings[34196]="我来这里是为了研究灵魂精华——野性魔法的作用方式。巫医尤克里派我来从森林里的低等生物入手。"
D.Strings[34197]="你好，$c。$B$B山脉崩塌，大灾变造成海水灌入，淹没了千针石林。$B$B我们需要你的帮助，就是现在！"
D.Strings[34198]="夏恩，我得赶往西岸峰！"
D.Strings[34199]="请帮帮我！他们要杀我！"
D.Strings[34200]="在主人的烈焰中燃烧吧！"
D.Strings[34201]="使用水晶的力量击败元素！我坚持不了多久……"
D.Strings[34202]="这是个好人，$r。我们曾在多次战争中并肩作战……$b$b这些野兽有债要偿！"
D.Strings[34203]="3000型辐射器已开启。注意，紧急。你有十分钟来抵达最近的安全区域。"
D.Strings[34204]="*哔*注意，紧急。你有十秒钟来抵达最近的安全区域。"
D.Strings[34205]="从这块神秘的水晶中获取新的能力，并用这些能力保护火语者杜莱克！"
D.Strings[34206]="我们绝不向这些懦夫低头！部落将团结一致对抗所有敌人！Lok'tar Ogar！"
D.Strings[34207]="擅闯者死！"
D.Strings[34208]="本该如此……"
D.Strings[34209]="海里昂会高兴的。"
D.Strings[34210]="啊，娱乐要开始了！"
D.Strings[34211]="我……没想到会这样……"
D.Strings[34212]="巴尔萨鲁斯从不留活口！"
D.Strings[34213]="这个世界的英雄够多了。"
D.Strings[34214]="双倍的痛苦不过是个开始。"
D.Strings[34215]="该死的泰坦……为什么他们的每一套设备中都要使用不同机械装置？"
D.Strings[34216]="感谢你救了我。等我恢复了体力，就会回到奥格瑞玛去。"
D.Strings[34217]="多管闲事的虫子！你们来晚了。红玉圣殿已经沦陷了！"
D.Strings[34218]="咪呜！$R是我们的好朋友。快跟上！我们要找到入侵者！"
D.Strings[34219]="我们发现坏人了！赶快！"
D.Strings[34220]="你是怎么找到我的？这无关紧要……反正你得死！"
D.Strings[34221]="我被发现了？受死吧！"
D.Strings[34222]="你别想泄漏我的行踪，$c！"
D.Strings[34223]="就算你发现了我，你也别想把消息带给别人！"
D.Strings[34224]="你永远也得不到这些石板！"
D.Strings[34225]="继续进攻！"
D.Strings[34226]="我会得到这些石板！"
D.Strings[34227]="干掉信使！"
D.Strings[34228]="我们向艾森娜发出的祈求没有得到回应。拉格纳罗斯麾下的燃烧爪牙已经将我们逼到了悬崖的边缘。如果我们不能在此终止他们的行径，世界之树将被大火烧得只剩下残桩断枝！"
D.Strings[34229]="生命的希翼已被斩断。$B$B梦游者一定会复仇的。"
D.Strings[34230]="走上前来，泰拉尔！我就站在你面前！"
D.Strings[34231]="我就知道你会回来的，伊森德雷……只是时间问题……"
D.Strings[34232]="平静？“平静”？"
D.Strings[34233]="我回来只为了结这件事，泰拉尔。这片土地终将获得平静。"
D.Strings[34234]="你到这里来是为了打扰我们吗？我们只想在静瑟中独处。"
D.Strings[34235]="在这里晃荡是没用的，朋友。这座城市中有许多我们的人，你可以从他们那里得到更多关于我们的信息。"
D.Strings[34236]="这里没有地方留给外人。回暴风城去吧，陌生人。"
D.Strings[34237]="我的精华将……永存……。"
D.Strings[34238]="世界末日即将到来！"
D.Strings[34239]="艾泽拉斯即将完结。赶快忏悔吧！"
D.Strings[34240]="跟我来，兄弟姐妹们，去了解这个世界的真相吧！"
D.Strings[34241]="我们的世界将四分五裂。加入我们才能活命！"
D.Strings[34242]="想要从即将到来的劫难中获得拯救，现在还不晚！"
D.Strings[34243]="整个世界都将被元素吞噬！"
D.Strings[34244]="没有必要和艾泽拉斯一同灭亡。跟随我，得生存！"
D.Strings[34245]="抛下你们的家园，你们的财产，还有你们所珍爱的一切，加入我们吧！"
D.Strings[34246]="你还没完成使命！"
D.Strings[34247]="你已经完成了使命！"
D.Strings[34248]="这正是我们需要的，更多的蠢货！"
D.Strings[34249]="难道你们还没有厌倦这样一遍又一遍地重复同一件事吗？"
D.Strings[34250]="教徒们，不要再扰乱和平了！"
D.Strings[34251]="穿成这个德行还想让我听你的？"
D.Strings[34252]="嘿，看啊，希尔瓦娜斯女士有了个新的傻瓜弄臣！"
D.Strings[34253]="为什么你不去找找会在乎它的人？"
D.Strings[34254]="这种世界末日的胡言乱语已经够多了！"
D.Strings[34255]="看啊，酋长给我们送来了娱兴节目！"
D.Strings[34256]="石槌为部落而战！"
D.Strings[34257]="啊……$b$b我的感觉……不太好……"
D.Strings[34258]="多谢你，$c。$b$b我差一点儿死在那了。"
D.Strings[34259]="我坚持不住了……"
D.Strings[34260]="情势的确十分严峻。我们必须找到这种疾病的真正诱因——为了这片土地。"
D.Strings[34261]="一头化身成凡人的绿龙！我从没有想过能够得到这样的光荣……"
D.Strings[34262]="我们来此为我们的人民守护这些土地。"
D.Strings[34263]="向右倾！\n\n|TInterface\\Icons\\misc_arrowright.blp:32|t"
D.Strings[34264]="你失去控制了。小心！"
D.Strings[34265]="$R，你要找我？自从主人去世之后，我已经被遗弃多久了？"
D.Strings[34266]="耐心点儿，朋友。让我帮你准备下一次尝试。"
D.Strings[34267]="你的部族从哪儿得到这些宝珠的，食人魔？"
D.Strings[34268]="欢迎你，$c。$B$B海加尔燃起了熊熊烈火，我耗尽毕生心血保护的世界已在毁灭的边缘。$B$B告诉我——你可曾听说过泰拉斯·黑角这个名字？"
D.Strings[34269]="你这恶心的怪物。你玷污了神圣的埃雷萨拉斯，现在又胆敢冒犯我？快说！"
D.Strings[34270]="暮光之锤……有趣。他们在你们的“厄运之槌”里？"
D.Strings[34271]="那里不再是你的家了，食人魔。另找个安全的地方安家吧——那地方已经不再适合你。"
D.Strings[34272]="多年的研究把我带到了这里。$b$b我现在还不想回头……"
D.Strings[34273]="真……真冷……"
D.Strings[34274]="泰拉斯·黑角是谁？"
D.Strings[34275]="古……古加尔给我们……魔球……暮光之锤部族让我们强大……"
D.Strings[34276]="对！厄运之槌！快放开……好冷……"
D.Strings[34277]="十年前，在海加尔山的顶峰爆发了一场旷世之战。污染者阿克蒙德指挥恶魔大军攻占了世界之树，并将其力量据为己有。$B$B他的战败标志着燃烧军团入侵艾泽拉斯计划的终结……但他许多堕落的支持者却仍没有离开。"
D.Strings[34278]="黑角是魔鬼？"
D.Strings[34279]="既是又不是。他现在也许是个恶魔，可泰拉斯·黑角曾经是个暗夜精灵。就像他用恶魔军团许给他的权利去劝诱和转变的那些同胞一样。$B$B在主人战败后，他被俘获并关在这顶峰上，神圣能量缚住了他不朽的人形。$B$B可也许在他心中仍有最晦暗的灵魂火光在燃烧……我们至少要设法弄个明白。"
D.Strings[34280]="是的，黑角。我奉命前来请求你的帮助——如果你愿意伸出援手。"
D.Strings[34281]="我的帮助？事态已经恶化到如此地步了吗？$B$B<黑角残忍的黑色瞳仁里闪着许久未见的光焰。>$B$B告诉我，我为什么不该让你的世界自生自灭？"
D.Strings[34282]="我在这里是为了防备有人晕倒。新兵们有时会因为过度兴奋而导致体力透支。\n\n……嗯，有时候那种新型步行坦克也会爆炸。轰！"
D.Strings[34283]="因为你曾是个凡人，黑角。和我们一样。"
D.Strings[34284]="凡人？不错，我曾是个凡人。弱小的凡人。$B$B你看到我现在所受的束缚了吗？但与身为凡人的桎梏相比，这些根本算不了什么。$B$B甚至现在，我主人的馈赠都在我体内激涌，随时准备释放。$B$B不，$c，凡人的身份已经离我远去，假如我体内还有丝毫过往生命的残焰在燃烧，我也希望它尽快熄灭。你最好去想其它办法，$r。"
D.Strings[34285]="要是暮光之锤毁了这座山，你也会被一并毁灭掉！"
D.Strings[34286]="被摧毁了？好吧，这也有可能。深夜里，我常常会受到同一个噩梦的困扰——这个世界从内部被撕成了碎片。但我并不觉得哀伤，也没有愤怒。只是……好奇。$B$B$c，我侍奉我的主人，从而换取力量。但你与之战斗的这些家伙……他们想要的只有灭亡。这真是一个奇怪的动机。"
D.Strings[34287]="麦托克劳相信，你仍值得被宽恕。这是你的机会，为投靠恶魔的行为赎罪。"
D.Strings[34288]="<黑角挣扎了一下。他第一次显露出烦乱的神情。>$B$B算了吧！难道你真能逃出燃烧军团的魔爪吗？不要自鸣得意了！难道你们十年前的所为和在外域的所作所为曾经减慢过燃烧军团的步伐吗？他们一定会回来的，$r。他们会回来。我则会在这里迎接他们。"
D.Strings[34289]="你的主人现在在哪儿，黑角？现在弃暗投明还不算太晚……"
D.Strings[34290]="你愿意帮我们击败他们吗？"
D.Strings[34291]="如果真的有一个世界等待着你的军团去征服，暮光之锤也会把那里的一切都摧毁。"
D.Strings[34292]="%s发出一声尖叫！"
D.Strings[34293]="<咳嗽。>$b$b我……死了吗？"
D.Strings[34294]="你很有天赋，$n。但仁慈使你懦弱。"
D.Strings[34295]="你是谁，朋友？"
D.Strings[34296]="我的生命已逝。要是在我生命的最后时刻还能效力的话，我将再所不辞。听凭你的安排……"
D.Strings[34297]="勇敢的士兵，你高贵的牺牲绝不会被忘记。"
D.Strings[34298]="……主人？"
D.Strings[34299]="当它们完成的时候，你就要将这些装置隐藏在暴风城各处。"
D.Strings[34300]="向左倾！\n\n|TInterface\\Icons\\misc_arrowleft.blp:32|t"
D.Strings[34301]="这里是灾变的中心。$b$b纳迦在这里的活动一定不是巧合。我们必须揭穿他们的意图！"
D.Strings[34302]="看来国王又有了一个新的宫廷小丑！"
D.Strings[34303]="平时想看一场这样的演出可是要付钱的。"
D.Strings[34304]="他失踪了，我完全不知道该怎么办！"
D.Strings[34305]="一定要帮帮我！他去了市场，就再没有回来！"
D.Strings[34306]="一定有人能帮我！"
D.Strings[34307]="他不会就这样无缘无故地消失！他不是这样的人。"
D.Strings[34308]="我的丈夫失踪了。将军，请一定帮帮我。我不是战士。"
D.Strings[34309]="长官，你是个通情达理的人。如果你的家人失踪了，你会怎样做？"
D.Strings[34310]="失去家人的并非只有我一个。和我有着相同遭遇的人还有很多！"
D.Strings[34311]="你的家人很担心你，他们正在等你回暴风城去。"
D.Strings[34312]="我不能回去了，我和他们之间发生过可怕的争执。抱歉，$n，我真的不能回去。"
D.Strings[34313]="我不能回去了。我已经知道了什么是真实。我的位置是在我新的兄弟姐妹中间。"
D.Strings[34314]="$n，我正在升华的道路上。我已经不能回头了。告诉我的家人，我希望他们一切平安，如果他们决定跟随我，我会在这里等他们。"
D.Strings[34315]="$n，为什么我要回去？这个世界即将完结，而我有机会得到升华。如果他们的道路能够将他们引向真实，就像我的道路一样，那么我们终将重逢。如果不是，我也无法让他们睁开眼睛。"
D.Strings[34316]="听我说，暴风城的市民们。我们已经在黑暗中昏睡了太久。我祈求你们，像我一样睁开眼睛！"
D.Strings[34317]="不要绝望，离开那虚伪的圣光吧，拥抱我给予你们的希望和真实！"
D.Strings[34318]="如果你对我们的信息感兴趣，那么我告诉你，我正在聚集信徒。如果你想要了解更多，就继续和我谈谈。但请小心，暴风城中有无数妄图扼杀真相的人。"
D.Strings[34319]="愚蠢的凡人。燃烧吧。"
D.Strings[34320]="我爱你，森西莉亚，可我必须得离开这儿。"
D.Strings[34321]="噢，维林尼亚斯。你这可怜的傻瓜。你真该早点儿离开。"
D.Strings[34322]="我要赶去与达斯雷玛他们会合。辛德拉已经走得太远了。与魔鬼做交易……我们已经将自己交付给堕落。"
D.Strings[34323]="不！不！"
D.Strings[34324]="现在想要阻止他们已经来不及了。让我给你看看他们的荣光……"
D.Strings[34325]="从这块神秘的水晶中获取新的能力，并用这些能力保护信使托姆恩！"
D.Strings[34326]="你们的世界正在灭绝的边缘摇摆。你们都将见证毁灭时代的到来！"
D.Strings[34327]="享受胜利吧，凡人们，这是你们最后的胜利。回归的主人将烧毁这个世界！"
D.Strings[34328]="又一个“英雄”倒下了。"
D.Strings[34329]="暮光的世界将会让你痛不欲生！够胆量的就进来吧！"
D.Strings[34330]="天空在燃烧！"
D.Strings[34331]="阴影在弥漫！"
D.Strings[34332]="很好，矮人。我要干掉你，然后将这些石板交给古加尔。"
D.Strings[34333]="黑暗能量正在这颗旋转的魔球中脉动！"
D.Strings[34334]="我就是交织的光影！凡人，在死亡之翼的使者面前颤抖吧！"
D.Strings[34335]="让暴风城和联盟的敌人们知道，我不会容许他们肆意散播恐惧和谣言！"
D.Strings[34336]="有了像$n这样的英雄，暴风城已经准备好迎击暮光之锤的任何威胁！"
D.Strings[34337]="我们有足够的时间准备同暮光之锤的战斗。而今天，我们要庆祝$n的胜利！"
D.Strings[34338]="$c，这座城市中弥漫着一种奇怪的气氛。人们都在害怕着什么。还有许多人失踪了。我们必须将这些谜团查清楚。"
D.Strings[34339]="应该有人将这件事告诉国王。同洛戈什谈谈，应该能够让这些教徒明白道理！"
D.Strings[34340]="其它人也会来……凡人的年代……已经远去。"
D.Strings[34341]="战友们的努力逼迫%s进一步进入了物质世界！"
D.Strings[34342]="战友们的努力逼迫%s进一步进入了暮光世界！"
D.Strings[34343]="暗矛的儿女们！部族的朋友们！"
D.Strings[34344]="我们的军队将把那些岛屿从扎拉赞恩的魔爪中解放出来！加入我们吧！"
D.Strings[34345]="扎拉赞恩的末日到了！暗矛部族将再次回到家园。准备出发！"
D.Strings[34346]="你好，睿智的姐妹！暗矛部族感谢你。"
D.Strings[34347]="不必担心，森金之子，岑塔布拉从来不会食言。"
D.Strings[34348]="暗矛部族的武士们，进军的时刻到了！众神与我们同在！准备好了吗？瓦妮拉，岑塔布拉？"
D.Strings[34349]="元素也将与我们同在……"
D.Strings[34350]="……就像这里的野兽。"
D.Strings[34351]="出发！我们先要去找邦桑迪……我们需要他强大的魔精力量。"
D.Strings[34352]="谁在碰我的骨头？这是邦桑迪的东西，绝不允许亵渎！"
D.Strings[34353]="我是沃金，森金之子。伟大的邦桑迪，我需要你的帮助。"
D.Strings[34354]="我知道你是谁，暗影猎手。我知道你想要什么。但你凭什么认为我会帮助你？召唤我可算不上明智的行为……"
D.Strings[34355]="暗矛……我已经很久没有听到这种鼓声……没喝过你们的祭品了。我很想见证你的死亡，沃金，你这个混帐。为什么暗矛要背弃邦桑迪？"
D.Strings[34356]="伟大的英灵，我们饱受欺凌。妖术之主扎拉赞恩夺走了我们的岛屿家园……他让我们疯狂地自相残杀。回音群岛上只剩下他那些失去意识的巨魔奴隶。"
D.Strings[34357]="扎拉赞恩……"
D.Strings[34358]="邦桑迪！请帮助我们！让暗矛部族回到岛国故土，让您的鼓声再次响起！请再次饮下我们的献祭！倾听我，森金之子的誓言！"
D.Strings[34359]="嗯，我想看看你有几分真诚，暗影猎手，对我又有几分价值。"
D.Strings[34360]="你以为你有资格面对我吗？放弃吧，暗影猎手！"
D.Strings[34361]="够了！沃金，你的魔精的确强大。也许你是值得帮助的……"
D.Strings[34362]="伟大的英灵，一切都是为我的部族。"
D.Strings[34363]="嗯。"
D.Strings[34364]="穿越水面，到那个村庄去，夺回它。我将帮助你。"
D.Strings[34365]="等时刻一到，它们就会释放出暴风元素，彻底冲刷这座城市，为我们主人的荣耀回归而铺平道路！"
D.Strings[34366]="这个标志……我以前可能见过……"
D.Strings[34367]="他们正等在那里。我们将为古老的家园而战……我们要夺回我们的岛国！"
D.Strings[34368]="暗矛的英灵们……起来吧！戴上古老的面具，拿起血色的长矛……现在你们将追随沃金而战！"
D.Strings[34369]="去吧！谨慎使用我的恩惠。"
D.Strings[34370]="那就来吧。Al'galar thol，thol al'thaug：末日即是新的开始。"
D.Strings[34371]="不要低估扎拉赞恩……他是一个可怕的敌人，狡诈而且拥有强大的法力。准备好了吗？出发！"
D.Strings[34372]="你的末日到了，恶魔！现在，暗矛部族的儿女们回来了！我们要把你赶进大海……"
D.Strings[34373]="你真是个可怜的家伙，暗影猎手。回音群岛是我的！"
D.Strings[34374]="我们不能让他逃走！"
D.Strings[34375]="只要他在群岛上，就逃不出岑塔布拉的手心。"
D.Strings[34376]="聪明的战士，马上去找到他！"
D.Strings[34377]="他就在西边，在操纵某种黑暗魔法。"
D.Strings[34378]="他灭亡的时刻已经近了。"
D.Strings[34379]="放弃吧，扎拉赞恩，一切都结束了。"
D.Strings[34380]="傻瓜！我不会逃走。我把你引到这里，就是为了消灭你和你珍爱的部族！"
D.Strings[34381]="没关系！我是不可战胜的。没有人能穿越这道屏障！回音群岛是扎拉赞恩的，暗影猎手！永远都是！"
D.Strings[34382]="喔，哈哈哈哈！"
D.Strings[34383]="谁……是谁？"
D.Strings[34384]="扎拉赞恩……你怎么敢抢走我的东西？死去的暗矛都是我的……而现在，你也将加入他们！"
D.Strings[34385]="不！不……不！！！"
D.Strings[34386]="这是邪恶巨魔应有的下场。邦桑迪，我们全体暗矛部族都感谢您。我们将继续赞颂您的荣耀。"
D.Strings[34387]="真高兴能再一次听到暗矛的鼓声。一切小心，森金之子。邦桑迪将在另一个世界，等待你的到来……"
D.Strings[34388]="我们要回到自己的村庄，重建家园……暗矛部族的家园。你愿意加入我们吗，岑塔布拉？"
D.Strings[34389]="我们的命运已经纠缠在一起，沃金，无论结局会是如何，我都会留下。"
D.Strings[34390]="真好，你终于来了！$b$b时间不多，你准备好了吗？"
D.Strings[34391]="噩梦统御一切！"
D.Strings[34392]="我们准备好了！去吧，布莱恩！"
D.Strings[34393]="生命的希冀……"
D.Strings[34394]="加入我们！加入我们！"
D.Strings[34395]="聆听他的声音……"
D.Strings[34396]="黑暗的灰烬在%s周围打着转，他口里吟诵着咒语："
D.Strings[34397]="灰烬燃自位面深渊，烧尽敌人散布梦魇……"
D.Strings[34398]="恐怖之神，雷霆地震，撕裂生灵，威慑凡尘！"
D.Strings[34399]="%s发出一阵残忍的笑声。"
D.Strings[34400]="感谢你，凡人！你在炼狱火海的英雄之举让我逃了出来。"
D.Strings[34401]="作为回报，我会饶你一命。"
D.Strings[34402]="但你的时间已经不多了。是的，凡人。不多了……"
D.Strings[34403]="辛克尔斯在背包中搜索着供给品。"
D.Strings[34404]="克斯宾在他的“巨无霸”背包中找东西。"
D.Strings[34405]="向荒野瞭望台前进。"
D.Strings[34406]="我们的防御牢不可破！我们是真正的诺莫瑞根之子！"
D.Strings[34407]="快用机械鲨鱼的修复功能！"
D.Strings[34408]="话已经说得够多了，伙伴们！现在是行动的时刻！我们不会让那些“天选者”夺走属于我们的东西！我们要夺下这名囚徒，将他献给我们的古老神祗！！"
D.Strings[34409]="就在这一刻，朋友，我们应该问问自己。上古之神希望我们做什么？"
D.Strings[34410]="记住克苏恩的话！牢牢记住！“你的朋友将会背叛你！”而且已经背叛了我们！"
D.Strings[34411]="是的，暮光之锤也许是古加尔建立的。但是谁让它有了今日的地位？是谁在兽人和人类的城市中成功地揭露了真相，散播了混乱？"
D.Strings[34412]="这真是暮光之锤的辉煌时刻。无与伦比的辉煌时刻。首先，我们迎来了死亡之翼领主。而现在……现在伟大的拉格纳罗斯也回来了！"
D.Strings[34413]="一个接一个……我们的敌人都将消亡！一个接一个，他们都将走向毁灭！"
D.Strings[34414]="不接受投降！不放过一个！！不留活口！！！"
D.Strings[34415]="有时候，你不得不问自己：“这样做值得吗？”而答案很简单：“痛苦不是代价，而是奖赏！”"
D.Strings[34416]="F'tagh nah'hat！I'mmathan！Sha'lub nahab！Sha'lub nahab，我的朋友！"
D.Strings[34417]="你将得到奖励！如果你在战场上倒下，你的死亡也将彪炳史册！当他再次在世间崛起的时候，你将站立在他身边！你将分享他的荣耀！"
D.Strings[34418]="已经没有希望了！但兄弟姐妹们，只有当我们失去一切希望的时候，真正的希望才会显现！"
D.Strings[34419]="是的，我的新兵小伙子们。我敌人的敌人的朋友……嗯他也是我朋友的敌人。啊对……他也得死！"
D.Strings[34420]="看看我们已经走了多远！昨天我们还活在文明的阴影下……就像过街老鼠！而今天！今天……海加尔正在燃烧！"
D.Strings[34421]="总是有人鼓吹团结！难道团结就能阻止锁链中最弱的一环断开吗？"
D.Strings[34422]="别以为是运气帮了你们的忙。这和运气一点儿关系也没有。是我们主人的意志把我们带到了这里！"
D.Strings[34423]="我望着这个将我们凝聚在一起的象征——这把锤子。这把锤子象征着建设和创造，也象征着暴力和毁灭！"
D.Strings[34424]="对于所有那些呼吁要在我们组织内部保持和谐的人……我要问问他们：“我们的主人喜爱一切冲突，渴望每一场战火，难道不是这样吗？”"
D.Strings[34425]="我是第一批响应沃金的号召，投身军队的人之一。你愿意加入我们吗？"
D.Strings[34426]="兰德鲁的礼物盒"
D.Strings[34427]="快干塑像"
D.Strings[34428]="炽焰角鹰兽"
D.Strings[34429]="涂料炸弹"
D.Strings[34430]="传送石"
D.Strings[34431]="犀牛坐骑"
D.Strings[34432]="天谴之门"
D.Strings[34433]="这并不能让我完全信服。"
D.Strings[34434]="切。"
D.Strings[34435]="对……我对此一无所知。"
D.Strings[34436]="鲜血！"
D.Strings[34437]="呜哇啊啊啊！！！"
D.Strings[34438]="我听见了那声音！"
D.Strings[34439]="就像……就像虚空刚刚触摸了我的灵魂。"
D.Strings[34440]="一切即将终结！结束就是新的开始！"
D.Strings[34441]="这位$g兄弟:姑娘;懂了！"
D.Strings[34442]="实话实说，$g兄弟:姐妹;！"
D.Strings[34443]="就是这样！耶！"
D.Strings[34444]="就像是从上古之神口中听到这一切！"
D.Strings[34445]="从来没人能如此诚实！"
D.Strings[34446]="我们在缔造历史！"
D.Strings[34447]="这家伙是谁？"
D.Strings[34448]="坐下！"
D.Strings[34449]="你撒谎！"
D.Strings[34450]="你在说什么？"
D.Strings[34451]="我原以为我的首次洋底冒险会是波澜不惊和令我大开眼界的。也许会有种与大自然融为一体的感觉？$B$B可这地方毫无自然之感。我们周围无所不在的元素们都在为复仇而呼号。"
D.Strings[34452]="不是你们所有人都能登上荣耀的顶峰。看看你的左边。再看看你的右边。他们最后都将消亡。但你，却将永存不朽。"
D.Strings[34453]="亘古之前，“泰坦”来此并推翻了我们主人的统治。但这并不是他们的世界，从来都不是！裁决终将到来！"
D.Strings[34454]="一股苦涩的臭气正在我们的队列中蔓延。我们的回答就是净化！净化！净化到暮光之锤再次纯洁！"
D.Strings[34455]="我们行走在绝壁的边缘。我们当中的一些人必须倒下，为的是让其它人能继续前进。"
D.Strings[34456]="一定要记住，只要还有叛徒在呼吸，我们的行动就不可能保持纯洁。你们知道我说的是谁。"
D.Strings[34457]="把一只手掌放于胸前，伸出另一只手去碰触永恒。心中有种柔软的感觉吗？不！你只感到……广大无边。"
D.Strings[34458]="我们挥洒的鲜血正在与我们交谈。它在说——“谢谢”。"
D.Strings[34459]="如果你想要蝙蝠，那么你可是来对地方了。我掌管着全部哨兵的蝙蝠。"
D.Strings[34460]="你！$B$B你以为你能像这样轻而易举的走进来夺走我的位置？再好好想想吧，$g小男孩:小姑娘;！$B$B我听见了会议室里的窃窃私语。在指挥部里围绕在你身边的那些人都是些溜须拍马的狗腿子，为上位不择手段。我应该知道的……当初是我把他们找来的。$B$B你的飞黄腾达只不过是侥幸，而且我已经做好充分的准备把你打回原形！你给我小心点儿，$n。没准儿哪天你还需要我帮你的忙！"
D.Strings[34461]="%s“咯咯”笑着。"
D.Strings[34462]="你为战争做好准备了吗，$r？"
D.Strings[34463]="带我去萨尔多岛。"
D.Strings[34464]="你好啊，长官。"
D.Strings[34465]="多加小心。巨魔太坏了！"
D.Strings[34466]="为什么不给我们来点儿卡亚可乐！我们需要灵感！"
D.Strings[34467]="我们在仔细监视那些巨魔！"
D.Strings[34468]="巨魔们在喋喋不休，长官。"
D.Strings[34469]="你想要我们去痛扁坏巨魔吗？"
D.Strings[34470]="巨魔想找架打吗？"
D.Strings[34471]="卡亚矿石是怎么变成卡亚可乐的？"
D.Strings[34472]="瓦妮拉让我从你这里借一只蝙蝠。"
D.Strings[34473]="我真想能再续上一杯。"
D.Strings[34474]="呃……给我来个桶！"
D.Strings[34475]="要是我能有个舞伴儿就好了。"
D.Strings[34476]="我喜欢焰火！"
D.Strings[34477]="太美味了！还有更多的餐前点心吗？"
D.Strings[34478]="%s即将被你推离暮光世界！"
D.Strings[34479]="%s即将被你推离物质世界！"
D.Strings[34480]="取样成功！"
D.Strings[34481]="取样中断。萨比诺制品致以诚挚的歉意。请尽快在方便的时候再次尝试取样。"
D.Strings[34482]="好啊，我们走！只需要在门禁系统中输入最终登录序列……然后……"
D.Strings[34483]="成功了！控制室应该就在这后面……哦……喔……"
D.Strings[34484]="什么？这儿不是控制室！这儿有另外一套完整的防御系统，那些该死的石头穴居人却闯入了这儿。穴居人，为什么闯进来的是穴居人！"
D.Strings[34485]="好吧，让我好好考虑一下。"
D.Strings[34486]="四个平台，各有一个巨大的元素。"
D.Strings[34487]="我明白了！我读过的一块石板上提到了这个房间。这里就是光明穹顶！好吧，这很简单。冒险者们，去干掉那四个元素，触发远处那道门的开启程序！"
D.Strings[34488]="是的，只要毁了四种元素，门就会打开。我确定。不过要小心那些穴居人。那些脾气乖戾、又臭又脏的生物——尽管他们还没屈服于血肉诅咒。"
D.Strings[34489]="我不知道你怎么样，老兄，可我不能在水下呼吸。"
D.Strings[34490]="|TInterface\\Icons\\inv_mace_15.blp:20|t%s装备好了他的|cFFFF0000战锤|r并且受到了|cFFFF0000|Hspell:75007|h[重若千钧]|h|r效果！"
D.Strings[34491]="镜子指向各个位置。"
D.Strings[34492]="我在此需要用来证明自己的，就是我的爪子！"
D.Strings[34493]="那帽子怎么了？"
D.Strings[34494]="你与大地之环同在，我刚刚想到你应该和他们一样，获得水下呼吸的法术效果。"
D.Strings[34495]="然后放弃我帅气的特制潜水头盔？没门。"
D.Strings[34496]="我能换一个地缚图腾吗？"
D.Strings[34497]="我能换一个石爪图腾吗？"
D.Strings[34498]="我能换一个大地之力图腾吗？"
D.Strings[34499]="我愿意出力。"
D.Strings[34500]="我能换一个土元素图腾吗？"
D.Strings[34501]="一切为了沃金！"
D.Strings[34502]="你可真是个挑剔的小$r啊，不是吗？好吧。去把那个样本拿给我。"
D.Strings[34503]="指引我杀敌！"
D.Strings[34504]="不。别再贪心了。"
D.Strings[34505]="我就是尖端技术的代表，宝贝儿！灌注元素能量的高科技。到艾泽拉斯海洋的最深处去探求失落的学识与新的资源吧。$B$B请牢记我的名字。"
D.Strings[34506]="必须——抵抗……"
D.Strings[34507]="纳迦永远不会效忠于你们这些鼠辈！"
D.Strings[34508]="死也不会屈服……"
D.Strings[34509]="你在跟我浪费时间，弱者！"
D.Strings[34510]="无法……停止！"
D.Strings[34511]="为了珊蒂斯！"
D.Strings[34512]="后退！他的烈焰太灼热了！"
D.Strings[34513]="真……耻辱……"
D.Strings[34514]="我能换一个石肤图腾吗？"
D.Strings[34515]="我们花费了大量精力训练和照料我们的动物们，但这一切都是值得的。$B$B尽管如此，有额外的帮手总是好的。"
D.Strings[34516]="史莉琪，我需要一件新的巨怪伪装服！"
D.Strings[34517]="退后！！！"
D.Strings[34518]="干掉一个！"
D.Strings[34519]="又干掉了一个！快看这些明亮的光柱！他们似乎和远处那道门是相互关联的！"
D.Strings[34520]="只剩一个元素了！大门就要被打开了！"
D.Strings[34521]="你成功了！穹顶的大门被打开了！现在就能……哦，不！"
D.Strings[34522]="喔抱歉……我的图腾冒犯到脆弱敏感的你了？好吧。看这儿。现在回去干活！"
D.Strings[34523]="天哪……你干活时需要让我派菲利斯给你做个全身按摩吗？这儿，拿去。快去找我要的样本！"
D.Strings[34524]="等一下……究竟是谁在替谁做事？要是我给你新的图腾，你能快点儿把那该死的任务完成吗？！"
D.Strings[34525]="此单位已经激活，脱离正常操作程序。正在下载新的操作参数。下载完成。单位完全自我防卫程序现在已被激活。对进入系统的外部单位进行清除，相关程序即将开始。"
D.Strings[34526]="贸易大王的游艇就要扬帆起航了。所有人都到码头上去！把钥匙给我，老板。我来驾驶。做好出发准备以后就通知我一声。"
D.Strings[34527]="新巨魔报道！"
D.Strings[34528]="报告工作。"
D.Strings[34529]="准备开始对扎拉赞恩的战斗。"
D.Strings[34530]="准备同沃金并肩作战！"
D.Strings[34531]="训练什么时候开始？"
D.Strings[34532]="你在这儿真是太好了，朋友！$B$B那些野生动物不得不逃到这片树林里来躲避烈火。它们已经无处可去了。我们必须保护幸存者！"
D.Strings[34533]="它来了，退后！"
D.Strings[34534]="在火熄灭前，别靠近他！"
D.Strings[34535]="珊蒂斯女士正指望我呢。我不会让她失望的。"
D.Strings[34536]="嘿，$g老兄:小姐;！听说你对贸易大王的职位有兴趣。$B$B是真的吗？"
D.Strings[34537]="<大胖哼哼着。你甚至无法确定他是否真的会说话。>"
D.Strings[34538]="嘿你好啊，宝贝儿！你和$g小甜甜:奇普;的传闻是怎么回事？"
D.Strings[34539]="今天可真是个好日子，正适合开挖这世上仅存的卡亚矿石，你不这样认为吗，$n？"
D.Strings[34540]="卡亚矿石在几千年前把我们变得非常聪明，现在却对我们这些巨魔产生不了任何效果，这不奇怪吗？"
D.Strings[34541]="能想到用卡亚矿石蒸馏出卡亚可乐，你可真是个天才啊，$n。贸易大王这下要担心你要抢他的位子了！"
D.Strings[34542]="看看我的魔法力量吧……别想活着离开这座岛屿！"
D.Strings[34543]="我可真想一拳打在奇普的脸上！我还想一口亲在小甜甜的脸上！"
D.Strings[34544]="哈，有人在说“聚会”?"
D.Strings[34545]="这瓶叫做卡亚可乐的玩意儿让我想法不断。我们真需要竞赛来获取灵感吗？"
D.Strings[34546]="从卡亚矿石里蒸馏出的汁水能做成可口的碳酸饮料，让人的脑袋里充满灵感！嘿，等一下……"
D.Strings[34547]="我们找到坏人了！快跟上！"
D.Strings[34548]="他们逃去这边了！赶快！"
D.Strings[34549]="我们在找坏人，是吧？"
D.Strings[34550]="在这边！你必须阻止他们！"
D.Strings[34551]="你现在必须战斗，$n！"
D.Strings[34552]="嘿，嘿！别再怀有敌意了！我就是你们常遇到的那些人畜无害的中立地精，跟部落没关系！"
D.Strings[34553]="嘿，快瞧啊，是$n。我猜$g他:她;肯定富得流油了。听说$g他:她;在竞争贸易大王的位置！"
D.Strings[34554]="苏扎博。他现在太热了！"
D.Strings[34555]="$n抱起一只蠕动的熊崽。"
D.Strings[34556]="我曾经是位女祭司，但我不变的身份却是学者。能够汲取上层精灵的学识，比施行无知的严律要宝贵得多。$B$B更重要的是，这里的大多数学徒，都是在第三次大战期间成年的年轻人。他们需要指引，需要智慧……$B$B我只希望那些曾把我当成朋友的人能明白这一点。"
D.Strings[34557]="你在看着我……你能看见我吗？$B$B请你，帮帮我……"
D.Strings[34558]="在安德麦工作要好得多！"
D.Strings[34559]="我做错了什么？一天连一顿午饭和两次休息都没有吗，老兄？"
D.Strings[34560]="嗷！好疼！"
D.Strings[34561]="我要上告人力官员！"
D.Strings[34562]="帮帮我……求你，如果你能听见，请帮帮我……"
D.Strings[34563]="你真是太好了，$n。因为维林尼亚斯，我被关在这儿太久了。那个年轻的精灵是我多年来尝到的第一个灵魂。"
D.Strings[34564]="就算我把那形态给了他，他还是坚持要把我困住。他甚至还把所有灵魂都藏了起来，就是为了不让我得到……真是太顽固了。"
D.Strings[34565]="我欠你个人情，宝贝儿……有一天我会回来偿还。"
D.Strings[34566]="暂时够了！"
D.Strings[34567]="不要这么惊讶。你的萨满朋友有着明察秋毫的眼睛，或者说，有着明察秋毫的青蛙。"
D.Strings[34568]="我们德鲁伊一直潜伏在这里，等待着，看沃金是不是会回来。"
D.Strings[34569]="看样子，暗矛部族正在返回这些岛屿。也许我们现身的时候到了。"
D.Strings[34570]="回到沃金那里去，告诉他：岑塔布拉已经做好了和他并肩作战的准备。"
D.Strings[34571]="一切都化为了废墟……"
D.Strings[34572]="水冲了进来，把一切都淹没了！"
D.Strings[34573]="你必须前往千针石林提供帮助。拜托了！"
D.Strings[34574]="愿大地母亲保佑我们。"
D.Strings[34575]="我们失去了乱风岗。千针石林被毁了。"
D.Strings[34576]="为哨兵守住这片区域，将是我们守卫菲拉斯任务的最后一步。"
D.Strings[34577]="大地母亲为什么没有护佑我们？"
D.Strings[34578]="魂角酋长必须立刻向乱风岗派出援军。"
D.Strings[34579]="他们把它叫做大灾变。这毁灭因何而起？为什么是我们？"
D.Strings[34580]="猛虎之灵，将你的力量借给$n，帮助我们找到答案吧！"
D.Strings[34581]="猛虎女王出现了！在战斗中证明你自己吧！"
D.Strings[34582]="布洛格，我请求你立刻派些地精前往西岸峰，趁现在还来得及。"
D.Strings[34583]="我好象是丢了一件制服。"
D.Strings[34584]="化为废墟的千针石林沉没在数百尺深的水底。你能派些地精来帮助我们吗？"
D.Strings[34585]="我明白大灾变也同样袭击了尘泥沼泽，但泥链镇看上去还相对安全。你愿意派些地精来帮忙吗？"
D.Strings[34586]="要是你不能派人前往西岸峰帮忙，那我们能把难民送到这儿来吗？"
D.Strings[34587]="要是千针石林的舒哈鲁被击败，恐怖图腾部族很快就会出现在你家门口。现在是时候行动了，布洛格！"
D.Strings[34588]="你必须留在回音群岛、暗矛海滩或者是森金村。"
D.Strings[34589]="布洛格。你不介意我这样称呼你吧？等等，我是在和哪个头说话？"
D.Strings[34590]="我们需要你和你的地精伸出援手。千针石林被毁了！萨兰纳尔已经沉在水底！"
D.Strings[34591]="你们现在谁是负责人？新萨兰纳尔现在需要你们的帮助！"
D.Strings[34592]="你们必须在这紧要关头向我们施以援手。对新萨兰纳尔的攻击已经迫在眉睫！"
D.Strings[34593]="是的，不会让你们白忙。"
D.Strings[34594]="你不是戈多克或戈杜尼部族那边的，对吧？"
D.Strings[34595]="大灾变对千针石林造成的影响最大。拜托了，可以帮帮我们吗？"
D.Strings[34596]="兔子和小鹿？是的，我们有那些动物。你现在能来新萨兰纳尔帮我们了吗？等等……你为什么会问这个问题？"
D.Strings[34597]="大灾变毁了千针石林的西部山脉。南海灌入并淹没了峡谷。$B$B拜托了，$c，你必须来新萨兰纳尔帮帮我们！"
D.Strings[34598]="大灾变毁掉了千针石林，$c。你愿意在我们最危难的时刻来帮帮我们吗？"
D.Strings[34599]="你们的训练进行得很顺利，姐妹们。过不了多久，你们就能带领自己的人民，再不需要我的教导。"
D.Strings[34600]="他现在很容易受到我们魔法的伤害！把他打倒！"
D.Strings[34601]="是时候让我瞧瞧你的领导力了。塔姆布莉，你将率军在萨尔多岛展开攻势。你一定能在那里为你的勇猛找到用武之地。"
D.Strings[34602]="西尔维亚，我要派你前往埃斯图兰之塔驱逐那些戈杜尼食人魔。看看你的外交手段和战略对策能否经受住考验。"
D.Strings[34603]="艾德娜，你必须向遥远的东边出击。我们的军队一定要夺回东部荒野，监视那些从未见过的部落。愿你的判断力与你的枪法一样精准。"
D.Strings[34604]="德斯利克，我要前往西岸峰！"
D.Strings[34605]="我很看好你。别让我失望。去吧！"
D.Strings[34606]="德斯利克，我要前往新萨兰纳尔！"
D.Strings[34607]="嗯？你找到什么了吗，小子？"
D.Strings[34608]="没错，把它挖出来。身后不留活口！"
D.Strings[34609]="你找到什么了，蠢猪？"
D.Strings[34610]="那个小姑娘！全都挖出来——一处都不放过。"
D.Strings[34611]="蠢猪。这地方已经没东西可挖了。继续前进！"
D.Strings[34612]="挖，挖，挖。烧，烧，烧。彻底的翻查这个地方！"
D.Strings[34613]="%s闻了闻，朝焦黑的土壤中挖去。"
D.Strings[34614]="塞亚娜，我要前往新萨兰纳尔！"
D.Strings[34615]="艾德琳，你不能请你的朋友来新萨兰纳尔帮助我们吗？"
D.Strings[34616]="千针石林被南海吞噬。萨兰纳尔已沉入水底！"
D.Strings[34617]="千针石林的东部山脉崩塌入海，南海的海水倾灌而入。什么都没剩下。"
D.Strings[34618]="大灾变毁了千针石林。我们需要你的帮助，以挽救尽可能多的生命！"
D.Strings[34619]="现在到了证明你对联盟忠心的时候了。请派出任何你所能调派的人手前往新萨兰纳尔。"
D.Strings[34620]="我们已经失去了萨兰纳尔，但跟许多人比起来这点损失还不算什么。我们是幸运的，洪水来袭时就处在灾区边缘。我甚至无法开始想象，有多少生命在瞬间陨落。请你尽力帮助我们建设新萨兰纳尔。"
D.Strings[34621]="相对而言，大灾变对菲拉斯的影响并不大。你当然能派些人前往新萨兰纳尔对吧？"
D.Strings[34622]="我们正在新萨兰纳尔对从千针石林逃出的所有幸存者展开救援。我们现在需要你的帮助！"
D.Strings[34623]="够了！这洞是你的了，小萨满。"
D.Strings[34624]="$C，这场大灾变震碎了山脉。南海淹没了千针石林。$B$B我们需要你的帮助！"
D.Strings[34625]="愿英灵指引你，$c。"
D.Strings[34626]="让我们来解读预兆。"
D.Strings[34627]="恐怖图腾出其不意地突袭了我们。我们就快要坚持不住了。"
D.Strings[34628]="暗矛的成员们，我们要向祖灵寻求答案！鼓手，立刻就位！"
D.Strings[34629]="伟大的英灵啊，我们聚集于此，寻求您的指引。"
D.Strings[34630]="我们的领袖，森金之子沃金向全体暗矛部族的成员发起了号召：夺回回音群岛。"
D.Strings[34631]="伟大的英灵啊！我向您献出自己的身躯。请通过我说话吧！现在是不是强大的沃金开始行动的时刻？"
D.Strings[34632]="巫医，祖先听到你的话了！"
D.Strings[34633]="你们的计划让我们喜悦，暗矛部族，森金之子的道路是正确的。"
D.Strings[34634]="你们的任务相当艰巨，但你们将得到我们的祝福。"
D.Strings[34635]="你们离开回音群岛，放弃了家园和祖先的光荣。祖先不喜欢你们如此冷漠沉寂。"
D.Strings[34636]="如果你们想要击败扎拉赞恩，你们就必须向亡魂的守护者邦桑迪赎罪。把这件事告诉森金之子。"
D.Strings[34637]="祖灵祝福了我们！回音群岛将再次成为我们的家园！"
D.Strings[34638]="我不会为了救你而丧命，暮光小子！"
D.Strings[34639]="在我们最为危难的时刻，恐怖图腾怎么能对我们作出这种事？"
D.Strings[34640]="莫特加，能再为我派一名水域探险家吗？"
D.Strings[34641]="看看这惨状，$c！放眼望去，视线所及到处都是鲜血与灰烬。$B$B但自然不会如此轻易被打败。只要我们做些努力，这片焦灼的土地将会重焕生机。"
D.Strings[34642]="我认为符文图腾在这毁灭的中心地带设营是在鲁莽行事，可我并不会让大德鲁伊只身来此。$B$B他在酝酿着什么计划，大计划。"
D.Strings[34643]="这群恐怖图腾畜生很快就要去见他们的造物主了！"
D.Strings[34644]="瑞恩多尔，我还能再搭乘一次水上旅行者吗？"
D.Strings[34645]="暗矛部族的战士们，我们的领袖，伟大的沃金已经准备好夺回回音群岛了。"
D.Strings[34646]="等待在前方的战斗将是对我们的战斗力和忠诚心的真正试炼。"
D.Strings[34647]="我们聚集在森金村的海岸，来夺回本属于我们的东西！"
D.Strings[34648]="来吧！我们将解放回音群岛！扎拉赞恩必将失败！"
D.Strings[34649]="祖先的灵魂在注视着我们，并在战场上帮助我们。"
D.Strings[34650]="要让他们为我们而骄傲！让他们看到你们的勇敢和强大！为祖先的英灵夺取新的光荣！"
D.Strings[34651]="最重要的是，我们要让扎拉赞恩明白，他的末日到了！他将把从我们这里夺走的一切归还给我们！"
D.Strings[34652]="扎拉赞恩让他的大多数巨魔妖术师藏在那座大岛上的树屋里面。"
D.Strings[34653]="他有一支规模很大的军队，而且他正在策划着一个阴谋。"
D.Strings[34654]="谢谢你，哨兵。你还要继续巡逻的工作。不过现在你应该去休息一下。解散。"
D.Strings[34655]="我的迅猛龙能战胜任何事任何人！"
D.Strings[34656]="你！你这蠢货杀了我的屠夫！我要碾碎你！"
D.Strings[34657]="导师德沃兰给你的迅猛龙找来了个对手。"
D.Strings[34658]="快逃离炽焰训练师吧！"
D.Strings[34659]="你想要什么，沃金？我正在忙着为战争做准备。"
D.Strings[34660]="%s用一声战吼鼓舞起了其他战士的士气。"
D.Strings[34661]="我告诉你，那个科林·烈酒是个疯子。\n\n他没有受邀请参加美酒节的美酒竞赛不是我的错！但这并不能阻止他和他的黑铁同伙殴打我的雇员，还喝光了我的藏酒。\n\n必须有人阻止他的暴行！"
D.Strings[34662]="排队等待科林·烈酒战斗。"
D.Strings[34663]="必须阻止冰霜领主埃霍恩。\n\n现在他正在获得现实的躯体。暮光之锤的疯狂教徒们将它从元素牢狱中召唤了出来。\n\n如果他完全进入我们的世界，他会用永恒的寒冬埋葬我们。"
D.Strings[34664]="排队等待冰霜之王埃霍恩之战。"
D.Strings[34665]="请……救……\n\n……无头骑士……必须阻止……\n\n他杀了那么多人！每天月亮升起的时候，他还去寻找更多牺牲者！"
D.Strings[34666]="排队等待无头骑士战斗。"
D.Strings[34667]="必须有人去阻止皇冠药剂公司。我用我的黄金虚空火箭打赌，他们那些让人发疯的巧克力里一定酝酿着另一个大阴谋……\n\n如果有人能逮捕他们的药剂师就好了！这样我们就能结束这场阴谋……也许还能取得他们的全部财产！"
D.Strings[34668]="排队等待皇冠药剂公司之战。"
D.Strings[34669]="$g小子:姑娘;，你带了一些石头进来，却没有说明。\n\n你想要干什么？"
D.Strings[34670]="搞臭科林·烈酒的酒。"
D.Strings[34671]="什么？！你说什么？！你怎么敢这样！我的啤酒比他们在美酒节喝的那些烂东西要好得多！\n\n你要为你所做的付出代价，$c！"
D.Strings[34672]="战斗"
D.Strings[34673]="道歉。"
D.Strings[34674]="我需要去剃刀岭，为沃金招募新兵。我能借一只蝙蝠吗？"
D.Strings[34675]="我已经做好了夺回回音群岛的准备。带我去军队集结地吧！"
D.Strings[34676]="你怎么敢这样！你阻止不了埃霍恩大人！"
D.Strings[34677]="冰霜领主……将……毁灭你……"
D.Strings[34678]="这一定会很迷人！"
D.Strings[34679]="欢迎来到侏儒区！"
D.Strings[34680]="用这块石头召唤埃霍恩大人。"
D.Strings[34681]="沃金跪倒下去，开始了颂唱。"
D.Strings[34682]="瓦妮拉，你会再次召唤猛虎之魂吗？"
D.Strings[34683]="守卫防火结界！"
D.Strings[34684]="胜利！防火结界守住了。"
D.Strings[34685]="扎拉赞恩就要完蛋了。回音群岛将再次属于暗矛部族！"
D.Strings[34686]="暗矛部族回到了家园！$n，如果没有你的帮助，我们无法实现这个梦想。现在，让我们庆祝吧！"
D.Strings[34687]="这个裂口通往水元素位面。猎潮者耐普图隆的国度。"
D.Strings[34688]="纳迦正在和暮光教派合作，而这就是他们努力的焦点所在。"
D.Strings[34689]="前景真是令人堪忧。可如果没有更多的人手，我们几乎什么都做不了。"
D.Strings[34690]="菲兹尔与普兹克赛艇平台——我的小宝贝儿！是我造出来的！不是他们，不是拉泽瑞克！$B$B它应该叫做金吉赛艇平台才对！"
D.Strings[34691]="战士们正在清除扎拉赞恩的余党。"
D.Strings[34692]="你现在可以随时派遣建筑工人开始工作了。现在有许多工作正等着他们呢。"
D.Strings[34693]="谢谢你，侦察兵。告诉那些建筑工人，这片群岛需要他们。暗矛部族将重建家园！"
D.Strings[34694]="暗矛部族的战士们，森金之子沃金将率领你们走向胜利！"
D.Strings[34695]="我们战士的勇气和力量无人可及！"
D.Strings[34696]="兄弟们，我们的祖先正自豪地看着你们！"
D.Strings[34697]="感谢祖先们！感谢伟大的邦桑迪！我们在此奉上我们感激的心情！"
D.Strings[34698]="不要忘记我们盟友的帮助。不要忘记来支援我们的部落战士！现在，正是我们一同庆祝这个伟大胜利的时刻！"
D.Strings[34699]="我的任务就是确保整个进攻行动像时钟一样准确地进行。$B$B大工匠梅卡托克已经到战场去了，但他正计划返回这里，再将更多的部队带上战场。$B$B他从不会迟到，所以你应该在这里等他。"
D.Strings[34700]="|TInterface\\Icons\\ability_druid_infectedwound.blp:20|t%s扬起身子，发动了|cFF01FFE1爆裂打击！|r"
D.Strings[34701]="|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s开始施放|cFFFF6F00|Hspell:75218|h[烈焰祈祷]|h|r!"
D.Strings[34702]="快点！你现在应该去找梅卡托克！如果我们不尽快开始进攻，我们就要耽误行动了。$B$B如果我们耽误的话，我们的首领可是要发火的！"
D.Strings[34703]="失败了！防火结界被摧毁了。"
D.Strings[34704]="|cFFFF2222嗜血鲨鱼因为贪食而陷入疯狂！|r"
D.Strings[34705]="菲兹尔、普兹克、金吉……他们都把自己当成我们的救星。但其实是我！船是我造的！$B$B它应该叫拉泽瑞克的赛艇平台！"
D.Strings[34706]="什么？我要让那小矮子瞧瞧！"
D.Strings[34707]="沃金要我在他回来之前一直敲这面鼓。如果你在等他，那么我可以告诉你，他很快就会回来夺回这些岛屿了。$B$B暂时先在这里等一等他，欣赏一下这音乐吧！"
D.Strings[34708]="沃金正在等你。你现在应该和他谈一谈。我的双臂已经有些疲惫了。$B$B但进攻回音群岛的行动很快就要开始了。"
D.Strings[34709]="在哪儿？！他在哪儿？"
D.Strings[34710]="该死的！是谁杀死了那个人类？这可不好！"
D.Strings[34711]="没有了来自两个领域的压力，%s开始重生了。"
D.Strings[34712]="古加尔的英明领导加上我们的精诚团结，我们一定能将敌人粉碎！"
D.Strings[34713]="|cFFFF2222发射鱼叉！|r"
D.Strings[34714]="我们该怎样做？"
D.Strings[34715]="我们正在为夺回回音群岛做准备。扎拉赞恩一直在施展他的黑暗魔法，操纵傀儡，进行古老的黑暗仪式。$B$B他知道我们的行动，所以我们必须做好万全的准备。"
D.Strings[34716]="如果要成功地夺回这些岛屿，我们就需要有援军的帮助。$B$B岑塔布拉一直在照看这片群岛上的动物们。我们需要她和那些动物的帮助。$B$B邦桑迪是一位强大的神灵。他控制着这片群岛上死者们的灵魂。他的祝福对我们是至关重要的。$B$B当我们取得他们的援助之后，扎拉赞恩和被他控制的巨魔将必败无疑！那时，回音群岛就会回到暗矛部族的怀抱！"
D.Strings[34717]="%s被鲜肉的气味弄得心烦意乱。"
D.Strings[34718]="站着别动！罗姆欧格要打碎你的脑袋！"
D.Strings[34719]="显然是这些人对我们的船只发动了突袭，可我没看见任何失踪者。他们被带到哪儿去了？"
D.Strings[34720]="酒吧斗殴！"
D.Strings[34721]="感谢你帮助我们作战。"
D.Strings[34722]="我们的祖先，如果没有你们的帮助，我们仍然会畏惧扎拉赞恩。"
D.Strings[34723]="愿死去的英灵继续护佑你。"
D.Strings[34724]="感谢你们的指引，伟大的英灵。"
D.Strings[34725]="邦桑迪，请指引那些战死的勇士们。"
D.Strings[34726]="这只是一份可怜的奉献，但它代表了我对您的谢意。"
D.Strings[34727]="啊，你离开了你的藏身洞？女士很快就会取你性命的。"
D.Strings[34728]="要是有谁能严肃对待我的工作，我会感激不尽。虽然我干的不是像和鲨鱼摔跤或是把鳗鱼打结那样的活儿，可不代表这就不重要。"
D.Strings[34729]="住手！大块头保安来了！"
D.Strings[34730]="%s发怒了，跑吧！"
D.Strings[34731]="<上古半神的眼睛巨大而深邃。>$B$B<它说话的速度很慢。你也听不懂它所说的语言。寒意爬上了你的脊骨，恐惧和困惑占据了你的心灵。>"
D.Strings[34732]="<上古半神缓缓地张开眼睛，那双眼睛如同充满痛苦与畏惧的深潭。>"
D.Strings[34733]="嘿，快进来乘乘凉。$B$B我帮你弄点儿喝的吧？反正我在这儿也没其它事情可做。"
D.Strings[34734]="好！"
D.Strings[34735]="坚定不移！"
D.Strings[34736]="战场牌子兑换荣誉值。"
D.Strings[34737]="破坏"
D.Strings[34738]="不——不！这个是我们的……"
D.Strings[34739]="主人的掌控没那么容易被脱离……"
D.Strings[34740]="可怜的……一袋……肉！"
D.Strings[34741]="凡人！你越界了。"
D.Strings[34742]="主人不会容忍这种冒犯！"
D.Strings[34743]="<上古半神巨大的黑眼睛盯着你，眼睛里流露出不信任的神情。>"
D.Strings[34744]="要是你问我的话，我认为我的兄弟应该解决这些地精！据说他们当中有人用足球炸弹引发了大灾变！$B$B我们得尽快除掉他们，再晚就来不及了！"
D.Strings[34745]="金吉，能再给我一个赛艇平台潜水头盔吗？"
D.Strings[34746]="喔好的，我这儿还有几百万个没人要呢。"
D.Strings[34747]="看见我的赛艇了吗？我找不到它了！"
D.Strings[34748]="当然，$g小伙子:小姑娘;！"
D.Strings[34749]="要不是因为那些侏儒，我们怎么会陷入这种混乱！$B$B众所周知，他们才是大灾变的罪魁祸首！引起灾难的就是他们那些能放大世界的装置和诸如此类的破烂！"
D.Strings[34750]="我已经尽力让这艘船不至于散架，我能做的就这么多，而且我还得腾出精力去对付像菲兹尔那样自吹自擂的小丑！"
D.Strings[34751]="我告诉你，这家伙快要把我逼疯了！难道真有人相信，地精能帮忙完成像这座赛艇驳船平台一样的宏伟之作？$B$B他们唯一的本事就是炸东西，而且多半炸飞的是自己！"
D.Strings[34752]="怪物！怪物来抢我们的金子了！"
D.Strings[34753]="我们这是在哪儿着陆了，怎么会有这么恶心的怪物？！"
D.Strings[34754]="啊！啊！！"
D.Strings[34755]="杀了那只蠢猪！让它的血溅出来！"
D.Strings[34756]="保护那个智者！保护肉脸！"
D.Strings[34757]="你永远别想活捉我！"
D.Strings[34758]="你必须待在暗语峡谷和它附近的地方！"
D.Strings[34759]="你在偏离过往事件。快调头。"
D.Strings[34760]="文书已经准备好，就等你签字了，马林。我的人正等着你做个决定。"
D.Strings[34761]="天哪，诺格弗格先生，我知道你不希望和部落建立更为紧密的联系，怕因此损害你作为中立贸易实体的声誉！"
D.Strings[34762]="这太可笑了。你知道和侏儒做生意是什么感觉。"
D.Strings[34763]="噢，噢，我知道这个！这可比和那些失败的地精做生意要好多了，他们总是要乞求别人的帮助！"
D.Strings[34764]="你这被辐射的小矮子为什么要……"
D.Strings[34765]="啊！够了！你们两个都快把我逼疯了！赶快让这些怪诞的东西结束吧，或者把这东西扔到我的镇子外面去！"
D.Strings[34766]="住手，你这小偷！"
D.Strings[34767]="啊，$n！一只小鸟告诉我，你会来这里。$B$B这是艾维娜传递信息的方式。"
D.Strings[34768]="到处都是烟尘。就算热不死我，我也会窒息而死。"
D.Strings[34769]="你将失败，你的身躯将会破碎！让我的诅咒落在你的身上。这是注定的命运！"
D.Strings[34770]="我欠你的永远还不清，$n。也许，能还清？$B$B嗯？"
D.Strings[34771]="听着，$n，我不喜欢亏欠任何人。所以你能不能低调处理这件事，保守我们俩之间的秘密？$B$B我可不想让我的债主知道。"
D.Strings[34772]="拖车管理员从厕所里逃了出来，对着赛艇平台疯狂地做手势。"
D.Strings[34773]="拉格菲兹从厕所里逃了出来，对着赛艇平台疯狂地做手势。"
D.Strings[34774]="跌进深渊吧，怪物！"
D.Strings[34775]="嗯？怎么了？"
D.Strings[34776]="头领，有个小子正在外面惹麻烦。"
D.Strings[34777]="坚持住，$r！"
D.Strings[34778]="按下拍打键来扇动你的两翼！"
D.Strings[34779]="第一波："
D.Strings[34780]="准备竞技吧，秃鹰诱饵！"
D.Strings[34781]="把那些炮弹装上，你这可怜虫！"
D.Strings[34782]="要是你们这群蠢货敢停下来抓鼻子，我就把你们抓鼻子的手给砍下来！"
D.Strings[34783]="动起来！动起来！"
D.Strings[34784]="你们这群鼠辈管那叫炮战技术？真让我恶心！"
D.Strings[34785]="你们这群笨蛋做点儿有意义的事吧！保持开火！"
D.Strings[34786]="格斯……你得……给我找个侏儒医疗人员……"
D.Strings[34787]="切尔西，孩子，你在说胡话！你一定是神志不清了！再坚持一下……"
D.Strings[34788]="好了，诺格弗格先生！你不用再担心那些巨人了！"
D.Strings[34789]="这可真让我如释重负啊。谢谢你，孩子。"
D.Strings[34790]="嗤！真业余。"
D.Strings[34791]="看到了吗，马林？我们保护了你，宝贝儿。毫不费力。"
D.Strings[34792]="我必须承认我喜欢我所见到的这一切，碎纸机夫人。"
D.Strings[34793]="天哪，梅格斯小姐，也许下一次你能真的做点儿什么！"
D.Strings[34794]="那现在是南海海盗的财产了，旱鸭子！"
D.Strings[34795]="别想冲破我们的封锁线！"
D.Strings[34796]="南海海盗是这片海岸的主人！"
D.Strings[34797]="谢谢你，$r。$b$b是你把我从死亡线上拉了回来。"
D.Strings[34798]="你有看清那个东西到底有多大吗！？"
D.Strings[34799]="我欠你个人情，$c。$b$b我以为我死定了。"
D.Strings[34800]="我们要怎么才能从这儿离开？"
D.Strings[34801]="就算我的死期已到，我也要死得轰轰烈烈！"
D.Strings[34802]="纳迦早晚会找到这儿来。$b$b到时候我们靠什么对付？"
D.Strings[34803]="船长总算挺住了。他会想办法把我们从这混乱中救出去。"
D.Strings[34804]="哇啊——！"
D.Strings[34805]="肉！肉！哈哈哈哈哈！"
D.Strings[34806]="好多鲜血！"
D.Strings[34807]="我是巨人！"
D.Strings[34808]="我们必须找到德利兹要的部分。剩下的归我们！"
D.Strings[34809]="那红色的东西连在……那弯弯曲曲的东西上……那弯弯曲曲的东西连在我的……腕带上……"
D.Strings[34810]="多么令人兴奋！"
D.Strings[34811]="在月神殿底层有两名德莱尼正在和埃莉萨·杜马斯——就是那位操纵魔法传送门的人类法师谈话。$B$B他们会知道该如何帮助你。"
D.Strings[34812]="让纳迦过来吧！我正想打一仗哪！"
D.Strings[34813]="感谢你，至少我们现在有了战斗的机会。"
D.Strings[34814]="我也许会倒下，但我也会多拖些怪物给我垫背！"
D.Strings[34815]="复仇时间到！"
D.Strings[34816]="干得好，$c。$b$b现在我和我的人已经准备好面对敌人了。"
D.Strings[34817]="纳迦必须为他们在这里的所作所为付出代价！"
D.Strings[34818]="救命！我被困在这棵树里了！我需要帮助！"
D.Strings[34819]="谢谢你的帮助！我已经濒临崩溃了……这里发生了可怕的事情。"
D.Strings[34820]="我们相信圣殿是坚不可摧的，但我们没想到会遭受这样的攻击。"
D.Strings[34821]="黑龙人凭空出现，在我们反应过来之前就发动了攻击。"
D.Strings[34822]="我们全面溃败。同胞们一个个死去。只有我撤退到这里，并封住了入口。"
D.Strings[34823]="他们冷酷无情地屠杀我们，但他们真正的目标似乎是圣殿里的那些卵。"
D.Strings[34824]="指挥他们的是一个名叫萨瑞瑟里安的残忍家伙。但我担心他背后还有更强大的力量。"
D.Strings[34825]="刚受到攻击时，我看见了他们真正的首领，一头恐怖的暮光巨龙。"
D.Strings[34826]="我还不知道他们的全盘计划，但我知道，英雄们，绝不能让他们得逞！"
D.Strings[34827]="我看见你离开那艘船了，弱者！很快我们就会把你们全都干掉！"
D.Strings[34828]="船长！是纳迦！他们跟着$n到船上来了！"
D.Strings[34829]="|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s开始对|cFF006EFD无面腐蚀者|r施放|cFF006EFD|Hspell:75809|h[梦魇之盾]|h|r！"
D.Strings[34830]="弱者！很快你们就将臣服于我的女士！"
D.Strings[34831]="来吧，受苦吧……进入，混沌！"
D.Strings[34832]="%s开始施展|cFFFF0000湮灭术！|r"
D.Strings[34833]="你的力量在减弱，老家伙……准备下去见你的朋友吧。"
D.Strings[34834]="死吧，怪兽！"
D.Strings[34835]="我们很快就会再见……"
D.Strings[34836]="我们被发现了……动作快$n，没时间了！"
D.Strings[34837]="你暗地里总嫌我不够苗条。"
D.Strings[34838]="我把你大部分的钱都花在按摩上了，天晓得你为什么总是做不好！"
D.Strings[34839]="你总是一无是处。我真开心总算找到了一个真正的男人来满足我的购物欲。"
D.Strings[34840]="你得帮帮我！我可怜的，可怜的切尔希……"
D.Strings[34841]="就连我遇到的船上服务生都比你有男人气概。真没想到我居然在你身上耽误那么多时间……"
D.Strings[34842]="你在我背后跟他说我是个胖子，对吗？"
D.Strings[34843]="你不过是在嫉妒我找到了一个有本事又有身家的男人。"
D.Strings[34844]="你永远都取代不了我。奇普永远不会堕落到与一个比蠢猪更蠢的家伙约会！"
D.Strings[34845]="你怎么能就那样出去？什么，你刚刚在某处沙滩上洗过了？！"
D.Strings[34846]="战斗吧，弟兄们！"
D.Strings[34847]="这鞭子可不是为凡人的双手准备的！"
D.Strings[34848]="为了暴风城！"
D.Strings[34849]="好了，这应该行得通。"
D.Strings[34850]="切尔西，孩子，请喝下这个。这会让你好受些。"
D.Strings[34851]="嗯？好吧……"
D.Strings[34852]="这是什么？吃上去感觉……我现在得躺一会儿。"
D.Strings[34853]="切尔希，孩子，快起来！我得到它了！它一定能治愈你！"
D.Strings[34854]="呃，格斯，我可不喝，我从这儿都能闻到味道了。让我把食物中毒的效果给睡过去，行吗？"
D.Strings[34855]="……食物有毒？等等，你说的是这些蜥蜴肉？所有这些？"
D.Strings[34856]="没什么，宝贝儿。我只是很高兴你一切都好……"
D.Strings[34857]="呸！不用说。这是当然了，那些东西完全没煮熟……你认为是什么使我中毒的？"
D.Strings[34858]="增援前方！我们遭到了入侵！"
D.Strings[34859]="好吧，现在我出汗了。暮光之锤竟然会到这里来保护我！"
D.Strings[34860]="掩护后方！阿莱克丝塔萨的爪牙正在杀死我们的士兵！"
D.Strings[34861]="经过三思——达加可能还是需要帮助！集合！"
D.Strings[34862]="你会灭火并阻止那些海盗上船的，对吧？"
D.Strings[34863]="让我上船，格里兹纳克。"
D.Strings[34864]="喔天哪！喔神哪！你会扑灭火焰，并阻止那些海盗登上赛艇平台，是吧？！！"
D.Strings[34865]="让我上船，玛兹尔。"
D.Strings[34866]="已经很接近了，$n。"
D.Strings[34867]="嗨你好啊！欢迎来到菲兹尔与普兹克赛艇平台。$B$B天底下跑的深渊里游的，我们这里无所不有！"
D.Strings[34868]="海盗、半人马、恐怖图腾，我的天！$B$B而且我想我昨晚还看到一个庞然大物从头顶上飞了过去。它可真是太大了，大得把月亮都遮住了！"
D.Strings[34869]="别担心——有我在。"
D.Strings[34870]="$n，一定要时刻保持谨慎！"
D.Strings[34871]="欢迎来到菲兹尔与普兹克赛艇平台。你能在这里找到所有你想要的东西。"
D.Strings[34872]="没事了$n——你现在安全了。"
D.Strings[34873]="在这里遇到你真是恰逢其时啊，$n！"
D.Strings[34874]="我们在这儿可能会遇到各种各样的麻烦，但至少我们已经进入开放水域了。$B$B虽然我们不一定能逃过昨晚从我头顶飞过的那大家伙。那玩意儿可真大……我是说，真的很大！"
D.Strings[34875]="献给那些在冰封荒原上为了对抗天灾军团而英勇牺牲的战士们。"
D.Strings[34876]="必定要铲除巫妖王。"
D.Strings[34877]="我在施放闪电链！！啾啾……"
D.Strings[34878]="坚守阵地，战士们！他们来了！"
D.Strings[34879]="他们人数太多了！萨满，快做点儿什么！"
D.Strings[34880]="抓紧时间休息吧，弟兄们。那可不是最后一波……"
D.Strings[34881]="你好啊，$c！$B$B这些可怜的小家伙正在这黑暗的地方竭尽全力对抗暮光之锤的爪牙！$B$B我已经尽力让那些倒下的死而复生。$B$B要是你需要另一只坐骑，这些鸟已经准备好再次展翅翱翔。好好对待它们！"
D.Strings[34882]="第二波："
D.Strings[34883]="卵摇晃着："
D.Strings[34884]="摧毁火焰之地龙卵！"
D.Strings[34885]="你一而再再而三地碍我的事，侏儒。"
D.Strings[34886]="你也已经彻底耗尽了我的耐心。"
D.Strings[34887]="这城镇无法同时容下我们两个人！"
D.Strings[34888]="我会尽量让自己不因彻底摧毁你而感到过度狂喜。"
D.Strings[34889]="来啊，小矮子！"
D.Strings[34890]="就是这样。听好了！这场冲突已经被我们用暴力引入了正轨！让我们看看敌人会有怎样的反应吧！"
D.Strings[34891]="我跟你还没完呢！"
D.Strings[34892]="好吧！算你赢了！我是狡猾，可不是疯子……"
D.Strings[34893]="大家坚持住！"
D.Strings[34894]="保持警觉！别让他们把你给拖走了！"
D.Strings[34895]="呃……不……"
D.Strings[34896]="什么鬼……真恶心！"
D.Strings[34897]="喔拜托。看来我经历得还不够多。"
D.Strings[34898]="我不想毫不领情，可那真是必要的吗？"
D.Strings[34899]="洗衣桶，对吧？当然。"
D.Strings[34900]="谢谢……我想。"
D.Strings[34901]="我想要知道这东西是从哪儿来的？"
D.Strings[34902]="一条鱼？给我的？真是可爱。"
D.Strings[34903]="远离那些鱼人会让我的心里多那么一点儿安全感。谢谢你。"
D.Strings[34904]="你一定要告诉加里维克斯，不要再低估诺莫瑞根了。"
D.Strings[34905]="下次再见，梅格斯。别忘了今天这一课。"
D.Strings[34906]="快打开！我有消息带给你！"
D.Strings[34907]="嘿！古加尔说你有消息给我！"
D.Strings[34908]="嘿！放我进来，不然“那个谁”会听到的！"
D.Strings[34909]="不！啊……"
D.Strings[34910]="一只饥饿的海洋锤头鲨嗅到了你的蛤蚌的气味。"
D.Strings[34911]="我的人——他们都被带走了……快逃！自己保重！"
D.Strings[34912]="这个很健康！夫人一定会非常高兴……"
D.Strings[34913]="你在今后的日子里都要效忠夫人！"
D.Strings[34914]="谁也别想逃！"
D.Strings[34915]="来吧，软皮肤的。还有很多工作要做呢！"
D.Strings[34916]="你们将任由夫人差遣……"
D.Strings[34917]="不听话就得死，弱者！"
D.Strings[34918]="你无处可躲，凡人！"
D.Strings[34919]="她会找到你……"
D.Strings[34920]="让他们付出代价！"
D.Strings[34921]="不要放弃！为联盟而战！"
D.Strings[34922]="他们的人数……无穷无尽……"
D.Strings[34923]="你会成为一个好劳工的。"
D.Strings[34924]="我的女士一定会对我的努力大加赞赏。"
D.Strings[34925]="你是否听话，就决定着你的死期是迟到还是早来。"
D.Strings[34926]="我们是得以逃脱的幸运儿，$n。跟着我。"
D.Strings[34927]="*咯咯*……找不到有用的东西！这些虫子*咯咯咯*根本不能吃*咯咯咯*要狠砸这个侏儒，如果他还要*咯咯咯咯咯咯*"
D.Strings[34928]="明白，猎手。我们正在移动！重复，我们正在移动！"
D.Strings[34929]="现在你所有的地精伙伴都再次迎来了安全与快乐的生活，也不会再有海盗想要炸碎你们的船！"
D.Strings[34930]="喔天哪，我太荣幸了！我愿意！你稍等一下，现在……"
D.Strings[34931]="所有单位等待部署。执行代号德尔塔方案。不计人员伤亡。"
D.Strings[34932]="我从没见过想那样的侏儒大清洗，孩子。我可以派你这样的人去解决所有那些剩下的海盗，永久性的。"
D.Strings[34933]="喔不，你不会的。我比你要快两步，小不点儿。让我们瞧瞧谁能先把落帆海湾夷为平地。"
D.Strings[34934]="那只受惊的小熊崽不肯离开那棵树！"
D.Strings[34935]="愚蠢的戈隆，你要么服从我们，要么……要么……你最好识相点！"
D.Strings[34936]="我快要受够你了！别逼我把铸炉之主索朗格斯请来！"
D.Strings[34937]="不管你愿不愿意，你都得把那源质移开！"
D.Strings[34938]="待在那儿别动，否则你也要加入你的朋友们！"
D.Strings[34939]="只会哭鼻子的懦夫们！地狱咆哮的部落大军将让你们所有的兄弟姐妹都面对同样的命运！"
D.Strings[34940]="可怜的小东西们！桑德拉克不会对你们施以丝毫怜悯！"
D.Strings[34941]="把垃圾和粪便扔到后面，让这些侏儒们有东西玩儿！"
D.Strings[34942]="闭上你那喋喋不休的臭嘴，否则我就把你送去喂狼！"
D.Strings[34943]="请——请——请别伤害我们，痛苦主宰大——大人！"
D.Strings[34944]="让心情平静。让自己沉浸在火焰中。"
D.Strings[34945]="小心，朋友。炎魔之王有结界保护，让我们无法对他发动攻击。"
D.Strings[34946]="我已经准备好开始对抗拉格纳罗斯的战斗了。"
D.Strings[34947]="嗨你好啊，$g帅哥:美女;。欢迎光临赛艇平台酒吧。$B$B想来点儿什么？"
D.Strings[34948]="你们这儿有些什么饮品？"
D.Strings[34949]="你好，$c。希望你能有宾至如归的感觉，即使是在这战火之中。"
D.Strings[34950]="$n，请在那些海盗摧毁赛艇平台前阻止他们！"
D.Strings[34951]="我会解决那些海盗。不过首先，得先来几杯壮壮胆。"
D.Strings[34952]="等哈缪尔和玛法里奥一到，我们就开始……"
D.Strings[34953]="我们准备好了，塞纳留斯。"
D.Strings[34954]="我们要直面炎魔之王，并将他的余烬残渣赶出我们的领地！"
D.Strings[34955]="通过按下“离开载具”按钮来快速返回赛艇平台。"
D.Strings[34956]="我会召唤冰冷的山风来保护我们，抵挡拉格纳罗斯的烈焰。玛法里奥和哈缪尔会打碎炎魔之王的防护，助我们击退他。"
D.Strings[34957]="让我们开始吧。炎魔之王用不了多久就会觉察到我们的存在，并前来防御这座尖塔。"
D.Strings[34958]="谁敢玷污烈焰之灵的大厅?我将烧尽你们的血肉与灵魂！"
D.Strings[34959]="快点，所有人赶紧就位！把他赶回火焰之地！"
D.Strings[34960]="送我去走私者洞穴。"
D.Strings[34961]="送我去银潮谷。"
D.Strings[34962]="|TInterface\\Icons\\ability_dualwield.blp:20|t%s装备好|cFFFF0000剑|r并获得了|cFFFF0000|Hspell:74981|h[双持利刃]|h|r!"
D.Strings[34963]="|TInterface\\Icons\\inv_shield_76.blp:20|t%s装备好|cFFFF0000盾牌|r并使用了|cFFFF0000|Hspell:74908|h[盾墙]|h|r!"
D.Strings[34964]="如果不返回千针石林，你将失去你的赛艇。"
D.Strings[34965]="我们在此对抗的势力远远不止暮光之锤、拉格纳罗斯甚至是死亡之翼。我们惟有取胜才能确保我们的世界不至于消亡。"
D.Strings[34966]="海加尔沦陷了！放弃吧！"
D.Strings[34967]="没有牢笼能够关住我，白痴！"
D.Strings[34968]="腐蚀已经泛滥了！你不可能成功！"
D.Strings[34969]="我担忧奥利瑟拉的命运。范达尔的腐蚀穿透的比任何噩梦都深。我们也没有太多时间去思考这个问题。"
D.Strings[34970]="在梦境中，我有了一个重大的发现。那道削弱世界边际的裂隙如今加快了强大盟友的归来。"
D.Strings[34971]="上古的守护者正在归来。塞纳留斯、艾维娜、戈德林……我能感受到他们的气息。我们必须确保他们能顺利回归。他们的及时援助将是不可或缺的。"
D.Strings[34972]="初步分析显示……我不能再继续了。"
D.Strings[34973]="你的表现很好，孩子。可这里现在是地精的地盘了。我建议你努力去适应。"
D.Strings[34974]="再见了，宝贝儿。要是你想要找个时间共进午餐，记得告诉我一声。既然你已经学会了一些礼节，我们会想出办法来的。"
D.Strings[34975]="你被艾萨尔监控器发现了！"
D.Strings[34976]="艾萨尔监控器发出了求援信号！"
D.Strings[34977]="它想要杀了我们？想要知道我们的秘密……"
D.Strings[34978]="我们必须消灭它。"
D.Strings[34979]="我们烧了它，烧了它！火大点儿，就这样！"
D.Strings[34980]="风啊，悄悄地，悄悄地……吹它，吹它，将它吹飞！"
D.Strings[34981]="我们……粉碎它！必须……粉碎。快点儿朋友们！"
D.Strings[34982]="不能让它知道……不能让它了解……我们的……"
D.Strings[34983]="我们的胜算不大，但我们不能退缩，$n。在敌人的大军和诺达希尔之间就只剩下我们这一道屏障。"
D.Strings[34984]="我……我快要没气了……我必须调头！"
D.Strings[34985]="请进来，$r。我必须报答你的恩情。"
D.Strings[34986]="拜托了，$r。$b$b我不知道自己还能在这儿撑多久……"
D.Strings[34987]="跟我来！我带你去走私者洞穴。"
D.Strings[34988]="准备，瞄准……开火！"
D.Strings[34989]="维兹，你这白痴！要是你能管住你的嘴，一切就都不会出问题！"
D.Strings[34990]="快来人把我从这笼子里放出去！！！"
D.Strings[34991]="只要我一出去，我就立刻把你掐死，维兹尔！"
D.Strings[34992]="我在这儿本来好好的。我正准备把一堆步枪卖给那些海盗，发笔小财！可是，不！维兹尾随而来，想要让他们买下他那些廉价的工程学零件。结果却把他们的几座火炮和我的步枪都给炸毁了！我们势不两立！"
D.Strings[34993]="喔，谢谢你！"
D.Strings[34994]="谁在那儿？放我出去！趁这些臭死人的海盗还没决定把我蘸上口水做成绿色的火腿炒蛋，快放我出去！"
D.Strings[34995]="请允许我代表锈水财阀，向第一个把我从这笼子里放出去的人赠予慷慨奖励！当然，还是要遵守标准合同条款的规定，但不用在意那些细枝末节。只要你能快点儿放我出去！"
D.Strings[34996]="嘿，你是海盗吗？！快点儿过来，别再到处瞎闹了。把我从这儿放出去，我会给你们大家好多把全新的步枪——只要让我从赛艇平台把这些步枪拿出来！"
D.Strings[34997]="有没有人能对那些火炮做点儿什么？我在这儿没办法好好思考了！"
D.Strings[34998]="赛恩格，没想到你居然让我们陷入这样的混乱，你这个愚蠢的地精！"
D.Strings[34999]="%s开始召唤某种火焰之地的怪物。"
D.Strings[35000]="喔我的天哪！喔我的天哪！快来人放我出去！我有幽闭恐惧症……幽闭……幽闭……呃，反正就是怕被关在笼子里！"
D.Strings[35001]="%s开始召唤天空之墙的怪物。"
D.Strings[35002]="%s开始召唤深岩之洲核心的怪物。"
D.Strings[35003]="喂，你，快过来！拜托了，拜托了，拜托了，快把我从这笼子里放出去！"
D.Strings[35004]="我正在列出可以用超适应性变形射线把你变成哪些样子，赛恩格！我希望你最后能变成毫无用处的蠢货，来搭配你悲剧的人生。"
D.Strings[35005]="海盗朋友们，听好了。我跟这个叫赛恩格的家伙不是一伙的。我向你们保证，要是你们能把我从这笼子里放出去，你们会发现我是你们所遇到的最顶级的工程师。我是说——真的，你们见识过你们火炮的精准性吧？非常接近目标，可还是差了好——远！"
D.Strings[35006]="谁愿意把一个无辜的侏儒从笼子里放出去？快点儿动手吧。这样的机会可不常有！"
D.Strings[35007]="赛恩格，我要打扁你，然后再打扁你！等着瞧吧。我要从这笼子里出去，然后幸灾乐祸地嘲笑你！"
D.Strings[35008]="嗯，海盗们，我的失踪一定正让我的兄弟们忧心不已。也许你能放我出去？里兹尔经常喝醉酒，而菲兹尔有血压高的毛病！"
D.Strings[35009]="好啊！"
D.Strings[35010]="魔法是个工具，有些人甚至会把它当作馈赠。可你永远不应该忘记它的本性。"
D.Strings[35011]="奥术魔法扭曲了我们世界的边界。它弱化了这个空间的自然定律，使原本不可能发生的事情变为了可能——就算只是在片刻。"
D.Strings[35012]="恶魔只需要那片刻的时间就能造成浩劫。燃烧军团已经盯了我们上千年，总是想伺机抓住最小的裂隙趁虚而入，利用最小的骚动制造混乱。"
D.Strings[35013]="记住这一点，年轻人。你所施放的每一个法术，不管威力多么不值一提，都会产生两方面的影响。这也正是严禁随意使用法术的原因。"
D.Strings[35014]="暮光之锤对我来说不仅仅是个组织。它就像是我的家。$B$B所以，我严加小心以确保不会有人滥竽充数地通过训练。"
D.Strings[35015]="我得尽快找个安全的地方。$b$b老马克的情况不太好。"
D.Strings[35016]="到西边那个洞穴去。那里安全又干燥。"
D.Strings[35017]="我受不了了，伙计！我在这儿快要发疯了！"
D.Strings[35018]="发生什么事了？！我们必须马上行动！我说马上！"
D.Strings[35019]="我们是在浪费时间，教授！兽人在屠杀我们！"
D.Strings[35020]="我可没主动报名来蹚这浑水！我本该回去帮梅卡托克夺回诺莫瑞根！"
D.Strings[35021]="你太过担心了，诺莫巴士。冷静下来！"
D.Strings[35022]="这太荒唐了！我们疯了才会去！"
D.Strings[35023]="那些暗夜精灵被你搞得很紧张，诺莫巴士！"
D.Strings[35024]="坚持，兄弟们！我们还有事情没干完！"
D.Strings[35025]="我们需要你的帮助，$n。帮我们阻止那些凶残的部落！"
D.Strings[35026]="你在这里只能找到痛苦，$r！"
D.Strings[35027]="谢谢你，朋友。我们欠你个人情。"
D.Strings[35028]="坚持住，马克……"
D.Strings[35029]="我以为我肯定要被落下了。谢谢你回来找我！"
D.Strings[35030]="谢谢你，陌生人！我们自由了！"
D.Strings[35031]="万岁！万岁！"
D.Strings[35032]="呀嘿！我们得救了！"
D.Strings[35033]="你可真是个大救星啊，$c。"
D.Strings[35034]="我欠你个人情。很大的人情。"
D.Strings[35035]="我不会忘记这件事。谢谢你。"
D.Strings[35036]="我会给我的长子起名叫$n。"
D.Strings[35037]="你今天已经救过我多少次了？我都数不过来了。"
D.Strings[35038]="不丢下任何一个人，嗯？你可真是个了不起的$r。"
D.Strings[35039]="我可真想亲你一下。可是算了，还是不要让你被我的口气熏死。"
D.Strings[35040]="%s一碰到水，就发出了狂暴的嚎叫！"
D.Strings[35041]="我会抓住你的，凡人！还有你那群小狼崽子！"
D.Strings[35042]="它……在燃烧！"
D.Strings[35043]="这<停顿>还没结束呢，凡人……"
D.Strings[35044]="怎样？这是什么招数？"
D.Strings[35045]="水！在这儿？！"
D.Strings[35046]="你把我惹火了，凡人！"
D.Strings[35047]="面对我，虫子！我将亲手碾碎你们！"
D.Strings[35048]="凡人，你们今日的失败昭示了旧世界的终结。我的子嗣将会引领烈焰统治的新纪元！"
D.Strings[35049]="我这儿需要一个监工，现在就要！"
D.Strings[35050]="看看这掷刀车。兽人的荣耀……哈哈！"
D.Strings[35051]="监工！告诉我你看到了什么。"
D.Strings[35052]="错！跟我来。"
D.Strings[35053]="击败正在攻击%s的火元素！"
D.Strings[35054]="一台……掷刀车，长官。"
D.Strings[35055]="亵渎！你们脆弱的血肉玷污了我的工作。"
D.Strings[35056]="%s倒下了！"
D.Strings[35057]="%s恢复过来，重新加入战斗！"
D.Strings[35058]="索恩克正在塔顶等着你，$c。"
D.Strings[35059]="这些刀刃在你看来够锋利吗？锋利吗，监工？"
D.Strings[35060]="协助我，孩子们！"
D.Strings[35061]="烧尽他们的血肉筋骨！"
D.Strings[35062]="你不过是在拖延时间，塞纳留斯。我的军团将在火焰之地重生……"
D.Strings[35063]="你们这些兽人知不知道自己究竟在做什么？"
D.Strings[35064]="钓鱼竿……你们钓鱼的样子就像海象人。甚至更糟，简直像人类。"
D.Strings[35065]="让老兽人教教你应该怎样做！"
D.Strings[35066]="兽人们，记住自己的荣耀。我们要让地狱咆哮为我们感到自豪。"
D.Strings[35067]="这地方看上去很不错，兽人们。继续努力。"
D.Strings[35068]="喂，我有没有告诉过你，我在格瑞姆巴托的战斗中差点儿被矮人杀死的事？"
D.Strings[35069]="他想要偷偷溜到我背后，把刀刃插进我的脑壳里。可幸运的是，我在一里外就能闻到矮人的气味……而且我的脑壳比普通人要厚得多。"
D.Strings[35070]="当然，在那时候，我头上还有好多头发做保护。"
D.Strings[35071]="我去那里转了一圈，拿回了他的剑，他的头，还有他的坐骑。"
D.Strings[35072]="你们这些兽人曾经梦想过战争吗？"
D.Strings[35073]="简直是渴望，长官。"
D.Strings[35074]="哈哈！很好！也许我会把你们的名字推荐给加尔鲁什。现在快去干活儿！Lok'tar ogar！"
D.Strings[35075]="监工！这儿发生什么事了？"
D.Strings[35076]="被烈焰吞没吧！"
D.Strings[35077]="在烈焰之流中燃烧！"
D.Strings[35078]="上次我来的时候，你的头衔是监工，可不是暴食者。"
D.Strings[35079]="我已经经过这里两次了，两次都看到你坐在火堆边上，在手下干活的时候无所事事。"
D.Strings[35080]="长官，我……我的兽人们干得很好，所以我只是……认为我……"
D.Strings[35081]="我看到绷带像武器一样堆在一边。我看到食物就这么暴晒在太阳底下，尽管我显然已经为你们提供了用于遮阳的帐篷。"
D.Strings[35082]="谁是这些人的监工？"
D.Strings[35083]="我……我是，长官。"
D.Strings[35084]="那就让我们确保让它保持原状。回去工作吧，监工。"
D.Strings[35085]="戈尔、希恩，你们真不该一天到晚待在这间小屋里。赶快出去和那些兽人一起干活！"
D.Strings[35086]="的确，萨满，我并不真的很在意你在做什么。我甚至不明白地狱咆哮为什么要把你带到这里来。"
D.Strings[35087]="戈尔，当你感觉自己不再年轻时，为什么不和我到外边来，开始管制那些兽人一次呢？"
D.Strings[35088]="农夫，到外面来。我们必须谈一谈。"
D.Strings[35089]="这些猪，它们太虚弱了。既不适合用来繁育，也不适合拿来食用，上战场当然更不行。"
D.Strings[35090]="你的繁育要更具选择性一些。部落容不下弱者，即使是在猪圈里。"
D.Strings[35091]="好吧。这样的事情我不想再做第二次。那是你的工作，猪倌。"
D.Strings[35092]="射得漂亮！狙击炮可真是个神奇的玩意儿！"
D.Strings[35093]="击败拉格纳罗斯之子，我才能协助塞纳留斯！"
D.Strings[35094]="我正受到攻击！帮我！"
D.Strings[35095]="%s正在遭受拉格纳罗斯的攻击。快治疗他！"
D.Strings[35096]="拉格纳罗斯的攻击削弱了我的战斗力……快治疗我！"
D.Strings[35097]="这是你们玷污海加尔圣山的代价。"
D.Strings[35098]="你对狂怒一无所知，虫子！"
D.Strings[35099]="弱小的$R！死吧！"
D.Strings[35100]="感受拉格纳罗斯的愤怒吧！"
D.Strings[35101]="这热浪。这令人窒息的热浪。$B$B令我想要靠破坏来发泄。"
D.Strings[35102]="我来了！别以为躲在那些树后面就没事了！"
D.Strings[35103]="从传送门那边又有人过来了！希望你已经做好了战斗的准备，$c。"
D.Strings[35104]="我们现在已经深入敌后了，$n。我们要尽可能地对敌人制造伤害！"
D.Strings[35105]="要是我们任由暮光之锤在艾泽拉斯各地打开像这样的传送门，那这世上就没有任何军团能挽救这个星球。我们必须一举解决这个坑道网！"
D.Strings[35106]="我们必须坚持，$n。我从我们敬爱的狼神先祖身上学到了一样东西。$B$B那就是永远、永远、永远都不要放弃。"
D.Strings[35107]="派伦迪乌斯倒下了！我们在这儿的工作完成了。$B$B现在只要穿过火焰之门就能返回海加尔山了，$c。我会确保看好大门的。"
D.Strings[35108]="我把洛戈什之牙弄丢了。可以再给我一个吗？"
D.Strings[35109]="我把戈德林之牙弄丢了。可以再给我一个吗？"
D.Strings[35110]="你很快就会知道，闪电与水是无法融合的！"
D.Strings[35111]="再见。"
D.Strings[35112]="向我们仁慈的统治者与保护者——埃利斯塔拉·瓦丝琪主母致敬。$B$B一百年来，她诚心地庇护着我们，保护着我们，坚定地引领我们走入了繁荣的现代新纪元。$B$B在艾萨拉女王的注视下，愿她的统治能再延续百年。"
D.Strings[35113]="什么懦夫竟敢在我不在时攻击我的孩子？我要把你的内脏挖出来喂它们吃！"
D.Strings[35114]="这耗尽了我们集结起来的所有力量，不过我们终于把拉格纳罗斯赶回了火焰之地。"
D.Strings[35115]="呜呼！"
D.Strings[35116]="我们绝不能有丝毫的松懈。他迟早会重获力量并且卷土重来，将诺达希尔变成焦土。"
D.Strings[35117]="我们必须与联盟和部落的领袖谈一谈。一定要在拉格纳罗斯的老巢将其击败。那样，才能将他彻底征服。"
D.Strings[35118]="让我们先离开这里吧。我们必须返回海加尔去抚平敌人造成的创伤。"
D.Strings[35119]="怪物，你再也不能污染海加尔之风了！"
D.Strings[35120]="主人泰拉尔将让你见证奇迹！"
D.Strings[35121]="我们都是他的一部分……"
D.Strings[35122]="为了泰拉尔！"
D.Strings[35123]="女猎手，那边！那是什么？！"
D.Strings[35124]="是……是那边那个吗，$n？要是部落成功把它点着了，这座岛屿就将彻底毁灭。"
D.Strings[35125]="那是什么，攻城坦克急救工具？你一定认识驾驶员迪恩·石轮！"
D.Strings[35126]="*砰* 不是这东西！继续前进！"
D.Strings[35127]="*噼啪声*错误！正确的地精钻孔机正在路上！"
D.Strings[35128]="艾维娜的魔法还未褪去，现在就杀了她！"
D.Strings[35129]="出来吧，畜牲！不管你藏在哪儿，我们都会把你和你那些堕落的余孽一起铲除掉！"
D.Strings[35130]="别想拿走矿石！"
D.Strings[35131]="%s现在很虚弱，可以捕捉了！"
D.Strings[35132]="哇——！快跑啊！"
D.Strings[35133]="为了安全起见……我要留下这个宝珠。快去把这档子邪教徒的麻烦事告诉奥哈恩。"
D.Strings[35134]="是谁？有人在那儿吗？"
D.Strings[35135]="动起来！这块石头太重了！"
D.Strings[35136]="什么都看不见了！别挡路！"
D.Strings[35137]="为什么我非要搬大石头？他们说新酋长继任后工作量会减少的！他们保证会有所变化的！"
D.Strings[35138]="也许我该放下这块石头说声你好。也许。"
D.Strings[35139]="瞎子摸黑一样地走在黑漆漆的矿井里，手里还抱着大石头。真比上一份工作好多了。"
D.Strings[35140]="快走，不然我就去告诉监工，说你在桶里拉屎！"
D.Strings[35141]="困啊……真是困死了……"
D.Strings[35142]="好的大人，我这就回去敲树。"
D.Strings[35143]="只是歇歇眼睛！马上就回去干活！"
D.Strings[35144]="嘘！轻点儿！你要害我们被发现了。"
D.Strings[35145]="感谢你花时间帮我们测试《魔兽世界》之《大地的裂变》资料片内容。\n\n你想去哪里？"
D.Strings[35146]="带我去奥格瑞玛，我希望经过瓦丝琪尔平台。"
D.Strings[35147]="带我去暴风城港口，我希望去瓦丝琪尔平台。"
D.Strings[35148]="带我去海加尔，我希望帮德鲁伊捍卫诺达希尔。"
D.Strings[35149]="我想直接前往瓦丝琪尔平台。"
D.Strings[35150]="我们在此为你演示你变身成为狼人的影像！我们同时还将镜头快速前移到当前！"
D.Strings[35151]="抢劫犯！死吧！"
D.Strings[35152]="你别想阻止我们！部落永远不会被打败！"
D.Strings[35153]="首领一定会为你的脑袋出个好价钱的！"
D.Strings[35154]="滚开！滚开！"
D.Strings[35155]="***故障***"
D.Strings[35156]="***电源变更***"
D.Strings[35157]="***远程访问激活***"
D.Strings[35158]="***返回命令初始化***"
D.Strings[35159]="***逐出全部未经许可的通行者***"
D.Strings[35160]="<尽管伊瑟拉的肉身就站在你面前，可她的意识却仿佛在两个世界间游移。>"
D.Strings[35161]="你最近去过灰谷吗？那里情况怎么样？"
D.Strings[35162]="是的，同胞！我们为真正的暮光之子带走这名囚犯！这些食人魔渣滓不配拿他来献祭！他们不够资格获得上古之神的眷顾！"
D.Strings[35163]="快点，指挥官。我们要把你带出去。$n，我们在索萨恩之门碰头——伊瑟拉正在那儿等着。"
D.Strings[35164]="%s开始施放超级新星。转过头去！"
D.Strings[35165]="我们四周仍然危机重重。我不能毫无戒备地离开这座营地。"
D.Strings[35166]="我已经尽全力去保护那些坚持走到这里的人。"
D.Strings[35167]="我已经派出所有可以调遣的战士。要是我能再为你派出哪怕一个人……"
D.Strings[35168]="让我们自己在两边都不设戒备，将会带来更大的灾难，加恩。"
D.Strings[35169]="我们必须让守卫留在这里以保护难民。"
D.Strings[35170]="恐怖图腾也潜伏在菲拉斯。他们在等待时机，对眼前这座营地发起攻击。"
D.Strings[35171]="嗯，好多财宝。"
D.Strings[35172]="%s受到了防御信标的保护！快拉下面的操纵杆，让防御信标停下！"
D.Strings[35173]="想要跟将军打架？财宝可真多啊。算我一个！"
D.Strings[35174]="不想找麻烦。只想要钱。"
D.Strings[35175]="好多金币啊！我扭过头去。"
D.Strings[35176]="双牙从来不给我财宝！"
D.Strings[35177]="我藏好宝贝。继续休息。"
D.Strings[35178]="好多金灿灿的宝贝。也许你比将军更让我喜欢。"
D.Strings[35179]="对愚蠢的$r来说，你还算不错。"
D.Strings[35180]="醒醒，水泡先生！"
D.Strings[35181]="所有好女孩都听爸爸的话！"
D.Strings[35182]="喔不！钥匙断在锁眼里了！我永远也别想离开这笼子了！"
D.Strings[35183]="你在吗，水泡先生？"
D.Strings[35184]="快醒醒，水泡先生！快救救那些灵魂！"
D.Strings[35185]="莱恩为名，买卖随性！你想来点儿什么？"
D.Strings[35186]="让我看看你有些什么，莱恩。"
D.Strings[35187]="我们猛禽德鲁伊并不适于前线作战。我们是空中侦察兵，是渗透者……$B$B不过我偶尔也不介意让我的爪子沾上血污。"
D.Strings[35188]="在这下面小心点儿，$c。这些雪怪都是残暴的战士。"
D.Strings[35189]="萨兰恩队长希望你放置好观察机器人以后撤退至卡拉诺斯。"
D.Strings[35190]="白痴！蠢货！看看你们无头苍蝇般的样子，对即将到来的末日浑然不觉！"
D.Strings[35191]="请允许我问一个简单的问题：一个男人是否有资格靠自己的血汗为生？"
D.Strings[35192]="我这辈子看够这个洞穴了。我恨不得立即返回卡拉诺斯。"
D.Strings[35193]="“不”——奥格瑞玛的兽人说道，“它属于部落！”"
D.Strings[35194]="“不”——暴风城的人类说道，“它属于联盟！”"
D.Strings[35195]="我曾结识过一个摒弃这些答案的人！一个为那些令他感同身受的人建造家园的伟人！一个选择不可能的人！"
D.Strings[35196]="那个人就是吉恩·格雷迈恩，而那个“不可能”的选择就是吉尔尼斯！"
D.Strings[35197]="这些雪怪当然是个麻烦，可真正的战斗却是对付那些霜鬃难民。"
D.Strings[35198]="靠……近点……$c。他们……在把我拉远……"
D.Strings[35199]="有%s出现在圆环上方，模糊不清。"
D.Strings[35200]="艾露恩在注视着你，$n。"
D.Strings[35201]="你的仁慈将被永远铭记！"
D.Strings[35202]="我将永远心怀感激，$n！"
D.Strings[35203]="诅咒该死的部落！要不是有你在，我早就死了！"
D.Strings[35204]="你们自以为很聪明，是不是，像这样联手对付我……好吧，准备面对——恐怖伐木机！"
D.Strings[35205]="快点……"
D.Strings[35206]="呃……我原本打算光明正大的与你公平交手，可你却带来了帮手。好吧！来面对合金锤击者零式吧！"
D.Strings[35207]="%s俯视着你，发出一阵震耳发聩的嚎叫！"
D.Strings[35208]="告诉萨兰恩队长，等我确定那机器人能正常工作，我就立刻返回卡拉诺斯。"
D.Strings[35209]="我已经迫不及待想要离开这里，去帮助对付那些巨魔了。"
D.Strings[35210]="姐妹！我……也……失——败了……"
D.Strings[35211]="自从大灾变发生以来，我们就日以继夜地战斗。能歇一歇真是太好了，哪怕只是稍作休息。"
D.Strings[35212]="干得好，$n！回到风剪要塞把部落的意图告知指挥官法罗米尔。我会冒险前往萨达拉瞭望台，通知我们的士兵们。"
D.Strings[35213]="啊！别打脸！"
D.Strings[35214]="哇——！"
D.Strings[35215]="现在你们统统去死吧！"
D.Strings[35216]="我在花园里就能听到你的三叉戟折断的声音！那些克瓦迪尔的脑袋就跟岩石一样硬。"
D.Strings[35217]="一把叉子可不能阻止我再杀掉成百上千的敌人。"
D.Strings[35218]="首先最重要的是，我是个商人。让我复活，我就停止对你的侵扰。你甚至还可能因此得到奖赏。"
D.Strings[35219]="当然，毋庸置疑。"
D.Strings[35220]="要知道，如果你在这整件事情上能通情达理一些，我也许就直接把钥匙卖给你了。倒不是说它会给你带来什么好处。但却能打破那把锁。木哈哈哈哈哈！"
D.Strings[35221]="很抱歉让你去和我妻子打交道，老兄。她很疯狂，但我仍然爱她，你知道吗？"
D.Strings[35222]="做鬼的感觉也还不算糟。我能在这儿看到许多商机。不少鬼魂都在等待合适机会的到来。"
D.Strings[35223]="要知道，对赛艇平台的攻击只是场商业误会。等你把我复活之后，我会考虑与菲兹尔与普兹克洽谈一份合约。"
D.Strings[35224]="你有吃的吗？我很饿！"
D.Strings[35225]="你不喜欢我到处跟着你吗？这可太糟了！也许下一次当你想要为了一把钥匙杀人时，你会三思！"
D.Strings[35226]="天气怎么样？我说不好……总之这里到处都是灰蒙蒙阴沉沉的，天上还有翻卷的云。"
D.Strings[35227]="阿加蒙姐妹那整件事真是个天大的误会。我没做过，我发誓！我想也许是老海盗法哈多。那小子看起来有点儿像他。"
D.Strings[35228]="噢，老兄，我死的时候身上长了个疮，直到现在都没消失。你可别跟我说，我得永远带着它？！你一定要把我复活！！！"
D.Strings[35229]="他们说我是个臭名昭著的海盗，可你不会看到我为了点儿钱就四处航行滥杀无辜。喔，等一下……"
D.Strings[35230]="阿加蒙再一次使用了她的娘家姓。不管怎样，我会想念她的。你明白吗？"
D.Strings[35231]="你知道为什么女人总是一无是处吗？因为你认为她们唯一会做的事就是招魂。可是然后，你发现她们并不只是会在那儿说话！我是说，那对鬼魂怎么会行得通？"
D.Strings[35232]="只要我一还魂，我就要杀了你，伙计！呃……不，我的意思是说，我就要拥抱你。对，没错，我就要抱住你，再给你一份大大的犒赏。别把我说的什么杀了你的话当回事。"
D.Strings[35233]="啊，库拉萨。我相信一切都会顺利的。"
D.Strings[35234]="我没有用多长时间，就几乎是凭空创造出一个海盗帝国。啊，贫瘠之地。不过这都是过去的事了。嘿，有没有人知道曼科里克的妻子到底出了什么事？"
D.Strings[35235]="我的组织正需要像你这样的帮手。要知道，我们是南海海盗独立运营的特许分支。我们向成员提供优厚的待遇、假期、全身检查、牙医和视力保健服务。也许我们应该等到你把我复活之后再谈。"
D.Strings[35236]="神兽加兹瑞拉——为上古之神所钟爱的灵宠，正在一天天地变得更大更强……暮光之锤教派也是如此。"
D.Strings[35237]="继续你在这里的工作吧，水占师。这个世界很快就会被重塑……"
D.Strings[35238]="……只要效忠我们的主人，你和沙怒部落就能得到应有的奖赏！"
D.Strings[35239]="入侵者！杀光他们！"
D.Strings[35240]="你以为你们都能勇敢面对我，是吗，钢烁？！那些猪尾巴阻挡不了魔锯的力量！"
D.Strings[35241]="小心，$n！督军罗克托克就在附近。他随时都会出现！"
D.Strings[35242]="很快，加兹瑞拉就能通过增宽的裂隙一举摧毁异教徒的城市了。她会把它们都碾成冰冷的碎石！"
D.Strings[35243]="督军在哪儿？我要杀了他，把你放出来！"
D.Strings[35244]="瓦丝琪女士和她的母亲完全不同。毕竟她在很久以前就离开了这座城市。"
D.Strings[35245]="石爪山这里总是困难重重，$n，但这片土地和生活在这里的人民从没像现在这么痛苦过。如果不加以制止的话，部落会把我们全都毁掉。"
D.Strings[35246]="喔，我最亲爱的吉尔尼斯，我是多么的想念你……"
D.Strings[35247]="龙啊，来帮助我！"
D.Strings[35248]="嗷！好烫！！"
D.Strings[35249]="哎呦！哎呦呦……！"
D.Strings[35250]="疼！"
D.Strings[35251]="就是它了。远古之神一定会站在我们这边。"
D.Strings[35252]="把其余的带去火焰之地孵化场！很快我们就将控制天穹。"
D.Strings[35253]="天空万灵之母，聆听我的祈祷，为你自己显现……一幕景象！这会是什么意思呢，$n？我要报告给欧穆隆。"
D.Strings[35254]="让我们看看你口袋里那些炸药喜不喜欢KS-L10钢烁，梅格斯！"
D.Strings[35255]="呀！好疼！"
D.Strings[35256]="你一定要救救我，$c！他已经疯了……疯了知道吗！由于他不能改变千针石林被洪水吞没的事实，他已经彻底精神失常了！$B$B他把一切都怪罪到我头上，包括大灾变。他可能认为我是死亡之翼或什么东西假扮的！$B$B救命！"
D.Strings[35257]="我听说你出售灰色小鸡？"
D.Strings[35258]="抓到你了小家伙！你最好开口，别逼我动手。"
D.Strings[35259]="我不知道那是不是真有必要。"
D.Strings[35260]="你从我这里什么都别想得到，$r！"
D.Strings[35261]="<玛瑞恩一边大声喘叫一边瞪着你。>"
D.Strings[35262]="你们的城市将会陷落，$r。你们将消亡在新政权的黑暗之中！"
D.Strings[35263]="想做什么尽管去做。我的新主人将会在他们处死你之前，把我的名字刻进你的血肉里。"
D.Strings[35264]="<说服她。>"
D.Strings[35265]="攻击他们，兄弟们！"
D.Strings[35266]="杀掉女人！我会亲自对付那些“战士”。"
D.Strings[35267]="攻击女海巫——打断他们的法术！"
D.Strings[35268]="碾碎这些毒蛇！"
D.Strings[35269]="战士们，进攻！"
D.Strings[35270]="站着别动你这没用的小鸡！"
D.Strings[35271]="要不是因为你总是在咯咯咯的叫，我就能挡住海水！"
D.Strings[35272]="我要拔光你的毛，强森！"
D.Strings[35273]="这次是什么，火焰还是冰霜？嗯？"
D.Strings[35274]="等等，我要扮演好警察的角色？"
D.Strings[35275]="我们不必让欧穆隆知道这件事。"
D.Strings[35276]="别急，朋友。我们还需要更多信息。"
D.Strings[35277]="嘿，别浪费时间。"
D.Strings[35278]="这才刚刚开始，玛瑞恩！"
D.Strings[35279]="残忍！"
D.Strings[35280]="我知道我今天晚饭要吃什么，那东西的谐音一定是“讨厌鬼”！"
D.Strings[35281]="别抵抗了……我只是想要把你变回人形。"
D.Strings[35282]="跳舞吧，强森，跳舞吧！"
D.Strings[35283]="噢，然后我要把我的灰色小鸡拿回来，谢谢你！"
D.Strings[35284]="你能动作快点儿吗？我可没时间跟你耗！"
D.Strings[35285]="强森，你又在卖我的灰色小鸡了？不——！"
D.Strings[35286]="嘿！你怎么没现出原形？趁还没变回来抓紧享受吧，“勇敢的”强森！"
D.Strings[35287]="你要是个好点儿的帮手，大灾变这整场灾难就能避免！"
D.Strings[35288]="有人听得见那声音吗？快让它停下来！"
D.Strings[35289]="真无聊啊！"
D.Strings[35290]="强森，告诉你的朋友继续前进。你们的死期早就过了。"
D.Strings[35291]="我得给自己捞点儿提成！最好直接把你烤熟了然后独吞所有利润。"
D.Strings[35292]="你为什么要偷这些蛋？"
D.Strings[35293]="她要这些蛋。要把它们带到她在另一个王国的炽热孵化场。$B$B而其中一只蛋……很特别的一只……是她最想要的。"
D.Strings[35294]="谁？你要把这些蛋拿给谁？"
D.Strings[35295]="她是天穹之主，也是黑暗之王。她是大地守护者的子嗣。她是不可战胜的！"
D.Strings[35296]="大地守护者的子嗣……你听命于一只黑龙？告诉我名字！"
D.Strings[35297]="愚蠢的$r！新的秩序已然建立。艾维娜已经死了。死了！再也不会回来了。$B$B回去告诉树林里的那群德鲁伊。$B$B塞西莉亚很快将成为新的天穹之主，而且有她在，艾维娜再也别想重生！蛋是塞西莉亚的了！$B$B你来的太迟了。"
D.Strings[35298]="你自己决定，$n。当玛瑞恩攻击我们主人的圣殿时，就已经为自己惹上了麻烦。"
D.Strings[35299]="<任由希萨莉处置这只鹰身女妖。>"
D.Strings[35300]="万岁，钳子先生！你回来了！你还记得怎么向敌人开枪吗？为什么不花点时间重新把战斗的技艺拾起来！以防万一。"
D.Strings[35301]="<要求希萨莉释放鹰身女妖。>"
D.Strings[35302]="你是个比我更好的人，$n。可我认为这里的鹰身人只是爪牙而已。"
D.Strings[35303]="一定要多加小心，水泡先生。要是你看到一大群地精，就用你的磁力对付他们！等你把他们全都吸过来之后，就送他们上西天！吖！"
D.Strings[35304]="抓住他们，水泡先生！"
D.Strings[35305]="打碎他们的骨头，水泡先生！"
D.Strings[35306]="让他们后悔对你造成的伤害，水泡先生！"
D.Strings[35307]="让他们更痛苦！更痛苦！"
D.Strings[35308]="可恶，可恶，可恶的部落！"
D.Strings[35309]="需要什么吗？"
D.Strings[35310]="我需要修理，铁羊。"
D.Strings[35311]="谢谢你，伙计。你实现了自己的诺言，我很钦佩。"
D.Strings[35312]="我要回去了。相信我们一定会再见面。下次见面时，我一定会还你这个人情。"
D.Strings[35313]="再见，阁下。今晚再见。"
D.Strings[35314]="不，千万别，托尼。离我远点儿，我晚上还有约会呢！"
D.Strings[35315]="回艾维娜圣殿找我，$n！"
D.Strings[35316]="从下方来的！"
D.Strings[35317]="保持镇静！"
D.Strings[35318]="请回到原位上去！"
D.Strings[35319]="嗯，这可有点儿令人尴尬……"
D.Strings[35320]="你要为你的妄为付出代价，$c！"
D.Strings[35321]="时间到了，玛瑞恩。"
D.Strings[35322]="冰淇淋！"
D.Strings[35323]="我已经准备好帮助Mr. P了，孩子。让我进去。"
D.Strings[35324]="像你这样的$r在这里干什么？……尤其是在现在这样的时候？$b$b嗯？"
D.Strings[35325]="那该死的野兽被赶跑了，可我宝贵的水资源被玷污了！我必须立刻净化它。$b$b如果你坚持要继续留在这儿，就请自保吧。"
D.Strings[35326]="我们准备好了！"
D.Strings[35327]="欢迎你，$c！欢迎来到艾维娜圣殿——天空中所有生灵的避风港。$B$B艾维娜或许已经不再与我们同在，但她的心魂与她的凶猛战力却将永远留存在所有藉双翼翱翔的生灵身上。$B$B要是你想了解艾维娜的故事，可以与位于下方的楚伦娜交谈。"
D.Strings[35328]="希萨莉告诉我，鹰身人和龙结成了联盟？可有些事情却怎么都说不通。我们必须了解更多才行。$B$B请在此协助楚伦娜的工作，看看我们能否将这一切都串连起来……"
D.Strings[35329]="楚伦娜告诉了我你所看见的情景。那非常令人困惑。我们珍爱的古树将要重生吗？如果是这样，现在她在哪里？$B$B我们需要得到更多的信息！请帮助希萨莉进一步收集信息，这样我们才能采取行动。"
D.Strings[35330]="我不知道我在这儿干什么。我没有做合约谈判员的经验。$B$B我以前曾经干过酒保，可因为黛西的原因做不下去了。也许是时候转行了。"
D.Strings[35331]="楚伦娜和希萨莉都已经把他们的报告给了我。现在我已经非常清楚了……$B$B$n，我相信艾维娜应该很快就会回来了，但我们必须阻止黑龙塞西莉亚！"
D.Strings[35332]="喂——这边！暂时别出现在视线之内……"
D.Strings[35333]="我以前就是个在赛道边上谋生的奖券商。可现在没比赛，也就没钱赚了。$B$B我现在正在努力学习谈判。你能帮我让这里的一切顺利进行吗？他们有油！"
D.Strings[35334]="复活仪式已失败！"
D.Strings[35335]="克拉维尔·浓须晕了。趁现在快去把联盟投标书偷到手！"
D.Strings[35336]="这是什么意思？"
D.Strings[35337]="保护%s直到仪式结束！"
D.Strings[35338]="你在做什么？！"
D.Strings[35339]="赛道管理员泽尔林晕了。趁现在快去把部落投标书偷到手！"
D.Strings[35340]="%s遭到了攻击！赶快保护他！"
D.Strings[35341]="<奥术守护者向贫民窟的集市指了指。>"
D.Strings[35342]="我准备开始鲜血仪式了，莱诺雷。"
D.Strings[35343]="许多人把血魔法当作一门黑暗与失落的艺术，对其避之不及。从那以及许多其它方面来说，它与恶魔的法术有着某种共通的鲜明特性。在这里——在黑色沼泽恶魔肆虐的遗迹中，我们相信我们的血魔法一定能焕发光华。"
D.Strings[35344]="你能教一名士兵学会杀戮的技巧，可你不能教他杀戮的欲望。还好我们在这下面不用担心这一点。我的每一位弟兄都已经迫不及待地想要把那些纳迦撕成碎片，让他们为犯下的恶行付出代价，而我也一样。$B$B我们要想办法与上面建立联系，可在那之前，我想先跟那些纳迦“联系”一下。那些倒下的兄弟不能白死。"
D.Strings[35345]="让我看看那碎片，可以吗将军？我能感觉到它的能量正从洞穴的另一侧放射出来。"
D.Strings[35346]="你已经目睹过这景象。"
D.Strings[35347]="你需要进一步使自己与纳兹夏尔女武士谐调一致，才能分享这景象。"
D.Strings[35348]="关闭暗影遮罩之后，一只塞西莉亚的雏龙出现了！"
D.Strings[35349]="我……这是什么巫术？"
D.Strings[35350]="你会为你的行为感到后悔的！"
D.Strings[35351]="我……我失去控制了。被你的疯狂装置所束缚。"
D.Strings[35352]="我们要跟弗巴说什么？"
D.Strings[35353]="哈！桶本该是归你看管的！"
D.Strings[35354]="你在工作中喝醉了！"
D.Strings[35355]="我们？应该是你要跟弗巴说什么才对！"
D.Strings[35356]="你才是负责防范兽人的人！"
D.Strings[35357]="你也是！"
D.Strings[35358]="就是它！我们找到艾维娜的卵了！你保护它，我去找帮手。"
D.Strings[35359]="关闭暗影遮罩之后，艾维娜的卵显现了出来！"
D.Strings[35360]="保护好这只卵！"
D.Strings[35361]="请帮帮我，要是这群懒虫能有一个叫得动，我就会让他回去工作，再把其它人打得鼻青脸肿！$B$B我们在这儿有工作要做！"
D.Strings[35362]="听着，你……你知道进行地质勘察是多么困难吗？这是精确、精密的工作！$B$B而且当你喝醉时，就更是难上加难了。"
D.Strings[35363]="你可真是个大救星。"
D.Strings[35364]="是时候了。"
D.Strings[35365]="保持努力。"
D.Strings[35366]="真及时——我差点就弹尽粮绝了。"
D.Strings[35367]="他们的攻击日渐频繁了。你最好别停下。"
D.Strings[35368]="我们会掩护你的。愿攻击一切顺利！"
D.Strings[35369]="他们仍在背后支持我们，这可真是个好消息。谢谢你！"
D.Strings[35370]="谢谢你让我重获自由！"
D.Strings[35371]="罗菲利安·达恩就在矿洞深处。跟着这些踪迹走就行了。"
D.Strings[35372]="丹恩在旁边的房间里等着你。"
D.Strings[35373]="真奇怪啊。"
D.Strings[35374]="那盒子一秒钟以前在那儿吗？"
D.Strings[35375]="双子峰战斗将在1分钟内开始。"
D.Strings[35376]="双子峰战斗将在30秒内开始。做好准备！"
D.Strings[35377]="我非常确定……一个移动的盒子。工程师们这次真的做到了！"
D.Strings[35378]="返回守望堡矿井。"
D.Strings[35379]="我知道你是谁，$n！我才不会把神圣烈焰交给像你这样恶心的饭桶！"
D.Strings[35380]="这里有令人惊叹的材料。任何工程材料和替换件都能找到代用品。一切皆有可能！"
D.Strings[35381]="我已经准备好对平台发起攻击了。"
D.Strings[35382]="把他们炸烂！"
D.Strings[35383]="那盒子是在自己移动吗？还是我发疯了？赶快，去个人检查一下！"
D.Strings[35384]="这地方让我们比先前更加暴露了，$r。$b$b我们必须尽快找到安全的藏身处！"
D.Strings[35385]="我们必须集结你的同伴，探明纳迦在这里的真正目的。$b$b不过首先，我们得先找个更为安全的地方。"
D.Strings[35386]="我觉得我们对纳迦在此地出现的原因了解得远远不够。$b$b我以前从没见过他们像现在这么富于组织性和纪律性。"
D.Strings[35387]="村庄……消失。家庭消失。纳迦……带走……一切。"
D.Strings[35388]="鱼人，我知道瑟温妮的护符在你手里。我需要它。"
D.Strings[35389]="你别想拿走护符！戈洛尔永生！"
D.Strings[35390]="你听到背后传来了一声噪音。"
D.Strings[35391]="戈洛尔会杀了你！"
D.Strings[35392]="这是什么？假的！裂蹄，$n还有那群侏儒想要耍我们。给我杀了$g他:她;！"
D.Strings[35393]="这是什么？假的！裂蹄，$n还有那群地精想要耍我们。给我杀了$g他:她;！"
D.Strings[35394]="离远点儿！"
D.Strings[35395]="滚开，部落的毛贼！"
D.Strings[35396]="虫子！消灭了你们，我就会把你们的神殿烧成焦土！"
D.Strings[35397]="你们拖延了时间……但仍难逃一死……我的孵化所还在……"
D.Strings[35398]="我们来了，$n！在我们准备发动迂回攻击时，帮我们拖住她。"
D.Strings[35399]="这对我们所有人来说都很困难，可我们正在勉强支撑。$B$B你要做的就是挽起袖子，做你该做的事。"
D.Strings[35400]="裂蹄高地的半人马摧毁了钻油机！"
D.Strings[35401]="<这名士兵痛苦的呻吟声在水中变得有些扭曲。>"
D.Strings[35402]="<这名受伤的士兵似乎还有呼吸。谢天谢地，他的魔法气泡还没掉。>"
D.Strings[35403]="<这名受伤的士兵似乎还有呼吸。谢天谢地，她的魔法气泡还没掉。>"
D.Strings[35404]="<这名士兵的体侧有一道深得可怕的伤口。>"
D.Strings[35405]="<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了他的命。>"
D.Strings[35406]="<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了她的命。>"
D.Strings[35407]="见到你很高兴。"
D.Strings[35408]="我被告知弄丢坐骑就要等着受死。谢谢你证明将军是错的。"
D.Strings[35409]="见到你实在是太好了，太好了，朋友。"
D.Strings[35410]="其他人都成功了吗？进攻胜利了吗？"
D.Strings[35411]="明白。谢谢。"
D.Strings[35412]="通往会合点的路基本已经畅通无阻了。你应该动身了。"
D.Strings[35413]="你不用告诉我两遍。"
D.Strings[35414]="这“正是”我想要听到的。谢谢你。"
D.Strings[35415]="看来我又欠了你一份人情。"
D.Strings[35416]="我没问题了。谢谢你。"
D.Strings[35417]="我要走了。谢谢你。"
D.Strings[35418]="你可真是个难得一见的大好人。"
D.Strings[35419]="那可真是场漂亮的突击战。我很佩服。"
D.Strings[35420]="第三舰队被诅咒的魂灵将永世游荡在这片海岸上，$r。帕雷斯之眼掌控着我们的生命，并永远将我们囚禁在泥沼之中。"
D.Strings[35421]="恶魔！我从坟墓中回来，就是为了毁灭你！"
D.Strings[35422]="死亡并没有抹去我的记忆。我还记得你的名字……"
D.Strings[35423]="拉瑟莱克！来吧，面对死亡吧！"
D.Strings[35424]="愚蠢的恶魔猎手。这次我得把你切成多少块？"
D.Strings[35425]="这是什么？洛拉姆斯……我明白了，他们利用了风暴祭坛，是不是？"
D.Strings[35426]="那你一定已经感受到了……恶魔的能量侵入你的心肺，席卷你的灵魂……"
D.Strings[35427]="让我把进程速度加快一点！"
D.Strings[35428]="好疼！喔，我的天，好疼！"
D.Strings[35429]="冒险者们！了结我吧，不要让拉瑟莱克再控制我了！"
D.Strings[35430]="快！用那把刀杀了我！时间要来不及了！"
D.Strings[35431]="死亡的喜悦在等着你。"
D.Strings[35432]="那把石匕！快用！我就快控制不了他了……"
D.Strings[35433]="回到我这里来！"
D.Strings[35434]="结束了。把我留在这儿吧，我会和拉瑟莱克在地狱里继续交战。你们的任务已经完成了，英雄们。"
D.Strings[35435]="感谢圣光！我得救了！"
D.Strings[35436]="那……那些刺客死了吗？"
D.Strings[35437]="究竟是怎么回事？"
D.Strings[35438]="一只能走路的盒子？我应该问问宏多这件事……嗯，也许再等一段时间吧。"
D.Strings[35439]="喔我的天。"
D.Strings[35440]="回去工作！喔等等……你只是个盒子，不要紧。"
D.Strings[35441]="嘘，小声点儿！我们正躲着呢。"
D.Strings[35442]="奥克莉拉不喜欢让我们这些非兽人进入镇子，但那并不妨碍她安排我们去工作。不管怎样……我倒宁可待在这外面。"
D.Strings[35443]="你们这群兽人可真幸运……战争主母让你们待在巨槌要塞，而我们剩下这些人却要在外边干活。不过不要紧……从某种意义上说，我倒是宁可待在外面也不愿意待在她的屋檐下。"
D.Strings[35444]="你已进入兽人的地盘。你需要什么吗，$r？"
D.Strings[35445]="欢迎你，$g兄弟:姐妹;。"
D.Strings[35446]="让我们开始吧！为成功祈祷吧，$n！"
D.Strings[35447]="呀嘿！我们成功了！我们再也不会受到部落的威胁了！"
D.Strings[35448]="嘿，$n，到这儿来，好吗？我有些任务要交给你。"
D.Strings[35449]="$n，请到这儿来。"
D.Strings[35450]="洪水并没那么可怕。至少没我们在铁炉堡里经历的那一切可怕。"
D.Strings[35451]="小心你的嘴巴，你这个醉鬼！那是无心之过！"
D.Strings[35452]="你的意思是，这是你造成的？"
D.Strings[35453]="你从里面给管道装上了闸门，把自己困住了！"
D.Strings[35454]="然后你就会从这条隧道一直冲进饭厅！"
D.Strings[35455]="我们已经喋喋不休地吵了几个星期了！"
D.Strings[35456]="这是一个无心之过！"
D.Strings[35457]="嗯，至少麦酒是安全的。"
D.Strings[35458]="这可真是个悲剧啊，兄弟们。米奈希尔的诅咒落在了我们每个人的身上。"
D.Strings[35459]="哈，她干得可真漂亮！但和将军还没法比。"
D.Strings[35460]="我们尽可能地守在这里，可还是不够。"
D.Strings[35461]="没人能像他那样守住一个地方，小子们。没人能做到。"
D.Strings[35462]="船长，处女号已经许多年没有航行过了。它就被安放在那里。"
D.Strings[35463]="我们明白，头儿。我们明白。"
D.Strings[35464]="我们到了，$n。他还活着吗？"
D.Strings[35465]="好强的风啊。"
D.Strings[35466]="这应该能让他暖和起来！"
D.Strings[35467]="戈洛尔！！"
D.Strings[35468]="你——你都干了什么？"
D.Strings[35469]="你竟敢召唤天空之墙的领主，$n？我要杀了你，然后把你的尸体扔回到你爬行而出的烂泥坑里！"
D.Strings[35470]="我明白了……这是我必须选择的道路。回到洞里找我，英雄们。"
D.Strings[35471]="我的天哪！"
D.Strings[35472]="真是太可怕了！"
D.Strings[35473]="嘿！滚出我的矿洞！"
D.Strings[35474]="小心！有个$r入侵者！"
D.Strings[35475]="退后，不然我就把你献给死神！"
D.Strings[35476]="什么？你是怎么进来的？"
D.Strings[35477]="上帝！你能看看那个吗？"
D.Strings[35478]="赞美上帝！"
D.Strings[35479]="嘿！那个长腿儿的盒子是谁的，它跑了！"
D.Strings[35480]="我觉得我待在这矿井里太久了。"
D.Strings[35481]="小心！那是个盒子魔鬼！"
D.Strings[35482]="看来这是给某人的特别快递包裹。"
D.Strings[35483]="我需要你按我说的去做，$r。如果我们退却，我们就很可能落入拉瑟莱克的股掌之中。"
D.Strings[35484]="我们正在对付的，看来要比大地之环预料到的任何东西都要大得多。"
D.Strings[35485]="在这个洞穴之外集结了大批纳迦。$b$b我们能神不知鬼不觉地到达这个地方，可真是幸运。"
D.Strings[35486]="我们的士兵……他们都已沦为俘虏。"
D.Strings[35487]="我不知道原因，但那些怪物在想方设法让我们的人活下来……"
D.Strings[35488]="好！拿去护符，可$r要帮助岩池鱼人。"
D.Strings[35489]="我们生活在同一片海浪中，吞吐着同一片海水，膜拜着同一位神灵。那究竟是为什么——纳迦要与我们反目为敌？"
D.Strings[35490]="帕雷斯之眼早在很久之前就已被夺回和净化，$c。我们以为诅咒早已被消除。"
D.Strings[35491]="不到一年前，大副菲兹莫斯那个可怜的老家伙去世了，是酒毁了他的身体。"
D.Strings[35492]="从那以后，时常会有人声称听到他跟他们说话，让他们去把眼睛拿来……"
D.Strings[35493]="被诅咒者只能永远在这里徘徊……就连可怜的菲兹莫斯也无法逃脱。"
D.Strings[35494]="别问我你究竟给我带来了什么，$c。你最好忘记这件事曾经发生过。"
D.Strings[35495]="地狱咆哮的军队正在朝我们袭来，兄弟姐妹们！"
D.Strings[35496]="继续作战！听从玛加萨的号令！"
D.Strings[35497]="不要丧失信心！我们还没一无所有！还没！"
D.Strings[35498]="我见到了未来，兄弟姐妹们，但却没有看到部落的踪影！"
D.Strings[35499]="我们会胜利的！不要懦弱！"
D.Strings[35500]="进攻！不惜一切代价！攻陷恐怖图腾！"
D.Strings[35501]="戈德林是狼神先祖，在部落语中又被称作“洛戈什”。他有着传奇般的坚韧战力。$B$B为纪念他而建造的圣殿就位于世界之树西边的盆地那里，但它的看守人在那次攻击之后就变得杳无声息。我担心最坏的事情已经发生了。$B$B在我们继续前进之前，你必须确保圣殿安全无虞，查明狼神先祖的下落，击退他的敌人。"
D.Strings[35502]="艾森娜是自然之魂，也是我在这个世界和梦境中永恒的同伴。她位于海加尔西部的圣殿，就在暮光入侵的最前线，此刻应该已被战火席卷。$B$B$n，如果没有艾森娜的帮助，我们永远都别想重建海加尔山。确保她的圣殿免受大火的侵袭，并救救附近那些被烈焰威胁的生灵吧。要是我们做不到，就将失去这整座山。"
D.Strings[35503]="艾维娜是天穹的失落卫士，一万年前在与恶魔大军的对抗中不幸消亡的鸟之女神。为纪念她而建造的圣殿就在西南边，在一棵参天大树的虬枝之中。$B$B猛禽德鲁伊把那圣殿作为他们的大本营，而我们需要他们的支援。你必须前去帮助他们。同时也帮助艾维娜，愿她能找到回归这世界的通途……"
D.Strings[35504]="我已经派大德鲁伊哈缪尔·符文图腾前往被烧得面目全非的玛洛恩庇护所。他在前线的后方——被称作烈焰之痕的焦枯之地。他正在寻找让我们挽回损失的办法，并调查龟神托尔托拉的下落。$B$B但在你前去帮他之前，你必须先确保西边艾森娜神殿的安全，还要保护那里的生灵免受烈焰的侵袭。否则我们将失去一切！先集中精力解决艾森娜林地的问题，然后他们会在适当的时候送你去大德鲁伊那里。"
D.Strings[35505]="告诉我关于戈德林圣殿的事。"
D.Strings[35506]="艾森娜林地发生什么事了？"
D.Strings[35507]="我该怎样帮助艾维娜圣殿？"
D.Strings[35508]="我能在玛洛恩庇护所做些什么吗？"
D.Strings[35509]="我已经想尽办法让这些矮人勤快起来，就差把他们暴打一顿了。$B$B你难道有更严苛的招数？"
D.Strings[35510]="扫清矿井！不留活口！"
D.Strings[35511]="干掉最多敌人的杀手，将被邀请与领主同桌共餐！"
D.Strings[35512]="兄弟们，地狱咆哮之眼在注视着你们！"
D.Strings[35513]="卡兹莫丹必将粉碎！一切都将以他的名义陷入毁灭！"
D.Strings[35514]="你无法阻止……末日……"
D.Strings[35515]="离开……这里……"
D.Strings[35516]="也许这里并不怎么舒适宜人，可这里仍旧是卡兹莫丹，所以它还是我们的家。"
D.Strings[35517]="我们的城镇沉没在被诅咒的洋底，我们的要塞已被黑铁叛徒侵占，而我也身受重伤，对这种局面束手无策。$B$B所以欢迎来到米奈希尔港！"
D.Strings[35518]="退后，$n！当“曲奇”烹饪时，场面可是相当疯狂！"
D.Strings[35519]="现在该把它搅拌在一起，加上我的秘制香料！"
D.Strings[35520]="烈焰将会吞噬你！会把我们所有人都吞噬殆尽！"
D.Strings[35521]="荣光献给……拉格纳罗斯……"
D.Strings[35522]="嗯，嗯！闻上去可真香啊，“曲奇”！谁能抵抗如此美味的诱惑？$n快把这份肥美的大餐送到恐怖图腾大使那里去！"
D.Strings[35523]="返回赤色海岸。"
D.Strings[35524]="伊瑟拉派我来这里与艾森娜的荒野灵魂取得联系。$B$B可这古老的灵魂仍在保持沉默。"
D.Strings[35525]="不是我们将战火引向部落，而是部落将战火引向我们。"
D.Strings[35526]="格鲁迪格就在附近。看那儿。"
D.Strings[35527]="部落派来了刺客！把他们全都干掉！"
D.Strings[35528]="真是强大的武器！"
D.Strings[35529]="部落将在我面前战栗！"
D.Strings[35530]="让部落尝尝联盟钢刃的味道！"
D.Strings[35531]="部落决不会获胜！"
D.Strings[35532]="部落将军的箱子掉在了地上。"
D.Strings[35533]="兄弟们，沃塔倒下了！"
D.Strings[35534]="我不会落得与沃拉琼相同的结局！死吧！"
D.Strings[35535]="面对玛格汉的愤怒吧！"
D.Strings[35536]="正当我以为我们终于能摆脱那些迅猛龙，喘口气时，这里的情况却变得更糟。$B$B可是抱怨是没用的。我们得像个真正的矮人一样去面对！"
D.Strings[35537]="别提那些迅猛龙。提也别提。"
D.Strings[35538]="欢迎来到远离家乡的家园，$c。希望我们能为您献上无比殷勤的款待。"
D.Strings[35539]="在谷地里要多加小心，$n。四周到处都是敌人！"
D.Strings[35540]="让我看看你出售的货物，莱纳斯。"
D.Strings[35541]="想要做买卖吗？"
D.Strings[35542]="请让我看看你出售的货物。"
D.Strings[35543]="东西都弄坏了，嗯？"
D.Strings[35544]="大胖，我要在我背包里找找。"
D.Strings[35545]="<这些小鱼人似乎是被遗弃在这里了。>"
D.Strings[35546]="<这些小岩池鱼人似乎是被遗弃在这里了。现在他们的境遇肯定很糟糕。耐普托一定想让你将他们带回到大海去。他们在那里才有可能躲避开纳迦的捕猎。>"
D.Strings[35547]="<帮助岩池鱼人蝌蚪。>"
D.Strings[35548]="<让他们自己保护自己吧。>"
D.Strings[35549]="列兵霍金纳多·伯纳德，暴风城步兵团第十三编队……$g阁下:女士;。"
D.Strings[35550]="你是怎么下来的？"
D.Strings[35551]="我们发现了他们……部落的船队……然后突然就不见了，有触手伸出来一把抓住了我们的船……把它折成了两截！$b$b幸存者们……我们一落水就立刻被纳迦抓住。$b$b那是差不多一星期以前的事了。"
D.Strings[35552]="关于那些抓你们的人，有什么能告诉我的吗？"
D.Strings[35553]="真是奇怪……从没想过纳迦竟然会设法让我们活下来。$b$b他们弄出这些像珍珠一样的泡泡……一人一个……让我们能够呼吸。$b$b他们每天都会送走一些囚犯……不知道去往哪里。$b$b再也没见过他们……"
D.Strings[35554]="你是怎么逃脱的呢，伯纳德？"
D.Strings[35555]="哈哈哈！我与恐怖图腾同在！你们这些傻瓜全都要死！"
D.Strings[35556]="另一名士兵设法获得了自由，打碎了我们的珍珠……释放了我们。$b$b有人游向了水面……有人看到这座洞穴，并向它游来。$b$b我是唯一一个活下来的……"
D.Strings[35557]="啊！$r！后退！"
D.Strings[35558]="你有没有见到泰勒上尉和他的部下？"
D.Strings[35559]="说不好……$b$b他们每天都会带来新的士兵。部落和联盟的都有。$b$b有些在来的当天就会被拖走……其它像我一样的，会在那儿待上一个星期……也许更久。"
D.Strings[35560]="有没有什么弱点可供我们利用？纳迦的防御是否有什么漏洞？"
D.Strings[35561]="试都别试，$r。$b$b趁还来得及，赶快离开这儿……$b$b有太多人都将……必死无疑……"
D.Strings[35562]="鲜血仪式已经完成……而且我现在能看到洛拉姆斯·萨里比迪斯正在何处等待着你。"
D.Strings[35563]="很好。退后……别弄得你满身都是。"
D.Strings[35564]="你早晚都要开口！"
D.Strings[35565]="希望你喜欢痛苦。"
D.Strings[35566]="你们的人准备什么时候发动反攻？告诉我，我就终结你的痛苦。"
D.Strings[35567]="无关私人恩怨。我们只是对那种被驱逐出家园的日子感到有些厌倦。现在轮到我们反击了。"
D.Strings[35568]="快把一切都说出来，你这没用的蠢牛！"
D.Strings[35569]="既然我们已经占领了乱风岗，现在就只剩下那艘愚蠢的驳船。侏儒与地精。你们这些人是多么的可怜。"
D.Strings[35570]="我已经对你的抵抗感到厌倦了。我现在就要杀了你，然后去撬开你其它同伴的嘴巴。"
D.Strings[35571]="我没时间和你耗！不说就去死吧！"
D.Strings[35572]="我准备开始护符仪式了，莱诺雷。"
D.Strings[35573]="以拉瑟莱克护符内的强大力量……"
D.Strings[35574]="……我将你缚于他的巢穴中！"
D.Strings[35575]="城市已被攻陷。艾萨尔向你发出了胜利的恭贺。你今天为自己赢得了足够的尊重。"
D.Strings[35576]="我没想到能这么快地夺取这座城市。看来我们将有大把时间来准备入侵。"
D.Strings[35577]="召唤咒语已经就绪，可我们是依靠纳萨林坩埚来汲取法术能量。必须找回这件圣物。"
D.Strings[35578]="马迪亚斯·肖尔亲自派我来协助暗夜精灵。"
D.Strings[35579]="你是谁，$c，要背负如此重担？"
D.Strings[35580]="动物的庇护者……屠龙者……远古之灵的勇士……"
D.Strings[35581]="我最亲爱的老友诺尔度赠予了你一件伟大的礼物，$r。生命的礼物。"
D.Strings[35582]="而我会给予你一个更加伟大的责任。"
D.Strings[35583]="由你之手，这座圣山将再次繁茂。守卫它，便是你的责任。"
D.Strings[35584]="定要使它兴盛。驱逐意欲危害它的敌人，以我之名。"
D.Strings[35585]="不会有第二次机会了，$r。"
D.Strings[35586]="$n!你做到了！我无法相信自己的眼睛……烈火消失了……艾森娜做了什么？"
D.Strings[35587]="愿艾露恩帮助我们。"
D.Strings[35588]="我们会有怎样的遭遇？石爪又会有怎样的遭遇？"
D.Strings[35589]="加尔鲁什·地狱咆哮，我诅咒你出生的那一天。"
D.Strings[35590]="我们在毁灭的边缘摇摆。难道就没人能帮帮我们吗？"
D.Strings[35591]="卡利姆多未来的情势相当严峻。"
D.Strings[35592]="拉兹，损伤如何？"
D.Strings[35593]="大灾变在丹莫罗引起了混乱。穴居人以我们前所未见的规模成群结队地迁移到地表，把我们的宿敌霜鬃巨魔赶到了离我们居住地更近的地方。$B$B铁炉堡已经派出我的巡山小队来协助解决这一问题。"
D.Strings[35594]="从过往的灰烬中生出新的生命……这是艾森娜的馈赠。$B$B如果没有你，这奇迹决不会出现。"
D.Strings[35595]="<这个上古生物盯着你。那双眼睛比你的头还要大。望着它们就好象坠入了一片深蓝的海洋。>"
D.Strings[35596]="我能在这儿休息吗？"
D.Strings[35597]="你这儿有什么补给品吗？"
D.Strings[35598]="等我们完成之后，那些霜鬃巨魔会把我们看作是比穴居人更可怕的对手。他们只能离开，别无选择。"
D.Strings[35599]="哇——我这是在哪儿？你是和他们一伙的吗？"
D.Strings[35600]="都结束了没有？"
D.Strings[35601]="必须……回到……铁木那里！"
D.Strings[35602]="你不是暮光之锤的人。外面发生什么事了？"
D.Strings[35603]="我烧伤了。非常严重。"
D.Strings[35604]="暮光之锤……我听见他们尖叫窜逃……我们是在发动反攻吗？"
D.Strings[35605]="城镇……被毁了！我们无法阻止他们。"
D.Strings[35606]="他们打开了通往火焰之地的传送门……告诉我希望还在！"
D.Strings[35607]="振作起来，士兵。远古半神与我们同在，群山得到了治愈！"
D.Strings[35608]="我们还身陷这场争斗？我得报告给铁木！"
D.Strings[35609]="谢谢你，$c！继续作战！"
D.Strings[35610]="情势逆转了？我得回去作战！"
D.Strings[35611]="我……我想我一定能回到铁木那里。我们会成功的！"
D.Strings[35612]="你先出发，我会到铁木的营地那里与你回合。谢谢你！"
D.Strings[35613]="暮光之锤的人跑了？我得回到前线上去！"
D.Strings[35614]="我的武器就在附近——我们可以去和铁木会合。"
D.Strings[35615]="你们那不起眼的小胜利根本算不了什么。暮光之锤的力量是无可匹敌的！"
D.Strings[35616]="巴尔加拉斯？！还有其他人……你们全都死了！这到底是什么邪恶的伎俩？"
D.Strings[35617]="返回萨达拉瞭望台、战痕谷、石爪峰或萨达拉树林，否则你的角鹰兽会把你丢下去！"
D.Strings[35618]="这地方快要爆炸了！快跑！"
D.Strings[35619]="快到我角鹰兽背上来。我们没多少时间！"
D.Strings[35620]="抓住我的手，年轻人。"
D.Strings[35621]="萨达拉大师派我来营救你。快上来！"
D.Strings[35622]="没人能来帮帮我们吗？"
D.Strings[35623]="到处都是兽人！"
D.Strings[35624]="萨达拉大师人呢？"
D.Strings[35625]="我永远不会忘记你的善举。"
D.Strings[35626]="总有一天，我会报答你。"
D.Strings[35627]="达纳苏斯的所有人都会知道你为我们所做的。"
D.Strings[35628]="我们能飞得更高一些吗？"
D.Strings[35629]="你真是位英雄。"
D.Strings[35630]="谢谢你。你救了我一命。"
D.Strings[35631]="我们的世界需要更多像你这样的英雄。"
D.Strings[35632]="愿艾露恩护佑你。"
D.Strings[35633]="我会派我的祭司来帮助你。尽快找到神器，这样我才能开始召唤援军，来应对即将到来的战争。"
D.Strings[35634]="我的精英良将会任你调遣，别担心，女武士。尽快回来找我们——我已经迫不及待想要开始追击猎潮者了。"
D.Strings[35635]="你会有援军的，女武士。我已经打算集结克瓦迪尔人去奈瑟匹拉工作了，所以你的时机刚刚好。"
D.Strings[35636]="我正要去找纳萨林坩埚。你有战士能助我一臂之力吗？"
D.Strings[35637]="生命之魂，给我你的力量！"
D.Strings[35638]="让我能清楚地与我面前的生灵对话！"
D.Strings[35639]="大地治愈者达鲁不安的踱着步。"
D.Strings[35640]="什么都没有发生……一定有东西在阻止我与她交流。"
D.Strings[35641]="这个生灵……她相当年迈且非常睿智。要是我们能与奈瑟匹拉交谈的话，我们就能了解很多与瓦丝琪尔和纳迦有关的事。"
D.Strings[35642]="你准备好就可以开始了，达鲁。"
D.Strings[35643]="让这成为所有克瓦迪尔人的教训。你太弱了！面对艾萨拉只会为你带来死亡。"
D.Strings[35644]="逃回你那可悲的迷雾中去吧。要是胆敢回来，我们就要把你们杀得一个不剩。"
D.Strings[35645]="这间破旧的旅馆从外面看已经惨不忍睹，不过倒是个理想的据点。"
D.Strings[35646]="是你救了我一命！"
D.Strings[35647]="我太愿意离开这鬼地方了。"
D.Strings[35648]="你无法想象我们所经历的一切……"
D.Strings[35649]="纳迦简直是恶魔！"
D.Strings[35650]="我欠你的永远还不清，英雄。"
D.Strings[35651]="他们在你离开时发动了攻击……首领在战斗中倒下了。其它人都退进了洞里，你也应该这么做。"
D.Strings[35652]="狂喜吧，因为你将第一个死去。我们会横扫卡兹莫丹，将一切烧成灰烬。"
D.Strings[35653]="我不在乎我得把你杀死多少回……为了救这片土地，我可以拿去你们所有人的生命！"
D.Strings[35654]="没错，我们也一样！"
D.Strings[35655]="看那儿！克罗姆加热气球朝林地飞去了！我们得赶快！"
D.Strings[35656]="我们来得太迟了。林地已经被毁，一起被毁的还有我们的希望和梦想。"
D.Strings[35657]="部落将为他们的残暴付出代价。地狱咆哮必须对这罪行负责！"
D.Strings[35658]="真是好运！贡品竟把自己扔上了祭坛！"
D.Strings[35659]="进攻！不留活口！"
D.Strings[35660]="烧吧……"
D.Strings[35661]="肉，鲜活的肉……"
D.Strings[35662]="把你自己献给火焰。"
D.Strings[35663]="脆弱的骨头和纤细的肌肉。来吧，来吧！被火焰吞噬吧！"
D.Strings[35664]="$r，耀眼的闪电总是会在转瞬间便消失。"
D.Strings[35665]="随我一同拥抱黑暗与烈火吧。"
D.Strings[35666]="你的痛苦将会使烈火烧得更旺！"
D.Strings[35667]="和这火焰融为一体吧！"
D.Strings[35668]="这是什么，长者？我从没见过像这样的东西……就连泰达希尔染病时都没见过。"
D.Strings[35669]="我不知道，哨兵。我唯一能感受到的就是黑暗魔法的气息。绝对的邪恶。"
D.Strings[35670]="是部落吗？腐化会是他们造成的吗？"
D.Strings[35671]="不，宝贝儿，这可比部落要邪恶得多。从石爪峰发散而出的黑暗力量非常古老。甚至比这个世界本身还要久远。"
D.Strings[35672]="那我们要如何存活下去，长者？我们该怎样对抗部落和这古老的邪恶力量？"
D.Strings[35673]="我也没有答案，孩子。"
D.Strings[35674]="一股黑暗力量在席卷石爪峰。"
D.Strings[35675]="我不明白这地方的起源与用途。$B$B这些通道是行军用的，这没错，可这里同样遍布烧焦与饱受折磨的尸体，有些尸体已经部分被吞食，而大部分则只是被打得面目全非。$B$B尽管我们是在火焰之地，我却感觉像是已经跨进了地狱。"
D.Strings[35676]="我把我的海龟伙伴弄丢了。我能再拥有一个吗？"
D.Strings[35677]="当然可以，$n。是你把这些海龟从暮光之锤的魔爪中救了出来——他们会追随你到任何地方。"
D.Strings[35678]="你是怎么让自己卷入这混乱的，鲍比？？？"
D.Strings[35679]="可这东西究竟是什么？我会再用我的扳手狠狠敲它几下。不管是什么毛病，希望这顿猛敲都能把它修好。"
D.Strings[35680]="下一次，鲍比……下一次……"
D.Strings[35681]="“当然没问题，我会接下这个活儿，去石爪山好好地修理修理那些垃圾暗夜精灵。”鲍比，你可真是个白痴。"
D.Strings[35682]="也许这玩意儿的疯狂翅膀会突然砸到我头上，帮我解除这痛苦。我要敲得更用力更快一些来加速这情况的发生。"
D.Strings[35683]="%s靠近涅墨西斯水晶，小心翼翼地检查着它。"
D.Strings[35684]="要是你不马上返回萨达拉瞭望台或战痕谷，你将被从达纳苏斯投刃车上移下来。"
D.Strings[35685]="小$r。你现在闯入了我的地盘！"
D.Strings[35686]="要是你想找回你们的牲畜，就来抢啊，懦夫！"
D.Strings[35687]="%s就要爆发了！快到图加的壳下面来！"
D.Strings[35688]="有人听到什么奇怪的声音了吗？"
D.Strings[35689]="又来了！我肯定听到什么声音了！"
D.Strings[35690]="霜鬃袭击者！快响警报！"
D.Strings[35691]="准备作战，巡山人！把那些牲畜抢回来！"
D.Strings[35692]="霜鬃巨魔一直在突袭这农场。"
D.Strings[35693]="我们的人数严重不足，很难抵挡他们的侵掠。"
D.Strings[35694]="他们每次都是抢了牲畜就走。畜群已经再也经不起这种打击。"
D.Strings[35695]="有位巡山人已经看见了什么。睁大你们的双眼！"
D.Strings[35696]="我们做到了！干得好，小子们！"
D.Strings[35697]="让我们与奈瑟匹拉谈一谈。"
D.Strings[35698]="发生什么事了？你能听到我说话吗？"
D.Strings[35699]="我看不见你，但我能感觉到你的存在。我会说清楚我能做些什么。"
D.Strings[35700]="纳迦在压制我的意志。我能感觉到他们在做什么，可我无力采取任何行动。"
D.Strings[35701]="他们挖掘我的珍宝，他们切刻我的身体，他们扭曲我的灵魂。我能感觉到我的意志在粉碎，陌生人……他们想要让我为他们作战！"
D.Strings[35702]="我不会成为纳迦的傀儡。我会尽我所能去抵抗，可我恐怕不能一直坚持下去。拜托了，快来人阻止他们！"
D.Strings[35703]="我还以为我要死在这下面了。"
D.Strings[35704]="我以为他们要把我撕成碎片！"
D.Strings[35705]="愿圣光护佑你，陌生人。是你救了我！"
D.Strings[35706]="从穴居人出现的那天起，我就再没有像现在这样高兴过！"
D.Strings[35707]="我已经迫不及待想要回家与家人团聚了。谢谢你，陌生人。"
D.Strings[35708]="我已经试着向沙尔斯巴里解释过很多次了——我没办法把他变成一只狼人。可他总是充耳不闻，反而让自己坚信，只要能获得我的信任，我就会和他分享秘密。$B$B侏儒可真是奇怪的家伙。"
D.Strings[35709]="听口令！集合！"
D.Strings[35710]="克罗姆加大王正在召集步兵前往石爪山。"
D.Strings[35711]="我们将向那里进军，目的只有一个——而且是唯一的一个："
D.Strings[35712]="消灭联盟！"
D.Strings[35713]="嗯哼。别忘了炸弹，阿尔多。"
D.Strings[35714]="更正一下。我们要做两件事："
D.Strings[35715]="消灭联盟，并确保我们的新式地精炸弹能完好无损的到达石爪山……"
D.Strings[35716]="用它去干掉联盟吧！"
D.Strings[35717]="现在，有没有志愿者？"
D.Strings[35718]="听起来不错。第一营做好准备！而且千万别忘了……"
D.Strings[35719]="地狱咆哮之眼注视着你。"
D.Strings[35720]="她的身体从里面看似乎显得更大了。真令人惊叹！"
D.Strings[35721]="看，$r。我看到了人类和兽人，他们是戴着锁链的奴隶，正在挖掘奈瑟匹拉的珠宝。我还看到手执鞭子的纳迦。一定要想想办法。"
D.Strings[35722]="这边这个是什么？"
D.Strings[35723]="戈德林的坚韧战力充满着传奇色彩。$B$B各地的战士都纷纷到访这座圣殿，祈求能像戈德林那样勇猛卓绝。"
D.Strings[35724]="你太迟了，蠢货！古灵的意志已经破碎了。占据已经接近完成了！"
D.Strings[35725]="现在，你将见证仪式的完成，那匹野兽将成为你的敌人！"
D.Strings[35726]="不！奈瑟匹拉属于纳迦！"
D.Strings[35727]="啊！我的魔球！"
D.Strings[35728]="不！我的气泡正在变得薄弱！"
D.Strings[35729]="奈瑟匹拉！你为何要对抗我？"
D.Strings[35730]="终于完成了！现在，奈瑟匹拉是我的了！！！"
D.Strings[35731]="抓紧了，这一路可会相当颠簸。密切留意暗夜精灵！"
D.Strings[35732]="又有一批新鲜的肉为你送到了，索博兹。希望这些不会像上次那营人一样，最后成为我车上的死尸。"
D.Strings[35733]="没什么事比杀联盟更让我感到爽快了。"
D.Strings[35734]="对像你这样堕落的兽人来说，还有什么是比杀联盟更美妙的呢，乌图克？"
D.Strings[35735]="你知道我无法拒绝牛头人美女，多特拉格。她们是我的死穴……"
D.Strings[35736]="你真是个恶心到极点的兽人啊，乌特。"
D.Strings[35737]="为部落作战机器准备了更多的弹药。"
D.Strings[35738]="看来我们这儿来了一些石雨的士兵。多特拉格、乌图克，你们的专长能够在克罗姆加壁垒派上用场。"
D.Strings[35739]="其余的步兵立刻整装出发！我们要战斗了。"
D.Strings[35740]="$r，我这一辈子都没见过这样的东西……"
D.Strings[35741]="我们的战备不足以在此交战。$b$b必须做好准备才行……"
D.Strings[35742]="是，长官！乌特，我们出发。"
D.Strings[35743]="你有宝贝吗？"
D.Strings[35744]="那口袋里是什么？嗯？"
D.Strings[35745]="我们干掉他们之后，夺走他们的东西……"
D.Strings[35746]="你给我们带来了什么？从上面带来了财宝？"
D.Strings[35747]="士气变得高涨了，多谢你的努力，$c。"
D.Strings[35748]="要是我们能从这儿杀出去，地狱咆哮一定会获知你的功绩，$r。"
D.Strings[35749]="这些兽人和我已经在多次战斗中出生入死。$b$b我不羡慕任何进到这里的纳迦。"
D.Strings[35750]="他们来了！动作快，$n，我的战斧渴望这些纳迦的鲜血！"
D.Strings[35751]="纳迦！他们跟踪$n溜上船了！"
D.Strings[35752]="他从不放弃——铁木队长——他说要让他们为其所玷污的每一寸土地付出代价。他很可能就在那下面，也许还活着！"
D.Strings[35753]="为了地狱咆哮！"
D.Strings[35754]="准备好战斧！敌人靠近了！"
D.Strings[35755]="他们在围攻我们，萨满！发挥你的作用！"
D.Strings[35756]="战士们，坚定意志！现在还有许多纳迦需要消灭！"
D.Strings[35757]="%s大口喘息着，在寒风中颤抖着。"
D.Strings[35758]="混合、搅拌、加热……"
D.Strings[35759]="凡人的躯壳能否经得住极端温度的转变，要弄清楚！为了科学！"
D.Strings[35760]="这个有点儿不稳定，但不经过失败怎么会进步？"
D.Strings[35761]="我为我们安排了逃路，$n。你们跟我来。"
D.Strings[35762]="达鲁——做得好。别在奈瑟匹拉的壳里耽搁太久。你跟我都清楚由愤怒的半神带来的危险。"
D.Strings[35763]="现在，跟我走！"
D.Strings[35764]="朋友，跨上海马吧。当奈瑟匹拉攻击纳迦的时候，你绝不会想要靠近她的。"
D.Strings[35765]="啊——啊！我终于不用再受纳迦的奴役了，我的意志又是我自己的了！"
D.Strings[35766]="我的身体已经开始对抗纳迦的侵染。我请你们在我释放怒火之前，快逃到安全的地方去！"
D.Strings[35767]="你现在可以走了，朋友。牛头人的挚友埃鲁纳克应该正和海马一起等在外面。事实上，就像他现在就在这儿。"
D.Strings[35768]="别担心，埃鲁纳克。牛头人会没事的。"
D.Strings[35769]="我们在等什么？出发！"
D.Strings[35770]="战士们！让他们流血！"
D.Strings[35771]="坚守阵地……战斗！"
D.Strings[35772]="你们天生就是英勇的兽人战士！绝不后退半步！"
D.Strings[35773]="我们……被打败了。尽量逃走……"
D.Strings[35774]="以萨尔之名！到处都是敌人……"
D.Strings[35775]="纳兹戈林！他们抓住我了……"
D.Strings[35776]="%s将自己钉在刺上，露出了他的头！"
D.Strings[35777]="这份工作对你来说再适合不过了，达鲁。我必须去处理外面的事情。"
D.Strings[35778]="也祝你好运，$n。"
D.Strings[35779]="让我看看那碎片，可以吗队长？我能感觉到它的能量正从洞穴的另一侧放射出来。"
D.Strings[35780]="还不够好……"
D.Strings[35781]="这些水下的资源真是让人无话可说。任何工程材料和替换件都能找到代用品。给我几天时间，我就能用水藻和贝壳做出一辆水下改装跑车！"
D.Strings[35782]="部落失去了斯通沃德监狱的控制权！"
D.Strings[35783]="联盟失去了斯通沃德监狱的控制权！"
D.Strings[35784]="联盟夺取了斯通沃德监狱的控制权！"
D.Strings[35785]="部落夺取了斯通沃德监狱的控制权！"
D.Strings[35786]="当被逼入绝境，结果可能是无法预料的……"
D.Strings[35787]="部落失去了商人广场的控制权！"
D.Strings[35788]="联盟失去了商人广场的控制权！"
D.Strings[35789]="联盟夺取了商人广场的控制权！"
D.Strings[35790]="部落夺取了商人广场的控制权！"
D.Strings[35791]="部落失去了教堂区的控制权！"
D.Strings[35792]="联盟失去了教堂区的控制权！"
D.Strings[35793]="联盟夺取了教堂区的控制权！"
D.Strings[35794]="部落夺取了教堂区的控制权！"
D.Strings[35795]="部落失去了格雷迈恩皇家庭院的控制权！"
D.Strings[35796]="联盟失去了格雷迈恩皇家庭院的控制权！"
D.Strings[35797]="联盟夺取了格雷迈恩皇家庭院的控制权！"
D.Strings[35798]="哦上帝！它还没死！快跑！"
D.Strings[35799]="部落夺取了格雷迈恩皇家庭院的控制权！"
D.Strings[35800]="别吃掉我的头！"
D.Strings[35801]="我还年轻，我不想死！见鬼，我那么漂亮，怎么能死！"
D.Strings[35802]="快来人干掉它！"
D.Strings[35803]="这都是你的错！它本该已经死了！现在它吃掉了你的脑子！"
D.Strings[35804]="|cFF68228B我来自深渊。|r"
D.Strings[35805]="|cFF68228B渺小的凡人|r"
D.Strings[35806]="|cFF68228B你将侍奉我，然后在痛苦中死去。|r"
D.Strings[35807]="|cFF68228B你的世界在你的面前崩溃。|r"
D.Strings[35808]="|cFF68228B你逃不掉的。|r"
D.Strings[35809]="|cFF68228B你简单的头脑不可能领悟这其中的真相。|r"
D.Strings[35810]="无耻的怪物！"
D.Strings[35811]="滚出我们的土地！"
D.Strings[35812]="这地方跟废墟相比没那么凉爽，如果要我说的话，这儿的空气也有些太过潮湿，不过确实给我一种舒服的、回到家里的感觉。$B$B你不这么认为吗？"
D.Strings[35813]="“洗衣桶”，让我再看看那个无悯者。"
D.Strings[35814]="我不知道你怎么想，可我真的很想念下面废墟里那些取之不尽的原料！$B$B就凭我们在这洞里找到的少得可怜的材料，我甚至都不知道能不能造出一颗哑弹！"
D.Strings[35815]="菲亚斯科，我想再看看那无悯之头。"
D.Strings[35816]="纳迦。$B$B<维索恩充满厌恶地朝地上吐了口唾沫。>$B$B他们可真蠢，居然妄想能用鞭子把兽人训得任其差遣。我们要让他们后悔，没把握住机会杀了我们，让他们一个个全都后悔。"
D.Strings[35817]="欢迎你，朋友。\n\n虽然我们这儿没什么现成的补给品，可我一定会尽我所能为你提供帮助。"
D.Strings[35818]="我的营救计划非常完美。简直无懈可击。只有一个地精可能阻止我成功。一个长鳍的地精。这想法可真可怕。"
D.Strings[35819]="啊！兽人……这得慢慢习惯才行……"
D.Strings[35820]="快醒醒，气泡先生！"
D.Strings[35821]="返回杜隆塔尔！"
D.Strings[35822]="你在吗，气泡先生！"
D.Strings[35823]="快醒醒，气泡先生！快救救那些灵魂！"
D.Strings[35824]="到底是……$n？"
D.Strings[35825]="乖乖隆地咚！"
D.Strings[35826]="你们这群白痴简直疯了！"
D.Strings[35827]="从野性生灵在艾泽拉斯出现的那一刻起，这个世界上就有了戈德林的身影。他就像是猎手之魂，是野兽嗅到食物或感受到幼子身处险境时迸发的动物本能。他出现时是一头身形巨大的白狼，凶猛而诡诈。$B$B他闻名于各种文化。兽人甚至给他起了个特有的名字——“洛戈什”。$B$B一万年前，当恶魔首次入侵艾泽拉斯时，戈德林与其它远古半神们比肩拼死抵抗。"
D.Strings[35828]="就是那段最黑暗的日子，为戈德林坚忍的作战风格笼上了一层传奇色彩。正当别人在那些恶魔军团面前战栗时，他们的数量却只会激发出狼神先祖更强大的战技。他会冲进敌阵，尖牙沾满敌人肮脏的血液，他的利爪会一下刺穿数十个敌人……$B$B据说，他在暗夜精灵撤离埃雷萨拉斯——现在被我们叫做厄运之槌的古城时，在后方担负着掩护的重任。$B$B他死了吗？我不知道这凶猛的野兽之魂是否会真的死去，$n。"
D.Strings[35829]="如何是好？"
D.Strings[35830]="让我看看你的货物，菲洛留斯。"
D.Strings[35831]="狼魂先祖的坚忍战力充满传奇色彩。$B$B以他为榜样吧，$c，胜利一定就在前方等着你。"
D.Strings[35832]="洛戈什是猎手之魂，是野兽嗅到食物或感受到幼子身处险境时迸发的动物本能。他始终与我们同在，与部落血脉相连，永存于我们的天性与血液之中。$B$B他以多种形态出现在我们的世界与此地。在艾泽拉斯，人们说他是一只巨大的白狼，凶猛又诡诈。暗夜精灵叫他“戈德林”。$B$B他们讲述着一场发生在一万年前的传奇之战——洛戈什击败了恶魔军团。你想要了解一下吗？"
D.Strings[35833]="一万年前，恶魔首次侵入了我们的世界，就像他们夺取兽人的家园德拉诺一样。他们鱼贯而入，将战火蔓延到了各个角落。艾泽拉斯伟大的远古半神们帮助凡间种族拼死抵抗。$B$B洛戈什的坚忍战力便是在这段最黑暗的日子里成为了传奇。他对恶魔毫无畏惧。他会冲进敌阵，尖牙沾满敌人肮脏的血液，他的利爪会一下刺穿数十个敌人……$B$B他不屈于恶魔的勇武精神激励着我们每一个人。我们都能从他身上汲取能量。"
D.Strings[35834]="高贵的艾维娜——百鸟之神！艾泽拉斯的所有空中生灵曾经都对她效忠，尤其是猛禽德鲁伊。正是由于她的恩赐，我们才获得了变换形态和翱翔天空的能力。$B$B艾维娜集美丽与可怖于一身，就像那些被她甄选而打造成的强大猛禽一样。她曾住在耸入云天的母亲之树加尼尔的精神圣域，而每当她在艾泽拉斯出现时，她的形象总是一位长着双翼的女神。"
D.Strings[35835]="<楚伦娜的脸色暗淡了下来。>$B$B一万年前，恶魔在上古战争期间闯入艾泽拉斯。艾维娜召集她的子嗣集聚天穹，在前线阻击恶魔军团。$B$B愤怒中的她所向披靡，千百个恶魔被她的利爪撕裂。可她最终还是陷入了末日守卫的包围，他们尖利的长矛从她身体两侧齐齐刺入……$B$B据说她的鲜血也仿佛有意志一般，向恶魔发起凶猛的攻击，烧灼他们的血肉，就像是她自己从天而降，把他们一举击溃。"
D.Strings[35836]="艾维娜在那天倒在了战场上，但凡间种族和其余的上古诸神最终还是取得了胜利。首批德鲁伊在遍地尸殍中找到了她的遗体，并将她埋葬在了这里——埋在了这高山之巅。$B$B她就永眠在这圣殿之外，在圣石圈起的圆环之中。$B$B人们用加尼尔的一颗种子种出了世界之树——这也是那圣域唯一的留存，否则整个圣域都会同艾维娜一同消亡。"
D.Strings[35837]="我们凡间种族对艾森娜知之甚少，她是在茂密的野性丛林中潜行的荒野之魂。她是森林之灵，是它跃动的心脉，是粉碎岩石、吞噬遗迹、将茂密的丛林用神秘与恐惧灌注的生命能量之源。艾森娜是生命之网的中心。$B$B暗夜精灵在卡利姆多各地都为她修建了圣殿。人们崇敬她……可并不了解她。$B$B你觉得要是我们能对这避世而强大的远古半神有少许了解，那会怎么样呢？"
D.Strings[35838]="啊，托尔托拉！它总是被误解，总是被低估。那些在陆地和海洋之间轻松穿行的生物都会将托尔托拉当作神祗和祖先来崇拜。$B$B一万年以前，燃烧军团入侵艾泽拉斯。托尔托拉与塞纳留斯和其他凡间种族共赴战场。$B$B当恶魔大军对守卫者们的阵线发动冲击的时候，他们拿托尔托拉毫无办法。一开始，他们对它并不在意。但托尔托拉可怕的重量和致命的双颚在转瞬间就杀死了成百上千的恶魔……"
D.Strings[35839]="托尔托拉从未倒下。尽管最后被那些强大的军团末日守卫团团围住，可他们却对他那坚硬的皮肤和刀枪不入的龟壳束手无策。喔，他们当时别提有多暴怒了！在凡间种族得以重整兵力来关闭传送门、终结入侵之前，托尔托拉守住了阵地，并掩护他们完成了决定性的撤退。$B$B据说在战斗结束后，有人发现托尔托拉被压在堆成山的恶魔尸体下面。他抖抖身上的尸体，从斑驳血污里伸出了头。然后安静地、慢慢地……问我们打赢了没。$B$B<哈缪尔把一只手按在了肚子上，发出了发自肺腑、无法抑制的狂笑。>"
D.Strings[35840]="给我讲讲与戈德林有关的事。"
D.Strings[35841]="他发生了什么事？"
D.Strings[35842]="告诉我有关狼魂先祖——洛戈什的事。"
D.Strings[35843]="是的，我还想知道更多。"
D.Strings[35844]="欢迎你，$c！"
D.Strings[35845]="告诉我有关艾维娜的事。"
D.Strings[35846]="你为什么用过去式讲话？她发生了什么事？"
D.Strings[35847]="她怎么了？"
D.Strings[35848]="告诉我有关艾森娜之魂的事。"
D.Strings[35849]="告诉我有关托尔托拉的事。"
D.Strings[35850]="大地观察者不会容许派系争斗威胁到大地之环在此地的工作。\n\n任何打破和平的人，都将面临……严厉的处罚。"
D.Strings[35851]="后来发生了什么事？"
D.Strings[35852]="蛮锤总是对萨满巫术青睐有加，这没错，可让我们待在海底下，作为大地之环的一员？\n\n要是在一年前，几大杯啤酒就能让我相信这个事实。"
D.Strings[35853]="正在使你与女武士进一步协调，你已获得一项新技能！"
D.Strings[35854]="我们的战士……他们现在都已沦为俘虏。"
D.Strings[35855]="这说不通，可那些恶棍却不遗余力地想要延长我们的生命……"
D.Strings[35856]="告诉我你的名字，兽人。"
D.Strings[35857]="我们是地狱咆哮的先锋战士！"
D.Strings[35858]="我们抓到他们了！$b$b该死的联盟船只……我们本可以第一时间抄近路直取暴风城，彻底解决了他们！$b$b可不知打哪儿冒出来巨大的触手，一把抓住了我们的船……把它断成了两截！$b$b幸存者们……我们一落水就立刻被纳迦抓住了。"
D.Strings[35859]="告诉我们是谁把你抓住的，古罗克。"
D.Strings[35860]="真是奇怪，从没想过纳迦竟然会设法让我们活下来。$b$b他们用神秘的珍珠造出牢房——让我们能够呼吸的小单间，然后就不管我们了……。$b$b他们每天都会送走一些囚犯……不知道去往哪里。$b$b再也没见过他们……"
D.Strings[35861]="你是怎么逃脱的呢？"
D.Strings[35862]="我们当中有位战士得以逃脱，并打碎了许多牢笼……我们自由了——至少是片刻的自由。$b$b有些人朝水面蜂拥游去……有些则看到并朝这个洞穴游来。$b$b我是唯一活下来的人……"
D.Strings[35863]="步兵们，立正站好！"
D.Strings[35864]="你有见到纳兹戈林和他的部队吗？"
D.Strings[35865]="我不知道他们发生了什么事。$b$b不断有俘虏出现。部落和联盟的都有——几乎都只剩下一口气。$b$b他们一定是被强行拖到海沟那边去了，不然就只有死路一条。"
D.Strings[35866]="那该怎么解决这些怪物呢，古罗克？我们该如何击败他们？"
D.Strings[35867]="他们的人数多得难以计算。他们的防御仿佛无懈可击。$b$b我找不出任何可以利用的薄弱环节，$r。"
D.Strings[35868]="待着别动，小鱼！"
D.Strings[35869]="你为什么非要如此嘲弄我？"
D.Strings[35870]="哦，珍宝船长要发怒了……"
D.Strings[35871]="回到……这儿……来……"
D.Strings[35872]="啊哈！一条鱼！"
D.Strings[35873]="过来，小乖鱼儿……"
D.Strings[35874]="我糊涂了。我所见到的一切让我困惑不已……"
D.Strings[35875]="谁会把“死”海怪放到他们脑袋上，真有这事儿？！"
D.Strings[35876]="菲亚斯科，你可真是个蠢货！下次随便找个什么东西炸了！"
D.Strings[35877]="我干嘛要怕这玩意儿？"
D.Strings[35878]="我想回家！"
D.Strings[35879]="我为什么会离开布瑞尔？"
D.Strings[35880]="别再把那么大个儿的恶魔章鱼弄进来了！"
D.Strings[35881]="肉豆蔻不会让我失望！"
D.Strings[35882]="我正在吉尔尼斯跳爆竹！"
D.Strings[35883]="“洗衣桶”，你长了个雷象的长鼻子？你连黏胶都没有！"
D.Strings[35884]="你这样子可真是蠢毙了！"
D.Strings[35885]="把他们的大个子头领敲掉！"
D.Strings[35886]="你要去找妈妈爸爸吗？去吧！"
D.Strings[35887]="等这结束之后，我可一定要好好喝上几杯！"
D.Strings[35888]="我们敬爱的酋长怎么让你失望了？"
D.Strings[35889]="那猪兔大杂烩是怎么一回事？"
D.Strings[35890]="你的家人不用再忍饥受饿。"
D.Strings[35891]="你所爱的人找到了遮风避雨的住所。"
D.Strings[35892]="大使，我们一直在等您。"
D.Strings[35893]="你可以昂首挺胸地走在奥格瑞玛的街道上！"
D.Strings[35894]="在地狱咆哮酋长的率领下，我们成为了新的部落，我们是自己命运的主人。"
D.Strings[35895]="可为什么，我们没能夺回石爪山？"
D.Strings[35896]="联盟是怎么阻止强大的部落战争机器的？"
D.Strings[35897]="从今天开始，我们的字典里再无失败二字。"
D.Strings[35898]="在地狱咆哮警觉的掩护下，不论生死，我们都要夺回石爪山。"
D.Strings[35899]="不要退缩——地狱咆哮的双目在注视着你们每一个人！"
D.Strings[35900]="向传送门的另一侧望去，你满眼却只看到黄沙。只能分辨出沙漠废墟当中的一池水。这传送门是通向哪里的呢？"
D.Strings[35901]="传送门里是一片古老的史前沙漠废墟。狂风吹过，一场沙尘暴呼之欲出。这传送门肯定是通往某个重要的地方，但究竟是哪里呢？"
D.Strings[35902]="你们这些蠢货别再四处乱跑了！面对惩罚吧！"
D.Strings[35903]="快来人，把$n的脑袋给我砍下来！"
D.Strings[35904]="地狱咆哮之眼注视着我们！"
D.Strings[35905]="愤怒，渴望杀戮。"
D.Strings[35906]="这颗宝珠上有一个巨大的人形生物掌印。掌印中似乎还脉动着一种绿色微光。"
D.Strings[35907]="这些土地是黑暗女王征战的前线，$n。看看它们吧；过不了多久，这些都将落入被遗忘者的掌控之中。"
D.Strings[35908]="啊，英雄们坚持到了辉煌的尾声。你们斗志昂扬，为最后一战做好准备了吧？那就看看我的终极造物！复活吧，妹妹！"
D.Strings[35909]="是谁在对我们做这样的事？"
D.Strings[35910]="黑暗女王在注视着你……"
D.Strings[35911]="在这种情况下要我怎么保持旅店的清洁？你会负责处理这俾格米的麻烦吗？"
D.Strings[35912]="地精僵尸？！接下来是什么……火山喷发？"
D.Strings[35913]="坩埚看起来废弃无力。$B也许你能在附近某个地方设法让自己与女武士谐调起来……"
D.Strings[35914]="万岁，气泡先生！你回来了！你还记得怎么开枪吗？为什么不花上几分钟来温习战斗的技巧呢！以防万一也好。"
D.Strings[35915]="千万要多加小心，气泡先生。要是你看见大批侏儒，记得用磁性拉住他们！等把他们全都吸住，就送他们归天！耶！"
D.Strings[35916]="抓住他们，气泡先生！"
D.Strings[35917]="让他们后悔对你造成的伤害，气泡先生！"
D.Strings[35918]="可恶，可恶，可恶的联盟！"
D.Strings[35919]="我已经准备好帮助气泡先生了，孩子。让我进去。"
D.Strings[35920]="立刻返回圣殿。仪式马上就要开始了。"
D.Strings[35921]="女士要你返回圣殿，荣誉卫兵。"
D.Strings[35922]="你的重担已经卸除，荣誉卫兵。回圣殿去吧。"
D.Strings[35923]="你先回圣殿。我留下收拾烂摊子。"
D.Strings[35924]="女士捎话来，要你返回圣殿。别耽搁了。"
D.Strings[35925]="祭司们很快就会需要你的帮助。女士命你返回。"
D.Strings[35926]="回去参加仪式。我们的女士在等着你。"
D.Strings[35927]="潮汐女王需要你帮她守卫圣殿。立即赶回那里。"
D.Strings[35928]="怎么，女武士？"
D.Strings[35929]="希拉柯丝女士派我来找你。她需要你参加仪式。"
D.Strings[35930]="我会立即前往的，女武士。谢谢你。"
D.Strings[35931]="以艾萨拉之名。"
D.Strings[35932]="猎潮者必败。"
D.Strings[35933]="希望你能用你的战戢为我们的防御带来荣光。克瓦迪尔人的数量还在增长。"
D.Strings[35934]="非常感谢你为我带来这个消息，女武士。"
D.Strings[35935]="为了她的荣耀，纳兹夏尔女士。"
D.Strings[35936]="我马上就去找潮汐女王。谢谢你为我带来这个消息，女武士。"
D.Strings[35937]="我明白了。多谢你亲自赶来通知我，女武士。"
D.Strings[35938]="女武士，你的出现使我倍感荣幸。现在可以开始仪式了吗？"
D.Strings[35939]="是的，深渊召唤者。女王在等待。"
D.Strings[35940]="当然，我会立即收工，回圣殿与女王会面。谢谢你，女武士。"
D.Strings[35941]="如您所愿，女士。"
D.Strings[35942]="马上，女士。"
D.Strings[35943]="听从命令。"
D.Strings[35944]="立即执行，我的女士。"
D.Strings[35945]="明白，女士大人。"
D.Strings[35946]="我即刻执行。"
D.Strings[35947]="当然，我的女士。"
D.Strings[35948]="开始行动。"
D.Strings[35949]="哎呦！你碰得我真难受！"
D.Strings[35950]="走哪边？？？"
D.Strings[35951]="你是自己人。谢谢你！"
D.Strings[35952]="为什么会这样？？？"
D.Strings[35953]="裂隙已经被关闭，暴风城安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！"
D.Strings[35954]="你会在深渊里粉身碎骨！"
D.Strings[35955]="放我出去！"
D.Strings[35956]="我们受到攻击了吗？"
D.Strings[35957]="让所有人都牢记这个名字——$n，真正的勇士，暴风城的救星！向$n致敬！"
D.Strings[35958]="%s被你的摇摆诱饵吸引了！"
D.Strings[35959]="黑铁万岁！"
D.Strings[35960]="返回关押所！"
D.Strings[35961]="更多敌人来了！开火！开火！"
D.Strings[35962]="把天空撕成碎片！"
D.Strings[35963]="我被击中了！"
D.Strings[35964]="到处都是联盟的人！"
D.Strings[35965]="Throm-ka，军团士兵！"
D.Strings[35966]="低头行礼！$n正从我们身边走过！"
D.Strings[35967]="$g阁下:女士;！"
D.Strings[35968]="现在走来的是部落真正的勇士！"
D.Strings[35969]="我们为什么要乘一艘雇佣兵船上战场？在过去我们早把这些海盗就地正法了。"
D.Strings[35970]="我不想伤害你，可我会的！"
D.Strings[35971]="闻到血了，你呢？"
D.Strings[35972]="你今天别想吃掉我！"
D.Strings[35973]="走开，深渊的怪物！"
D.Strings[35974]="别逼我召唤闪电！"
D.Strings[35975]="别靠近维尔哈伊！"
D.Strings[35976]="看到码头里的船啦？"
D.Strings[35977]="从战场返回的就只剩它们了，还在被维修。"
D.Strings[35978]="我也不喜欢这样，但又能怎么办呢?"
D.Strings[35979]="我们雇那些佣兵把我们送过去，这是支援友军的唯一办法了。"
D.Strings[35980]="有点道理。只是感觉有些不对劲儿……"
D.Strings[35981]="让我看看你的商品，德尼卡。"
D.Strings[35982]="欢迎加入军队，新兵。"
D.Strings[35983]="好吧好吧！$r说了算！"
D.Strings[35984]="噢别打我！我愿意帮助部落！"
D.Strings[35985]="疼！快停下！"
D.Strings[35986]="别伤害我！我听你的！"
D.Strings[35987]="不！我是不会帮部落的！"
D.Strings[35988]="我恨鞭子！"
D.Strings[35989]="我要打扁你的脸！"
D.Strings[35990]="我要让你吃鞭子！"
D.Strings[35991]="你是坏$r！"
D.Strings[35992]="我生气了！"
D.Strings[35993]="如此强大！我是不可战胜的！"
D.Strings[35994]="一切都将消亡！"
D.Strings[35995]="恐怖图腾死定了！"
D.Strings[35996]="在部落的力量面前颤抖吧！"
D.Strings[35997]="杀光粉皮肤的！杀！杀！"
D.Strings[35998]="勇士$n！"
D.Strings[35999]="你为部落带来了极大的荣耀，勇士$n。"
D.Strings[36000]="有何吩咐，$g 阁下:女士;？"
D.Strings[36001]="勇士$n与我们并肩作战！我们将战无不胜！"
D.Strings[36002]="$g 阁下:女士;，您愿意在我的武器上签个名吗？我儿子一定会开心死的。"
D.Strings[36003]="联盟必败！"
D.Strings[36004]="为了部落！为了地狱咆哮！"
D.Strings[36005]="很荣幸能与你共同战斗，勇士$n。"
D.Strings[36006]="嘿！嘿吉卜力！这地方可真臭！"
D.Strings[36007]="小心！大粪来了！"
D.Strings[36008]="我在这种环境下没法干活！我快不行了！"
D.Strings[36009]="这肯定有害健康！"
D.Strings[36010]="吉卜力，快找人弄掉这些大粪！"
D.Strings[36011]="史上·最烂·工作。"
D.Strings[36012]="我要吐了……"
D.Strings[36013]="我不干了！我宁可被联盟的火枪打死！"
D.Strings[36014]="部落可没给我足够的钱来干这……破事儿！"
D.Strings[36015]="把这臭死人的工作留给你吧，找个太阳晒不到的地方慢慢干！"
D.Strings[36016]="我受够了！找别人来守你这满是粪便的鬼地方吧！"
D.Strings[36017]="我快崩溃了，我再也不想忍受下去了！我退出！"
D.Strings[36018]="找别的倒霉鬼来守你这粪山吧！我不干了！"
D.Strings[36019]="不！！！别再来了！"
D.Strings[36020]="啊！嗯……你好啊。我在这儿只是在检查这个壳。继续！这儿没什么好看的！"
D.Strings[36021]="我在来的路上经过了公园区。那儿已经什么都没了……"
D.Strings[36022]="是啊，那只龙发动攻击时我正巧在那儿。"
D.Strings[36023]="要是愿意，他原本可以毁掉整座城市。而我们根本无能为力。"
D.Strings[36024]="他怎么又走了？"
D.Strings[36025]="不知道。这说不通……"
D.Strings[36026]="在我看来，那畜生简直疯了。"
D.Strings[36027]="他飞进来，一把火烧光了公园，然后拍拍翅膀飞走了。"
D.Strings[36028]="你为什么头朝下？"
D.Strings[36029]="要是你不马上返回战痕谷，你将被从克罗姆加攻城车上移下来。"
D.Strings[36030]="那你一路究竟是怎么过来的呢？"
D.Strings[36031]="听上去很不错。"
D.Strings[36032]="真是太糟了。总之……"
D.Strings[36033]="我现在真得走了。"
D.Strings[36034]="我看来遇到了……漂浮的麻烦。"
D.Strings[36035]="我也不确定。可能是因为我骨头太轻，或是肺活量异于常人。也许只是因为我中午吃的那块奶酪。$b$b不管怎样，要不是有这壳在，我早就像火箭一样窜出水面了。"
D.Strings[36036]="哎，家族遗传问题。恐怕掘歌家的人总是被浮力问题困扰。"
D.Strings[36037]="我用手划啊划啊，$g小伙子:小姑娘;……精疲力竭地划。我都不知道究竟有多少海水直接灌进了我的鼻子。$b$b不过你应该看见我用脚和牙齿力战大螃蟹的精彩场面了！那可真是荣耀啊，真的。"
D.Strings[36038]="我记得当我还是个小不点儿的时候……别的男孩子都能一猛子扎到洛克莫丹湖底，拾上来各种各样的海胆和贝壳。奥斯卡和我却只能趴在湖面上，两腿乱蹬，分享不到半点儿乐趣。"
D.Strings[36039]="我都数不清究竟有多少次，远远看见水底有金光闪闪的矿脉，透过水面折射出诱人的光芒。我却只能拿着矿锄两手空空地游走，眼睁睁地看着该死的兽人和血精灵轻而易举的潜入水底，大摇大摆的携矿而去。"
D.Strings[36040]="你根本无法想象像这样被困在瓦丝琪尔是什么感觉！你知道有多少鱼把我当成海草，咬我的脚趾头，在我的护甲里钻来钻去吗？$b$b光是挠痒痒就能把一个矮人逼疯！"
D.Strings[36041]="我知道你没兴趣听我抱怨这些。不要紧。$b$b但别忘了你有多幸运——“深谙水性”还能“向着一个方向游泳而不是只能往上浮”。"
D.Strings[36042]="每天都在地震。一头疯狂的龙正在毁灭世界，接着是什么？"
D.Strings[36043]="别胡思乱想，新兵。"
D.Strings[36044]="我跟部落打了十年的仗，还没见过比这次更糟的。"
D.Strings[36045]="专注于眼前的这场战斗，不然你怕是没命来担心了。"
D.Strings[36046]="你从哪儿来，士兵？"
D.Strings[36047]="刚刚从贫瘠之地回来。"
D.Strings[36048]="危险？你肯定听错了。那地方简直是绝境！"
D.Strings[36049]="我当时真不敢相信他们竟然要让我们一半人出海……"
D.Strings[36050]="啊，战斗之痕。我听说那地方相当危险。"
D.Strings[36051]="痛肠可真了不起。痛肠是在这新地方头一个打碎弱小人类的英雄。$B$B痛肠可真高兴。"
D.Strings[36052]="希尔瓦娜斯的胜利！这些土地将是我们的。"
D.Strings[36053]="如果没有援军，我们过不了几天就将被击溃。"
D.Strings[36054]="愿圣光与他们同在，老兄——当然也与我们同在。我们的兵力近来分得太散了。"
D.Strings[36055]="我们已经消灭了数百个元素，$n，可他们的力量却在增强！我们的守卫还能撑住，但他们肯定需要你的帮助。瓦里安·乌瑞恩国王正亲自坐镇贸易区指挥防御，吉安娜·普罗德摩尔女士正在法师区支援，大主教本尼迪塔斯则在镇守光明大教堂。$b$b不管你要前往暴风城的哪个方向，$n，我们需要你伸出援手！"
D.Strings[36056]="$n！暴风城已陷入元素的围困，需要你的支援！$b$b我们已疏散了大部分市民。乌瑞恩国王正在守卫贸易区，吉安娜·普罗德摩尔女士与大主教本尼迪塔斯正分别镇守法师区和教堂区。$b$b不论你要去哪儿，你的帮助都是必不可少的！"
D.Strings[36057]="我们击退了元素，$n。但它们留下了不少诡异的传送门。$b$b尽管于理不合——国王已经穿过了传送门，去探明它们通往哪里。我们已经在贸易区、教堂区和法师区都发现了传送门。$b$b我必须留下收拾残局，安排市民的返城工作。你快去帮国王！"
D.Strings[36058]="你的要求可真过分，将军。"
D.Strings[36059]="你在萨达拉树林只会找到受惊的小德鲁伊。他们手里根本没有什么大规模杀伤性武器。"
D.Strings[36060]="小心点儿，牛头人，你的话可以会成为背叛的证据。"
D.Strings[36061]="据我的眼线回报，在树林里藏着某种强大的武器。如果不加以阻止，联盟就将用它来对付我们。"
D.Strings[36062]="此外，是克罗姆加大王——加尔鲁什·地狱咆哮的钦点爱将派我来的。你可以选择按他说的做，或者后果自负。"
D.Strings[36063]="我已经派人去萨达拉树林找你所谓的证据了。你很快就会发现，那里的人根本不会对我们构成任何威胁。"
D.Strings[36064]="%s看上去充满感激。"
D.Strings[36065]="不找到她，我就哪儿都不去！"
D.Strings[36066]="我想我从这儿刚刚能看到它。就在海平线那儿。"
D.Strings[36067]="那座新岛是在上次地震之后升出水面的。"
D.Strings[36068]="在这条战线，我们将为那座岛屿而战。"
D.Strings[36069]="我这已经是第三次了。"
D.Strings[36070]="那可是场硬仗……"
D.Strings[36071]="要是那座岛落到部落的手里，暴风城就保不住了……他们都明白。"
D.Strings[36072]="我的宝贝儿子……不！！！为什么？？！"
D.Strings[36073]="玛莎，快到我们帐篷那边去躲起来。"
D.Strings[36074]="我不会离开你！别忘了，我可是家族中的女猎手！"
D.Strings[36075]="噢，玛莎……"
D.Strings[36076]="够了，士兵。"
D.Strings[36077]="暴风城还没失守，我们不会让部落占到半点儿便宜！"
D.Strings[36078]="将军！从你的帐篷里出来面对我吧！"
D.Strings[36079]="集中精神！很快就要和兽人交手了。"
D.Strings[36080]="到底要打什么？"
D.Strings[36081]="你去过那里对吗？"
D.Strings[36082]="是的，我……我想我也能看到它。"
D.Strings[36083]="愚蠢的老牛头人，你竟敢如此目空一切？！"
D.Strings[36084]="究竟为什么要打断我？"
D.Strings[36085]="这是你掉的吗，将军？"
D.Strings[36086]="我的徽章！是，是我丢的。你在哪里找到的，牛头人？"
D.Strings[36087]="是$n找到的。"
D.Strings[36088]="你的儿子无能又懦弱。真是有其父必有其子。"
D.Strings[36089]="至于你——$n，可真令人失望。你简直是部落的耻辱！"
D.Strings[36090]="你们所有人应受的惩罚，就是死！"
D.Strings[36091]="那是为我儿子！"
D.Strings[36092]="玛莎，我们必须逃走。逃得远远的。他们会来找我们的。"
D.Strings[36093]="谢谢你为我带回了狼。"
D.Strings[36094]="听好了！运输船随时都会抵达。"
D.Strings[36095]="好吧，兄弟们……等37066号任务一执行，船就会“即刻”抵达。在此期间，我邀请你们一起来跳段小舞消磨时光……"
D.Strings[36096]="别不好意思了，这里都是自己人……"
D.Strings[36097]="好，兄弟们！出发！"
D.Strings[36098]="我们是胜利使者……"
D.Strings[36099]="我嘲笑你，没用的$n，但我会照做。现在我们该回下面找我的主人了！"
D.Strings[36100]="有人正在用这些烧杯和炼金工具进行各种潜水艇燃料的实验。"
D.Strings[36101]="我们的人民被人类当作囚犯、当作奴隶，就关在这座营地里。我被锁在这些笼子里面；我看到我的兄弟们被关在这儿，吊在这些绞架上。$B$B我看见我们所有人的领袖——奥格瑞姆·毁灭之锤，被利刃刺穿背部。他的血把我们脚下的土地都染成了深色。$B$B现在再看看我们。落锤镇——我们世代的家园，我们在这里失去了一切，然后再用我们自己的双手夺回来。"
D.Strings[36102]="你面前放着几种油料样本，旁边还有一个空烧杯。烧杯看起来能装下大约五种样本。$b$b你想先选哪种油料？"
D.Strings[36103]="你接下来想要选哪种油料？"
D.Strings[36104]="你现在有两份油料样本了。接下来想要选哪种？"
D.Strings[36105]="你现在有三份样本了。接下来想要选哪种？"
D.Strings[36106]="你现在选好四份样本了，只能再选一份。选哪种呢？"
D.Strings[36107]="你已经把五份样本都选好了。"
D.Strings[36108]="龟油样本"
D.Strings[36109]="鮣魚油样本"
D.Strings[36110]="锤头鲨鱼油样本"
D.Strings[36111]="你可以用这些烧杯和炼金工具进行各种潜水艇燃料的实验。"
D.Strings[36112]="我们开始吧！"
D.Strings[36113]="把样本混合在一起！"
D.Strings[36114]="我想重新开始。"
D.Strings[36115]="你竟敢闯进我的宫殿，妄图散播这阴谋论的胡话！"
D.Strings[36116]="我不会让你和这大逆不道的指挥官碎石盗取我儿子与生俱来的权利！"
D.Strings[36117]="这指控可真荒诞啊，茉艾拉。首先，这就不能算是你的宫殿。"
D.Strings[36118]="我知道指挥官碎石和我都会为他的忠心和诚实打包票。我们必须相信他。"
D.Strings[36119]="看这儿，我做成了一份巨浪燃料样本。这烟可真呛人！"
D.Strings[36120]="看这儿，我做成了一份原子燃料样本。它看起来有点儿过热了。"
D.Strings[36121]="看这儿，我做成了一份贫油样本。它看上去……真不带劲儿。"
D.Strings[36122]="黑铁矮人有什么理由对铁炉堡兵戎相见？你连自己的人都管不住了吗，茉艾拉？"
D.Strings[36123]="看这儿，我做成了一份持久燃料样本。你觉得怎么样？"
D.Strings[36124]="看这儿，我做成了一份浓烟燃料样本。很漂亮，是吧？"
D.Strings[36125]="看这儿，我做成了一份快速燃烧的燃料样本。达到标准了吗？"
D.Strings[36126]="看这儿，我做成了一份可靠的燃料样本。锤头鲨鱼油和鮣魚油的比例是三比二。"
D.Strings[36127]="穆拉丁说得对。要是你连自己的人都管不好，就没资格进行这场谈判。"
D.Strings[36128]="呸！<咳嗽>那么多烟！<咳嗽>看来你加进了太多龟油！重来！"
D.Strings[36129]="没错，这确实太热了。你想要把船炸了吗？下次少放点儿鮣魚油。"
D.Strings[36130]="你说得对，真是一点劲儿都没有。还得加入更多的鮣魚油。重试一次！"
D.Strings[36131]="看上去是不错……可它烧得太久了！我需要能立刻让火停掉。下次少放点儿锤头鲨鱼油。"
D.Strings[36132]="你们都知道我决不会下这种命令！我为什么要把我儿子的遗产分一半给别人？"
D.Strings[36133]="我们接近成功了……可烟还是太多了点儿。下次别放龟油。<咳嗽>太多烟了。重来！"
D.Strings[36134]="你怎么做出这个的？它烧得就像闪光粉一样……太快了。再加点儿锤头鲨鱼油。"
D.Strings[36135]="就是它了！完美的生物燃料！干得好，$n！"
D.Strings[36136]="不，这对我们双方的人民来说都是一种背叛。尽管我拼尽了全力，一些黑铁矮人仍在暮光之锤的掌控之中。"
D.Strings[36137]="你发现了一种新型生物燃料！快把它拿给工程师“洗衣桶”测试一下。"
D.Strings[36138]="教派肯定在城里安插了人手来协同配合此次进攻。只有一个人有嫌疑——熔锤大使！"
D.Strings[36139]="你正要跨过一道可怕的门槛，克罗姆加。愿大地母亲宽恕你的灵魂。"
D.Strings[36140]="你发现了一种新型生物燃料！快把它拿给菲亚斯科·尖笑测试一下。"
D.Strings[36141]="黑铁矮人渣滓终于得到了他应得的，这太令人高兴了！"
D.Strings[36142]="安静！茉艾拉现在心情很糟，要是让她听见，你的脑袋就保不住了……"
D.Strings[36143]="这是艾泽拉斯的困难时期，$n。"
D.Strings[36144]="我需要图腾来打破元素囚牢！"
D.Strings[36145]="要怎样尽管来。我不怕。那个杂种永远别想成为我的帝王！暮光之锤万岁！"
D.Strings[36146]="要是我们在暗炉城，我一定会把你扔进秩序竞技场的，大使先生。现在只好拿铁炉堡里最黑暗的地下城凑合一下。"
D.Strings[36147]="仔细看着这一切，峭壁行者，见证部落的力量！"
D.Strings[36148]="我愿意去，$c。我在主人计划中应尽的职责已经完成。"
D.Strings[36149]="你都干了些什么，克罗姆加？"
D.Strings[36150]="我会护送你到新的“住所”，阁下。"
D.Strings[36151]="酋长！我……只是在执行你的命令！"
D.Strings[36152]="我的命令？"
D.Strings[36153]="我的命令是滥杀无辜吗，克罗姆加？"
D.Strings[36154]="熔喉开始挣脱捆绑他的锁链了！"
D.Strings[36155]="酋长……大人……我……"
D.Strings[36156]="我是个杀人狂吗，克罗姆加？"
D.Strings[36157]="不，酋长！"
D.Strings[36158]="那么，我再问你一次，你都干了些什么！"
D.Strings[36159]="我派你带一支军队来到石爪山。你的使命是为了部落守住这块土地。"
D.Strings[36160]="然而，你却把它变成了废土，滥杀无辜，连孩童也不放过……"
D.Strings[36161]="我在诺森德奋战了很长一段日子，克罗姆加。在那儿我学到了很多有关部落的东西。"
D.Strings[36162]="正是在那儿，一位睿智的老英雄给我留下了终生难忘的教导……"
D.Strings[36163]="“荣耀”，克罗姆加，“无论战斗多么可怕……也不要忘记荣耀”。"
D.Strings[36164]="克罗姆加大王，你使部落蒙羞了。"
D.Strings[36165]="你给我们带来了耻辱。"
D.Strings[36166]="以部落酋长之名，我现在解除你的职务。"
D.Strings[36167]="你被罢免了！"
D.Strings[36168]="还有你，$r！"
D.Strings[36169]="等等，酋长！请等等！正是$n这位英雄揭露了这场堕落。$g他:她;曾竭力阻止克罗姆加！"
D.Strings[36170]="请宽恕他，酋长。"
D.Strings[36171]="宽恕……你的妻儿被杀，族群被灭，你的家园被烧至焦土。"
D.Strings[36172]="宽恕……族长，今日你教导了我。"
D.Strings[36173]="巡山人维拉特·麦酒说你能帮我抵达洛克莫丹。"
D.Strings[36174]="$n，克罗姆加的军队不复存在了。你的军阶不再有意义。如果真心希望帮助部落，你的能力可以在凄凉之地或者南贫瘠之地派上用场。"
D.Strings[36175]="你自行决定吧。"
D.Strings[36176]="让荣誉指引你，$n。不要忘记，地狱咆哮一直在注视着你。"
D.Strings[36177]="<弗瑞恩呻吟着。>"
D.Strings[36178]="哈哈！他们肯定会看见这个，能不能开火都一样。"
D.Strings[36179]="别担心——要是他们敢装没看见，我会亲自游过去把他们从船上拽来。"
D.Strings[36180]="我们坚持到现在已经消灭了许多纳迦，可他们还在前仆后继地冲过来。到底要怎么做才能逃出这该死的洞穴？"
D.Strings[36181]="我不在乎自己是否会死在这儿，$n。我要让这些纳迦为我们每一个被杀死或奴役的同胞付出代价！$b$b就让其它人去烦恼该如何逃生吧。我要考虑的是该怎么让这些魔鬼受到惩罚。"
D.Strings[36182]="他们为什么这么做？为了珠宝？为了战争？上古之神奈瑟匹拉远比纳迦了解得要强大得多。要是奈瑟匹拉能为他们所用……那他们所能造成的伤害将达到令人发指的程度。"
D.Strings[36183]="负伤坐在这儿，看着我的弟兄们奋力战斗，这感觉可真让人难以忍受，可就连我都知道，我活着的价值要比死掉大得多。"
D.Strings[36184]="我不喜欢这里的感觉，$n。到处都是纳迦巫师和奴役者……我在这洞里唯一能感受到的就是痛苦。古老的生命在试图呼喊，可我却说不出话来。"
D.Strings[36185]="我们需要你的帮助，$c。我们已经拼尽了全力，但纳迦的攻势丝毫没有减弱。"
D.Strings[36186]="我的伤口还没愈合，$r。要是我们不尽快行动，恐怕我就要死在这家伙的肚子里。"
D.Strings[36187]="要是你的双手沾上了纳迦的鲜血，那你就是我的盟友。$b$b很久以前，我发誓决不再做任何人的奴隶，在那以后我一直信守对自己的承诺，直到落在埃卓凯丝的手里。现在我已经抑制不住胸中的怒火。鲜血是我唯一的渴望……我可以不吃不睡，甚至可以不要胜利……只要鲜血。"
D.Strings[36188]="噢……巴德。你这是又要干嘛？"
D.Strings[36189]="平民…"
D.Strings[36190]="列队！"
D.Strings[36191]="海平线上的岛就是我们的目的地！"
D.Strings[36192]="我们将在那里履行使命——为了国王，为了暴风城和她的子民们……"
D.Strings[36193]="击败那些兽人，送他们去追求荣耀，以此告慰每一名阵亡的士兵。"
D.Strings[36194]="地狱咆哮派来了他最强的战士。我们要确保他们全都回不了家……"
D.Strings[36195]="今天，地狱咆哮将学到萨尔没能教会他的那堂课…"
D.Strings[36196]="暴风城永不陷落！"
D.Strings[36197]="你已经获得不菲的报酬来完成这次直达行程，小姐。我们可没时间耽搁……"
D.Strings[36198]="现在做好准备。我们即将登岸。"
D.Strings[36199]="一块肉排被敲进了石头里，周围还垂着一大段绳子。$B$B这肯定有什么用途。"
D.Strings[36200]="解开你的诱饵，让它走。"
D.Strings[36201]="<拉葛雷克的声音在你脑中回荡。>$B$B我已经要……死了。你必须帮忙……阻止……暮光之锤。$B$B他们汲取……我的能量……来创造……他们的升腾者。他们在……对抗耐普图隆的……战争中……将是重大的……威胁。"
D.Strings[36202]="我想你为我准备了一只海龟？"
D.Strings[36203]="元素在愤怒的咆哮着。这与纳迦的到来一定不会是巧合。他们一定在等待着什么。"
D.Strings[36204]="我已经准备好和你一起看了，先知。"
D.Strings[36205]="等你准备好出发时，告诉我一声。"
D.Strings[36206]="巴德！不——！"
D.Strings[36207]="前进！守住桥梁！"
D.Strings[36208]="出发，断轮先生。"
D.Strings[36209]="设定航路向东，全速前进，与主力舰队汇合。"
D.Strings[36210]="新兵招募有何进展，统帅？我们迫切需要新兵增援。必须阻止黑石兽人对我们领土的入侵！"
D.Strings[36211]="喔上帝，快来人把我从这笼子里弄出去！"
D.Strings[36212]="我还年轻，我不想做祭品！"
D.Strings[36213]="等我出去了，我一定要把你们这群暮光之锤渣滓杀得一个不留！"
D.Strings[36214]="你们不用献祭我。我能做一个很好的教徒！"
D.Strings[36215]="你们这些教徒都是懦夫。你们令我恶心！"
D.Strings[36216]="嘿，你。对，就是你。你不是邪教徒。快把我弄出去！"
D.Strings[36217]="他们当中有人身上带着钥匙。快找来放我出去！"
D.Strings[36218]="我从没想到会以这种方式结束。"
D.Strings[36219]="谢谢你，$n。谢谢！"
D.Strings[36220]="我从没想过救我的人竟会是你，$n！"
D.Strings[36221]="我一定会转告泰勒上尉，你正在这里解决暮光之锤。"
D.Strings[36222]="$n正在拼搏！我得赶快回到上尉那儿去。"
D.Strings[36223]="他们正在把自己变成某种叫做升腾者的超能元素。你得去阻止他们，$n！"
D.Strings[36224]="我以为我死定了。谢谢你，$n！"
D.Strings[36225]="我们在另一边见，$g兄弟:姐妹;。出口在哪边？"
D.Strings[36226]="这个怎么样，玛克布莱德？这位$c一定能帮到我们的！"
D.Strings[36227]="太棒了。$n，你一定会成为优秀的$c。玛克布莱德会教你学会你所要了解的一切，帮你成为守卫暴风城的精兵强将！"
D.Strings[36228]="我已经被关在这儿好多天了。他们正准备拿我献祭！"
D.Strings[36229]="再见了，$n。下次再见……"
D.Strings[36230]="这座岛屿属于部落！攻击！"
D.Strings[36231]="碾死这群守望堡蛆虫！"
D.Strings[36232]="感受欧卡里隆的愤怒吧！诅咒之地是我们的！"
D.Strings[36233]="地狱咆哮的双眼在注视着你们！"
D.Strings[36234]="调整高度和速度，断轮先生。"
D.Strings[36235]="向舰队发出编队信号。"
D.Strings[36236]="快来人把我从这笼子里弄出去！"
D.Strings[36237]="我长得太帅了，怎么能被当成祭品！"
D.Strings[36238]="等我出去，我一定会把你们这群暮光之锤杂种撕成碎片！"
D.Strings[36239]="也许我们能做个交易。我会是个优秀的教徒！"
D.Strings[36240]="你过来。你不是教徒。快把我放出去！"
D.Strings[36241]="我不要这么无助的死去！"
D.Strings[36242]="向你致敬，$n。"
D.Strings[36243]="我一定会转告军团士兵纳兹戈林，你正在这里解决暮光之锤。"
D.Strings[36244]="我得回去找纳兹戈林了。"
D.Strings[36245]="我们外面见，$g兄弟:姐妹;。出口是在那边吗？"
D.Strings[36246]="穿过传送门往里望去，你看到一个地下洞穴的内部。水流拍击与大地移位的声音混杂在一起。这个传送门一定是因某种原因打开的，但究竟是为什么呢？"
D.Strings[36247]="当你靠近传送门时，你感到了自门内侵散而出的热浪。锤子敲击声自峡谷回响而来，在四周环绕着微弱而坚实的节奏。这传送门究竟是通往哪里的？"
D.Strings[36248]="你怎么说，$n？我们必须集结一切力量来击败死亡之翼和他的爪牙！"
D.Strings[36249]="是。阁下！我们会帮$n为即将打响的战斗做好准备！"
D.Strings[36250]="命令舰队组成密集队形。所有人，高度戒备！"
D.Strings[36251]="我们的盟军到了！全力进攻，族人们，把他们赶回去。"
D.Strings[36252]="长官！舰队正向前进发。"
D.Strings[36253]="接近萨多尔大桥，长官。"
D.Strings[36254]="我们胜利了！以艾萨拉之名！"
D.Strings[36255]="我的女武士，你再一次赢得了我和我们全部族人的尊重。"
D.Strings[36256]="女武士这个头衔已经无法彰显你的功勋了。接受这新的冠冕吧——纳尓吉拉，艾萨拉的勇士。"
D.Strings[36257]="召唤已经完成，艾萨拉的军队正在集结，猎潮者耐普图隆很快就会被击溃。"
D.Strings[36258]="啊，就算没有这些新麻烦不断的冒出来，维持这儿的秩序就已经够让人头痛的了！希望你有好消息，$n……"
D.Strings[36259]="我希望能骑上暴风城军马，长官。"
D.Strings[36260]="我们经受了一次不小的挫折，但我们无论如何都要完成任务。"
D.Strings[36261]="打起精神来，$n。$b$b我们必须赶往决口处，不能让纳迦进入水元素位面！"
D.Strings[36262]="啊，它已经完全被破坏了！我们得换别处试试。"
D.Strings[36263]="奥格瑞玛之心，你的高度太低了。太低了！"
D.Strings[36264]="拉升！下降！随便做点儿什么！"
D.Strings[36265]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s高仰起身子，开始施放|cFFFF0000|Hspell:77982|h[灼热烈焰]|h|r！"
D.Strings[36266]="站起来，朋友们。没时间处理伤口！"
D.Strings[36267]="尽管我们损失了这辆战车，但必须坚持下去。我们必须成功！"
D.Strings[36268]="以为他们能把这一切都弄好？我们去另一侧。"
D.Strings[36269]="我克服重重障碍才走到这里……"
D.Strings[36270]="我们必须到裂口那里去！"
D.Strings[36271]="潜艇要爆炸了！撤离！"
D.Strings[36272]="哪儿疼？"
D.Strings[36273]="该死的海巫击垮了我们的舰船！抓紧了！！！"
D.Strings[36274]="%s将他的法术核心掷到地面上！"
D.Strings[36275]="你们愚蠢地侵入了我们的水域，部落的傻瓜们。接受我风暴的鞭笞吧！"
D.Strings[36276]="哦，地精圣灵啊！"
D.Strings[36277]="这座山谷能掩护我们。低空飞行，跟紧。"
D.Strings[36278]="别再有人犯错误！"
D.Strings[36279]="追随部落的勇士们。听我说！"
D.Strings[36280]="敌人近在眼前。混沌的信徒正图谋重铸这个世界。"
D.Strings[36281]="新的世界即将到来，朋友们，但并不是他们设计的世界。"
D.Strings[36282]="我们将齐心协力，粉碎暮光之锤，摧毁他们的堡垒，"
D.Strings[36283]="让他们的土地寸草不生。我们的力量将让他们颤抖。"
D.Strings[36284]="我们将成为这个世界真正的主人。"
D.Strings[36285]="我们拥有共同的信念，强大的力量，无畏的勇气。"
D.Strings[36286]="今天，我们将重铸世界。我们的世界。为了部落！"
D.Strings[36287]="即将到达暮光高地，船长。"
D.Strings[36288]="看——那些矮人。哈！他们生气的样子就好像缩在洞里的土拨鼠。"
D.Strings[36289]="船长！船首左舷发现联盟海军舰队。"
D.Strings[36290]="联盟军队阵型密集，而且没有护卫。"
D.Strings[36291]="空军部队进攻！！趁他们动弹不得的时候，狠狠地打！"
D.Strings[36292]="什么……什么？！他以为他在干什么？运输船没有保护啦。"
D.Strings[36293]="是哪个疯子下令撤去对他的空中支援？"
D.Strings[36294]="断轮先生，向舰队发信号。防御队形！"
D.Strings[36295]="我们已经没有护卫了，准备交叉火力射击。赶快，赶快！"
D.Strings[36296]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t盲眼巨龙跳向后方，开始施放|cFFFF0000灼热烈焰！|r"
D.Strings[36297]="胜利者。"
D.Strings[36298]="我准备开始鲜血仪式了，卡西姆。"
D.Strings[36299]="鲜血仪式已经完成……现在我能看到有三个护符在等着你。"
D.Strings[36300]="我准备开始护符仪式了，卡西姆。"
D.Strings[36301]="转头，咳嗽两次。"
D.Strings[36302]="见过我所见过的那些，做过我所做过的那些，而现在还能呼吸……我真是个幸运的侏儒。"
D.Strings[36303]="怎么？怎么啦？！"
D.Strings[36304]="那些炮！别让它们闲着！有什么打什么！"
D.Strings[36305]="被攻击了！"
D.Strings[36306]="真是场惨祸啊，中尉。他们都被谋杀了。"
D.Strings[36307]="根据体温判断，我敢说他们的死亡时间不超过6小时。"
D.Strings[36308]="他们居然对老马布兰契做出这种事……"
D.Strings[36309]="不是开玩笑，菜鸟……"
D.Strings[36310]="看来他们真把推车放在了……"
D.Strings[36311]="……马前面。"
D.Strings[36312]="诺莫瑞根行动取得了成功。当然，那个卑鄙的瑟玛普拉格使出了让人出乎意料的一招，但我们还是把他赶跑了！诺莫瑞根很快就会被肃清，重新回到我们的手中，这只是时间问题！"
D.Strings[36313]="收获中"
D.Strings[36314]="为国王料理膳食是份荣耀，可不是工作。你有时间帮我跑跑腿儿吗？"
D.Strings[36315]="训练一刻都不能停，$n。我要每个侏儒都做好准备，等到我们将叛徒瑟玛普拉格彻底干掉的那天，都能大展拳脚！"
D.Strings[36316]="诺莫瑞根行动的结束对大多数人来说意味着终于有了喘息的机会。然而我的助手和我却一直忙于救治那些救援人员从城里救出的伤病员和幸存者。"
D.Strings[36317]="守望堡有时真是闷得够呛。有时一个矮人需要的只是一杯啤酒，让她的脑袋换换气儿！"
D.Strings[36318]="我只是稍事休息。永恒地坚守并不像听上去那么容易，$r。"
D.Strings[36319]="回到拉葛雷克那里去！"
D.Strings[36320]="埃鲁纳克，来看看这个。还记得我跟你说过的视象法术吗？这看起来像是个有力的证据。"
D.Strings[36321]="埃鲁纳克检视着碎片，认同地点了点头。"
D.Strings[36322]="那我这就准备施法。这也许总算能让我们对纳迦的手段和意图有所了解。"
D.Strings[36323]="贸易区守住了！现在，守住城市的其它部分！"
D.Strings[36324]="我们守住了法师区！所有入侵者都已被击退，撤离也已顺利完成！"
D.Strings[36325]="你好啊，$n。我可以对你进行法师方面的训练。"
